type BubbleButtonAction =
  | "send_steps"
  | "send_payment_method"
  | "show_payment"
  | "choose_combo"
  | "choose_basico"
  | "choose_upsell"
  | "decline_upsell"
  | "show_order_bump"
  | "accept_gift"
  | "decline_gift"
