/** Colores de los cuadritos de decisión. */
const COLORES_DE_DECISION = [
  { valor: "esmeralda", clase: "border-emerald-400 bg-emerald-500 text-white" },
  { valor: "rojo", clase: "border-red-400 bg-red-500 text-white" },
  { valor: "azul", clase: "border-sky-400 bg-sky-500 text-white" },
  { valor: "violeta", clase: "border-violet-400 bg-violet-500 text-white" },
  { valor: "ambar", clase: "border-amber-400 bg-amber-500 text-white" },
  { valor: "gris", clase: "border-neutral-400 bg-neutral-500 text-white" },
  // EL BLANCO ES EL ORIGINAL, Y NO SE PODÍA VOLVER A ÉL.
  //
  // Es el aspecto de todo lo que nadie ha pintado. Estaba solo como estado por
  // defecto —cuando el color viene vacío— pero no como opción, así que pintar
  // algo era un viaje de ida: no había forma de dejarlo como estaba.
  { valor: "blanco", clase: "border-neutral-300 bg-tarjeta text-neutral-700" },
] as const;
const CLASE_DE_COLOR = (color?: string) =>
  COLORES_DE_DECISION.find((c) => c.valor === color)?.clase ??
  "border-neutral-300 bg-tarjeta text-neutral-700";

/**
 * LOS COLORES DE LOS BOTONES DE «PRECIOS Y PAGOS».
 *
 * Los mismos SEIS de los cuadritos de decisión, para no aprenderse dos paletas.
 * Aquí hacen falta tres tonos del mismo color en vez de uno: la CARA del botón
 * (clarito, que va a estar todo el rato en pantalla), el TÍTULO (oscuro, para
 * que se lea encima) y la CINTA de la ventana que abre (fuerte, para que se vea
 * de un vistazo qué botón se abrió).
 */
const COLORES_DE_BOTON = {
  esmeralda: {
    cara: "border-emerald-300 bg-emerald-50 hover:bg-emerald-100",
    titulo: "text-emerald-900",
    cinta: "bg-emerald-600",
    punto: "bg-emerald-500",
  },
  rojo: {
    cara: "border-red-300 bg-red-50 hover:bg-red-100",
    titulo: "text-red-900",
    cinta: "bg-red-600",
    punto: "bg-red-500",
  },
  azul: {
    cara: "border-sky-300 bg-sky-50 hover:bg-sky-100",
    titulo: "text-sky-900",
    cinta: "bg-sky-600",
    punto: "bg-sky-500",
  },
  violeta: {
    cara: "border-violet-300 bg-violet-50 hover:bg-violet-100",
    titulo: "text-violet-900",
    cinta: "bg-violet-600",
    punto: "bg-violet-500",
  },
  ambar: {
    cara: "border-amber-300 bg-amber-50 hover:bg-amber-100",
    titulo: "text-amber-900",
    cinta: "bg-amber-500",
    punto: "bg-amber-500",
  },
  gris: {
    cara: "border-neutral-300 bg-neutral-50 hover:bg-neutral-100",
    titulo: "text-neutral-800",
    cinta: "bg-neutral-500",
    punto: "bg-neutral-500",
  },
  // El original, para poder deshacer un color. Ver COLORES_DE_DECISION.
  blanco: {
    cara: "border-neutral-300 bg-tarjeta hover:bg-neutral-50",
    titulo: "text-neutral-900",
    cinta: "bg-neutral-300",
    punto: "bg-neutral-400",
  },
} as const;
type ColorDeBoton = keyof typeof COLORES_DE_BOTON;
const esColorDeBoton = (valor?: string): valor is ColorDeBoton =>
  !!valor && valor in COLORES_DE_BOTON;
/** El color elegido, o el de fábrica si no hay ninguno guardado todavía. */
const tonoDelBoton = (color: string | undefined, porDefecto: ColorDeBoton) =>
  COLORES_DE_BOTON[esColorDeBoton(color) ? color : porDefecto];

/** Lo que puede hacer un cuadrito además de mandar sus burbujas. */
type DecisionAction =
  | "choose_combo"
  | "choose_basico"
  /** El segundo producto, el de después de la venta. */
  | "choose_upsell"
  /** El «No» al segundo producto: sigue con el regalo. */
  | "decline_upsell"
  | "send_payment_method"
  | "show_payment"
  /** La intro de la oferta de 2 opciones, para armar el recorrido a mano. */
  | "show_order_bump"
  /** El regalo: aceptarlo, rechazarlo, entregarlo. */
  | "accept_gift"
  | "decline_gift"
  | "claim_gift"
  | "human"
  /** Arranca un workflow del tablero (23/10/2026). */
  | "start_workflow";

/**
 * Los tres productos que puede elegir un cuadrito, con los MISMOS nombres que
 * los cajones de entrega. Que se llamen igual en los dos sitios es a propósito:
 * cuando no coincidían, llenar el cajón equivocado costaba entregar el producto
 * que no era.
 */
const PRODUCTOS_DE_DECISION: { valor: DecisionAction; texto: string }[] = [
  { valor: "choose_basico", texto: "BÁSICO" },
  { valor: "choose_combo", texto: "FULL" },
  { valor: "choose_upsell", texto: "UPSELL (el segundo producto)" },
];

const esElegirProducto = (accion: DecisionAction | "" | undefined): boolean =>
  accion === "choose_basico" ||
  accion === "choose_combo" ||
  accion === "choose_upsell";

/**
 * Las familias del menú de links. "Elegir producto" agrupa a los tres de
 * arriba: es UNA línea en el menú con un selector al lado, en vez de un link
 * suelto por producto. Lo que se guarda sigue siendo choose_basico,
 * choose_combo o choose_upsell — esto es solo cómo se ve.
 */
const LINKS_DE_DECISION: { valor: string; texto: string }[] = [
  { valor: "choose_product", texto: "Elegir producto" },
  { valor: "send_payment_method", texto: "Mandar los datos de un método de pago" },
  { valor: "show_payment", texto: "Mostrar los métodos de pago" },
  // ARMAR EL RECORRIDO A MANO, SIN DEPENDER DE LO AUTOMÁTICO.
  //
  // Estas cuatro ya existían como acciones de las reglas del Cerebro, hechas y
  // probadas. Aquí solo se abren a los cuadritos: la burbuja final de una intro
  // pregunta, y su cuadrito lleva a la oferta de dos opciones o contesta al
  // regalo. Sin esto, la única forma de responder al regalo era que el detector
  // de "sí/no" acertara — y ese detector no puede saber qué palabras usa cada
  // negocio.
  { valor: "show_order_bump", texto: "Mostrar la oferta de 2 opciones" },
  { valor: "accept_gift", texto: "Aceptar el regalo" },
  { valor: "decline_gift", texto: "Rechazar el regalo" },
  { valor: "claim_gift", texto: "Entregar el regalo (ya comentó)" },
  { valor: "human", texto: "Pasar a una persona" },
  // ▶ ACTIVAR UN WORKFLOW DEL TABLERO (23/10/2026): el cliente sale de la venta automática.
  { valor: "start_workflow", texto: "▶ Activar un workflow" },
];

