function textStep(body: string): EditorStep {
  return {
    type: "text",
    drive_url: "",
    texts: [body],
    delay_after_sec: 0,
    enabled: true,
  };
}

function replaceEditorStepPreviewTokens(
  steps: EditorStep[],
  replacements: Record<string, string>
): EditorStep[] {
  return steps.map((step) => ({
    ...step,
    texts: step.texts.map((text) =>
      Object.entries(replacements).reduce(
        (current, [token, replacement]) =>
          current.replace(
            new RegExp(`\\{\\{\\s*(?:${token})\\s*\\}\\}`, "gi"), literal(replacement)),
        text
      )
    ),
  }));
}

function createCountryPaymentResponses(
  country: CountryCode,
  buttons: PaymentButtonEditor[]
): Record<string, EditorStep[]> {
  const countryName =
    COUNTRY_OPTIONS.find((item) => item.code === country)?.label ?? country;
  return Object.fromEntries(
    buttons.map((button) => [
      button.method,
      [
        textStep(
          `[Referencia ${countryName}] Escribe aqui los datos reales para ${button.label}. Incluye titular, banco/cuenta/enlace y el monto {{precio}}.`
        ),
      ],
    ])
  );
}

function createReferenceCountryPaymentProfile(
  country: CountryCode,
  cfg: FullConfig
): CountryPaymentProfileEditor {
  const reference = COUNTRY_PAYMENT_REFERENCES[country];
  // Perú vive en el motor GLOBAL: su referencia = datos reales (texto, botones,
  // pasos, precio, receptor). Así, al sembrar una CAPA de modalidad para Perú,
  // arranca con lo que hoy usa el bot y no se pierde nada.
  if (country === "PE") {
    return {
      enabled: true,
      course_price_soles: cfg.globals.course_price_soles,
      payment_validation: {
        yape_recipient_name_starts_with:
          cfg.payment_validation.yape_recipient_name_starts_with,
      },
      payment_text: cfg.payment_text,
      payment_buttons: cfg.payment_buttons,
      payment_responses: {
        yape: cfg.payment_methods.yape,
        bcp_transferencia: cfg.payment_methods.bcp_transferencia,
        efectivo: cfg.payment_methods.efectivo,
      },
    };
  }
  return {
    enabled: false,
    course_price_soles: 0,
    payment_validation: {
      yape_recipient_name_starts_with: "",
    },
    payment_text: reference.payment_text,
    payment_buttons: reference.payment_buttons,
    payment_responses: createCountryPaymentResponses(
      country,
      reference.payment_buttons
    ),
  };
}

function mergeCountryPaymentProfileForEditor(
  country: CountryCode,
  cfg: FullConfig,
  saved?: CountryPaymentProfileEditor
): CountryPaymentProfileEditor {
  const reference = createReferenceCountryPaymentProfile(country, cfg);
  // "Vender en este país" es una decisión GLOBAL del país: el mismo interruptor
  // la escribe desde cualquier modalidad y el motor la respeta en todas. Así que
  // la casilla tiene que mostrar ESA bandera y no el "enabled" de la capa: en una
  // modalidad sin capa propia, la capa cae a la raíz y la casilla acabaría
  // diciendo lo contrario de lo que hace el bot.
  const ventaDelPais = cfg.country_sales_enabled?.[country];
  const conBandera = (
    perfil: CountryPaymentProfileEditor
  ): CountryPaymentProfileEditor =>
    typeof ventaDelPais === "boolean" ? { ...perfil, enabled: ventaDelPais } : perfil;
  if (!saved) return conBandera(reference);
  const buttons =
    saved.payment_buttons && saved.payment_buttons.length > 0
      ? saved.payment_buttons
      : reference.payment_buttons;
  const combinado: CountryPaymentProfileEditor = {
    ...reference,
    ...saved,
    payment_validation: {
      ...reference.payment_validation,
      ...(saved.payment_validation ?? {}),
    },
    payment_text: saved.payment_text?.trim()
      ? saved.payment_text
      : reference.payment_text,
    payment_buttons: buttons,
    payment_responses: {
      // Perú trae sus pasos REALES desde la referencia (motor global) y NO genera
      // placeholders (evita claves plin/bcp basura que se filtrarían al cliente).
      // Otros países sí siembran placeholders editables por cada botón.
      ...(country === "PE"
        ? {}
        : createCountryPaymentResponses(country, buttons)),
      ...reference.payment_responses,
      ...(saved.payment_responses ?? {}),
    },
  };
  return conBandera(combinado);
}

