  /** Burbujas que cierran la explicación luego de las muestras. */
  samples_after_sequence?: EditorStep[];
  /** SEGUNDO producto (Doble Oferta): contenido, nombre ({{PRODUCTO2}}) y galería. */
  course_content_2?: string;
  product_name_2?: string;
  image_gallery_2?: {
    topic: string;
    keywords?: string[];
    when: string;
    media_type: GalleryMediaType;
    drive_url: string;
    caption: string;
    caption_variants?: string[];
    enabled?: boolean;
  }[];
