const TYPE_LABEL: Record<StepType, string> = {
  text: "📝 Texto",
  image: "🖼️ Imagen",
  audio: "🎵 Audio",
  video: "🎥 Video",
  document: "📄 PDF",
};

type LinkMediaKind = Exclude<StepType, "text"> | "unknown";
/**
 * Lo que se sabe del enlace tras preguntarle a Drive.
 *
 * «restringido» va aquí y NO en `LinkMediaKind` a propósito: no es una clase de
 * archivo —no compite con imagen, video o PDF—, es el resultado de haber
 * preguntado. Metiéndolo con los otros habría que darle una etiqueta y una
 * extensión que no tiene.
 */
type LinkMediaResolution = LinkMediaKind | "loading" | "restringido";

const LINK_MEDIA_LABEL: Record<Exclude<LinkMediaKind, "unknown">, string> = {
  image: "Imagen",
  audio: "Audio",
  video: "Video",
  document: "PDF",
};

const MEDIA_EXTENSION_PATTERNS: Array<{
  kind: Exclude<LinkMediaKind, "unknown">;
  pattern: RegExp;
}> = [
  { kind: "image", pattern: /\.(jpe?g|png|webp|gif|bmp|svg|heic|heif)$/i },
  { kind: "video", pattern: /\.(mp4|mov|m4v|webm|avi|mkv|mpeg|mpg)$/i },
  { kind: "audio", pattern: /\.(mp3|m4a|aac|ogg|wav|opus|flac)$/i },
  { kind: "document", pattern: /\.(pdf)$/i },
];

function normalizedUrlPath(rawUrl: string): string {
  const trimmed = rawUrl.trim();
  if (!trimmed || trimmed.includes("<<") || trimmed.includes("{{")) return "";
  try {
    return decodeURIComponent(new URL(trimmed).pathname).toLowerCase();
  } catch {
    return decodeURIComponent(trimmed.split(/[?#]/)[0] ?? "").toLowerCase();
  }
}

function isGoogleDriveFileUrl(rawUrl: string): boolean {
  const trimmed = rawUrl.trim().toLowerCase();
  return (
    trimmed.includes("drive.google.com/file/d/") ||
    trimmed.includes("drive.google.com/open?") ||
    trimmed.includes("drive.google.com/uc?") ||
    trimmed.includes("drive.google.com/thumbnail?")
  );
}

function inferLinkMediaKind(rawUrl: string): LinkMediaKind {
  const path = normalizedUrlPath(rawUrl);
  if (!path) return "unknown";
  const found = MEDIA_EXTENSION_PATTERNS.find(({ pattern }) =>
    pattern.test(path)
  );
  return found?.kind ?? "unknown";
}

function shouldResolveLinkMediaKind(rawUrl: string): boolean {
  return (
    isGoogleDriveFileUrl(rawUrl) && inferLinkMediaKind(rawUrl) === "unknown"
  );
}

function resolvedMediaPreviewIssue(
  step: EditorStep,
  resolvedKind?: LinkMediaResolution
):
  | {
      title: string;
      detail: string;
      tone: "danger" | "warn";
    }
  | null {
  if (step.type === "text" || !step.drive_url.trim()) return null;
  /**
   * EL ARCHIVO ESTÁ RESTRINGIDO EN DRIVE.
   *
   * Va lo PRIMERO de todo, antes de mirar de qué tipo es: si Drive no deja
   * abrirlo, saber si era imagen o video no le sirve de nada a nadie. Y como
   * este aviso devuelve algo, la miniatura no se dibuja —ver dónde se calcula
   * `thumb`—, así que en el sitio de la foto sale este mensaje. Que es
   * exactamente lo que pidió el dueño: «que en vez de imagen diga que el
   * archivo está restringido, que vaya a Drive y lo comparta».
   *
   * Solo llega aquí con las señales inequívocas — ver el comentario del
   * endpoint `media-kind`. Un «no pude comprobarlo» no entra por aquí.
   */
  if (resolvedKind === "restringido") {
    return {
      title: "El archivo está restringido en Drive",
      detail:
        "El bot no puede abrirlo, así que al cliente no le llegaría. Entra a Drive, abre este archivo, y en Compartir ponlo como «Cualquier persona con el enlace».",
      tone: "danger",
    };
  }
  const detected = inferLinkMediaKind(step.drive_url);
  const actual =
    detected !== "unknown" || !resolvedKind || resolvedKind === "loading"
      ? detected
      : resolvedKind;
  if (actual !== "unknown" && actual !== step.type) {
    return {
      title: "Seleccion no compatible",
      detail: `Selector: ${LINK_MEDIA_LABEL[step.type]}. Enlace: ${LINK_MEDIA_LABEL[actual]}.`,
      tone: "danger",
    };
  }
  if (
    step.type === "image" &&
    actual === "unknown" &&
    isGoogleDriveFileUrl(step.drive_url)
  ) {
    return {
      title: resolvedKind === "loading" ? "Verificando tipo" : "Tipo no confirmado",
      detail:
        resolvedKind === "loading"
          ? "Estoy confirmando si el archivo de Drive coincide con Imagen."
          : "Drive no permitio confirmar si este enlace es imagen o video.",
      tone: "warn",
    };
  }
  return null;
}

type PostSaleEditorValues = {
  whatsappPreference: string;
  deliveryUsage: string;
  lifetimeAccess: string;
  farewells: string[];
};

const POST_SALE_FALLBACKS: PostSaleEditorValues = {
  whatsappPreference:
    "No te preocupes. Tu enlace ya esta en el mensaje de *PAGO APROBADO* de arriba: solo tocalo desde ahi para descargar el material. Guardalo o enviatelo a tu correo cuando puedas, para tenerlo siempre seguro.",
  deliveryUsage:
    "Todo esta en las carpetas de Drive que te envie: abres el enlace, descargas tu material y lo imprimes las veces que quieras.",
  lifetimeAccess:
    "Si, el acceso es de por vida y el material queda siempre disponible para ti.",
  farewells: [
    "Que disfrutes mucho tu material.",
    "Que lo disfrutes mucho aprendiendo y practicando.",
    "Muchos exitos con el material.",
  ],
};

function extractPostSaleValues(source: string): PostSaleEditorValues {
  const whatsappPreference =
    source.match(/Example response[\s\S]*?\n\s*"([\s\S]*?)"/)?.[1] ??
    POST_SALE_FALLBACKS.whatsappPreference;
  const deliveryUsage =
    source.match(/Phrases like:\s*\n\s*"([\s\S]*?)"/)?.[1] ??
    POST_SALE_FALLBACKS.deliveryUsage;
  const lifetimeAccess =
    source.match(/Phrases like:[\s\S]*?"[\s\S]*?"\s*\n\s*\n\s*"([\s\S]*?)"/)?.[1] ??
    POST_SALE_FALLBACKS.lifetimeAccess;
  const farewellMatch = source.match(
    /Instead, close with a warm farewell[\s\S]*?-\s*"([\s\S]*?)"\s*\n\s*-\s*"([\s\S]*?)"\s*\n\s*-\s*"([\s\S]*?)"/
  );
  const farewells = farewellMatch
    ? [farewellMatch[1], farewellMatch[2], farewellMatch[3]]
    : POST_SALE_FALLBACKS.farewells;
  return { whatsappPreference, deliveryUsage, lifetimeAccess, farewells };
}

function sanitizePostSaleInstruction(source: string): string {
  return source.replace(
    /in the PAGO APROBADO message \(the .*?\)\. Speak as if you know the content, WITHOUT inventing specific steps\./,
    "in the PAGO APROBADO message (the material you already received). Speak as if you know the content, WITHOUT inventing specific steps."
  );
}

function updatePostSaleSingle(
  source: string,
  current: string,
  next: string,
  pattern: RegExp
): string {
  // literal(): el texto nuevo es del usuario y puede traer un "$". Aquí no hay
  // grupos, pero "$&" seguiría metiendo el trozo encontrado.
  if (current && source.includes(current))
    return source.replace(current, literal(next));
  // Aquí sí se quieren conservar los trozos de alrededor, pero se toman como
  // ARGUMENTOS de una función en vez de escribir "$1" dentro del texto: así el
  // "$" que traiga `next` no se lee como otra referencia.
  if (pattern.test(source))
    return source.replace(pattern, (_todo, antes: string, despues: string) =>
      `${antes}${next}${despues}`
    );
  return source;
}

function updatePostSaleFarewells(
  source: string,
  farewellsText: string
): string {
  const lines = farewellsText
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);
  const next = [
    lines[0] ?? POST_SALE_FALLBACKS.farewells[0],
    lines[1] ?? POST_SALE_FALLBACKS.farewells[1],
    lines[2] ?? POST_SALE_FALLBACKS.farewells[2],
  ];
  return source.replace(
    /(Instead, close with a warm farewell that does NOT invite continuation:\s*\n\s*-\s*")[\s\S]*?("\s*\n\s*-\s*")[\s\S]*?("\s*\n\s*-\s*")[\s\S]*?(")/,
    // Con función, no con "$1": las despedidas las escribe el usuario y un "$"
    // suyo se leería como referencia a un grupo.
    (_todo, a: string, b: string, c: string, d: string) =>
      `${a}${next[0]}${b}${next[1]}${c}${next[2]}${d}`
  );
}

function adaptTextForChannel(text: string, channel: ChannelKey): string {
  if (channel === "whatsapp") return text;
  const chatName =
    channel === "messenger"
      ? "Messenger"
      : channel === "instagram"
        ? "Instagram"
        : "este chat";
  return text
    .replace(/\bpor whatsapp\b/gi, literal("por aqui"))
    .replace(/\bpor WhatsApp\b/g, literal("por aqui"))
    .replace(/\bWhatsApp\b/gi, literal(chatName))
    .replace(/\bmensaje de \*PAGO APROBADO\* de arriba\b/gi, literal("mensaje de *PAGO APROBADO* de arriba"))
    .replace(/\bte envi(?:e|\u00e9)\b/gi, literal("te envie por aqui"));
}

function adaptPostSaleForChannel(
  postSale: PostSaleEditorValues,
  channel: ChannelKey
): ChannelPostSaleEditor {
  return {
    whatsappPreference: adaptTextForChannel(postSale.whatsappPreference, channel),
    deliveryUsage: adaptTextForChannel(postSale.deliveryUsage, channel),
    lifetimeAccess: adaptTextForChannel(postSale.lifetimeAccess, channel),
    farewells: postSale.farewells
      .map((line) => adaptTextForChannel(line, channel))
      .join("\n"),
  };
}

function emptyStep(type: StepType = "text"): EditorStep {
  return { type, drive_url: "", texts: [""], delay_after_sec: 6 };
}

/**
 * El recordatorio de correo que el bot mandaba de fábrica.
 *
 * Vivía SOLO en el código del motor: no había ninguna pantalla donde leerlo ni
 * cambiarlo, así que el bot mandaba un mensaje que no aparecía en ningún sitio
 * del editor. Aquí está para que se pueda ver y reescribir.
 *
 * Tiene que decir lo MISMO que el respaldo del motor (getConfiguredEmailReminder
 * en engine.ts): si divergen, la pantalla enseñaría un texto y saldría otro.
 */
const TEXTO_DE_FABRICA_DEL_RECORDATORIO =
  "*Recuerda que los mensajes de whatsapp suelen desaparecer con el tiempo.*\n\n*Envíame tu correo electrónico* 📧 para que lo tengas siempre a la mano y *no pierdas acceso* 😊.";

function stepFromText(text: string, delayAfterSec = 1): EditorStep {
  return {
    type: "text",
    drive_url: "",
    texts: [text],
    delay_after_sec: delayAfterSec,
    enabled: true,
  };
}

function hasEditorStepContent(steps: EditorStep[] | undefined): boolean {
  return (steps ?? []).some(
    (step) =>
      step.enabled !== false &&
      (!!step.drive_url.trim() || step.texts.some((text) => text.trim()))
  );
}

function textFromSteps(steps: EditorStep[] | undefined): string {
  return (steps ?? [])
    .filter((step) => step.enabled !== false)
    .flatMap((step) => step.texts ?? [])
    .map((text) => text.trim())
    .filter(Boolean)
    .join("\n\n");
}

