function ButtonsPreview({
  prompt,
  buttons,
  /** Qué enseñar mientras no haya ninguna etiqueta escrita.
   *
   *  Nació para el menú de pago, así que el ejemplo de fábrica son métodos de
   *  pago. En la pregunta del upsell eso no pinta nada: quien la abriera vacía
   *  vería «Yape / Plin / BCP» colgando de «¿deseas llevarlo?». Cada sitio trae
   *  el suyo; el de fábrica se queda para quien no diga nada. */
  ejemplo,
}: {
  prompt: string;
  buttons: { label: string; method: string }[];
  ejemplo?: { label: string; method: string }[];
}) {
  const filled = buttons.filter((b) => b.label.trim());
  const shown =
    filled.length > 0
      ? filled
      : (ejemplo ?? [
          { label: "Yape", method: "yape" },
          { label: "Plin", method: "plin" },
          { label: "BCP", method: "bcp" },
        ]);
  return (
    <div className="rounded-lg bg-[#e5ddd5] p-3">
      <div className="max-w-[85%] overflow-hidden rounded-lg bg-tarjeta shadow-sm">
        <div className="whitespace-pre-wrap px-3 py-2 text-sm text-neutral-800">
          {prompt.trim() || "Puedes elegir tu método de pago 👇"}
        </div>
        {shown.slice(0, 3).map((b, i) => (
          <div
            key={i}
            className="flex items-center justify-center gap-1 border-t border-neutral-200 px-3 py-2 text-sm font-medium text-[#1ba7e0]"
          >
            <span className="text-base leading-none">↩</span>
            {b.label.trim() || "(sin etiqueta)"}
          </div>
        ))}
      </div>
      {filled.length === 0 && (
        <p className="mt-1 text-[11px] text-neutral-500">
          (Ejemplo por defecto. Agrega tus botones arriba para verlos aquí.)
        </p>
      )}
    </div>
  );
}

