// ── Tarjeta colapsable (mostrar/ocultar para organizar el editor) ───────────
/**
 * ¿El cursor está dentro de algo donde se escribe?
 *
 * Sirve para no robarle al navegador el deshacer del texto. Se mira el
 * elemento del evento y, si no lo hay, el que tenga el foco.
 */
function escribiendoEnUnCampo(objetivo: EventTarget | null): boolean {
  const el =
    objetivo instanceof HTMLElement
      ? objetivo
      : document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null;
  if (!el) return false;
  if (el.isContentEditable) return true;
  if (el.tagName === "TEXTAREA") return true;
  if (el.tagName === "INPUT") {
    // Una casilla o un botón no tienen texto que deshacer.
    const tipo = (el as HTMLInputElement).type;
    return !["checkbox", "radio", "range", "button", "submit", "file", "color"].includes(
      tipo
    );
  }
  return false;
}

/**
 * El menú del click derecho sobre un cajón, y su estado.
 *
 * Vive aparte porque lo usan dos sitios con forma distinta: los cajones
 * desplegables (Collapsible) y la cabecera de cada seguimiento, que no es un
 * desplegable sino un recuadro. Escrito una vez, no pueden comportarse
 * distinto.
 */
function useMenuDeCajon() {
  const [menu, setMenu] = useState<{ x: number; y: number } | null>(null);
  useEffect(() => {
    if (!menu) return;
    const cerrar = () => setMenu(null);
    const conEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") setMenu(null);
    };
    window.addEventListener("mousedown", cerrar);
    window.addEventListener("keydown", conEscape);
    window.addEventListener("scroll", cerrar, true);
    return () => {
      window.removeEventListener("mousedown", cerrar);
      window.removeEventListener("keydown", conEscape);
      window.removeEventListener("scroll", cerrar, true);
    };
  }, [menu]);
  return {
    menu,
    abrir: (event: React.MouseEvent) => {
      event.preventDefault();
      setMenu({ x: event.clientX, y: event.clientY });
    },
    cerrar: () => setMenu(null),
  };
}

function MenuDeCajon({
  estado,
  onCopiarCajon,
  onPegarCajonEncima,
  onPegarCajonDebajo,
  etiquetaCajonCopiado,
}: {
  estado: ReturnType<typeof useMenuDeCajon>;
  onCopiarCajon?: () => void;
  onPegarCajonEncima?: () => void;
  /** «Pegar debajo»: lo pidió el 10/10/2026 para los cajones de intro del upsell. Sin él,
   *  el menú es el de siempre. */
  onPegarCajonDebajo?: () => void;
  etiquetaCajonCopiado?: string;
}) {
  if (!estado.menu) return null;
  return (
    <div
      className="fixed z-[70] w-64 overflow-hidden rounded-md border border-neutral-300 bg-tarjeta py-1 text-sm shadow-xl"
      style={{ left: estado.menu.x, top: estado.menu.y }}
      onMouseDown={(event) => event.stopPropagation()}
    >
      {onCopiarCajon && (
        <button
          type="button"
          onClick={() => {
            onCopiarCajon();
            estado.cerrar();
          }}
          className="block w-full px-3 py-2 text-left text-neutral-800 hover:bg-neutral-100"
        >
          📋 Copiar este cajón
        </button>
      )}
      {onPegarCajonEncima ? (
        <button
          type="button"
          onClick={() => {
            onPegarCajonEncima();
            estado.cerrar();
          }}
          className="block w-full px-3 py-2 text-left text-neutral-800 hover:bg-neutral-100"
        >
          📥 Pegar encima
          {etiquetaCajonCopiado ? (
            <span className="block text-[11px] text-neutral-500">
              {etiquetaCajonCopiado}
            </span>
          ) : null}
        </button>
      ) : null}
      {onPegarCajonDebajo ? (
        <button
          type="button"
          onClick={() => {
            onPegarCajonDebajo();
            estado.cerrar();
          }}
          className="block w-full px-3 py-2 text-left text-neutral-800 hover:bg-neutral-100"
        >
          📥 Pegar debajo
          {etiquetaCajonCopiado ? (
            <span className="block text-[11px] text-neutral-500">
              {etiquetaCajonCopiado}
            </span>
          ) : null}
        </button>
      ) : null}
      {onPegarCajonEncima || onPegarCajonDebajo ? null : (
        <p className="px-3 py-2 text-[11px] text-neutral-400">
          Copia un cajón de esta misma sección para poder pegarlo aquí.
        </p>
      )}
    </div>
  );
}

/**
 * EL COLOR Y EL DIBUJO DE LA SECCIÓN EN LA QUE ESTAMOS.
 *
 * Cada pestaña tiene el suyo —lo que se dice va en azul, lo que se vende en
 * verde, el dinero en fucsia— y todos los cajones de dentro lo heredan. Así dos
 * pestañas del mismo color se leen como vecinas, y dentro de una, el color dice
 * a simple vista que todo eso es la misma cosa.
 *
 * Va por contexto y no por parámetro porque los cajones están escritos en
 * cientos de sitios, muchos dentro de componentes aparte: pasarlo a mano
 * significaría tocar los cientos, y el día que cambie un color, otra vez.
 */
const TonoDeLaSeccion = createContext<{ tono: TonoDelTema; icono: string }>({
  tono: "violeta",
  icono: "📄",
});

/**
 * EL DIBUJO QUE VA DELANTE DEL TÍTULO, SEPARADO DEL TEXTO.
 *
 * Los títulos de los cajones se escribieron con el emoji pegado: «🛒 PRODUCTO
 * UPSELL». Para dibujarlo en su cuadrado de color hay que separarlo, y hacerlo
 * aquí evita reescribir los cientos de sitios donde está puesto.
 *
 * Solo el del principio, y solo si detrás queda texto: un título que sea ÚNICA-
 * MENTE un emoji se deja como está, porque quitárselo lo dejaría sin nombre.
 */
const EMOJI_AL_PRINCIPIO =
  /^(?:\p{Extended_Pictographic}(?:️|‍\p{Extended_Pictographic})*\s*)+/u;

function partirTituloConEmoji(title: ReactNode): {
  icono: string | null;
  texto: ReactNode;
} {
  if (typeof title !== "string") return { icono: null, texto: title };
  const encontrado = title.match(EMOJI_AL_PRINCIPIO);
  if (!encontrado) return { icono: null, texto: title };
  const resto = title.slice(encontrado[0].length).trim();
  if (!resto) return { icono: null, texto: title };
  return { icono: encontrado[0].trim(), texto: resto };
}

/**
 * EL CÍRCULO DE ENCENDIDO, EN LA CABECERA DEL CAJÓN.
 *
 * Claro = encendido, oscuro = apagado. Sin marca dentro: ni un check ni un
 * punto. Lo pidió así el dueño y tiene razón — una marca dentro ensucia una fila
 * que ya lleva dibujo, título y chapa, y el color solo ya lo dice.
 *
 * VA EN LA CABECERA, plegada o desplegada, porque encender y apagar es lo que
 * más se toca y estaba dentro del cajón: había que abrirlo para saber si estaba
 * activo, y eso en una lista de catorce es abrirlos todos.
 */
function CirculoDeEncendido({
  encendido,
  onCambiar,
  queEs,
}: {
  encendido: boolean;
  onCambiar: () => void;
  /** Qué se enciende, para el texto de ayuda. Ej: «esta intro». */
  queEs: string;
}) {
  return (
    <button
      type="button"
      onClick={onCambiar}
      title={
        encendido
          ? `Encendido: ${queEs} se usa. Toca para apagarla`
          : `Apagado: ${queEs} no se usa. Toca para encenderla`
      }
      aria-pressed={encendido}
      aria-label={`${encendido ? "Apagar" : "Encender"} ${queEs}`}
      className={`h-5 w-5 shrink-0 rounded-full border transition-colors ${
        encendido
          ? "border-emerald-600 bg-emerald-300 hover:bg-emerald-200"
          : "border-neutral-600 bg-neutral-600 hover:bg-neutral-500"
      }`}
    />
  );
}

/**
 * A QUÉ ALTURA ESTÁ ESTE CAJÓN.
 *
 * Los cajones se meten unos dentro de otros —un seguimiento lleva sus variantes,
 * y cada variante sus burbujas— y todos se pintaban igual de grandes. Con tres
 * niveles a la vista, dónde empieza uno y acaba otro había que deducirlo por la
 * sangría.
 *
 * El de fuera lleva el dibujo grande y los de dentro uno pequeño. Se cuenta
 * solo: cada cajón le pasa a sus hijos su altura más uno, así que nadie tiene
 * que acordarse de decir «yo voy dentro».
 */
const NivelDeCajon = createContext(0);

/** Un cajón de intro en la pantalla. Misma forma que en el motor. */
type GrupoDeIntroEditor = {
  name?: string;
  enabled?: boolean;
  weight?: number;
  /** LA BANDERA, QUE ES UNA ETIQUETA MÁS. Vacío = para todos los países.
   *  Ver `BanderaTagPicker`. Faltaba aquí y el dueño lo vio en su prueba del
   *  24/09: «no le has puesto en la intro del OB; cuando yo cambio a COMO ob,
   *  aquí también debería haber ese selector». */
  paises?: string[];
  pais_routing_enabled?: boolean;
  /** LA SEMIMODALIDAD — «lineal», «dou» u «ob». Vacío = general, sale cuando
   *  ninguna etiquetada corresponde. Ver `PastillaDeSemimodalidad`. */
  semimodalidad?: string;
  /** LAS TIENDAS que reciben este cajón, por id. Vacío = todas.
   *  Ver `PastillaDeTiendas`: es la única etiqueta que EXCLUYE. */
  tiendas?: string[];
  /** Su camino (18/10/2026). Vacío = el principal. Ver `etiqueta-de-camino.ts`. */
  camino?: string;
  /** Los otros caminos que también pasan por ella (PRINCIPAL = el principal). */
  tambien_en_caminos?: string[];
  steps?: EditorStep[];
};

/**
 * LOS CAJONES QUE VE UN CANAL LA PRIMERA VEZ.
 *
 * Un canal que todavía no tiene los suyos no puede abrir en blanco con un botón
 * de «agregar». Eso obliga a reescribir lo que ya está escrito, y mientras tanto
 * la pantalla enseña vacío algo que el bot sí está enviando.
 *
 * Así que llega con lo de la modalidad delante, listo para editar o duplicar. Es
 * el mismo trato que ya tienen las entregas por canal.
 *
 * Se SIEMBRA, no se enlaza: en cuanto se toca, ese canal tiene lo suyo y la
 * modalidad se queda como estaba. Es la gracia de tener canales.
 */
function cajonesSembrados(
  propios: GrupoDeIntroEditor[] | undefined,
  deLaModalidad: GrupoDeIntroEditor[] | undefined,
  respaldo: EditorStep[] | undefined
): GrupoDeIntroEditor[] {
  if (propios && propios.length > 0) return propios;
  if (deLaModalidad && deLaModalidad.length > 0) return cloneJson(deLaModalidad);
  if (respaldo && respaldo.length > 0) {
    return [
      { name: "", enabled: true, weight: 1, steps: cloneJson(respaldo) },
    ];
  }
  // Ni cajones ni versión vieja: uno vacío, para que haya dónde escribir.
  return [{ name: "", enabled: true, weight: 1, steps: [emptyStep()] }];
}

/**
 * EL DIBUJO DE CADA CLASE DE CAJÓN.
 *
 * Antes salía de la PESTAÑA donde estabas, así que dentro de Canales las intros,
 * los seguimientos y las variantes llevaban los tres el mismo teléfono. El
 * dibujo tiene que decir qué clase de mensaje es, no dónde estás parado.
 */
const ICONO_DE_CAJON = {
  /** El primer contacto. */
  intro: "📱",
  /** El que vuelve a escribirle al que no contestó. */
  seguimiento: "📲",
  /** La oferta de dos opciones: la balanza de elegir, en forma de bolsa. */
  orderBump: "🛍️",
  /** La segunda venta, hacia arriba. */
  upsell: "⬆️",
} as const;

function Collapsible({
  title,
  /** El dibujo de la ficha. Manda sobre el emoji pegado al título y sobre el de
   *  la pestaña: ver `ICONO_DE_CAJON`. */
  icono: iconoPropio,
  /** El título no es un nombre escrito: lo puso el cajón porque el campo está
   *  vacío. Se pinta en gris flojo para que se distinga de uno de verdad. */
  tituloDeRelleno,
  titleKey,
  titleClassName,
  /** La frase corta debajo del título. Dice qué se hace en este cajón sin
   *  tener que abrirlo. */
  subtitulo,
  /** Apagado: se pinta gris oscuro y, al pasar el mouse, rojo suave. Sin
   *  esto el hover lo aclaraba y parecía encendido. */
  inactivo,
  /** Click derecho en la cabecera: copiar este cajón entero. */
  onCopiarCajon,
  /** Click derecho: pegar el cajón copiado JUSTO ENCIMA de este. */
  onPegarCajonEncima,
  /** Click derecho: pegar el cajón copiado JUSTO DEBAJO de este. */
  onPegarCajonDebajo,
  /** Qué hay en el portapapeles, para nombrarlo en el menú. */
  etiquetaCajonCopiado,
  bodyClassName,
  headerActions,
  onDragOver,
  onDrop,
  defaultOpen = false,
  openSignal,
  closeSignal,
  /** LA BARRA IGUAL, PERO ABRE UNA VENTANA.
   *
   *  Encendido, la cabecera se queda EXACTAMENTE como un cajón plegado —mismo
   *  recuadro, misma flecha, mismo borde de «estoy aquí», mismo clic derecho— y
   *  lo único que cambia es a dónde va el contenido: a una ventana, en vez de
   *  crecer hacia abajo.
   *
   *  Se hace aquí, con un interruptor, y no copiando barras a mano: dos barras
   *  escritas por separado acaban pareciéndose cada vez menos, y el día que una
   *  cambie la otra se queda vieja sin que nadie lo note.
   *
   *  El título tiene que ser TEXTO, porque también es el de la ventana. */
  enVentana = false,
  children,
}: {
  title: ReactNode;
  icono?: string;
  tituloDeRelleno?: boolean;
  titleKey?: string;
  titleClassName?: string;
  subtitulo?: string;
  inactivo?: boolean;
  onCopiarCajon?: () => void;
  onPegarCajonEncima?: () => void;
  onPegarCajonDebajo?: () => void;
  etiquetaCajonCopiado?: string;
  bodyClassName?: string;
  headerActions?: ReactNode;
  onDragOver?: (e: React.DragEvent<HTMLDivElement>) => void;
  onDrop?: (e: React.DragEvent<HTMLDivElement>) => void;
  defaultOpen?: boolean;
  openSignal?: number;
  closeSignal?: number;
  enVentana?: boolean;
  children: ReactNode | (() => ReactNode);
}) {
  const storageKey = `wf:collapsible:${titleKey ?? String(title)}`;
  // EN VENTANA NO SE RECUERDA NADA.
  //
  // Un cajón se deja abierto a propósito y uno espera encontrarlo abierto al
  // volver. Una ventana tapa la pantalla: recordarla significaría entrar a la
  // pestaña y encontrarse una ventana encima que nadie acaba de abrir.
  const recuerda = !enVentana;
  // De fuera hacia dentro: el de arriba lleva el dibujo grande y los de dentro
  // uno pequeño. Ver `NivelDeCajon`.
  const nivel = useContext(NivelDeCajon);
  const [open, setOpen] = useState(defaultOpen);
  // Recupera el estado (abierto/cerrado) guardado para que PERSISTA al cambiar
  // de pestaña o recargar — antes se reiniciaba a cerrado.
  //
  // Y VUELVE A LEERLO CUANDO ALGUIEN MUEVE CAJONES.
  //
  // Leerlo una sola vez basta mientras nadie mueva nada. Al mover, la llave es
  // la POSICIÓN y lo que hay en cada posición pasa a ser otra cosa: sin releer,
  // cada cajón se quedaba con lo que recordaba y el que seguía abierto era el
  // de la posición de antes, con otro contenido dentro.
  useEffect(() => {
    if (!recuerda) return;
    const leer = () => {
      try {
        const saved = localStorage.getItem(storageKey);
        if (saved !== null) setOpen(saved === "1");
      } catch {}
    };
    leer();
    window.addEventListener("wf:releer-cajones", leer);
    return () => window.removeEventListener("wf:releer-cajones", leer);
  }, [storageKey, recuerda]);
  // UNA SEÑAL ES ALGO QUE ACABA DE PASAR, NO UN VALOR QUE EXISTE.
  //
  // AQUÍ ESTABA EL CAJÓN QUE SE ABRÍA SOLO.
  //
  // Estos dos efectos miraban solo si la señal EXISTE. Quien la manda la deja
  // puesta —se apunta al mover un cajón y no se borra nunca—, así que en cada
  // remontaje volvía a dispararse. Y cambiar de pestaña y volver ES un
  // remontaje: la pestaña entera se desmonta.
  //
  // Resultado: movías un cajón una vez, y a partir de ahí ese cajón se abría
  // solo cada vez que volvías. Lo cerrabas, ibas a otra pestaña, y al regresar
  // estaba abierto otra vez. No hay error, no hay aviso: parece que el editor
  // no recuerda nada, cuando lo que pasa es que alguien lo vuelve a abrir.
  //
  // Ahora se recuerda la última señal ATENDIDA. Al montar, la primera que se ve
  // ya cuenta como atendida, así que no se hace nada. Solo se reacciona cuando
  // llega una distinta, que es cuando de verdad acaba de pasar algo.
  // Apuntar «abierto» o «cerrado», salvo en ventana, que no se recuerda.
  const apuntar = useCallback(
    (valor: "0" | "1") => {
      if (!recuerda) return;
      try {
        localStorage.setItem(storageKey, valor);
      } catch {}
    },
    [recuerda, storageKey]
  );
  const ultimaSenalDeAbrir = useRef(openSignal);
  const ultimaSenalDeCerrar = useRef(closeSignal);
  useEffect(() => {
    if (openSignal === undefined || openSignal === ultimaSenalDeAbrir.current) {
      return;
    }
    ultimaSenalDeAbrir.current = openSignal;
    setOpen(true);
    apuntar("1");
  }, [openSignal, apuntar]);
  useEffect(() => {
    if (
      closeSignal === undefined ||
      closeSignal === ultimaSenalDeCerrar.current
    ) {
      return;
    }
    ultimaSenalDeCerrar.current = closeSignal;
    setOpen(false);
    apuntar("0");
  }, [closeSignal, apuntar]);
  useEffect(() => {
    const onCollapseAll = (event: Event) => {
      const prefix =
        event instanceof CustomEvent && typeof event.detail?.prefix === "string"
          ? event.detail.prefix
          : "";
      if (prefix && titleKey && !titleKey.startsWith(prefix)) return;
      setOpen(false);
      apuntar("0");
    };
    window.addEventListener("wf:collapse-all", onCollapseAll);
    return () => window.removeEventListener("wf:collapse-all", onCollapseAll);
  }, [apuntar, titleKey]);
  useEffect(() => {
    const onOpenRequested = (event: Event) => {
      const keys =
        event instanceof CustomEvent && Array.isArray(event.detail?.keys)
          ? event.detail.keys
          : [];
      if (!titleKey || !keys.includes(titleKey)) return;
      setOpen(true);
      apuntar("1");
    };
    window.addEventListener("wf:open-collapsibles", onOpenRequested);
    return () => window.removeEventListener("wf:open-collapsibles", onOpenRequested);
  }, [apuntar, titleKey]);
  // EL ÚLTIMO QUE SE TOCA ES EL ACTIVO.
  //
  // Se apunta con un aviso a todos: el que coincide se enciende y los demás se
  // apagan solos. Al cerrar no queda ninguno, porque cerrar es dejar de estar.
  const [activo, setActivo] = useState(false);
  useEffect(() => {
    const alCambiar = (evento: Event) => {
      const cual =
        (evento as CustomEvent<{ key?: string | null }>).detail?.key ?? null;
      setActivo(cual === storageKey);
    };
    window.addEventListener(CAJON_ACTIVO, alCambiar);
    return () => window.removeEventListener(CAJON_ACTIVO, alCambiar);
  }, [storageKey]);
  const toggle = (evento?: { nativeEvent: Event }) => {
    // El clic de la cabecera no puede llegar al contenedor: allí volvería a
    // reclamar el foco y al cerrar lo devolvería justo después de soltarlo.
    if (evento) (evento.nativeEvent as ClicDeCajon).__cajonAtendido = true;
    setOpen((o) => {
      const next = !o;
      apuntar(next ? "1" : "0");
      anunciarCajonActivo(next ? storageKey : null);
      return next;
    });
  };
  // EL CONTENIDO VA UN NIVEL MÁS ADENTRO, y por eso sus cajones llevan el dibujo
  // pequeño. Se cuenta solo: nadie tiene que acordarse de decir «yo voy dentro».
  const body = open ? (
    <NivelDeCajon.Provider value={nivel + 1}>
      {typeof children === "function" ? children() : children}
    </NivelDeCajon.Provider>
  ) : null;
  // LA BARRA SE VE PLEGADA SIEMPRE QUE EL CONTENIDO SE VAYA A UNA VENTANA.
  //
  // Si no, al abrir la ventana la barra de debajo se quedaba con cara de
  // desplegada —flecha hacia abajo, fondo verde y la línea de separación— pero
  // sin nada debajo. Al cerrar la ventana se veía ese cajón abierto y vacío.
  const desplegado = open && !enVentana;

  // El color y el dibujo de la pestaña en la que estamos, y el emoji propio del
  // título si lo lleva pegado. Ver `TonoDeLaSeccion` y `partirTituloConEmoji`.
  const seccion = useContext(TonoDeLaSeccion);
  const { icono, texto } = partirTituloConEmoji(title);

  const menuDelCajon = useMenuDeCajon();
  const hayMenu = Boolean(onCopiarCajon || onPegarCajonEncima || onPegarCajonDebajo);
  return (
    <div
      onDragOver={onDragOver}
      onDrop={onDrop}
      // Marca para que deshacer sepa qué cajones tiene que abrir antes de
      // llevarte al sitio del cambio.
      data-collapsible-key={titleKey}
      // UN CLIC DENTRO TAMBIÉN LO ACTIVA.
      //
      // No hace falta volver a la cabecera para decir «estoy aquí»: se escribe
      // dentro y ya. El primero que atiende el clic es el cajón MÁS INTERNO,
      // así que en los anidados gana la subpestaña, que es donde está la mano.
      onClickCapture={(evento) => {
        const clic = evento.nativeEvent as ClicDeCajon;
        if (clic.__cajonAtendido) return;
        clic.__cajonAtendido = true;
        anunciarCajonActivo(storageKey);
      }}
      // EL ACTIVO SE VE, SIN OSCURECER NADA.
      //
      // Antes el borde marcaba «abierto», y se pueden tener varios abiertos a
      // la vez: al final media pantalla iba con borde y dejaba de decir nada.
      // Ahora marca UNO, el último que se tocó.
      //
      // Se marca con borde y no atenuando los demás: atenuar obliga a apagar
      // los nombres de los otros cajones, que es justo lo que hace falta leer
      // para orientarse, y hace que media pantalla cambie de brillo.
      //
      // Y es el borde que ya usa esta casa para la burbuja seleccionada. Un
      // solo idioma para «esto es en lo que estoy».
      // EL GROSOR SOLO CRECE EN LA SELECCIONADA.
      //
      // Se probó dejando 2 px en las dos, para que no diera el saltito de un
      // píxel al marcarla. Pero engordaba TODAS las pestañas, que no era lo
      // pedido: la línea gruesa es la marca de «estoy aquí», y si la llevan
      // todas deja de marcar nada.
      //
      // El ancho va dentro de cada rama, no en la base: dos anchos de borde
      // sueltos en la misma clase y gana el que decida el CSS generado, no el
      // orden en que se escriben.
      // TARJETA BLANCA SOBRE EL PANEL GRIS, NO UNA BARRA GRIS SOBRE GRIS.
      //
      // Iba en gris muy claro sobre un suelo casi blanco: una lista de barras
      // planas, todas iguales, sin nada que dijera dónde empieza cada una. La
      // pestaña Canales ya se veía de la otra forma —tarjeta blanca, cuadrado
      // de color, título y frase— y las dos maneras convivían en el mismo
      // editor. Esta es la de Canales, para todos.
      className={`rounded-2xl bg-tarjeta ${
        activo
          ? "border-2 border-emerald-600 shadow-md"
          : "border border-borde shadow-sm"
      }`}
    >
      {/* LA BARRA ENTERA YA NO ABRE EL CAJÓN.
          Abría con un clic en cualquier parte, así que seleccionar el texto de un
          campo de la cabecera, o soltar el ratón un pelo fuera de un botón,
          plegaba lo que estabas mirando. Abren solo el triangulito y la chapa de
          «Abrir», que es como funcionan las fichas de producto — y ahí nunca
          estorbó. El clic derecho del menú se queda en toda la barra. */}
      <div
        onContextMenu={hayMenu ? menuDelCajon.abrir : undefined}
        className={`flex w-full items-center gap-4 px-5 py-4 text-left transition-colors ${
          inactivo
            ? "hover:border-rose-400 hover:bg-rose-50"
            : "hover:bg-relleno"
        } ${
          // Un tinte MUY suave en la barra del abierto, para que el borde no
          // vaya solo. `titleClassName` sigue mandando cuando lo hay: es lo que
          // pinta de gris los cajones apagados, y eso no puede taparse.
          titleClassName ?? (desplegado ? "bg-emerald-50" : "bg-tarjeta")
        } ${
          desplegado
            ? "rounded-t-2xl border-b border-emerald-200"
            : "rounded-2xl"
        }`}
      >
        {/* EL CUADRADO DE COLOR VA PRIMERO Y GRANDE A PROPÓSITO.
            Es la guía que el ojo busca antes de leer nada, así que dos filas
            distintas se distinguen sin leerlas. El dibujo sale del propio
            título cuando lo lleva pegado —«🛒 PRODUCTO UPSELL»— y, si no, se
            hereda el de la pestaña. */}
        {/* EL TRIANGULITO VUELVE, Y NO SOBRA.
            Se quitó al poner la chapa de «Abrir / Cerrar», pensando que decían
            lo mismo. No lo dicen: la chapa dice qué PASA al tocar y el
            triangulito dice CÓMO ESTÁ. En una lista de catorce cajones, ver de
            un vistazo cuáles están abiertos es lo que dice dónde te quedaste.
            Y apunta: a la derecha cerrado, hacia abajo abierto. */}
        <button
          type="button"
          onClick={toggle}
          aria-expanded={desplegado || (enVentana && open)}
          title={
            desplegado || (enVentana && open) ? "Cerrar este cajón" : "Abrir este cajón"
          }
          className="shrink-0 rounded px-1 text-xs text-tinta-suave hover:bg-relleno"
        >
          {desplegado ? "▼" : "▶"}
        </button>
        <FichaDeIcono
          tono={seccion.tono}
          clase={tonoDeFila(typeof title === "string" ? title : (titleKey ?? ""))}
          tamano={nivel === 0 ? "lg" : "md"}
        >
          {iconoPropio ?? icono ?? seccion.icono}
        </FichaDeIcono>
        <span className="min-w-0 flex-1">
          {/* SIN NOMBRE, LO DICE EN ROJO Y NO SE INVENTA UNO.
              Antes el cajón se renombraba solo al quedarse vacío, así que el
              título nunca se podía borrar y nadie sabía por qué. Ahora se queda
              vacío de verdad y la barra pide el nombre. En rojo porque es algo
              que hay que hacer, no un dato. */}
          <span
            className={`font-titulo block text-base font-extrabold tracking-tight ${
              tituloDeRelleno ? "text-red-600" : "text-tinta"
            }`}
          >
            {texto}
          </span>
          {subtitulo && (
            <span className="mt-0.5 block text-xs leading-snug text-tinta-suave">
              {subtitulo}
            </span>
          )}
        </span>
        <span className="flex shrink-0 flex-wrap items-center justify-end gap-2">
          {headerActions}
          {/* LA CHAPA DICE QUÉ PASA AL TOCAR, NO CÓMO ESTÁ.
              Antes había una flecha a la izquierda del título. Una flecha dice
              el estado; esta dice la acción, que es lo que hace falta saber
              antes de tocar. Es la misma chapa de las filas de Canales. */}
          <button
            type="button"
            onClick={toggle}
            className="rounded-full bg-relleno px-3 py-1.5 text-xs font-bold text-tinta-suave hover:bg-borde"
          >
            {desplegado || (enVentana && open) ? "Cerrar" : "Abrir"}
          </button>
        </span>
      </div>
      {desplegado && (
        <div className={`px-4 pb-4 pt-3 ${bodyClassName ?? ""}`}>{body}</div>
      )}
      {/* EL MISMO CONTENIDO, EN LA VENTANA DE LA CASA.
          Es `children` tal cual, sin una sola copia: lo que se editaba dentro
          del cajón es lo que se edita dentro de la ventana, con sus campos, sus
          clics derechos y sus vistas previas.
          Sin «Cancelar»: aquí se escribe DIRECTO en la configuración, letra a
          letra, igual que en el cajón. Un botón de cancelar prometería deshacer
          algo que ya está hecho. Para eso está Deshacer, arriba. */}
      {enVentana && open && (
        <VentanaDeProducto
          titulo={typeof title === "string" ? title : (titleKey ?? "Editar")}
          colorPorDefecto="blanco"
          onCerrar={() => toggle()}
        >
          <div className={bodyClassName ?? ""}>{body}</div>
        </VentanaDeProducto>
      )}
      <MenuDeCajon
        estado={menuDelCajon}
        onCopiarCajon={onCopiarCajon}
        onPegarCajonEncima={onPegarCajonEncima}
        onPegarCajonDebajo={onPegarCajonDebajo}
        etiquetaCajonCopiado={etiquetaCajonCopiado}
      />
    </div>
  );
}

// ── Editor de una opción del Order Bump (combo / básico) ────────────────────
function PlaceholderHelp() {
  // AQUÍ HABÍA UNA SEGUNDA LISTA DE COMODINES, A MANO Y MUERTA.
  //
  // Veintiocho entradas escritas aquí que no leía nadie: la lista de verdad
  // viene del contexto, ya filtrada por la modalidad activa. Al no usarse,
  // nadie la actualizaba — seguía nombrando comodines que ya no se ofrecen.
  //
  // Una copia dormida de una lista es una trampa: el día que alguien la lea
  // creerá que dice la verdad.
  const filteredItems = useContext(PlaceholderOptionsContext);
  return (
    <div className="border-t border-neutral-200 bg-neutral-50 px-4 py-3">
      <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
        {filteredItems.map((item) => (
          <div
            key={item.token}
            className="rounded-md border border-neutral-200 bg-tarjeta px-3 py-2"
          >
            <code className="block text-xs font-semibold text-emerald-700">
              {item.token}
            </code>
            <p className="mt-1 text-[11px] leading-snug text-neutral-600">
              {item.description ?? item.label}
            </p>
          </div>
        ))}
      </div>
      <p className="mt-2 text-[11px] text-neutral-500">
        Cada precio tiene su comodín: {"{{PRECIO_BASE}}"}, {"{{PRECIO_FULL}}"} y{" "}
        {"{{PRECIO_UPSELL}}"}. Todos traen su símbolo y su moneda — no escribas
        el «S/.» ni el «SOLES» al lado, o un cliente de otro país leerá la
        moneda equivocada.
      </p>
    </div>
  );
}

/**
 * LOS PRECIOS DE LAS DOS OPCIONES VIVEN POR PAÍS, EN UN SOLO SITIO.
 *
 * La pestaña de las dos ofertas escribía el precio GLOBAL mientras Precios y
 * pagos escribía el del PAÍS — y el del país manda. Se corregía uno, el bot
 * seguía cobrando el otro, y al vender fuera de Perú se cobraba en soles el
 * número de otra tienda. Un precio equivocado no da error: cobra de menos.
 *
 * Estas dos funciones hacen lo mismo que ya hacía Order Bump: leer de la capa
 * del país con el global de respaldo, y escribir en la capa. Nombre y textos
 * siguen siendo comunes a todos los países.
 */
function preciosPorPaisDeOpcion(
  cfg: FullConfig,
  modalidad: "doble_oferta_dos" | "doble_oferta_upsell",
  cual: "combo" | "basico",
  cc: CountryCode
): { price_soles: number; discount_price_soles: number } {
  const perfil = cfg.modality_payment_profiles?.[modalidad]?.[cc];
  const global = cfg.doble_oferta_dos[cual];
  if (cual === "combo") {
    return {
      price_soles:
        perfil?.order_bump?.combo_price_soles ?? global.price_soles,
      discount_price_soles:
        perfil?.order_bump?.combo_discount_price_soles ??
        global.discount_price_soles,
    };
  }
  return {
    price_soles: perfil?.course_price_soles ?? global.price_soles,
    discount_price_soles:
      perfil?.discount_price_soles ?? global.discount_price_soles,
  };
}

function guardarOpcionDeDosNiveles(
  cfg: FullConfig,
  modalidad: "doble_oferta_dos" | "doble_oferta_upsell",
  cual: "combo" | "basico",
  cc: CountryCode,
  v: ObOption
): FullConfig {
  const global = cfg.doble_oferta_dos[cual];
  const mostrado = preciosPorPaisDeOpcion(cfg, modalidad, cual, cc);
  // Global: TODO menos el precio, que es del país.
  const base: FullConfig = {
    ...cfg,
    doble_oferta_dos: {
      ...cfg.doble_oferta_dos,
      [cual]: {
        ...v,
        price_soles: global.price_soles,
        discount_price_soles: global.discount_price_soles,
      },
    },
  };
  // Solo se crea capa del país si cambió el precio: editar el nombre o un texto
  // no debe dejar a ese país con precios propios sin que nadie lo pidiera.
  const cambioElPrecio =
    v.price_soles !== mostrado.price_soles ||
    v.discount_price_soles !== mostrado.discount_price_soles;
  if (!cambioElPrecio) return base;
  const capa = cfg.modality_payment_profiles?.[modalidad] ?? {};
  const sembrado =
    capa[cc] ??
    mergeCountryPaymentProfileForEditor(
      cc,
      cfg,
      cfg.payment_profiles_by_country?.[cc]
    );
  const conPrecio =
    cual === "combo"
      ? {
          ...sembrado,
          order_bump: {
            ...sembrado.order_bump,
            combo_price_soles: v.price_soles,
            combo_discount_price_soles: v.discount_price_soles,
          },
        }
      : {
          ...sembrado,
          course_price_soles: v.price_soles,
          discount_price_soles: v.discount_price_soles,
        };
  return {
    ...base,
    modality_payment_profiles: {
      ...cfg.modality_payment_profiles,
      [modalidad]: { ...capa, [cc]: conPrecio },
    },
  };
}

/**
 * EL MENSAJE QUE ABRE EL PAGO DE ESTA OPCIÓN.
 *
 * Vivía dentro del cajón del producto, en Order Bump, metido en un desplegable
 * dentro de otro desplegable — dos clics a ciegas. Ahora vive en 👤 Usuario,
 * junto a los datos de pago y a los métodos, que es donde el dueño va cuando
 * quiere tocar lo que se dice al cobrar.
 *
 * Se sacó a su propio componente para MOVERLO, no para copiarlo: hay una sola
 * implementación, y sigue guardando exactamente donde guardaba —el campo de la
 * opción, o su override del país— así que el motor no se entera de nada.
 */
function MensajeDirectoAntesDelPago({
  value,
  onChange,
  idPrefix,
  snapshot,
  editSnapshot,
  comboPrice,
  basicoPrice,
  previewContext,
  editingCountry,
  defaultCountry,
}: {
  value: ObOption;
  onChange: (v: ObOption) => void;
  idPrefix: string;
  snapshot: () => void;
  editSnapshot: (key: string) => void;
  comboPrice?: number;
  basicoPrice?: number;
  previewContext?: PreviewContext;
  editingCountry?: CountryCode;
  defaultCountry?: CountryCode;
}) {
  const country = editingCountry ?? defaultCountry ?? "PE";
  const isBaseCountry = country === (defaultCountry ?? "PE");
  const ov = value.by_country?.[country];
  const steps = isBaseCountry
    ? value.direct_payment_prompt ?? []
    : ov?.direct_payment_prompt ?? value.direct_payment_prompt ?? [];
  const setSteps = (siguientes: EditorStep[]) =>
    isBaseCountry
      ? onChange({ ...value, direct_payment_prompt: siguientes })
      : onChange({
          ...value,
          by_country: {
            ...value.by_country,
            [country]: {
              ...value.by_country?.[country],
              direct_payment_prompt: siguientes,
            },
          },
        });
  return (
    <div className="space-y-3 rounded-lg border border-amber-200 bg-amber-50 p-4">
      <label className="flex items-start gap-2 text-sm font-semibold text-neutral-800">
        <input
          type="checkbox"
          checked={value.direct_payment_prompt_enabled === true}
          onChange={(e) =>
            onChange({
              ...value,
              direct_payment_prompt_enabled: e.target.checked,
              direct_payment_prompt:
                value.direct_payment_prompt &&
                value.direct_payment_prompt.length > 0
                  ? value.direct_payment_prompt
                  : [
                      {
                        type: "text",
                        drive_url: "",
                        texts: [
                          "🔥 *Buena elección!* Elegiste esta opción por *{{PRECIO_COMPLETO}}*.\n\nAhora puedes pagar con cualquiera de estos métodos 👇",
                        ],
                        delay_after_sec: 0,
                        enabled: true,
                      },
                    ],
            })
          }
          className="mt-0.5 h-4 w-4"
        />
        <span>Usar este mensaje y mostrar métodos de pago directamente</span>
      </label>
      <p className="text-xs leading-5 text-neutral-600">
        Encendido: reemplaza la respuesta clásica de elección y luego muestra los
        métodos de pago. Apagado: conserva el flujo actual.
      </p>
      <p className="text-xs leading-5 text-neutral-600">
        <b>Este texto presenta el pago.</b> Cuando está encendido, el bot no
        vuelve a presentarlo con el texto general: pasa directo a los datos de
        pago del país y al cierre. Antes salían las dos frases seguidas diciendo
        lo mismo con distintas palabras.
      </p>
      {value.direct_payment_prompt_enabled === true && (
        <StepEditorPreviewPair
          steps={steps}
          onChange={setSteps}
          onSnapshot={snapshot}
          onEdit={editSnapshot}
          idPrefix={`${idPrefix}_direct_pay`}
          priceSoles={value.price_soles}
          comboPrice={comboPrice}
          basicoPrice={basicoPrice}
          previewContext={previewContext}
        />
      )}
    </div>
  );
}

function ObOptionEditor({
  title,
  /** Qué papel de la biblioteca llena esta opción, si es que alguno. Con el
   *  papel tomado, el cajón deja de editarse y dice quién lo llena. */
  papel,
  value,
  onChange,
  idPrefix,
  snapshot,
  editSnapshot,
  comboPrice,
  basicoPrice,
  previewContext,
  hideDelivery,
  showChoiceAliasGenerator,
  editingCountry,
  defaultCountry,
}: {
  title: string;
  papel?: PuestoDeProducto;
  value: ObOption;
  onChange: (v: ObOption) => void;
  idPrefix: string;
  snapshot: () => void;
  editSnapshot: (key: string) => void;
  comboPrice?: number;
  basicoPrice?: number;
  previewContext?: PreviewContext;
  hideDelivery?: boolean;
  showChoiceAliasGenerator?: boolean;
  editingCountry?: CountryCode;
  defaultCountry?: CountryCode;
}) {
  // País cuyos TEXTOS se editan. El país por defecto (usualmente Perú) edita los
  // campos BASE; cualquier otro país edita su override en value.by_country[cc],
  // mostrando el texto base como punto de partida (fallback). La entrega NO se
  // individualiza. Igual patrón que "Precios y pagos".
  const country = editingCountry ?? defaultCountry ?? "PE";
  const isBaseCountry = country === (defaultCountry ?? "PE");
  // QUIÉN JUEGA ESTE PUESTO, para que el visor resuelva {{PRODUCTO_ENTREGADO}}
  // con el nombre de verdad. Si nadie lo juega, el del propio cajón, que es lo
  // que le va a llegar al cliente.
  const quienJuegaAqui = useQuienJuega(papel);
  const ov = value.by_country?.[country];
  const countryLabel =
    COUNTRY_OPTIONS.find((c) => c.code === country)?.label ?? country;
  // Setter del override por país para un campo suelto (response / direct_payment_prompt).
  const setCountryField = (
    field: "response" | "direct_payment_prompt",
    steps: EditorStep[]
  ) =>
    onChange({
      ...value,
      by_country: {
        ...value.by_country,
        [country]: { ...value.by_country?.[country], [field]: steps },
      },
    });
  // Setter del override por país para un método de payment_responses.
  const setCountryMethod = (
    method: "yape" | "bcp_transferencia" | "efectivo",
    steps: EditorStep[]
  ) =>
    onChange({
      ...value,
      by_country: {
        ...value.by_country,
        [country]: {
          ...value.by_country?.[country],
          payment_responses: {
            ...value.by_country?.[country]?.payment_responses,
            [method]: steps,
          },
        },
      },
    });
  // Getters (para mostrar): base si es país por defecto; si no, override ?? base.
  const responseSteps = isBaseCountry
    ? value.response
    : ov?.response ?? value.response;
  // El «mensaje directo antes de métodos de pago» se mudó a 👤 Usuario, a su
  // tarjeta propia. Ver `MensajeDirectoAntesDelPago`: una sola implementación,
  // guardando en el mismo sitio de siempre.
  const methodSteps = (
    method: "yape" | "bcp_transferencia" | "efectivo"
  ): EditorStep[] =>
    isBaseCountry
      ? value.payment_responses[method]
      : ov?.payment_responses?.[method] ?? value.payment_responses[method];
  const setResponse = (steps: EditorStep[]) =>
    isBaseCountry
      ? onChange({ ...value, response: steps })
      : setCountryField("response", steps);
  const setMethod = (
    method: "yape" | "bcp_transferencia" | "efectivo",
    steps: EditorStep[]
  ) =>
    isBaseCountry
      ? onChange({
          ...value,
          payment_responses: { ...value.payment_responses, [method]: steps },
        })
      : setCountryMethod(method, steps);
  return (
    // El rótulo cambia con la modalidad —«FULL», «COMBO», «PACK»—, así que
    // usarlo de llave hacía que el cajón olvidara si estaba abierto en cuanto
    // se cambiaba de modalidad. `idPrefix` identifica la opción y no cambia.
    <Collapsible title={title} titleKey={`ob_option_${idPrefix}`}>
      {/* Si un producto etiquetado ya llena esta opción, aquí no se edita: al
          leer la configuración manda la etiqueta, así que lo que se escribiera
          se guardaría y no se enviaría. */}
      {/* EL CANDADO TAPA EL NOMBRE, Y SOLO EL NOMBRE.
          Tapaba también los precios, y ahí se quedó sin poder editarse el PRECIO
          POR PAÍS de esta opción: ese no vive en la ficha del producto, vive
          aquí y en Precios y pagos. Taparlo dejó un dato que sale al cliente y
          no se puede tocar desde ningún sitio.
          El nombre sí es del producto y por eso se tapa. Los precios, la
          respuesta al elegir y la entrega tienen cada uno su propia regla más
          abajo. */}
      <SiLoLlenaLaBiblioteca papel={papel}>
        <NameAliases
          value={{ name: value.name, aliases: value.aliases }}
          onChange={(v) => onChange({ ...value, ...v })}
          showChoiceAliasGenerator={showChoiceAliasGenerator}
        />
      </SiLoLlenaLaBiblioteca>
      <div className="mt-3 flex flex-wrap gap-4">
        <div>
          <label className="block text-xs font-medium text-neutral-700">
            Precio normal
          </label>
          <DraftNumberInput
            value={value.price_soles}
            onValueChange={(price_soles) =>
              onChange({
                ...value,
                price_soles,
                discount_price_soles:
                  (value.discount_price_soles ?? 0) > price_soles
                    ? 0
                    : value.discount_price_soles,
              })
            }
            className="mt-1 w-32 rounded border border-neutral-300 px-3 py-2 text-sm"
          />
        </div>
        <div>
          <label className="block text-xs font-medium text-neutral-700">
            Precio promo (oferta)
          </label>
          <OfferPriceField
            normalPrice={value.price_soles}
            value={value.discount_price_soles ?? 0}
            onChange={(discount_price_soles) =>
              onChange({
                ...value,
                discount_price_soles,
              })
            }
          />
          <p className="mt-1 text-[11px] text-neutral-500">
            Se usa cuando el cliente ya entró en etapa de oferta. 0 = sin promo.
          </p>
        </div>
      </div>
      <div className="mt-4">
        <label className="block text-xs font-medium text-neutral-700">
          Regalos incluidos
        </label>
        <textarea
          value={value.regalos ?? ""}
          onChange={(e) => onChange({ ...value, regalos: e.target.value })}
          rows={3}
          className="mt-1 w-full rounded border border-neutral-300 px-3 py-2 text-sm"
          placeholder="Ej.: incluye bonos, plantillas extra, guía rápida, regalo por comentar..."
        />
        <p className="mt-1 text-[11px] text-neutral-500">
          Solo ayuda al bot a explicar qué regalos vienen con esta opción. No
          cambia precios, comprobantes ni entrega.
        </p>
      </div>
      {/* LO DE ABAJO SIGUE SIENDO DE ESTE CAJÓN.
          El guion de venta —la respuesta al elegir, el mensaje directo y las
          respuestas por método de pago— es del PUESTO, no del producto: «la
          opción cara» se presenta igual sea cual sea el producto que la ocupe, y
          esos textos ya lo nombran con comodines.
          Antes el candado tapaba todo el cajón, así que al sentar un producto
          en ese puesto el guion se volvía imposible de editar. */}
      <div className="mt-4 rounded-lg border-2 border-emerald-400 bg-emerald-50 px-3 py-2 text-xs text-emerald-900">
        ✏️ Editando los textos de <b>{countryLabel}</b>
        {isBaseCountry ? (
          <> (país base). Cambia el país arriba para personalizar otro.</>
        ) : (
          <>
            {" "}
            — independiente de los demás países. Vacío = usa el texto de{" "}
            <b>{COUNTRY_OPTIONS.find((c) => c.code === (defaultCountry ?? "PE"))?.label ?? "base"}</b>.
          </>
        )}
        <div className="mt-1 text-[11px] text-emerald-700">
          Aplica a: respuesta al elegir, mensaje directo y Yape/BCP/Efectivo. La{" "}
          <b>entrega es común</b> a todos los países.
        </div>
      </div>
      <h3 className="mb-2 mt-4 text-sm font-semibold text-neutral-800">
        Respuesta al elegir (método de pago + precio)
      </h3>
      <StepEditorPreviewPair
        steps={responseSteps}
        onChange={setResponse}
        onSnapshot={snapshot}
        onEdit={editSnapshot}
        idPrefix={`${idPrefix}_resp`}
        priceSoles={value.price_soles}
        comboPrice={comboPrice}
        basicoPrice={basicoPrice}
        previewContext={previewContext}
      />
      <h3 className="mb-1 mt-5 text-sm font-semibold text-neutral-800">
        Respuestas al confirmar el método de pago
      </h3>
      <p className="mb-3 text-xs text-neutral-500">
        Estos textos se copian inicialmente desde la pestaña Pago y luego puedes
        personalizarlos de forma independiente. Usa <code>{"{price}"}</code> o{" "}
        <code>{"{precio}"}</code> para insertar automáticamente el precio normal
        o promocional de esta opción. El preview muestra el precio normal.
      </p>
      <div className="space-y-4">
        {(
          [
            ["yape", "Forma 1 (principal)"],
            ["bcp_transferencia", "Forma 2"],
            ["efectivo", "Forma 3"],
          ] as [keyof ObOption["payment_responses"], string][]
        ).map(([key, label]) => (
          <div
            key={key}
            className="rounded-lg border border-neutral-300 bg-neutral-50 p-4"
          >
            <h4 className="mb-3 text-sm font-semibold text-neutral-800">
              {label}
            </h4>
            <StepEditorPreviewPair
              steps={methodSteps(key)}
              onChange={(steps) => setMethod(key, steps)}
              onSnapshot={snapshot}
              onEdit={editSnapshot}
              idPrefix={`${idPrefix}_pay_${key}`}
              priceSoles={value.price_soles}
              comboPrice={comboPrice}
              basicoPrice={basicoPrice}
              previewContext={previewContext}
            />
          </div>
        ))}
      </div>
      {!hideDelivery && (
        <SiLoLlenaLaBiblioteca papel={papel}>
          <h3 className="mb-2 mt-4 text-sm font-semibold text-neutral-800">
            Entrega (lo que recibe al pagar)
          </h3>
          <StepEditorPreviewPair
            steps={value.delivery}
            onChange={(steps) => onChange({ ...value, delivery: steps })}
            onSnapshot={snapshot}
            onEdit={editSnapshot}
            idPrefix={`${idPrefix}_del`}
            comboPrice={comboPrice}
            basicoPrice={basicoPrice}
            previewContext={{
              ...previewContext,
              nombreEntregado:
                quienJuegaAqui?.name?.trim() || value.name?.trim() || "",
            }}
          />
        </SiLoLlenaLaBiblioteca>
      )}
    </Collapsible>
  );
}

// ── Simulador de chat de WhatsApp ───────────────────────────────────────────
// Muestra cómo le llega al cliente la secuencia de pasos: negritas (*..*),
// cursivas (_.._), tachado (~..~), emojis e imágenes. Como el bot elige UNA
// variante al azar por paso, muestra una corrida; el botón "Variar" re-arma
// otra combinación al azar (igual que el bot real con un cliente).

/**
 * EL BOTÓN ↻, al lado de la etiqueta del enlace.
 *
 * Reemplazaste la foto en Drive conservando el enlace: le das y el bot se olvida
 * de la copia que tenía guardada, y la miniatura se rehace al momento.
 *
 * Normalmente no hace falta —el bot compara peso y fecha antes de usar su copia—
 * pero sirve para el caso raro que esa comparación no ve (una foto nueva que
 * pese exactamente lo mismo) y para cuando hay prisa.
 */
function BotonDeRefrescoDeMedia({ url }: { url: string }) {
  const { refrescar } = useContext(MarcasDeMediaContext);
  const [estado, setEstado] = useState<"quieto" | "yendo" | "listo">("quieto");
  const limpio = url.trim();
  if (!limpio) return null;
  return (
    <button
      type="button"
      title="Actualizar este archivo: olvida la copia guardada y rehace la miniatura"
      aria-label="Actualizar este archivo"
      disabled={estado === "yendo"}
      onClick={async () => {
        setEstado("yendo");
        const res = await refrescar(limpio);
        setEstado(res.ok ? "listo" : "quieto");
        if (res.ok) window.setTimeout(() => setEstado("quieto"), 1600);
      }}
      className={`rounded border px-1.5 py-0.5 text-sm leading-none transition ${
        estado === "listo"
          ? "border-emerald-300 bg-emerald-50 text-emerald-700"
          : "border-neutral-300 bg-tarjeta text-neutral-600 hover:bg-neutral-50"
      } ${estado === "yendo" ? "opacity-50" : ""}`}
    >
      {estado === "listo" ? "✓" : "↻"}
    </button>
  );
}

function driveThumb(url: string, marca?: number): string | null {
  if (!url) return null;
  const m = url.match(/\/d\/([-\w]{10,})/) || url.match(/[?&]id=([-\w]{10,})/);
  if (!m) return null;
  // La marca solo se añade cuando alguien pulsó ↻ para este archivo. Sin ella el
  // enlace es el de siempre y el navegador sigue reutilizando su copia, que es
  // lo que se quiere el 99% del tiempo. Google acepta el parámetro de sobra —
  // probado contra archivos reales: devuelve la imagen igual.
  const refresco = marca ? `&v=${marca}` : "";
  return `https://drive.google.com/thumbnail?id=${m[1]}&sz=w600${refresco}`;
}

/**
 * Los ENLACES quedan fuera del formato.
 *
 * WhatsApp reconoce la URL entera y no le aplica marcado. Aquí no se hacía, y
 * un enlace de Drive con dos guiones bajos —
 * .../1VmGlE_XthJKKFjSqD9HVzrTs4i3_Gy-V/view — salía en cursiva y SIN los
 * guiones: en la previsualización parecía un enlace roto aunque al cliente le
 * llegara entero.
 *
 * Es la misma regla que ya usa el chat (whatsapp-format.tsx). Aquí faltaba
 * porque el editor tiene su propio conversor.
 */
const ENLACE_RE = /(https?:\/\/[^\s]+)/g;
const ES_ENLACE = /^https?:\/\/\S+$/;

// Convierte el formato de WhatsApp de UNA línea a nodos (negrita/cursiva/etc.),
// dejando los enlaces intactos.
function parseWaInline(text: string): ReactNode[] {
  // Se arma la lista a mano en vez de con flatMap: las dos ramas devuelven
  // cosas de tipo distinto —una etiqueta suelta y una lista de nodos— y
  // TypeScript deducía el tipo de la primera y luego rechazaba la segunda.
  const salida: ReactNode[] = [];
  text.split(ENLACE_RE).forEach((trozo, i) => {
    if (!trozo) return;
    if (ES_ENLACE.test(trozo)) {
      salida.push(<TwemojiText key={`enlace-${i}`} text={trozo} />);
      return;
    }
    salida.push(...parseWaInlineSinEnlaces(trozo, i));
  });
  return salida;
}

function parseWaInlineSinEnlaces(text: string, prefijo = 0): ReactNode[] {
  const parts: ReactNode[] = [];
  const re = /(\*[^*\n]+\*|_[^_\n]+_|~[^~\n]+~|```[^`]+```)/g;
  let last = 0;
  let m: RegExpExecArray | null;
  let key = prefijo * 1000;
  while ((m = re.exec(text)) !== null) {
    if (m.index > last)
      parts.push(<TwemojiText key={key++} text={text.slice(last, m.index)} />);
    const tok = m[0];
    if (tok.startsWith("```"))
      parts.push(
        <code key={key++} className="font-mono text-[0.92em]">
          {tok.slice(3, -3)}
        </code>
      );
    else if (tok[0] === "*")
      parts.push(
        <strong key={key++}>
          <TwemojiText text={tok.slice(1, -1)} />
        </strong>
      );
    else if (tok[0] === "_")
      parts.push(
        <em key={key++}>
          <TwemojiText text={tok.slice(1, -1)} />
        </em>
      );
    else
      parts.push(
        <s key={key++}>
          <TwemojiText text={tok.slice(1, -1)} />
        </s>
      );
    last = m.index + tok.length;
  }
  if (last < text.length)
    parts.push(<TwemojiText key={key++} text={text.slice(last)} />);
  return parts;
}

function renderWa(text: string): ReactNode {
  return text.split("\n").map((line, i, arr) => (
    <span key={i}>
      {parseWaInline(line)}
      {i < arr.length - 1 ? <br /> : null}
    </span>
  ));
}

// Aquí vivía previewPlaceholderValues: hacía la lista de VALORES que produce un
// texto para después buscarlos dentro del resultado. Esa búsqueda era el fallo
// —pintaba lo escrito a mano cuando coincidía con un precio— y al marcar los
// comodines en su sitio dejó de hacer falta.

/** Marcas invisibles para saber DÓNDE estaba cada comodín. Son caracteres de
 *  control: nadie los puede escribir en un campo de texto. */
const MARCA_ABRE = String.fromCharCode(1);
const MARCA_CIERRA = String.fromCharCode(2);
const PATRON_DE_COMODIN =
  /\{\{\s*[A-Za-z0-9_]+\s*\}\}|\{(?:precio|price)\}/gi;

/**
 * El texto del visor con los comodines resaltados EN SU SITIO.
 *
 * ANTES se pintaba buscando el VALOR dentro del texto ya resuelto. Si el precio
 * configurado era 7.000 y alguien escribía "7.000" a mano, esa cifra escrita a
 * mano se pintaba igual: parecía un comodín y no lo era. Y al cambiar el precio
 * a 6.999 dejaba de pintarse — ahí se veía que el resaltado mentía.
 *
 * AHORA se marca dónde ESTABA cada comodín antes de resolverlo. Cada uno se
 * cambia por una marca que nadie puede teclear, el texto pasa por el mismo
 * molino de siempre —precios y luego spintax— y al final cada marca se cambia
 * por su valor, ya envuelto. Lo escrito a mano no se toca nunca.
 */
function renderPreviewTextWithHighlights(
  rawText: string,
  priceSoles: number | undefined,
  comboPrice: number | undefined,
  basicoPrice: number | undefined,
  context: PreviewContext,
  roll: number,
  stepIdx: number
): ReactNode {
  const valores: string[] = [];
  const marcado = rawText.replace(PATRON_DE_COMODIN, (token) => {
    // El valor también pasa por el spintax: un método de pago puede traer
    // {uno|otro} dentro, y sin esto saldrían las llaves a la vista.
    valores.push(
      resolvePreviewSpintax(
        applyPreviewPrices(token, priceSoles, comboPrice, basicoPrice, context),
        roll,
        stepIdx
      )
    );
    return `${MARCA_ABRE}${valores.length - 1}${MARCA_CIERRA}`;
  });
  const resuelto = resolvePreviewSpintax(
    applyPreviewPrices(marcado, priceSoles, comboPrice, basicoPrice, context),
    roll,
    stepIdx
  );
  if (valores.length === 0) return renderWa(resuelto);
  const partes = resuelto.split(
    new RegExp(`${MARCA_ABRE}(\\d+)${MARCA_CIERRA}`)
  );
  const fragments: ReactNode[] = [];
  partes.forEach((parte, indice) => {
    // split con grupo captura devuelve [texto, número, texto, número, …]: los
    // impares son el índice del comodín que iba en ese hueco.
    if (indice % 2 === 1) {
      const valor = valores[Number(parte)] ?? "";
      if (!valor) return;
      fragments.push(
        <span
          key={indice}
          title="Valor generado por comodín"
          className="rounded border border-sky-300 bg-sky-100 px-0.5 font-semibold text-sky-900"
        >
          {renderWa(valor)}
        </span>
      );
      return;
    }
    if (parte) fragments.push(<span key={indice}>{renderWa(parte)}</span>);
  });
  return fragments;
}

function placeholderMatchAtCursor(text: string, cursor: number) {
  const before = text.slice(0, cursor);
  return before.match(/\{\{\s*([A-Za-z0-9_]*)$/);
}

/**
 * Altura (dentro del textarea) del BORDE INFERIOR del renglón donde está el
 * cursor.
 *
 * Contar los saltos de línea no basta: un párrafo largo se parte solo al
 * llegar al borde y ocupa varios renglones, así que el cursor queda más abajo
 * de lo calculado y el desplegable acababa tapando lo que se escribía.
 *
 * Se mide de verdad con un clon invisible del campo: mismas fuentes, mismo
 * ancho y mismo ajuste de línea. Se le mete el texto hasta el cursor, se marca
 * la posición y se lee su altura.
 */
function bajoDelRenglonDelCursor(
  campo: HTMLTextAreaElement,
  cursor: number
): number {
  const estilo = window.getComputedStyle(campo);
  const altoLinea =
    parseFloat(estilo.lineHeight) || parseFloat(estilo.fontSize) * 1.4 || 20;
  const clon = document.createElement("div");
  try {
    for (const prop of [
      "paddingTop",
      "paddingRight",
      "paddingBottom",
      "paddingLeft",
      "fontFamily",
      "fontSize",
      "fontWeight",
      "fontStyle",
      "lineHeight",
      "letterSpacing",
      "textIndent",
      "textTransform",
    ] as const) {
      clon.style[prop] = estilo[prop];
    }
    // EL ANCHO SE MIDE, NO SE COPIA.
    //
    // Aquí estaba el fallo. Se copiaba el `width` del CSS, que con
    // box-sizing:border-box incluye los bordes Y el hueco de la barra de
    // desplazamiento. El clon salía más ancho que el texto real, así que cabían
    // más palabras por renglón, contaba MENOS renglones, y el desplegable
    // aparecía más arriba de donde estaba el cursor — encima de lo que se
    // escribía. Solo pasaba en cajones largos, que son los que tienen barra.
    //
    // clientWidth es el ancho de dentro sin bordes ni barra; quitándole los
    // rellenos queda el ancho exacto donde se parte el texto.
    const relleno =
      (parseFloat(estilo.paddingLeft) || 0) +
      (parseFloat(estilo.paddingRight) || 0);
    clon.style.boxSizing = "content-box";
    clon.style.width = `${Math.max(0, campo.clientWidth - relleno)}px`;
    clon.style.position = "absolute";
    clon.style.top = "-9999px";
    clon.style.left = "-9999px";
    clon.style.visibility = "hidden";
    clon.style.whiteSpace = "pre-wrap";
    clon.style.wordWrap = "break-word";
    clon.style.overflowWrap = "break-word";
    clon.style.height = "auto";
    clon.textContent = campo.value.slice(0, cursor);
    const marca = document.createElement("span");
    marca.textContent = "";
    clon.appendChild(marca);
    document.body.appendChild(clon);
    const alto = marca.offsetTop + altoLinea;
    document.body.removeChild(clon);
    return alto;
  } catch {
    if (clon.parentNode) clon.parentNode.removeChild(clon);
    // Si algo falla, se cae al cálculo por saltos de línea de siempre.
    const relleno = parseFloat(estilo.paddingTop) || 0;
    const lineas = campo.value.slice(0, cursor).split("\n").length - 1;
    return relleno + (lineas + 1) * altoLinea;
  }
}

function GlobalPlaceholderAutocomplete() {
  const placeholderOptions = useContext(PlaceholderOptionsContext);
  const [state, setState] = useState<{
    target: HTMLInputElement | HTMLTextAreaElement;
    query: string;
    x: number;
    y: number;
    /** Alto máximo, para que quepa debajo del renglón sin taparlo. */
    alto: number;
  } | null>(null);

  // Antes cortaba a 8 y escondia comodines validos sin avisar: con la lista ya
  // filtrada por modalidad, 8 se quedaban cortos y el usuario no sabia que
  // habia mas. El desplegable ya tiene scroll propio (max-h-64 + overflow),
  // asi que mostrarlos todos no desborda la pantalla. El tope alto solo evita
  // una lista absurda si algun dia se crean cientos de comodines propios.
  const filtered =
    state === null
      ? []
      : placeholderOptions
          .filter((option) =>
            option.token
              .replace(/[{}]/g, "")
              .toLowerCase()
              .includes(state.query.toLowerCase())
          )
          // TODOS (24/10/2026): con los «ocultos» y las cuentas por método ya pasan de 60, y el tope
          // los cortaba sin avisar. La lista tiene su propia barra para bajar.
          .slice(0, 400);

  useEffect(() => {
    const isTextTarget = (
      target: EventTarget | null
    ): target is HTMLInputElement | HTMLTextAreaElement => {
      if (
        target instanceof HTMLTextAreaElement ||
        target instanceof HTMLInputElement
      ) {
        if (target instanceof HTMLInputElement) {
          const type = (target.type || "text").toLowerCase();
          if (!["text", "search", "email", "url", "tel"].includes(type)) {
            return false;
          }
        }
        return !target.readOnly && !target.disabled;
      }
      return false;
    };

    const update = (target: EventTarget | null) => {
      if (!isTextTarget(target)) {
        setState(null);
        return;
      }
      const cursor = target.selectionStart ?? target.value.length;
      const match = placeholderMatchAtCursor(target.value, cursor);
      if (!match) {
        setState(null);
        return;
      }
      // El desplegable se coloca DEBAJO DEL RENGLON que se esta escribiendo.
      // Antes se anclaba al borde superior del campo, asi que en un cajon de
      // varias lineas tapaba justo lo que el usuario estaba escribiendo.
      const rect = target.getBoundingClientRect();
      const ALTO_MENU = 264; // max-h-64 + margen
      let baseRenglon = rect.bottom; // los inputs de una linea van bajo el campo

      if (target instanceof HTMLTextAreaElement) {
        const yDentro = bajoDelRenglonDelCursor(target, cursor);
        // Acotado al alto visible del campo: si el cursor esta fuera de vista
        // el menu no se va a la otra punta de la pantalla.
        baseRenglon =
          rect.top + Math.min(Math.max(yDentro - target.scrollTop, 0), rect.height);
      }

      // SIEMPRE debajo del renglón, nunca encima.
      //
      // Antes, si no cabía debajo, se volteaba arriba — y ahí tapaba justo la
      // línea que se estaba escribiendo. No se veía lo que uno escribía, que es
      // lo único que no puede pasar en un cuadro de texto.
      //
      // Ahora se queda abajo y, si el espacio es poco, se encoge. Ya tiene
      // scroll propio, así que corto se sigue usando; tapando, no.
      // AQUÍ ESTABA EL «EN UNOS CAJONES SALEN UNOS Y EN OTROS OTROS».
      //
      // La lista es LA MISMA en todos los cuadros del editor. Lo que cambiaba
      // era cuánto se veía de ella: el menú se encogía hasta 120 px cuando el
      // cuadro quedaba cerca del borde de abajo, y en 120 px entran dos o tres.
      // Con scroll interno y sin nada que lo indique, eso se lee como «en este
      // cajón hay menos comodines», que es justo lo que no es.
      //
      // El suelo sube a 180, que ya deja ver cuatro, y encima el menú dice
      // cuántos hay en total. Se queda DEBAJO del renglón igual que antes: tapar
      // lo que uno está escribiendo sigue siendo lo único que no puede pasar.
      const y = baseRenglon + 14;
      const alto = Math.max(
        180,
        Math.min(ALTO_MENU, window.innerHeight - y - 12)
      );

      setState({
        target,
        query: match[1] ?? "",
        x: rect.left + window.scrollX + 8,
        y: y + window.scrollY,
        alto,
      });
    };

    const onInput = (event: Event) => update(event.target);
    const onClick = (event: MouseEvent) => update(event.target);
    const onKeyUp = (event: KeyboardEvent) => {
      if (event.key === "Escape") return;
      update(event.target);
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setState(null);
      if (event.key === "Enter" && state && filtered.length > 0) {
        event.preventDefault();
        insertToken(filtered[0].token);
      }
    };
    const onFocusOut = () => {
      window.setTimeout(() => setState(null), 120);
    };

    document.addEventListener("input", onInput, true);
    document.addEventListener("click", onClick, true);
    document.addEventListener("keyup", onKeyUp, true);
    document.addEventListener("keydown", onKeyDown, true);
    document.addEventListener("focusout", onFocusOut, true);
    return () => {
      document.removeEventListener("input", onInput, true);
      document.removeEventListener("click", onClick, true);
      document.removeEventListener("keyup", onKeyUp, true);
      document.removeEventListener("keydown", onKeyDown, true);
      document.removeEventListener("focusout", onFocusOut, true);
    };
  }, [filtered, state]);

  function insertToken(token: string) {
    if (!state) return;
    const target = state.target;
    const cursor = target.selectionStart ?? target.value.length;
    const match = placeholderMatchAtCursor(target.value, cursor);
    const start = match ? cursor - match[0].length : cursor;
    const next = target.value.slice(0, start) + token + target.value.slice(cursor);

    // setRangeText cambia el valor visible, pero en un input controlado React
    // puede no detectar el cambio y el comodin termina sin llegar al guardado.
    // Usamos el setter nativo para que el evento input actualice el estado del
    // editor, igual para cualquier comodin elegido desde este selector global.
    const prototype =
      target instanceof HTMLTextAreaElement
        ? HTMLTextAreaElement.prototype
        : HTMLInputElement.prototype;
    const valueSetter = Object.getOwnPropertyDescriptor(prototype, "value")?.set;
    valueSetter?.call(target, next);
    target.dispatchEvent(new Event("input", { bubbles: true }));
    const position = start + token.length;
    target.setSelectionRange(position, position);
    target.focus();
    setState(null);
  }

  if (filtered.length === 0 || !state) return null;
  return (
    <div
      className="absolute z-[9999] w-[min(420px,calc(100vw-2rem))] overflow-auto rounded-md border border-emerald-200 bg-tarjeta p-1 text-xs shadow-xl"
      style={{ left: state.x, top: state.y, maxHeight: state.alto }}
    >
      {/* CUÁNTOS HAY, PEGADO ARRIBA.
          El menú tiene scroll propio y su alto depende del sitio que quede en
          la pantalla, así que en un cuadro de abajo se veían tres y parecía que
          ahí había tres. Diciendo el total se entiende que hay que deslizar, y
          de paso se ve si el filtro ya redujo la lista. */}
      <div className="sticky top-0 z-10 mb-1 rounded-sm bg-emerald-50 px-2 py-1 text-[10px] font-bold uppercase tracking-wide text-emerald-800">
        {filtered.length} comodín{filtered.length === 1 ? "" : "es"}
        {state.query ? ` con «${state.query}»` : ""}
        {filtered.length > 4 ? " · desliza para ver todos" : ""}
      </div>
      {filtered.map((option) => (
        <button
          key={option.token}
          type="button"
          onMouseDown={(e) => {
            e.preventDefault();
            insertToken(option.token);
          }}
          className="block w-full rounded px-2 py-1.5 text-left hover:bg-emerald-50"
        >
          <span className="font-mono font-semibold text-emerald-700">
            {option.token}
          </span>
          <span className="ml-2 font-medium text-neutral-700">
            {option.label}
          </span>
          {option.description && (
            <span className="block truncate text-neutral-500">
              {option.description}
            </span>
          )}
        </button>
      ))}
    </div>
  );
}

function TextVariantToolbar({
  children,
  onEmoji,
}: {
  children?: ReactNode;
  onEmoji: (emoji: string) => void;
}) {
  return (
    <div className="mb-1 flex flex-wrap items-center justify-end gap-2">
      {children}
      <EmojiPicker onPick={onEmoji} />
    </div>
  );
}

// Elige una variante válida (ignora vacías y placeholders <<...>>). roll=0 usa
// la primera; roll>0 elige una pseudo-aleatoria estable según roll + posición.
function pickVariantText(texts: string[], roll: number, stepIdx: number): string {
  const valid = texts.filter(
    (t) => t && t.trim() && !(t.includes("<<") && t.includes(">>"))
  );
  if (valid.length === 0) return "";
  if (roll === 0) return valid[0];
  const r = Math.abs(Math.sin(roll * 9301 + stepIdx * 49297));
  return valid[Math.floor(r * valid.length) % valid.length];
}

function resolvePreviewSpintax(text: string, roll: number, stepIdx: number): string {
  if (!text || !text.includes("|")) return text;
  const protectedPlaceholders: string[] = [];
  const protectedText = text.replace(/\{\{[^{}\n]+\}\}/g, (match) => {
    const token = `__WF_PREVIEW_PLACEHOLDER_${protectedPlaceholders.length}__`;
    protectedPlaceholders.push(match);
    return token;
  });
  let groupIndex = 0;
  const resolved = protectedText.replace(/\{([^{}\n]*\|[^{}\n]*)\}/g, (match, body: string) => {
    const options = body.split("|");
    if (options.length < 2) return match;
    if (roll === 0) {
      groupIndex += 1;
      return options[0] ?? "";
    }
    const r = Math.abs(Math.sin(roll * 15485863 + stepIdx * 32452843 + groupIndex * 49979687));
    groupIndex += 1;
    return options[Math.floor(r * options.length) % options.length] ?? "";
  });
  return resolved.replace(
    /__WF_PREVIEW_PLACEHOLDER_(\d+)__/g,
    (match, index: string) => protectedPlaceholders[Number(index)] ?? match
  );
}

/** Resuelve los comodines de precio para la vista previa, igual que el bot en
 *  runtime: {price}/{precio} (precio de ESTA opción) y, en el order bump,
 *  {{precio_1}} (combo), {{precio_2}} (básico) y {{precio_extra}} (diferencia).
 *  Muestra el precio NORMAL, como el resto del preview. */
function applyPreviewPrices(
  text: string,
  priceSoles?: number,
  comboPrice?: number,
  basicoPrice?: number,
  context?: PreviewContext
): string {
  let out = text;
  // EN UNA FICHA DEL TABLERO, sus productos primero: la misma función que el bot.
  if (context?.productosDeLaFicha?.productos.length)
    out = comodinesDeLaFichaEnTexto(out, context.productosDeLaFicha.productos, context.productosDeLaFicha.pais);
  // {{METODO_DE_PAGO_1/2/3}}: expande el texto POR PAÍS PRIMERO, para que sus
  // comodines internos ({{NOMBRE_RECEPTOR}}, {{PRECIO_SEGUN_ELECCION}}…) los
  // resuelva el resto de esta función, igual que en vivo.
  out = out
    .replace(
      /\{\{\s*(metodo_de_pago_1|metodo_pago_1)\s*\}\}/gi, literal(context?.metodoPago1 ?? ""))
    .replace(
      /\{\{\s*(metodo_de_pago_2|metodo_pago_2)\s*\}\}/gi, literal(context?.metodoPago2 ?? ""))
    .replace(
      /\{\{\s*(metodo_de_pago_3|metodo_pago_3)\s*\}\}/gi, literal(context?.metodoPago3 ?? ""))
    .replace(
      /\{\{\s*(metodo_de_pago_principal|metodo_pago_principal|metodo_de_pago_prioritario)\s*\}\}/gi, literal(context?.metodoPagoPrincipal ?? ""));
  const currency = context?.currencySymbol ?? "S/.";
  const option1Name = context?.option1Name?.trim() || "Opcion 1";
  const option2Name = context?.option2Name?.trim() || "Opcion 2";
  const productName = context?.productName?.trim() || "Producto principal";
  const product2Name = context?.product2Name?.trim() || "Producto 2";
  // Sin nombre puesto se deja el hueco, igual que hace el bot: es preferible
  // ver el vacío en la vista previa a que aparezca un texto inventado.
  const productoUpsellName = context?.productoUpsellName?.trim() ?? "";
  // Los tres papeles ya vienen resueltos por la modalidad. El respaldo es el
  // reparto de siempre —full = principal, base = segundo— para que un visor sin
  // contexto (los hay) siga enseñando algo razonable.
  const nombreBase = context?.nombreBase?.trim() || product2Name;
  const nombreFull = context?.nombreFull?.trim() || productName;
  const nombreComplementario = context?.nombreComplementario?.trim() ?? "";
  // El cajón de entrega manda el suyo. Sin él, el hueco explicado: es el único
  // comodín del editor que no se puede resolver mirando la configuración.
  const nombreEntregado =
    context?.nombreEntregado?.trim() || "[el producto de esta entrega]";
  const customerName = context?.customerName?.trim() || "Cliente";
  const paymentRecipient =
    context?.paymentRecipientName?.trim() ||
    "[Nombre del receptor sin configurar]";
  const currencyCode = context?.currencyCode?.trim() || "PEN";
  const countryCode = context?.countryCode ?? "PE";
  const resolvedPriceSoles =
    typeof priceSoles === "number" ? priceSoles : context?.priceSoles;
  const marketPrice = context?.marketPrice;
  const marketPriceFull = context?.marketPriceFull;
  const marketPriceUpsell = context?.marketPriceUpsell;
  const estiloBase = context?.estiloBase;
  const estiloFull = context?.estiloFull;
  const estiloUpsell = context?.estiloUpsell;
  const upsellPrice = context?.upsellPrice;
  const resolvedComboPrice =
    typeof comboPrice === "number" ? comboPrice : context?.comboPrice;
  const resolvedBasicoPrice =
    typeof basicoPrice === "number" ? basicoPrice : context?.basicoPrice;
  const resolvedUpsellPrice = context?.upsellPrice;
  if (typeof resolvedPriceSoles === "number") {
    // Colapso inteligente (igual que el runtime): "S/. {precio} soles" escrito a
    // mano se reemplaza ENTERO por el precio con contexto en mayúsculas, para no
    // duplicar el símbolo/moneda cuando {precio} ya trae contexto.
    out = out.replace(
      /(?:S\/\.?|US?\$|\$|Bs\.?|Q|₡)\s*\{\{?\s*(?:precio|price)\s*\}?\}\s*(?:sol(?:es)?|d[oó]lares?|pesos?|bol[ií]vares?|quetzales?|colones?)/gi, literal(formatPreviewCurrencyAmount(
        resolvedPriceSoles,
        countryCode,
        currencyCode,
        currency,
        "upper"
      )));
    out = out.replace(
      /\{\{\s*(precio_completo_mayusculas|precio_full_mayusculas|full_price_upper)\s*\}\}/gi, literal(formatPreviewCurrencyAmount(
        resolvedPriceSoles,
        countryCode,
        currencyCode,
        currency,
        "upper"
      )));
    out = out.replace(
      /\{\{\s*(precio_completo_minusculas|precio_full_minusculas|full_price_lower)\s*\}\}/gi, literal(formatPreviewCurrencyAmount(
        resolvedPriceSoles,
        countryCode,
        currencyCode,
        currency,
        "lower"
      )));
    out = out.replace(
      // Sin `precio_full`: ese nombre es ahora el precio del producto FULL y se
    // resuelve más abajo. Aquí ganaba esta línea y la vista previa enseñaba el
    // precio del base — el mensaje real salía bien y el visor mentía.
    /\{\{\s*(precio_completo|precio_label|price_label|full_price)\s*\}\}/gi, literal(formatPreviewCurrencyAmount(
        resolvedPriceSoles,
        countryCode,
        currencyCode,
        currency
      )));
    // {precio}/{price} con CONTEXTO en mayúsculas ("S/. 10 SOLES" / "$ 3 DÓLARES"),
    // igual que el runtime.
    const precioUpper = formatPreviewCurrencyAmount(
      resolvedPriceSoles,
      countryCode,
      currencyCode,
      currency,
      "upper"
    );
    out = out
      .replace(/\{price\}/gi, literal(precioUpper))
      .replace(/\{precio\}/gi, literal(precioUpper));
    // {{PRECIO_SEGUN_ELECCION}}: en runtime es el precio de la opción elegida; en
    // la preview mostramos el básico (o el base) como representativo, con contexto.
    const precioSegunEleccionPreview =
      typeof resolvedBasicoPrice === "number"
        ? resolvedBasicoPrice
        : resolvedPriceSoles;
    out = out.replace(
      /\{\{\s*(precio_segun_eleccion|precio_eleccion|precio_elegido|precio_opcion|precio_segun_opcion)\s*\}\}/gi, literal(formatPreviewCurrencyAmount(
        precioSegunEleccionPreview,
        countryCode,
        currencyCode,
        currency,
        "upper"
      )));
  }
  // UN COMODÍN POR PRECIO, CON EL ESTILO QUE DIGA SU BOTÓN.
  //
  // Van los primeros de todos: "precio_base" contiene "precio", y cualquiera
  // de los genéricos de abajo se comería su principio dejando "_base" suelto.
  // Misma lista y mismo orden que en el bot (renderOrderBumpTemplate).
  const conEstiloPreview = (
    valor: number | undefined,
    estilo: "upper" | "lower" | "off" | undefined,
    cual: string
  ): string =>
    typeof valor === "number" && Number.isFinite(valor) && valor > 0
      ? formatPreviewCurrencyAmount(
          valor,
          countryCode,
          currencyCode,
          currency,
          estilo ?? "upper"
        )
      : `[Precio ${cual} sin configurar]`;
  out = out
    .replace(
      /\{\{\s*(precio_full|precio_combo)\s*\}\}/gi,
      literal(conEstiloPreview(resolvedComboPrice, estiloFull, "del full"))
    )
    .replace(
      /\{\{\s*(precio_base|precio_basico)\s*\}\}/gi,
      literal(conEstiloPreview(resolvedBasicoPrice, estiloBase, "del base"))
    )
    .replace(
      /\{\{\s*(precio_upsell|precio_upsell_solo|precio_3|precio3)\s*\}\}/gi,
      literal(conEstiloPreview(upsellPrice, estiloUpsell, "del extra"))
    )
    .replace(
      // `precio_complementario` va con estos: es el precio del producto que se
      // suma al básico, o sea lo mismo que la diferencia. Empatado con
      // {{PRODUCTO_COMPLEMENTARIO}}, que antes no tenía precio con su nombre.
      /\{\{\s*(precio_complementario|precio_diferencia|precio_extra_completo)\s*\}\}/gi,
      literal(
        conEstiloPreview(
          typeof resolvedComboPrice === "number" &&
            typeof resolvedBasicoPrice === "number"
            ? Math.round((resolvedComboPrice - resolvedBasicoPrice) * 100) / 100
            : undefined,
          estiloFull,
          "de la diferencia"
        )
      )
    )
    .replace(
      /\{\{\s*(precio_antes_full|precio_anterior_full)\s*\}\}/gi,
      literal(conEstiloPreview(marketPriceFull, estiloFull, "anterior del full"))
    )
    .replace(
      /\{\{\s*(precio_antes_base|precio_anterior_base)\s*\}\}/gi,
      literal(conEstiloPreview(marketPrice, estiloBase, "anterior del base"))
    )
    .replace(
      /\{\{\s*(precio_antes_upsell|precio_anterior_upsell)\s*\}\}/gi,
      literal(
        conEstiloPreview(marketPriceUpsell, estiloUpsell, "anterior del extra")
      )
    );
  // Los tres «antes» por producto van ANTES que el genérico: si no, el de
  // {{PRECIO_MERCADO}} se comería su principio y dejaría "_FULL" a la vista.
  // Sin valor se avisa en el editor —igual que el genérico— aunque en el
  // mensaje real no salga nada: aquí el aviso es para ti, no para el cliente.
  const previewMercado = (valor: number | undefined, cual: string): string =>
    typeof valor === "number" && Number.isFinite(valor) && valor > 0
      ? formatPreviewCurrencyAmount(valor, countryCode, currencyCode, currency)
      : `[Precio anterior ${cual} sin configurar]`;
  out = out.replace(
    /\{\{\s*(precio_mercado_basico|precio_anterior_basico|market_price_basico)\s*\}\}/gi,
    literal(previewMercado(marketPrice, "del básico"))
  );
  out = out.replace(
    /\{\{\s*(precio_mercado_full|precio_mercado_combo|precio_anterior_full|market_price_full)\s*\}\}/gi,
    literal(previewMercado(marketPriceFull, "del full"))
  );
  out = out.replace(
    /\{\{\s*(precio_mercado_upsell|precio_anterior_upsell|market_price_upsell)\s*\}\}/gi,
    literal(previewMercado(marketPriceUpsell, "del extra"))
  );
  out = out.replace(
    /\{\{\s*(precio_mercado|precio_anterior|precio_referencial|market_price|previous_price)\s*\}\}/gi, literal(typeof marketPrice === "number" && Number.isFinite(marketPrice) && marketPrice > 0
      ? formatPreviewCurrencyAmount(marketPrice, countryCode, currencyCode, currency)
      : "[Precio anterior sin configurar]"));
  out = out
    .replace(
      /\{\{\s*(metodos_de_pago_por_pais|metodos_pago_pais|payment_methods_by_country)\s*\}\}/gi, literal(context?.paymentMethodsText?.trim() ||
        "[Métodos de pago sin configurar para este país]"))
    .replace(
      /\{\{\s*(lista_metodos_por_pais|lista_metodos_pago_por_pais|payment_methods_list_by_country)\s*\}\}/gi, literal(context?.paymentMethodsList?.trim() ||
        "[Lista de métodos sin configurar para este país]"))
    .replace(/\{\{\s*(currency|moneda_iso|codigo_moneda|currency_code)\s*\}\}/gi, literal(currencyCode))
    .replace(/\{\{\s*(moneda|simbolo|sÃ­mbolo|símbolo)\s*\}\}/gi, literal(currency))
    .replace(/\{\{\s*(nombre|nombre_whatsapp|name|customer_name)\s*\}\}/gi, literal(customerName))
    .replace(
      /\{\{\s*(nombre_receptor|receptor_pago|payment_recipient|recipient_name)\s*\}\}/gi, literal(paymentRecipient))
    // Tu nombre completo, el de leer. Es OTRO comodín: el de arriba valida el
    // comprobante y éste no valida nada. Ver `nombre_completo`.
    .replace(
      /\{\{\s*(nombre_completo|mi_nombre|nombre_vendedor|full_name)\s*\}\}/gi,
      literal(context?.nombreCompleto?.trim() || "[Tu nombre sin configurar]"))
    // Igual que en vivo: va DESPUÉS de los cajones de pago, que se expanden al
    // principio de esta función, así que también se resuelve cuando el número
    // se escribe dentro de un cajón.
    // LA CUENTA DE UN MÉTODO NOMBRADO: {{CUENTA_BILLETERA}}, {{CUENTA_BANCO}}…
    // Va ANTES del genérico, y resuelve igual que en vivo: por el método que se
    // nombra, no por el elegido. Hay burbujas que listan las dos cuentas juntas.
    .replace(
      /\{\{\s*cuenta_([a-z0-9_]+)\s*\}\}/gi,
      (_entero: string, metodo: string) => {
        const tabla = context?.cuentasPorMetodo ?? {};
        const clave = metodo.trim().toLowerCase();
        const suya = Object.entries(tabla).find(
          ([k]) => String(k).trim().toLowerCase() === clave
        )?.[1];
        return (
          String(suya ?? "").trim() ||
          context?.numeroDeCuenta?.trim() ||
          `[Cuenta de ${metodo} sin configurar]`
        );
      })
    .replace(
      /\{\{\s*(numero_de_cuenta|numero_cuenta|cuenta|account_number)\s*\}\}/gi,
      literal(context?.numeroDeCuenta?.trim() || "[Número de cuenta sin configurar]"))
    // LOS QUE SOLO EXISTEN EN LA CONVERSACIÓN.
    //
    // Cuál opción eligió, cuánto lleva pagado, cuánto le falta, de qué anuncio
    // vino: nada de eso existe todavía cuando estás escribiendo la burbuja. El
    // visor no puede saberlo, pero enseñar la llave cruda es peor — parece que
    // el comodín está roto. Se enseña QUÉ va a salir ahí.
    .replace(
      /\{\{\s*(opcion_elegida|opcion_seleccionada)\s*\}\}/gi,
      literal("[la opción que elija]")
    )
    .replace(
      /\{\{\s*(precio_opcion_elegida|precio_elegido|precio_seleccionado)\s*\}\}/gi,
      literal("[el precio de la opción que elija]")
    )
    .replace(
      /\{\{\s*(monto_abonado|pago_acumulado)\s*\}\}/gi,
      literal("[lo que ya pagó]")
    )
    .replace(
      /\{\{\s*(monto_faltante|saldo_faltante|diferencia_pendiente)\s*\}\}/gi,
      literal("[lo que le falta pagar]")
    )
    .replace(
      /\{\{\s*enlace_anuncio\s*\}\}/gi,
      literal("[el enlace de su anuncio]")
    )
    // EL DE LA ENTREGA: EL CAJÓN SABE DE QUIÉN ES.
    //
    // El comodín apunta a lo que el bot está entregando, y eso solo se sabe en
    // la conversación real. Pero el sitio donde se escribe no es ambiguo: en la
    // ficha de un producto la entrega es de ese producto, y en el cajón del Full
    // es de quien juegue de Full. Cada cajón de entrega manda el suyo.
    //
    // Donde de verdad no se puede saber —un cajón que no es de entrega— se
    // pinta el hueco explicado, como ya se hace con el monto abonado. Enseñar
    // ahí el nombre de una de las entregas haría creer que sale en todas.
    .replace(
      /\{\{\s*(producto_entregado|producto_de_la_entrega|lo_que_compro)\s*\}\}/gi,
      literal(nombreEntregado)
    )
    // El del TERCER producto va ANTES: "producto_upsell" empieza por
    // "producto", así que si se sustituyera después el de abajo ya se habría
    // comido su principio y quedaría un "_upsell" suelto en el mensaje.
    .replace(
      /\{\{\s*(producto_upsell|producto3|producto_3)\s*\}\}/gi, literal(productoUpsellName))
    // TODOS los nombres del SEGUNDO producto, y antes que el genérico.
    //
    // El visor sabía resolver dos: {{producto}} y {{producto2}}. Al renombrar
    // el segundo a {{PRODUCTO_SECUNDARIO}}, el visor se quedó sin saber qué
    // era y lo enseñaba crudo — 125 textos mostrando la llave en la vista
    // previa mientras al cliente le llegaba bien. Esta lista es la MISMA que
    // la del motor (applyProductName en config.ts); si una crece, la otra
    // también, y la prueba de comodines lo vigila.
    // El COMPLEMENTO, solo de Order Bump. Fuera de ahí no hay tercer producto
    // que sumar, así que queda en blanco — igual que hace el bot.
    .replace(
      /\{\{\s*(producto_complementario|producto_complemento|complemento)\s*\}\}/gi,
      literal(nombreComplementario)
    )
    // La BASE y el FULL, ya resueltos por la modalidad (ver PreviewContext).
    .replace(
      /\{\{\s*(producto_base|producto_basico)\s*\}\}/gi,
      literal(nombreBase)
    )
    .replace(/\{\{\s*producto_full\s*\}\}/gi, literal(nombreFull))
    // Los de siempre, intactos: hay 125 textos escritos con ellos.
    .replace(
      /\{\{\s*(producto_secundario|producto2|product2)\s*\}\}/gi,
      literal(product2Name)
    )
    .replace(/\{\{\s*(producto|product)\s*\}\}/gi, literal(productName))
    .replace(
      /\{\{\s*(opcion_1|opcion1|option_1|option1|combo_name|producto_1|producto1|product_1|product1)\s*\}\}/gi, literal(option1Name))
    .replace(
      /\{\{\s*(opcion_2|opcion2|option_2|option2|basico_name|producto_2|product_2)\s*\}\}/gi, literal(option2Name));
  if (typeof resolvedComboPrice === "number") {
    out = out
      .replace(
        /\{\{\s*(precio_1_mayusculas|precio1_mayusculas)\s*\}\}/gi, literal(formatPreviewCurrencyAmount(resolvedComboPrice, countryCode, currencyCode, currency, "upper")))
      .replace(
        /\{\{\s*(precio_1_minusculas|precio1_minusculas)\s*\}\}/gi, literal(formatPreviewCurrencyAmount(resolvedComboPrice, countryCode, currencyCode, currency, "lower")))
      .replace(
        /\{\{\s*(precio_1_completo|precio1_completo|price_1_label|combo_price_label)\s*\}\}/gi, literal(formatPreviewCurrencyAmount(
          resolvedComboPrice,
          countryCode,
          currencyCode,
          currency
        )))
      .replace(
        /\{\{\s*(precio_1|precio1|price_1|price1|combo_price)\s*\}\}/gi, literal(String(resolvedComboPrice)));
  }
  if (typeof resolvedBasicoPrice === "number") {
    out = out
      .replace(
        /\{\{\s*(precio_2_mayusculas|precio2_mayusculas)\s*\}\}/gi, literal(formatPreviewCurrencyAmount(resolvedBasicoPrice, countryCode, currencyCode, currency, "upper")))
      .replace(
        /\{\{\s*(precio_2_minusculas|precio2_minusculas)\s*\}\}/gi, literal(formatPreviewCurrencyAmount(resolvedBasicoPrice, countryCode, currencyCode, currency, "lower")))
      .replace(
        /\{\{\s*(precio_2_completo|precio2_completo|price_2_label|basico_price_label)\s*\}\}/gi, literal(formatPreviewCurrencyAmount(
          resolvedBasicoPrice,
          countryCode,
          currencyCode,
          currency
        )))
      .replace(
        /\{\{\s*(precio_2|precio2|price_2|price2|basico_price)\s*\}\}/gi, literal(String(resolvedBasicoPrice)));
  }
  if (
    typeof resolvedComboPrice === "number" &&
    typeof resolvedBasicoPrice === "number"
  ) {
    const extra = Math.round((resolvedComboPrice - resolvedBasicoPrice) * 100) / 100;
    out = out
      .replace(
        /\{\{\s*(precio_extra_mayusculas|precio_adicional_mayusculas|precio_diferencia_mayusculas)\s*\}\}/gi, literal(formatPreviewCurrencyAmount(extra, countryCode, currencyCode, currency, "upper")))
      .replace(
        /\{\{\s*(precio_extra_minusculas|precio_adicional_minusculas|precio_diferencia_minusculas)\s*\}\}/gi, literal(formatPreviewCurrencyAmount(extra, countryCode, currencyCode, currency, "lower")))
      .replace(
        /\{\{\s*(precio_extra_completo|precio_adicional_completo|precio_diferencia_completo|diferencia_completa|extra_label)\s*\}\}/gi, literal(formatPreviewCurrencyAmount(extra, countryCode, currencyCode, currency)))
      .replace(
        /\{\{\s*(precio_extra|precio_adicional|precio_diferencia|diferencia|extra)\s*\}\}/gi, literal(String(extra)));
  }
  // El 3er producto. Las cuatro formas, y la escueta LA ULTIMA: si fuera
  // antes, "precio_upsell" se comeria el principio de "precio_upsell_completo"
  // y esa forma no saldria nunca.
  if (typeof resolvedUpsellPrice === "number") {
    out = out
      .replace(
        /\{\{\s*(precio_upsell_mayusculas|precio_3_mayusculas|precio3_mayusculas)\s*\}\}/gi, literal(formatPreviewCurrencyAmount(resolvedUpsellPrice, countryCode, currencyCode, currency, "upper")))
      .replace(
        /\{\{\s*(precio_upsell_minusculas|precio_3_minusculas|precio3_minusculas)\s*\}\}/gi, literal(formatPreviewCurrencyAmount(resolvedUpsellPrice, countryCode, currencyCode, currency, "lower")))
      .replace(
        /\{\{\s*(precio_upsell_completo|precio_3_completo|precio3_completo|upsell_price_label)\s*\}\}/gi, literal(formatPreviewCurrencyAmount(resolvedUpsellPrice, countryCode, currencyCode, currency)))
      .replace(
        /\{\{\s*(precio_upsell|precio_3|precio3|price_upsell|upsell_price)\s*\}\}/gi, literal(String(resolvedUpsellPrice)));
  }
  for (const item of context?.customPlaceholders ?? []) {
    const key = normalizePlaceholderKey(item.key ?? "");
    const value = item.value ?? "";
    if (!key || !value) continue;
    out = out.replace(
      new RegExp(`\\{\\{\\s*${key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s*\\}\\}`, "gi"), literal(value));
  }
  return out;
}

/**
 * LOS BOTONES DE UNA BURBUJA, PINTADOS COMO LOS PINTA WHATSAPP.
 *
 * POR QUÉ HACÍA FALTA. El editor deja ponerle botones a una burbuja, pero la
 * vista previa no los dibujaba: se escribían a ciegas y solo se veían viviendo
 * una conversación. Y lo que se descarta —el cuarto botón, la etiqueta larga— se
 * descartaba EN SILENCIO, así que ni entonces quedaba claro por qué faltaba uno.
 *
 * LAS MISMAS REGLAS QUE EL MOTOR, a propósito. Están copiadas de donde se envían
 * de verdad (`sendResponseStep`, en engine.ts):
 *
 *   · hacen falta id Y etiqueta; sin una de las dos, el botón no sale
 *   · como mucho TRES; del cuarto en adelante no se mandan
 *   · la etiqueta se corta a 20 caracteres, que es el límite de WhatsApp
 *
 * Si alguien cambia esas reglas en el motor y no aquí, la previa empieza a
 * mentir. Hay una prueba que compara los dos sitios.
 *
 * DENTRO O FUERA DE LA BURBUJA, SEGÚN EL TIPO. En texto, imagen y video los
 * botones viajan DENTRO del mismo mensaje. En audio y documento no se puede
 * —no hay cuerpo donde colgarlos—, así que el motor manda una burbuja aparte
 * con un texto fijo. Se dibuja igual de distinto, o la previa engañaría.
 */
function BotonesDeLaBurbuja({ step }: { step: EditorStep }) {
  const todos = step.buttons ?? [];
  const visibles = todos
    .filter((b) => (b.id ?? "").trim() && (b.label ?? "").trim())
    .slice(0, 3);
  const descartados = todos.length - visibles.length;
  if (visibles.length === 0 && descartados === 0) return null;
  const enBurbujaAparte = step.type === "audio" || step.type === "document";
  const lista = visibles.map((boton, i) => {
    const etiqueta = boton.label.trim();
    const cortada = etiqueta.slice(0, 20);
    return (
      <div
        key={boton.id || i}
        title={cortada !== etiqueta ? `WhatsApp corta a 20: «${etiqueta}»` : undefined}
        className="rounded-md border border-sky-200 bg-tarjeta px-2 py-1 text-center text-[12px] font-semibold text-sky-700"
      >
        {cortada}
        {cortada !== etiqueta && <span className="text-sky-400"> …</span>}
      </div>
    );
  });
  const aviso =
    descartados > 0 ? (
      <div className="mt-1 text-[10px] font-semibold leading-snug text-amber-700">
        {todos.length > 3
          ? `WhatsApp admite 3 botones: ${todos.length - 3} no se enviará(n).`
          : "Hay un botón sin texto: no se enviará."}
      </div>
    ) : null;
  if (enBurbujaAparte) {
    return (
      <div className="mt-1">
        {/* El MISMO verde que la burbuja de al lado, no otro inventado: es una
            burbuja más, la que manda el motor con su texto fijo. */}
        <div className="rounded-lg bg-[#d9fdd3] px-3 py-2 shadow-sm">
          <div className="text-[13px] leading-snug text-neutral-800">
            ¿Qué deseas hacer?
          </div>
          <div className="mt-1 space-y-1 border-t border-emerald-200 pt-1">{lista}</div>
        </div>
        <div className="mt-0.5 text-[10px] font-semibold text-neutral-500">
          En {step.type === "audio" ? "audio" : "documento"} los botones salen en
          una burbuja aparte, con este texto fijo.
        </div>
        {aviso}
      </div>
    );
  }
  return (
    <div>
      <div className="mt-1 space-y-1 border-t border-emerald-200 pt-1">{lista}</div>
      {aviso}
    </div>
  );
}

function ChatPreview({
  steps,
  priceSoles,
  comboPrice,
  basicoPrice,
  previewPriceOverride,
  previewComboPriceOverride,
  previewBasicoPriceOverride,
  previewContext,
  activeStepIndex,
  previewRolls,
  useScrollContainer,
  onSelectStep,
  onVaryAll,
  onEditStep,
  onDuplicateStep,
  onToggleStep,
  onRemoveStep,
  onPasteStep,
  onMoveStep,
  highlightPlaceholders = false,
  channelLabel = "WhatsApp",
  perBubbleVary = false,
  sinTopeDeAncho = false,
}: {
  steps: EditorStep[];
  priceSoles?: number;
  comboPrice?: number;
  basicoPrice?: number;
  /** Overrides exclusivos de preview para representar una etapa comercial. */
  previewPriceOverride?: number;
  previewComboPriceOverride?: number;
  previewBasicoPriceOverride?: number;
  previewContext?: PreviewContext;
  activeStepIndex?: number | null;
  previewRolls?: Record<number, number>;
  useScrollContainer?: boolean;
  onSelectStep?: (index: number) => void;
  onVaryAll?: () => void;
  onEditStep?: (index: number) => void;
  onDuplicateStep?: (index: number) => void;
  onToggleStep?: (index: number) => void;
  /** `sinPreguntar` lo usa CORTAR: ahí el operador no está borrando, está
   *  moviendo, y la burbuja ya quedó a salvo en el portapapeles. Preguntarle
   *  «¿eliminar?» en mitad de un cortar y pegar asusta sin motivo. */
  onRemoveStep?: (index: number, opciones?: { sinPreguntar?: boolean }) => void;
  onPasteStep?: (index: number, step: EditorStep) => void;
  onMoveStep?: (from: number, target: number, placement: "before" | "after") => void;
  /** En el visor integral, distingue los valores generados por comodines. */
  highlightPlaceholders?: boolean;
  channelLabel?: string;
  perBubbleVary?: boolean;
  /** El visor es un teléfono: se queda en ancho de teléfono aunque la página
   *  crezca. Solo la ventana de recorrido —que tiene su propio selector
   *  móvil/normal/ancho a la vista— lo desactiva, para no contradecir un
   *  control que el operador está pulsando. */
  sinTopeDeAncho?: boolean;
}) {
  const [roll, setRoll] = useState(0);
  const [bubbleRolls, setBubbleRolls] = useState<Record<number, number>>({});
  const [contextMenu, setContextMenu] = useState<{ index: number; x: number; y: number } | null>(null);
  /**
   * EL MODO SELECCIÓN — `null` = apagado.
   *
   * LO QUE PIDIÓ EL DUEÑO (17/09/2026): «yo quiero copiar más de 1 burbuja a la
   * vez; click derecho, seleccionar burbuja, automáticamente aparezca al lado un
   * check y en la que seleccioné ya esté activo, luego las demás con el check
   * vacío; una vez seleccionadas, click derecho en cualquiera y copiar».
   *
   * VIVE AQUÍ Y NO EN UN CONTEXTO GLOBAL, a diferencia del portapapeles: marcar
   * burbujas de dos secuencias distintas a la vez no significa nada —no se
   * pueden copiar juntas ni pegar en ningún sitio— y tenerlo global haría que al
   * abrir otra sección aparecieran checks marcados sin que nadie los tocara.
   */
  const [seleccion, setSeleccion] = useState<Set<number> | null>(null);
  const seleccionadas = seleccion ? [...seleccion].sort((a, b) => a - b) : [];
  /**
   * ESCAPE SALE DEL MODO SELECCIÓN, Y NO CIERRA LA VENTANA.
   *
   * EL CUIDADO QUE PIDIÓ, con sus palabras: «al presionar escape se sale del
   * pop up, entonces hay que tener cuidado». Tiene razón: la ventana escucha
   * Escape en `window` —ver `salir` en la ventana— y sin esto un solo golpe
   * habría hecho las dos cosas, perdiendo lo que estuviera editando.
   *
   * SE ESCUCHA EN FASE DE CAPTURA. Así corre ANTES que el de la ventana, y al
   * cortar la propagación aquel ni se entera. Es la misma idea que ya usa la
   * ventana con las ventanas de dentro —«Escape cierra de dentro hacia
   * fuera»—, aplicada un escalón más abajo y sin tocarla.
   *
   * Y SI HAY UN MENÚ ABIERTO, ESCAPE ES DEL MENÚ. Primero se cierra el menú y
   * el modo selección se queda: cerrar las dos cosas de un golpe es justo lo
   * que él pidió evitar.
   */
  useEffect(() => {
    if (seleccion === null) return;
    const alPulsar = (evento: KeyboardEvent) => {
      if (evento.key !== "Escape") return;
      if (contextMenu) return;
      evento.preventDefault();
      evento.stopPropagation();
      setSeleccion(null);
    };
    window.addEventListener("keydown", alPulsar, true);
    return () => window.removeEventListener("keydown", alPulsar, true);
  }, [seleccion, contextMenu]);
  const marcar = (index: number) => {
    setSeleccion((antes) => {
      const siguiente = new Set(antes ?? []);
      if (siguiente.has(index)) siguiente.delete(index);
      else siguiente.add(index);
      return siguiente;
    });
  };
  const [previewDrag, setPreviewDrag] = useState<{
    index: number;
    target: number;
    placement: "before" | "after";
  } | null>(null);
  const previewDragRef = useRef<{
    index: number;
    startX: number;
    startY: number;
    active: boolean;
  } | null>(null);
  const previewDropRef = useRef<{
    index: number;
    target: number;
    placement: "before" | "after";
  } | null>(null);
  const ignorePreviewClickRef = useRef(false);
  const [resolvedMediaKinds, setResolvedMediaKinds] = useState<
    Record<string, LinkMediaResolution>
  >({});
  const previewScrollRef = useRef<HTMLDivElement | null>(null);
  const inheritedPreviewContext = useContext(EditorPreviewContext);
  const bubbleClipboard = useContext(BubbleClipboardContext);
  const effectivePreviewContext: PreviewContext = {
    ...previewContext,
    // El selector de país del editor debe gobernar todas las vistas previas.
    // Los paneles antiguos todavía mandan su contexto base, por eso el contexto
    // heredado se aplica al final para mantener una sola moneda y precio visibles.
    ...inheritedPreviewContext,
    customPlaceholders:
      inheritedPreviewContext.customPlaceholders ??
      previewContext?.customPlaceholders ??
      [],
    // Y SI QUIEN LLAMA LO PIDE, SUS NOMBRES VUELVEN A MANDAR.
    //
    // Solo los NOMBRES, y solo los que traiga puestos: el país, la moneda y el receptor
    // siguen saliendo del heredado, que es lo que ese orden protege. Ver
    // `nombresDelLlamanteMandan` en `PreviewContext` para el caso que lo puso aquí.
    ...(previewContext?.nombresDelLlamanteMandan
      ? Object.fromEntries(
          (
            [
              "productName",
              "product2Name",
              "option1Name",
              "option2Name",
              "nombreBase",
              "nombreFull",
              "productoUpsellName",
            ] as const
          )
            .filter((k) => previewContext?.[k] !== undefined)
            .map((k) => [k, previewContext?.[k]])
        )
      : {}),
    // Y SUS PRECIOS DEL UPSELL, si los pide. Ver `preciosDelLlamanteMandan`. Aquí van
    // también los que vengan vacíos: un producto sin precio en ese país tiene que verse sin
    // precio, no con el del upsell de siempre.
    ...(previewContext?.preciosDelLlamanteMandan
      ? {
          upsellPrice: previewContext.upsellPrice,
          marketPriceUpsell: previewContext.marketPriceUpsell,
        }
      : {}),
  };
  const effectivePriceSoles =
    previewPriceOverride ??
    (previewContext?.preciosDelLlamanteMandan ? previewContext.priceSoles : undefined) ??
    inheritedPreviewContext.priceSoles ??
    priceSoles;
  const effectiveComboPrice = previewComboPriceOverride ?? comboPrice;
  const effectiveBasicoPrice = previewBasicoPriceOverride ?? basicoPrice;
  const shouldHighlightPlaceholders =
    highlightPlaceholders || inheritedPreviewContext.highlightPlaceholderValues === true;
  // Para que la miniatura se rehaga cuando se pulsa ↻ en el editor de al lado.
  const marcasDeMedia = useContext(MarcasDeMediaContext);
  const mediaUrlsToResolve = useMemo(
    () =>
      Array.from(
        new Set(
          steps
            .map((step) => step.drive_url.trim())
            .filter((url) => url && shouldResolveLinkMediaKind(url))
        )
      ),
    [steps]
  );
  const mediaUrlsToResolveKey = mediaUrlsToResolve.join("\n");
  useEffect(() => {
    if (!mediaUrlsToResolveKey) return;
    let cancelled = false;
    for (const url of mediaUrlsToResolve) {
      setResolvedMediaKinds((current) =>
        current[url] ? current : { ...current, [url]: "loading" }
      );
      void fetch(`/api/editor/media-kind?url=${encodeURIComponent(url)}`)
        .then((res) => res.json())
        .then((data: { kind?: string }) => {
          if (cancelled) return;
          // «restricted» llega del servidor solo cuando Drive NEGÓ el archivo.
          // Cualquier otra cosa rara cae en "unknown", que no avisa de nada.
          const kind: LinkMediaResolution =
            data.kind === "image" ||
            data.kind === "audio" ||
            data.kind === "video" ||
            data.kind === "document"
              ? data.kind
              : data.kind === "restricted"
                ? "restringido"
                : "unknown";
          setResolvedMediaKinds((current) => ({ ...current, [url]: kind }));
        })
        .catch(() => {
          if (cancelled) return;
          setResolvedMediaKinds((current) => ({ ...current, [url]: "unknown" }));
        });
    }
    return () => {
      cancelled = true;
    };
  }, [mediaUrlsToResolve, mediaUrlsToResolveKey]);
  const visibles = steps
    .map((s, originalIndex) => ({ step: s, originalIndex }))
    .filter(
      ({ step }) =>
        step.enabled !== false &&
        (step.texts.some((t) => t && t.trim()) || step.drive_url.trim())
    );
  useEffect(() => {
    if (!useScrollContainer || activeStepIndex == null) return;
    const container = previewScrollRef.current;
    const node = container?.querySelector<HTMLDivElement>(
      `[data-preview-step="${activeStepIndex}"]`
    );
    if (!container || !node) return;
    const top = node.offsetTop - container.offsetTop;
    container.scrollTo({ top, behavior: "smooth" });
  }, [activeStepIndex, useScrollContainer, visibles.length]);

  useEffect(() => {
    if (!onMoveStep) return;
    const onPointerMove = (event: PointerEvent) => {
      const drag = previewDragRef.current;
      if (!drag) return;
      if (!drag.active) {
        const distance = Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY);
        if (distance < 6) return;
        drag.active = true;
      }
      const target = document
        .elementFromPoint(event.clientX, event.clientY)
        ?.closest<HTMLElement>("[data-preview-step]");
      const targetIndex = Number(target?.dataset.previewStep);
      if (!Number.isFinite(targetIndex)) return;
      const rect = target!.getBoundingClientRect();
      const nextDrop = {
        index: drag.index,
        target: targetIndex,
        placement: event.clientY < rect.top + rect.height / 2 ? "before" : "after",
      } as const;
      previewDropRef.current = nextDrop;
      setPreviewDrag(nextDrop);
    };
    const onPointerUp = () => {
      const drag = previewDragRef.current;
      const target = previewDropRef.current;
      previewDragRef.current = null;
      previewDropRef.current = null;
      setPreviewDrag(null);
      if (drag?.active && target && target.index === drag.index) {
        onMoveStep(drag.index, target.target, target.placement);
        ignorePreviewClickRef.current = true;
        window.setTimeout(() => {
          ignorePreviewClickRef.current = false;
        }, 0);
      }
    };
    document.addEventListener("pointermove", onPointerMove);
    document.addEventListener("pointerup", onPointerUp);
    return () => {
      document.removeEventListener("pointermove", onPointerMove);
      document.removeEventListener("pointerup", onPointerUp);
    };
  }, [onMoveStep]);

  const copyStep = (step: EditorStep) => {
    bubbleClipboard.setStep({ ...step, texts: [...step.texts] });
  };
  /** Se lleva al portapapeles las marcadas, EN SU ORDEN, y sale del modo. */
  const copiarSeleccionadas = () => {
    const copia = seleccionadas
      .map((i) => steps[i])
      .filter(Boolean)
      .map((paso) => ({ ...paso, texts: [...paso.texts] }));
    if (copia.length === 0) return;
    bubbleClipboard.setSteps(copia);
    setSeleccion(null);
    setAvisoDelMenu(
      `${copia.length} burbuja(s) copiadas. Abre el menú donde las quieras —otra intro, un seguimiento, el upsell— y elige «Pegar debajo de esta burbuja».`
    );
  };
  /**
   * BORRA DE MAYOR A MENOR ÍNDICE, y no es un detalle de estilo.
   *
   * Borrando de arriba abajo, al quitar la 2 todas las de debajo suben un
   * puesto: el siguiente borrado se lleva la que no era. De abajo hacia arriba
   * los índices de las que faltan por borrar no se mueven.
   */
  const borrarSeleccionadas = () => {
    if (!onRemoveStep || seleccionadas.length === 0) return;
    const cuantas = seleccionadas.length;
    [...seleccionadas]
      .sort((a, b) => b - a)
      .forEach((i) => onRemoveStep(i, { sinPreguntar: true }));
    setSeleccion(null);
    setAvisoDelMenu(`${cuantas} burbuja(s) eliminadas.`);
  };
  /**
   * PEGA LO QUE HAYA EN EL PORTAPAPELES, DEBAJO DE UNA BURBUJA Y EN SU ORDEN.
   *
   * SE INSERTA DE LA ÚLTIMA A LA PRIMERA, todas en el MISMO sitio. Insertando
   * de la primera a la última cada una empujaría a la siguiente y saldrían al
   * revés. Así, la primera copiada queda justo debajo y las demás detrás, que
   * es como se copiaron.
   *
   * Y NO VACÍA EL PORTAPAPELES: pegar lo mismo en dos sitios es normal —una
   * despedida que va en tres seguimientos— y perderlo al primer pegado obliga a
   * volver al origen a copiar otra vez.
   */
  const pegarDebajo = (index: number) => {
    if (!onPasteStep) return;
    const lista = bubbleClipboard.steps.length
      ? bubbleClipboard.steps
      : bubbleClipboard.step
        ? [bubbleClipboard.step]
        : [];
    if (lista.length === 0) return;
    [...lista].reverse().forEach((paso) => onPasteStep(index, paso));
    setSeleccion(null);
    setAvisoDelMenu(
      lista.length === 1
        ? `Burbuja pegada debajo de la ${index + 1}.`
        : `${lista.length} burbujas pegadas debajo de la ${index + 1}, en su orden.`
    );
  };
  /** Cortar = copiar y quitar, igual que con una sola: primero se copia, así
   *  que si el borrado fallara las burbujas siguen en el portapapeles. */
  const cortarSeleccionadas = () => {
    const copia = seleccionadas
      .map((i) => steps[i])
      .filter(Boolean)
      .map((paso) => ({ ...paso, texts: [...paso.texts] }));
    if (copia.length === 0 || !onRemoveStep) return;
    bubbleClipboard.setSteps(copia);
    [...seleccionadas]
      .sort((a, b) => b - a)
      .forEach((i) => onRemoveStep(i, { sinPreguntar: true }));
    setSeleccion(null);
    setAvisoDelMenu(
      `${copia.length} burbuja(s) cortadas. Están en el portapapeles: abre el menú donde las quieras y elige «Pegar debajo de esta burbuja».`
    );
  };
  // LO QUE HIZO EL MENÚ, DICHO EN VOZ ALTA.
  //
  // «Duplicar» y «Copiar» funcionaban y no se veía nada, así que parecían
  // rotos:
  //
  //  · La copia nace APAGADA —a propósito, para que no se envíe sola— y esta
  //    vista solo muestra las encendidas. Se duplicaba de verdad, aparecía en
  //    el cajón de la izquierda, y aquí no pasaba nada.
  //  · «Copiar» deja la burbuja en el portapapeles y no manda ningún mensaje.
  //    El único rastro era que aparecía «Pegar» en el menú… la próxima vez que
  //    lo abrieras.
  //
  // Un aviso de dos segundos cuesta poco y evita que alguien dé tres veces a
  // duplicar creyendo que no funciona — y se encuentre tres copias.
  const [avisoDelMenu, setAvisoDelMenu] = useState<string | null>(null);
  useEffect(() => {
    if (!avisoDelMenu) return;
    const t = window.setTimeout(() => setAvisoDelMenu(null), 3500);
    return () => window.clearTimeout(t);
  }, [avisoDelMenu]);
  // EL VISOR ES UN TELÉFONO Y SE QUEDA DEL ANCHO DE UN TELÉFONO.
  //
  // Al ensanchar la página, todo lo demás gana sitio —que es de lo que se
  // trataba— pero el visor no debe crecer con ella: estirado deja de parecerse
  // a lo que ve el cliente y las burbujas salen larguísimas, así que ya no
  // sirve para lo único que sirve, comprobar cómo llega el mensaje.
  return (
    <div
      className={`rounded-xl border border-neutral-300 bg-[#efeae2] p-2 ${
        sinTopeDeAncho ? "" : "w-full max-w-[420px]"
      }`}
    >
      {avisoDelMenu && (
        <div className="mb-2 rounded-md border border-emerald-300 bg-emerald-50 px-3 py-2 text-[11px] font-semibold text-emerald-900">
          ✅ {avisoDelMenu}
        </div>
      )}
      <div className="mb-2 flex items-center justify-between gap-2">
        <div className="flex min-w-0 flex-wrap items-center gap-2">
          <span className="text-[11px] font-semibold text-neutral-500">
            📱 Vista previa (WhatsApp)
          </span>
          <span
            title="Burbujas activas visibles en esta previsualización"
            className="rounded-full border border-emerald-200 bg-white/80 px-2 py-0.5 text-[11px] font-semibold text-emerald-700"
          >
            {visibles.length} {visibles.length === 1 ? "activa" : "activas"}
          </span>
        </div>
        <button
          type="button"
          onClick={() => {
            setRoll((r) => r + 1);
            onVaryAll?.();
          }}
          title="Mostrar otra combinación de variantes al azar (como hace el bot)"
          className="rounded border border-neutral-300 bg-tarjeta px-2 py-0.5 text-[11px] text-neutral-600 hover:bg-neutral-50"
        >
          🔀 Variar
        </button>
      </div>
      {/* LA BARRA DE LA SELECCIÓN.
          Sin ella, lo único que se puede hacer con lo marcado está escondido
          detrás de un click derecho — y quien no sepa que está ahí, no lo
          encuentra. Aquí se ve cuántas hay y qué se puede hacer con ellas.
          Solo aparece en modo selección: fuera de él, el visor no cambia. */}
      {seleccion !== null && (
        <div className="mb-2 flex flex-wrap items-center gap-2 rounded-lg border border-emerald-300 bg-emerald-50 px-3 py-2 text-xs font-semibold text-emerald-900">
          <span>
            {seleccionadas.length}{" "}
            {seleccionadas.length === 1 ? "seleccionada" : "seleccionadas"}
          </span>
          <button
            type="button"
            disabled={seleccionadas.length === 0}
            onClick={() => copiarSeleccionadas()}
            className="rounded border border-emerald-300 bg-tarjeta px-2 py-1 disabled:opacity-40"
          >
            📋 Copiar
          </button>
          {onToggleStep && (
            <button
              type="button"
              disabled={seleccionadas.length === 0}
              onClick={() => {
                seleccionadas.forEach((i) => onToggleStep(i));
                setAvisoDelMenu(
                  `${seleccionadas.length} burbuja(s) cambiadas de encendido.`
                );
                setSeleccion(null);
              }}
              className="rounded border border-emerald-300 bg-tarjeta px-2 py-1 disabled:opacity-40"
            >
              Apagar / encender
            </button>
          )}
          {onRemoveStep && (
            <button
              type="button"
              disabled={seleccionadas.length === 0}
              onClick={() => borrarSeleccionadas()}
              className="rounded border border-red-300 bg-tarjeta px-2 py-1 text-red-700 disabled:opacity-40"
            >
              Eliminar
            </button>
          )}
          <button
            type="button"
            onClick={() => setSeleccion(null)}
            className="ml-auto rounded border border-neutral-300 bg-tarjeta px-2 py-1 text-neutral-700"
          >
            Cancelar (Esc)
          </button>
        </div>
      )}
      <div
        ref={previewScrollRef}
        tabIndex={-1}
        onKeyDown={(event) => {
          if (!(event.metaKey || event.ctrlKey) || event.key.toLowerCase() !== "d") return;
          if (activeStepIndex == null || !onDuplicateStep) return;
          event.preventDefault();
          onDuplicateStep(activeStepIndex);
        }}
        className={`${useScrollContainer ? "max-h-[70vh] overflow-y-auto pr-1" : ""} space-y-2`}
      >
        {visibles.length === 0 && (
          <p className="py-6 text-center text-[11px] text-neutral-400">
            Agrega texto o una imagen para ver la vista previa.
          </p>
        )}
        {visibles.map(({ step: s, originalIndex }, i) => {
          const stepRoll = bubbleRolls[originalIndex] ?? previewRolls?.[originalIndex] ?? roll;
          const rawCaption = pickVariantText(s.texts, stepRoll, i);
          const caption = resolvePreviewSpintax(
            applyPreviewPrices(
              rawCaption,
              effectivePriceSoles,
              effectiveComboPrice,
              effectiveBasicoPrice,
              effectivePreviewContext
            ),
            stepRoll,
            i
          );
          const previewIssue = resolvedMediaPreviewIssue(
            s,
            resolvedMediaKinds[s.drive_url.trim()]
          );
          const thumb =
            !previewIssue &&
            (s.type === "image" || s.type === "video" || s.type === "document")
              ? driveThumb(s.drive_url, marcasDeMedia.marcaDe(s.drive_url))
              : null;
          const isDropBefore =
            previewDrag?.target === originalIndex && previewDrag.placement === "before";
          const isDropAfter =
            previewDrag?.target === originalIndex && previewDrag.placement === "after";
          return (
            <div key={i}>
              {isDropBefore && (
                <div className="my-1 h-1 rounded-full bg-sky-500 shadow-[0_0_0_2px_rgba(14,165,233,0.18)]" />
              )}
              <div className="flex items-center justify-end gap-2">
              {/* EL CHECK, A LA IZQUIERDA DE LA BURBUJA.
                  Solo existe en modo selección: fuera de él, el visor se ve
                  exactamente como siempre. Va FUERA de la burbuja para no
                  robarle sitio al texto ni cambiar su ancho — si entrara
                  dentro, las burbujas se reajustarían al entrar y salir del
                  modo y parecería que el contenido se movió. */}
              {seleccion !== null && (
                <input
                  type="checkbox"
                  checked={seleccion.has(originalIndex)}
                  onChange={() => marcar(originalIndex)}
                  onClick={(event) => event.stopPropagation()}
                  aria-label={`Seleccionar la burbuja ${originalIndex + 1}`}
                  className="h-4 w-4 shrink-0 cursor-pointer accent-emerald-600"
                />
              )}
              <div
                data-preview-step={originalIndex}
                onPointerDown={(event) => {
                  if (!onMoveStep || event.button !== 0) return;
                  if ((event.target as HTMLElement).closest("button, a, input, textarea, video, audio")) return;
                  previewDropRef.current = null;
                  previewDragRef.current = {
                    index: originalIndex,
                    startX: event.clientX,
                    startY: event.clientY,
                    active: false,
                  };
                }}
                onClick={() => {
                  if (ignorePreviewClickRef.current) return;
                  // EN MODO SELECCIÓN, EL CLIC MARCA. Obligar a apuntar al
                  // cuadradito de 16 px para marcar diez burbujas es trabajo
                  // de puntería; la burbuja entera es el blanco natural.
                  if (seleccion !== null) {
                    marcar(originalIndex);
                    return;
                  }
                  previewScrollRef.current?.focus({ preventScroll: true });
                  onSelectStep?.(originalIndex);
                }}
                onContextMenu={(event) => {
                  if (!onEditStep && !onDuplicateStep && !onToggleStep && !onRemoveStep) return;
                  event.preventDefault();
                  event.stopPropagation();
                  onSelectStep?.(originalIndex);
                  setContextMenu({ index: originalIndex, x: event.clientX, y: event.clientY });
                }}
                className={`max-w-[88%] rounded-lg rounded-tr-none bg-[#d9fdd3] px-2.5 py-1.5 shadow-sm transition ${
                  // UNA SOLA LÍNEA. Aquí había un borde de 2 px MÁS un aro de
                  // 2 px separado: dos líneas de verdad, que en un Mac se
                  // funden y en un PC se ven las dos.
                  //
                  // EL COLOR VA EN LAS DOS RAMAS, NUNCA EN LA BASE.
                  //
                  // Poner «border-transparent» en la base y el verde aquí deja
                  // los dos colores puestos a la vez, y cuál gana no lo decide
                  // el orden en que se escriben: lo decide el orden del CSS
                  // generado. Puede ganar el transparente y entonces la burbuja
                  // seleccionada se queda SIN línea.
                  //
                  // Transparente cuando no está marcada: así el grosor está
                  // siempre reservado y al marcarla no se mueve nada.
                  activeStepIndex === originalIndex
                    ? "border-2 border-emerald-600 shadow-md"
                    : "border border-transparent"
                } ${onMoveStep ? "cursor-grab active:cursor-grabbing select-none" : onSelectStep ? "cursor-pointer" : ""}`}
              >
                {thumb && (
                  <div className="relative mb-1 overflow-hidden rounded-md">
                    {/* eslint-disable-next-line @next/next/no-img-element */}
                    {/* LA FOTO ENTERA, CON SU PROPORCIÓN.
                        Estaba dentro de una caja de alto fijo con orden de
                        RELLENARLA, así que a una imagen más alta que la caja se
                        le cortaban el borde de arriba y el de abajo: un cartel
                        vertical se veía casi cuadrado. El visor enseñaba algo
                        que el cliente no recibe.
                        La miniatura ya llega entera desde Drive; el recorte era
                        solo del dibujo. Ahora la burbuja se adapta al alto real:
                        cuadrada se ve cuadrada, vertical se ve alta, y nunca
                        quedan franjas vacías porque no hay caja que rellenar.
                        Es lo que hace WhatsApp. */}
                    <img
                      src={thumb}
                      alt="imagen"
                      className="h-auto w-full"
                      onError={(e) => {
                        const box = e.currentTarget
                          .parentElement as HTMLElement | null;
                        if (box) box.style.display = "none";
                      }}
                    />
                    {s.type === "video" && (
                      <span className="absolute inset-0 flex items-center justify-center text-3xl text-white drop-shadow">
                        ▶
                      </span>
                    )}
                    {s.type === "document" && (
                      <span className="absolute bottom-2 right-2 rounded bg-black/70 px-2 py-0.5 text-[10px] font-semibold text-white">
                        PDF
                      </span>
                    )}
                  </div>
                )}
                {previewIssue && (
                  <div
                    className={`mb-1 rounded-md border px-3 py-4 text-center ${
                      previewIssue.tone === "danger"
                        ? "border-red-300 bg-red-50 text-red-700"
                        : "border-amber-300 bg-amber-50 text-amber-800"
                    }`}
                  >
                    <div className="text-xs font-bold uppercase tracking-wide">
                      {previewIssue.title}
                    </div>
                    <div className="mt-1 text-[11px] leading-snug">
                      {previewIssue.detail}
                    </div>
                  </div>
                )}
                {s.type === "audio" && s.drive_url.trim() && (
                  <div className="mb-1 flex items-center gap-2 rounded-md bg-neutral-100 px-3 py-2 text-xs text-neutral-600">
                    <span className="text-lg">▶</span>
                    <div className="h-1.5 flex-1 rounded-full bg-neutral-300" />
                    <span>Audio</span>
                  </div>
                )}
                {s.type === "document" && s.drive_url.trim() && (
                  <div className="mb-1 flex items-center gap-2 rounded-md bg-neutral-100 px-3 py-2 text-xs text-neutral-600">
                    <span className="text-lg">📄</span>
                    <span>PDF</span>
                  </div>
                )}
                {(s.type === "image" || s.type === "video") &&
                  !previewIssue &&
                  !thumb &&
                  s.drive_url.trim() && (
                  <div className="mb-1 rounded-md bg-neutral-200 px-2 py-3 text-center text-[10px] text-neutral-500">
                    [media del enlace]
                  </div>
                )}
                {perBubbleVary && (s.texts.length > 1 || rawCaption.includes("|")) && (
                  <button
                    type="button"
                    onClick={() => setBubbleRolls((current) => ({
                      ...current,
                      [originalIndex]: (current[originalIndex] ?? 0) + 1,
                    }))}
                    title="Mostrar otra versión de esta burbuja"
                    className="float-right ml-2 rounded border border-emerald-200 bg-white/70 px-1.5 py-0.5 text-[10px] font-bold text-emerald-800 hover:bg-tarjeta"
                  >
                    Variar
                  </button>
                )}
                {caption && (
                  <div className="whitespace-pre-wrap break-words text-[13px] leading-snug text-neutral-800">
                    {shouldHighlightPlaceholders
                      ? renderPreviewTextWithHighlights(
                          // El texto CRUDO, no el resuelto: hace falta saber
                          // dónde estaba cada comodín antes de cambiarlo por su
                          // valor.
                          rawCaption,
                          effectivePriceSoles,
                          effectiveComboPrice,
                          effectiveBasicoPrice,
                          effectivePreviewContext,
                          stepRoll,
                          i
                        )
                      : renderWa(caption)}
                  </div>
                )}
                <BotonesDeLaBurbuja step={s} />
              </div>
              </div>
              {isDropAfter && (
                <div className="my-1 h-1 rounded-full bg-sky-500 shadow-[0_0_0_2px_rgba(14,165,233,0.18)]" />
              )}
            </div>
          );
        })}
      </div>
      {contextMenu && (
        <>
          <button
            type="button"
            aria-label="Cerrar menu"
            onClick={() => setContextMenu(null)}
            className="fixed inset-0 z-20 cursor-default"
          />
          <div
            role="menu"
            style={{ left: contextMenu.x, top: contextMenu.y }}
            className="fixed z-30 min-w-52 overflow-hidden rounded-md border border-neutral-300 bg-tarjeta py-1 text-xs font-semibold text-neutral-800 shadow-lg"
          >
            {/* CON BURBUJAS MARCADAS, EL MENÚ ES DE ELLAS.
                Mezclar «Copiar burbuja» (ésta) y «Copiar las 3» (las marcadas)
                en la misma lista es pedir que se equivoque: dos órdenes casi
                iguales, una encima de otra, y la que actúa no es la que se
                leyó. Mientras haya selección, el menú habla SOLO de lo marcado
                y al final ofrece salir del modo. */}
            {seleccionadas.length > 0 ? (
              <>
                <div className="border-b border-neutral-200 px-3 py-2 text-[11px] font-bold uppercase tracking-wide text-neutral-500">
                  {seleccionadas.length} seleccionadas
                </div>
                <button type="button" onClick={() => { setContextMenu(null); copiarSeleccionadas(); }} className="block w-full px-3 py-2 text-left hover:bg-neutral-50">Copiar las {seleccionadas.length}</button>
                {onRemoveStep && (
                  <button type="button" onClick={() => { setContextMenu(null); cortarSeleccionadas(); }} className="block w-full px-3 py-2 text-left hover:bg-neutral-50">Cortar las {seleccionadas.length}</button>
                )}
                {onPasteStep && bubbleClipboard.steps.length > 0 && (
                  <button type="button" onClick={() => { const index = contextMenu.index; setContextMenu(null); pegarDebajo(index); }} className="block w-full px-3 py-2 text-left hover:bg-neutral-50">Pegar {bubbleClipboard.steps.length === 1 ? "la burbuja" : `las ${bubbleClipboard.steps.length}`} debajo de esta</button>
                )}
                {onToggleStep && (
                  <button type="button" onClick={() => { const marcadas = seleccionadas; setContextMenu(null); marcadas.forEach((i) => onToggleStep(i)); setSeleccion(null); setAvisoDelMenu(`${marcadas.length} burbuja(s) cambiadas de encendido.`); }} className="block w-full px-3 py-2 text-left hover:bg-neutral-50">Apagar / encender las {seleccionadas.length}</button>
                )}
                {onRemoveStep && (
                  <button type="button" onClick={() => { setContextMenu(null); borrarSeleccionadas(); }} className="block w-full px-3 py-2 text-left text-red-600 hover:bg-red-50">Eliminar las {seleccionadas.length}</button>
                )}
                <button type="button" onClick={() => { setContextMenu(null); setSeleccion(null); }} className="block w-full border-t border-neutral-200 px-3 py-2 text-left text-neutral-600 hover:bg-neutral-50">Salir de la selección (Esc)</button>
              </>
            ) : (
            <>
            {onEditStep && (
              <button type="button" onClick={() => { const index = contextMenu.index; setContextMenu(null); onEditStep(index); }} className="block w-full px-3 py-2 text-left hover:bg-neutral-50">Editar esta burbuja</button>
            )}
            {onDuplicateStep && (
              <button type="button" onClick={() => { const index = contextMenu.index; setContextMenu(null); onDuplicateStep(index); setAvisoDelMenu(`Burbuja ${index + 1} duplicada. La copia está justo debajo.`); }} className="block w-full px-3 py-2 text-left hover:bg-neutral-50">Duplicar burbuja</button>
            )}
            <button type="button" onClick={() => { copyStep(steps[contextMenu.index]); setContextMenu(null); setAvisoDelMenu("Burbuja copiada. Abre el menú donde la quieras —otra intro, un seguimiento, el upsell— y elige «Pegar debajo de esta burbuja»."); }} className="block w-full px-3 py-2 text-left hover:bg-neutral-50">Copiar burbuja</button>
            {/* CORTAR = COPIAR Y QUITAR.
                Sin esto, mover una burbuja a otra secuencia eran dos pasos y
                acordarse de volver a borrar el original — y si se olvidaba, el
                cliente recibía el mismo mensaje dos veces desde sitios
                distintos. Se copia PRIMERO y se quita después: si el borrado
                fallara, la burbuja sigue en el portapapeles. */}
            {onRemoveStep && (
              <button type="button" onClick={() => { const index = contextMenu.index; const step = steps[index]; setContextMenu(null); if (!step) return; copyStep(step); onRemoveStep(index, { sinPreguntar: true }); setAvisoDelMenu("Burbuja cortada. Está en el portapapeles: abre el menú donde la quieras y elige «Pegar debajo de esta burbuja»."); }} className="block w-full px-3 py-2 text-left hover:bg-neutral-50">Cortar burbuja</button>
            )}
            {onPasteStep && bubbleClipboard.steps.length > 0 && (
              <button type="button" onClick={() => { const index = contextMenu.index; setContextMenu(null); pegarDebajo(index); }} className="block w-full px-3 py-2 text-left hover:bg-neutral-50">{bubbleClipboard.steps.length === 1 ? "Pegar debajo de esta burbuja" : `Pegar las ${bubbleClipboard.steps.length} debajo de esta`}</button>
            )}
            {onToggleStep && (
              <button type="button" onClick={() => { const index = contextMenu.index; setContextMenu(null); onToggleStep(index); }} className="block w-full px-3 py-2 text-left hover:bg-neutral-50">{steps[contextMenu.index]?.enabled === false ? "Encender burbuja" : "Apagar burbuja"}</button>
            )}
            {onRemoveStep && (
              <button type="button" onClick={() => { const index = contextMenu.index; setContextMenu(null); onRemoveStep(index); }} className="block w-full px-3 py-2 text-left text-red-600 hover:bg-red-50">Eliminar burbuja</button>
            )}
            {/* LA PUERTA DE ENTRADA AL MODO SELECCIÓN, tal y como la pidió: la
                burbuja del click derecho entra YA marcada, y las demás
                aparecen con su check vacío al lado. */}
            <button type="button" onClick={() => { const index = contextMenu.index; setContextMenu(null); setSeleccion(new Set([index])); setAvisoDelMenu("Marca las burbujas que quieras y usa la barra de arriba o el click derecho. Escape sale de la selección."); }} className="block w-full border-t border-neutral-200 px-3 py-2 text-left hover:bg-neutral-50">☑️ Seleccionar varias burbujas</button>
            </>
            )}
          </div>
        </>
      )}
    </div>
  );
}

type JourneyTarget = { tab: Tab; id: string; openKeys?: string[]; stepId?: string };

/**
 * CUÁNDO SALE UN SEGUIMIENTO, dicho como lo diría una persona.
 *
 * LO SUGERÍ Y LO PIDIÓ EL DUEÑO el 06/10/2026. Sin esto el visor enseña el ORDEN de los
 * seguimientos pero no el RECORRIDO: no se sabe si el segundo llega tres minutos después del
 * primero o tres días. Y es justo lo que se mira cuando se ajusta una venta.
 *
 * SE CUENTA DESDE EL PRIMER MENSAJE, que es lo que significa el campo
 * `delay_minutes_from_first_message` — no desde el seguimiento anterior. Por eso se dice «a
 * los 5 min del primer mensaje» y no «5 min después»: la diferencia confunde a cualquiera que
 * esté ajustando tiempos, y confundirse ahí sale caro.
 *
 * Los minutos se escriben en minutos hasta la hora, en horas hasta el día, y en días a partir
 * de ahí: «a los 1200 min» no se lee, «a los 20 h» sí.
 */
function cuandoSale(minutos: number | undefined | null): string {
  const m = Number(minutos ?? 0);
  if (!Number.isFinite(m) || m <= 0) return "en cuanto termina la intro";
  const redondo = (n: number) => (Number.isInteger(n) ? String(n) : n.toFixed(1));
  if (m < 60) return `a los ${redondo(m)} min del primer mensaje`;
  if (m < 1440) return `a las ${redondo(m / 60)} h del primer mensaje`;
  const dias = m / 1440;
  return `a los ${redondo(dias)} ${dias === 1 ? "día" : "días"} del primer mensaje`;
}

function JourneyPreviewModal({
  cfg,
  country,
  tiendaInicial,
  paisesDeLaPizarra,
  onClose,
  onNavigate,
  onConfigChange,
  onSnapshot,
  onSave,
  onUndo,
  onRedo,
  undoCount,
  redoCount,
  saving,
  hayCambios,
  highlightPlaceholderValues,
}: {
  cfg: FullConfig;
  country: CountryCode;
  /** Abierto desde la pizarra: arranca en ESA tienda (17/10/2026). Sin él, como siempre. */
  tiendaInicial?: string;
  /** Abierto desde la pizarra: los países de su pizarra, una columna cada uno. */
  paisesDeLaPizarra?: string[];
  /** El recorrido armaba su propio contexto de vista previa y se dejaba fuera
   *  el resaltado, así que la "C" no hacía nada aquí. Ahora entra. */
  highlightPlaceholderValues: boolean;
  onClose: () => void;
  onNavigate: (target: JourneyTarget) => void;
  onConfigChange: (config: FullConfig) => void;
  onSnapshot: () => void;
  onSave: () => void;
  onUndo: () => void;
  onRedo: () => void;
  undoCount: number;
  redoCount: number;
  saving: boolean;
  /**
   * ¿QUEDA ALGO SIN GUARDAR?
   *
   * LO QUE CONTÓ EL DUEÑO — 21 de septiembre de 2026:
   *
   *   «El visor del recorrido tiene un botón de "guardar cambios", este botón
   *    está activo así los cambios estén guardados.»
   *
   * Y tenía razón: el botón solo se apagaba MIENTRAS guardaba, nunca por no
   * tener nada que guardar. El dato existe en el editor —`isDirty`, la misma
   * comparación que usan las demás ventanas— pero esta se dibuja FUERA del
   * proveedor que lo reparte, así que hay que pasárselo a mano.
   */
  hayCambios: boolean;
}) {
  const mode = activeModality(cfg);
  const [channel, setChannel] = useState<ChannelKey>("whatsapp");
  /**
   * QUÉ TIENDA SE ESTÁ MIRANDO. Vacío = sin tienda, el recorrido general de siempre.
   *
   * ARRANCA EN LA PRIMERA QUE TENGA NÚMERO, no en «sin tienda»: quien tiene tiendas quiere
   * ver una tienda, y abrir en el general le enseñaría un recorrido que no es de nadie. Sin
   * tiendas creadas, ni se pinta el selector.
   */
  const tiendasDelProyecto = (cfg.tiendas ?? []).filter((t) => String(t?.id ?? "").trim());
  const [tiendaDelVisor, setTiendaDelVisor] = useState<string>(
    () =>
      (tiendaInicial && tiendasDelProyecto.some((t) => t.id === tiendaInicial) ? tiendaInicial : undefined) ??
      tiendasDelProyecto.find((t) => String(t?.numero ?? "").trim())?.id ??
      tiendasDelProyecto[0]?.id ??
      ""
  );
  /** Ver TODAS las tiendas una al lado de otra, en vez de la del selector. */
  const [verTodasLasTiendas, setVerTodasLasTiendas] = useState(false);
  /** LAS COLUMNAS PLEGADAS CON EL OJO (17/10/2026): «un ojo o algo que al tocarlo lo repliegue…
   *  si hay un país que no trabaja lo oculto». Solo la vista: no cambia nada del bot. */
  const [plegadas, setPlegadas] = useState<Set<string>>(() => new Set());
  /** LA RUTA QUE SE MIRA EN CADA COLUMNA (20/10/2026), por su clave. Se recuerda en este
   *  navegador: al volver a abrir el visor, cada país sigue en la ruta que él eligió. */
  const [rutaElegida, setRutaElegidaYa] = useState<Record<string, string>>(() => {
    try {
      return JSON.parse(localStorage.getItem("wf:visor-rutas") ?? "{}") as Record<string, string>;
    } catch {
      return {};
    }
  });
  /** El visor a la derecha, con la pizarra a la vista (20/10/2026). */
  const [conLaPizarra, setConLaPizarra] = useState(false);
  /** Los países que se ven con sus rutas lado a lado (por la clave de su columna). */
  const [ladoALado, setLadoALado] = useState<Set<string>>(() => new Set());
  const alternarLadoALado = (clave: string) =>
    setLadoALado((s) => {
      const n = new Set(s);
      if (n.has(clave)) n.delete(clave);
      else n.add(clave);
      return n;
    });
  /**
   * LA RUTA ELEGIDA, ILUMINADA EN LA PIZARRA (20/10/2026): «¿cómo vería esa rama activa en la
   * pizarra?». El visor avisa con un evento y la pizarra (si está abierta) ilumina esa ruta y
   * la centra. Al cerrar el visor, sigue iluminada unos segundos y se apaga sola.
   */
  const iluminarEnLaPizarra = (pais: string | null, camino?: string, lateral = conLaPizarra) => {
    try {
      window.dispatchEvent(
        new CustomEvent("pizarra:iluminar-ruta", {
          // `margen`: lo que tapa el visor a la derecha, para encuadrar la ruta en lo que se ve.
          detail: pais ? { pais, camino: camino ?? "", margen: lateral ? Math.max(420, Math.round(window.innerWidth * 0.46)) : 0 } : null,
        })
      );
    } catch {}
  };
  const elegirRuta = (clave: string, camino: string, pais?: string) => {
    setRutaElegidaYa((r) => {
      const n = { ...r, [clave]: camino };
      try {
        localStorage.setItem("wf:visor-rutas", JSON.stringify(n));
      } catch {}
      return n;
    });
    if (pais) iluminarEnLaPizarra(pais, camino);
  };
  // Al cerrar el visor: la última ruta sigue iluminada unos segundos y se apaga.
  useEffect(() => () => {
    window.setTimeout(() => iluminarEnLaPizarra(null), 4000);
  }, []);
  const alternarPlegada = (clave: string) =>
    setPlegadas((s) => {
      const n = new Set(s);
      if (n.has(clave)) n.delete(clave);
      else n.add(clave);
      return n;
    });
  const [previewWidth, setPreviewWidth] = useState<"mobile" | "normal" | "wide">("mobile");
  /**
   * LO QUE MIDE CADA CHAT. La ventana ya ocupa la pantalla; esto es el de dentro.
   *
   * 350px EN «celular», Y EL NÚMERO NO ES AL AZAR: es exactamente lo que medía antes el
   * recorrido. La ventana era `max-w-[390px]` y el cuerpo lleva `p-5`, así que al chat le
   * quedaban 390 − 20 − 20 = 350. Al sacar la ventana a pantalla completa puse 390 y él lo
   * notó en seguida: «los visores están ligeramente más anchos que cuando se veía 1 solo».
   */
  const anchoDelChat =
    previewWidth === "mobile"
      ? "w-[350px]"
      : previewWidth === "wide"
        ? "w-[720px]"
        : "w-[560px]";
  const channelUsesOwnContent = cfg.channels?.[channel]?.use_content === true;
  const channelContent = channelContentForMode(cfg, channel, mode);
  /**
   * EL POP UP DE UNA BURBUJA YA NO SUBE NADA. LA HISTORIA, QUE ES LARGA:
   *
   * 21 DE SEPTIEMBRE DE 2026 — el dueño, tras probarlo paso a paso:
   *
   *   «Me fui a la burbuja del seguimiento 2, click derecho editar, le cambié un
   *    carácter, le di al botón GUARDAR de ese pop up, y no hubo cambios. Luego
   *    me fui a la primera burbuja de intro, cambié un carácter, le di guardar y
   *    sí guardó… y entonces el del seguimiento también se guardó. No debería ser
   *    así: debería funcionar de manera independiente.»
   *
   * No era un fallo de escritura —se midió ejecutando el código y el camino que
   * escribe funciona en los tres seguimientos y en sus variantes—: era que este
   * pop up era el ÚNICO cuyo «Guardar» no subía. Así que se conectó al guardado
   * general con una bandera, porque llamarlo en el manejador del botón subiría la
   * configuración DE ANTES: `setCfg` vive en el padre y no está puesto todavía
   * cuando termina el manejador.
   *
   * 28 DE SEPTIEMBRE DE 2026 — pidió lo contrario, y con motivo:
   *
   *   «Yo quiero que el guardar de los pop ups guarden los cambios del contenido
   *    de sus ventanas respectivas, pero que no hagan guardado general. Pero,
   *    cuando yo haga algún cambio en el editor que aparezca al lado de "guardar"
   *    AÚN NO HAS GUARDADO TUS CAMBIOS, como aviso extra. Entonces con eso puedo
   *    hacer ediciones y el botón de guardar "general" que está en el menú o
   *    cerca de él ó control+S es el que define el guardado general.»
   *
   * Lo que le molestaba en septiembre no era que el pop up no subiera: era que
   * NADIE LE AVISABA de que quedaba algo sin subir. Con el aviso al lado del
   * Guardar de la barra, ese problema deja de existir y él recupera lo que quiere:
   * hacer varias ediciones y subirlas de una vez.
   *
   * Así que la bandera se retira —el efecto que guardaba, con ella— y queda
   * escrito aquí para que nadie la devuelva sin leer las dos fechas. Ver la
   * cabecera de `BotonesDeLaVentana`, donde está el resto del caso.
   */
  const [editingStep, setEditingStep] = useState<{
    title: string;
    steps: EditorStep[];
    index: number;
    onChange: (steps: EditorStep[]) => void;
    previewPriceOverride?: number;
    previewComboPriceOverride?: number;
    previewBasicoPriceOverride?: number;
  } | null>(null);
  // ESCAPE CIERRA DE DENTRO HACIA FUERA. Con el cajón de una burbuja abierto,
  // Escape lo cierra a ÉL y te deja en el recorrido; su propio manejador se
  // encarga y aquí no hacemos nada. Solo con el recorrido a solas, Escape sale
  // del recorrido. Antes los dos manejadores disparaban a la vez y una sola
  // pulsación te devolvía al editor, saltándose el recorrido.
  //
  // Va DESPUÉS de `editingStep` a propósito: sus dependencias se evalúan al
  // renderizar, y declararlo antes rompía por usar la variable sin declarar.
  useEffect(() => {
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      if (editingStep) return;
      onClose();
    };
    window.addEventListener("keydown", closeOnEscape);
    return () => window.removeEventListener("keydown", closeOnEscape);
  }, [onClose, editingStep]);
  /* AQUÍ IBA EL EFECTO QUE SUBÍA LO QUE SE ACABABA DE APLICAR EN UNA BURBUJA.
     Se retira el 28/09/2026 a petición del dueño, junto con su bandera. El
     porqué, con sus palabras y con las dos fechas, está unas líneas más arriba.
     `onSave` sigue en pie: es el botón «Guardar cambios» de esta ventana, que es
     el guardado general de toda la vida y el único que hay a mano mientras el
     recorrido está abierto. */
  const updateChannelContent = (content: ChannelContentEditor) => {
    onConfigChange({
      ...cfg,
      channels: {
        ...cfg.channels,
        [channel]: {
          ...(cfg.channels?.[channel] ?? {}),
          modality_templates: {
            ...(cfg.channels?.[channel]?.modality_templates ?? {}),
            [mode]: content,
          },
        },
      },
    });
  };
  const openChannelStepEditor = (
    title: string,
    steps: EditorStep[],
    index: number,
    updateSteps: (next: EditorStep[]) => void,
    previewOverrides?: Pick<
      NonNullable<typeof editingStep>,
      "previewPriceOverride" | "previewComboPriceOverride" | "previewBasicoPriceOverride"
    >
  ) => setEditingStep({ title, steps, index, onChange: updateSteps, ...previewOverrides });
  const updateBaseIntroSteps = (index: number, steps: EditorStep[]) => {
    const template = cfg.modality_templates?.[mode] ?? {};
    const field = index === 1
      ? "intro_sequence"
      : index === 2
        ? "intro_sequence_2"
        : index === 3
          ? "intro_sequence_3"
          : null;
    if (field) {
      onConfigChange({
        ...cfg,
        modality_templates: {
          ...cfg.modality_templates,
          [mode]: { ...template, [field]: steps },
        },
      });
      return;
    }
    if (index > 3) {
      const extra = [...(template.intro_extra_sequences ?? [])];
      extra[index - 4] = steps;
      onConfigChange({
        ...cfg,
        modality_templates: {
          ...cfg.modality_templates,
          [mode]: { ...template, intro_extra_sequences: extra },
        },
      });
    }
  };
  /**
   * LA CONFIGURACIÓN *COMO LA VE* UNA TIENDA EN UNA SEMIMODALIDAD.
   *
   * ── EL FALLO QUE ARREGLA, Y ÉL LO DESCRIBIÓ EXACTO ───────────────────
   *
   * «en las intros y seguimientos donde hay 2 productos está mostrando el nombre de 1
   * repetido en los 2». Y es verdad: el visor armaba su contexto con `cfg` A SECAS, o sea con
   * la alineación GENERAL y el selector general. Nunca miraba la tienda.
   *
   * Por eso los dos comodines daban lo mismo: sin `segunda_opcion_prestada`, el reparto de
   * «lineal» dice «caja 1 = el único, caja 2 = no existe», así que la segunda se caía al
   * campo viejo y acababa enseñando el primero. Está documentado en
   * `puestoDelCajonDeContenido`, que ya lo sufrió en septiembre con el selector general.
   *
   * ── ES UNA COPIA PARA LA PANTALLA, NO SE GUARDA ─────────────────────
   *
   * Mismo truco que ya usa la sección de Tiendas para enseñar los productos de cada una. Se
   * cambian dos cosas y nada más:
   *
   *     el selector        pasa a ser el de ESTA columna, no el general
   *     la alineación      pasa a ser la de ESTA tienda, si tiene
   *
   * Con eso `previewContextFromConfig` y los precios resuelven lo que de verdad va a salir.
   */
  const configDeLaColumna = (tiendaId: string, semi: string): FullConfig => {
    const suTienda = tiendasDelProyecto.find((t) => t.id === tiendaId);
    const suya = Object.entries(suTienda?.alineacion ?? {}).filter(([, v]) => v);
    return {
      ...cfg,
      globals: {
        ...cfg.globals,
        segunda_opcion_prestada: semi as "" | "dos_juntas" | "segunda_oculta",
      },
      ...(suya.length > 0
        ? {
            alineacion_por_modalidad: {
              ...cfg.alineacion_por_modalidad,
              [mode]: {
                ...(cfg.alineacion_por_modalidad?.[mode] ?? {}),
                ...Object.fromEntries(suya),
              } as AlineacionEditor,
            },
          }
        : {}),
    };
  };
  // EL DE LA COLUMNA ACTIVA, para lo que todavía se calcula una sola vez arriba. Cada columna
  // se vuelve a calcular el suyo más abajo.
  const context = {
    ...previewContextFromConfig(cfg, country),
    highlightPlaceholderValues,
  };
  const priceSoles = previewFullPriceFromConfig(cfg, country);
  const comboPrice = previewComboPriceFromConfig(cfg, country);
  const basicoPrice = previewBasicoPriceFromConfig(cfg, country);
  /**
   * ¿ESTO LE SALE DE VERDAD A ESTA TIENDA Y EN ESTE PAÍS?
   *
   * ── EL PROBLEMA, CON SUS PALABRAS ────────────────────────────────────
   *
   * «el visor de recorrido está mostrando cualquier cosa… en el mismo visor veo Perú,
   * Ecuador, Argentina, está hecho un safarrancho». Y tenía razón: el visor pintaba TODOS
   * los cajones que existen. Recibía el país, pero solo lo usaba para los PRECIOS — nunca
   * para decidir qué enseñar.
   *
   * ── POR QUÉ SE USAN LAS FUNCIONES DEL MOTOR Y NO UNAS PROPIAS ───────
   *
   * Un visor con su propia regla es un visor que puede mentir, y él lo pidió expreso:
   * «muchísimo cuidado que no vaya a salir información falsa». `soloDeSuTienda` es LA MISMA
   * que usa el bot, y vive en su propio archivo precisamente para poder leerse desde aquí.
   *
   * ── Y EL PAÍS VA POR EL MISMO MOLDE, QUE NO ES OBVIO ────────────────
   *
   * La bandera no filtra «los que son de Perú»: funciona como la etiqueta de tienda —si hay
   * alguno con la bandera del cliente juegan SOLO ésos; si no hay ninguno, juegan los que no
   * llevan bandera—. Por eso se pasa por la misma función con otro extractor, en vez de
   * escribir un filtro nuevo que se parecería pero no sería igual.
   *
   * `pais_routing_enabled === false` deja el grupo SIN bandera a propósito: es su forma de
   * probar sin borrar el etiquetado.
   */
  const banderasDe = (g: { paises?: string[] | null; pais_routing_enabled?: boolean }) =>
    g?.pais_routing_enabled === false
      ? []
      : (g?.paises ?? []).map((p) => String(p ?? "").trim().toUpperCase()).filter(Boolean);
  /**
   * SE FILTRA LA LISTA ENTERA, NO PIEZA A PIEZA. Y la diferencia no es un detalle:
   *
   * La regla es «si hay alguno con la bandera del cliente, juegan SOLO ésos». Mirando una
   * pieza sola eso no se puede saber, así que un cajón SIN bandera pasaría el filtro aunque
   * exista otro de Perú — y el bot usaría el de Perú. El visor enseñaría uno y el cliente
   * recibiría otro, que es exactamente lo que él pidió evitar.
   *
   * Por eso esto recibe la lista completa y devuelve la que de verdad juega.
   */
  // El tipo se deja suelto y el ajuste se hace DENTRO, en los dos extractores: atarlo en la
  // firma hacía que TypeScript perdiera el resto de campos de la pieza —`steps`, `label`,
  // `sourceIndex`— y el visor dejaba de saber qué dibujar.
  // RECIBE LA TIENDA, no la toma de fuera: desde que el visor enseña VARIAS columnas a la
  // vez, cada una pregunta por la suya. Cerrarla sobre la seleccionada haría que las dos
  // columnas enseñaran lo mismo — y eso sería mentir en dos sitios en vez de uno.
  const losQueJuegan = <T,>(lista: T[], tiendaId: string, semi: string): T[] => {
    type ConEtiquetas = {
      tiendas?: string[] | null;
      paises?: string[] | null;
      pais_routing_enabled?: boolean;
      semimodalidad?: string | null;
    };
    const deSuTienda = soloDeSuTienda(
      lista,
      (x) => tiendasDe(x as ConEtiquetas),
      tiendaId || null
    );
    /**
     * Y LA TERCERA ETIQUETA: LA SEMIMODALIDAD. Faltaba, y era el fallo que más molestaba.
     *
     * LO VIO EL DUEÑO el 06/10/2026: «todas las semimodalidades están dentro del mismo y causa
     * confusión, y esa confusión ocasiona que aparezcan el mismo producto en los 2 comodines».
     *
     * Con los cajones de COMOHOY, COMO -DOU- y COMO -OB- apilados en la misma columna, el
     * visor no enseñaba un recorrido: enseñaba tres montados. Y los comodines se resolvían
     * contra ese montón, así que el mismo producto salía en los dos huecos.
     *
     * LA SEMIMODALIDAD SALE DE LA TIENDA, que es de donde la saca el bot. Sin tienda se usa
     * «lineal», que es lo que vale cuando no hay ninguna.
     */
    const deSuSemimodalidad = porSemimodalidad(
      deSuTienda,
      (x) => semimodalidadDe(x as ConEtiquetas),
      laSemimodalidadDeLaTienda({ semimodalidad: semi })
    );
    return soloDeSuTienda(
      deSuSemimodalidad,
      (x) => banderasDe(x as ConEtiquetas),
      String(country ?? "").toUpperCase()
    );
  };
  /**
   * LO MISMO, PERO SIN LA RED DE SEGURIDAD — y solo para el visor.
   *
   * ── POR QUE HACE FALTA UNA VERSION DISTINTA ──────────────────────────
   *
   * `porSemimodalidad` acaba con «y si no hay ninguna etiquetada ni ninguna general, devuelve
   * TODAS». En el motor eso es sagrado: un cliente sin cajon es una venta perdida segura, y
   * el dueño eligió esa red a sabiendas el 30/09/2026.
   *
   * EN EL VISOR ES EXACTAMENTE EL FALLO QUE ÉL REPORTA: «en el visor de como lineal hay
   * seguimientos de comodou y como ob». La red llena las tres columnas con lo mismo, y
   * entonces el visor no enseña tres recorridos: enseña tres veces todo.
   *
   * AQUI SE PREFIERE EL HUECO: si a esta semimodalidad no le toca nada, no sale nada — y eso
   * se dice, que es informacion util. El visor no vende; informa.
   */
  // `pais`: el de la columna (17/10/2026: una columna por país desde la pizarra). Sin él, el
  // país del visor, como siempre.
  const soloLoEtiquetado = <T,>(lista: T[], tiendaId: string, semi: string, pais: string = country): T[] => {
    type ConEtiquetas = {
      tiendas?: string[] | null;
      paises?: string[] | null;
      pais_routing_enabled?: boolean;
      semimodalidad?: string | null;
    };
    const deSuTienda = soloDeSuTienda(
      lista,
      (x) => tiendasDe(x as ConEtiquetas),
      tiendaId || null
    );
    const activa = laSemimodalidadDeLaTienda({ semimodalidad: semi });
    const suyas = deSuTienda.filter(
      (x) => semimodalidadDe(x as ConEtiquetas) === activa
    );
    // Sin ninguna etiquetada se usan las generales. Quien no etiqueta nada ve lo de siempre;
    // lo que NO pasa es caer a «todas», que es lo que mezclaba las tres.
    const deSuSemi =
      suyas.length > 0
        ? suyas
        : deSuTienda.filter((x) => semimodalidadDe(x as ConEtiquetas) === null);
    return soloDeSuTienda(
      deSuSemi,
      (x) => banderasDe(x as ConEtiquetas),
      String(pais ?? "").toUpperCase()
    );
  };
  const intros = (channelUsesOwnContent
    ? channelContent.intro_groups.map((group) => ({ ...group, label: group.name }))
    : activeIntroGroupsForEditor(cfg)
  )
    // El índice de origen se conserva: al ocultar una intro apagada, su posición
    // visual deja de coincidir con la posición real que se debe editar.
    .map((group, sourceIndex) => ({ ...group, sourceIndex }))
    .filter((group) => group.sourceIndex === 0 || group.enabled !== false);
  // LAS QUE DE VERDAD JUEGAN EN ESTA TIENDA Y ESTE PAÍS. El `sourceIndex` ya está puesto
  // ARRIBA, así que filtrar aquí no mueve ningún índice: el número con el que se edita una
  // burbuja desde el visor sigue apuntando a la misma de siempre.
  const sourceFollowups = channelUsesOwnContent ? channelContent.followups : cfg.followups;
  /**
   * LO QUE LE SALE A UNA TIENDA, para poder enseñar varias a la vez.
   *
   * Antes esto se calculaba una sola vez, para la tienda del selector. Al pasar a columnas en
   * paralelo cada una necesita lo SUYO, asi que se convierte en una funcion. El cuerpo de
   * abajo no cambia: recibe las mismas dos listas con los mismos nombres.
   */
  // `ruta`: el camino que se está mirando (20/10/2026: «el visor debería tener esa capacidad de
  // verlas cuando yo lo decida, en un caso la A o en otro la B, sin perder de vista los otros
  // países»). Sin ruta, todo lo que juega, como siempre. Con ruta, la MISMA regla del bot
  // (`porCamino`): lo de ese camino y nada más.
  const loQueSaleEn = (tiendaId: string, semi: string, pais: string = country, ruta?: string) => {
    const enLaRuta = <T,>(lista: T[]): T[] =>
      ruta === undefined ? lista : porCamino(lista, (x) => caminosDe(x as { camino?: unknown; tambien_en_caminos?: unknown }), ruta);
    const introsQueJuegan = enLaRuta(soloLoEtiquetado(intros, tiendaId, semi, pais));
    /**
     * LAS ETIQUETAS DE SUS SEGUIMIENTOS ESTAN EN LAS VARIANTES, NO EN EL CONTENEDOR.
     *
     * ── LO QUE SE MIDIO, y es el porqué de todo esto ─────────────────────
     *
     * Él reportó que el visor de COMO HOY enseñaba seguimientos de -DOU- y de -OB-. Al medir
     * su configuración aparecieron SOLO TRES seguimientos —`seguimiento_1`, `_2` y `_3`— y
     * NINGUNO con etiqueta de semimodalidad.
     *
     * Las etiquetas viven una capa más adentro: en las VARIANTES. «SEGUIMIENTO LINEAL PERU»
     * y «SEGUIMIENTO PRUEBA DOU PERU» no son seguimientos distintos — son variantes del
     * mismo, y cada una lleva su tienda, su bandera y su semimodalidad. Es también donde
     * decide el motor: su registro dice «arranca SEGUIMIENTO LINEAL PERU», que es el nombre
     * de una variante.
     *
     * Filtrar el contenedor no quitaba nada, porque el contenedor no lleva etiqueta. Por eso
     * salían las tres mezcladas.
     *
     * SE FILTRA ANTES DE NUMERAR LAS VARIANTES, no: se numeran y después se filtran, igual
     * que los seguimientos. El índice de la variante es con el que se guarda al editarla
     * desde aquí, y moverlo escribiría en la de al lado — eso ya costó caro en septiembre.
     */
    const seguimientosQueJuegan = soloLoEtiquetado(
      sourceFollowups.map((f, followupIndex) => ({
        ...f,
        followupIndex,
        variants: enLaRuta(
          soloLoEtiquetado(
            (f.variants ?? []).map((v, variantIndex) => ({ ...v, variantIndex })),
            tiendaId,
            semi,
            pais
          )
        ),
        // Los mensajes principales también son de un camino: fuera de la ruta, no salen aquí.
        baseFueraDeLaRuta: ruta !== undefined && enLaRuta([f]).length === 0,
      })),
      tiendaId,
      semi,
      pais
    );
    // LA INTRO DE ORDER BUMP DE ESTA COLUMNA (17/10/2026): «ahí también debe entrar la intro de
    // order bump luego del seguimiento, ya que necesito revisarla». Solo en COMO -OB-, que es
    // la única forma que la tiene. Del mismo sitio del que la lee el bot: los cajones del canal
    // si tiene, si no los de la modalidad; filtrados por tienda, forma y país como lo demás.
    const cajonesDeLaOferta = (
      channelUsesOwnContent && (channelContent.order_bump_intro_groups ?? []).length > 0
        ? channelContent.order_bump_intro_groups ?? []
        : cfg.order_bump?.intro_groups ?? []
    )
      .map((g, sourceIndex) => ({ ...g, sourceIndex }))
      .filter((g) => g.enabled !== false && compactSteps(g.steps ?? []).length > 0);
    const ofertaQueJuega =
      laSemimodalidadDeLaTienda({ semimodalidad: semi }) === "ob"
        ? enLaRuta(soloLoEtiquetado(cajonesDeLaOferta, tiendaId, semi, pais))
        : [];
    return { introsQueJuegan, seguimientosQueJuegan, ofertaQueJuega };
  };
  const calcularFollowups = (
    seguimientosQueJuegan: ReturnType<typeof loQueSaleEn>["seguimientosQueJuegan"]
  ) =>
    seguimientosQueJuegan.flatMap((followup) => {
    const followupIndex = followup.followupIndex;
    if (followup.enabled === false) return [];
    return [
      // Sus mensajes principales, salvo que sean de otra ruta que la que se mira.
      ...((followup as { baseFueraDeLaRuta?: boolean }).baseFueraDeLaRuta ? [] : [{
        title: followup.name || `Seguimiento ${followupIndex + 1}`,
        steps: followup.steps,
        followupIndex,
        // CUÁNDO SALE. Viaja con el seguimiento para poder escribirlo al lado del título:
        // sin el tiempo, el visor enseña el orden pero no el recorrido.
        minutos: followup.delay_minutes_from_first_message,
        editorPrefix: channelUsesOwnContent
          ? `channel_${channel}_followup_${followupIndex}`
          : `fu${followupIndex}`,
        target: {
          tab: (channelUsesOwnContent ? "canales" : "seguimientos") as Tab,
          id: channelUsesOwnContent ? `canal-${channel}` : `journey-followup-${followupIndex}-base`,
          openKeys: channelUsesOwnContent
            ? [`channel_${channel}_followups`, `channel_${channel}_own_followup_${followupIndex}`, `channel_${channel}_own_followup_${followupIndex}_steps`]
            : [`followup:${followupIndex}:variant:base`],
        },
      }]),
      /**
       * EL ÍNDICE DE LA VARIANTE ES EL DE VERDAD, NO EL DE LO QUE SE VE.
       *
       * LO QUE CONTÓ EL DUEÑO — 21 de septiembre de 2026, después de que le
       * entregara dos arreglos que NO eran éste:
       *
       *   «En el pop up del seguimiento 2, modo recorrido, hago un cambio y le
       *    doy guardar: el cambio no se realiza. Cierro el pop up y el contenido
       *    sigue igual sin actualizarse.»
       *
       * QUÉ PASABA, medido con su contenido real. Su seguimiento 2 tiene DOS
       * variantes y la primera está APAGADA. Aquí se FILTRABA primero y se
       * numeraba después, así que a la variante que él ve —la segunda de la
       * lista— se le ponía el número 0. Y el guardado escribe por ese número en
       * la lista COMPLETA: su texto acababa dentro de la variante apagada.
       *
       * Se guardaba de verdad. En el sitio equivocado, y en uno que no se ve.
       *
       * ESTE ARREGLO YA EXISTÍA DOS LÍNEAS MÁS ARRIBA, en las intros, con un
       * comentario que describe este mismo fallo: «al ocultar una intro apagada,
       * su posición visual deja de coincidir con la posición real que se debe
       * editar». Llegó a las intros y no a las variantes de los seguimientos —
       * por eso la intro guardaba bien y el seguimiento no.
       *
       * Y NO ERA SOLO EL GUARDADO: el `id` y las `openKeys` de abajo también
       * llevaban el número corrido, así que «ir a editarlo» abría otra variante.
       */
      // EL ÍNDICE VIENE PUESTO DESDE ARRIBA, no se vuelve a contar aquí.
      //
      // Las variantes llegan YA FILTRADAS por tienda, semimodalidad y bandera —es donde viven
      // esas etiquetas—, así que numerarlas ahora daría la posición de LO QUE SE VE y no la
      // de verdad. Guardar por ese número escribiría en la variante de al lado, que es
      // exactamente el fallo que él reportó el 21/09/2026 y que está contado aquí debajo.
      ...(followup.variants ?? [])
        .map((variant, i) => ({
          variant,
          // SE NUMERA ANTES DE FILTRAR, y además se respeta el número que ya traiga.
          //
          // Las variantes llegan YA FILTRADAS por tienda, semimodalidad y bandera —ahí viven
          // esas etiquetas—, y en ese filtrado se les pegó su posición REAL. Si aquí se
          // volviera a contar, la numeración sería la de LO QUE SE VE, y guardar por ese
          // número escribiría en la variante de al lado. Es el fallo del 21/09/2026.
          //
          // El `?? i` no es adorno: si algún día llegan sin pasar por ese filtro, se numeran
          // aquí antes de quitar las apagadas, que es lo que esta cadena siempre garantizó.
          variantIndex: (variant as { variantIndex?: number }).variantIndex ?? i,
        }))
        .filter(({ variant }) => variant.enabled !== false)
        .map(({ variant, variantIndex }) => ({
          title: variant.name || `Variante ${variantIndex + 2}`,
          steps: variant.steps,
          followupIndex,
          // La variante sale a la MISMA hora que su seguimiento: es la misma cita, dicha de
          // otra forma. Sin esto, las variantes aparecerían sin tiempo al lado.
          minutos: followup.delay_minutes_from_first_message,
          editorPrefix: channelUsesOwnContent
            ? `channel_${channel}_followup_${followupIndex}_variant_${variantIndex}`
            : `fu${followupIndex}:variant${variantIndex}`,
          target: {
            tab: (channelUsesOwnContent ? "canales" : "seguimientos") as Tab,
            id: channelUsesOwnContent ? `canal-${channel}` : `journey-followup-${followupIndex}-variant-${variantIndex}`,
            openKeys: channelUsesOwnContent
              ? [`channel_${channel}_followups`, `channel_${channel}_own_followup_${followupIndex}`, `channel_${channel}_own_followup_${followupIndex}_variants`, `channel_${channel}_own_followup_${followupIndex}_variant_${variantIndex}`]
              : [`followup:${followupIndex}:variant:${variantIndex + 1}`],
          },
        })),
    ].filter((entry) => compactSteps(entry.steps).length > 0);
    });
  /**
   * LAS COLUMNAS QUE SE DIBUJAN, de izquierda a derecha.
   *
   * LO PIDIO EL DUEÑO el 06/10/2026, y lo decidio el a mitad de frase: pensaba en que
   * crecieran del centro hacia los lados y se corrigio solo — «mejor sabes que? que se
   * alineen como el testeador, ese tiene de izquierda a derecha bien bonito y cuando agrego
   * mas ventanas puedo correr la barrita».
   *
   * Y TENIA RAZON: creciendo desde el centro, añadir una columna mueve todas las demas y
   * pierdes de vista la que estabas leyendo. De izquierda a derecha, lo que ya miras se queda
   * quieto.
   *
   * SIN TIENDAS SE DIBUJA UNA SOLA COLUMNA, la de siempre, con la tienda vacia. Quien no las
   * usa no nota absolutamente nada.
   */
  /**
   * UNA COLUMNA POR SEMIMODALIDAD, Y POR TIENDA SI PIDE VER TODAS.
   *
   * LO PIDIÓ ASÍ el 06/10/2026, despues de ver la primera version: «en un visor aparezcan solo
   * lo lineal, en otro solo lo comodou, en otro lo comoob… Y QUE muestre por tienda cuando yo
   * ponga "ver todas"».
   *
   * ANTES ERA UNA COLUMNA POR TIENDA, con la semimodalidad que esa tienda tuviera puesta. Eso
   * enseñaba un solo recorrido de los tres, y los otros dos quedaban invisibles — justo los
   * que él quiere comparar antes de decidir cuál vende mejor.
   */
  const LAS_TRES: { semi: string; nombre: string }[] = [
    { semi: "", nombre: "COMO HOY" },
    { semi: "dos_juntas", nombre: "COMO -DOU-" },
    { semi: "segunda_oculta", nombre: "COMO -OB-" },
  ];
  const tiendasAVer =
    tiendasDelProyecto.length === 0
      ? [{ id: "", nombre: "", color: "" }]
      : verTodasLasTiendas
        ? tiendasDelProyecto.map((t, i) => ({
            id: String(t.id),
            nombre: t.nombre?.trim() || `Tienda ${i + 1}`,
            color: String(t.color ?? "").trim(),
          }))
        : [
            {
              id: tiendaDelVisor,
              nombre:
                tiendasDelProyecto.find((t) => t.id === tiendaDelVisor)?.nombre?.trim() ||
                "Sin tienda",
              color: String(
                tiendasDelProyecto.find((t) => t.id === tiendaDelVisor)?.color ?? ""
              ).trim(),
            },
          ];
  /**
   * DESDE LA PIZARRA: UNA COLUMNA POR PAÍS (17/10/2026). «quisiera ver el recorrido de la pizarra
   * de las que están ahí, en su semimodalidad… si están trabajando Argentina, Ecuador, Perú,
   * Colombia, deberían aparecer… en sus visores respectivos». La forma de vender es la de SU
   * tienda —no las tres— y cada columna resuelve con SU país: lo que le llega, sus precios.
   */
  const porPaises = (paisesDeLaPizarra ?? []).length > 0 && !verTodasLasTiendas;
  const semiDeLaTienda = String(tiendasDelProyecto.find((t) => t.id === tiendaDelVisor)?.semimodalidad ?? "");
  const columnas = (
    porPaises
      ? (paisesDeLaPizarra ?? []).map((pais) => {
          const t = tiendasAVer[0];
          const forma = LAS_TRES.find((s) => s.semi === semiDeLaTienda) ?? LAS_TRES[0];
          // (La etiqueta del país ya lleva su bandera delante.)
          const nombre = COUNTRY_OPTIONS.find((o) => o.code === pais)?.label ?? `${banderaDe(pais)} ${pais}`;
          return {
            ...t,
            semi: forma.semi,
            pais,
            rotulo: `${nombre} · ${forma.nombre}`,
            clave: `${t.id}|${forma.semi}|${pais}`,
          };
        })
      : tiendasAVer.flatMap((t) =>
          LAS_TRES.map((s) => ({
            ...t,
            semi: s.semi,
            pais: country as string,
            // El rótulo lleva la tienda SOLO cuando hay varias: con una, repetir su nombre tres
            // veces es ruido.
            rotulo: verTodasLasTiendas ? `${t.nombre} · ${s.nombre}` : s.nombre,
            clave: `${t.id}|${s.semi}`,
          }))
        )
  )
    .map((col) => {
      /**
       * QUÉ PRODUCTOS JUEGA ESTA COLUMNA, dicho en la cabecera.
       *
       * LO PROPUSE Y LO APROBÓ EL DUEÑO el 06/10/2026, buscando por qué le salía el producto
       * de la otra tienda. El problema no era solo el fallo: era que para comprobarlo había
       * que LEER LAS BURBUJAS y adivinar si el comodín se resolvió bien.
       *
       * Con el nombre en la chapa se ve antes de leer nada. Y si algún día vuelve a salir
       * mal, el rótulo lo dice en vez de esconderlo entre el texto.
       */
      const suCfg = configDeLaColumna(col.id, col.semi);
      const ctx = previewContextFromConfig(suCfg, col.pais as CountryCode);
      const uno = ctx.productName?.trim();
      const dos = ctx.product2Name?.trim();
      const vende = [uno, dos && dos !== uno ? dos : null].filter(Boolean).join(" + ");
      return { ...col, vende };
    })
    .flatMap((col) => {
    // LAS RUTAS DE ESTA COLUMNA: los caminos de sus intros (cada intro abre el suyo). Con dos o
    // más, pestañas; cada una con su parte del sorteo, por el peso de sus intros.
    const todasLasIntros = loQueSaleEn(col.id, col.semi, col.pais).introsQueJuegan;
    const caminosDeLaIntro = (g: unknown) => caminosDe(g as { camino?: unknown; tambien_en_caminos?: unknown });
    const caminosDeLaColumna = [...new Set(todasLasIntros.flatMap((g) => caminosDeLaIntro(g)))].sort();
    const pesoDeLaRuta = (c: string) =>
      todasLasIntros.filter((g) => caminosDeLaIntro(g).includes(c)).reduce((t, g) => t + Math.max(0, Number((g as { weight?: number }).weight ?? 1) || 0), 0);
    const pesoTotal = caminosDeLaColumna.reduce((t, c) => t + pesoDeLaRuta(c), 0) || 1;
    const rutas =
      caminosDeLaColumna.length > 1
        ? caminosDeLaColumna.map((c) => ({ camino: c, texto: `Ruta ${c || "A"}`, pct: Math.round((100 * pesoDeLaRuta(c)) / pesoTotal) }))
        : [];
    const elegida = rutas.length > 0 ? (caminosDeLaColumna.includes(rutaElegida[col.clave] ?? "\u0000") ? rutaElegida[col.clave] : caminosDeLaColumna[0]) : undefined;
    // UNA COLUMNA CON SU RUTA. `partida`: es una de las de «⇆ A y B lado a lado».
    const armar = (ruta: string | undefined, partida: boolean) => {
    const { introsQueJuegan, seguimientosQueJuegan, ofertaQueJuega } = loQueSaleEn(col.id, col.semi, col.pais, ruta);
    /**
     * Y SU PROPIO CONTEXTO: es lo que arregla el comodín repetido.
     *
     * Cada columna resuelve sus comodines y sus precios con la configuración de SU
     * semimodalidad y SU tienda. Compartir uno solo —como hasta ahora— es lo que hacía que
     * los dos huecos enseñaran el mismo producto.
     */
    const suCfg = configDeLaColumna(col.id, col.semi);
    const suContexto = {
      ...previewContextFromConfig(suCfg, col.pais as CountryCode),
      highlightPlaceholderValues,
      // SIN ESTO, EL CONTEXTO GLOBAL PISA ESTOS NOMBRES y las tres columnas enseñan el
      // producto de la alineación general — el de la otra tienda. Ver
      // `nombresDelLlamanteMandan`, donde está medido el caso.
      nombresDelLlamanteMandan: true,
    };
    /**
     * LA ENTREGA DE LA FICHA DEL PRODUCTO QUE JUEGA ESTA TIENDA.
     *
     * Antes el visor enseñaba la entrega GENERAL (`cfg.payment_approved`), y con dos tiendas
     * vendiendo productos distintos esa entrega no es la de ninguna: le prometía al comprador
     * un enlace que no va a recibir. Ahora sale la de su ficha, que es lo que de verdad llega.
     *
     * SE MIRA EL PUESTO `unico`/`basico`, que es el producto que anuncia el recorrido. Sin
     * tienda se cae al primero del almacén, que es el comportamiento de siempre.
     */
    const almacen = cfg.biblioteca_de_productos ?? [];
    /**
     * UNA ENTREGA POR PRODUCTO QUE JUEGA, NO UNA SOLA.
     *
     * LO PIDIO EL 07/10/2026: «en comolineal hay 1 sola entrega, pero en comodou y como ob son
     * 2 entregas y esta mostrando solo 1».
     *
     * Tiene razon, y es importante: en esas dos el cliente puede comprar el basico O el full, y
     * cada uno entrega SU material. Enseñar una sola entrega le escondia la mitad de lo que su
     * bot promete — y justo la mitad que mas cuesta revisar, porque es la que llega despues de
     * cobrar.
     *
     * SE PREGUNTA POR LOS PUESTOS, NO POR EL NOMBRE DE LA MODALIDAD. `puestoDelCajonDeContenido`
     * ya sabe que juega cada columna: en lineal devuelve un puesto y en las prestadas devuelve
     * full y basico. Asi, el dia que el mueva un producto de sitio, la entrega le sigue sola.
     * Una condicion escrita a mano con los nombres de las modalidades es justo el fallo que este
     * proyecto ya ha pagado tres veces.
     *
     * SE QUITAN LOS REPETIDOS: si el mismo producto ocupa dos puestos, su entrega es una.
     */
    const suTienda = tiendasDelProyecto.find((t) => t.id === col.id);
    const alineados = {
      ...(cfg.alineacion_por_modalidad?.[activeModality(suCfg)] ?? {}),
      ...Object.fromEntries(
        Object.entries(suTienda?.alineacion ?? {}).filter(([, v]) => v)
      ),
    } as Record<string, string | undefined>;
    const puestosQueJuegan = ([1, 2] as const)
      .map((cajon) => puestoDelCajonDeContenido(activeModality(suCfg), cajon, suCfg))
      .filter((p): p is PuestoDeProducto => Boolean(p));
    const idsQueEntregan = [
      ...new Set(
        puestosQueJuegan.map((p) => alineados[p]).filter((id): id is string => Boolean(id))
      ),
    ];
    const fichasQueEntregan = (
      idsQueEntregan.length > 0
        ? idsQueEntregan.map((id) => almacen.find((p) => p?.id === id))
        : [almacen[0]]
    ).filter(Boolean);
    return {
      ...col,
      // Partida, cada ruta es su propia columna: su propia clave (para plegarla) y su nombre.
      clave: partida ? `${col.clave}|ruta:${ruta ?? ""}` : col.clave,
      rotulo: partida ? `${col.rotulo} · Ruta ${ruta || "A"}` : col.rotulo,
      claveDelPais: col.clave,
      partida,
      rutas,
      ruta,
      introsQueJuegan,
      followups: calcularFollowups(seguimientosQueJuegan),
      // Cada una con su nombre delante: sin el no se sabe cual de las dos se esta leyendo.
      entregasDeLasFichas: fichasQueEntregan.map((ficha) => ({
        nombre: ficha?.name?.trim() || "sin producto",
        pasos: (ficha?.delivery ?? []) as EditorStep[],
      })),
      // LA CONFIGURACION DE ESTA COLUMNA VIAJA ENTERA. Los precios con descuento de los
      // seguimientos se calculan por seguimiento, asi que no basta con llevar el numero ya
      // resuelto: hace falta la configuracion para pedirselos uno a uno. Ver el bloque de
      // seguimientos, donde esto arregla el «[precio full sin configurar]».
      suCfg,
      suContexto,
      ofertaQueJuega,
      suPrecio: previewFullPriceFromConfig(suCfg, col.pais as CountryCode),
      suCombo: previewComboPriceFromConfig(suCfg, col.pais as CountryCode),
      suBasico: previewBasicoPriceFromConfig(suCfg, col.pais as CountryCode),
    };
    };
    // «⇆ A Y B LADO A LADO» (20/10/2026): las rutas de este país en columnas juntas, para comparar
    // mensaje por mensaje. Los demás países no cambian.
    if (ladoALado.has(col.clave) && rutas.length > 1) return rutas.map((r) => armar(r.camino, true));
    return [armar(elegida, false)];
  });
  const bumpStages =
    mode === "order_bump"
      ? [
          {
            title: "Presentación de las 2 opciones",
            steps: cfg.order_bump.intro,
            target: { tab: "orderbump" as const, id: "journey-order-bump" },
          },
          {
            title: cfg.order_bump.combo.name || "Opción Combo",
            steps: cfg.order_bump.combo.response,
            target: { tab: "orderbump" as const, id: "journey-order-bump" },
          },
          {
            title: cfg.order_bump.basico.name || "Opción Básico",
            steps: cfg.order_bump.basico.response,
            target: { tab: "orderbump" as const, id: "journey-order-bump" },
          },
        ].filter((entry) => compactSteps(entry.steps).length > 0)
      : [];
  const paymentProfile =
    cfg.modality_payment_profiles?.[mode]?.[country] ??
    cfg.payment_profiles_by_country?.[country];
  const updatePaymentResponseSteps = (method: string, steps: EditorStep[]) => {
    const resolvedProfile = (paymentProfile ?? {}) as CountryPaymentProfileEditor;
    onConfigChange({
      ...cfg,
      modality_payment_profiles: {
        ...cfg.modality_payment_profiles,
        [mode]: {
          ...cfg.modality_payment_profiles?.[mode],
          [country]: {
            ...resolvedProfile,
            payment_responses: {
              ...(resolvedProfile.payment_responses ?? {}),
              [method]: steps,
            },
          },
        },
      },
    });
  };
  const paymentStages: Array<{
    title: string;
    steps: EditorStep[];
    onStepsChange?: (steps: EditorStep[]) => void;
  }> = channelUsesOwnContent
    ? [{ title: "Pago del canal", steps: channelContent.payment }]
    : [
    ...(paymentProfile?.payment_text?.trim()
      ? [{
          title: "Elección de método de pago",
          steps: [textStep(paymentProfile.payment_text)],
        }]
      : []),
    ...Object.entries(paymentProfile?.payment_responses ?? {}).map(([method, steps]) => ({
      title: `Datos de pago: ${paymentProfile?.payment_buttons.find((button) => button.method === method)?.label || method}`,
      steps,
      onStepsChange: (next: EditorStep[]) => updatePaymentResponseSteps(method, next),
    })),
  ].filter((entry) => compactSteps(entry.steps).length > 0);
  // ChatPreview oculta los pasos OFF. Aquí conservamos el arreglo completo para
  // que mover una burbuja visible nunca descarte las que están apagadas.
  const deliverySteps = channelUsesOwnContent ? channelContent.delivery : cfg.payment_approved;
  const countryLabel = COUNTRY_OPTIONS.find((item) => item.code === country)?.label ?? country;

  return (
    <div
      className={
        // «◧ VER CON LA PIZARRA» (20/10/2026): el visor a la derecha y la pizarra viva a la izquierda,
        // con la ruta elegida iluminada. Sin fondo oscuro: la pizarra se ve y se usa.
        conLaPizarra
          ? "pointer-events-none fixed inset-y-0 right-0 z-50 flex w-[46vw] min-w-[420px] p-2"
          : "fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-3 sm:p-6"
      }
      role="dialog"
      aria-modal={!conLaPizarra}
      aria-labelledby="journey-preview-title"
      onMouseDown={(event) => {
        if (!EL_CLIC_FUERA_CIERRA_LA_VENTANA) return;
        if (event.target === event.currentTarget) onClose();
      }}
    >
      {/* LA VENTANA OCUPA LA PANTALLA; EL CHAT ES EL QUE MIDE UN CELULAR.

          LO PIDIÓ EL DUEÑO el 06/10/2026 despues de verlo: «solo lo necesito en ancho de
          celular, pero que se parezca al visor del modo testeo… el modo testeo abarca todo el
          ancho de la pantalla, el chat alineado a la izquierda y el siguiente a su derecha».

          ANTES ERA AL REVES, y ahi estaba el problema: la VENTANA media 390px, asi que el
          recorrido salia centrado en una columna estrecha y no cabia nada al lado. Con dos
          tiendas no habia sitio para la segunda.

          AHORA EL ANCHO DE «celular» ES EL DEL CHAT, no el de la ventana — que es lo que ese
          selector siempre quiso decir. */}
      <div
        className={`pointer-events-auto flex w-full flex-col overflow-hidden rounded-lg bg-tarjeta shadow-2xl ${
          conLaPizarra ? "h-full border border-neutral-300" : "h-[min(92vh,960px)] max-w-[98vw]"
        }`}
      >
        <div className="flex flex-wrap items-center justify-between gap-3 border-b border-neutral-200 px-4 py-3 sm:px-5">
          <div>
            <h2 id="journey-preview-title" className="flex items-center gap-2 text-base font-bold text-neutral-900">
              Recorrido completo
              {/* LAS DOS FORMAS (20/10/2026): todos los países lado a lado, o junto a la pizarra. */}
              {paisesDeLaPizarra && paisesDeLaPizarra.length > 0 && (
                <button
                  type="button"
                  onClick={() => {
                    const ahora = !conLaPizarra;
                    setConLaPizarra(ahora);
                    // Al ponerlo junto a la pizarra, se ilumina ya la ruta que se mira: la de la
                    // primera columna con varias rutas, o la primera columna.
                    if (ahora) {
                      const col = columnas.find((c) => c.rutas.length > 0) ?? columnas[0];
                      if (col?.pais) iluminarEnLaPizarra(col.pais, col.ruta ?? "", true);
                    }
                  }}
                  data-visor-con-pizarra
                  title={conLaPizarra ? "Volver a ver todos los países lado a lado" : "El visor a la derecha y la pizarra a la vista, con la ruta elegida iluminada"}
                  className="rounded-md border border-neutral-300 px-2 py-0.5 text-[11px] font-semibold text-neutral-700 hover:bg-neutral-50"
                >
                  {conLaPizarra ? "⬚ Visor completo" : "◧ Ver con la pizarra"}
                </button>
              )}
            </h2>
            <p className="text-xs text-neutral-500">{MODALIDAD_LABEL[mode]} · {countryLabel} · {channelUsesOwnContent ? `textos propios de ${CHANNEL_PROTOTYPE_META[channel].name}` : "Base (el canal no tiene textos propios activos)"}</p>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            {/* QUÉ TIENDA SE MIRA. Solo aparece si tiene tiendas: quien no las usa no ve
                un selector de algo que no tiene.

                Va al lado del canal porque son la misma clase de pregunta —«¿de quién es
                este recorrido?»— y porque los dos cambian lo que se enseña debajo. */}
            {tiendasDelProyecto.length > 0 && (
              <select
                value={tiendaDelVisor}
                onChange={(event) => setTiendaDelVisor(event.target.value)}
                disabled={verTodasLasTiendas}
                title="De qué tienda es este recorrido"
                className="rounded border border-teal-300 bg-teal-50 px-2 py-1.5 text-xs font-semibold text-teal-900 disabled:opacity-40"
              >
                {tiendasDelProyecto.map((t, i) => (
                  <option key={t.id} value={t.id}>
                    🏪 {t.nombre?.trim() || `Tienda ${i + 1}`}
                  </option>
                ))}
                {/* «SIN TIENDA» YA NO ESTÁ, y se quita a propósito.

                    Enseñaba la alineación GENERAL, que no es el recorrido de nadie: quien
                    tiene tiendas vende siempre por una de ellas. Y con su configuración
                    pasaba lo peor — la general apunta al producto de la OTRA tienda, así
                    que elegirla sin querer enseñaba un nombre equivocado que parecía un
                    fallo del visor. Un sitio donde solo se puede uno equivocar, no debería
                    existir. */}
              </select>
            )}
            {/* VER TODAS A LA VEZ. Solo con dos o mas: con una sola tienda, ponerlas «en
                paralelo» no enseña nada que no esté ya en pantalla. */}
            {tiendasDelProyecto.length > 1 && (
              <button
                type="button"
                onClick={() => setVerTodasLasTiendas((v) => !v)}
                title="Ver todas las tiendas una al lado de otra"
                className={`rounded border px-2 py-1.5 text-xs font-semibold ${
                  verTodasLasTiendas
                    ? "border-teal-500 bg-teal-500 text-white"
                    : "border-teal-300 bg-teal-50 text-teal-900 hover:bg-teal-100"
                }`}
              >
                {verTodasLasTiendas
                  ? `◧ viendo las ${tiendasDelProyecto.length}`
                  : "◧ ver todas"}
              </button>
            )}
            <select value={channel} onChange={(event) => setChannel(event.target.value as ChannelKey)} className="rounded border border-violet-300 bg-violet-50 px-2 py-1.5 text-xs font-semibold text-violet-900">
              {CHANNEL_KEYS.filter((item) => item !== "tiktok").map((item) => <option key={item} value={item}>{CHANNEL_PROTOTYPE_META[item].name}</option>)}
            </select>
            <select value={previewWidth} onChange={(event) => setPreviewWidth(event.target.value as "mobile" | "normal" | "wide")} title="Ancho de cada chat (la ventana ya ocupa la pantalla)" className="rounded border border-neutral-300 bg-tarjeta px-2 py-1.5 text-xs text-neutral-700">
              <option value="mobile">Celular</option><option value="normal">Normal</option><option value="wide">Ancho</option>
            </select>
            <button type="button" onClick={onUndo} disabled={undoCount === 0 || saving} title="Deshacer el último cambio" className="rounded border border-neutral-300 bg-tarjeta px-3 py-1.5 text-xs font-medium text-neutral-700 hover:bg-neutral-50 disabled:opacity-40">↶ Deshacer{undoCount ? ` (${undoCount})` : ""}</button>
            <button type="button" onClick={onRedo} disabled={redoCount === 0 || saving} title="Rehacer el cambio deshecho" className="rounded border border-neutral-300 bg-tarjeta px-3 py-1.5 text-xs font-medium text-neutral-700 hover:bg-neutral-50 disabled:opacity-40">Rehacer{redoCount ? ` (${redoCount})` : ""}</button>
            {/* APAGADO CUANDO NO HAY NADA QUE GUARDAR. Ver `hayCambios` arriba: antes
    solo se apagaba mientras guardaba, así que recién guardado seguía
    invitando a pulsarlo. Y dice «Guardado» para que se vea POR QUÉ está
    apagado, en vez de parecer que se rompió. */}
<button
  type="button"
  onClick={onSave}
  disabled={saving || !hayCambios}
  title={
    saving
      ? "Guardando…"
      : hayCambios
        ? "Sube los cambios al bot"
        : "No hay cambios sin guardar"
  }
  className="rounded border border-emerald-700 bg-emerald-600 px-3 py-1.5 text-xs font-bold text-white hover:bg-emerald-700 disabled:opacity-50"
>
  {saving ? "Guardando..." : hayCambios ? "Guardar cambios" : "Guardado"}
</button>
            <button type="button" onClick={onClose} className="rounded border border-neutral-300 px-3 py-1.5 text-xs font-medium text-neutral-700 hover:bg-neutral-50">Cerrar</button>
          </div>
        </div>
        <div className="border-b border-sky-100 bg-sky-50 px-4 py-2 text-xs text-sky-900 sm:px-5">
          <span className="mr-2 inline-block rounded border border-sky-300 bg-sky-100 px-1.5 py-0.5 font-semibold text-sky-800">Valor de comodín</span>
          Los fragmentos marcados se generan desde un comodín. Si un precio, país o receptor no está marcado, revísalo en su burbuja.
        </div>
        {/* EL CUERPO, UNA COLUMNA POR TIENDA.

            `overflow-auto` en vez de solo vertical: con varias columnas aparece la barrita
            de abajo y se corre a los lados, como el testeador. Con una sola tienda el ancho
            no llega a sobrar y la barra ni se ve, asi que quien no las usa no nota nada.

            EL CUERPO DE DENTRO NO SE REESCRIBIO: se envuelve y se le pasan las dos listas con
            los mismos nombres que tenian. Es la pieza mas larga del editor y desde ella el
            dueño edita burbujas; reescribirla para enseñar dos columnas habria sido cambiar
            lo que funciona por comodidad. */}
        <div className="flex-1 overflow-auto bg-neutral-100 p-4 sm:p-5">
          {/* CENTRADO, Y CRECIENDO HACIA LOS LADOS.

              Lo pidió así el 06/10/2026 después de verlo: «que mejor estén al centro y que
              cuando aumenten, se pongan uno al lado del otro aumentando desde el centro hacia
              los lados. Cuando hayan sobrepasado el ancho de la pantalla que haya esa barrita
              desplazable abajo».

              EL TRUCO ES `w-max mx-auto`, Y NO `justify-center`. Con `justify-center` y
              desbordamiento, el navegador recorta por la IZQUIERDA y esa parte NO SE PUEDE
              ALCANZAR con la barra: la primera columna queda inaccesible para siempre. Es un
              fallo clásico y silencioso. Una caja del ancho de su contenido con márgenes
              automáticos hace las dos cosas: se centra mientras cabe, y al no caber empieza
              por el principio y se recorre entera.

              LO QUE HABÍA ANTES, y queda escrito para que no se repita: */}
          {/* SIEMPRE PEGADO A LA IZQUIERDA, con una sola tienda o con cuatro.

              Antes esto se centraba cuando habia una sola columna, y era justo lo que a el no
              le gustaba: «en el modo testeo no aparece en el centro». Centrar deja el chat
              bailando segun cuantas tiendas tengas, y ademas mueve lo que estabas leyendo en
              cuanto enciendes «ver todas». */}
          <div className="mx-auto flex w-max items-start gap-5">
          {columnas.map((columna) => {
            const introsQueJuegan = columna.introsQueJuegan;
            const followups = columna.followups;
            const entregasDeLasFichas = columna.entregasDeLasFichas;
            // SE TAPAN LOS DE ARRIBA CON LOS DE ESTA COLUMNA. Es lo que hace que cada
            // recorrido resuelva SUS comodines y SUS precios, en vez de compartir unos
            // generales que no son de nadie — el comodín repetido salía de ahí.
            const context = columna.suContexto;
            const priceSoles = columna.suPrecio;
            const comboPrice = columna.suCombo;
            const basicoPrice = columna.suBasico;
            // PLEGADA CON EL OJO: una tira estrecha con su nombre, para volver a abrirla.
            if (plegadas.has(columna.clave)) {
              return (
                <button
                  key={columna.clave}
                  type="button"
                  onClick={() => alternarPlegada(columna.clave)}
                  title="Mostrar esta columna"
                  className="flex w-10 shrink-0 flex-col items-center gap-2 rounded-lg border border-neutral-300 bg-tarjeta py-3 text-xs font-bold text-neutral-700 hover:bg-neutral-50"
                >
                  <span>👁</span>
                  <span style={{ writingMode: "vertical-rl" }}>{columna.rotulo}</span>
                </button>
              );
            }
            return (
          <div
            key={columna.clave}
            className={`shrink-0 space-y-6 ${anchoDelChat}`}
          >
            {/* LA CHAPA DE LA COLUMNA, SIEMPRE: ahora hay tres aunque haya una sola tienda
                —COMO HOY, COMO -DOU-, COMO -OB-— y sin el rótulo son tres recorridos
                parecidos imposibles de distinguir. Lleva el color de su tienda, el mismo de
                las fachadas. */}
            {(
              <div
                className="sticky top-0 z-10 rounded-lg border px-3 py-2 text-sm font-black"
                style={
                  /^#[0-9a-fA-F]{6}$/.test(columna.color ?? "")
                    ? {
                        backgroundColor: columna.color,
                        borderColor: columna.color,
                        color: adTagTextColor(columna.color ?? ""),
                      }
                    : undefined
                }
              >
                <div className="flex items-center gap-2">
                  <span className="min-w-0 flex-1">
                    {verTodasLasTiendas ? "🏪 " : ""}
                    {columna.rotulo}
                  </span>
                  <button
                    type="button"
                    onClick={() => alternarPlegada(columna.clave)}
                    title="Ocultar esta columna (vuelve con un clic)"
                    className="shrink-0 rounded px-1 text-base leading-none opacity-80 hover:opacity-100"
                  >
                    👁
                  </button>
                </div>
                {/* QUÉ VENDE ESTA COLUMNA. Se ve antes de leer una sola burbuja: si el
                    comodín se resolvió mal, aquí sale el nombre equivocado y se caza de un
                    vistazo en vez de buscarlo dentro del texto. */}
                <div className="text-[11px] font-semibold opacity-80">
                  vende {columna.vende || "— nada: a esta tienda le falta su producto"}
                </div>
                {/* PARTIDA: esta columna es una ruta; un botón las vuelve a juntar en pestañas. */}
                {columna.partida && (
                  <div className="mt-1.5 flex flex-wrap items-center gap-1">
                    <span className="rounded-md bg-neutral-900 px-2 py-0.5 text-[11px] font-bold text-white">
                      Ruta {columna.ruta || "A"} · {columna.rutas.find((r) => r.camino === columna.ruta)?.pct ?? 0}%
                    </span>
                    <button
                      type="button"
                      onClick={() => alternarLadoALado(columna.claveDelPais)}
                      data-unir-rutas
                      title="Volver a una sola columna, con las rutas en pestañas"
                      className="rounded-md bg-white/70 px-2 py-0.5 text-[11px] font-semibold text-neutral-800 hover:bg-white"
                    >
                      ✕ Unir rutas
                    </button>
                  </div>
                )}
                {/* SUS RUTAS, EN PESTAÑAS (20/10/2026): una a la vez, sin tocar las otras columnas. */}
                {columna.rutas.length > 0 && !columna.partida && (
                  <div className="mt-1.5 flex flex-wrap gap-1" data-rutas-del-visor>
                    {columna.rutas.map((r) => (
                      <button
                        key={r.camino || "A"}
                        type="button"
                        onClick={() => elegirRuta(columna.clave, r.camino, columna.pais)}
                        title={`Lo que recibe un cliente de la ${r.texto}: ${r.pct}% de los que entran (por el peso de sus intros).`}
                        className={`rounded-md px-2 py-0.5 text-[11px] font-bold ${
                          columna.ruta === r.camino ? "bg-neutral-900 text-white" : "bg-white/70 text-neutral-800 hover:bg-white"
                        }`}
                      >
                        {r.texto} · {r.pct}%
                      </button>
                    ))}
                    <button
                      type="button"
                      onClick={() => alternarLadoALado(columna.claveDelPais)}
                      data-lado-a-lado
                      title="Ver todas las rutas de este país en columnas juntas, para comparar mensaje por mensaje"
                      className="rounded-md bg-white/70 px-2 py-0.5 text-[11px] font-semibold text-neutral-800 hover:bg-white"
                    >
                      ⇆ Lado a lado
                    </button>
                  </div>
                )}
              </div>
            )}
            <JourneyPreviewSection title="Inicio">
              {/* UN HUECO EN EL RECORRIDO SE DICE, no se deja en blanco.
                  Antes aquí salían todas las intros de todos los países y todas las
                  tiendas; ahora salen las que de verdad juegan, y si no queda ninguna eso
                  ES la noticia: ese cliente saluda y no recibe nada. */}
              {introsQueJuegan.length === 0 && (
                <p className="rounded-lg border border-red-300 bg-red-50 px-3 py-2 text-xs font-semibold text-red-800">
                  ⛔ Esta tienda no tiene ninguna presentación para este país. El cliente
                  saluda y no recibe nada.
                </p>
              )}
              {introsQueJuegan.map((group) => (
                <JourneyPreviewBlock
                  key={`${group.label}-${group.sourceIndex}`}
                  title={group.label}
                  detail={group.sourceIndex === 0 ? "Saludo" : `Variante activa · peso ${group.weight}`}
                  steps={group.steps}
                  priceSoles={priceSoles}
                  comboPrice={comboPrice}
                  basicoPrice={basicoPrice}
                  previewContext={context}
                  channelLabel={CHANNEL_PROTOTYPE_META[channel].name}
                  onSnapshot={onSnapshot}
                  onStepsChange={channelUsesOwnContent
                    ? (steps) => updateChannelContent({
                        ...channelContent,
                        intro_groups: channelContent.intro_groups.map((item, itemIndex) =>
                          itemIndex === group.sourceIndex ? { ...item, steps } : item
                        ),
                      })
                    : group.sourceIndex > 0 ? (steps) => updateBaseIntroSteps(group.sourceIndex, steps) : undefined}
                  onEdit={(stepIndex) => channelUsesOwnContent
                    ? openChannelStepEditor(group.label, group.steps, stepIndex, (steps) =>
                        updateChannelContent({
                          ...channelContent,
                          intro_groups: channelContent.intro_groups.map((item, itemIndex) =>
                            itemIndex === group.sourceIndex ? { ...item, steps } : item
                          ),
                        })
                      )
                    : onNavigate(group.sourceIndex === 0
                      ? { tab: "intro", id: "journey-intro-greeting", openKeys: ["journey:greeting"] }
                      : { tab: "intro", id: `journey-intro-${group.sourceIndex - 1}`, openKeys: [`Intro ${group.sourceIndex}`], stepId: `editor-step-intro${group.sourceIndex}-${stepIndex}` })}
                />
              ))}
            </JourneyPreviewSection>

            {followups.length > 0 && (
              <JourneyPreviewSection title="Seguimientos">
                {followups.map((followup, index) => (
                  /* LOS PRECIOS CON DESCUENTO SALEN DE LA CONFIGURACION DE ESTA COLUMNA.

                     LO REPORTO EL 07/10/2026: «en el seguimiento 2 de comodou, en el precio dice
                     "[precio full sin configurar]", y acabo de revisar y si estan los precios
                     basico y full».

                     Y los tenia. Los tres `…Override` de abajo recibian `cfg` —la configuracion
                     GENERAL—, donde su modalidad activa es LINEAL: una sola opcion.
                     `previewComboPriceFromConfig` empieza cortando con «si esta modalidad no vende
                     dos, devuelve 0», asi que el precio del full no llegaba a buscarse siquiera.

                     POR ESO SOLO FALLABA EN EL SEGUIMIENTO 2: estos tres son los precios CON
                     DESCUENTO, y el descuento empieza ahi. En el seguimiento 1 no se usan y el
                     precio salia bien — que es lo que lo hacia tan raro de mirar.

                     `suCfg` lleva puesta la semimodalidad de la columna, asi que ese corte ya no
                     se dispara y el precio sale de la ficha, como en todo lo demas. */
                  <JourneyPreviewBlock
                    key={`${followup.title}-${index}`}
                    title={followup.title}
                    detail={cuandoSale(followup.minutos)}
                    steps={followup.steps}
                    priceSoles={priceSoles}
                    comboPrice={comboPrice}
                    basicoPrice={basicoPrice}
                    previewPriceOverride={previewFullPriceForFollowup(columna.suCfg, followup.followupIndex, columna.pais as CountryCode)}
                    previewComboPriceOverride={previewOrderBumpPriceForFollowup(columna.suCfg, "combo", followup.followupIndex, columna.pais as CountryCode)}
                    previewBasicoPriceOverride={previewOrderBumpPriceForFollowup(columna.suCfg, "basico", followup.followupIndex, columna.pais as CountryCode)}
                    previewContext={context}
                    channelLabel={CHANNEL_PROTOTYPE_META[channel].name}
                    onSnapshot={onSnapshot}
                    onStepsChange={channelUsesOwnContent
                      ? (steps) => {
                          const isVariant = followup.editorPrefix.includes("_variant_");
                          const match = followup.editorPrefix.match(/followup_(\d+)(?:_variant_(\d+))?/);
                          const followupIndex = Number(match?.[1] ?? -1);
                          const variantIndex = match?.[2] === undefined ? -1 : Number(match[2]);
                          updateChannelContent({
                            ...channelContent,
                            followups: channelContent.followups.map((item, itemIndex) => {
                              if (itemIndex !== followupIndex) return item;
                              if (!isVariant) return { ...item, steps };
                              return { ...item, variants: (item.variants ?? []).map((variant, currentIndex) => currentIndex === variantIndex ? { ...variant, steps } : variant) };
                            }),
                          });
                        }
                      : (steps) => {
                          const isVariant = followup.editorPrefix.includes("variant");
                          const variantMatch = followup.editorPrefix.match(/fu(\d+):variant(\d+)/);
                          const baseMatch = followup.editorPrefix.match(/fu(\d+)/);
                          const followupIndex = Number((variantMatch ?? baseMatch)?.[1] ?? -1);
                          const variantIndex = variantMatch ? Number(variantMatch[2]) : -1;
                          onConfigChange({
                            ...cfg,
                            followups: cfg.followups.map((item, itemIndex) => {
                              if (itemIndex !== followupIndex) return item;
                              if (variantIndex < 0) return { ...item, steps };
                              return { ...item, variants: (item.variants ?? []).map((variant, currentIndex) => currentIndex === variantIndex ? { ...variant, steps } : variant) };
                            }),
                          });
                        }}
                    onEdit={(stepIndex) => channelUsesOwnContent
                    ? openChannelStepEditor(followup.title, followup.steps, stepIndex, (steps) => {
                          const isVariant = followup.editorPrefix.includes("_variant_");
                          const match = followup.editorPrefix.match(/followup_(\d+)(?:_variant_(\d+))?/);
                          const followupIndex = Number(match?.[1] ?? -1);
                          const variantIndex = match?.[2] === undefined ? -1 : Number(match[2]);
                          updateChannelContent({
                            ...channelContent,
                            followups: channelContent.followups.map((item, itemIndex) => {
                              if (itemIndex !== followupIndex) return item;
                              if (!isVariant) return { ...item, steps };
                              return {
                                ...item,
                                variants: (item.variants ?? []).map((variant, currentIndex) =>
                                  currentIndex === variantIndex ? { ...variant, steps } : variant
                                ),
                              };
                            }),
                          });
                        }, {
                          previewPriceOverride: previewFullPriceForFollowup(cfg, followup.followupIndex, country),
                          previewComboPriceOverride: previewOrderBumpPriceForFollowup(cfg, "combo", followup.followupIndex, country),
                          previewBasicoPriceOverride: previewOrderBumpPriceForFollowup(cfg, "basico", followup.followupIndex, country),
                        })
                      : onNavigate({ ...followup.target, stepId: `editor-step-${followup.editorPrefix}-${stepIndex}` })}
                  />
                ))}
              </JourneyPreviewSection>
            )}

            {/* LA INTRO DE ORDER BUMP, DESPUÉS DE LOS SEGUIMIENTOS (17/10/2026), con los precios
                NORMALES: «cuidado no se vaya a… aparecer el precio de descuento». Es lo que ve quien
                elige método antes de la etapa de descuento; si llega después, el bot le enseña los
                de descuento, y se dice. Solo en COMO -OB-. */}
            {columna.ofertaQueJuega.length > 0 && (
              <JourneyPreviewSection title="Intro de order bump">
                {columna.ofertaQueJuega.map((g) => {
                  const guardar = (steps: EditorStep[]) =>
                    channelUsesOwnContent && (channelContent.order_bump_intro_groups ?? []).length > 0
                      ? updateChannelContent({
                          ...channelContent,
                          order_bump_intro_groups: (channelContent.order_bump_intro_groups ?? []).map((item, i) =>
                            i === g.sourceIndex ? { ...item, steps } : item
                          ),
                        })
                      : onConfigChange({
                          ...cfg,
                          order_bump: {
                            ...cfg.order_bump,
                            intro_groups: (cfg.order_bump.intro_groups ?? []).map((item, i) =>
                              i === g.sourceIndex ? { ...item, steps } : item
                            ),
                          },
                        });
                  return (
                    <JourneyPreviewBlock
                      key={`ob-${g.sourceIndex}`}
                      title={g.name || `Intro de order bump ${g.sourceIndex + 1}`}
                      detail="Cuando quiere pagar o elige método · precios normales (si llega después del seguimiento con descuento, ve los de descuento)"
                      steps={g.steps ?? []}
                      priceSoles={priceSoles}
                      comboPrice={comboPrice}
                      basicoPrice={basicoPrice}
                      previewContext={context}
                      channelLabel={CHANNEL_PROTOTYPE_META[channel].name}
                      onSnapshot={onSnapshot}
                      onStepsChange={guardar}
                      onEdit={(stepIndex) => openChannelStepEditor(g.name || "Intro de order bump", g.steps ?? [], stepIndex, guardar)}
                    />
                  );
                })}
              </JourneyPreviewSection>
            )}

            {bumpStages.length > 0 && (
              <JourneyPreviewSection title="Order Bump">
                {bumpStages.map((stage, index) => (
                  <JourneyPreviewBlock
                    key={`${stage.title}-${index}`}
                    title={stage.title}
                    detail="Se muestra según la elección del cliente"
                    steps={stage.steps}
                    priceSoles={priceSoles}
                    comboPrice={comboPrice}
                    basicoPrice={basicoPrice}
                    previewContext={context}
                    channelLabel={CHANNEL_PROTOTYPE_META[channel].name}
                    onSnapshot={onSnapshot}
                    onStepsChange={(steps) => onConfigChange({
                      ...cfg,
                      order_bump: index === 0
                        ? { ...cfg.order_bump, intro: steps }
                        : index === 1
                          ? { ...cfg.order_bump, combo: { ...cfg.order_bump.combo, response: steps } }
                          : { ...cfg.order_bump, basico: { ...cfg.order_bump.basico, response: steps } },
                    })}
                    onEdit={() => onNavigate(stage.target)}
                  />
                ))}
              </JourneyPreviewSection>
            )}

            {/* LA SECCIÓN «PAGO» YA NO SE PINTA — 06/10/2026.

                La quitó él: «en este momento en el visor se está mostrando "Pago" y "Entrega",
                necesito que no esté ninguno de esos 2».

                Y tiene sentido en este visor: los datos de pago no son UN paso del recorrido,
                son la respuesta a cada método, y aquí salían los de TODOS los métodos
                seguidos — una lista que ningún cliente ve nunca así. Se siguen editando en su
                pestaña, que es donde se entienden.

                `paymentStages` se deja calculado a propósito: alimenta otras cosas de esta
                ventana y borrarlo sería quitar más de lo que se pidió. */}

            {entregasDeLasFichas.some((e) => e.pasos.length > 0) && (
              <JourneyPreviewSection title="Entrega">
                {/* LA ENTREGA SALE DE LA FICHA DEL PRODUCTO, NO DE LA GENERAL.

                    Lo pidió el 06/10/2026: «hay que reemplazar la entrega con el texto de
                    entrega que se encuentra en la ficha de producto que esté activa».

                    Y es lo correcto, porque es lo que de verdad recibe el cliente: cada
                    producto entrega SU material, y con dos tiendas vendiendo cosas distintas
                    la entrega general no es la de nadie. Enseñarla aquí era prometer un
                    enlace que ese comprador no va a recibir.

                    SE EDITA EN LA FICHA, que es donde vive. Por eso el botón lleva al almacén
                    de productos y no a la pestaña de entrega. */}
                {/* UNA POR CADA PRODUCTO QUE JUEGA ESTA COLUMNA.

                    En COMO HOY sale una. En COMO -DOU- y COMO -OB- salen DOS, porque el cliente
                    puede comprar el basico o el full y cada uno entrega su material. Lo pidio el
                    07/10/2026 y es la mitad del recorrido que antes no se veia. */}
                {entregasDeLasFichas
                  .filter((entrega) => entrega.pasos.length > 0)
                  .map((entrega) => (
                    <JourneyPreviewBlock
                      key={entrega.nombre}
                      title={`Pago aprobado · ${entrega.nombre}`}
                      detail="Lo que entrega la ficha de este producto"
                      steps={entrega.pasos}
                      priceSoles={priceSoles}
                      comboPrice={comboPrice}
                      basicoPrice={basicoPrice}
                      previewContext={context}
                      channelLabel={CHANNEL_PROTOTYPE_META[channel].name}
                      onSnapshot={onSnapshot}
                      onStepsChange={() => {}}
                      onEdit={() => onNavigate({ tab: "contenido", id: "journey-delivery" })}
                    />
                  ))}
              </JourneyPreviewSection>
            )}
          </div>
            );
          })}
          </div>
        </div>
      </div>
      {editingStep && (
        <JourneyStepEditorModal
          title={editingStep.title}
          steps={editingStep.steps}
          stepIndex={editingStep.index}
          previewContext={context}
          priceSoles={priceSoles}
          comboPrice={comboPrice}
          basicoPrice={basicoPrice}
          previewPriceOverride={editingStep.previewPriceOverride}
          previewComboPriceOverride={editingStep.previewComboPriceOverride}
          previewBasicoPriceOverride={editingStep.previewBasicoPriceOverride}
          onChange={(steps) => {
            // El popup debe actualizar su propio borrador inmediatamente. Sin
            // esto conservaba la foto con la que se abrió y React devolvía el
            // cursor al final del texto después de cada tecla o pegado.
            setEditingStep((current) => current ? { ...current, steps } : current);
            editingStep.onChange(steps);
            // AQUÍ NO SE SUBE NADA, Y ES LO QUE PIDIÓ EL DUEÑO EL 28/09/2026:
            // el «Guardar» de este pop up deja el cambio puesto en el borrador y
            // el guardado general es el de la barra de arriba o Ctrl+S. El aviso
            // «Aún no has guardado tus cambios» es lo que impide que se te
            // olvide. Ver la cabecera de `BotonesDeLaVentana`, que cuenta el
            // caso entero con sus palabras.
          }}
          onClose={() => setEditingStep(null)}
        />
      )}
    </div>
  );
}

/**
 * LA VISTA PIZARRA — la otra forma de trabajar el MISMO contenido.
 *
 * Lo pidió el dueño el 16/10/2026, y lo dijo así: «las conexiones son el futuro de este
 * proyecto… aquí el rey del proyecto son las conexiones». Y que la pensara como un novato:
 * «a un usuario no le va a gustar hacer cosas que no sabe, ni algo que no sea intuitivo».
 *
 * ES UNA VISTA FIJA, NO UNA VENTANA: «no debería salirse con apretar Escape, debería quedar
 * fijo incluso al refrescar», con el modo esencial/profesional arriba. Se sale con «Menús».
 *
 * TODO VA AL MISMO BORRADOR QUE LOS MENÚS (`onConfigChange` + `onSnapshot`): el aviso «sin
 * guardar», Ctrl+S y Ctrl+Z valen igual aquí. Hasta lo que él MUEVE: dónde deja cada ficha y
 * sus cajas viaja con el contenido (`cfg.pizarra`), «le doy guardar y que se guarde y quede
 * tal cual está».
 *
 * QUÉ SALE LO DECIDE `loQueSaleEnLaEstacion`, con las mismas piezas de regla que el bot. Su
 * prueba lo compara contra el motor de verdad con su contenido real. Por dentro, cada cable de
 * un país es una bandera; él no tiene que saberlo.
 */
function VistaPizarra({
  cfg,
  onClose,
  onConfigChange,
  onSnapshot,
  onUndo,
  onRedo,
  onSave,
  onTiendaEnPantalla,
  herramientas,
  hayCambios,
  saving,
  modoEsencial,
  onModoEsencial,
  onPaisDeLaVista,
  onIrAlMenu,
  onVerRecorrido,
}: {
  /** Para las ventanas del menú ☰: los pasos de Ctrl+Z del editor y el país de los precios. */
  herramientas?: {
    editSnapshot: (clave: string) => void;
    marcarPunto: () => void;
    volverAlPunto: () => void;
    paisDePago: CountryCode;
  };
  /** Avisa qué tienda tiene abierta (o null en «Mis tiendas»), para el aviso al guardar. */
  onTiendaEnPantalla?: (tiendaId: string | null) => void;
  /** ▶ Ver recorrido de un país, desde su fondo en la pizarra, con los países de la pizarra. */
  onVerRecorrido?: (tiendaId: string, pais: string, paises: string[]) => void;
  cfg: FullConfig;
  /** Cambia el país de la vista previa (el botón de abajo a la derecha). */
  onPaisDeLaVista?: (pais: string) => void;
  /** Vuelve a los menús, abierto en ése: los botones nativos (upsell, regalo) se editan allí. */
  onIrAlMenu?: (menu: "upsell" | "regalo") => void;
  /** Volver a la vista de menús. */
  onClose: () => void;
  onConfigChange: (config: FullConfig) => void;
  onSnapshot: () => void;
  onUndo: () => void;
  onRedo: () => void;
  onSave: () => void;
  hayCambios: boolean;
  saving: boolean;
  modoEsencial: boolean;
  onModoEsencial: (esencial: boolean) => void;
}) {
  const tiendas = (cfg.tiendas ?? []).filter((t) => String(t?.id ?? "").trim());
  // LA TIENDA Y EL CANAL SE RECUERDAN (20/10/2026): al recargar, la misma pizarra que estaba abierta.
  // (La pizarra solo se dibuja en el navegador, así que leer aquí no desajusta nada.)
  const [tiendaId, setTiendaId] = useState<string>(() => {
    try {
      const guardada = window.localStorage.getItem("pizarra-tienda");
      if (guardada && tiendas.some((t) => t.id === guardada)) return guardada;
    } catch {}
    return tiendas.find((t) => String(t?.numero ?? "").trim())?.id ?? tiendas[0]?.id ?? "";
  });
  const [canal, setCanal] = useState<ChannelKey>(() => {
    try {
      const guardado = window.localStorage.getItem("pizarra-canal");
      if (guardado === "whatsapp" || guardado === "messenger" || guardado === "instagram") return guardado;
    } catch {}
    return "whatsapp";
  });
  useEffect(() => {
    try {
      window.localStorage.setItem("pizarra-tienda", tiendaId);
      window.localStorage.setItem("pizarra-canal", canal);
    } catch {}
  }, [tiendaId, canal]);
  /**
   * MIS TIENDAS O LA PIZARRA DE UNA (16/10/2026), como los vendedores de Sendy: «al yo dar doble
   * click a PACK MASCOTAS se abre la pizarra… al lado del botón + hay una flecha de retroceso».
   * Se recuerda en este navegador, igual que la vista: al refrescar sigue donde estaba.
   */
  const [pantalla, setPantalla] = useState<"tiendas" | "pizarra" | "tablero">(() => {
    try {
      const guardada = window.localStorage.getItem("pizarra-pantalla");
      return guardada === "pizarra" || guardada === "tablero" ? guardada : "tiendas";
    } catch {
      return "tiendas";
    }
  });
  useEffect(() => {
    onTiendaEnPantalla?.(pantalla === "pizarra" ? tiendaId || null : null);
    return () => onTiendaEnPantalla?.(null);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pantalla, tiendaId]);
  /** El workflow abierto en el tablero (null = el de la tienda). Solo pantalla. */
  const [workflowAbierto, setWorkflowAbierto] = useState<string | null>(null);
  const irA = (p: "tiendas" | "pizarra" | "tablero") => {
    setPantalla(p);
    try {
      window.localStorage.setItem("pizarra-pantalla", p);
    } catch {
      // Sin almacenamiento: dura hasta refrescar.
    }
  };
  /** El cajón que se está editando ENTERO, o el mensaje de una rama. */
  const [editando, setEditando] = useState<{ piezaId: string; burbuja?: number; pais?: string } | null>(null);
  const [editandoRama, setEditandoRama] = useState<{ piezaId: string; ramaId: string } | null>(null);
  /** El pop up del cobro: quién cobra en esta tienda y sus cuentas por país. */
  /** El Pago abierto: `true` sin país, o el país del camino desde el que se abrió. */
  const [verCobro, setVerCobro] = useState<boolean | string>(false);
  /** La entrega del regalo o la despedida: un texto solo, en su ventana. */
  const [editandoTexto, setEditandoTexto] = useState<"regalo-premio" | "regalo-despedida" | null>(null);
  const tienda = tiendas.find((t) => t.id === tiendaId);
  const semi = tienda?.semimodalidad ?? "";
  // LOS CAMINOS QUE ÉL AGREGÓ CON «+ País», sin nada conectado todavía. Viven en la pizarra de
  // esta tienda y canal —no en un estado de la pantalla— para que Ctrl+Z los quite y se guarden
  // (16/10/2026: «agregué un país y al presionar Ctrl+Z no se quita»).
  const paisesExtra = useMemo(
    () => vistaDeLaPizarra(cfg, tiendaId, canal, semi)?.paises ?? [],
    [cfg.pizarra, tiendaId, canal, semi]
  );
  const [aviso, setAviso] = useState<string | null>(null);
  useEffect(() => {
    if (!aviso) return;
    const t = window.setTimeout(() => setAviso(null), 7000);
    return () => window.clearTimeout(t);
  }, [aviso]);
  const [menuMas, setMenuMas] = useState(false);
  /**
   * EL MENÚ ☰, JUNTO AL «+» (19/10/2026): «que haya un menú así como ese pero con acceso a las
   * tiendas, etc., pero tiene que aparecer como pop ups… yo quiero no salir del modo pizarra».
   * Cada cosa se abre en su ventana, encima de la pizarra.
   */
  const [menuHerramientas, setMenuHerramientas] = useState(false);
  const [ventanaDeHerramienta, setVentanaDeHerramienta] = useState<null | "tienda" | "productos" | "anuncios" | "prueba" | "exportar">(null);
  /** EL GESTOR DE UN CAJÓN abierto (19/10/2026): el del regalo o el de los upsells, de ese país. */
  const [gestorAbierto, setGestorAbierto] = useState<{ cual: "regalo" | "upsells" | "cobro" | "seguimientos"; pais: string; camino?: string; soloEstas?: string[] } | null>(null);
  const refDeHerramientas = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!menuHerramientas) return;
    const alTeclear = (e: KeyboardEvent) => {
      if (e.key === "Escape") setMenuHerramientas(false);
    };
    const alPulsar = (e: PointerEvent) => {
      if (!refDeHerramientas.current?.contains(e.target as globalThis.Node | null)) setMenuHerramientas(false);
    };
    window.addEventListener("keydown", alTeclear);
    window.addEventListener("pointerdown", alPulsar);
    return () => {
      window.removeEventListener("keydown", alTeclear);
      window.removeEventListener("pointerdown", alPulsar);
    };
  }, [menuHerramientas]);
  // ESCAPE O UN CLIC AFUERA CIERRAN EL «+» (16/10/2026).
  const refDelMas = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!menuMas) return;
    const alTeclear = (e: KeyboardEvent) => {
      if (e.key === "Escape") setMenuMas(false);
    };
    const alPulsar = (e: PointerEvent) => {
      if (!refDelMas.current?.contains(e.target as globalThis.Node | null)) setMenuMas(false);
    };
    window.addEventListener("keydown", alTeclear);
    window.addEventListener("pointerdown", alPulsar);
    return () => {
      window.removeEventListener("keydown", alTeclear);
      window.removeEventListener("pointerdown", alPulsar);
    };
  }, [menuMas]);
  /**
   * LOS TRES MODOS DE LA PIZARRA (22/10/2026):
   *   ☀️ claro  — todo claro.
   *   🌗 mixto  — «fondo de pizarra oscuro y los pop ups en claro… y lo de la tienda claro, así como
   *               antes»: el fondo y sus barras oscuros; cajones editores y Mis tiendas, claros.
   *   🌙 oscuro — todo oscuro, cajones y Mis tiendas con los colores de Sendy.
   */
  const [temaDeLaPizarra, setTemaDeLaPizarra] = useState<"claro" | "mixto" | "oscuro">(() => {
    try {
      const guardado = window.localStorage.getItem("pizarra-tema");
      return guardado === "oscuro" || guardado === "mixto" ? guardado : "claro";
    } catch {
      return "claro";
    }
  });
  /** El fondo y las barras: oscuros en mixto y en oscuro. */
  const fondoOscuro = temaDeLaPizarra !== "claro";
  // LOS CAJONES EDITORES Y MIS TIENDAS SIGUEN AL 🌙 DE LA PIZARRA (22/10/2026): «en modo oscuro se
  // vea así… y el visor como WhatsApp oscuro». Se marca en la raíz mientras la pizarra está abierta;
  // globals.css oscurece solo lo que lleva la clase `prolijo`. Al salir de la pizarra se quita: el
  // resto del bot sigue en claro.
  useEffect(() => {
    document.documentElement.dataset.pizarraTema = temaDeLaPizarra;
    return () => {
      delete document.documentElement.dataset.pizarraTema;
    };
  }, [temaDeLaPizarra]);
  const cambiarTemaDeLaPizarra = (siguiente: "claro" | "mixto" | "oscuro") => {
    setTemaDeLaPizarra(siguiente);
    try {
      window.localStorage.setItem("pizarra-tema", siguiente);
    } catch {
      // Sin almacenamiento: dura hasta cerrar la pizarra.
    }
  };
  const [probando, setProbando] = useState<string>("");
  const [buscar, setBuscar] = useState("");
  const [pedidoDeCaja, setPedidoDeCaja] = useState(0);

  // LO ÚLTIMO DE TODO, para que cada clic trabaje sobre lo que hay AHORA en el borrador.
  const vivo = useRef({ cfg, canal, tiendaId, semi, piezas: [] as PiezaDePizarra[] });
  vivo.current = { ...vivo.current, cfg, canal, tiendaId, semi };
  const aplicar = (nuevo: FullConfig | null) => {
    if (!nuevo) return;
    onSnapshot();
    onConfigChange(nuevo);
  };
  /**
   * EL SEGURO (17/10/2026). Antes de aplicar un cambio, ¿algún país que NO se tocó se queda sin
   * su sub pestaña en alguna columna? Pasó así: conectar una intro nueva a Argentina dejó sin
   * intro a Perú y Ecuador —la tienda excluye a las 🌐— y él lo vio guardado: «no puede ser que
   * yo desconecte algo y se vaya a la mierda el workflow». Se compara lo que dibuja la pizarra
   * ANTES y DESPUÉS con las mismas reglas del bot, y si algo se cae fuera de lo tocado, se dice.
   */
  const perdidasPorElCambio = (antes: FullConfig, despues: FullConfig, tocados: string[] = []): string[] => {
    const { canal: k, tiendaId: t } = vivo.current;
    const foto = (c: FullConfig) => {
      const ts = (c.tiendas ?? []).filter((x) => String(x?.id ?? "").trim());
      const s = ts.find((x) => x.id === t)?.semimodalidad ?? "";
      const extra = vistaDeLaPizarra(c, t, k, s)?.paises ?? [];
      return modeloDePizarra(c, k, t, s, ts, extra);
    };
    const a = foto(antes);
    const d = foto(despues);
    const perdidas: string[] = [];
    for (const e of a.estaciones) {
      const e2 = d.estaciones.find((x) => x.id === e.id);
      for (const f of e.filas) {
        if (!f.clave || tocados.includes(f.clave) || f.piezas.length === 0) continue;
        const f2 = e2?.filas.find((x) => x.clave === f.clave);
        if (!f2 || f2.piezas.length === 0) perdidas.push(`${banderaDe(f.clave)} ${f.clave} en ${e.titulo}`);
      }
    }
    return perdidas;
  };
  /** Aplica, pero si el cambio deja sin lo suyo a un país que no se tocó, pregunta antes. */
  /** Dónde está ahora cada sub pestaña en el lienzo (lo dice el propio lienzo). */
  const posDePieza = useRef<(piezaId: string, pais?: string) => { x: number; y: number } | undefined>(() => undefined);
  /** Las estaciones del modelo (intro, seguimiento…), para saber en cuál cae cada ficha. */
  const estacionesVivas = useRef<ModeloDePizarra["estaciones"]>([]);
  /**
   * EL CAMINO DE UN CABLE ENTRE DOS FICHAS (18/10/2026): «yo fijo el camino y dónde tiene que
   * conectar cada uno, es como si se duplicara y se abre otro camino». SIN REEMPLAZOS: cada
   * ficha es de los caminos que le llegan por cable, y de ninguno más. Lo que hace el cable:
   *
   *   · Si la de origen es solo del principal y COMPITE en su paso con otra del principal (la
   *     copia al lado de la original), abre un camino nuevo (B, C…) y se lo pone. Suelta, también.
   *   · La de destino pasa a ser TAMBIÉN de los caminos de la de origen («dos intros al mismo
   *     seguimiento 1», «una sola intro de order bump para todos»). Recién copiada y sin país,
   *     deja de ser del principal: es solo de esos caminos.
   *   · Si uno de esos caminos ya sigue por OTRA ficha en ese paso, no se le cambia: se avisa.
   *
   * Lee el modelo de ANTES del cable (`vivo.current`), y pone las etiquetas en `c`.
   */
  const conCaminoDelCable = (
    c: FullConfig,
    desdeId: string,
    hacia: { antes: string; ahora: string },
    pais: string | null
  ): { cfg: FullConfig; aviso?: string } => {
    const { canal: k, piezas } = vivo.current;
    const deLaPieza = (id: string) => piezas.find((x) => x.id === id);
    const susCaminos = (id: string): string[] => {
      const p = deLaPieza(id);
      return p?.caminos ?? [p?.camino ?? ""];
    };
    /** Las otras fichas de su mismo paso en ese país. */
    const enSuPaso = (id: string) => {
      if (!pais) return [] as string[];
      const fila = estacionesVivas.current.find((e) => e.piezas.includes(id))?.filas.find((f) => f.clave === pais);
      return (fila?.piezas ?? []).filter((x) => x !== id);
    };
    const ponerCaminos = (cfg: FullConfig, id: string, caminos: string[], preferido?: string): FullConfig => {
      const u = ubicarPieza(cfg, k, id);
      if (!u || u.esBase || caminos.length === 0) return cfg;
      const suyo = preferido !== undefined && caminos.includes(preferido) ? preferido : caminos[0];
      const otros = caminos.filter((x) => x !== suyo).map((x) => x || PRINCIPAL);
      return u.poner({ ...u.obj, camino: suyo || undefined, tambien_en_caminos: otros.length > 0 ? otros : undefined });
    };
    const desde = deLaPieza(desdeId);
    const destino = deLaPieza(hacia.antes);
    if (!desde || !destino) return { cfg: c };
    let deOrigen = susCaminos(desdeId);
    const yaEnElPais = !!pais && destino.paises.includes(pais);
    // Los caminos de la de destino a los que no llega ninguna intro de ese país: un tramo suelto.
    const filaDe = (e: (typeof estacionesVivas.current)[number]) => e.filas.find((f) => f.clave === pais)?.piezas ?? [];
    const introsDelPais = estacionesVivas.current.filter((e) => e.tipo === "intro").flatMap(filaDe);
    const huerfanos =
      yaEnElPais && pais
        ? susCaminos(hacia.antes).filter((x) => x && !introsDelPais.some((id) => susCaminos(id).includes(x)))
        : [];
    const soloPrincipal = deOrigen.length === 1 && deOrigen[0] === "";
    if (soloPrincipal && (!pais || !desde.paises.includes(pais) || enSuPaso(desdeId).some((x) => susCaminos(x).includes("")))) {
      const usados = new Set(piezas.flatMap((x) => x.caminos ?? [x.camino ?? ""]).filter(Boolean));
      // LA INTRO TOMA EL CAMINO DEL TRAMO (18/10/2026): en Ecuador, la intro 35 (del principal)
      // conectada a un tramo B suelto debe quedar B, con su propia ruta. Si no, una letra nueva.
      const nuevo = huerfanos[0] ?? "BCDEFGHIJKLMNOPQRSTUVWXYZ".split("").find((l) => !usados.has(l)) ?? `${usados.size + 2}`;
      c = ponerCaminos(c, desdeId, [nuevo]);
      deOrigen = [nuevo];
    }
    // UN TRAMO SUELTO VUELVE ENTERO (18/10/2026): si la de destino es de un camino al que no
    // llega ninguna intro de ese país (lo que deja `cortarCable`), ese camino entero pasa a ser
    // el de la de origen —el tramo se reengancha de una vez, como él lo dejó—.
    if (yaEnElPais && pais && deOrigen.length > 0) {
      if (huerfanos.length > 0) {
        const delPais = [...new Set(estacionesVivas.current.flatMap(filaDe))];
        for (const id of delPais) {
          const suyos = susCaminos(id);
          if (!suyos.some((x) => huerfanos.includes(x))) continue;
          const nuevos = [...new Set(suyos.map((x) => (huerfanos.includes(x) ? deOrigen[0] : x)))];
          c = ponerCaminos(c, id === hacia.antes ? hacia.ahora : id, nuevos, deLaPieza(id)?.camino === "" ? "" : undefined);
        }
        return { cfg: c };
      }
    }
    // Recién copiada (sin país): todavía no es de nadie, ni del principal.
    const antes = yaEnElPais ? susCaminos(hacia.antes) : [];
    const despues = new Set(antes);
    const avisos: string[] = [];
    for (const camino of deOrigen) {
      if (despues.has(camino)) continue;
      const otra = enSuPaso(hacia.antes).find((x) => susCaminos(x).includes(camino));
      if (otra) {
        avisos.push(`El ${camino ? `camino ${camino}` : "principal"} ya sigue por «${deLaPieza(otra)?.titulo ?? otra}» en ese paso.`);
        continue;
      }
      despues.add(camino);
    }
    if (despues.size === 0) return { cfg: c, aviso: avisos.join(" ") || undefined };
    if (despues.size === antes.length && antes.every((x) => despues.has(x))) return { cfg: c, aviso: avisos.join(" ") || undefined };
    return { cfg: ponerCaminos(c, hacia.ahora, [...despues], destino.camino ?? ""), aviso: avisos.join(" ") || undefined };
  };
  /**
   * NADA SE MUEVE SOLO (17/10/2026): «yo en ningún momento pedí que algo se regrese solo, eso
   * genera confusión, yo no sé si se ha borrado o se ha fusionado». Si por un cambio una sub
   * pestaña deja de verse en las filas —p. ej. un upsell sin país cuando otro recibe el suyo—, se
   * queda EN SU SITIO, tenue y suelta, con su aviso. Solo va a Fichas guardadas si él la manda.
   */
  const quedanEnSuSitio = (antes: FullConfig, despues: FullConfig): FullConfig => {
    const { canal: k, tiendaId: t } = vivo.current;
    const enLasFilas = (c: FullConfig) => {
      const ts = (c.tiendas ?? []).filter((x) => String(x?.id ?? "").trim());
      const s = ts.find((x) => x.id === t)?.semimodalidad ?? "";
      const m = modeloDePizarra(c, k, t, s, ts, vistaDeLaPizarra(c, t, k, s)?.paises ?? []);
      return new Set(m.estaciones.flatMap((e) => e.filas.filter((f) => f.clave && f.estado !== "prestada").flatMap((f) => f.piezas)));
    };
    const antesSi = enLasFilas(antes);
    const despuesSi = enLasFilas(despues);
    let c = despues;
    for (const pid of antesSi) {
      if (despuesSi.has(pid)) continue;
      const donde = posDePieza.current(pid);
      if (donde) c = aLaVista(c, pid, donde);
    }
    return c;
  };
  /** `tocado`: el país (o los países) que el cambio toca A PROPÓSITO: ésos no cuentan. */
  const aplicarConSeguro = (
    nuevo: FullConfig | null,
    tocado?: string | string[],
    /** false al eliminar: las de detrás cambian de número y no hay «su sitio» que guardar. */
    quedarse = true
  ): boolean => {
    if (!nuevo) return false;
    const perdidas = perdidasPorElCambio(vivo.current.cfg, nuevo, tocado === undefined ? [] : ([] as string[]).concat(tocado));
    if (
      perdidas.length > 0 &&
      !window.confirm(
        `Cuidado: esto deja SIN su sub pestaña a ${perdidas.join(", ")}. Esos clientes pasarían a humano o se saltarían ese paso. ¿Sigo de todos modos?`
      )
    )
      return false;
    aplicar(quedarse ? quedanEnSuSitio(vivo.current.cfg, nuevo) : nuevo);
    return true;
  };
  /**
   * LO QUE SE TOCA EN ESTA TIENDA ES DE ESTA TIENDA (17/10/2026). Si la sub pestaña todavía es
   * compartida (🌐 o de otra tienda): apagada y 🌐 → se marca de esta tienda (nadie la usa);
   * encendida → se trabaja sobre una COPIA propia, y la original queda igual para las demás.
   * Devuelve el id con el que seguir (el de la copia, si la hubo).
   */
  const idReal = useRef<string | null>(null);
  const deEstaTienda = (c: FullConfig, piezaId: string): { cfg: FullConfig; id: string } => {
    const { canal: k, tiendaId: t } = vivo.current;
    const u = t ? ubicarPieza(c, k, piezaId) : null;
    if (!t || !u) return { cfg: c, id: piezaId };
    // Sus tiendas de verdad: las suyas o, si es una variante sin las suyas, las de su seguimiento.
    const [tipo, a] = piezaId.split(":");
    const suyas = u.obj.tiendas ?? [];
    const efectivas =
      tipo === "seg" && (u.esBase || suyas.length === 0)
        ? channelContentForMode(c, k, activeModality(c)).followups[Number(a)]?.tiendas ?? []
        : suyas;
    if (efectivas.length === 1 && efectivas[0] === t) return { cfg: c, id: piezaId }; // ya es de aquí
    // 🌐 y apagada: nadie la usa, se marca de esta tienda sin copiar.
    if (efectivas.length === 0 && u.obj.enabled === false && !u.esBase) {
      return { cfg: u.poner({ ...u.obj, tiendas: [t] }), id: piezaId };
    }
    const r = copiaPropiaDeLaTienda(c, k, piezaId, t);
    if (!r) return { cfg: c, id: piezaId };
    return { cfg: sinEstaTienda(r.cfg, k, piezaId, t, usadasEnOtrasTiendas(c, k, t)), id: r.id };
  };
  /** La pizarra guardada de esta tienda, con cada id viejo cambiado por el nuevo. */
  const conIdsNuevos = (c: FullConfig, mapa: Map<string, string>): FullConfig =>
    mapa.size === 0
      ? c
      : conDisposicion(c, (d) => {
          const nuevo = (id: string) => mapa.get(id) ?? id;
          const llave = (k: string) => {
            for (const [viejo, n] of mapa) if (k === viejo || k.endsWith(`:${viejo}`)) return `${k.slice(0, k.length - viejo.length)}${n}`;
            return k;
          };
          return {
            ...d,
            posiciones: Object.fromEntries(Object.entries(d.posiciones).map(([k, v]) => [llave(k), v])),
            visibles: d.visibles?.map(nuevo),
            puentes: d.puentes?.map((pu) => {
              const [pa, de, a] = pu.split("|");
              return `${pa}|${nuevo(de)}|${nuevo(a)}`;
            }),
          };
        });
  const avisoDeCompartida = (piezaId: string): string | null => {
    const p = vivo.current.piezas.find((x) => x.id === piezaId);
    if (!p) return null;
    if (p.otrasTiendas.length > 0) return `también la usa ${p.otrasTiendas.join(", ")}`;
    if (p.todasLasTiendas) return "no tiene tienda: vale para TODAS las tiendas";
    return null;
  };
  const SEMI_CORTA: Record<string, string> = { "": "lineal", dos_juntas: "dou", segunda_oculta: "ob" };
  const NOMBRE_DE_LA_SEMI: Record<string, string> = { lineal: "COMOHOY (lineal)", dou: "COMO DOU (doble oferta)", ob: "COMO OB (order bump)" };
  const claveDeVista = claveDeLaVista(tiendaId, canal, semi);
  /**
   * LA CONFIGURACIÓN CON LA PIZARRA DE ESTA TIENDA CAMBIADA, en el MISMO paso que el contenido:
   * cortar un cable cambia la bandera Y deja la ficha a la vista donde estaba, y un solo Ctrl+Z
   * deshace las dos cosas. Es la de ESTA semimodalidad (18/10/2026): la primera vez arranca con
   * la que había, y desde ahí cada una con lo suyo.
   */
  const conDisposicion = (
    c: FullConfig,
    cambio: (d: DisposicionDePizarra) => DisposicionDePizarra
  ): FullConfig => {
    const { tiendaId: t, canal: k, semi: s } = vivo.current;
    const d = vistaDeLaPizarra(c, t, k, s) ?? { posiciones: {} };
    return { ...c, pizarra: { vistas: { ...(c.pizarra?.vistas ?? {}), [claveDeLaVista(t, k, s)]: cambio(d) } } };
  };
  /**
   * LOS BOTONES DE UNA COPIA ESPERAN SU CABLE (20/10/2026): «las conexiones sí existen… pero el
   * usuario no debe ver una conexión automática; tendrá que conectarlo de manera manual». La copia
   * conserva lo que hace cada botón en el bot; la pizarra no dibuja el cable de los que llevan a
   * comprar (a la oferta o a un Pago) hasta que él lo tira. Solo pizarra.
   */
  const conBotonesPorConectar = (c: FullConfig, idCopia: string): FullConfig => {
    const { canal: k, tiendaId: t } = vivo.current;
    const pieza = piezaEditable(c, k, idCopia, t);
    if (!pieza) return c;
    const deCompra = new Set(["show_order_bump", "choose_basico", "choose_combo", "show_payment", "send_payment_method"]);
    const entradas = ramasParaLaPizarra(pieza.steps)
      .filter((r) => deCompra.has(r.accion ?? ""))
      .map((r) => `${idCopia}|${r.id}`);
    if (entradas.length === 0) return c;
    return conDisposicion(c, (d) => ({ ...d, ramasPorConectar: [...new Set([...(d.ramasPorConectar ?? []), ...entradas])] }));
  };
  /** UNA COPIA LLEVA SUS RECUADROS DE BOTÓN donde la original los tenía (18/10/2026). */
  const conRecuadros = (c: FullConfig, idCopia: string, recuadros?: Array<{ x: number; y: number } | null>): FullConfig =>
    recuadros && recuadros.length > 0
      ? conDisposicion(c, (d) => ({ ...d, recuadros: { ...(d.recuadros ?? {}), [idCopia]: recuadros } }))
      : c;
  /**
   * LO MISMO EN TODAS LAS PIZARRAS DEL CANAL (18/10/2026): las de cada tienda y cada
   * semimodalidad. Para lo que cambia el NÚMERO de una ficha (eliminar): las listas son del
   * canal entero, y una pizarra no renumerada dejaría cada sitio en la ficha de al lado.
   */
  const enTodasLasPizarras = (
    c: FullConfig,
    cambio: (d: DisposicionDePizarra) => DisposicionDePizarra
  ): FullConfig => {
    const { canal: k } = vivo.current;
    const vistas = c.pizarra?.vistas ?? {};
    const conLaActual = conDisposicion(c, (d) => d).pizarra?.vistas ?? vistas;
    return {
      ...c,
      pizarra: {
        vistas: Object.fromEntries(
          Object.entries(conLaActual).map(([clave, d]) => [clave, clave.split("|")[1] === k ? cambio(d) : d])
        ),
      },
    };
  };
  /**
   * QUITAR UNA FICHA, sin aplicar todavía (17/10/2026). Es lo que hacía «Eliminar», sacado a una
   * función para poder quitar VARIAS en un solo paso (Delete).
   *
   *   · Un seguimiento que NO es el último de su lista se ARCHIVA: apagado y sin país —el bot no
   *     lo manda— y fuera de la vista. Quitarlo correría a los de detrás, y el motor recuerda por
   *     número cuál le tocó a cada cliente.
   *   · Lo demás se quita de verdad, y las de detrás corren un número con su sitio, su «a la
   *     vista», sus cables de grupo y su archivado.
   */
  const quitarUna = (
    c: FullConfig,
    k: ChannelKey,
    piezaId: string
  ): { cfg: FullConfig; paises: string[] } | { error: string } => {
    const paises = vivo.current.piezas.find((x) => x.id === piezaId)?.paises ?? [];
    const [tipo, a, b] = piezaId.split(":");
    const variantes = tipo === "seg" ? channelContentForMode(c, k, activeModality(c)).followups[Number(a)]?.variants ?? [] : [];
    if (tipo === "seg" && Number(b) < variantes.length - 1) {
      const u = ubicarPieza(c, k, piezaId);
      if (!u) return { error: "No encontré esa ficha." };
      const apagada = u.poner({ ...u.obj, enabled: false, paises: [] });
      return {
        cfg: conDisposicion(apagada, (d) => ({
          ...d,
          archivadas: [...new Set([...(d.archivadas ?? []), piezaId])],
          visibles: (d.visibles ?? []).filter((x) => x !== piezaId),
          ...(d.enlaces ? { enlaces: d.enlaces.filter((x) => !x.split("|").includes(piezaId)) } : {}),
        })),
        paises,
      };
    }
    const r = eliminarPieza(c, k, piezaId);
    if ("error" in r) return r;
    // LAS DE DETRÁS CORREN UN NÚMERO: su sitio y su «a la vista» van con ellas, no se quedan
    // pegados al número viejo (si no, cada una heredaría el sitio de la de al lado).
    const prefijo = tipo === "seg" ? `${tipo}:${a}:` : `${tipo}:`;
    const quitada = Number(tipo === "seg" ? b : a);
    const renumera = (id: string): string | null => {
      if (!id.startsWith(prefijo)) return id;
      const n = Number(id.slice(prefijo.length));
      if (!Number.isFinite(n)) return id;
      if (n === quitada) return null;
      return n > quitada ? `${prefijo}${n - 1}` : id;
    };
    const renumerados = (lista: string[]) =>
      lista.flatMap((x) => {
        const nuevo = renumera(x);
        return nuevo ? [nuevo] : [];
      });
    return {
      // En TODAS las pizarras del canal (18/10/2026): cada tienda y cada semimodalidad tiene la
      // suya, y la lista de fichas es del canal entero.
      cfg: enTodasLasPizarras(r.cfg, (d) => ({
        ...d,
        visibles: renumerados(d.visibles ?? []),
        // Toda llave que TERMINE en esa sub pestaña («suelta:…», «pz:PE:intro:…», «hueco:…»).
        posiciones: Object.fromEntries(
          Object.entries(d.posiciones).flatMap(([llave, v]) => {
            const m = llave.match(new RegExp(`^(.*?)(${prefijo.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\d+)$`));
            if (!m) return [[llave, v]];
            const nuevo = renumera(m[2]);
            return nuevo ? [[`${m[1]}${nuevo}`, v]] : [];
          })
        ),
        // Y LOS CABLES DE UN GRUPO PEGADO (17/10/2026): renumerados igual; los de la quitada, fuera.
        ...(d.enlaces
          ? {
              enlaces: d.enlaces.flatMap((x) => {
                const [de, aa] = x.split("|");
                const nde = renumera(de);
                const na = renumera(aa);
                return nde && na ? [`${nde}|${na}`] : [];
              }),
            }
          : {}),
        ...(d.archivadas ? { archivadas: renumerados(d.archivadas) } : {}),
        ...(d.recuadros
          ? {
              recuadros: Object.fromEntries(
                Object.entries(d.recuadros).flatMap(([id, v]) => {
                  const nuevo = renumera(id);
                  return nuevo ? [[nuevo, v]] : [];
                })
              ),
            }
          : {}),
      })),
      paises,
    };
  };
  /**
   * UN CAMBIO EN UNA FICHA DE LA PIZARRA, en la de ESTA tienda (17/10/2026): el peso y los
   * anuncios. Mismo camino que guardar sus burbujas (`deEstaTienda`): si era compartida con otra
   * tienda, se cambia su copia propia y la otra tienda no se entera. Devuelve el id con el que
   * quedó (cambia si se hizo una copia).
   */
  /**
   * LA COPIA PROPIA QUE NACIÓ DE UNA FICHA COMPARTIDA (19/10/2026). Si en un gestor se enciende o se
   * le cambia el peso a una ficha que también usa otra tienda, nace su copia de esta tienda; el
   * editor incrustado, al aplicar lo que tenía escrito, debe ir a ESA copia y no hacer otra.
   */
  const copiaDeLaFicha = useRef<Record<string, string>>({});
  const cambiarEnLaFicha = (
    piezaId: string,
    cambio: (obj: PiezaUbicada["obj"], esBase: boolean) => PiezaUbicada["obj"]
  ): string => {
    const { cfg: c, canal: k } = vivo.current;
    const propia = deEstaTienda(c, piezaId);
    const u = ubicarPieza(propia.cfg, k, propia.id);
    if (!u) return piezaId;
    const hecho = u.poner(cambio(u.obj, u.esBase));
    if (propia.id !== piezaId) copiaDeLaFicha.current[piezaId] = propia.id;
    aplicar(propia.id !== piezaId ? conIdsNuevos(hecho, new Map([[piezaId, propia.id]])) : hecho);
    return propia.id;
  };
  /**
   * SIN LOS SITIOS VIEJOS DE LA FILA, desde el puesto `desde` (17/10/2026). Las tarjetas de la
   * fila se llaman por su número («pv:PE:fila:0»): un upsell nuevo heredaba el sitio de otro que
   * ya no está y salía fuera del fondo de su país. Sin sitio, nace junto a la tarjeta de la que sale.
   */
  const sinSitiosDeLaFila = (c: FullConfig, desde: number): FullConfig =>
    conDisposicion(c, (d) => ({
      ...d,
      posiciones: Object.fromEntries(
        Object.entries(d.posiciones).filter(([k]) => {
          const m = /^pv:[^:]*:(?:fila|fila-entrega):(\d+)$/.exec(k);
          return !m || Number(m[1]) < desde;
        })
      ),
    }));
  /** Dejar una ficha suelta A LA VISTA, y si se dice dónde, ahí. */
  const aLaVista = (c: FullConfig, piezaId: string, donde?: { x: number; y: number }): FullConfig =>
    conDisposicion(c, (d) => {
      // SIN SITIO DADO, SIN SITIO HEREDADO (17/10/2026): los números se reusan —una copia nueva
      // recibe el de una eliminada— y se ponía donde estaba aquélla, encima de otra. Sin sitio,
      // se borra el viejo y la pizarra le busca un hueco libre.
      const { [`suelta:${piezaId}`]: _viejo, ...sinElViejo } = d.posiciones;
      void _viejo;
      return {
        ...d,
        visibles: [...new Set([...(d.visibles ?? []), piezaId])],
        posiciones: donde ? { ...d.posiciones, [`suelta:${piezaId}`]: donde } : sinElViejo,
      };
    });

  /**
   * DESCONECTAR SIN PERDER SU ENCENDIDO (20/10/2026): «si yo tengo accesorios y los conecto y los
   * desconecto, el accesorio no debería cambiar». Una ficha que se queda sin país se apaga (así el
   * bot no la manda a nadie), y al conectarla se encendía siempre: una que él tenía APAGADA volvía
   * encendida. Si ya estaba apagada al quedarse sin país, se apunta en la pizarra y al volver a
   * conectarla sigue apagada.
   */
  const desconectarRecordando = (c: FullConfig, k: ChannelKey, piezaId: string, pais: string): { cfg: FullConfig } | { error: string } => {
    const u = ubicarPieza(c, k, piezaId);
    const yaApagada = u?.obj.enabled === false;
    const r = desconectarPieza(c, k, piezaId, pais);
    if ("error" in r) return r;
    const sinPais = ((ubicarPieza(r.cfg, k, piezaId)?.obj.paises as string[] | undefined) ?? []).length === 0;
    return sinPais && yaApagada
      ? { cfg: conDisposicion(r.cfg, (d) => ({ ...d, apagadas: [...new Set([...(d.apagadas ?? []), piezaId])] })) }
      : r;
  };

  /** Apunta un corte en el plano de esta pizarra (ver `leerCorte`). */
  const conElCorte = (c: FullConfig, x: CorteDeRuta): FullConfig =>
    conDisposicion(c, (d) => ({
      ...d,
      cortesDeRuta: [...(d.cortesDeRuta ?? []).filter((y) => !(leerCorte(y)?.pais === x.pais && leerCorte(y)?.hacia === x.hacia)), escribirCorte(x)],
    }));
  /**
   * VOLVER A ENCHUFAR LO QUE ÉL CORTÓ (20/10/2026): vuelve EXACTAMENTE como estaba: su país (si
   * salió de él), la ruta de todo su tramo, y el corte sale del plano. Solo si se enchufa desde el
   * mismo sitio (o desde una ficha de la misma ruta); si no, devuelve null y sigue lo de siempre.
   */
  const reenchufar = (piezaId: string, pais: string, desde?: string): FullConfig | null => {
    const { cfg: c0, canal: k, tiendaId: t, semi: s, piezas } = vivo.current;
    const cortes = (vistaDeLaPizarra(c0, t, k, s)?.cortesDeRuta ?? []).map(leerCorte).filter((x): x is CorteDeRuta => !!x);
    const caminosDe = (id: string) => {
      const p = piezas.find((x) => x.id === id);
      return p?.caminos ?? [p?.camino ?? ""];
    };
    // El suyo, o el del tramo en el que está (se puede enchufar a cualquier versión del cajón).
    const corte =
      cortes.find((x) => x.pais === pais && x.hacia === piezaId) ??
      cortes.find((x) => x.pais === pais && !!x.letra && caminosDe(piezaId).includes(x.letra));
    if (!corte) return null;
    const mismoSitio = (desde ?? "inicio") === corte.desde || (!!desde && caminosDe(desde).includes(corte.original));
    if (!mismoSitio) return null;
    let c: FullConfig = c0;
    if (corte.quitado) c = conectarSobre(c, corte.hacia, pais, false) ?? c;
    if (corte.letra) {
      for (const p of piezas) {
        if (!p.paises.includes(pais)) continue;
        const suyos = caminosDe(p.id);
        if (!suyos.includes(corte.letra)) continue;
        const nuevos = [...new Set(suyos.map((x) => (x === corte.letra ? corte.original : x)))];
        const u = ubicarPieza(c, k, p.id);
        if (!u || u.esBase) continue;
        const propio = (u.obj as { camino?: string }).camino ?? "";
        const suyo = nuevos.includes(propio) ? propio : nuevos[0];
        const otros = nuevos.filter((x) => x !== suyo).map((x) => x || PRINCIPAL);
        c = u.poner({ ...u.obj, camino: suyo || undefined, tambien_en_caminos: otros.length > 0 ? otros : undefined });
      }
    }
    return conDisposicion(c, (d) => ({
      ...d,
      cortesDeRuta: (d.cortesDeRuta ?? []).filter((y) => !(leerCorte(y)?.pais === pais && leerCorte(y)?.hacia === corte.hacia)),
    }));
  };


  /**
   * LA COPIA DE UNA APAGADA, APAGADA (20/10/2026): «la casa de al lado necesita una conexión
   * idéntica… agarra esto y ármalo igual». Toda copia nace apagada y al conectarla se encendía; si
   * la original estaba apagada, se apunta y al conectarla sigue apagada (`conectarSobre`).
   */
  const conLaApagadaRecordada = (c: FullConfig, origenId: string, copiaId: string): FullConfig =>
    ubicarPieza(vivo.current.cfg, vivo.current.canal, origenId)?.obj.enabled === false
      ? conDisposicion(c, (d) => ({ ...d, apagadas: [...new Set([...(d.apagadas ?? []), copiaId])] }))
      : c;

  /**
   * IMPORTAR UNA TIENDA AQUÍ, COMO BLOQUES SUELTOS (20/10/2026): «en n8n exportaba un proyecto,
   * abría otro, importaba el json y aparecía al lado, lógicamente desconectado, y ya podía usar esos
   * bloques». Las fichas del archivo (las de este canal y esta semimodalidad) entran como COPIAS en
   * esta tienda, al final de sus listas, sueltas y sin país ni ruta, a la derecha de lo que ya hay y
   * con la forma que tenían. Cada bloque (un país y su ruta) viene unido como un bloque pegado: al
   * conectar su intro se conecta entero. Lo de esta tienda no se toca. Nada se conecta solo; sus
   * botones al Pago esperan el cable de él. Un solo Ctrl+Z lo deshace.
   */
  const importarComoBloques = (datos: unknown): string => {
    const d = datos as {
      formato?: string;
      productos?: ProductoEditor[];
      fichas?: Array<{ canal: ChannelKey; piezaId: string; obj: Record<string, unknown> }>;
      vistas?: Record<string, DisposicionDePizarra>;
    } | null;
    if (!d || d.formato !== FORMATO_DE_TIENDA) return "Este archivo no es una tienda exportada desde aquí.";
    const { cfg: c0, canal: k, tiendaId: t, semi: s } = vivo.current;
    const semiDeAqui = laSemimodalidadDeLaTienda({ semimodalidad: s });
    const fichas = (d.fichas ?? []).filter(
      (f) =>
        f.canal === k &&
        !f.piezaId.startsWith("up:") &&
        (!semimodalidadDe({ semimodalidad: f.obj?.semimodalidad as string | undefined }) ||
          semimodalidadDe({ semimodalidad: f.obj?.semimodalidad as string | undefined }) === semiDeAqui)
    );
    if (fichas.length === 0) return "El archivo no trae fichas de este canal y esta semimodalidad.";
    let c: FullConfig = c0;
    // Los productos que falten (los que ya estén, con el mismo id, no se tocan).
    const yaEstan = new Set((c.biblioteca_de_productos ?? []).map((p) => p?.id));
    const faltan = (d.productos ?? []).filter((p) => p?.id && !yaEstan.has(p.id));
    if (faltan.length > 0) c = { ...c, biblioteca_de_productos: [...(c.biblioteca_de_productos ?? []), ...faltan] };
    // Dónde estaban en su pizarra.
    const suVista =
      d.vistas?.[`${k}|${semiDeAqui}`] ?? d.vistas?.[k] ?? Object.values(d.vistas ?? {})[0];
    const sitioDe = (pid: string) => {
      const pos = suVista?.posiciones ?? {};
      const clave = Object.keys(pos).find((x) => x === `suelta:${pid}` || x.endsWith(`:${pid}`));
      return clave ? pos[clave] : undefined;
    };
    // A la derecha de todo lo de aquí.
    const aqui = vistaDeLaPizarra(c0, t, k, s);
    const finDeAqui = Math.max(
      0,
      ...Object.values(aqui?.posiciones ?? {}).map((p) => p.x + 300),
      ...(aqui?.cajas ?? []).map((x) => x.x + x.ancho)
    );
    const sitios = fichas.map((f) => sitioDe(f.piezaId));
    const minX = Math.min(...sitios.filter(Boolean).map((p) => p!.x), Number.POSITIVE_INFINITY);
    const dx = Number.isFinite(minX) ? finDeAqui + 300 - minX : finDeAqui + 300;
    const avisos: string[] = [];
    const nuevoDe = new Map<string, string>();
    fichas.forEach((f, i) => {
      const [tipo, a] = f.piezaId.split(":");
      const que: LoQueSeAgrega | null =
        tipo === "intro" ? { tipo: "intro" } : tipo === "ob" ? { tipo: "ob" } : tipo === "seg" ? { tipo: "seguimiento", indice: Number(a) } : null;
      const id = que ? idDeLaNueva(c, que) : null;
      const u = ubicarPieza(c, k, tipo === "seg" ? `seg:${a}:0` : `${tipo}:0`);
      if (!que || !id || !u) {
        avisos.push(`«${String(f.obj?.name ?? f.piezaId)}» no se pudo traer: aquí no hay dónde ponerla.`);
        return;
      }
      const obj = conBotonesNuevos(JSON.parse(JSON.stringify(f.obj)) as PiezaUbicada["obj"]);
      c = u.agregarAlFinal({
        ...obj,
        enabled: false,
        paises: [],
        tiendas: t ? [t] : [],
        camino: undefined,
        tambien_en_caminos: undefined,
      } as PiezaUbicada["obj"]);
      const sitio = sitios[i];
      const donde = sitio ? { x: Math.round(sitio.x + dx), y: Math.round(sitio.y) } : { x: Math.round(finDeAqui + 300 + (i % 4) * 300), y: 200 + Math.floor(i / 4) * 260 };
      c = conBotonesPorConectar(aLaVista(c, id, donde), id);
      if ((f.obj as { enabled?: boolean }).enabled === false) c = conDisposicion(c, (x) => ({ ...x, apagadas: [...new Set([...(x.apagadas ?? []), id])] }));
      nuevoDe.set(f.piezaId, id);
    });
    // Cada bloque (un país y su ruta), unido como al pegar: paso tras paso.
    const pasoDe = (pid: string) => (pid.startsWith("intro:") ? 0 : pid.startsWith("seg:") ? 1 + Number(pid.split(":")[1]) : 1000);
    const grupos = new Map<string, string[]>();
    for (const f of fichas) {
      if (!nuevoDe.has(f.piezaId)) continue;
      const o = f.obj as { paises?: string[]; camino?: string; tambien_en_caminos?: string[] };
      const rutas = [o.camino ?? "", ...(o.tambien_en_caminos ?? []).map((x) => (x === PRINCIPAL ? "" : x))];
      for (const pais of o.paises ?? []) for (const ruta of rutas) grupos.set(`${pais}|${ruta}`, [...(grupos.get(`${pais}|${ruta}`) ?? []), f.piezaId]);
    }
    const enlaces = new Set<string>();
    for (const ids of grupos.values()) {
      const enOrden = [...new Set(ids)].sort((x, y) => pasoDe(x) - pasoDe(y));
      for (let i = 1; i < enOrden.length; i++) {
        const antes = enOrden.slice(0, i).filter((x) => pasoDe(x) < pasoDe(enOrden[i]));
        const de = antes[antes.length - 1];
        if (de) enlaces.add(`${nuevoDe.get(de)}|${nuevoDe.get(enOrden[i])}`);
      }
    }
    if (enlaces.size > 0) c = conDisposicion(c, (x) => ({ ...x, enlaces: [...new Set([...(x.enlaces ?? []), ...enlaces])] }));
    if (nuevoDe.size === 0) return avisos.join(" ") || "No se trajo ninguna ficha.";
    aplicar(c);
    return `Importadas ${nuevoDe.size} fichas como bloques sueltos, a la derecha de la pizarra. Conecta su intro desde el Inicio de un país. Ctrl+Z lo deshace.${avisos.length > 0 ? ` ${avisos.join(" ")}` : ""}`;
  };

  /**
   * LLEVARLA A OTRA CASA (20/10/2026): «tengo una conexión en una casa, la quito y me la llevo a otra
   * casa». Una ficha que se quedó DESENCHUFADA en un país (cortada: su ruta es una letra propia a la
   * que no llega ninguna intro de allí) y se conecta en OTRO país, sale del primero. Si no, como la
   * ruta es una por ficha, la del país nuevo la revivía en el viejo sin que él lo viera.
   * Solo con ruta de letra: una del principal no está desenchufada (le llega la intro de siempre).
   */
  const llevarDeCasa = (c: FullConfig, k: ChannelKey, piezaId: string, haciaPais: string): FullConfig => {
    const { piezas } = vivo.current;
    const p = piezas.find((x) => x.id === piezaId);
    if (!p || p.tipo === "intro" || p.paises.includes(haciaPais)) return c;
    const susC = p.caminos ?? [p.camino ?? ""];
    if (susC.includes("")) return c;
    const intro = estacionesVivas.current.find((e) => e.tipo === "intro");
    let nuevo = c;
    for (const casa of p.paises) {
      const introsDeAlli = intro?.filas.find((f) => f.clave === casa)?.piezas ?? [];
      const leLlega = introsDeAlli.some((i) => {
        const q = piezas.find((y) => y.id === i);
        return (q?.caminos ?? [q?.camino ?? ""]).some((x) => susC.includes(x));
      });
      if (leLlega) continue;
      const r = desconectarPieza(nuevo, k, piezaId, casa);
      if (!("error" in r)) nuevo = r.cfg;
    }
    return nuevo;
  };

  /** Conecta una ficha a un país sobre una configuración dada (para encadenar con crear). */
  /**
   * LA SEMIMODALIDAD DE UNA COPIA: SIEMPRE la que se está viendo (25/10/2026). Antes, la copia de
   * una ficha general (sin semimodalidad) salía general también, y una ficha general aparece en las
   * TRES (lineal, COMO OB y COMO DOU): «se pega en las 3 semimodalidades, es un caos». Lo que se pega
   * o se duplica aquí es de aquí.
   */
  const semiParaLaCopia = (_piezaId: string): string | undefined => SEMI_CORTA[vivo.current.semi] || undefined;
  const conectarSobre = (
    c: FullConfig,
    piezaId: string,
    pais: string,
    preguntar: boolean,
    /** Solo para un seguimiento NUEVO: nadie lo apagó a propósito, así que se enciende sin más. */
    esSeguimientoNuevo = false
  ): FullConfig | null => {
    const { canal: k, tiendaId: t, semi: s, piezas } = vivo.current;
    idReal.current = null;
    const p = piezas.find((x) => x.id === piezaId);
    if (p?.semimodalidad && p.semimodalidad !== SEMI_CORTA[s]) {
      setAviso(`«${p.titulo}» está hecha para otra forma de vender y aquí no saldría. Duplícala (clic derecho → Duplicar): la copia queda para la que estás viendo, y la original no cambia.`);
      return null;
    }
    // SIN EL AVISO DE «NO TIENE TIENDA» (17/10/2026: «es ridículo, ¿cómo no va a tener tienda si
    // estoy en GRAFISMO?»): lo que se conecta aquí pasa a ser de esta tienda.
    void preguntar;
    const original = piezaId;
    const propia = deEstaTienda(c, piezaId);
    idReal.current = propia.id;
    c = propia.cfg;
    piezaId = propia.id;
    const r = conectarPieza(c, k, piezaId, pais, t);
    if ("error" in r) {
      setAviso(r.error);
      return null;
    }
    let nuevo = r.cfg;
    // LA QUE ÉL TENÍA APAGADA vuelve apagada (ver `desconectarRecordando`).
    const apagadas = vistaDeLaPizarra(nuevo, t, k, s)?.apagadas ?? [];
    if (apagadas.includes(original) || apagadas.includes(piezaId)) {
      const u = ubicarPieza(nuevo, k, piezaId);
      if (u && !u.esBase) nuevo = u.poner({ ...u.obj, enabled: false });
      nuevo = conDisposicion(nuevo, (d) => ({ ...d, apagadas: (d.apagadas ?? []).filter((x) => x !== original && x !== piezaId) }));
    }
    // UN SEGUIMIENTO APAGADO ENTERO: la ficha no saldría. Encenderlo es de todo el canal —si él
    // lo apagó a propósito, las demás tiendas lo notarían—, así que se pregunta, salvo que sea
    // uno recién creado.
    const seg = seguimientoApagadoDe(nuevo, k, piezaId);
    if (
      seg !== null &&
      (esSeguimientoNuevo ||
        window.confirm(
          "Ese seguimiento está APAGADO entero, así que la ficha no saldría. ¿Lo enciendo? Solo lo recibirán las tiendas que tengan fichas suyas en él."
        ))
    ) {
      nuevo = encenderSeguimiento(nuevo, k, seg);
    }
    return nuevo;
  };

  /** ¿Qué id tendrá la ficha que se agregue AL FINAL de esta lista? */
  const idDeLaNueva = (c: FullConfig, que: LoQueSeAgrega): string | null => {
    const contenido = channelContentForMode(c, vivo.current.canal, activeModality(c));
    if (que.tipo === "intro") return `intro:${contenido.intro_groups.length}`;
    if (que.tipo === "ob") {
      const n = (contenido.order_bump_intro_groups ?? []).length > 0 || c.channels?.[vivo.current.canal]?.use_content === true
        ? (contenido.order_bump_intro_groups ?? []).length
        : (c.order_bump?.intro_groups ?? []).length;
      return `ob:${n}`;
    }
    if (que.tipo === "upsell") {
      const n = (contenido.upsell_intro_groups ?? []).length > 0
        ? (contenido.upsell_intro_groups ?? []).length
        : (c.upsell?.intro_groups ?? []).length;
      return `up:${n}`;
    }
    if (que.tipo === "seguimiento") return `seg:${que.indice}:${(contenido.followups[que.indice]?.variants ?? []).length}`;
    return `seg:${contenido.followups.length}:0`;
  };

  const acciones = useMemo<AccionesDelLienzo>(
    () => ({
      abrir: (piezaId: string, burbuja?: number, pais?: string) => {
        if (piezaId === "pago") {
          setVerCobro(pais || true);
          return;
        }
        if (piezaId === "regalo-premio" || piezaId === "regalo-despedida") {
          setEditandoTexto(piezaId);
          return;
        }
        if (pais) onPaisDeLaVista?.(pais);
        setEditando({ piezaId, burbuja, pais });
      },
      conectar: (piezaId: string, pais: string, desde?: string) => {
        // LO QUE ÉL CORTÓ, ENCHUFADO DESDE EL MISMO SITIO: vuelve exactamente como estaba.
        const devuelto = reenchufar(piezaId, pais, desde);
        if (devuelto) {
          aplicar(devuelto);
          return;
        }
        // UN GRUPO PEGADO SE CONECTA ENTERO (17/10/2026): «al enchufarlas a un país que se conecte
        // todo el flujo». Las copias unidas por sus cables de grupo reciben el país todas a la vez
        // (un solo Ctrl+Z), y esos cables se quitan: ya los dibuja el camino de ese país.
        const vista = vistaDeLaPizarra(vivo.current.cfg, vivo.current.tiendaId, vivo.current.canal, vivo.current.semi);
        const enlacesDelGrupo = vista?.enlaces ?? [];
        const grupo = new Set<string>([piezaId]);
        for (let cambio = true; cambio; ) {
          cambio = false;
          for (const x of enlacesDelGrupo) {
            const [de, a] = x.split("|");
            if (grupo.has(de) !== grupo.has(a)) {
              grupo.add(de);
              grupo.add(a);
              cambio = true;
            }
          }
        }
        if (grupo.size > 1) {
          // CADA FICHA SE QUEDA DONDE ÉL LA DEJÓ (17/10/2026): «cuando lo conecto en otro país se
          // desordena… se autoalinea en el top del cuadro y me hace reacomodar todo». Al pasar al
          // camino del país cambia de tarjeta (de «suelta» a la de ese país), así que su sitio se
          // copia a la nueva. Las del upsell van dentro de su tarjeta, que no se mueve.
          const sitios: Record<string, { x: number; y: number }> = {};
          for (const id of grupo) {
            if (id.startsWith("up:")) continue;
            const donde = posDePieza.current(id);
            const estacion = estacionesVivas.current.find((e) => e.piezas.includes(id))?.id;
            if (donde && estacion) sitios[`pz:${pais}:${estacion}:${id}`] = donde;
          }
          // UN BLOQUE PEGADO ABRE SU PROPIO CAMINO (18/10/2026): «copié la intro, seguimiento 1 y 2
          // en un solo bloque, lo conecté al país y nuevamente se conectaron solas entre ellas». Si
          // en ese país ya hay fichas del principal en los pasos del bloque, el bloque entero es un
          // camino nuevo (B, C…), como si él hubiera tirado los cables de una en una. País vacío:
          // queda del principal, como siempre.
          const { piezas: todas } = vivo.current;
          const caminosDe_ = (id: string) => {
            const p = todas.find((x) => x.id === id);
            return p?.caminos ?? [p?.camino ?? ""];
          };
          const compite = [...grupo].some((id) => {
            const fila = estacionesVivas.current.find((e) => e.piezas.includes(id))?.filas.find((f) => f.clave === pais);
            return (fila?.piezas ?? []).some((x) => !grupo.has(x) && caminosDe_(x).includes(""));
          });
          const sinCamino = [...grupo].filter((id) => !todas.find((x) => x.id === id)?.caminos && !todas.find((x) => x.id === id)?.camino);
          const usados = new Set(todas.flatMap((x) => x.caminos ?? [x.camino ?? ""]).filter(Boolean));
          // CONECTADO DESDE UNA FICHA, EL BLOQUE SIGUE SU RUTA (20/10/2026): un tramo cortado (o un
          // bloque pegado) que se vuelve a enchufar desde una ficha toma la ruta de esa ficha, como
          // una sola suelta (`conCaminoDelCable`). Desde el Inicio, lo de siempre.
          const delOrigen = desde && !grupo.has(desde) ? caminosDe_(desde) : null;
          const caminoDelBloque =
            !delOrigen && compite && sinCamino.length > 0 ? "BCDEFGHIJKLMNOPQRSTUVWXYZ".split("").find((l) => !usados.has(l)) ?? `${usados.size + 2}` : "";
          let c: FullConfig | null = vivo.current.cfg;
          for (const id of grupo) {
            if (!c) break;
            c = conectarSobre(llevarDeCasa(c, vivo.current.canal, id, pais), id, pais, false) ?? c;
            const ahora = idReal.current ?? id;
            if (c && sinCamino.includes(id) && (delOrigen || caminoDelBloque)) {
              const u = ubicarPieza(c, vivo.current.canal, ahora);
              const suyo = delOrigen ? delOrigen[0] ?? "" : caminoDelBloque;
              const otros = delOrigen ? delOrigen.slice(1).map((x) => x || PRINCIPAL) : [];
              if (u && !u.esBase) c = u.poner({ ...u.obj, camino: suyo || undefined, tambien_en_caminos: otros.length > 0 ? otros : undefined });
            }
          }
          aplicarConSeguro(
            c
              ? conDisposicion(c, (d) => ({
                  ...d,
                  posiciones: { ...d.posiciones, ...sitios },
                  enlaces: (d.enlaces ?? []).filter((x) => !x.split("|").some((id) => grupo.has(id))),
                }))
              : c,
            pais
          );
          setAviso(
            `Grupo conectado a ${banderaDe(pais)} ${pais}: ${grupo.size} fichas.${caminoDelBloque ? ` Es el camino ${caminoDelBloque}.` : ""}`
          );
          return;
        }
        // UNA SUELTA SE QUEDA DONDE ÉL LA DEJÓ (18/10/2026): «al conectarla se alinea en el borde
        // de la caja… necesito que al conectar algo, se quede en su sitio». Como los grupos
        // pegados: al pasar al camino del país cambia de tarjeta, y su sitio va a la nueva. Solo
        // una SUELTA (sin país): una que ya está en otro país conserva allí su sitio.
        const suelta = (vivo.current.piezas.find((x) => x.id === piezaId)?.paises ?? []).length === 0;
        const dondeEstaba = suelta ? posDePieza.current(piezaId) : undefined;
        const estacion = estacionesVivas.current.find((e) => e.piezas.includes(piezaId))?.id;
        const conectada = conectarSobre(llevarDeCasa(vivo.current.cfg, vivo.current.canal, piezaId, pais), piezaId, pais, true);
        // Si se conectó una copia propia (era compartida), sus cables y su sitio van con ella.
        const id = idReal.current ?? piezaId;
        const conSusCosas = conectada && id !== piezaId ? conIdsNuevos(conectada, new Map([[piezaId, id]])) : conectada;
        const conSuSitio =
          conSusCosas && dondeEstaba && estacion
            ? conDisposicion(conSusCosas, (d) => ({
                ...d,
                posiciones: { ...d.posiciones, [`pz:${pais}:${estacion}:${id}`]: dondeEstaba },
              }))
            : conSusCosas;
        // DE FICHA A FICHA, EL CABLE TAMBIÉN DICE EL CAMINO (18/10/2026). Ver `conCaminoDelCable`.
        const conCamino = conSuSitio && desde ? conCaminoDelCable(conSuSitio, desde, { antes: piezaId, ahora: id }, pais) : null;
        let conTodo = conCamino ? conCamino.cfg : conSuSitio;
        // UNA INTRO COPIADA, DEL INICIO A UN PAÍS QUE YA TIENE SU INTRO, ABRE CAMINO (18/10/2026):
        // «que no ocurra en todas las copias». Es donde empieza una ruta; los cables que él tire
        // desde ella llevan ese camino. (Un seguimiento suelto no: se queda en el sorteo con
        // pesos hasta que un cable le diga de qué camino es.)
        let caminoNuevo = "";
        if (conTodo && !desde && suelta && piezaId.startsWith("intro:")) {
          const { piezas: todas } = vivo.current;
          const fila = estacionesVivas.current.find((e) => e.piezas.includes(piezaId))?.filas.find((f) => f.clave === pais);
          const yaTieneIntro = (fila?.piezas ?? []).some((x) => x !== piezaId);
          if (yaTieneIntro) {
            const usados = new Set(todas.flatMap((x) => x.caminos ?? [x.camino ?? ""]).filter(Boolean));
            caminoNuevo = "BCDEFGHIJKLMNOPQRSTUVWXYZ".split("").find((l) => !usados.has(l)) ?? `${usados.size + 2}`;
            const u = ubicarPieza(conTodo, vivo.current.canal, id);
            if (u && !u.esBase) conTodo = u.poner({ ...u.obj, camino: caminoNuevo, tambien_en_caminos: undefined });
          }
        }
        // EL SALTO QUE ÉL DIBUJA (17/10/2026): «lo intenté conectar a la intro de order bump pero
        // no conecta». Ya era de Perú, así que no cambiaba nada y el cable no salía. Ahora el
        // cable que él tira se guarda y se dibuja (el bot ya salta el paso que falta).
        const hecho = aplicarConSeguro(
          conTodo && desde
            ? conDisposicion(conTodo, (d) => ({ ...d, puentes: [...new Set([...(d.puentes ?? []), `${pais}|${desde}|${id}`])] }))
            : conTodo,
          pais
        );
        if (hecho && conCamino?.aviso) setAviso(conCamino.aviso);
        if (hecho && caminoNuevo) setAviso(`Intro conectada a ${banderaDe(pais)} ${pais}: abre el camino ${caminoNuevo}. Conecta desde ella sus seguimientos.`);
      },
      // ENTRE DOS FICHAS SUELTAS (18/10/2026): «debe permitir hacer conexiones aunque el país no
      // esté conectado, entre cuadro y cuadro flotante». Quedan enlazadas en grupo —al conectar la
      // primera a un país se conecta todo— y en el mismo camino.
      enlazar: (desdeId: string, haciaId: string) => {
        const destino = vivo.current.piezas.find((x) => x.id === haciaId);
        if (destino && destino.paises.length > 0) {
          setAviso(`«${destino.titulo}» ya está en un camino de país. Conecta primero la de origen a un país y luego tira el cable.`);
          return;
        }
        const r = conCaminoDelCable(vivo.current.cfg, desdeId, { antes: haciaId, ahora: haciaId }, null);
        aplicar(conDisposicion(r.cfg, (d) => ({ ...d, enlaces: [...new Set([...(d.enlaces ?? []), `${desdeId}|${haciaId}`])] })));
        if (r.aviso) setAviso(r.aviso);
      },
      // CORTAR EL CABLE DE UN CAMINO (18/10/2026): «el camino lo armo y desarmo yo… no puede haber
      // reconexiones automáticas». Se va ESE cable y nada más se mueve:
      //   · la ficha de destino y lo que cuelga de ella por ese camino en ese país quedan como un
      //     tramo suelto, unido entre sí, con su punto rojo (camino propio, sin intro: no le llega
      //     nadie, y el bot no se lo manda a nadie);
      //   · si la de destino era también de otros caminos, sigue en ellos: solo sale de éste;
      //   · una ficha que está en varios países no se toca en los demás: en éste se desconecta.
      // Volver a conectar el tramo desde una ficha lo devuelve entero a ese camino.
      cortarCable: (haciaId: string, pais: string, camino: string, desdeId?: string) => {
        const { cfg: c0, canal: k, piezas } = vivo.current;
        // Y LOS CABLES QUE ÉL DIBUJÓ ENTRE ESAS DOS, también: si no, al quitar uno aparecía el otro.
        const c = desdeId
          ? conDisposicion(c0, (d) => ({ ...d, puentes: (d.puentes ?? []).filter((x) => x !== `${pais}|${desdeId}|${haciaId}`) }))
          : c0;
        // DEL INICIO A UNA INTRO: la intro sale de este país, como siempre (se queda en su sitio).
        // NADA SE MUEVE NI DESAPARECE (20/10/2026: «corté el cable que une el inicio con la intro y
        // desaparece la intro… se movió a Ecuador»). La de varios países sale de éste y aquí queda
        // su sitio «sin conectar»; la de un solo país queda suelta en su mismo sitio.
        // Y EN EL PLANO (20/10/2026): sale de este país (el bot ya no la manda aquí), pero se sigue
        // dibujando en su sitio, desconectada y con todos sus cables hacia lo que sigue.
        if (haciaId.startsWith("intro:")) {
          const r = desconectarRecordando(c, k, haciaId, pais);
          if (!("error" in r)) aplicar(conElCorte(r.cfg, { pais, desde: "inicio", hacia: haciaId, original: "", letra: "", quitado: true }));
          return;
        }
        const susCaminos = (id: string): string[] => {
          const p = piezas.find((x) => x.id === id);
          return p?.caminos ?? [p?.camino ?? ""];
        };
        const estaciones = estacionesVivas.current;
        const iDestino = estaciones.findIndex((e) => e.piezas.includes(haciaId));
        const enElTramo = new Set([
          haciaId,
          // LAS OTRAS VERSIONES DEL MISMO PASO Y RUTA (20/10/2026): van en el mismo cajón y llegan
          // por el mismo cable; cortarlo las corta a todas, no solo a la primera.
          ...(estaciones[iDestino]?.filas.find((f) => f.clave === pais)?.piezas ?? []).filter(
            (id) => id !== haciaId && /^seg:/.test(id) && /^seg:/.test(haciaId) && susCaminos(id).includes(camino)
          ),
          ...estaciones
            .slice(iDestino + 1)
            .flatMap((e) => e.filas.find((f) => f.clave === pais)?.piezas ?? [])
            // Solo seguimientos e intros de order bump: el upsell no lleva camino (18/10/2026:
            // un upsell quedó marcado «B» al cortar).
            // Y LA INTRO DE ORDER BUMP NO VA EN EL TRAMO DE UN SEGUIMIENTO (20/10/2026): el bot la
            // saca cuando el cliente quiere pagar, venga o no de los seguimientos; cortar intro →
            // seguimientos la dejaba fuera de la ruta y el cliente se quedaba trabado. Solo sale si
            // se corta su propio cable.
            .filter((id) => /^seg:/.test(id) && susCaminos(id).includes(camino)),
        ]);
        // LO QUE A ESE CAMINO LE SIGUE LLEGANDO POR OTRO CABLE SUYO no entra en el tramo suelto
        // (p. ej. la intro de order bump, unida además desde la intro con un cable de él).
        const puentesQuedan = (vistaDeLaPizarra(c, vivo.current.tiendaId, k, vivo.current.semi)?.puentes ?? []).filter((x) => x.startsWith(`${pais}|`));
        for (const pu of puentesQuedan) {
          const [, de, a] = pu.split("|");
          if (a !== haciaId && enElTramo.has(a) && !enElTramo.has(de) && susCaminos(de).includes(camino)) enElTramo.delete(a);
        }
        const detras = [...enElTramo].filter((id) => id !== haciaId);
        const poner = (cfg: FullConfig, id: string, caminos: string[]): FullConfig => {
          const u = ubicarPieza(cfg, k, id);
          if (!u || u.esBase || caminos.length === 0) return cfg;
          const propio = piezas.find((x) => x.id === id)?.camino ?? "";
          const suyo = caminos.includes(propio) ? propio : caminos[0];
          const otros = caminos.filter((x) => x !== suyo).map((x) => x || PRINCIPAL);
          return u.poner({ ...u.obj, camino: suyo || undefined, tambien_en_caminos: otros.length > 0 ? otros : undefined });
        };
        // CORTAR QUITA ESE CABLE Y NADA MÁS (20/10/2026): «si yo corto la línea principal inicial,
        // ningún poste se desconecta». En el bot, lo de detrás deja de recibir clientes: su ruta pasa
        // a una propia (B, C…) a la que no llega ninguna intro. En la PIZARRA queda el PLANO: el corte
        // se apunta (`cortesDeRuta`) y se dibuja todo como estaba, con todos sus cables, menos ESE,
        // y tenue (sin corriente). Al volver a enchufarlo vuelve exactamente como estaba.
        //   · La de destino que también es de OTRAS rutas solo sale de ésta.
        //   · La de destino de VARIOS países sale de éste (su ruta es de todos sus países); se sigue
        //     dibujando aquí, en su sitio, desconectada.
        //   · Las de detrás de varios países no se tocan.
        const usados = new Set(piezas.flatMap((x) => x.caminos ?? [x.camino ?? ""]).filter(Boolean));
        const tramo = "BCDEFGHIJKLMNOPQRSTUVWXYZ".split("").find((l) => !usados.has(l)) ?? `${usados.size + 2}`;
        let nuevo = c;
        const deVariosPaises = (id: string) => (piezas.find((x) => x.id === id)?.paises.length ?? 0) > 1;
        const destinoDeVarios = deVariosPaises(haciaId);
        for (const id of [haciaId, ...detras]) {
          const suyos = susCaminos(id);
          if (deVariosPaises(id)) {
            if (id === haciaId) {
              const r = desconectarRecordando(nuevo, k, id, pais);
              if (!("error" in r)) nuevo = r.cfg;
            }
            continue;
          }
          const quedan =
            id === haciaId && suyos.length > 1
              ? suyos.filter((x) => x !== camino)
              : [...new Set(suyos.map((x) => (x === camino ? tramo : x)))];
          nuevo = poner(nuevo, id, quedan);
        }
        aplicar(conElCorte(nuevo, { pais, desde: desdeId ?? "inicio", hacia: haciaId, original: camino, letra: tramo, quitado: destinoDeVarios }));
      },
      // QUITAR UN PAÍS DE LA PIZARRA (19/10/2026): «se pueden agregar países… pero no los puedo
      // eliminar». Sus fichas se desconectan de ese país (las que solo eran de él quedan sueltas
      // en su sitio, no se borran; las de varios países siguen en los otros), y se van su fila, su
      // fondo y sus cables dibujados. Un solo Ctrl+Z lo devuelve. NO toca «Vender en este país».
      quitarPais: (pais: string, sitios: Record<string, { x: number; y: number }>, piezasDeLaFila: string[]) => {
        const { cfg: c0, canal: k, piezas } = vivo.current;
        // SOLO LAS DE SU FILA EN ESTA PIZARRA: las de otra tienda o semimodalidad no se tocan.
        const suyas = piezas.filter((p) => piezasDeLaFila.includes(p.id) && p.paises.includes(pais));
        if (
          suyas.length > 0 &&
          !window.confirm(
            `Se desconectarán ${suyas.length} ficha(s) de ${banderaDe(pais)} ${pais}. Las que solo eran de este país quedan sueltas en su sitio; no se borra ninguna. ¿Seguir?`
          )
        )
          return;
        let c = c0;
        for (const p of suyas) {
          const r = desconectarRecordando(c, k, p.id, pais);
          if ("error" in r) {
            setAviso(r.error);
            return;
          }
          c = r.cfg;
          if (p.paises.length === 1 && sitios[p.id]) c = aLaVista(c, p.id, sitios[p.id]);
        }
        c = conDisposicion(c, (d) => ({
          ...d,
          paises: (d.paises ?? []).filter((x) => x !== pais),
          // Y fuera de esta pizarra aunque otra tienda o semimodalidad lo use.
          quitados: [...new Set([...(d.quitados ?? []), pais])],
          puentes: (d.puentes ?? []).filter((x) => !x.startsWith(`${pais}|`)),
          ...(d.cajas ? { cajas: d.cajas.filter((x) => x.id !== `caja:carril:${pais}`) } : {}),
        }));
        aplicarConSeguro(c, pais);
        setAviso(`${banderaDe(pais)} ${pais} quitado de la pizarra. Ctrl+Z lo devuelve. La venta en ese país sigue como estaba (su interruptor no se tocó).`);
      },
      // EL INTERRUPTOR DEL INICIO DE CADA PAÍS (19/10/2026): «esa misma acción debería usarse
      // cuando se activa país». Es el «Vender en este país» del menú, tal cual: la misma bandera
      // global (`country_sales_enabled`) y, si la modalidad ya tiene perfil de pago de ese país,
      // su «enabled» —como hace `setCountryProfile`—. Pasa por el borrador: Ctrl+Z lo deshace y
      // se guarda con «Guardar». El motor no cambia: ya lee esa bandera.
      ventaDelPais: (pais: string) => laVentaEstaAbiertaEnElPais(vivo.current.cfg, pais as CountryCode),
      // EL INICIO EN REVISIÓN (20/10/2026): no vende (es el mismo «no vende» del bot) pero el país se
      // ve normal en la pizarra. Solo pizarra: se apunta en esta vista.
      enRevision: (pais: string) =>
        (vistaDeLaPizarra(vivo.current.cfg, vivo.current.tiendaId, vivo.current.canal, vivo.current.semi)?.revision ?? []).includes(pais),
      alternarRevision: (pais: string) =>
        aplicar(
          conDisposicion(vivo.current.cfg, (d) => ({
            ...d,
            revision: (d.revision ?? []).includes(pais) ? (d.revision ?? []).filter((x) => x !== pais) : [...(d.revision ?? []), pais],
          }))
        ),
      alternarVentaDelPais: (pais: string) => {
        const c = vivo.current.cfg;
        const pc = pais as CountryCode;
        const ahora = !laVentaEstaAbiertaEnElPais(c, pc);
        const mode = activeModality(c);
        const perfil = c.modality_payment_profiles?.[mode]?.[pc];
        aplicar({
          ...c,
          country_sales_enabled: { ...(c.country_sales_enabled ?? {}), [pc]: ahora },
          ...(perfil
            ? {
                modality_payment_profiles: {
                  ...c.modality_payment_profiles,
                  [mode]: { ...c.modality_payment_profiles?.[mode], [pc]: { ...perfil, enabled: ahora } },
                },
              }
            : {}),
        });
      },
      // EL CABLE DE «QUIERE COMPRAR / PAGAR» (19/10/2026): lo pone él; solo se dibuja (el bot ya
      // lleva a la compra al que lo dice). Ctrl+Z lo quita; su ✕ también (`quitarPuente`).
      ponerPuente: (pais: string, desdeId: string, haciaId: string) => {
        const llave = `${pais}|${desdeId}|${haciaId}`;
        aplicar(conDisposicion(vivo.current.cfg, (d) => ({ ...d, puentes: [...new Set([...(d.puentes ?? []), llave])] })));
      },
      // CORTAR UN CABLE QUE ÉL DIBUJÓ (18/10/2026): «corté uno de los cables y se cortaron los 3».
      // Se va ESE cable. Y si con él llegaba un camino a la ficha de destino, y ningún otro cable de
      // ese camino le llega, la ficha sale de ese camino (si le queda alguno). Nada más se toca.
      quitarPuente: (pais: string, desdeId: string, haciaId: string) => {
        const { cfg: c, canal: k, piezas } = vivo.current;
        const vista = vistaDeLaPizarra(c, vivo.current.tiendaId, k, vivo.current.semi);
        const quedan = (vista?.puentes ?? []).filter((x) => x !== `${pais}|${desdeId}|${haciaId}`);
        const caminosDe_ = (id: string) => {
          const p = piezas.find((x) => x.id === id);
          return p?.caminos ?? [p?.camino ?? ""];
        };
        const delDestino = caminosDe_(haciaId);
        const siguenLlegando = new Set(
          quedan.filter((x) => x.startsWith(`${pais}|`) && x.endsWith(`|${haciaId}`)).flatMap((x) => caminosDe_(x.split("|")[1]))
        );
        const sinEste = delDestino.filter((m) => !caminosDe_(desdeId).includes(m) || siguenLlegando.has(m));
        let nuevo = conDisposicion(c, (d) => ({ ...d, puentes: quedan }));
        if (sinEste.length > 0 && sinEste.length < delDestino.length) {
          const u = ubicarPieza(nuevo, k, haciaId);
          if (u && !u.esBase) {
            const suyo = sinEste.includes(piezas.find((x) => x.id === haciaId)?.camino ?? "") ? piezas.find((x) => x.id === haciaId)?.camino ?? "" : sinEste[0];
            const otros = sinEste.filter((x) => x !== suyo).map((x) => x || PRINCIPAL);
            nuevo = u.poner({ ...u.obj, camino: suyo || undefined, tambien_en_caminos: otros.length > 0 ? otros : undefined });
          }
        }
        aplicar(nuevo);
      },
      // CORTAR EL CABLE DE UN CAMINO A UNA FICHA DE VARIOS (18/10/2026): sale de ESE camino y los
      // demás siguen pasando por ella. Ctrl+Z lo devuelve.
      quitarDelCamino: (piezaId: string, camino: string) => {
        const { cfg: c, canal: k } = vivo.current;
        const p = vivo.current.piezas.find((x) => x.id === piezaId);
        const quedan = (p?.caminos ?? [p?.camino ?? ""]).filter((x) => x !== camino);
        const u = ubicarPieza(c, k, piezaId);
        if (!u || u.esBase || quedan.length === 0) return;
        const suyo = quedan.includes(p?.camino ?? "") ? p?.camino ?? "" : quedan[0];
        const otros = quedan.filter((x) => x !== suyo).map((x) => x || PRINCIPAL);
        aplicar(u.poner({ ...u.obj, camino: suyo || undefined, tambien_en_caminos: otros.length > 0 ? otros : undefined }));
      },
      conectarATodos: (piezaId: string, paises: string[]) => {
        let c: FullConfig | null = vivo.current.cfg;
        let id = piezaId;
        for (const pais of paises) {
          if (!c) break;
          c = conectarSobre(c, id, pais, false);
          // Si la primera vez se hizo propia (copia), las siguientes van a la copia.
          id = idReal.current ?? id;
        }
        aplicarConSeguro(c && id !== piezaId ? conIdsNuevos(c, new Map([[piezaId, id]])) : c, paises);
      },
      // ELIMINAR VARIAS DE UNA VEZ (17/10/2026): «yo debería presionar Delete y borrar». Una sola
      // pregunta y un solo Ctrl+Z. De cada lista se quitan de la última a la primera, para que
      // quitar una no corra el número de las que faltan por quitar.
      eliminarVarias: (piezaIds: string[], soloDeSuPais: Array<{ piezaId: string; pais: string }> = []) => {
        const { canal: k } = vivo.current;
        const ids = [...new Set(piezaIds)].sort((x, y) => {
          const [tx, ax, bx] = x.split(":");
          const [ty, ay, by] = y.split(":");
          if (tx !== ty || (tx === "seg" && ax !== ay)) return x < y ? -1 : 1;
          return Number(tx === "seg" ? by : ay) < Number(tx === "seg" ? bx : ax) ? -1 : 1;
        });
        if (ids.length === 0 && soloDeSuPais.length === 0) return;
        const nombres = ids.map((id) => vivo.current.piezas.find((x) => x.id === id)?.titulo || id);
        const partes = [
          ids.length > 0 ? (ids.length === 1 ? `eliminar «${nombres[0]}»` : `eliminar ${ids.length} fichas`) : "",
          soloDeSuPais.length > 0
            ? `sacar ${soloDeSuPais.length === 1 ? "1 ficha común" : `${soloDeSuPais.length} fichas comunes`} solo de ${[...new Set(soloDeSuPais.map((x) => x.pais))].join(", ")} (en los demás países sigue)`
            : "",
        ].filter(Boolean);
        if (!window.confirm(`¿${partes.join(" y ")}? Ctrl+Z lo devuelve mientras no guardes.`)) return;
        let c: FullConfig = vivo.current.cfg;
        const paises = new Set<string>();
        // Primero las comunes, solo de su país: no cambian el número de nadie.
        for (const { piezaId, pais } of soloDeSuPais) {
          const r = desconectarPieza(c, k, piezaId, pais);
          if ("error" in r) continue;
          c = r.cfg;
          paises.add(pais);
        }
        for (const id of ids) {
          const r = quitarUna(c, k, id);
          if ("error" in r) continue;
          c = r.cfg;
          r.paises.forEach((p) => paises.add(p));
        }
        aplicarConSeguro(c, [...paises], false);
      },
      eliminar: (piezaId: string) => {
        const { cfg: c, canal: k } = vivo.current;
        const p = vivo.current.piezas.find((x) => x.id === piezaId);
        // UN SEGUIMIENTO QUE NO ES EL ÚLTIMO DE SU LISTA SE ARCHIVA (17/10/2026): «no entiendo por
        // qué no se puede eliminar». Los ya agendados guardan el NÚMERO de su variante
        // (`variant_index` en el motor): quitarla del medio correría a las de detrás. Archivada,
        // queda apagada y sin país —el bot no la manda— y desaparece de la vista. Para él, borrada.
        const [tipo, a, b] = piezaId.split(":");
        const variantes = tipo === "seg" ? channelContentForMode(c, k, activeModality(c)).followups[Number(a)]?.variants ?? [] : [];
        if (tipo === "seg" && Number(b) < variantes.length - 1) {
          if (!window.confirm(`¿Eliminar «${p?.titulo || "esta sub pestaña"}»? Ctrl+Z la devuelve mientras no guardes.`)) return;
          const r = quitarUna(c, k, piezaId);
          if ("error" in r) setAviso(r.error);
          else aplicarConSeguro(r.cfg, r.paises, false);
          return;
        }
        const r = eliminarPieza(c, k, piezaId);
        // SI AL QUITARLA VUELVE A SALIR UNA COMPARTIDA (la que usa otra tienda), se dice antes: el
        // bot se la mandaría a esta tienda, y la pizarra la traería como propia. Sin esto parecía
        // que eliminar «no funcionaba» (17/10/2026).
        const vuelven =
          "error" in r
            ? []
            : [
                ...hacerPropiaLaTienda(
                  r.cfg,
                  k,
                  vivo.current.tiendaId,
                  vivo.current.semi,
                  (r.cfg.tiendas ?? []).filter((x) => String(x?.id ?? "").trim()),
                  []
                ).mapa.keys(),
              ].map((id) => vivo.current.piezas.find((x) => x.id === id)?.titulo || id);
        if (
          !window.confirm(
            vuelven.length > 0
              ? `¿Eliminar «${p?.titulo || "esta sub pestaña"}»? Ojo: sin ella, el bot le mandaría a esta tienda «${vuelven.join("», «")}», que es de otra tienda, y aparecerá aquí como propia.`
              : `¿Eliminar «${p?.titulo || "esta sub pestaña"}»? Ctrl+Z la devuelve mientras no guardes.`
          )
        )
          return;
        if ("error" in r) {
          setAviso(r.error);
          return;
        }
        const q = quitarUna(c, k, piezaId);
        if ("error" in q) {
          setAviso(q.error);
          return;
        }
        // Sus propios países la pierden a propósito: el seguro mira solo a los demás.
        aplicarConSeguro(q.cfg, p?.paises ?? [], false);
      },
      // CORTAR, SIN AVISO (16/10/2026): «al cortar la conexión que no salga ningún aviso». Ctrl+Z
      // lo deshace. Y la ficha NO desaparece: «debería estar en ese lugar sin conexión o tenue».
      desconectar: (piezaId: string, pais: string, dondeQueda?: { x: number; y: number }) => {
        const { cfg: c, canal: k } = vivo.current;
        const r = desconectarPieza(c, k, piezaId, pais);
        if ("error" in r) {
          setAviso(r.error);
          return;
        }
        // Y SUS SALTOS DIBUJADOS hacia ella en ese país, fuera también.
        const sinSaltos = conDisposicion(r.cfg, (d) => ({
          ...d,
          puentes: (d.puentes ?? []).filter((p) => !(p.startsWith(`${pais}|`) && p.endsWith(`|${piezaId}`))),
        }));
        aplicarConSeguro(dondeQueda ? aLaVista(sinSaltos, piezaId, dondeQueda) : sinSaltos, pais);
      },
      mostrar: (piezaId: string, donde: { x: number; y: number }) =>
        aplicar(aLaVista(vivo.current.cfg, piezaId, donde)),
      ocultar: (piezaId: string) =>
        aplicar(
          conDisposicion(vivo.current.cfg, (d) => ({
            ...d,
            visibles: (d.visibles ?? []).filter((x) => x !== piezaId),
          }))
        ),
      alternar: (piezaId: string) => {
        const { cfg: c, canal: k } = vivo.current;
        // SIN AVISO: lo que se enciende o apaga aquí es de esta tienda (17/10/2026).
        const propia = deEstaTienda(c, piezaId);
        if (propia.id !== piezaId) copiaDeLaFicha.current[piezaId] = propia.id;
        const alternada = alternarPieza(propia.cfg, k, propia.id);
        // LA QUE ÉL APAGA AQUÍ SE QUEDA EN SU SITIO, con sus cables y tenue (20/10/2026); al
        // encenderla, deja de estar apuntada.
        const seApaga = ubicarPieza(alternada ?? propia.cfg, k, propia.id)?.obj.enabled === false;
        const conSuSitio = alternada
          ? conDisposicion(alternada, (d) => ({
              ...d,
              quedanApagadas: seApaga
                ? [...new Set([...(d.quedanApagadas ?? []), propia.id])]
                : (d.quedanApagadas ?? []).filter((x) => x !== propia.id && x !== piezaId),
            }))
          : alternada;
        aplicarConSeguro(
          conSuSitio && propia.id !== piezaId ? conIdsNuevos(conSuSitio, new Map([[piezaId, propia.id]])) : conSuSitio,
          vivo.current.piezas.find((x) => x.id === piezaId)?.paises ?? []
        );
      },
      // DUPLICAR PARA UN PAÍS: la copia nace al final de su lista y YA conectada a ese país —
      // es lo que él hacía a mano: «duplico la de Perú, la conecto a Argentina».
      duplicar: (piezaId: string, paraPais?: string, junto?: { x: number; y: number }, recuadros?: Array<{ x: number; y: number } | null>) => {
        const { cfg: c0, canal: k } = vivo.current;
        const [tipo] = piezaId.split(":");
        const que: LoQueSeAgrega | null =
          tipo === "intro" ? { tipo: "intro" } : tipo === "ob" ? { tipo: "ob" } : tipo === "up" ? { tipo: "upsell" }
          : tipo === "seg" ? { tipo: "seguimiento", indice: Number(piezaId.split(":")[1]) } : null;
        const idCopia = que ? idDeLaNueva(c0, que) : null;
        const c = idCopia ? conRecuadros(c0, idCopia, recuadros) : c0;
        const copiaSola = duplicarPieza(c, k, piezaId, semiParaLaCopia(piezaId));
        if (!copiaSola || !idCopia) {
          setAviso("Los «mensajes principales» se duplican en su sección de siempre.");
          return;
        }
        const copia = conLaApagadaRecordada(conBotonesPorConectar(copiaSola, idCopia), piezaId, idCopia);
        if (!paraPais) {
          // NACE AL LADO de la original, sin conectar: «que el duplicado aparezca al lado y yo
          // moverlo» (16/10/2026).
          aplicar(aLaVista(copia, idCopia, junto));
          return;
        }
        // Se conecta SOLO a ese país: la copia nace sin banderas, así que lleva solo la suya.
        const conectada = conectarSobre(copia, idCopia, paraPais, false);
        if (aplicarConSeguro(conectada ?? copia, paraPais) && conectada) setAviso(`Copia creada y conectada a ${banderaDe(paraPais)} ${paraPais}. Doble clic en su franja para cambiarle lo que haga falta.`);
      },
      cambiarRama: (piezaId: string, ramaId: string, destino: DestinoDeRama, yaPreguntado?: boolean) => {
        const nuevo = cambiarDestinoDeRama(vivo.current.cfg, vivo.current.canal, piezaId, ramaId, destino, vivo.current.tiendaId, yaPreguntado);
        if ("error" in nuevo) {
          if (nuevo.error) setAviso(nuevo.error);
          return;
        }
        // Si era un botón de una copia que esperaba su cable, o uno cuyo cable él cortó, ya lo
        // tiró él: deja de esperar.
        const llave = `${piezaId}|${ramaId}`;
        aplicar(
          conDisposicion(nuevo.cfg, (d) =>
            (d.ramasPorConectar ?? []).includes(llave) || (d.cortados ?? []).includes(llave)
              ? {
                  ...d,
                  ramasPorConectar: (d.ramasPorConectar ?? []).filter((x) => x !== llave),
                  cortados: (d.cortados ?? []).filter((x) => x !== llave),
                }
              : d
          )
        );
      },
      abrirRama: (piezaId: string, ramaId: string) => setEditandoRama({ piezaId, ramaId }),
      // EL CABLE DE UN BOTÓN COPIADO, TIRADO ADONDE YA LLEVA: solo deja de esperar; el botón no cambia.
      confirmarCable: (piezaId: string, ramaId: string) =>
        aplicar(
          conDisposicion(vivo.current.cfg, (d) => ({
            ...d,
            ramasPorConectar: (d.ramasPorConectar ?? []).filter((x) => x !== `${piezaId}|${ramaId}`),
            cortados: (d.cortados ?? []).filter((x) => x !== `${piezaId}|${ramaId}`),
          }))
        ),
      // CORTAR EL CABLE DE UN BOTÓN ES SOLO PANTALLA (20/10/2026): «no me puedes cambiar una función
      // al cortar el cable». El botón sigue igual en el bot; su cable deja de dibujarse hasta que él
      // lo vuelva a tirar (y entonces vuelve tal cual, sin aviso).
      cortarCableDeBoton: (piezaId: string, ramaId: string) =>
        aplicar(
          conDisposicion(vivo.current.cfg, (d) => ({
            ...d,
            cortados: [...new Set([...(d.cortados ?? []), `${piezaId}|${ramaId}`])],
          }))
        ),
      crearConectada: (que: LoQueSeCrea, pais: string, donde?: { x: number; y: number }) => {
        const { cfg: c, canal: k, tiendaId: t } = vivo.current;
        const id = idDeLaNueva(c, que);
        const creada = agregarPieza(c, k, que, t);
        if (!creada || !id) return;
        const conectada = conectarSobre(creada, id, pais, false, que.tipo === "seguimiento-nuevo");
        // Recién creada y vacía: se abre para escribirla. Mientras no tenga contenido el bot no
        // la manda, así que queda A LA VISTA —si no, al cerrar sin escribir «desaparecía»—.
        const hecho = aplicarConSeguro(aLaVista(conectada ?? creada, id, donde), pais);
        if (hecho && conectada) {
          setEditando({ piezaId: id });
          setAviso(`Ficha creada para ${banderaDe(pais)} ${pais}. Escríbela: hasta que tenga contenido no sale.`);
        }
      },
      // «USAR TAMBIÉN EN…» SIN CONECTAR (20/10/2026): «hacerla común no significa que hay que
      // conectarla automáticamente, nada debe conectar automáticamente». Solo se apunta en la
      // pizarra; el bot no cambia hasta que él tira el cable.
      ponerComun: (piezaIds: string[], paises: string[], grupo: string) => {
        const entradas = paises.flatMap((p) => piezaIds.map((id) => `${p}|${id}|${grupo}`));
        aplicar(conDisposicion(vivo.current.cfg, (d) => ({ ...d, comunes: [...new Set([...(d.comunes ?? []), ...entradas])] })));
        setAviso(
          `Queda en ${paises.map((p) => `${banderaDe(p)} ${p}`).join(", ")} sin conectar, marcada «COMÚN». Conéctala con un cable para que salga ahí. Es la misma: si la editas, cambia en todos.`
        );
      },
      quitarComun: (pais: string, piezaIds: string[]) => {
        aplicar(
          conDisposicion(vivo.current.cfg, (d) => ({
            ...d,
            comunes: (d.comunes ?? []).filter((x) => {
              const [p, id] = x.split("|");
              return !(p === pais && piezaIds.includes(id));
            }),
          }))
        );
      },
      // CONECTAR LO COMÚN CON SU CABLE: todas sus fichas a ese país, en el camino del cable, y en
      // UN solo paso (un Ctrl+Z). Lo mismo que conectar cada una (`conectarSobre`); su apunte en
      // espera se va.
      conectarComunes: (piezaIds: string[], pais: string, desde?: string) => {
        let c: FullConfig = vivo.current.cfg;
        const cambiados = new Map<string, string>();
        const aviso: string | undefined = undefined;
        // EL CAMINO SE SUMA, NUNCA SE CAMBIA (20/10/2026). Es la MISMA ficha que ya sale en otros
        // países por su camino: `conCaminoDelCable` la trataría como recién copiada y le quitaría
        // el suyo (en Perú dejaría de salir). Aquí conserva sus caminos y gana el del cable.
        const caminosDe = (id: string) => {
          const p = vivo.current.piezas.find((x) => x.id === id);
          return p?.caminos ?? [p?.camino ?? ""];
        };
        const delCable = desde ? caminosDe(desde) : [""];
        for (const id of piezaIds) {
          const conectada = conectarSobre(c, id, pais, false);
          if (!conectada) continue;
          const real = idReal.current ?? id;
          if (real !== id) cambiados.set(id, real);
          c = conectada;
          const suyos = caminosDe(id);
          // (Una intro desde el Inicio conserva su ruta: el Inicio no tiene ruta que darle. Así una
          // intro de la ruta B desconectada de un país vuelve a él como B, no como principal.)
          const todos = !desde && id.startsWith("intro:") ? suyos : [...new Set([...suyos, ...delCable])];
          if (todos.length !== suyos.length) {
            const u = ubicarPieza(c, vivo.current.canal, real);
            if (u && !u.esBase) {
              const principal = (u.obj as { camino?: string }).camino ?? "";
              const otros = todos.filter((x) => x !== principal).map((x) => x || PRINCIPAL);
              c = u.poner({ ...u.obj, camino: principal || undefined, tambien_en_caminos: otros.length > 0 ? otros : undefined } as unknown as PiezaUbicada["obj"]);
            }
          }
        }
        const conIds = cambiados.size > 0 ? conIdsNuevos(c, cambiados) : c;
        const hecho = aplicarConSeguro(
          conDisposicion(conIds, (d) => ({
            ...d,
            comunes: (d.comunes ?? []).filter((x) => {
              const [p, id] = x.split("|");
              return !(p === pais && piezaIds.includes(id));
            }),
          })),
          pais
        );
        if (hecho) setAviso(aviso ?? `Conectada en ${banderaDe(pais)} ${pais}: ya sale ahí. Es COMÚN: si la editas, cambia en todos sus países.`);
      },
      // CREAR DESDE UN GESTOR (19/10/2026): «al crearlo se abre un pop up que no tiene nada que ver
      // con el diseño». Lo mismo que `crearConectada`, pero SIN abrir la ventana vieja (el gestor
      // la enseña dentro) y en el CAMINO del cajón. Devuelve su id, para que el gestor la elija.
      crearEnGestor: (que: LoQueSeCrea, pais: string, camino: string) => {
        const { cfg: c, canal: k, tiendaId: t } = vivo.current;
        const id = idDeLaNueva(c, que);
        const creada = agregarPieza(c, k, que, t);
        if (!creada || !id) return null;
        const conectada = conectarSobre(creada, id, pais, false, que.tipo === "seguimiento-nuevo");
        if (!conectada) return null;
        const real = idReal.current ?? id;
        let r = conectada;
        if (camino) {
          const u = ubicarPieza(r, k, real);
          if (u) r = u.poner({ ...u.obj, camino } as unknown as PiezaUbicada["obj"]);
        }
        return aplicarConSeguro(aLaVista(r, real), pais) ? real : null;
      },
      // DUPLICAR UNA VERSIÓN DESDE EL GESTOR: la copia, conectada a ese país y en ese camino.
      duplicarEnGestor: (piezaId: string, pais: string, camino: string) => {
        const { cfg: c0, canal: k } = vivo.current;
        // Seguimientos y presentaciones del upsell 1 (20/10/2026: «el mismo upsell, con una segunda versión»).
        const que: LoQueSeAgrega | null = piezaId.startsWith("seg:")
          ? { tipo: "seguimiento", indice: Number(piezaId.split(":")[1]) }
          : piezaId.startsWith("up:")
            ? { tipo: "upsell" }
            : null;
        if (!que) return null;
        const idCopia = idDeLaNueva(c0, que);
        const copiaSola = duplicarPieza(c0, k, piezaId, semiParaLaCopia(piezaId));
        if (!copiaSola || !idCopia) {
          setAviso("Los «mensajes principales» se duplican en su sección de siempre.");
          return null;
        }
        const copia = conLaApagadaRecordada(conBotonesPorConectar(copiaSola, idCopia), piezaId, idCopia);
        const conectada = conectarSobre(copia, idCopia, pais, false);
        if (!conectada) return null;
        const real = idReal.current ?? idCopia;
        let r = conectada;
        if (camino) {
          const u = ubicarPieza(r, k, real);
          if (u) r = u.poner({ ...u.obj, camino } as unknown as PiezaUbicada["obj"]);
        }
        // A la vista, como al crear: la copia de una versión VACÍA tampoco está en su fila todavía,
        // y sin esto el gestor no la encontraba (medido: duplicar una vacía «no hacía nada»).
        return aplicarConSeguro(aLaVista(r, real), pais) ? real : null;
      },
      cambiarDisposicion: (d: DisposicionDePizarra) => aplicar(conDisposicion(vivo.current.cfg, () => d)),
      seguimientos: [],
      conOferta: false,
      // PEGAR (17/10/2026): una copia SUELTA de cada ficha, en su sitio, con los cables del grupo
      // guardados en la pizarra («enlaces»). Cada copia, igual que «Duplicar»: al final de su
      // lista, apagada y sin país —hasta que la conecte, el bot no la manda— y con botones de
      // código propio (`conBotonesNuevos`).
      // DÓNDE SE COPIÓ (25/10/2026): «copiaste en COMO OB pero estás pegando en LINEAL…».
      alCopiar: () => {
        semiDelPortapapeles = SEMI_CORTA[vivo.current.semi] ?? null;
      },
      pegar: (items: Array<{ piezaId: string; donde: { x: number; y: number }; recuadros?: Array<{ x: number; y: number } | null> }>, enlaces: Array<[number, number]>) => {
        const { canal: k } = vivo.current;
        // PEGAR EN OTRA FORMA DE VENDER: se avisa antes. La tubería de COMO OB lleva la oferta de 2
        // opciones; en LINEAL eso no existe, y al revés faltaría. Si dice que sí, se pega aquí.
        const aqui = SEMI_CORTA[vivo.current.semi];
        if (semiDelPortapapeles && aqui && semiDelPortapapeles !== aqui) {
          const nombre = (s: string) => NOMBRE_DE_LA_SEMI[s] ?? s;
          const seguir = window.confirm(
            `Copiaste en ${nombre(semiDelPortapapeles)} y estás pegando en ${nombre(aqui)}.\n\n` +
              `Puede haber incompatibilidad: cada forma de vender tiene sus pasos (por ejemplo, la oferta de 2 opciones solo existe en COMO OB).\n\n` +
              `¿Pegar igual aquí, en ${nombre(aqui)}? Las copias quedan solo en ${nombre(aqui)}.`
          );
          if (!seguir) {
            setAviso("No se pegó nada.");
            return [];
          }
        }
        let c: FullConfig = vivo.current.cfg;
        const nuevas: string[] = [];
        const deCadaUna: (string | null)[] = [];
        for (const { piezaId, donde, recuadros } of items) {
          const [tipo, a] = piezaId.split(":");
          const que: LoQueSeAgrega | null =
            tipo === "intro" ? { tipo: "intro" } : tipo === "ob" ? { tipo: "ob" } : tipo === "up" ? { tipo: "upsell" }
            : tipo === "seg" ? { tipo: "seguimiento", indice: Number(a) } : null;
          const id = que ? idDeLaNueva(c, que) : null;
          const copia = id ? duplicarPieza(c, k, piezaId, semiParaLaCopia(piezaId)) : null;
          if (!copia || !id) {
            deCadaUna.push(null);
            continue;
          }
          // PEGADA EN OTRA TIENDA, ES DE ÉSTA (19/10/2026): la copia nombraba a la tienda de la
          // original, así que aquí no se veía como suya (y el bot no la mandaba aquí).
          const tiendaDeAqui = vivo.current.tiendaId;
          const u = tiendaDeAqui ? ubicarPieza(copia, k, id) : null;
          const susTiendas = (u?.obj as { tiendas?: string[] } | undefined)?.tiendas ?? [];
          const enEsta = u && susTiendas.length > 0 && !susTiendas.includes(tiendaDeAqui) ? u.poner({ ...u.obj, tiendas: [tiendaDeAqui] }) : copia;
          c = conLaApagadaRecordada(conBotonesPorConectar(conRecuadros(aLaVista(enEsta, id, donde), id, recuadros), id), piezaId, id);
          nuevas.push(id);
          deCadaUna.push(id);
        }
        if (nuevas.length === 0) {
          setAviso("Los «mensajes principales» de un seguimiento no se copian aquí: se duplican en su sección de siempre.");
          return [];
        }
        const delGrupo = enlaces.flatMap(([i, j]) =>
          deCadaUna[i] && deCadaUna[j] ? [`${deCadaUna[i]}|${deCadaUna[j]}`] : []
        );
        if (delGrupo.length > 0) {
          c = conDisposicion(c, (d) => ({ ...d, enlaces: [...new Set([...(d.enlaces ?? []), ...delGrupo])] }));
        }
        aplicar(c);
        return nuevas;
      },
      quitarEnlace: (de: string, a: string) => {
        aplicar(
          conDisposicion(vivo.current.cfg, (d) => ({ ...d, enlaces: (d.enlaces ?? []).filter((x) => x !== `${de}|${a}`) }))
        );
      },
      // LOS UPSELLS EN FILA DE ESTA TIENDA, desde la pizarra (17/10/2026). Escriben en la MISMA
      // fila que el menú Upsell → «Upsells en fila»: no hay una segunda copia de nada.
      fila: {
        agregar: (productoId: string) => {
          const { cfg: c, tiendaId: t } = vivo.current;
          let nuevo = 0;
          const conElNuevo = conLaFilaDeLaTienda(c, t, (puestos) => {
            nuevo = puestos.length;
            return [...puestos, { producto_id: productoId, minutos: 0, enabled: true }];
          });
          // Nace junto a lo suyo: se olvida el sitio que tuvo otro upsell con ese número.
          aplicar(sinSitiosDeLaFila(conElNuevo, nuevo));
          setAviso("Upsell agregado al final de la fila. Su presentación se escribe en su ficha de producto (Contenido).");
        },
        alternar: (k: number) => {
          const { cfg: c, tiendaId: t } = vivo.current;
          aplicar(conLaFilaDeLaTienda(c, t, (puestos) => puestos.map((p, i) => (i === k ? { ...p, enabled: p.enabled === false } : p))));
        },
        quitar: (k: number) => {
          const { cfg: c, tiendaId: t } = vivo.current;
          if (!window.confirm("¿Quitar este upsell de la fila? El producto no se borra de Contenido.")) return;
          // Los de detrás cambian de número: sus sitios viejos ya no son suyos.
          aplicar(sinSitiosDeLaFila(conLaFilaDeLaTienda(c, t, (puestos) => puestos.filter((_, i) => i !== k)), k));
        },
        minutos: (k: number, minutos: number) => {
          const { cfg: c, tiendaId: t } = vivo.current;
          aplicar(conLaFilaDeLaTienda(c, t, (puestos) => puestos.map((p, i) => (i === k ? { ...p, minutos } : p))));
        },
        // CAMBIAR SU PRODUCTO (19/10/2026): «solo veo que se pueden crear pero no cambiar de
        // producto». El mismo puesto, con otro producto; su sitio en la pizarra se olvida.
        cambiar: (k: number, productoId: string) => {
          const { cfg: c, tiendaId: t } = vivo.current;
          aplicar(sinSitiosDeLaFila(conLaFilaDeLaTienda(c, t, (puestos) => puestos.map((p, i) => (i === k ? { ...p, producto_id: productoId } : p))), k));
        },
        // CAMBIAR EL ORDEN, CON FLECHAS (19/10/2026), como el gestor de Sendy. Los dos que se
        // cruzan pierden su sitio guardado en la pizarra (ya no son el mismo número).
        mover: (k: number, haciaArriba: boolean) => {
          const { cfg: c, tiendaId: t } = vivo.current;
          const j = haciaArriba ? k - 1 : k + 1;
          aplicar(
            sinSitiosDeLaFila(
              sinSitiosDeLaFila(
                conLaFilaDeLaTienda(c, t, (puestos) => {
                  if (j < 0 || j >= puestos.length) return puestos;
                  const copia = [...puestos];
                  [copia[k], copia[j]] = [copia[j], copia[k]];
                  return copia;
                }),
                k
              ),
              j
            )
          );
        },
      },
    }),
    // `vivo` siempre trae lo último; las funciones no necesitan rehacerse.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    []
  );
  const agregar = (que: LoQueSeAgrega) => {
    setMenuMas(false);
    const id = idDeLaNueva(cfg, que);
    const nuevo = agregarPieza(cfg, canal, que, tiendaId);
    if (!nuevo || !id) return;
    // A LA VISTA, sin conectar: él la escribe con doble clic y la conecta arrastrando.
    aplicar(aLaVista(nuevo, id));
    setAviso("Ficha nueva, sin conectar, debajo de los caminos. Doble clic en su franja para escribirla, y arrastra hasta su punto verde el naranja de un país para conectarla.");
  };
  const canalUsaLoSuyo = cfg.channels?.[canal]?.use_content === true;
  // LA VISTA PREVIA DE LA PIZARRA, CON LOS PRODUCTOS DE SU TIENDA (17/10/2026). Él eligió en
  // GRAFISMO el básico GRAFISMO FONÉTICO y la vista previa decía LECTOESCRITURA, el de la
  // alineación general. Medido: la ventana calculaba bien los de la tienda, pero `ChatPreview`
  // aplica al final el contexto HEREDADO del editor —a propósito, para que el país mande en
  // todas— y ése traía los nombres y precios generales. Aquí lo heredado pasa a ser el de la
  // tienda: mismo país (`activePreviewCountry`), sus productos y sus precios.
  const contextoHeredado = useContext(EditorPreviewContext);
  const contextoDeLaTienda = useMemo<PreviewContext>(
    () => ({ ...contextoHeredado, ...previewContextFromConfig(configComoLaVeLaTienda(cfg, tienda, semi)) }),
    [contextoHeredado, cfg, tienda, semi]
  );
  const completo = useMemo<ModeloDePizarra | null>(
    () => (canalUsaLoSuyo ? modeloDePizarra(cfg, canal, tiendaId, semi, tiendas, paisesExtra) : null),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [cfg, canal, tiendaId, semi, canalUsaLoSuyo, paisesExtra]
  );
  vivo.current.piezas = completo?.piezas ?? [];
  estacionesVivas.current = completo?.estaciones ?? [];
  // CADA TIENDA CON LO SUYO, SOLO (17/10/2026): al abrir la pizarra de una tienda, lo
  // compartido que ella usa pasa a ser suyo (copias idénticas al final; las originales siguen
  // para las demás). Después no queda nada compartido y la pizarra no tiene nada que avisar.
  // Si no hay nada compartido no hace nada, así que no se repite.
  useEffect(() => {
    if (pantalla !== "pizarra" || !canalUsaLoSuyo || !tiendaId) return;
    const r = hacerPropiaLaTienda(cfg, canal, tiendaId, semi, tiendas, paisesExtra);
    const deLaTienda = r.mapa.size > 0 ? conIdsNuevos(r.cfg, r.mapa) : cfg;
    // Y CADA SEMIMODALIDAD CON LO SUYO (18/10/2026), sobre lo que ya es de la tienda.
    const s = hacerPropiaLaSemi(deLaTienda, canal, tiendaId, semi, tiendas, paisesExtra);
    if (r.mapa.size === 0 && s.mapa.size === 0) return;
    // SIN PASO DE DESHACER PROPIO: no es un cambio suyo. Si fuera un paso, Ctrl+Z lo desharía y
    // se volvería a hacer al instante, y él quedaría trabado ahí.
    onConfigChange(s.mapa.size > 0 ? conIdsNuevos(s.cfg, s.mapa) : deLaTienda);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cfg, canal, tiendaId, pantalla, canalUsaLoSuyo]);
  const seguimientosDelCanal = canalUsaLoSuyo ? channelContentForMode(cfg, canal, activeModality(cfg)).followups : [];
  // Lo que cambia con el contenido va aparte, para no rehacer las acciones.
  /**
   * CLIENTES Y VENTAS POR RUTA (20/10/2026): «yo veo cuál ruta vende más y las demás las apago».
   * Se leen los chats (solo lectura, lo mismo que pide el panel) y se cuentan por país y por la
   * ruta que anotó el bot al mandar la intro. Las rutas B, C… son de una sola tienda; la A (la
   * principal) junta a todas las tiendas que venden en ese país, y se dice.
   */
  const [chatsParaRutas, setChatsParaRutas] = useState<Array<{ phone: string; channel?: string; camino?: string | null; intro_variant_sent?: number | null; paid_total_cents?: number }>>([]);
  useEffect(() => {
    let vivoAun = true;
    void (async () => {
      try {
        const res = await fetch("/api/conversations", { cache: "no-store" });
        if (!res.ok) return;
        const d = (await res.json()) as { conversations?: typeof chatsParaRutas };
        if (vivoAun) setChatsParaRutas(d.conversations ?? []);
      } catch {}
    })();
    return () => {
      vivoAun = false;
    };
  }, []);
  const numerosPorRuta = useMemo(() => {
    const m = new Map<string, { clientes: number; ventas: number; ahora?: number }>();
    for (const c of chatsParaRutas) {
      if ((c.channel ?? "whatsapp") !== "whatsapp") continue;
      if (c.intro_variant_sent == null && !c.camino) continue;
      const pais = countryFromPhone(c.phone);
      if (!pais) continue;
      const k = `${pais}|${String(c.camino ?? "").trim()}`;
      const v = m.get(k) ?? { clientes: 0, ventas: 0 };
      v.clientes += 1;
      if ((c.paid_total_cents ?? 0) > 0) v.ventas += 1;
      m.set(k, v);
    }
    return m;
  }, [chatsParaRutas]);
  /**
   * EL EDITOR DENTRO DE LOS GESTORES (19/10/2026): «no debería estar el paso de Editar en el botón
   * verde, sino mostrarse tal como está en el ejemplo de seguimientos de Sendy». El MISMO editor de
   * la ventana (`VentanaDelCajon`), incrustado, y al aplicar lo MISMO que su «Listo».
   */
  /** Los anuncios que ya llevan las intros y seguimientos dibujados en esta pizarra: en el selector
   *  de anuncios, sus campañas van primero (19/10/2026). */
  const anunciosDeLaTienda = (() => {
    if (!completo) return [];
    const enLaPizarra = new Set(completo.estaciones.flatMap((e) => e.filas.flatMap((f) => (f.estado === "prestada" ? [] : f.piezas))));
    return [
      ...new Set(
        completo.piezas
          .filter((p) => enLaPizarra.has(p.id) && /^(intro|seg):/.test(p.id))
          .flatMap((p) => {
            const o = ubicarPieza(cfg, canal, p.id)?.obj as { adKeys?: string[]; ad_keys?: string[] } | undefined;
            return (p.id.startsWith("intro:") ? o?.adKeys : o?.ad_keys) ?? [];
          })
      ),
    ];
  })();
  const editorIncrustado = (piezaId: string, pais?: string) => {
    const pieza = piezaEditable(cfg, canal, piezaId, tiendaId);
    if (!pieza) return <p className="text-sm text-tinta-suave">No se encontró esta ficha.</p>;
    const anuncios = (() => {
      if (!/^(intro|seg):/.test(piezaId)) return undefined;
      const u = ubicarPieza(cfg, canal, piezaId);
      if (!u) return undefined;
      const o = u.obj as { adKeys?: string[]; adRoutingEnabled?: boolean; ad_keys?: string[]; ad_routing_enabled?: boolean };
      const esIntro = piezaId.startsWith("intro:");
      return {
        claves: (esIntro ? o.adKeys : o.ad_keys) ?? [],
        dirigir: (esIntro ? o.adRoutingEnabled : o.ad_routing_enabled) !== false,
        registro: cfg.ad_registry ?? [],
        alCambiarRegistro: (ad_registry: AdRegistryEntry[]) => aplicar({ ...vivo.current.cfg, ad_registry }),
        deLaTienda: anunciosDeLaTienda,
      };
    })();
    return (
      <VentanaDelCajon
        key={`${piezaId}|${pais ?? ""}`}
        incrustado
        titulo={pieza.titulo}
        nombre={nombreDePieza(cfg, canal, piezaId)}
        steps={pieza.steps}
        idPrefix={`gestor_${piezaId.replace(/[^a-z0-9]/gi, "_")}`}
        cfgVista={configComoLaVeLaTienda(cfg, tienda, semi)}
        pais={pais}
        seguimiento={piezaId.startsWith("seg:") ? Number(piezaId.split(":")[1]) : undefined}
        anuncios={anuncios}
        onGuardar={(steps, nombre, anunciosNuevos) => {
          // Lo mismo que «Listo» en la ventana, sobre lo ÚLTIMO (se puede aplicar al cerrar). Si
          // mientras tanto nació su copia propia (al encenderla o cambiarle el peso), va a ésa.
          const { cfg: c, canal: k, tiendaId: t } = vivo.current;
          const idAhora = copiaDeLaFicha.current[piezaId] ?? piezaId;
          const esDeLaPizarra = /^(intro|ob|up|seg):/.test(idAhora);
          const propia = esDeLaPizarra ? deEstaTienda(c, idAhora) : { cfg: c, id: idAhora };
          const suya = piezaEditable(propia.cfg, k, propia.id, t);
          if (!suya) return;
          const conSusPasos = suya.conPasos(steps);
          const conNombre = nombre !== undefined ? renombrarPieza(conSusPasos, k, propia.id, nombre) : conSusPasos;
          let conTodo = conNombre;
          if (anunciosNuevos) {
            const u = ubicarPieza(conNombre, k, propia.id);
            if (u) {
              const esIntro = propia.id.startsWith("intro:");
              conTodo = u.poner(
                (esIntro
                  ? { ...u.obj, adKeys: anunciosNuevos.claves, adRoutingEnabled: anunciosNuevos.dirigir }
                  : { ...u.obj, ad_keys: anunciosNuevos.claves, ad_routing_enabled: anunciosNuevos.dirigir }) as unknown as PiezaUbicada["obj"]
              );
            }
          }
          if (propia.id !== idAhora) copiaDeLaFicha.current[piezaId] = propia.id;
          aplicar(propia.id !== idAhora ? conIdsNuevos(conTodo, new Map([[idAhora, propia.id]])) : conTodo);
        }}
        onCerrar={() => {}}
      />
    );
  };
  const textoDelRegaloIncrustado = (cual: "regalo-premio" | "regalo-despedida") =>
    cfg.gift ? (
      <VentanaDeTexto
        key={cual}
        incrustado
        titulo={cual === "regalo-premio" ? "4. Premio" : "Despedida · si dice que no"}
        valor={
          (cual === "regalo-premio"
            ? tienda?.regalo?.reward_message?.trim() ? tienda.regalo.reward_message : cfg.gift.reward_message
            : tienda?.regalo?.decline_message?.trim() ? tienda.regalo.decline_message : cfg.gift.decline_message) ?? ""
        }
        cfgVista={configComoLaVeLaTienda(cfg, tienda, semi)}
        onGuardar={(texto) => {
          const c = vivo.current.cfg;
          const cambio = cual === "regalo-premio" ? { reward_message: texto } : { decline_message: texto };
          const t = (c.tiendas ?? []).find((x) => x.id === vivo.current.tiendaId);
          if (t) aplicar(conRegaloDeLaTienda(c, t.id, cambio));
          else if (c.gift) aplicar({ ...c, gift: { ...c.gift, ...cambio } });
        }}
        onCerrar={() => {}}
      />
    ) : (
      <p className="text-sm text-tinta-suave">El regalo no está configurado.</p>
    );
  const cobroIncrustado = (pais?: string) =>
    tienda ? (
      <VentanaDelCobro
        incrustado
        cfg={cfg}
        tienda={tienda}
        pais={pais || undefined}
        onCobrador={(id) => {
          const c = vivo.current.cfg;
          aplicar({ ...c, tiendas: (c.tiendas ?? []).map((t) => (t.id === vivo.current.tiendaId ? { ...t, cobrador: id } : t)) });
        }}
        onCobradores={(cobradores) => onConfigChange({ ...vivo.current.cfg, cobradores })}
        onSnapshot={onSnapshot}
        onCerrar={() => {}}
      />
    ) : null;
  // Lo último, para leerlo sin rehacer las acciones en cada cambio.
  const rutasVivas = useRef({ completo, numerosPorRuta });
  rutasVivas.current = { completo, numerosPorRuta };
  const accionesVivas = useMemo<AccionesDelLienzo>(
    () => ({
      ...acciones,
      // Las rutas de un país en ESTA pizarra (los caminos de sus intros), con sus números.
      numerosDeLasRutas: (pais: string) => {
        const { completo, numerosPorRuta } = rutasVivas.current;
        const fila = completo?.estaciones.find((e) => e.tipo === "intro")?.filas.find((f) => f.clave === pais);
        const caminos = [
          ...new Set(
            (fila?.estado === "prestada" ? [] : fila?.piezas ?? []).flatMap((pid) => {
              const p = completo?.piezas.find((x) => x.id === pid);
              return p?.caminos ?? [p?.camino ?? ""];
            })
          ),
        ].sort();
        if (caminos.length < 2) return [];
        return caminos.map((c) => ({ ruta: c || "A", ...(numerosPorRuta.get(`${pais}|${c}`) ?? { clientes: 0, ventas: 0 }) }));
      },
      seguimientos: seguimientosDelCanal.map((f, i) => ({
        indice: i,
        nombre: f.name || `Seguimiento ${i + 1}`,
        minutos: f.delay_minutes_from_first_message,
      })),
      conOferta: semi === "segunda_oculta",
      irAlMenu: onIrAlMenu,
      // LOS TIEMPOS EN SU TARJETA (17/10/2026). Escriben en el MISMO dato que su menú: el del
      // seguimiento (Canales), el del upsell (menú Upsell) y el del regalo (menú ajustes).
      tiempos: {
        upsell: cfg.upsell?.retraso_minutos ?? 5,
        regalo: cfg.globals?.awaiting_email_timeout_seconds,
      },
      cambiarTiempo: (que: "upsell" | "regalo" | number, valor: number) => {
        const { cfg: c, canal: k } = vivo.current;
        if (que === "upsell") aplicar({ ...c, upsell: { ...c.upsell, retraso_minutos: valor } });
        else if (que === "regalo") aplicar({ ...c, globals: { ...c.globals, awaiting_email_timeout_seconds: valor } });
        else aplicar(conMinutosDelSeguimiento(c, k, que, valor));
      },
      // Con TODOS los países de esta pizarra: el visor pone una columna por cada uno.
      verRecorrido: (pais: string) =>
        onVerRecorrido?.(
          vivo.current.tiendaId,
          pais,
          (completo?.estaciones[0]?.filas ?? []).map((f) => f.clave).filter(Boolean)
        ),
      // EL PESO, desde la tarjeta (17/10/2026). En la ficha de ESTA tienda: si era compartida,
      // se cambia su copia propia, como al editar sus burbujas. Los «mensajes principales» de
      // un seguimiento guardan el suyo en `steps_weight`.
      cambiarPeso: (piezaId: string, peso: number) =>
        cambiarEnLaFicha(
          piezaId,
          (obj, esBase) =>
            (esBase ? { ...obj, steps_weight: peso } : { ...obj, weight: peso }) as unknown as PiezaUbicada["obj"]
        ),
      // EL UPSELL 1 DE ESTA TIENDA (17/10/2026): «yo pueda activar ese upsell desde adentro de esa
      // ficha». Es el MISMO puesto «upsell» de su tienda (menú ajustes → Tiendas). Si la tienda
      // todavía no tenía productos propios, primero se copian los generales: el bot usa los de la
      // tienda O los generales, nunca mezclados, y sin esto se quedaría sin básico ni full.
      elegirUpsell: (productoId: string) => {
        const { cfg: c, tiendaId: t } = vivo.current;
        const general = c.alineacion_por_modalidad?.[activeModality(c)] ?? {};
        aplicar({
          ...c,
          tiendas: (c.tiendas ?? []).map((x) => {
            if (x.id !== t) return x;
            const propia = Object.fromEntries(Object.entries(x.alineacion ?? {}).filter(([, v]) => v));
            const base = Object.keys(propia).length > 0 ? propia : Object.fromEntries(Object.entries(general).filter(([, v]) => v));
            return { ...x, alineacion: { ...base, upsell: productoId }, upsell_apagado: undefined };
          }),
        });
        setAviso("Upsell elegido para esta tienda. Ya se ofrece después de la entrega.");
      },
      // LOS CAJONES (19/10/2026): su gestor se abre encima de la pizarra.
      abrirGestor: (cual: "regalo" | "upsells" | "cobro" | "seguimientos", pais: string, camino?: string, soloEstas?: string[]) =>
        setGestorAbierto({ cual, pais, camino, soloEstas }),
      // EL CABLE DEL REGALO ES VERDADERO (19/10/2026): es el MISMO interruptor del menú Regalo
      // (`gift.has`), uno solo para todo el bot. Por eso pregunta antes.
      alternarRegalo: (encender: boolean) => {
        const c = vivo.current.cfg;
        if (!c.gift) return;
        if (
          !window.confirm(
            encender
              ? "Esto ENCIENDE el regalo en todos los países y todas tus tiendas (cada una ofrece el suyo). ¿Seguir?"
              : "Esto APAGA el regalo en todos los países y todas tus tiendas. ¿Seguir?"
          )
        )
          return;
        aplicar({ ...c, gift: { ...c.gift, has: encender } });
        setAviso(encender ? "Regalo encendido. Ctrl+Z lo deshace." : "Regalo apagado. Ctrl+Z lo deshace.");
      },
      // EL CABLE DE LOS UPSELLS ES VERDADERO (19/10/2026), en ESTA tienda: cortarlo apaga el upsell
      // 1 (sin perder su producto) y los de su fila; conectarlo enciende el upsell 1 o, si no tiene,
      // el primero de la fila. Son los mismos interruptores de cada upsell.
      alternarUpsells: (encender: boolean) => {
        const { cfg: c0, tiendaId: t } = vivo.current;
        if (
          !window.confirm(
            encender
              ? "Esto enciende el primer upsell de esta tienda. ¿Seguir?"
              : "Esto APAGA todos los upsells de esta tienda (no se borra ninguno; se encienden en su gestor). ¿Seguir?"
          )
        )
          return;
        const general = c0.alineacion_por_modalidad?.[activeModality(c0)] ?? {};
        let c = c0;
        let hecho = false;
        c = {
          ...c,
          tiendas: (c.tiendas ?? []).map((x) => {
            if (x.id !== t) return x;
            const propia = Object.fromEntries(Object.entries(x.alineacion ?? {}).filter(([, v]) => v));
            const base = Object.keys(propia).length > 0 ? propia : Object.fromEntries(Object.entries(general).filter(([, v]) => v));
            if (!encender && base.upsell) {
              const { upsell: suyo, ...sinUpsell } = base;
              hecho = true;
              return { ...x, alineacion: sinUpsell, upsell_apagado: suyo };
            }
            if (encender && !base.upsell && x.upsell_apagado) {
              hecho = true;
              return { ...x, alineacion: { ...base, upsell: x.upsell_apagado }, upsell_apagado: undefined };
            }
            return x;
          }),
        };
        if (!encender) {
          c = conLaFilaDeLaTienda(c, t, (puestos) => puestos.map((p) => ({ ...p, enabled: false })));
        } else if (!hecho) {
          c = conLaFilaDeLaTienda(c, t, (puestos) => puestos.map((p, i) => (i === 0 ? { ...p, enabled: true } : p)));
        }
        aplicar(c);
        setAviso(encender ? "Upsells encendidos. Ctrl+Z lo deshace." : "Upsells de esta tienda apagados. Ctrl+Z lo deshace.");
      },
      // ENCENDER O APAGAR EL UPSELL 1 SIN PERDER SU PRODUCTO (19/10/2026): «al desactivar el upsell
      // 1 se quita el producto, no debe ser así». Apagado, su producto sale de los de la tienda
      // —para el bot, como antes: no hay upsell 1— y se guarda en `upsell_apagado`; al
      // encenderlo vuelve a su sitio. El motor no cambia.
      alternarUpsell1: () => {
        const { cfg: c, tiendaId: t } = vivo.current;
        const general = c.alineacion_por_modalidad?.[activeModality(c)] ?? {};
        let encendido = false;
        aplicar({
          ...c,
          tiendas: (c.tiendas ?? []).map((x) => {
            if (x.id !== t) return x;
            const propia = Object.fromEntries(Object.entries(x.alineacion ?? {}).filter(([, v]) => v));
            const base = Object.keys(propia).length > 0 ? propia : Object.fromEntries(Object.entries(general).filter(([, v]) => v));
            if (base.upsell) {
              const { upsell: suyo, ...sinUpsell } = base;
              return { ...x, alineacion: sinUpsell, upsell_apagado: suyo };
            }
            if (x.upsell_apagado) {
              encendido = true;
              return { ...x, alineacion: { ...base, upsell: x.upsell_apagado }, upsell_apagado: undefined };
            }
            return x;
          }),
        });
        setAviso(encendido ? "Upsell 1 encendido: ya se ofrece después de la entrega." : "Upsell 1 apagado: el bot lo salta. Su producto queda guardado para encenderlo otra vez.");
      },
      // LO CONTRARIO (17/10/2026): «si agregas algo, también que tenga opción de quitarse». Saca el
      // upsell de los productos de ESTA tienda; las demás no cambian. Si la tienda usaba los
      // generales, se copian sin el upsell (el bot usa los de la tienda O los generales, sin mezclar).
      quitarUpsell: () => {
        const { cfg: c, tiendaId: t } = vivo.current;
        const general = c.alineacion_por_modalidad?.[activeModality(c)] ?? {};
        aplicar({
          ...c,
          tiendas: (c.tiendas ?? []).map((x) => {
            if (x.id !== t) return x;
            const propia = Object.fromEntries(Object.entries(x.alineacion ?? {}).filter(([, v]) => v));
            const base = Object.keys(propia).length > 0 ? propia : Object.fromEntries(Object.entries(general).filter(([, v]) => v));
            const { upsell: _fuera, ...sinUpsell } = base;
            return { ...x, alineacion: sinUpsell };
          }),
        });
        setAviso("Upsell desactivado en esta tienda. Ctrl+Z lo devuelve mientras no guardes.");
      },
    }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [
      acciones,
      seguimientosDelCanal.length,
      seguimientosDelCanal.map((f) => f.delay_minutes_from_first_message).join(","),
      semi,
      cfg.upsell?.retraso_minutos,
      cfg.globals?.awaiting_email_timeout_seconds,
      // Los países de la pizarra, para «▶ Ver recorrido».
      (completo?.estaciones[0]?.filas ?? []).map((f) => f.clave).join(","),
      // Al llegar los números de las rutas, el Inicio de cada país los enseña.
      numerosPorRuta,
    ]
  );
  // LAS SUELTAS YA NO SE FILTRAN AQUÍ: el lienzo enseña las que él dejó a la vista y el resto
  // va al panel «Fichas guardadas».
  // LAS ARCHIVADAS NO SE VEN (17/10/2026): «eliminar» de un seguimiento del medio la archiva —el
  // bot nunca la manda— y desaparece de la pizarra y de «Fichas guardadas». Ver `quitarUna`.
  // (De TODAS las pizarras de esta tienda y canal: una archivada no sale en ninguna semimodalidad.)
  const archivadas = new Set(
    Object.entries(cfg.pizarra?.vistas ?? {})
      .filter(([k]) => k === `${tiendaId}|${canal}` || k.startsWith(`${tiendaId}|${canal}|`))
      .flatMap(([, v]) => v.archivadas ?? [])
  );
  const modelo =
    completo && archivadas.size > 0
      ? {
          ...completo,
          piezas: completo.piezas.filter((p) => !archivadas.has(p.id)),
          estaciones: completo.estaciones.map((e) => ({ ...e, piezas: e.piezas.filter((id) => !archivadas.has(id)) })),
        }
      : completo;
  const disposicion = useMemo<DisposicionDePizarra>(
    () => vistaDeLaPizarra(cfg, tiendaId, canal, semi) ?? { posiciones: {} },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [cfg.pizarra, claveDeVista]
  );
  // (La franja roja «⛔ Sin intro, no avanzan» se quitó el 20/10/2026: «ensucia la pantalla». Lo
  // dice el Inicio de cada país, que se pone anaranjado cuando está desconectado.)
  const CANALES: Array<{ clave: ChannelKey; nombre: string }> = [
    { clave: "whatsapp", nombre: "WhatsApp" },
    { clave: "messenger", nombre: "Messenger" },
    { clave: "instagram", nombre: "Instagram" },
  ];
  const botonDeBarra = "rounded-md border border-borde bg-relleno px-3 py-1 text-xs font-semibold text-tinta hover:bg-tarjeta disabled:opacity-40";

  return (
    <div className="fixed inset-0 z-40 flex flex-col bg-fondo">
      {/* CONGELADA MIENTRAS GUARDA (17/10/2026): «necesito congelar la pantalla mientras guarda».
          Un velo encima de todo: nada se mueve ni se cambia hasta que termina, y se dice. */}
      {saving && (
        <div
          className="absolute inset-0 z-[80] flex items-center justify-center bg-black/30"
          onPointerDownCapture={(e) => e.stopPropagation()}
          onKeyDownCapture={(e) => e.preventDefault()}
        >
          <div className="rounded-xl bg-tarjeta px-5 py-3 text-sm font-bold text-tinta shadow-2xl">💾 Guardando… espera un momento</div>
        </div>
      )}
      {/* LA BARRA DE LA PIZARRA: lo de siempre del editor arriba —vista, modo, deshacer,
          guardar— y lo de la pizarra debajo. */}
      <div className={`flex flex-wrap items-center gap-2 border-b border-borde bg-tarjeta px-4 py-2 text-tinta ${fondoOscuro ? "tema-oscuro-local" : ""}`}>
        <span className="inline-flex overflow-hidden rounded-lg border border-borde text-xs" role="group" aria-label="Vista del editor">
          <button type="button" onClick={onClose} className="bg-tarjeta px-3 py-1.5 font-semibold text-tinta-suave hover:bg-relleno">
            ☰ Menús
          </button>
          <button type="button" aria-pressed className="bg-carbon-fuerte px-3 py-1.5 font-semibold text-white">
            ◈ Pizarra
          </button>
        </span>
        <span className="inline-flex overflow-hidden rounded-lg border border-borde text-xs" role="group" aria-label="Modo del editor">
          {([[true, "Modo esencial"], [false, "Modo profesional"]] as const).map(([esencial, nombre]) => (
            <button
              key={nombre}
              type="button"
              aria-pressed={modoEsencial === esencial}
              onClick={() => onModoEsencial(esencial)}
              className={`px-3 py-1.5 font-semibold ${modoEsencial === esencial ? "bg-carbon-fuerte text-white" : "bg-tarjeta text-tinta-suave hover:bg-relleno"}`}
            >
              {nombre}
            </button>
          ))}
        </span>
        <span className="ml-auto" />
        <button type="button" onClick={onUndo} title="Deshacer (Ctrl+Z)" className={botonDeBarra}>↶ Deshacer</button>
        <button type="button" onClick={onRedo} title="Rehacer (Ctrl+Shift+Z)" className={botonDeBarra}>↷ Rehacer</button>
        {hayCambios && <span className="text-[11px] font-semibold text-amber-700">● Sin guardar</span>}
        <button
          type="button"
          onClick={onSave}
          disabled={saving || !hayCambios}
          title="Guardar (Ctrl+S)"
          className="rounded-md bg-emerald-600 px-3 py-1 text-xs font-bold text-white hover:bg-emerald-700 disabled:opacity-40"
        >
          {saving ? "Guardando…" : "💾 Guardar"}
        </button>
      </div>
      {pantalla === "tiendas" ? (
        <MisTiendas
          cfg={cfg}
          onAbrir={(id) => {
            setTiendaId(id);
            irA("pizarra");
          }}
          onTablero={(id) => {
            setTiendaId(id);
            setWorkflowAbierto(null);
            irA("tablero");
          }}
          onWorkflow={(id) => {
            setWorkflowAbierto(id);
            irA("tablero");
          }}
          onCambiar={aplicar}
          onConfigChange={onConfigChange}
          onSnapshot={onSnapshot}
        />
      ) : pantalla === "tablero" ? (
        <PantallaDelTablero
          cfg={cfg}
          clave={workflowAbierto ? `wf:${workflowAbierto}` : tiendaId}
          tema={temaDeLaPizarra}
          onTema={cambiarTemaDeLaPizarra}
          onTienda={(id) => {
            setWorkflowAbierto(null);
            setTiendaId(id);
          }}
          onVolver={() => {
            setWorkflowAbierto(null);
            irA("tiendas");
          }}
          aplicar={aplicar}
          onConfigChange={onConfigChange}
          onSnapshot={onSnapshot}
          onPais={onPaisDeLaVista}
        />
      ) : (
      <>
      <div className={`flex flex-wrap items-center gap-2 border-b border-borde bg-tarjeta px-4 py-2 text-tinta ${fondoOscuro ? "tema-oscuro-local" : ""}`}>
        {tiendas.length > 0 ? (
          <select
            value={tiendaId}
            onChange={(e) => setTiendaId(e.target.value)}
            className="rounded-md border border-borde bg-relleno px-2 py-1 text-xs font-semibold text-tinta"
            title="Tienda"
          >
            {tiendas.map((t, i) => (
              <option key={t.id} value={t.id}>
                🏪 {t.nombre?.trim() || `Tienda ${i + 1}`}
              </option>
            ))}
          </select>
        ) : (
          <span className="text-xs text-tinta-suave">Sin tiendas</span>
        )}
        {/* LA SEMIMODALIDAD SE CAMBIA AQUÍ (16/10/2026): «dice COMO OB pero no puedo cambiarla».
            Es la misma de la tienda en menú ajustes → Tiendas, con su misma regla: pasar a
            COMO DOU u OB enciende el reenganche en la misma escritura, y volver no lo apaga. */}
        {tienda && (
          <select
            value={semi}
            title="Cómo presenta esta tienda. Es la misma de menú ajustes → Tiendas"
            onChange={(e) => {
              const valor = e.target.value as NonNullable<TiendaEditor["semimodalidad"]>;
              const c = vivo.current.cfg;
              const siguientes = (c.tiendas ?? []).map((t) => (t.id === tiendaId ? { ...t, semimodalidad: valor } : t));
              aplicar({
                ...c,
                tiendas: siguientes,
                ...(valor !== "" ? { globals: { ...c.globals, modo_reenganche: true } } : {}),
              });
            }}
            className="rounded-md border border-violet-300 bg-violet-100 px-2 py-1 text-xs font-semibold text-violet-800"
          >
            <option value="">COMOHOY</option>
            <option value="dos_juntas">COMO DOU</option>
            <option value="segunda_oculta">COMO OB</option>
          </select>
        )}
        <div className="flex overflow-hidden rounded-md border border-borde">
          {CANALES.map((c) => (
            <button
              key={c.clave}
              type="button"
              onClick={() => setCanal(c.clave)}
              className={`px-3 py-1 text-xs font-semibold ${canal === c.clave ? "bg-acento text-white" : "bg-relleno text-tinta-suave hover:bg-tarjeta"}`}
            >
              {c.nombre}
            </button>
          ))}
        </div>
        {canalUsaLoSuyo && (
          <select
            value={probando}
            onChange={(e) => setProbando(e.target.value)}
            className={`rounded-md border px-2 py-1 text-xs font-semibold ${probando ? "border-emerald-500 bg-emerald-50 text-emerald-800" : "border-borde bg-relleno text-tinta-suave"}`}
            title="Ver el camino que recorre un cliente de ese país"
          >
            <option value="">▶ Probar recorrido</option>
            {(completo?.estaciones[0]?.filas ?? [])
              // Sin «Otros países» cuando hay países: ya no tiene fila (17/10/2026).
              .filter((f, _i, todas) => f.clave || !todas.some((x) => x.clave))
              .map((f) => (
              <option key={f.clave || "otros"} value={f.clave || "__otros"}>
                ▶ {f.clave ? f.etiqueta.replace(/^Si país = /, "") : "Otros países"}
              </option>
            ))}
          </select>
        )}
        {canalUsaLoSuyo && (
          <input
            type="search"
            value={buscar}
            onChange={(e) => setBuscar(e.target.value)}
            placeholder="🔍 Buscar"
            className="w-40 rounded-md border border-borde bg-relleno px-2 py-1 text-xs text-tinta"
          />
        )}
        {canalUsaLoSuyo && (
          <select
            value=""
            onChange={(e) => {
              const p = e.target.value;
              if (p)
                aplicar(
                  conDisposicion(vivo.current.cfg, (d) => ({
                    ...d,
                    paises: [...new Set([...(d.paises ?? []), p])],
                    // Si él lo había quitado, vuelve.
                    quitados: (d.quitados ?? []).filter((x) => x !== p),
                    sinFondo: (d.sinFondo ?? []).filter((x) => x !== `caja:carril:${p}`),
                  }))
                );
            }}
            className="rounded-md border border-borde bg-relleno px-2 py-1 text-xs font-semibold text-tinta-suave"
            title="Agregar el camino de un país"
          >
            <option value="">+ País</option>
            {COUNTRY_OPTIONS.filter((o) => !(completo?.estaciones[0]?.filas ?? []).some((f) => f.clave === o.code)).map((o) => (
              <option key={o.code} value={o.code}>{o.label}</option>
            ))}
          </select>
        )}
        <span className="ml-auto" />
        {/* CLARO · MIXTO · OSCURO (22/10/2026). El elegido, resaltado. */}
        <div className="flex overflow-hidden rounded-md border border-borde text-xs font-semibold">
          {(
            [
              ["claro", "☀️ Claro", "Todo claro"],
              ["mixto", "🌗 Mixto", "Fondo oscuro; ventanas y Mis tiendas claras"],
              ["oscuro", "🌙 Oscuro", "Todo oscuro"],
            ] as const
          ).map(([valor, texto, ayuda]) => (
            <button
              key={valor}
              type="button"
              onClick={() => cambiarTemaDeLaPizarra(valor)}
              title={ayuda}
              className={`px-2.5 py-1 ${
                temaDeLaPizarra === valor ? "bg-acento text-white" : "bg-relleno text-tinta-suave hover:bg-tarjeta"
              }`}
            >
              {texto}
            </button>
          ))}
        </div>
      </div>
      {aviso && (
        <div className="border-b border-amber-300 bg-amber-50 px-4 py-1.5 text-xs font-semibold text-amber-950">{aviso}</div>
      )}
      <div className="relative min-h-0 flex-1">
        {/* ← Y «+», DENTRO DE LA PIZARRA, arriba a la izquierda, como en Sendy (16/10/2026). */}
        <div className="absolute left-3 top-3 z-20 flex items-center gap-2">
          <button
            type="button"
            onClick={() => irA("tiendas")}
            title="Volver a Mis tiendas"
            className="flex h-9 w-9 items-center justify-center rounded-full border border-borde bg-tarjeta text-lg font-bold text-tinta shadow-md hover:bg-relleno"
          >
            ←
          </button>
            <div ref={refDelMas} className="relative">
              <button
                type="button"
                disabled={!canalUsaLoSuyo}
                onClick={() => setMenuMas((v) => !v)}
                title="Agregar"
                className="flex h-9 w-9 items-center justify-center rounded-full bg-violet-600 text-xl font-bold text-white shadow-md hover:bg-violet-700 disabled:opacity-40"
              >
                {menuMas ? "×" : "+"}
              </button>
              {menuMas && (
                <div className="absolute left-0 top-11 z-50 w-72 overflow-hidden rounded-xl border border-borde bg-tarjeta py-1 text-sm text-tinta shadow-2xl">
                  <div className="px-3 py-1.5 text-[11px] font-bold uppercase tracking-wide text-tinta-suave">Agregar a la pizarra</div>
                  <button type="button" onClick={() => agregar({ tipo: "intro" })} className="flex w-full items-center gap-2 px-3 py-1.5 text-left hover:bg-relleno">
                    <span className="h-2.5 w-2.5 rounded-sm bg-sky-600" /> Intro
                  </button>
                  {seguimientosDelCanal.map((f, i) => (
                    <button key={i} type="button" onClick={() => agregar({ tipo: "seguimiento", indice: i })} className="flex w-full items-center gap-2 px-3 py-1.5 text-left hover:bg-relleno">
                      <span className="h-2.5 w-2.5 rounded-sm bg-orange-500" /> {f.name || `Seguimiento ${i + 1}`}
                    </button>
                  ))}
                  <button type="button" onClick={() => agregar({ tipo: "seguimiento-nuevo" })} className="flex w-full items-center gap-2 px-3 py-1.5 text-left hover:bg-relleno">
                    <span className="h-2.5 w-2.5 rounded-sm bg-orange-500" /> Seguimiento nuevo ({seguimientosDelCanal.length + 1})
                  </button>
                  {semi === "segunda_oculta" && (
                    <button type="button" onClick={() => agregar({ tipo: "ob" })} className="flex w-full items-center gap-2 px-3 py-1.5 text-left hover:bg-relleno">
                      <span className="h-2.5 w-2.5 rounded-sm bg-violet-600" /> Oferta de 2 opciones
                    </button>
                  )}
                  <button type="button" onClick={() => agregar({ tipo: "upsell" })} className="flex w-full items-center gap-2 px-3 py-1.5 text-left hover:bg-relleno">
                    <span className="h-2.5 w-2.5 rounded-sm bg-amber-500" /> Upsell
                  </button>
                  {/* UPSELL EN FILA (17/10/2026): antes era un recuadro en medio de la pizarra y le
                      estorbaba. Se elige el producto y se pone al final de la fila de esta tienda;
                      aparece en su sitio, detrás del último upsell. */}
                  {(completo?.postventa?.paraLaFila ?? []).length > 0 && (
                    <div className="px-3 py-1.5">
                      <div className="mb-1 flex items-center gap-2">
                        <span className="h-2.5 w-2.5 rounded-sm bg-amber-500" /> Upsell en fila
                      </div>
                      <select
                        value=""
                        onChange={(e) => {
                          const id = e.target.value;
                          if (!id) return;
                          setMenuMas(false);
                          accionesVivas.fila?.agregar(id);
                        }}
                        className="w-full rounded border border-borde bg-tarjeta px-1 py-1 text-xs"
                        title="Va detrás del último upsell: se ofrece si compró el anterior. Al primer «No», al regalo."
                      >
                        <option value="">Elige el producto…</option>
                        {(completo?.postventa?.paraLaFila ?? []).map((p) => (
                          <option key={p.id} value={p.id}>
                            {p.nombre}
                          </option>
                        ))}
                      </select>
                    </div>
                  )}
                  <button
                    type="button"
                    onClick={() => {
                      setMenuMas(false);
                      setEditando({ piezaId: "regalo" });
                    }}
                    className="flex w-full items-center gap-2 px-3 py-1.5 text-left hover:bg-relleno"
                    title="El regalo es uno solo: se abre el que hay"
                  >
                    <span className="h-2.5 w-2.5 rounded-sm bg-pink-500" /> Ofrecimiento de regalo
                  </button>
                  <div className="my-1 border-t border-borde" />
                  {/* EL ÁREA DE UN PAÍS (17/10/2026): «quiero poder crear esa área atenuada y darle la
                      propiedad que sea de algún país». Es su fila, con su fondo: lo que se ponga
                      ahí es de ese país. */}
                  <div className="px-3 pb-1 pt-1.5 text-[11px] font-bold uppercase tracking-wide text-tinta-suave">🌎 Área de un país</div>
                  <div className="max-h-40 overflow-y-auto">
                    {COUNTRY_OPTIONS.filter((o) => !(completo?.estaciones[0]?.filas ?? []).some((f) => f.clave === o.code)).map((o) => (
                      <button
                        key={o.code}
                        type="button"
                        onClick={() => {
                          setMenuMas(false);
                          aplicar(
                            conDisposicion(vivo.current.cfg, (d) => ({
                              ...d,
                              paises: [...new Set([...(d.paises ?? []), o.code])],
                              quitados: (d.quitados ?? []).filter((x) => x !== o.code),
                              // Si antes borró su fondo, al pedir su área vuelve.
                              sinFondo: (d.sinFondo ?? []).filter((x) => x !== `caja:carril:${o.code}`),
                            }))
                          );
                        }}
                        className="flex w-full items-center gap-2 px-5 py-1 text-left text-xs hover:bg-relleno"
                      >
                        {banderaDe(o.code)} {o.label}
                      </button>
                    ))}
                  </div>
                  <div className="my-1 border-t border-borde" />
                  <button
                    type="button"
                    onClick={() => {
                      setMenuMas(false);
                      setPedidoDeCaja((n) => n + 1);
                    }}
                    className="flex w-full items-center gap-2 px-3 py-1.5 text-left hover:bg-relleno"
                    title="Solo un fondo para ordenar, sin país: se estira por las esquinas y se borra con Delete"
                  >
                    <span className="h-2.5 w-3.5 rounded-sm border-2 border-dashed border-slate-400" /> Caja libre (solo fondo, sin país)
                  </button>
                </div>
              )}
            </div>
            {/* ☰ HERRAMIENTAS (19/10/2026): la tienda, los productos, el modo prueba y su JSON, en
                ventanas encima de la pizarra. Ver `menuHerramientas`. */}
            <div ref={refDeHerramientas} className="relative">
              <button
                type="button"
                onClick={() => setMenuHerramientas((v) => !v)}
                title="Tienda, productos, modo prueba y exportar"
                className="flex h-9 w-9 items-center justify-center rounded-full bg-slate-700 text-lg font-bold text-white shadow-md hover:bg-slate-800"
              >
                {menuHerramientas ? "×" : "☰"}
              </button>
              {menuHerramientas && (
                <div className="absolute left-0 top-11 z-50 w-72 overflow-hidden rounded-xl border border-borde bg-tarjeta py-1 text-sm text-tinta shadow-2xl">
                  <div className="px-3 py-1.5 text-[11px] font-bold uppercase tracking-wide text-tinta-suave">Sin salir de la pizarra</div>
                  {(
                    [
                      ["tienda", "🏪", "Datos de esta tienda", "Número, página, pixel, quién cobra, semimodalidad y sus productos"],
                      ["productos", "📦", "Productos y precios", "El mismo buscador del menú Productos: precio por país, entrega y contenido"],
                      ["anuncios", "📣", "Anuncios", "Tus campañas y anuncios, y a qué ficha lleva cada uno"],
                      ["prueba", "🧪", "Modo prueba", "Probar el bot sin enviar nada a Meta"],
                      ["exportar", "⇅", "Exportar / importar tienda", "La tienda entera en un archivo JSON, y traerla de vuelta"],
                    ] as const
                  ).map(([clave, icono, texto, ayuda]) => (
                    <button
                      key={clave}
                      type="button"
                      title={ayuda}
                      disabled={clave === "tienda" && !tiendaId}
                      onClick={() => {
                        setMenuHerramientas(false);
                        setVentanaDeHerramienta(clave);
                      }}
                      className="flex w-full items-center gap-2 px-3 py-1.5 text-left hover:bg-relleno disabled:opacity-40"
                    >
                      <span className="w-5 text-center">{icono}</span> {texto}
                    </button>
                  ))}
                </div>
              )}
            </div>
        </div>
        {modelo ? (
          <LienzoDePizarra
            modelo={modelo}
            acciones={accionesVivas}
            disposicion={disposicion}
            claveDeLaVista={claveDeLaVista(tiendaId, canal, semi)}
            probando={probando === "" ? null : probando === "__otros" ? "" : probando}
            buscar={buscar}
            temaDeLaPizarra={fondoOscuro ? "oscuro" : "claro"}
            pedidoDeCaja={pedidoDeCaja}
            registrarPosiciones={(f) => {
              posDePieza.current = f;
            }}
          />
        ) : (
          <div className="flex h-full items-center justify-center p-6 text-center text-sm text-tinta-suave">
            Este canal usa el contenido de la modalidad, no el suyo propio.
            <br />
            Míralo en la vista de menús o en «Ver recorrido».
          </div>
        )}
      </div>
      </>
      )}
      {/* Las ventanas de aquí abajo ven los productos y precios de ESTA tienda. Ver `contextoDeLaTienda`. */}
      <EditorPreviewContext.Provider value={contextoDeLaTienda}>
      {/* EL CAJÓN ENTERO, con todas sus burbujas, como en los menús. */}
      {editando && (() => {
        const pieza = piezaEditable(cfg, canal, editando.piezaId, tiendaId);
        if (!pieza) return null;
        return (
          <VentanaDelCajon
            titulo={pieza.titulo}
            nombre={nombreDePieza(cfg, canal, editando.piezaId)}
            steps={pieza.steps}
            idPrefix={`pizarra_${editando.piezaId.replace(/[^a-z0-9]/gi, "_")}`}
            cfgVista={configComoLaVeLaTienda(cfg, tienda, semi)}
            burbuja={editando.burbuja}
            pais={editando.pais}
            seguimiento={editando.piezaId.startsWith("seg:") ? Number(editando.piezaId.split(":")[1]) : undefined}
            // SUS ANUNCIOS, solo en intros y seguimientos (las que el bot dirige por anuncio).
            anuncios={(() => {
              if (!/^(intro|seg):/.test(editando.piezaId)) return undefined;
              const u = ubicarPieza(cfg, canal, editando.piezaId);
              if (!u) return undefined;
              const o = u.obj as { adKeys?: string[]; adRoutingEnabled?: boolean; ad_keys?: string[]; ad_routing_enabled?: boolean };
              const esIntro = editando.piezaId.startsWith("intro:");
              return {
                claves: (esIntro ? o.adKeys : o.ad_keys) ?? [],
                dirigir: (esIntro ? o.adRoutingEnabled : o.ad_routing_enabled) !== false,
                registro: cfg.ad_registry ?? [],
                alCambiarRegistro: (ad_registry: AdRegistryEntry[]) => aplicar({ ...vivo.current.cfg, ad_registry }),
                deLaTienda: anunciosDeLaTienda,
              };
            })()}
            onGuardar={(steps, nombre, anunciosNuevos) => {
              // Burbujas, nombre y anuncios en UN paso: un solo Ctrl+Z lo deshace todo. Y lo que se
              // edita aquí es de esta tienda: si era compartida, se edita su copia propia (17/10/2026).
              const esDeLaPizarra = /^(intro|ob|up|seg):/.test(editando.piezaId);
              const propia = esDeLaPizarra ? deEstaTienda(cfg, editando.piezaId) : { cfg, id: editando.piezaId };
              const suya = propia.id === editando.piezaId && propia.cfg === cfg ? pieza : piezaEditable(propia.cfg, canal, propia.id, tiendaId);
              if (!suya) return;
              const conSusPasos = suya.conPasos(steps);
              const conNombre = nombre !== undefined ? renombrarPieza(conSusPasos, canal, propia.id, nombre) : conSusPasos;
              let conTodo = conNombre;
              if (anunciosNuevos) {
                const u = ubicarPieza(conNombre, canal, propia.id);
                if (u) {
                  const esIntro = propia.id.startsWith("intro:");
                  conTodo = u.poner(
                    (esIntro
                      ? { ...u.obj, adKeys: anunciosNuevos.claves, adRoutingEnabled: anunciosNuevos.dirigir }
                      : { ...u.obj, ad_keys: anunciosNuevos.claves, ad_routing_enabled: anunciosNuevos.dirigir }) as unknown as PiezaUbicada["obj"]
                  );
                }
              }
              aplicar(propia.id !== editando.piezaId ? conIdsNuevos(conTodo, new Map([[editando.piezaId, propia.id]])) : conTodo);
              setEditando(null);
            }}
            onCerrar={() => setEditando(null)}
          />
        );
      })()}
      {/* (Los anuncios de una ficha ya no tienen ventana propia: van DENTRO de la ficha, arriba,
          con su ON/OFF, como en Canales — ver `VentanaDelCajon`.) */}
      {/* EL MENSAJE DE UNA RAMA: lo que se envía al tocar ese botón o al decir eso. */}
      {editandoRama && (() => {
        const rama = ramaEditable(cfg, canal, editandoRama.piezaId, editandoRama.ramaId, tiendaId);
        if (!rama) return null;
        return (
          <BubbleButtonStepsModal
            titulo={rama.etiqueta}
            steps={rama.steps}
            onGuardar={(steps) => {
              aplicar(rama.conPasos(steps));
              setEditandoRama(null);
            }}
            onCerrar={() => setEditandoRama(null)}
            onSnapshot={() => {}}
            onEdit={() => {}}
            idPrefix={`pizarra_rama_${editandoRama.ramaId.replace(/[^a-z0-9]/gi, "_")}`}
          />
        );
      })()}
      {/* EL COBRO: doble clic en 💳 Pago (16/10/2026: «al dar doble click aparezca… pagos»). Es
          el MISMO almacén de menú usuarios → «Otros usuarios que cobran», y arriba quién cobra
          en esta tienda, que es el mismo selector de menú ajustes → Tiendas. */}
      {editandoTexto && cfg.gift && (
        <VentanaDeTexto
          titulo={editandoTexto === "regalo-premio" ? "🎁 Entrega del regalo" : "👋 Despedida (si no quiere el regalo)"}
          // EL DE ESTA TIENDA si lo tiene; si no, el de todas. Al guardar pasa a ser suyo (17/10/2026).
          valor={
            (editandoTexto === "regalo-premio"
              ? tienda?.regalo?.reward_message?.trim() ? tienda.regalo.reward_message : cfg.gift.reward_message
              : tienda?.regalo?.decline_message?.trim() ? tienda.regalo.decline_message : cfg.gift.decline_message) ?? ""
          }
          cfgVista={configComoLaVeLaTienda(cfg, tienda, semi)}
          onGuardar={(texto) => {
            const c = vivo.current.cfg;
            const cambio = editandoTexto === "regalo-premio" ? { reward_message: texto } : { decline_message: texto };
            if (tienda) aplicar(conRegaloDeLaTienda(c, tienda.id, cambio));
            else if (c.gift) aplicar({ ...c, gift: { ...c.gift, ...cambio } });
            setEditandoTexto(null);
          }}
          onCerrar={() => setEditandoTexto(null)}
        />
      )}
      </EditorPreviewContext.Provider>
      {verCobro && tienda && (
        <VentanaDelCobro
          cfg={cfg}
          tienda={tienda}
          pais={typeof verCobro === "string" ? verCobro : undefined}
          onCobrador={(id) => {
            const c = vivo.current.cfg;
            aplicar({ ...c, tiendas: (c.tiendas ?? []).map((t) => (t.id === tiendaId ? { ...t, cobrador: id } : t)) });
          }}
          onCobradores={(cobradores) => onConfigChange({ ...vivo.current.cfg, cobradores })}
          onSnapshot={onSnapshot}
          onCerrar={() => setVerCobro(false)}
        />
      )}
      {/* EL GESTOR DE UN CAJÓN (19/10/2026). Mientras se edita un paso, se esconde; al cerrar el
          editor, vuelve donde estaba. */}
      {gestorAbierto && !editando && !editandoTexto && !verCobro && completo?.postventa && (
        gestorAbierto.cual === "cobro" ? (
          <GestorDelCobro
            pv={completo.postventa}
            pais={gestorAbierto.pais}
            editor={(piezaId) => editorIncrustado(piezaId, gestorAbierto.pais || undefined)}
            cobro={() => cobroIncrustado(gestorAbierto.pais)}
            onCerrar={() => setGestorAbierto(null)}
          />
        ) : gestorAbierto.cual === "seguimientos" ? (
          <GestorDeSeguimientos
            modelo={completo}
            pais={gestorAbierto.pais}
            camino={gestorAbierto.camino ?? ""}
            visibles={vistaDeLaPizarra(cfg, tiendaId, canal, semi)?.visibles ?? []}
            soloEstas={gestorAbierto.soloEstas}
            acciones={accionesVivas}
            editor={(piezaId) => editorIncrustado(piezaId, gestorAbierto.pais || undefined)}
            onCerrar={() => setGestorAbierto(null)}
          />
        ) : gestorAbierto.cual === "regalo" ? (
          <GestorDelRegalo
            pv={completo.postventa}
            acciones={accionesVivas}
            editor={(piezaId) => editorIncrustado(piezaId, gestorAbierto.pais || undefined)}
            texto={textoDelRegaloIncrustado}
            onCerrar={() => setGestorAbierto(null)}
            selector={tienda ? <SelectorDeRegalo cfg={cfg} tiendaId={tienda.id} aplicar={aplicar} /> : undefined}
          />
        ) : (
          <GestorDeUpsells
            pv={completo.postventa}
            piezasDelUpsell1={(() => {
              const fila = completo.estaciones.find((e) => e.tipo === "upsell")?.filas.find((f) => f.clave === gestorAbierto.pais);
              const deLaFila = (fila?.estado === "prestada" ? [] : fila?.piezas ?? []).flatMap((pid) => completo.piezas.filter((p) => p.id === pid));
              // Y LAS RECIÉN CREADAS AQUÍ, aún vacías (la pizarra todavía no las pone en su fila):
              // solo las que esta pizarra enseña, como en el gestor de seguimientos.
              const visibles = vistaDeLaPizarra(cfg, tiendaId, canal, semi)?.visibles ?? [];
              const vacias = completo.piezas.filter(
                (p) => p.id.startsWith("up:") && p.paises.includes(gestorAbierto.pais) && visibles.includes(p.id) && !deLaFila.some((q) => q.id === p.id)
              );
              return [...deLaFila, ...vacias];
            })()}
            pais={gestorAbierto.pais}
            acciones={accionesVivas}
            editor={(piezaId) => editorIncrustado(piezaId, gestorAbierto.pais || undefined)}
            cobro={() => cobroIncrustado(gestorAbierto.pais)}
            onCerrar={() => setGestorAbierto(null)}
          />
        )
      )}
      {/* LAS VENTANAS DEL MENÚ ☰ (19/10/2026), encima de la pizarra. */}
      {ventanaDeHerramienta === "tienda" && tienda && (
        <VentanaDeDatosDeTienda
          cfg={cfg}
          tienda={tienda}
          onConfigChange={onConfigChange}
          onSnapshot={onSnapshot}
          onCerrar={() => setVentanaDeHerramienta(null)}
          alEditarProductos={() => setVentanaDeHerramienta("productos")}
        />
      )}
      {ventanaDeHerramienta === "productos" && (
        <VentanaFlotante titulo="📦 Productos y precios" detalle="Busca un producto y ábrelo: precio por país, entrega y contenido. Ctrl+Z deshace." onCerrar={() => setVentanaDeHerramienta(null)}>
          <BibliotecaDeProductos
            cfg={cfg}
            productos={cfg.biblioteca_de_productos ?? []}
            onProductos={(lista) => {
              herramientas?.editSnapshot("biblioteca");
              onConfigChange({ ...vivo.current.cfg, biblioteca_de_productos: lista });
            }}
            onCfg={onConfigChange}
            pais={herramientas?.paisDePago ?? ("PE" as CountryCode)}
            modalidad={activeModality(cfg)}
            alineacion={
              (configComoLaVeLaTienda(cfg, tienda, semi).alineacion_por_modalidad?.[activeModality(cfg)] ?? {}) as AlineacionEditor
            }
            precioBase={cfg.globals?.course_price_soles ?? 0}
            comboPrice={previewComboPriceFromConfig(cfg)}
            basicoPrice={previewBasicoPriceFromConfig(cfg)}
            previewContext={previewContextFromConfig(cfg)}
            onSnapshot={onSnapshot}
            onEdit={(clave) => (herramientas ? herramientas.editSnapshot(clave) : onSnapshot())}
            onMarcarPunto={() => herramientas?.marcarPunto()}
            onCancelarVentana={() => herramientas?.volverAlPunto()}
          />
        </VentanaFlotante>
      )}
      {ventanaDeHerramienta === "anuncios" && completo && (
        <VentanaFlotante
          titulo="📣 Anuncios"
          detalle="Por BM y campaña: a qué ficha de esta tienda lleva cada anuncio. Abajo, para importar y administrar."
          onCerrar={() => setVentanaDeHerramienta(null)}
          ancho="max-w-6xl"
        >
          <GuiaDeAnuncios
            registro={cfg.ad_registry ?? []}
            destinos={(() => {
              // Solo las dibujadas en ESTA pizarra (tienda, canal y semimodalidad): las de sus filas.
              const enLaPizarra = new Set(completo.estaciones.flatMap((e) => e.filas.flatMap((f) => (f.estado === "prestada" ? [] : f.piezas))));
              return completo.piezas.filter((p) => enLaPizarra.has(p.id) && p.paises.length > 0);
            })().flatMap((p) => {
              if (!/^(intro|seg):/.test(p.id)) return [];
              const u = ubicarPieza(cfg, canal, p.id);
              if (!u) return [];
              const o = u.obj as { adKeys?: string[]; ad_keys?: string[]; adRoutingEnabled?: boolean; ad_routing_enabled?: boolean };
              const esIntro = p.id.startsWith("intro:");
              const claves = (esIntro ? o.adKeys : o.ad_keys) ?? [];
              const dirige = (esIntro ? o.adRoutingEnabled : o.ad_routing_enabled) !== false;
              return claves.length > 0 ? [{ piezaId: p.id, titulo: p.titulo || "(sin nombre)", tipo: esIntro ? "Intro" : "Seguimiento", paises: p.paises, apagada: p.estado === "apagada", claves, dirige }] : [];
            })}
            onAbrir={(piezaId, pais) => {
              setVentanaDeHerramienta(null);
              setEditando({ piezaId, pais });
            }}
          />
          <div className="mt-4">
            <AdRegistryManager
              entries={cfg.ad_registry ?? []}
              palette={cfg.ad_color_palette ?? []}
              onPaletteChange={(ad_color_palette) => onConfigChange({ ...vivo.current.cfg, ad_color_palette })}
              onChange={(ad_registry) => {
                // Lo MISMO que en menú ajustes: quitar un anuncio quita su bloque del regalo, con aviso.
                const c = vivo.current.cfg;
                const activeIds = new Set(ad_registry.flatMap((ad) => ad.ids));
                const removed = c.gift.variants.filter((variant) => variant.registry_ad_id && !activeIds.has(variant.registry_ad_id));
                if (
                  removed.some((variant) => variant.text.trim() || variant.ad_link?.trim() || variant.ads_reader_id) &&
                  !confirm("Al quitar este ID se borrara tambien su bloque configurado en Regalo. ¿Continuar?")
                )
                  return;
                herramientas?.editSnapshot("anuncios");
                onConfigChange({ ...c, ad_registry, gift: syncGiftVariantsWithRegistry(c.gift, ad_registry) });
              }}
            />
          </div>
        </VentanaFlotante>
      )}
      {ventanaDeHerramienta === "prueba" && (
        <VentanaFlotante
          titulo="🧪 Modo prueba"
          detalle="Prueba el bot sin enviar nada a Meta. Lo que no hayas guardado no entra en la prueba."
          onCerrar={() => setVentanaDeHerramienta(null)}
          ancho="max-w-6xl"
        >
          <iframe src="/simulador" title="Modo prueba" className="h-[75vh] w-full rounded-md border border-borde bg-white" />
        </VentanaFlotante>
      )}
      {ventanaDeHerramienta === "exportar" && (
        <VentanaFlotante titulo="⇅ Exportar / importar tienda" detalle="Un archivo JSON con la tienda entera." onCerrar={() => setVentanaDeHerramienta(null)} ancho="max-w-xl">
          <div className="space-y-4 text-sm text-tinta">
            <div>
              <button
                type="button"
                disabled={!tienda}
                onClick={() => {
                  const datos = tienda ? exportarTienda(vivo.current.cfg, tienda.id) : null;
                  if (!datos) return;
                  const blob = new Blob([JSON.stringify(datos, null, 2)], { type: "application/json" });
                  const a = document.createElement("a");
                  a.href = URL.createObjectURL(blob);
                  a.download = `tienda-${(tienda?.nombre || tienda?.id || "tienda").replace(/[^a-z0-9]+/gi, "-").toLowerCase()}.json`;
                  a.click();
                  setTimeout(() => URL.revokeObjectURL(a.href), 2000);
                }}
                className="rounded-md bg-emerald-600 px-3 py-2 text-sm font-semibold text-white hover:bg-emerald-700 disabled:opacity-40"
              >
                ⬇ Exportar «{tienda?.nombre?.trim() || "esta tienda"}»
              </button>
              <p className="mt-1 text-xs text-tinta-suave">
                Lleva sus datos, sus productos (con precios, entregas y contenido), su fila de upsells, sus fichas propias y su
                pizarra. Las fichas «🌐 de todas las tiendas» son del bot entero y no viajan.
              </p>
            </div>
            <div className="border-t border-borde pt-4">
              <label className="inline-block cursor-pointer rounded-md border border-borde bg-tarjeta px-3 py-2 text-sm font-semibold hover:bg-relleno">
                ⬆ Importar una tienda (JSON)
                <input
                  type="file"
                  accept="application/json,.json"
                  data-importar-tienda
                  className="hidden"
                  onChange={async (e) => {
                    const archivo = e.target.files?.[0];
                    e.target.value = "";
                    if (!archivo) return;
                    let datos: unknown;
                    try {
                      datos = JSON.parse(await archivo.text());
                    } catch {
                      setAviso("Ese archivo no es un JSON válido.");
                      return;
                    }
                    const r = importarTienda(vivo.current.cfg, datos);
                    if ("error" in r) {
                      setAviso(r.error);
                      return;
                    }
                    onSnapshot();
                    onConfigChange(r.cfg);
                    setVentanaDeHerramienta(null);
                    setAviso(
                      `Tienda importada como nueva, sin número: búscala en Mis tiendas. Guarda para que quede.${
                        r.avisos.length > 0 ? ` ${r.avisos.join(" ")}` : ""
                      }`
                    );
                  }}
                />
              </label>
              <p className="mt-1 text-xs text-tinta-suave">
                Entra como una tienda NUEVA, sin número ni página: nunca pisa una que ya exista. Los productos que ya estén
                aquí no se tocan; los que falten se agregan.
              </p>
            </div>
            <div className="border-t border-borde pt-4">
              <label className="inline-block cursor-pointer rounded-md border border-sky-300 bg-sky-50 px-3 py-2 text-sm font-semibold text-sky-900 hover:bg-sky-100">
                ⬆ Importar aquí, como bloques sueltos (JSON)
                <input
                  type="file"
                  accept="application/json,.json"
                  className="hidden"
                  onChange={async (e) => {
                    const archivo = e.target.files?.[0];
                    e.target.value = "";
                    if (!archivo) return;
                    let datos: unknown;
                    try {
                      datos = JSON.parse(await archivo.text());
                    } catch {
                      setAviso("Ese archivo no es un JSON válido.");
                      return;
                    }
                    setAviso(importarComoBloques(datos));
                    setVentanaDeHerramienta(null);
                  }}
                />
              </label>
              <p className="mt-1 text-xs text-tinta-suave">
                Como en n8n: las fichas del archivo aparecen al lado de lo tuyo, sueltas y sin conectar, unidas por bloques. Lo de esta
                tienda no se toca. Trae las de este canal y esta semimodalidad.
              </p>
            </div>
          </div>
        </VentanaFlotante>
      )}
    </div>
  );
}

type PostventaDeLaPizarra = NonNullable<ModeloDePizarra["postventa"]>;

/** En qué semimodalidad se copió lo que hay en el portapapeles de la pizarra (vive mientras la pestaña). */
let semiDelPortapapeles: string | null = null;

/** Los gestores llevan el editor completo dentro: casi toda la pantalla, como Sendy. */
const ANCHO_DEL_GESTOR = "max-w-[1500px]";

/** Pestañas pequeñas dentro del centro de un gestor (Presentación · Pago · Entrega, versiones…). */
function PestanasDelGestor<T extends string>({ opciones, valor, onCambiar }: { opciones: Array<{ id: T; texto: string; apagada?: boolean }>; valor: T; onCambiar: (v: T) => void }) {
  return (
    <div className="flex flex-wrap gap-1 border-b border-borde pb-2">
      {opciones.map((o) => (
        <button
          key={o.id}
          type="button"
          onClick={() => onCambiar(o.id)}
          className={`rounded-md px-2.5 py-1 text-xs font-semibold ${valor === o.id ? "bg-acento text-white" : "bg-relleno text-tinta hover:bg-acento-suave"} ${o.apagada ? "opacity-60" : ""}`}
        >
          {o.texto}
        </button>
      ))}
    </div>
  );
}

/**
 * EL ENCENDIDO DE UNA VERSIÓN EN SU GESTOR (20/10/2026: «en los seguimientos nuevos agregados no
 * se pueden encender ni apagar a pesar que el botón está ahí»). Una ficha sin burbujas con
 * contenido no sale nunca —el bot no manda nada vacío—, así que su interruptor no cambiaba lo
 * que se veía. Vacía, se dice eso; con contenido, el interruptor de siempre.
 */
function InterruptorDeVersion({ p, acciones }: { p: PiezaDePizarra; acciones: AccionesDelLienzo }) {
  if (p.motivo === "Sin burbujas con contenido") {
    return (
      <span className="rounded border border-dashed border-amber-400 bg-amber-50 px-1.5 py-0.5 text-[11px] font-bold text-amber-800" title="Hasta que tenga una burbuja con contenido, el bot no la manda. Escríbela aquí abajo.">
        VACÍA · escribe algo para que salga
      </span>
    );
  }
  return (
    <button
      type="button"
      onClick={() => acciones.alternar(p.id)}
      className={`rounded px-1.5 py-0.5 text-[11px] font-bold text-white ${p.estado === "apagada" ? "bg-slate-400" : "bg-emerald-600"}`}
      title={p.estado === "apagada" ? "Apagada: el bot no la manda. Clic para encenderla." : "Encendida. Clic para apagarla."}
    >
      {p.estado === "apagada" ? "APAGADA" : "ENCENDIDA"}
    </button>
  );
}

/** Las burbujas de un paso, en pequeño, para el centro de un gestor. */
function BurbujasDelGestor({ burbujas, vacio }: { burbujas: ResumenDeBurbuja[]; vacio: string }) {
  if (burbujas.length === 0) return <p className="text-xs italic text-tinta-suave">{vacio}</p>;
  return (
    <div className="flex flex-col gap-1">
      {burbujas.map((b, i) => (
        <div key={i} className="rounded-md border border-borde bg-relleno px-2 py-1 text-xs text-tinta">
          {b.tipo === "texto" ? b.texto || "(sin texto)" : `${b.tipo === "imagen" ? "🖼️" : b.tipo === "video" ? "🎬" : b.tipo === "audio" ? "🎤" : "📄"} ${b.texto || b.tipo}`}
        </div>
      ))}
    </div>
  );
}

/** Un paso de la lista izquierda de un gestor. */
function PasoDelGestor({ n, titulo, detalle, elegido, onElegir, apagado }: { n: string; titulo: string; detalle?: string; elegido: boolean; onElegir: () => void; apagado?: boolean }) {
  return (
    <button
      type="button"
      onClick={onElegir}
      className={`flex w-full items-start gap-2 rounded-lg border px-2 py-2 text-left ${elegido ? "border-acento bg-acento-suave" : "border-borde bg-tarjeta hover:bg-relleno"} ${apagado ? "opacity-60" : ""}`}
    >
      <span className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-xs font-bold ${elegido ? "bg-acento text-white" : "bg-relleno text-tinta-suave"}`}>{n}</span>
      <span className="min-w-0">
        <span className="block truncate text-sm font-semibold text-tinta">{titulo}</span>
        {detalle && <span className="block truncate text-[11px] text-tinta-suave">{detalle}</span>}
      </span>
    </button>
  );
}

/**
 * EL GESTOR DEL REGALO (19/10/2026): «metido tipo el gestor de seguimientos». A la izquierda sus
 * pasos en el orden en que el bot los hace; al centro el elegido, con «Editar» que abre el mismo
 * editor de siempre. Su interruptor arriba (el mismo del menú Regalo: uno para todo el bot).
 */
function GestorDelRegalo({
  pv,
  acciones,
  editor,
  texto,
  onCerrar,
  selector,
}: {
  pv: PostventaDeLaPizarra;
  acciones: AccionesDelLienzo;
  /** El editor de siempre, incrustado (ver `editorIncrustado`). */
  editor: (piezaId: string) => React.ReactNode;
  texto: (cual: "regalo-premio" | "regalo-despedida") => React.ReactNode;
  onCerrar: () => void;
  /** «¿Qué regalo?» de la tienda (25/10/2026), arriba. */
  selector?: React.ReactNode;
}) {
  const rg = pv.regalo;
  const [paso, setPaso] = useState<"ofrece" | "enlace" | "comento" | "premio" | "despedida">("ofrece");
  return (
    <VentanaFlotante titulo="🎁 Regalo" detalle={rg?.deEstaTienda ? "El regalo de esta tienda." : "El de todas las tiendas: si lo editas aquí, esta tienda tendrá el suyo."} onCerrar={onCerrar} ancho={ANCHO_DEL_GESTOR}>
      {selector}
      <div className="mb-3 flex items-center gap-2">
        <button
          type="button"
          onClick={() => acciones.alternarRegalo?.(!rg?.encendido)}
          className={`rounded px-2 py-1 text-xs font-bold text-white ${rg?.encendido ? "bg-emerald-600" : "bg-slate-400"}`}
          title="El mismo interruptor del menú Regalo: uno solo para todo el bot"
        >
          {rg?.encendido ? "ENCENDIDO" : "APAGADO"}
        </button>
        <span className="text-xs text-tinta-suave">Uno solo para todo el bot: vale para todos los países y todas tus tiendas.</span>
        {/* EN MINUTOS (19/10/2026: «el regalo hay que ponerlo en minutos»). Se guarda en segundos,
            el mismo dato de siempre (menú ajustes). */}
        {acciones.cambiarTiempo && (
          <label className="ml-auto flex items-center gap-1 text-xs text-tinta" title="De silencio, desde que recibe su compra (o desde la oferta del upsell). Si el cliente escribe, vuelve a cero.">
            Se ofrece tras
            <input
              key={acciones.tiempos?.regalo ?? 0}
              type="number"
              min={0}
              step={0.5}
              defaultValue={Math.round(((acciones.tiempos?.regalo ?? 0) / 60) * 10) / 10}
              onBlur={(e) => {
                const seg = Math.max(0, Math.round((Number(e.target.value) || 0) * 60));
                if (seg !== (acciones.tiempos?.regalo ?? 0)) acciones.cambiarTiempo?.("regalo", seg);
              }}
              className="w-16 rounded border border-borde bg-tarjeta px-1 py-0.5"
            />
            min de silencio
          </label>
        )}
      </div>
      <div className="grid gap-4 md:grid-cols-[240px_minmax(0,1fr)]">
        <div className="flex flex-col gap-1.5">
          <PasoDelGestor n="1" titulo="Ofrecimiento" detalle="Con sus botones Sí / No" elegido={paso === "ofrece"} onElegir={() => setPaso("ofrece")} />
          <PasoDelGestor n="2" titulo="Enlace para comentar" detalle="Si dice que sí" elegido={paso === "enlace"} onElegir={() => setPaso("enlace")} />
          <PasoDelGestor n="3" titulo="Dice que comentó" detalle="Lo detecta el bot" elegido={paso === "comento"} onElegir={() => setPaso("comento")} />
          <PasoDelGestor n="4" titulo="Premio" detalle="Lo que recibe" elegido={paso === "premio"} onElegir={() => setPaso("premio")} />
          <div className="mt-2 border-t border-borde pt-2">
            <PasoDelGestor n="✕" titulo="Despedida" detalle="Si dice que no" elegido={paso === "despedida"} onElegir={() => setPaso("despedida")} />
          </div>
        </div>
        <div className="min-w-0 rounded-lg border border-borde bg-tarjeta p-3">
          {paso === "ofrece" && (
            <>
              <p className="mb-2 text-xs text-tinta-suave">
                1. Ofrecimiento · botones: ✅ {rg?.acepta ?? "Acepta"} · ❌ {rg?.noQuiere ?? "No quiere"}
              </p>
              {editor("regalo")}
            </>
          )}
          {paso === "enlace" && (
            <>
              <p className="mb-2 text-xs text-tinta-suave">2. Enlace para comentar · sale si dice que sí.</p>
              {editor("regalo-pedido")}
            </>
          )}
          {paso === "comento" && (
            <>
              <h4 className="mb-2 text-sm font-bold text-tinta">3. Dice que comentó</h4>
              <p className="text-sm text-tinta">
                Cuando el cliente dice que ya comentó, el bot le entrega el premio (paso 4). No hay nada que escribir aquí.
              </p>
            </>
          )}
          {paso === "premio" && texto("regalo-premio")}
          {paso === "despedida" && texto("regalo-despedida")}
        </div>
      </div>
    </VentanaFlotante>
  );
}

/**
 * EL GESTOR DE LOS UPSELLS (19/10/2026): a la izquierda la fila en orden —el upsell 1 y los de
 * detrás—, cada uno con su ENCENDIDO / APAGADO, flechas y «+ Agregar upsell»; al centro el
 * elegido con sus tres partes: presentación → pago → entrega. Todo escribe en los MISMOS datos de
 * siempre (los del menú Upsell y la ficha de cada producto).
 */
function GestorDeUpsells({
  pv,
  piezasDelUpsell1,
  pais,
  acciones,
  editor,
  cobro,
  onCerrar,
}: {
  pv: PostventaDeLaPizarra;
  /** Las presentaciones del upsell 1 en este país (sus fichas, con su peso). */
  piezasDelUpsell1: PiezaDePizarra[];
  pais: string;
  acciones: AccionesDelLienzo;
  /** El editor de siempre, incrustado (ver `editorIncrustado`). */
  editor: (piezaId: string) => React.ReactNode;
  /** Quién cobra, incrustado. */
  cobro: () => React.ReactNode;
  onCerrar: () => void;
}) {
  const tieneUno = !!(pv.upsell || pv.upsellApagado);
  const [elegido, setElegido] = useState<number>(tieneUno ? 0 : 1);
  const [parte, setParte] = useState<"presentacion" | "pago" | "entrega">("presentacion");
  // La versión elegida, por ID (crear o quitar otra no cambia lo que se ve).
  const [versionId, setVersionId] = useState<string | null>(null);
  const fila = pv.enFila ?? [];
  const uno = pv.upsell ?? (pv.upsellApagado ? { nombre: pv.upsellApagado.nombre } : null);
  const delElegido = elegido >= 1 ? fila[elegido - 1] : null;
  const elegir = (k: number) => {
    setElegido(k);
    setVersionId(null);
  };
  const interruptor = (encendido: boolean, hacer: () => void) => (
    <button type="button" onClick={hacer} className={`rounded px-1.5 py-0.5 text-[11px] font-bold text-white ${encendido ? "bg-emerald-600" : "bg-slate-400"}`}>
      {encendido ? "ENCENDIDO" : "APAGADO"}
    </button>
  );
  const partes = (
    <PestanasDelGestor
      opciones={[
        { id: "presentacion" as const, texto: "1. Presentación" },
        { id: "pago" as const, texto: "2. Pago" },
        { id: "entrega" as const, texto: "3. Entrega" },
      ]}
      valor={parte}
      onCambiar={setParte}
    />
  );
  const pesoTotal = piezasDelUpsell1.reduce((t, p) => t + (p.peso ?? 1), 0);
  const versionDelUno = piezasDelUpsell1.find((p) => p.id === versionId) ?? piezasDelUpsell1[0];
  return (
    <VentanaFlotante titulo="🛒 Upsells" detalle="En el orden en que el bot los ofrece: al siguiente solo se llega si compró el anterior; al primer «No», al regalo." onCerrar={onCerrar} ancho={ANCHO_DEL_GESTOR}>
      <div className="grid gap-4 md:grid-cols-[280px_minmax(0,1fr)]">
        <div className="flex flex-col gap-1.5">
          {tieneUno ? (
            <PasoDelGestor n="1" titulo={uno?.nombre ?? "Upsell 1"} detalle={pv.upsell ? "Encendido" : "Apagado"} elegido={elegido === 0} onElegir={() => elegir(0)} apagado={!pv.upsell} />
          ) : (
            <div className="rounded-lg border border-dashed border-borde p-2 text-xs text-tinta-suave">
              Sin upsell 1.
              {(pv.productosParaElUpsell ?? []).length > 0 && acciones.elegirUpsell && (
                <select
                  value=""
                  onChange={(e) => e.target.value && acciones.elegirUpsell?.(e.target.value)}
                  className="mt-1 block w-full rounded border border-borde bg-tarjeta px-1 py-1 text-xs"
                >
                  <option value="">Elige su producto…</option>
                  {(pv.productosParaElUpsell ?? []).map((p) => (
                    <option key={p.id} value={p.id}>
                      {p.nombre}
                    </option>
                  ))}
                </select>
              )}
            </div>
          )}
          {fila.map((f, k) => (
            <div key={`${f.productoId}_${k}`} className="flex items-center gap-1">
              <div className="min-w-0 flex-1">
                <PasoDelGestor n={String(k + 2)} titulo={f.nombre} detalle={`${f.encendido === false ? "Apagado" : "Encendido"} · a los ${f.minutos ?? 0} min`} elegido={elegido === k + 1} onElegir={() => elegir(k + 1)} apagado={f.encendido === false} />
              </div>
              {acciones.fila?.mover && (
                <span className="flex flex-col">
                  <button type="button" disabled={k === 0} onClick={() => acciones.fila?.mover?.(k, true)} className="px-1 text-xs disabled:opacity-30" title="Subir">↑</button>
                  <button type="button" disabled={k === fila.length - 1} onClick={() => acciones.fila?.mover?.(k, false)} className="px-1 text-xs disabled:opacity-30" title="Bajar">↓</button>
                </span>
              )}
            </div>
          ))}
          {(pv.paraLaFila ?? []).length > 0 && acciones.fila && (
            <select
              value=""
              onChange={(e) => e.target.value && acciones.fila?.agregar(e.target.value)}
              className="mt-1 rounded-lg border border-dashed border-borde bg-tarjeta px-2 py-2 text-xs font-semibold text-tinta"
            >
              <option value="">+ Agregar upsell…</option>
              {(pv.paraLaFila ?? []).map((p) => (
                <option key={p.id} value={p.id}>
                  {p.nombre}
                </option>
              ))}
            </select>
          )}
        </div>
        <div className="flex min-w-0 flex-col gap-3">
          {elegido === 0 && uno && (
            <>
              <div className="flex flex-wrap items-center gap-2">
                <h4 className="text-sm font-bold text-tinta">1. {uno.nombre}</h4>
                {acciones.alternarUpsell1 && interruptor(!!pv.upsell, () => acciones.alternarUpsell1?.())}
                {pv.upsell && acciones.cambiarTiempo && (
                  <label className="flex items-center gap-1 text-xs text-tinta">
                    · sale a los
                    <input
                      type="number"
                      min={0}
                      defaultValue={acciones.tiempos?.upsell ?? 0}
                      onBlur={(e) => acciones.cambiarTiempo?.("upsell", Math.max(0, Math.floor(Number(e.target.value) || 0)))}
                      className="w-16 rounded border border-borde bg-tarjeta px-1 py-0.5"
                    />
                    min de recibir su compra (uno solo para todas las tiendas)
                  </label>
                )}
                {/* CAMBIAR SU PRODUCTO AQUÍ MISMO (19/10/2026): «solo veo que se pueden crear pero no
                    cambiar de producto, eso debería poder hacerse desde su cajón». */}
                {acciones.elegirUpsell && (pv.productosParaElUpsell ?? []).length > 0 && (
                  <select
                    value=""
                    onChange={(e) => e.target.value && acciones.elegirUpsell?.(e.target.value)}
                    className="ml-auto rounded border border-borde bg-tarjeta px-1.5 py-0.5 text-[11px] font-semibold text-tinta"
                    title="El upsell 1 de esta tienda pasa a ser otro producto"
                  >
                    <option value="">🔄 Cambiar por otro producto…</option>
                    {(pv.productosParaElUpsell ?? []).map((p) => (
                      <option key={p.id} value={p.id}>
                        {p.nombre}
                      </option>
                    ))}
                  </select>
                )}
                {acciones.quitarUpsell && (
                  <button type="button" onClick={() => acciones.quitarUpsell?.()} className="rounded border border-borde px-2 py-0.5 text-[11px] text-tinta-suave hover:bg-relleno" title="Esta tienda deja de tener upsell 1">
                    Quitar
                  </button>
                )}
              </div>
              {partes}
              {parte === "presentacion" &&
                (piezasDelUpsell1.length === 0 ? (
                  <div className="flex flex-wrap items-center gap-2">
                    <p className="text-sm italic text-tinta-suave">Sin presentación en {banderaDe(pais)} {pais}: aquí no se ofrece.</p>
                    {acciones.crearEnGestor && (
                      <button
                        type="button"
                        onClick={() => {
                          const id = acciones.crearEnGestor?.({ tipo: "upsell" }, pais, "");
                          if (id) setVersionId(id);
                        }}
                        className="rounded-md border border-dashed border-borde px-2.5 py-1 text-xs font-semibold text-tinta hover:bg-relleno"
                      >
                        + Crear su presentación aquí
                      </button>
                    )}
                  </div>
                ) : (
                  <>
                    {piezasDelUpsell1.length > 1 && (
                      <PestanasDelGestor
                        opciones={piezasDelUpsell1.map((p, i) => ({
                          id: p.id,
                          texto: `Versión ${String.fromCharCode(65 + i)} · ${Math.round((100 * (p.peso ?? 1)) / pesoTotal)}%`,
                          apagada: p.estado === "apagada",
                        }))}
                        valor={versionDelUno?.id ?? ""}
                        onCambiar={(v) => setVersionId(v)}
                      />
                    )}
                    {/* LAS VERSIONES DEL MISMO UPSELL (20/10/2026): «el mismo upsell, con una segunda
                        versión… como el ejemplo de los cajones». El bot ya las sortea por su peso. */}
                    {versionDelUno && (
                      <div className="flex flex-wrap items-center gap-2">
                        <InterruptorDeVersion p={versionDelUno} acciones={acciones} />
                        {piezasDelUpsell1.length > 1 && acciones.cambiarPeso && (
                          <label className="flex items-center gap-1 text-xs text-tinta">
                            Peso
                            <input
                              key={`${versionDelUno.id}_${versionDelUno.peso ?? 1}`}
                              type="number"
                              min={0}
                              defaultValue={versionDelUno.peso ?? 1}
                              onBlur={(e) => acciones.cambiarPeso?.(versionDelUno.id, Math.max(0, Math.floor(Number(e.target.value) || 0)))}
                              className="w-14 rounded border border-borde bg-tarjeta px-1 py-0.5"
                            />
                          </label>
                        )}
                        {acciones.duplicarEnGestor && (
                          <button
                            type="button"
                            onClick={() => {
                              const id = acciones.duplicarEnGestor?.(versionDelUno.id, pais, "");
                              if (id) setVersionId(id);
                            }}
                            className="rounded border border-borde px-2 py-0.5 text-[11px] font-semibold text-tinta hover:bg-relleno"
                          >
                            ⧉ Duplicar versión
                          </button>
                        )}
                        <button
                          type="button"
                          onClick={() => {
                            if (versionDelUno.paises.length > 1 && acciones.eliminarVarias) acciones.eliminarVarias([], [{ piezaId: versionDelUno.id, pais }]);
                            else acciones.eliminar(versionDelUno.id);
                            setVersionId(null);
                          }}
                          title={versionDelUno.paises.length > 1 ? `También va a otros países: se quita solo de ${pais}.` : "Quitar esta versión. Ctrl+Z la devuelve."}
                          className="rounded border border-red-200 px-2 py-0.5 text-[11px] font-semibold text-red-700 hover:bg-red-50"
                        >
                          🗑 Quitar versión
                        </button>
                      </div>
                    )}
                    {pv.upsell && <p className="text-[11px] text-tinta-suave">Botones: ✅ {pv.upsell.si} · ❌ {pv.upsell.no}</p>}
                    {versionDelUno && editor(versionDelUno.id)}
                    {acciones.crearEnGestor && (
                      <button
                        type="button"
                        onClick={() => {
                          const id = acciones.crearEnGestor?.({ tipo: "upsell" }, pais, "");
                          if (id) setVersionId(id);
                        }}
                        className="self-start rounded-md border border-dashed border-borde px-2.5 py-1 text-xs font-semibold text-tinta hover:bg-relleno"
                      >
                        + Otra versión de este upsell
                      </button>
                    )}
                  </>
                ))}
              {parte === "pago" && (
                <>
                  <p className="text-xs text-tinta">Precio: el de su ficha, por país. Se paga entero.</p>
                  {cobro()}
                </>
              )}
              {parte === "entrega" &&
                (pv.upsell ? editor(pv.upsell.entregaId) : <p className="text-sm italic text-tinta-suave">Enciéndelo para ver su entrega.</p>)}
            </>
          )}
          {delElegido && (
            <>
              <div className="flex flex-wrap items-center gap-2">
                <h4 className="text-sm font-bold text-tinta">
                  {elegido + 1}. {delElegido.nombre}
                </h4>
                {acciones.fila && interruptor(delElegido.encendido !== false, () => acciones.fila?.alternar(delElegido.puesto ?? elegido - 1))}
                {acciones.fila && (
                  <label className="flex items-center gap-1 text-xs text-tinta">
                    · sale a los
                    <input
                      key={`${elegido}_${delElegido.minutos ?? 0}`}
                      type="number"
                      min={0}
                      defaultValue={delElegido.minutos ?? 0}
                      onBlur={(e) => acciones.fila?.minutos(delElegido.puesto ?? elegido - 1, Math.max(0, Math.floor(Number(e.target.value) || 0)))}
                      className="w-16 rounded border border-borde bg-tarjeta px-1 py-0.5"
                    />
                    min de la entrega anterior
                  </label>
                )}
                {acciones.fila?.cambiar && (pv.paraLaFila ?? []).length > 0 && (
                  <select
                    value=""
                    onChange={(e) => e.target.value && acciones.fila?.cambiar?.(delElegido.puesto ?? elegido - 1, e.target.value)}
                    className="ml-auto rounded border border-borde bg-tarjeta px-1.5 py-0.5 text-[11px] font-semibold text-tinta"
                    title="Este puesto de la fila pasa a ser otro producto"
                  >
                    <option value="">🔄 Cambiar por otro producto…</option>
                    {(pv.paraLaFila ?? []).map((p) => (
                      <option key={p.id} value={p.id}>
                        {p.nombre}
                      </option>
                    ))}
                  </select>
                )}
                {acciones.fila && (
                  <button type="button" onClick={() => acciones.fila?.quitar(delElegido.puesto ?? elegido - 1)} className="rounded border border-red-200 px-2 py-0.5 text-[11px] text-red-700 hover:bg-red-50">
                    Quitar de la fila
                  </button>
                )}
              </div>
              {delElegido.aviso && <p className="rounded bg-red-50 px-2 py-1 text-xs font-semibold text-red-700">{delElegido.aviso}</p>}
              {partes}
              {parte === "presentacion" &&
                (delElegido.productoId ? (
                  <>
                    <p className="text-[11px] text-tinta-suave">Vive en la ficha del producto (su «presentación como upsell»).</p>
                    {editor(`presentacion:${delElegido.productoId}`)}
                  </>
                ) : (
                  <p className="text-sm italic text-tinta-suave">Sin producto.</p>
                ))}
              {parte === "pago" && (
                <>
                  <p className="text-xs text-tinta">Precio: el de su ficha, por país. Se paga entero.</p>
                  {cobro()}
                </>
              )}
              {parte === "entrega" && editor(delElegido.entregaId)}
            </>
          )}
          {!uno && !delElegido && <p className="text-sm text-tinta-suave">Elige un producto para el upsell 1, o agrega uno a la fila.</p>}
        </div>
      </div>
    </VentanaFlotante>
  );
}

/**
 * EL GESTOR DEL COBRO Y LA ENTREGA (19/10/2026): cada producto con su pago (quién cobra y su
 * precio, que sale de su ficha por país) y su entrega, en el orden en que pasan.
 */
function GestorDelCobro({
  pv,
  pais,
  editor,
  cobro,
  onCerrar,
}: {
  pv: PostventaDeLaPizarra;
  pais: string;
  /** El editor de siempre, incrustado (ver `editorIncrustado`). */
  editor: (piezaId: string) => React.ReactNode;
  /** Quién cobra, incrustado. */
  cobro: () => React.ReactNode;
  onCerrar: () => void;
}) {
  const entregas = pv.entregas ?? [];
  const [elegido, setElegido] = useState(0);
  const [parte, setParte] = useState<"pago" | "entrega">("pago");
  const e = entregas[elegido];
  return (
    <VentanaFlotante titulo="💳 Cobro y entrega" detalle="Cuando el cliente paga, se valida su comprobante y recibe la entrega de lo que eligió." onCerrar={onCerrar} ancho={ANCHO_DEL_GESTOR}>
      <div className="grid gap-4 md:grid-cols-[240px_minmax(0,1fr)]">
        <div className="flex flex-col gap-1.5">
          {entregas.length === 0 && <p className="text-xs text-tinta-suave">Esta tienda no tiene producto con entrega.</p>}
          {entregas.map((x, i) => (
            <PasoDelGestor key={x.id || i} n={String(i + 1)} titulo={x.nombre} detalle="Pago → entrega" elegido={elegido === i} onElegir={() => setElegido(i)} />
          ))}
        </div>
        {e && (
          <div className="flex min-w-0 flex-col gap-3">
            <h4 className="text-sm font-bold text-tinta">{e.nombre}</h4>
            <PestanasDelGestor
              opciones={[
                { id: "pago" as const, texto: "1. Pago" },
                { id: "entrega" as const, texto: "2. Entrega" },
              ]}
              valor={parte}
              onCambiar={setParte}
            />
            {parte === "pago" && (
              <>
                <p className="text-xs text-tinta">{pv.pagoPorPais?.[pais] ?? pv.pago}</p>
                {cobro()}
              </>
            )}
            {parte === "entrega" && (
              <>
                {pv.entregaDelCanal && (
                  <p className="text-[11px] font-semibold text-amber-700">⚠ La entrega del canal está encendida y pisa ésta, en TODAS las tiendas.</p>
                )}
                {e.id ? editor(e.id) : <p className="text-sm italic text-tinta-suave">Sin entrega todavía: quien pague no recibe nada.</p>}
              </>
            )}
          </div>
        )}
      </div>
    </VentanaFlotante>
  );
}

/**
 * EL GESTOR DE SEGUIMIENTOS (19/10/2026), como el de Sendy: a la izquierda Seguimiento 1, 2, 3…
 * con sus minutos; al centro sus fichas en este país y este camino (las versiones con su peso),
 * cada una con «Editar» y su ENCENDIDO / APAGADO. Los minutos son del seguimiento entero (iguales
 * en todas sus fichas, países y tiendas), como siempre.
 */
function GestorDeSeguimientos({
  modelo,
  pais,
  camino,
  acciones,
  editor,
  onCerrar,
  visibles,
  soloEstas,
}: {
  modelo: ModeloDePizarra;
  pais: string;
  camino: string;
  /** Las sueltas que esta pizarra enseña (las recién creadas y aún vacías están ahí). */
  visibles: string[];
  /** UN CAJÓN PEGADO Y SIN PAÍS (20/10/2026): solo sus fichas. Se editan; crear y quitar versiones
   *  se hace después de conectarlo, cuando ya es de un país. */
  soloEstas?: string[];
  acciones: AccionesDelLienzo;
  /** El editor de siempre, incrustado (ver `editorIncrustado`). */
  editor: (piezaId: string) => React.ReactNode;
  onCerrar: () => void;
}) {
  // LA LISTA SALE DE TODOS LOS SEGUIMIENTOS DEL CANAL y de las fichas de ESTE país y camino —
  // también las recién creadas y aún vacías, que la pizarra todavía no pone en su fila—. Así lo
  // que se crea aquí aparece aquí (19/10/2026).
  const delCamino = (p: PiezaDePizarra) => (p.caminos ?? [p.camino ?? ""]).includes(camino);
  const suelto = !!soloEstas;
  const seguimientos = acciones.seguimientos
    .map((x) => {
      if (soloEstas) {
        return { indice: x.indice, titulo: x.nombre, piezas: modelo.piezas.filter((p) => soloEstas.includes(p.id) && p.id.startsWith(`seg:${x.indice}:`)) };
      }
      const fila = modelo.estaciones.find((e) => e.tipo === "seguimiento" && Number(e.id.split(":")[1] ?? -1) === x.indice)?.filas.find((f) => f.clave === pais);
      const deLaFila = (fila?.estado === "prestada" ? [] : fila?.piezas ?? []).flatMap((pid) => modelo.piezas.filter((p) => p.id === pid));
      // Solo las sueltas que ESTA pizarra enseña: las de otras tiendas o semimodalidades también
      // llevan el país, pero aquí no juegan (medido: salían 6 versiones donde había 1).
      const sueltasDelPais = modelo.piezas.filter((p) => p.id.startsWith(`seg:${x.indice}:`) && p.paises.includes(pais) && visibles.includes(p.id));
      const piezas = [...new Map([...deLaFila, ...sueltasDelPais].filter(delCamino).map((p) => [p.id, p])).values()];
      return { indice: x.indice, titulo: x.nombre, piezas };
    })
    // En uno sin conectar, solo los seguimientos que trae.
    .filter((x) => !suelto || x.piezas.length > 0);
  // Se elige por NÚMERO de seguimiento y por ID de ficha (no por posición): crear o quitar no
  // cambia lo que se está viendo.
  const [elegido, setElegido] = useState(seguimientos[0]?.indice ?? 0);
  const [versionId, setVersionId] = useState<string | null>(null);
  const s = seguimientos.find((x) => x.indice === elegido) ?? seguimientos[0];
  const minutosDe = (i: number) => acciones.seguimientos.find((x) => x.indice === i)?.minutos ?? 0;
  const pesoTotal = (s?.piezas ?? []).reduce((t, p) => t + (p.peso ?? 1), 0);
  const versionActual = s?.piezas.find((p) => p.id === versionId) ?? s?.piezas[0];
  const crear = (que: LoQueSeCrea) => {
    const id = acciones.crearEnGestor?.(que, pais, camino);
    if (!id) return;
    setElegido(Number(id.split(":")[1]));
    setVersionId(id);
  };
  const quitarSeguimientoAqui = (x: (typeof seguimientos)[number]) => {
    if (x.piezas.length === 0 || !acciones.eliminarVarias) return;
    // Una ficha que también va a otros países solo se saca de éste; las demás se eliminan.
    acciones.eliminarVarias(
      x.piezas.filter((p) => p.paises.length <= 1).map((p) => p.id),
      x.piezas.filter((p) => p.paises.length > 1).map((p) => ({ piezaId: p.id, pais }))
    );
  };
  return (
    <VentanaFlotante
      titulo={suelto ? "⏱ Seguimientos · sin conectar" : `⏱ Seguimientos${camino ? ` · camino ${camino}` : ""} · ${banderaDe(pais)} ${pais}`}
      detalle={
        suelto
          ? "Pegados y aún sin país: el bot no los manda. Puedes editarlos; para agregar o quitar versiones, conéctalos primero a un país."
          : "Salen por tiempo, desde el primer mensaje del cliente, mientras no compre. El orden define cuál sale primero."
      }
      onCerrar={onCerrar}
      ancho={ANCHO_DEL_GESTOR}
    >
      <div className="grid gap-4 md:grid-cols-[260px_minmax(0,1fr)]">
        <div className="flex flex-col gap-1.5">
          {seguimientos.map((x) => (
            <div key={x.indice} className="flex items-center gap-1">
              <div className="min-w-0 flex-1">
                <PasoDelGestor
                  n={String(x.indice + 1)}
                  titulo={x.titulo}
                  detalle={`${minutosDe(x.indice)} min · ${x.piezas.length === 0 ? "no sale aquí" : `${x.piezas.length} versión(es)`}`}
                  elegido={s?.indice === x.indice}
                  onElegir={() => {
                    setElegido(x.indice);
                    setVersionId(null);
                  }}
                  apagado={x.piezas.length === 0}
                />
              </div>
              {!suelto && x.piezas.length > 0 && acciones.eliminarVarias && (
                <button
                  type="button"
                  onClick={() => quitarSeguimientoAqui(x)}
                  title={`Quitar este seguimiento de ${banderaDe(pais)} ${pais}${camino ? ` (camino ${camino})` : ""}. En los otros países sigue. Ctrl+Z lo devuelve.`}
                  className="rounded px-1.5 py-1 text-sm text-red-600 hover:bg-red-50"
                >
                  🗑
                </button>
              )}
            </div>
          ))}
          {!suelto && acciones.crearEnGestor && (
            <button
              type="button"
              onClick={() => crear({ tipo: "seguimiento-nuevo" })}
              className="mt-1 rounded-lg border border-dashed border-borde bg-tarjeta px-2 py-2 text-left text-xs font-semibold text-tinta hover:bg-relleno"
            >
              + Agregar seguimiento
            </button>
          )}
          {!suelto && (
            <p className="mt-1 text-[11px] text-tinta-suave">
              🗑 lo quita solo de {banderaDe(pais)} {pais}
              {camino ? ` (camino ${camino})` : ""}. El orden lo dan sus minutos.
            </p>
          )}
        </div>
        {s && (
          <div className="flex min-w-0 flex-col gap-3">
            <div className="flex flex-wrap items-center gap-2">
              <h4 className="text-sm font-bold text-tinta">
                {s.indice + 1}. {s.titulo}
              </h4>
              {acciones.cambiarTiempo && (
                <label className="flex items-center gap-1 text-xs text-tinta">
                  · sale a los
                  <input
                    key={`${s.indice}_${minutosDe(s.indice)}`}
                    type="number"
                    min={0}
                    defaultValue={minutosDe(s.indice)}
                    onBlur={(e) => acciones.cambiarTiempo?.(s.indice, Math.max(0, Math.floor(Number(e.target.value) || 0)))}
                    className="w-16 rounded border border-borde bg-tarjeta px-1 py-0.5"
                  />
                  min del primer mensaje del cliente (vale para todo este seguimiento)
                </label>
              )}
            </div>
            {s.piezas.length === 0 && (
              <p className="text-sm text-tinta-suave">
                En {banderaDe(pais)} {pais}{camino ? ` (camino ${camino})` : ""} no tiene ninguna versión: aquí este seguimiento no sale. Crea una con «+ Otra versión».
              </p>
            )}
            {s.piezas.length > 1 && (
              <PestanasDelGestor
                opciones={s.piezas.map((p, i) => ({
                  id: p.id,
                  texto: `Versión ${String.fromCharCode(65 + i)} · ${Math.round((100 * (p.peso ?? 1)) / pesoTotal)}%`,
                  apagada: p.estado === "apagada",
                }))}
                valor={versionActual?.id ?? ""}
                onCambiar={(v) => setVersionId(v)}
              />
            )}
            {(() => {
              const p = versionActual;
              if (!p) return null;
              return (
                <>
                  <div className="flex flex-wrap items-center gap-2">
                    <InterruptorDeVersion p={p} acciones={acciones} />
                    {s.piezas.length > 1 && acciones.cambiarPeso && (
                      <label className="flex items-center gap-1 text-xs text-tinta">
                        Peso
                        <input
                          key={`${p.id}_${p.peso ?? 1}`}
                          type="number"
                          min={0}
                          defaultValue={p.peso ?? 1}
                          onBlur={(e) => acciones.cambiarPeso?.(p.id, Math.max(0, Math.floor(Number(e.target.value) || 0)))}
                          className="w-14 rounded border border-borde bg-tarjeta px-1 py-0.5"
                        />
                      </label>
                    )}
                    {!suelto && acciones.duplicarEnGestor && (
                      <button
                        type="button"
                        onClick={() => {
                          const id = acciones.duplicarEnGestor?.(p.id, pais, camino);
                          if (id) setVersionId(id);
                        }}
                        title="Una copia de esta versión, aquí mismo"
                        className="rounded border border-borde px-2 py-0.5 text-[11px] font-semibold text-tinta hover:bg-relleno"
                      >
                        ⧉ Duplicar versión
                      </button>
                    )}
                    {!suelto && (
                      <button
                        type="button"
                        onClick={() => {
                          if (p.paises.length > 1 && acciones.eliminarVarias) acciones.eliminarVarias([], [{ piezaId: p.id, pais }]);
                          else acciones.eliminar(p.id);
                          setVersionId(null);
                        }}
                        title={p.paises.length > 1 ? `También va a otros países: se quita solo de ${pais}.` : "Quitar esta versión. Ctrl+Z la devuelve."}
                        className="rounded border border-red-200 px-2 py-0.5 text-[11px] font-semibold text-red-700 hover:bg-red-50"
                      >
                        🗑 Quitar versión
                      </button>
                    )}
                    {p.ramas.length > 0 && (
                      <span className="text-[11px] text-tinta-suave">Sus botones y cuadritos se cablean desde el borde del cajón, en la pizarra.</span>
                    )}
                  </div>
                  {editor(p.id)}
                </>
              );
            })()}
            {!suelto && acciones.crearEnGestor && (
              <button
                type="button"
                onClick={() => crear({ tipo: "seguimiento", indice: s.indice })}
                className="self-start rounded-md border border-dashed border-borde px-2.5 py-1 text-xs font-semibold text-tinta hover:bg-relleno"
              >
                + Otra versión de este seguimiento
              </button>
            )}
          </div>
        )}
      </div>
    </VentanaFlotante>
  );
}

/**
 * LA GUÍA DE LOS ANUNCIOS (19/10/2026): «el gestor de ads también debería estar en esa pizarra…
 * y ver las campañas y guiarme cuáles son los ads». Por BM y campaña, cada anuncio con su estado y
 * las fichas de ESTA tienda que lo llevan. Las campañas que esta tienda usa, primero. Solo enseña:
 * los anuncios de una ficha se ponen dentro de la ficha, como siempre.
 */
function GuiaDeAnuncios({
  registro,
  destinos,
  onAbrir,
}: {
  registro: AdRegistryEntry[];
  destinos: Array<{ piezaId: string; titulo: string; tipo: string; paises: string[]; apagada: boolean; claves: string[]; dirige: boolean }>;
  onAbrir: (piezaId: string, pais?: string) => void;
}) {
  const [buscar, setBuscar] = useState("");
  const destinosDe = (ad: AdRegistryEntry) => destinos.filter((d) => d.claves.includes(ad.key));
  const q = buscar.trim().toLowerCase();
  const visibles = registro.filter(
    (ad) =>
      !q ||
      [ad.name, ad.reference, ad.meta?.campaign_name, ad.meta?.business_name, ...ad.ids].some((x) => String(x ?? "").toLowerCase().includes(q))
  );
  // BM → campaña → anuncios.
  const grupos = new Map<string, Map<string, AdRegistryEntry[]>>();
  for (const ad of visibles) {
    const bm = ad.meta?.business_name || (ad.meta ? "BM sin nombre" : "Anuncios sin consultar");
    const campana = ad.meta?.campaign_name || "Sin campaña";
    const porCampana = grupos.get(bm) ?? new Map<string, AdRegistryEntry[]>();
    porCampana.set(campana, [...(porCampana.get(campana) ?? []), ad]);
    grupos.set(bm, porCampana);
  }
  const usaLaTienda = (ads: AdRegistryEntry[]) => ads.some((ad) => destinosDe(ad).length > 0);
  // Las claves puestas en una ficha que ya no están en el gestor: se dicen, no se esconden.
  const sinImportar = [...new Set(destinos.flatMap((d) => d.claves))].filter((k) => !registro.some((ad) => ad.key === k));
  const encendido = (ad: AdRegistryEntry) => ad.enabled !== false && ad.meta?.active !== false;
  return (
    <div className="flex flex-col gap-3">
      <input
        value={buscar}
        onChange={(e) => setBuscar(e.target.value)}
        placeholder="Buscar un anuncio, campaña o ID…"
        className="w-full max-w-md rounded-md border border-borde bg-tarjeta px-2 py-1.5 text-sm"
      />
      {registro.length === 0 && (
        <p className="text-sm text-tinta-suave">Todavía no hay anuncios. Impórtalos abajo, con «Consultar / refrescar».</p>
      )}
      {[...grupos.entries()].map(([bm, campanas]) => (
        <div key={bm} className="rounded-lg border border-borde">
          <div className="border-b border-borde bg-relleno px-3 py-1.5 text-xs font-bold uppercase tracking-wide text-tinta-suave">BM: {bm}</div>
          <div className="flex flex-col gap-2 p-2">
            {[...campanas.entries()]
              .sort(([, a], [, b]) => Number(usaLaTienda(b)) - Number(usaLaTienda(a)))
              .map(([campana, ads]) => (
                <div key={campana} className="rounded-md border border-borde bg-tarjeta">
                  <div className="flex flex-wrap items-center gap-2 px-2 py-1.5">
                    <span className="text-sm font-bold text-tinta">📢 {campana}</span>
                    <span className="text-[11px] text-tinta-suave">{ads.length} anuncio(s)</span>
                    {usaLaTienda(ads) && <span className="rounded bg-emerald-100 px-1.5 text-[11px] font-bold text-emerald-800">la usa esta tienda</span>}
                  </div>
                  <div className="flex flex-col divide-y divide-borde border-t border-borde">
                    {ads.map((ad) => {
                      const suyos = destinosDe(ad);
                      return (
                        <div key={ad.key} className={`flex flex-wrap items-center gap-2 px-2 py-1.5 ${encendido(ad) ? "" : "opacity-60"}`}>
                          <span className="rounded px-1.5 py-0.5 text-xs font-semibold" style={{ backgroundColor: ad.color, color: adTagTextColor(ad.color) }}>
                            {ad.reference || ad.name}
                          </span>
                          <span className={`text-[11px] font-bold ${encendido(ad) ? "text-emerald-700" : "text-slate-500"}`}>{encendido(ad) ? "ON" : "OFF"}</span>
                          <span className="text-tinta-suave">→</span>
                          {suyos.length === 0 ? (
                            <span className="text-xs italic text-tinta-suave">ninguna ficha de esta tienda: quien llegue por él recibe una intro del sorteo</span>
                          ) : (
                            suyos.map((d) => (
                              <button
                                key={d.piezaId}
                                type="button"
                                onClick={() => onAbrir(d.piezaId, d.paises[0])}
                                title="Abrir esta ficha"
                                className={`rounded-md border border-borde bg-relleno px-2 py-0.5 text-xs text-tinta hover:bg-acento-suave ${d.apagada ? "opacity-60" : ""}`}
                              >
                                {d.paises.map(banderaDe).join(" ")} {d.tipo} · {d.titulo}
                                {d.apagada ? " (apagada)" : ""}
                                {!d.dirige ? " · etiquetas en OFF" : ""}
                              </button>
                            ))
                          )}
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
          </div>
        </div>
      ))}
      {sinImportar.length > 0 && (
        <div className="rounded-md bg-amber-50 px-2 py-1.5 text-xs text-amber-800" title={sinImportar.join("\n")}>
          <p className="font-semibold">⚠ {sinImportar.length} anuncio(s) viejo(s) en fichas de esta tienda: ya no están en tu lista importada.</p>
          <p>Nadie llegará por ellos. Pasa el ratón para ver sus códigos. Fichas que los tienen:</p>
          <div className="mt-1 flex flex-wrap gap-1">
            {destinos
              .filter((d) => d.claves.some((k) => sinImportar.includes(k)))
              .map((d) => (
                <button
                  key={d.piezaId}
                  type="button"
                  onClick={() => onAbrir(d.piezaId, d.paises[0])}
                  className="rounded border border-amber-300 bg-white px-1.5 py-0.5 text-[11px] text-amber-900 hover:bg-amber-100"
                >
                  {d.paises.map(banderaDe).join(" ")} {d.tipo} · {d.titulo}
                </button>
              ))}
          </div>
        </div>
      )}
    </div>
  );
}

/** UNA VENTANA ENCIMA DE LA PIZARRA (19/10/2026): Escape, clic afuera o ✕ la cierran. */
function VentanaFlotante({
  titulo,
  detalle,
  onCerrar,
  ancho = "max-w-5xl",
  children,
}: {
  titulo: string;
  detalle?: string;
  onCerrar: () => void;
  ancho?: string;
  children: React.ReactNode;
}) {
  useEffect(() => {
    const alPulsar = (e: KeyboardEvent) => {
      if (e.key === "Escape" && !document.querySelector("[data-ventana-de-producto]")) onCerrar();
    };
    window.addEventListener("keydown", alPulsar);
    return () => window.removeEventListener("keydown", alPulsar);
  }, [onCerrar]);
  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-black/40 p-4" onClick={onCerrar}>
      <div className={`my-8 w-full ${ancho} rounded-xl border border-borde bg-tarjeta shadow-2xl`} onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between gap-3 border-b border-borde px-4 py-3">
          <div>
            <h3 className="text-sm font-bold text-tinta">{titulo}</h3>
            {detalle && <p className="text-xs text-tinta-suave">{detalle}</p>}
          </div>
          <button type="button" onClick={onCerrar} className="rounded border border-borde px-3 py-1.5 text-xs font-semibold text-tinta-suave hover:bg-relleno">
            ✕ Cerrar
          </button>
        </div>
        <div className="p-4">{children}</div>
      </div>
    </div>
  );
}

/**
 * MIS TIENDAS (16/10/2026) — la puerta de la pizarra, como «Mis vendedores» de Sendy.
 *
 * Lo pidió así: «voy a vender varios productos con varios números a la vez… al yo dar doble
 * click a PACK MASCOTAS se abre la pizarra», con «duplicar» y, más adelante, «exportar un json».
 * Cada fila es una tienda —número, productos, semimodalidad, cobrador—; doble clic abre su
 * pizarra. «Cambiar sus datos» abre la MISMA ficha de menú ajustes → Tiendas, no otra: así no
 * hay dos sitios que puedan decir cosas distintas de la misma tienda.
 */
/**
 * EL TABLERO DE UNA TIENDA, POR CANAL, Y LOS WORKFLOWS (22-23/10/2026, solo ALBERTO 4) — la ruta
 * que él arma con fichas y cables, y que el bot SÍ sigue. Ver PLAN-TABLERO.md y src/lib/tablero/.
 *
 * Se ve y se maneja como la pizarra (ver `LienzoDelTablero`). Doble clic en una ficha de mensaje o
 * de cobro abre el MISMO cajón de burbujas de siempre; las cajas «Seguimientos» e «Intro de order
 * bump» abren su gestor flotante con sus versiones; las demás, sus ajustes. Todo va al borrador del
 * editor: Ctrl+S guarda y Ctrl+Z deshace, como en la pizarra.
 *
 * UN TABLERO POR CANAL, como la sección Canales: «es que no puede funcionar el mismo camino para
 * messenger… yo puedo variar las burbujas cuando yo desee». Messenger e Instagram tienen
 * «Clonar desde WhatsApp». Un workflow es uno solo para los tres canales.
 */
function tableroVacio(): TableroEnElEditor {
  return { encendido: false, fichas: [{ id: "inicio", tipo: "inicio", x: 0, y: 160 }], cables: [] };
}

type CanalDeTablero = "whatsapp" | "messenger" | "instagram";
const CANALES_DE_TABLERO: Array<[CanalDeTablero, string]> = [
  ["whatsapp", "🟢 WhatsApp"],
  ["messenger", "🔵 Messenger"],
  ["instagram", "🟣 Instagram"],
];

function textoDeLaBurbuja(s: EditorStep | undefined): string {
  if (!s) return "";
  return (s.texts ?? []).find((t) => t?.trim())?.trim() ?? "";
}

function PantallaDelTablero({
  cfg,
  clave,
  tema,
  onTema,
  onTienda,
  onVolver,
  aplicar,
  onConfigChange,
  onSnapshot,
  onPais,
}: {
  /** Pone la bandera de abajo a la derecha en ese país (al tocar una ficha de su manta). */
  onPais?: (pais: string) => void;
  cfg: FullConfig;
  /** La tienda (su id) o un workflow (`wf:<id>`). */
  clave: string;
  tema: "claro" | "mixto" | "oscuro";
  onTema: (t: "claro" | "mixto" | "oscuro") => void;
  onTienda: (id: string) => void;
  onVolver: () => void;
  aplicar: (c: FullConfig) => void;
  /** Para las ventanas del ☰ (Datos de la tienda, Productos): las mismas que en la pizarra. */
  onConfigChange: (c: FullConfig) => void;
  onSnapshot: () => void;
}) {
  const esWorkflow = clave.startsWith("wf:");
  const wfId = esWorkflow ? clave.slice(3) : "";
  const tiendas = cfg.tiendas ?? [];
  const tienda = esWorkflow ? undefined : tiendas.find((t) => t.id === clave) ?? tiendas[0];
  const tiendaId = tienda?.id ?? "";
  const [canal, setCanal] = useState<CanalDeTablero>(() => {
    try {
      const c = window.localStorage.getItem("tablero-canal");
      return c === "messenger" || c === "instagram" ? c : "whatsapp";
    } catch {
      return "whatsapp";
    }
  });
  const elegirCanal = (c: CanalDeTablero) => {
    setCanal(c);
    try {
      window.localStorage.setItem("tablero-canal", c);
    } catch {}
  };
  const tablero: TableroEnElEditor = esWorkflow
    ? cfg.workflows?.[wfId] ?? tableroVacio()
    : cfg.tableros?.[tiendaId]?.[canal] ?? tableroVacio();
  const [cajon, setCajon] = useState<string | null>(null);
  const [burbujaDelCajon, setBurbujaDelCajon] = useState<number | null>(null);
  const [verCerebro, setVerCerebro] = useState(false);
  const [gestor, setGestor] = useState<string | null>(null);
  const [ajustes, setAjustes] = useState<string | null>(null);
  const [paisVisto, setPaisVisto] = useState<string>("PE");
  // EL BUSCADOR EN LA BARRA y el ☰ HERRAMIENTAS, como en la pizarra (24/10/2026).
  const [buscar, setBuscar] = useState("");
  const [menuHerramientas, setMenuHerramientas] = useState(false);
  // ESCAPE O UN CLIC AFUERA CIERRAN EL ☰ (25/10/2026), como en la pizarra (`refDeHerramientas`).
  const refDeHerramientasDelTablero = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!menuHerramientas) return;
    const alTeclear = (e: KeyboardEvent) => {
      if (e.key === "Escape") setMenuHerramientas(false);
    };
    const alPulsar = (e: PointerEvent) => {
      if (!refDeHerramientasDelTablero.current?.contains(e.target as globalThis.Node | null)) setMenuHerramientas(false);
    };
    window.addEventListener("keydown", alTeclear);
    window.addEventListener("pointerdown", alPulsar);
    return () => {
      window.removeEventListener("keydown", alTeclear);
      window.removeEventListener("pointerdown", alPulsar);
    };
  }, [menuHerramientas]);
  const [ventanaDeHerramienta, setVentanaDeHerramienta] = useState<null | "tienda" | "productos" | "prueba" | "pagos" | "anuncios" | "exportar">(null);
  const [regaloAbierto, setRegaloAbierto] = useState<string | null>(null);
  const [avisoDelTablero, setAvisoDelTablero] = useState<string | null>(null);
  // LOS NÚMEROS DE CADA FICHA (25/10/2026): clientes que llegaron y cuántos pagaron, como en la
  // pizarra. Se piden al abrir y cada minuto; si falla, simplemente no se muestran.
  const [numeros, setNumeros] = useState<Record<string, { clientes: number; ventas: number; ahora?: number }>>({});
  useEffect(() => {
    if (!tiendaId) return;
    let vivo = true;
    const pedir = () =>
      fetch(`/api/tablero-numeros?tienda=${encodeURIComponent(tiendaId)}`)
        .then((r) => (r.ok ? r.json() : null))
        .then((d) => vivo && d?.numeros && setNumeros(d.numeros))
        .catch(() => {});
    pedir();
    const reloj = window.setInterval(pedir, 60_000);
    return () => {
      vivo = false;
      window.clearInterval(reloj);
    };
  }, [tiendaId]);
  useEffect(() => {
    if (!avisoDelTablero) return;
    const r = window.setTimeout(() => setAvisoDelTablero(null), 9000);
    return () => window.clearTimeout(r);
  }, [avisoDelTablero]);
  const [paisDePagos, setPaisDePagos] = useState<string>("PE");
  const vivoCfg = useRef(cfg);
  vivoCfg.current = cfg;
  const productos = (cfg.biblioteca_de_productos ?? []).filter((p) => p.id);
  const nombres: Record<string, string> = {
    ...Object.fromEntries(productos.map((p) => [p.id, p.name?.trim() || p.id])),
    // Los anuncios por su nombre, para las salidas del Inicio «📣 anuncio» (26/10/2026).
    ...Object.fromEntries(((cfg as { ad_registry?: Array<{ key: string; name?: string }> }).ad_registry ?? []).map((a) => [`anuncio:${a.key}`, a.name?.trim() || a.key])),
  };
  const nombreDelProducto = (pid?: string) => (pid ? nombres[pid] : undefined) ?? "(sin elegir)";
  /** «FIGURARTE» o «FIGURARTE · Muestras gratuitas»: el nombre de una entrega por su clave. */
  const nombreDeLaEntrega = (clave: string) => {
    const [pid, eid] = clave.split("#");
    if (!eid) return nombreDelProducto(pid);
    const e = productos.find((p) => p.id === pid)?.entregas_extra?.find((x) => x.id === eid);
    return `${nombreDelProducto(pid)} · ${e?.nombre?.trim() || "(entrega borrada)"}`;
  };
  // LAS ENTREGAS PARA ELEGIR EN UNA FICHA «ENTREGAR» (25/10/2026), agrupadas por producto: primero los
  // de esta tienda (su selector y los que ya usa este tablero) y al final los demás, para que nada
  // quede escondido. Cada producto: su entrega principal y sus entregas extra.
  const enEsteTablero = new Set<string>(Object.values(tienda?.alineacion ?? {}).filter((v): v is string => typeof v === "string" && !!v));
  {
    const texto = JSON.stringify(tablero.fichas ?? []);
    for (const p of productos) if (texto.includes(`"${p.id}"`) || texto.includes(`"${p.id}#`)) enEsteTablero.add(p.id);
  }
  const entregasPorProducto = [...productos]
    .sort((x, y) => Number(enEsteTablero.has(y.id)) - Number(enEsteTablero.has(x.id)))
    .map((p) => ({
      id: p.id,
      nombre: p.name?.trim() || p.id,
      propio: enEsteTablero.has(p.id),
      opciones: [
        { clave: p.id, nombre: "entrega principal" },
        ...(p.entregas_extra ?? []).map((e) => ({ clave: `${p.id}#${e.id}`, nombre: e.nombre?.trim() || "Entrega sin nombre" })),
      ],
    }));
  const workflows = Object.entries(cfg.workflows ?? {}).map(([id, w]) => ({ id, nombre: w.nombre?.trim() || "Workflow sin nombre" }));
  // QUIÉN COBRA EN CADA PAÍS, PARA SU INICIO (29/10/2026). Él: «que automáticamente aparezca el avatar del
  // cobrador que está activo… o si se olvidó de seleccionarlo, el que es por defecto… yo solo miro la pizarra y
  // digo, ah ok, está bien el que va a cobrar». La misma regla del bot (`quienCobraEn`): el cobrador de la tienda
  // si tiene cuenta en ese país; si no, el titular de los Datos para pago del país («por defecto»).
  const quienCobraPorPais: Record<string, { foto?: string; nombre: string; porDefecto: boolean }> = {};
  if (!esWorkflow)
    for (const f of tablero.fichas) {
      if (f.tipo !== "inicio" || !f.pais || quienCobraPorPais[f.pais]) continue;
      const q = quienCobraEn(cfg, tienda, f.pais);
      const perfil = (cfg.modality_payment_profiles?.[activeModality(cfg)]?.[f.pais as CountryCode] ??
        cfg.payment_profiles_by_country?.[f.pais as CountryCode]) as { foto?: string } | undefined;
      quienCobraPorPais[f.pais] =
        q.deQuien && q.cobrador
          ? { foto: q.cobrador.foto, nombre: q.cobrador.nombre?.trim() || q.nombre, porDefecto: false }
          : { foto: perfil?.foto, nombre: q.nombre || q.titular || "Cuenta del país", porDefecto: true };
    }

  const guardar = (t: TableroEnElEditor) =>
    aplicar(
      esWorkflow
        ? { ...cfg, workflows: { ...(cfg.workflows ?? {}), [wfId]: t } }
        : { ...cfg, tableros: { ...(cfg.tableros ?? {}), [tiendaId]: { ...(cfg.tableros?.[tiendaId] ?? {}), [canal]: t } } }
    );
  const cambiarFicha = (fid: string, cambio: Partial<FichaEnElEditor>) =>
    guardar({ ...tablero, fichas: tablero.fichas.map((f) => (f.id === fid ? { ...f, ...cambio } : f)) });

  /**
   * TRAER FICHAS DE UN ARCHIVO O DE LA PIZARRA (25/10/2026). Con el tablero vacío, entra entero:
   * sus Inicios con sus mantas, listo para revisar (apagado). Con fichas ya puestas, entra al lado,
   * sin Inicios y sin conectar («nada se conecta solo»): lo suyo no se toca.
   */
  const traerAlTablero = (r: ReturnType<typeof fichasDeUnArchivo>) => {
    if ("error" in r) {
      setAvisoDelTablero(r.error);
      return;
    }
    const actual = tablero;
    const vacio = actual.fichas.every((f) => f.tipo === "inicio") && actual.cables.length === 0;
    let nuevo: TableroEnElEditor;
    let dicho: string;
    if (vacio) {
      const t = { ...r.tablero, encendido: false, cerebro: actual.cerebro ?? r.tablero.cerebro };
      nuevo = { ...t, cajas: [...(t.cajas ?? []).filter((c) => !c.inicio), ...t.fichas.filter((f) => f.tipo === "inicio").map((i) => mantaPara(t, i))] };
      const paisesNuevos = t.fichas.filter((f) => f.tipo === "inicio").map((f) => (f.pais ? `${banderaDe(f.pais)} ${f.pais}` : "🌍 Otros países"));
      dicho = `Tablero armado: ${t.fichas.length} fichas en ${paisesNuevos.join(", ")}. Queda APAGADO hasta que lo revises y lo enciendas.`;
    } else {
      const derecha = Math.max(...actual.fichas.map((f) => f.x + 250)) + 300;
      const arriba = Math.min(...actual.fichas.map((f) => f.y));
      const minX = Math.min(...r.tablero.fichas.map((f) => f.x));
      const minY = Math.min(...r.tablero.fichas.map((f) => f.y));
      const copia = copiarFichas(r.tablero.fichas, r.tablero.cables, { x: derecha - minX, y: arriba - minY });
      nuevo = { ...actual, fichas: [...actual.fichas, ...copia.fichas], cables: [...actual.cables, ...copia.cables] };
      dicho = `${copia.fichas.length} ficha(s) traídas a la derecha de lo tuyo, sin Inicio y sin conectar: cablea la primera a tu Inicio.`;
    }
    onSnapshot();
    aplicar(
      esWorkflow
        ? { ...r.cfg, workflows: { ...(r.cfg.workflows ?? {}), [wfId]: nuevo } }
        : { ...r.cfg, tableros: { ...(r.cfg.tableros ?? {}), [tiendaId]: { ...(r.cfg.tableros?.[tiendaId] ?? {}), [canal]: nuevo } } }
    );
    setVentanaDeHerramienta(null);
    setAvisoDelTablero([dicho, ...r.avisos].join(" "));
  };

  const inicios = tablero.fichas.filter((f) => f.tipo === "inicio");
  const conectados = inicios.filter((f) => !f.sin_venta && !f.en_revision && tablero.cables.some((c) => c.de === f.id && c.salida === "siguiente"));
  const atiende = esWorkflow || (tablero.encendido && conectados.length > 0);

  const resumenDe = (f: FichaEnElEditor): string => {
    const pasos = ((f.steps ?? []) as EditorStep[]).filter((s) => s.enabled !== false);
    const presenta = (f.presenta ?? []).length ? `\nPresenta: ${(f.presenta ?? []).map((x) => nombreDelProducto(x)).join(", ")}` : "";
    switch (f.tipo) {
      case "inicio":
        return "";
      case "mensaje":
        return (pasos.length === 0 ? "Sin burbujas — doble clic para escribirlas." : "") + presenta;
      case "intro_ob":
        return `${(f.variantes ?? []).length} versión(es) · destapa el producto oculto${presenta}`;
      case "seguimientos": {
        const s = f.seguimientos ?? [];
        return s.length === 0
          ? "Sin seguimientos — doble clic para crearlos."
          : `${s.length} seguimiento(s) · el 1 a ${minutosLegiblesDelTablero(s[0].minutos)}${s.length > 1 ? " · los demás en tu horario fijo" : ""}\nSe detienen si elige o paga.${presenta}`;
      }
      case "correo":
        return `Pide el correo y le manda lo que recibió.${f.sin_respuesta_min ? `\nSi no lo da en ${minutosLegiblesDelTablero(f.sin_respuesta_min)}, sigue por «No dio su correo».` : ""}`;
      case "entregar":
        return f.entregas?.length
          ? `Entrega: ${f.entregas.map(nombreDeLaEntrega).join(" + ")}`
          : `Entrega: ${nombreDelProducto(f.producto_id)}`;
      case "cobro": {
        const c = f.cobro;
        const precio = c?.precio === "normal" ? "precio normal" : c?.precio === "oferta" ? "precio de oferta" : "precio según la etapa";
        if (c?.modo === "producto")
          return `Cobra: ${nombreDelProducto(c.producto_id)} · ${precio}${(c.acepta ?? []).length ? `\nTambién acepta: ${(c.acepta ?? []).map((x) => nombreDelProducto(x)).join(", ")}` : ""}${
            c.metodos ? "\n💳 Pregunta el método y manda sus datos" : ""
          }${c.diferencia ? "\n⬆️ Si ya compró uno más barato, cobra la diferencia" : ""}`;
        const min = c?.minimo_por_pais?.[paisVisto];
        const tramos = c?.tramos_por_pais?.[paisVisto]?.length ?? 0;
        return `Pago abierto · ${paisVisto}: mínimo ${min ?? 0}, ${tramos} tramo${tramos === 1 ? "" : "s"}`;
      }
      case "condicion": {
        const c = f.condicion;
        if (c?.tipo === "pais") return `¿Es de ${(c.paises ?? []).join(", ") || "(elige países)"}?`;
        if (c?.tipo === "anuncio")
          return (c.anuncios ?? []).length
            ? `¿Vino de: ${(c.anuncios ?? []).map((k) => cfg.ad_registry?.find((a) => a.key === k)?.name ?? k).join(", ")}?`
            : "¿Vino de un anuncio?";
        return `¿Ya compró ${nombreDelProducto(c?.producto_id)}?`;
      }
      case "reparto":
        return "Reparte a los clientes entre sus rutas, por peso.";
      case "esperar":
        return `Espera ${minutosLegiblesDelTablero(f.minutos ?? 60)} y sigue.`;
      case "workflow":
        return `Lleva al workflow: ${workflows.find((w) => w.id === f.workflow_id)?.nombre ?? "(sin elegir)"}`;
      case "regalo":
        return "Arranca el regalo de siempre (el de esta tienda, si tiene).";
      case "humano":
        return "El bot se calla y te avisa.";
    }
  };

  const fichaDeCajon = tablero.fichas.find((f) => f.id === cajon);
  const fichaDeGestor = tablero.fichas.find((f) => f.id === gestor);
  const fichaDeAjustes = tablero.fichas.find((f) => f.id === ajustes);
  const paises = Object.keys(COUNTRIES);
  const fondoOscuro = tema !== "claro";
  const vacioEnEsteCanal = (t: TableroEnElEditor | undefined) =>
    !t || (t.fichas.filter((f) => f.tipo !== "inicio").length === 0 && t.cables.length === 0);

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <div className={`flex flex-wrap items-center gap-2 border-b border-borde bg-tarjeta px-4 py-2 text-tinta ${fondoOscuro ? "tema-oscuro-local" : ""}`}>
        {esWorkflow ? (
          <input
            value={cfg.workflows?.[wfId]?.nombre ?? ""}
            onChange={(e) => guardar({ ...tablero, nombre: e.target.value })}
            placeholder="Nombre del workflow"
            className="w-56 rounded-md border border-borde bg-relleno px-2 py-1 text-xs font-semibold text-tinta"
            title="El nombre con el que lo eliges en «Activar workflow»"
          />
        ) : (
          <select
            value={tiendaId}
            onChange={(e) => onTienda(e.target.value)}
            className="rounded-md border border-borde bg-relleno px-2 py-1 text-xs font-semibold text-tinta"
            title="Tienda"
          >
            {tiendas.map((t, i) => (
              <option key={t.id} value={t.id}>
                🏪 {t.nombre?.trim() || `Tienda ${i + 1}`}
              </option>
            ))}
          </select>
        )}
        <span className="text-xs font-bold">{esWorkflow ? "▶▶ Workflow" : "🧩 Tablero"}</span>
        {/* EL BUSCADOR, EN LA BARRA como en la pizarra: las que coinciden se marcan y lo demás queda tenue. */}
        <input
          type="search"
          value={buscar}
          onChange={(e) => setBuscar(e.target.value)}
          onKeyDown={(e) => e.key === "Escape" && setBuscar("")}
          placeholder="🔍 Buscar"
          title="Busca en los títulos y en lo que dicen las burbujas · Esc: borrar"
          className="w-40 rounded-md border border-borde bg-relleno px-2 py-1 text-xs text-tinta"
        />
        {!esWorkflow && (
          <span className="inline-flex overflow-hidden rounded-lg border border-borde text-xs" role="group" aria-label="Canal">
            {CANALES_DE_TABLERO.map(([c, nombre]) => (
              <button
                key={c}
                type="button"
                aria-pressed={canal === c}
                onClick={() => elegirCanal(c)}
                className={`px-2.5 py-1 font-semibold ${canal === c ? "bg-carbon-fuerte text-white" : "bg-tarjeta text-tinta-suave hover:bg-relleno"}`}
              >
                {nombre}
              </button>
            ))}
          </span>
        )}
        {!esWorkflow && canal !== "whatsapp" && (
          <button
            type="button"
            onClick={() => {
              const deWhatsApp = cfg.tableros?.[tiendaId]?.whatsapp;
              if (vacioEnEsteCanal(deWhatsApp)) {
                window.alert("El tablero de WhatsApp de esta tienda está vacío: no hay nada que clonar.");
                return;
              }
              if (!vacioEnEsteCanal(cfg.tableros?.[tiendaId]?.[canal]) && !window.confirm(`El tablero de ${canal === "messenger" ? "Messenger" : "Instagram"} ya tiene fichas. ¿Reemplazarlo por una copia del de WhatsApp?`))
                return;
              guardar({ ...JSON.parse(JSON.stringify(deWhatsApp)), encendido: false });
            }}
            className="rounded-md border border-borde bg-relleno px-2 py-1 text-xs font-semibold text-tinta hover:bg-tarjeta"
            title="Copia fichas, burbujas, botones y cables del tablero de WhatsApp. Luego lo cambias sin tocar el de WhatsApp. Nace apagado."
          >
            ⧉ Clonar desde WhatsApp
          </button>
        )}
        {!esWorkflow && (
          <button
            type="button"
            onClick={() => guardar({ ...tablero, encendido: !tablero.encendido })}
            className={`rounded-md px-3 py-1 text-xs font-bold text-white ${tablero.encendido ? "bg-emerald-600 hover:bg-emerald-700" : "bg-slate-500 hover:bg-slate-600"}`}
            title="Encendido: los clientes NUEVOS de esta tienda, en este canal, van por el tablero. Apagado: venta automática."
          >
            {tablero.encendido ? "● Encendido" : "○ Apagado"}
          </button>
        )}
        <span className={`text-[11px] font-semibold ${atiende ? "text-emerald-700" : "text-tinta-suave"}`}>
          {esWorkflow
            ? "Arranca cuando un botón, cuadrito o ficha lo activa."
            : atiende
              ? `Los clientes nuevos (${conectados.map((f) => f.pais ?? "otros países").join(", ")}) van por este tablero.`
              : !tablero.encendido
                ? "Apagado: esta tienda vende con la venta automática en este canal."
                : "Falta conectar un ▶ Inicio: mientras tanto, venta automática."}
        </span>
        {/* EL CEREBRO GENERAL (24/10/2026): uno por tablero, con el de fábrica si no se escribe. */}
        <button
          type="button"
          onClick={() => setVerCerebro(true)}
          className="rounded-md border border-borde bg-relleno px-2 py-1 text-xs font-semibold text-tinta hover:bg-tarjeta"
          title="Quién es la IA y cómo habla en todo este tablero"
        >
          🧠 Cerebro{tablero.cerebro?.trim() ? " · tuyo" : " · de fábrica"}
        </button>
        {verCerebro && (
          <VentanaFlotante
            titulo="🧠 Cerebro general de este tablero"
            detalle="Quién es la IA y cómo habla en todas las fichas. Lo de cada etapa va en su ficha (⚙ → Instrucciones para la IA aquí)."
            onCerrar={() => setVerCerebro(false)}
            ancho="max-w-3xl"
          >
            <textarea
              value={tablero.cerebro ?? CEREBRO_DE_FABRICA}
              onChange={(e) => guardar({ ...tablero, cerebro: e.target.value.trim() === CEREBRO_DE_FABRICA.trim() ? undefined : e.target.value })}
              rows={12}
              className="w-full rounded-md border border-borde bg-relleno px-3 py-2 text-sm"
            />
            <div className="mt-2 flex flex-wrap items-center gap-2 text-[11px] text-tinta-suave">
              <button type="button" onClick={() => guardar({ ...tablero, cerebro: undefined })} className="rounded border border-borde px-2 py-1 font-semibold text-tinta hover:bg-relleno">
                Volver al de fábrica
              </button>
              {/* COPIAR EL CEREBRO DEL AUTOMÁTICO (27/10/2026): una copia de sus secciones (=== ROL ===, PAGO…), que
                  el tablero recorta por etapa como la venta de siempre. Es una copia: editarla aquí no cambia el
                  automático, ni al revés. Lo que ya estaba escrito arriba (quién es esta tienda) se conserva delante. */}
              <button
                type="button"
                onClick={() => {
                  const s = (cfg as { system_prompt_sections?: Record<string, unknown> }).system_prompt_sections ?? {};
                  const leer = (k: string) => {
                    const v = s[k] as string | { text?: string; content?: string } | undefined;
                    return String(typeof v === "string" ? v : v?.text ?? v?.content ?? "").trim();
                  };
                  const secciones = (
                    [
                      ["ROL", leer("rol_producto")],
                      ["IDIOMA", leer("idioma_pais")],
                      ["PAGO", leer("pago")],
                      ["PRECIO Y CIERRE", leer("precio_cierre")],
                      ["POSTVENTA", leer("postventa")],
                      ["EXTRA", leer("extra")],
                    ] as const
                  ).filter(([, t]) => t);
                  if (secciones.length === 0) {
                    window.alert("El cerebro del automático no tiene secciones escritas: no hay nada que copiar.");
                    return;
                  }
                  const suyo = (tablero.cerebro ?? "").split(/^===\s/m)[0].replace(/\(Lo que sigue es la copia[^)]*\)\s*$/, "").trim();
                  if (!window.confirm("¿Copiar aquí el cerebro del automático? Lo que ya tenía este tablero (antes de las secciones) se conserva delante.")) return;
                  guardar({
                    ...tablero,
                    cerebro: `${suyo ? `${suyo}\n\n` : ""}(Lo que sigue es la copia de tu cerebro del automático. Se edita aquí y solo cambia este tablero.)\n\n${secciones
                      .map(([n, t]) => `=== ${n} ===\n${t}`)
                      .join("\n\n")}`,
                  });
                }}
                className="rounded border border-borde px-2 py-1 font-semibold text-tinta hover:bg-relleno"
                title="Copia aquí tu cerebro del automático, para que este tablero hable como él"
              >
                ⧉ Copiar el cerebro del automático
              </button>
              <span>
                Lo que protege el dinero va siempre y no está aquí: nunca da números de cuenta, solo nombra los montos permitidos y solo habla de los
                productos ya presentados.
              </span>
            </div>
          </VentanaFlotante>
        )}
        <span className="ml-auto" />
        <span className="inline-flex overflow-hidden rounded-lg border border-borde text-xs" role="group" aria-label="Tema">
          {(
            [
              ["claro", "☀️ Claro"],
              ["mixto", "🌗 Mixto"],
              ["oscuro", "🌙 Oscuro"],
            ] as const
          ).map(([v, n]) => (
            <button
              key={v}
              type="button"
              aria-pressed={tema === v}
              onClick={() => onTema(v)}
              className={`px-2 py-1 font-semibold ${tema === v ? "bg-carbon-fuerte text-white" : "bg-tarjeta text-tinta-suave hover:bg-relleno"}`}
            >
              {n}
            </button>
          ))}
        </span>
        <label className="flex items-center gap-1 text-[11px] text-tinta-suave" title="Los montos de los cobros se ven con los de este país">
          Montos de
          <select value={paisVisto} onChange={(e) => setPaisVisto(e.target.value)} className="rounded border border-borde bg-relleno px-1 py-0.5 text-[11px] text-tinta">
            {paises.map((p) => (
              <option key={p} value={p}>
                {p}
              </option>
            ))}
          </select>
        </label>
      </div>
      <div className="min-h-0 flex-1 overflow-hidden">
        <LienzoDelTablero
          key={`${clave}|${canal}`}
          tablero={tablero}
          resumenDe={resumenDe}
          paisVisto={paisVisto}
          tema={fondoOscuro ? "oscuro" : "claro"}
          nombres={nombres}
          paisesDisponibles={paises}
          quienCobra={quienCobraPorPais}
          onCambiar={guardar}
          onAbrir={(fid, burbuja) => {
            const f = tablero.fichas.find((x) => x.id === fid);
            setBurbujaDelCajon(burbuja ?? null);
            if (f?.tipo === "mensaje" || f?.tipo === "cobro" || f?.tipo === "correo") setCajon(fid);
            else if (f?.tipo === "seguimientos" || f?.tipo === "intro_ob") setGestor(fid);
            else if (f?.tipo === "regalo" && tienda) setRegaloAbierto(fid);
            else setAjustes(fid);
          }}
          onAjustes={setAjustes}
          // TOCAR UNA FICHA LLEVA LA BANDERA A SU PAÍS (27/10/2026): el de su Inicio, si es de uno solo.
          onFichaTocada={(fid) => {
            const f = tablero.fichas.find((x) => x.id === fid);
            if (!f) return;
            const pais = f.tipo === "inicio" ? f.pais ?? "" : paisDeSuManta(tablero, f, "");
            if (!pais) return;
            setPaisVisto(pais);
            onPais?.(pais);
          }}
          buscar={buscar}
          numeros={esWorkflow ? undefined : numeros}
          antesDelMas={
            <button
              type="button"
              onClick={onVolver}
              title="Volver a Mis tiendas"
              className="flex h-9 w-9 items-center justify-center rounded-full border border-borde bg-tarjeta text-lg font-bold text-tinta shadow-md hover:bg-relleno"
            >
              ←
            </button>
          }
          despuesDelMas={
            <div className="relative flex items-center gap-2" ref={refDeHerramientasDelTablero}>
              {/* EL SIMULADOR, A LA VISTA (27/10/2026): un botón propio, no escondido en el ☰. */}
              <button
                type="button"
                onClick={() => setVentanaDeHerramienta("prueba")}
                title="Simulador: chatea con el bot como un cliente, sin enviar nada a Meta"
                className="order-2 flex h-9 items-center gap-1 rounded-full bg-emerald-600 px-3 text-xs font-bold text-white shadow-md hover:bg-emerald-700"
              >
                💬 Simulador
              </button>
              <button
                type="button"
                onClick={() => setMenuHerramientas((v) => !v)}
                title="Tienda, productos y simulador"
                className="flex h-9 w-9 items-center justify-center rounded-full bg-slate-700 text-lg font-bold text-white shadow-md hover:bg-slate-800"
              >
                {menuHerramientas ? "×" : "☰"}
              </button>
              {menuHerramientas && (
                <div className="absolute left-0 top-11 z-50 w-72 overflow-hidden rounded-xl border border-borde bg-tarjeta py-1 text-sm text-tinta shadow-2xl">
                  <div className="px-3 py-1.5 text-[11px] font-bold uppercase tracking-wide text-tinta-suave">Sin salir del tablero</div>
                  {(
                    [
                      ["tienda", "🏪", "Datos de esta tienda", "Número, página, pixel, quién cobra, frases de entrada y su regalo"],
                      ["productos", "📦", "Productos y precios", "Precio por país, entrega, contenido y muestras"],
                      ["pagos", "💳", "Datos de pago por país", "Los textos de cada método (Yape, BCP…), las cuentas y el menú de métodos, por país"],
                      ["anuncios", "📣", "Anuncios", "Tus campañas y anuncios, y a qué ficha de este tablero lleva cada uno"],
                      ["prueba", "💬", "Simulador", "Chatea con el bot como un cliente, sin enviar nada a Meta"],
                      ["exportar", "⇅", "Exportar / importar tienda", "La tienda entera (con su tablero) en un archivo JSON, y traerla de vuelta"],
                    ] as const
                  ).map(([v, icono, texto, ayuda]) => (
                    <button
                      key={v}
                      type="button"
                      title={ayuda}
                      disabled={(v === "tienda" || v === "exportar") && !tienda}
                      onClick={() => {
                        setMenuHerramientas(false);
                        setVentanaDeHerramienta(v);
                      }}
                      className="flex w-full items-center gap-2 px-3 py-1.5 text-left hover:bg-relleno disabled:opacity-40"
                    >
                      <span className="w-5 text-center">{icono}</span> {texto}
                    </button>
                  ))}
                </div>
              )}
            </div>
          }
        />
      </div>
      {regaloAbierto && tienda && (
        <GestorDelRegaloDelTablero
          cfg={cfg}
          tiendaId={tienda.id}
          pais={(() => {
            const f = tablero.fichas.find((x) => x.id === regaloAbierto);
            return f ? paisDeSuManta(tablero, f, paisVisto) : paisVisto;
          })()}
          aplicar={aplicar}
          onCerrar={() => setRegaloAbierto(null)}
        />
      )}
      {/* LAS VENTANAS DEL ☰, las mismas de la pizarra, encima del tablero. */}
      {ventanaDeHerramienta === "tienda" && tienda && (
        <VentanaDeDatosDeTienda
          cfg={cfg}
          tienda={tienda}
          onConfigChange={onConfigChange}
          onSnapshot={onSnapshot}
          onCerrar={() => setVentanaDeHerramienta(null)}
          alEditarProductos={() => setVentanaDeHerramienta("productos")}
        />
      )}
      {ventanaDeHerramienta === "productos" && (
        <VentanaFlotante titulo="📦 Productos y precios" detalle="Busca un producto y ábrelo: precio por país, entrega y contenido. Ctrl+Z deshace." onCerrar={() => setVentanaDeHerramienta(null)}>
          <BibliotecaDeProductos
            cfg={cfg}
            productos={cfg.biblioteca_de_productos ?? []}
            onProductos={(lista) => {
              onSnapshot();
              onConfigChange({ ...vivoCfg.current, biblioteca_de_productos: lista });
            }}
            onCfg={onConfigChange}
            pais={paisVisto as CountryCode}
            modalidad={activeModality(cfg)}
            alineacion={(configComoLaVeLaTienda(cfg, tienda, "lineal").alineacion_por_modalidad?.[activeModality(cfg)] ?? {}) as AlineacionEditor}
            precioBase={cfg.globals?.course_price_soles ?? 0}
            comboPrice={previewComboPriceFromConfig(cfg)}
            basicoPrice={previewBasicoPriceFromConfig(cfg)}
            previewContext={previewContextFromConfig(cfg)}
            onSnapshot={onSnapshot}
            onEdit={() => onSnapshot()}
            onMarcarPunto={() => {}}
            onCancelarVentana={() => {}}
          />
        </VentanaFlotante>
      )}
      {/* LOS DATOS DE PAGO POR PAÍS (24/10/2026): la MISMA ventana de «Precios y pagos» de los menús,
          aquí sin salir del tablero. Son los textos que el cobro manda al elegir cada método. */}
      {ventanaDeHerramienta === "pagos" && (
        <VentanaFlotante
          titulo="💳 Datos de pago por país"
          detalle="Lo que el cobro manda cuando el cliente elige cada método. Es lo mismo que menú ajustes → Precios y pagos: cambiarlo aquí lo cambia allá."
          onCerrar={() => setVentanaDeHerramienta(null)}
          ancho="max-w-6xl"
        >
          <label className="mb-3 flex items-center gap-2 text-xs font-semibold text-tinta">
            País
            <select value={paisDePagos} onChange={(e) => setPaisDePagos(e.target.value)} className="rounded border border-borde bg-relleno px-2 py-1 text-xs">
              {paises.map((p) => (
                <option key={p} value={p}>
                  {banderaDe(p)} {p}
                </option>
              ))}
            </select>
          </label>
          <DatosDePagoDelTablero key={paisDePagos} cfg={cfg} pais={paisDePagos as CountryCode} onConfigChange={onConfigChange} onSnapshot={onSnapshot} />
        </VentanaFlotante>
      )}
      {ventanaDeHerramienta === "prueba" && (
        <VentanaFlotante
          titulo="💬 Simulador"
          detalle="Chatea con el bot como un cliente, sin enviar nada a Meta. Lo que no hayas guardado no entra."
          onCerrar={() => setVentanaDeHerramienta(null)}
          ancho="max-w-6xl"
        >
          <iframe src="/simulador" title="Simulador" className="h-[75vh] w-full rounded-md border border-borde bg-white" />
        </VentanaFlotante>
      )}
      {/* LOS ANUNCIOS, como en la pizarra (25/10/2026): por BM y campaña, a qué ficha de ESTE tablero
          lleva cada anuncio (las versiones con su etiqueta y las condiciones «¿vino de un anuncio?»). */}
      {ventanaDeHerramienta === "anuncios" && (
        <VentanaFlotante
          titulo="📣 Anuncios"
          detalle="Por BM y campaña: a qué ficha de este tablero lleva cada anuncio. Abajo, para importar y administrar."
          onCerrar={() => setVentanaDeHerramienta(null)}
          ancho="max-w-6xl"
        >
          <GuiaDeAnuncios
            registro={cfg.ad_registry ?? []}
            destinos={tablero.fichas.flatMap((f) => {
              const pais = paisDeSuManta(tablero, f, "");
              const paisesDeLaFicha = pais ? [pais] : [];
              const nombre = f.titulo?.trim() || (f.tipo === "intro_ob" ? "Intro de order bump" : f.tipo === "seguimientos" ? "Seguimientos" : "Condición");
              const deVersiones = (vs: VersionEnElEditor[], tipo: string) =>
                vs
                  .filter((v) => (v.anuncios ?? []).length > 0)
                  .map((v, i) => ({
                    piezaId: f.id,
                    titulo: `${nombre} · ${v.nombre?.trim() || `Versión ${String.fromCharCode(65 + i)}`}`,
                    tipo,
                    paises: paisesDeLaFicha,
                    apagada: !!f.apagada,
                    claves: v.anuncios ?? [],
                    dirige: v.dirigir !== false,
                  }));
              if (f.tipo === "intro_ob") return deVersiones(f.variantes ?? [], "Intro de order bump");
              if (f.tipo === "seguimientos")
                return (f.seguimientos ?? []).flatMap((s) => deVersiones(s.variantes, `Seguimiento · ${minutosLegiblesDelTablero(s.minutos)}`));
              if (f.tipo === "condicion" && f.condicion?.tipo === "anuncio" && (f.condicion.anuncios ?? []).length > 0)
                return [{ piezaId: f.id, titulo: nombre, tipo: "Condición «¿vino de un anuncio?»", paises: paisesDeLaFicha, apagada: !!f.apagada, claves: f.condicion.anuncios ?? [], dirige: true }];
              return [];
            })}
            onAbrir={(fid) => {
              setVentanaDeHerramienta(null);
              const f = tablero.fichas.find((x) => x.id === fid);
              if (f?.tipo === "seguimientos" || f?.tipo === "intro_ob") setGestor(fid);
              else setAjustes(fid);
            }}
          />
          <div className="mt-4">
            <AdRegistryManager
              entries={cfg.ad_registry ?? []}
              palette={cfg.ad_color_palette ?? []}
              onPaletteChange={(ad_color_palette) => onConfigChange({ ...vivoCfg.current, ad_color_palette })}
              onChange={(ad_registry) => {
                // Lo MISMO que en la pizarra y en menú ajustes: quitar un anuncio quita su bloque del regalo, con aviso.
                const c = vivoCfg.current;
                const activeIds = new Set(ad_registry.flatMap((ad) => ad.ids));
                const removed = c.gift.variants.filter((variant) => variant.registry_ad_id && !activeIds.has(variant.registry_ad_id));
                if (
                  removed.some((variant) => variant.text.trim() || variant.ad_link?.trim() || variant.ads_reader_id) &&
                  !confirm("Al quitar este ID se borrara tambien su bloque configurado en Regalo. ¿Continuar?")
                )
                  return;
                onSnapshot();
                onConfigChange({ ...c, ad_registry, gift: syncGiftVariantsWithRegistry(c.gift, ad_registry) });
              }}
            />
          </div>
        </VentanaFlotante>
      )}
      {/* EXPORTAR / IMPORTAR, como en la pizarra (25/10/2026). El archivo lleva también el tablero. */}
      {ventanaDeHerramienta === "exportar" && tienda && (
        <VentanaFlotante titulo="⇅ Exportar / importar tienda" detalle="Un archivo JSON con la tienda entera, con su tablero." onCerrar={() => setVentanaDeHerramienta(null)} ancho="max-w-xl">
          <div className="space-y-4 text-sm text-tinta">
            <div>
              <button
                type="button"
                onClick={() => {
                  const datos = exportarTienda(vivoCfg.current, tienda.id);
                  if (!datos) return;
                  const blob = new Blob([JSON.stringify(datos, null, 2)], { type: "application/json" });
                  const a = document.createElement("a");
                  a.href = URL.createObjectURL(blob);
                  a.download = `tienda-${(tienda.nombre || tienda.id || "tienda").replace(/[^a-z0-9]+/gi, "-").toLowerCase()}.json`;
                  a.click();
                  setTimeout(() => URL.revokeObjectURL(a.href), 2000);
                }}
                className="rounded-md bg-emerald-600 px-3 py-2 text-sm font-semibold text-white hover:bg-emerald-700"
              >
                ⬇ Exportar «{tienda.nombre?.trim() || "esta tienda"}»
              </button>
              <p className="mt-1 text-xs text-tinta-suave">
                Lleva sus datos, sus productos (también los que usan los cobros y entregas del tablero), su pizarra y su tablero de cada canal.
              </p>
            </div>
            <div className="border-t border-borde pt-4">
              <label className="inline-block cursor-pointer rounded-md border border-borde bg-tarjeta px-3 py-2 text-sm font-semibold hover:bg-relleno">
                ⬆ Importar una tienda (JSON)
                <input
                  type="file"
                  accept="application/json,.json"
                  data-importar-tienda
                  className="hidden"
                  onChange={async (e) => {
                    const archivo = e.target.files?.[0];
                    e.target.value = "";
                    if (!archivo) return;
                    let datos: unknown;
                    try {
                      datos = JSON.parse(await archivo.text());
                    } catch {
                      setAvisoDelTablero("Ese archivo no es un JSON válido.");
                      return;
                    }
                    const r = importarTienda(vivoCfg.current, datos);
                    if ("error" in r) {
                      setAvisoDelTablero(r.error);
                      return;
                    }
                    onSnapshot();
                    onConfigChange(r.cfg);
                    setVentanaDeHerramienta(null);
                    setAvisoDelTablero(
                      `Tienda importada como nueva, sin número: búscala en Mis tiendas. Guarda para que quede.${r.avisos.length > 0 ? ` ${r.avisos.join(" ")}` : ""}`
                    );
                  }}
                />
              </label>
              <p className="mt-1 text-xs text-tinta-suave">
                Entra como una tienda NUEVA, sin número ni página, con su tablero apagado: nunca pisa una que ya exista.
              </p>
            </div>
            <div className="border-t border-borde pt-4">
              <label className="inline-block cursor-pointer rounded-md border border-sky-300 bg-sky-50 px-3 py-2 text-sm font-semibold text-sky-900 hover:bg-sky-100">
                ⬆ Traer sus fichas a este tablero (JSON)
                <input
                  type="file"
                  accept="application/json,.json"
                  data-importar-fichas
                  className="hidden"
                  onChange={async (e) => {
                    const archivo = e.target.files?.[0];
                    e.target.value = "";
                    if (!archivo) return;
                    let datos: unknown;
                    try {
                      datos = JSON.parse(await archivo.text());
                    } catch {
                      setAvisoDelTablero("Ese archivo no es un JSON válido.");
                      return;
                    }
                    traerAlTablero(fichasDeUnArchivo(vivoCfg.current, datos, canal));
                  }}
                />
              </label>
              <p className="mt-1 text-xs text-tinta-suave">
                Con el tablero vacío entra entero, con sus países y mantas. Si ya tienes fichas, aparecen a la derecha, sin conectar: lo tuyo no se
                toca. Si el archivo es de una tienda que trabajaste en la pizarra (por ejemplo, la de ALBERTO 5), se arma desde su pizarra.
              </p>
            </div>
            <div className="border-t border-borde pt-4">
              <button
                type="button"
                data-armar-desde-la-pizarra
                onClick={() => {
                  const datos = exportarTienda(vivoCfg.current, tienda.id);
                  if (!datos) return;
                  delete (datos as { tablero?: unknown }).tablero;
                  traerAlTablero(fichasDeUnArchivo(vivoCfg.current, datos, canal));
                }}
                className="rounded-md border border-violet-300 bg-violet-50 px-3 py-2 text-sm font-semibold text-violet-900 hover:bg-violet-100"
              >
                🔄 Armar desde la pizarra de esta tienda
              </button>
              <p className="mt-1 text-xs text-tinta-suave">
                Lee lo que esta tienda tiene en la pizarra (intros, oferta, upsells, seguimientos con sus anuncios) y lo arma aquí por país. La pizarra no
                cambia. Ctrl+Z lo deshace.
              </p>
            </div>
          </div>
        </VentanaFlotante>
      )}
      {avisoDelTablero && (
        <div className="fixed bottom-6 left-1/2 z-[60] max-w-xl -translate-x-1/2 rounded-lg border border-amber-300 bg-amber-50 px-3 py-2 text-xs font-semibold text-amber-950 shadow-lg" onClick={() => setAvisoDelTablero(null)}>
          {avisoDelTablero}
        </div>
      )}
      {fichaDeCajon && (
        <EnElTableroContext.Provider value={true}>
          <ProductosDeLaFichaContext.Provider value={productosParaElVisor(cfg, fichaDeCajon, paisVisto, tablero)}>
          <VentanaDelCajon
            key={fichaDeCajon.id}
            titulo={`${fichaDeCajon.tipo === "cobro" ? "💰" : fichaDeCajon.tipo === "correo" ? "📧" : "💬"} ${
              fichaDeCajon.titulo?.trim() || (fichaDeCajon.tipo === "cobro" ? "Cobro" : fichaDeCajon.tipo === "correo" ? "Pedir correo" : "Mensaje")
            }`}
            steps={(fichaDeCajon.steps ?? []) as EditorStep[]}
            idPrefix={`tablero_${fichaDeCajon.id.replace(/[^a-z0-9]/gi, "_")}`}
            cfgVista={configComoLaVeLaTienda(cfg, tienda, "lineal")}
            // EL PAÍS DE SU MANTA (25/10/2026), como el gestor y los ajustes: una intro de Ecuador
            // enseña sus precios en dólares aunque «Montos de» diga Perú.
            pais={paisDeSuManta(tablero, fichaDeCajon, paisVisto)}
            // Doble clic en una burbuja de la ficha: se abre en ESA burbuja, como en la pizarra.
            burbuja={burbujaDelCajon ?? undefined}
            onGuardar={(steps) => {
              cambiarFicha(fichaDeCajon.id, { steps });
              setCajon(null);
            }}
            onCerrar={() => setCajon(null)}
          />
          </ProductosDeLaFichaContext.Provider>
        </EnElTableroContext.Provider>
      )}
      {fichaDeGestor && (
        <EnElTableroContext.Provider value={true}>
          <ProductosDeLaFichaContext.Provider value={productosParaElVisor(cfg, fichaDeGestor, paisVisto, tablero)}>
          <GestorDeVersiones
            key={fichaDeGestor.id}
            ficha={fichaDeGestor}
            cfgVista={configComoLaVeLaTienda(cfg, tienda, "lineal")}
            pais={paisDeSuManta(tablero, fichaDeGestor, paisVisto)}
            onCambiar={(cambio) => cambiarFicha(fichaDeGestor.id, cambio)}
            onCerrar={() => setGestor(null)}
            onRegistroDeAnuncios={(ad_registry) => aplicar({ ...vivoCfg.current, ad_registry })}
          />
          </ProductosDeLaFichaContext.Provider>
        </EnElTableroContext.Provider>
      )}
      {fichaDeAjustes && (
        <AjustesDeLaFicha
          ficha={fichaDeAjustes}
          productos={productos.map((p) => ({ id: p.id, nombre: p.name?.trim() || p.id }))}
          entregasPorProducto={entregasPorProducto}
          anuncios={(cfg.ad_registry ?? []).map((a) => ({ id: a.key, nombre: a.name || a.key }))}
          workflows={workflows.filter((w) => w.id !== wfId)}
          paises={paises}
          paisInicial={paisDeSuManta(tablero, fichaDeAjustes, paisVisto)}
          onAbrirPagos={(p) => {
            setAjustes(null);
            setPaisDePagos(p);
            setVentanaDeHerramienta("pagos");
          }}
          onAbrirBurbujas={() => {
            setAjustes(null);
            if (fichaDeAjustes.tipo === "seguimientos" || fichaDeAjustes.tipo === "intro_ob") setGestor(fichaDeAjustes.id);
            else if (fichaDeAjustes.tipo === "regalo") setRegaloAbierto(fichaDeAjustes.id);
            else setCajon(fichaDeAjustes.id);
          }}
          onGuardar={(cambio) => {
            cambiarFicha(fichaDeAjustes.id, cambio);
            setAjustes(null);
          }}
          onCerrar={() => setAjustes(null)}
        />
      )}
    </div>
  );
}

/**
 * EL GESTOR FLOTANTE de la caja «Seguimientos» y de la «Intro de order bump», como los gestores
 * de la pizarra: a la izquierda la lista (seguimientos y sus versiones con peso), a la derecha el
 * cajón de burbujas de siempre, incrustado.
 */
function GestorDeVersiones({
  ficha,
  cfgVista,
  pais,
  onCambiar,
  onCerrar,
  onRegistroDeAnuncios,
}: {
  ficha: FichaEnElEditor;
  cfgVista: FullConfig;
  /** El país de su manta (el de la vista previa y el del título). "" = otros países. */
  pais: string;
  onCambiar: (cambio: Partial<FichaEnElEditor>) => void;
  onCerrar: () => void;
  /** Al crear un anuncio desde las etiquetas, como en la pizarra. */
  onRegistroDeAnuncios: (r: AdRegistryEntry[]) => void;
}) {
  // COMO EL GESTOR DE SEGUIMIENTOS DE LA PIZARRA (24/10/2026): «el cuadro es un desastre, no se
  // entiende… me gusta mucho como está hecho en modo pizarra». A la izquierda solo la lista; a la
  // derecha el elegido: su tiempo, sus casillas, sus versiones en pestañas y, debajo, sus burbujas con
  // las ETIQUETAS DE AD («aquí no veo las textareas para las etiquetas de los ads»).
  const esSeg = ficha.tipo === "seguimientos";
  type Version = VersionEnElEditor;
  type Seg = NonNullable<FichaEnElEditor["seguimientos"]>[number];
  // UN BORRADOR, como el cajón: lo de aquí se aplica a la ficha al ir cambiando.
  const [segs, setSegs] = useState<Seg[]>(() => JSON.parse(JSON.stringify(ficha.seguimientos ?? [])));
  const [versiones, setVersiones] = useState<Version[]>(() => JSON.parse(JSON.stringify(ficha.variantes ?? [])));
  const [elegida, setElegida] = useState<{ seg: number; ver: number }>({ seg: 0, ver: 0 });
  const nuevoId = (p: string) => `${p}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 5)}`;
  const vivo = useRef({ segs, versiones });
  vivo.current = { segs, versiones };
  const aplicar = (s: Seg[], v: Version[]) => onCambiar(esSeg ? { seguimientos: s } : { variantes: v });
  const ponerSegs = (s: Seg[]) => {
    setSegs(s);
    aplicar(s, vivo.current.versiones);
  };
  const ponerVersiones = (v: Version[]) => {
    setVersiones(v);
    aplicar(vivo.current.segs, v);
  };
  const s = esSeg ? segs[elegida.seg] : undefined;
  const lista: Version[] = esSeg ? s?.variantes ?? [] : versiones;
  const version = lista[elegida.ver];
  const ponerLista = (nueva: Version[]) =>
    esSeg ? ponerSegs(vivo.current.segs.map((x, i) => (i === elegida.seg ? { ...x, variantes: nueva } : x))) : ponerVersiones(nueva);
  const cambiarVersion = (cambio: Partial<Version>) => {
    const actual = esSeg ? vivo.current.segs[elegida.seg]?.variantes ?? [] : vivo.current.versiones;
    ponerLista(actual.map((v, j) => (j === elegida.ver ? { ...v, ...cambio } : v)));
  };
  const ponerSeg = (cambio: Partial<Seg>) => ponerSegs(vivo.current.segs.map((x, i) => (i === elegida.seg ? { ...x, ...cambio } : x)));
  const letra = (j: number) => String.fromCharCode(65 + j);
  const pesoTotal = lista.reduce((t, v) => t + (v.peso ?? 1), 0) || 1;
  const porcentaje = (v: Version) => Math.round((100 * (v.peso ?? 1)) / pesoTotal);
  const bandera = pais ? `${banderaDe(pais)} ${pais}` : "🌍 Otros países";
  const conAnuncio = (v: Version) => v.dirigir !== false && (v.anuncios ?? []).length > 0;
  // EL PRECIO DE OFERTA EN SU VISTA PREVIA (25/10/2026): desde el seguimiento que «activa el precio de
  // oferta» (ese mismo y los siguientes), el bot cobra el de oferta; la vista previa enseña ése.
  const productosDeLaFicha = useContext(ProductosDeLaFichaContext);
  const ofertaDesde = esSeg ? (() => {
    const i = segs.findIndex((x) => x.activa_oferta === true);
    return i >= 0 && i <= elegida.seg ? i : null;
  })() : null;
  const productosDeEsteSeguimiento =
    ofertaDesde !== null && productosDeLaFicha
      ? { ...productosDeLaFicha, productos: productosDeLaFicha.productos.map((p) => ({ ...p, precio: p.oferta ?? p.precio })) }
      : productosDeLaFicha;
  return (
    <VentanaFlotante
      titulo={esSeg ? `⏱ Seguimientos · ${bandera}` : `🎁 Intro de order bump · ${bandera}`}
      detalle={
        esSeg
          ? "Cada seguimiento sale a su tiempo desde el último mensaje del cliente (si escribe, vuelve a contar) y se detiene si paga. Respeta las 24 h, las horas de silencio, el lead tardío y la cola antirráfaga de Ajustes."
          : "Destapa el producto oculto. Antes de esta ficha la IA no sabe nada de él. Con varias versiones, el bot sortea por peso."
      }
      onCerrar={onCerrar}
      ancho={ANCHO_DEL_GESTOR}
    >
      <div data-ventana-del-tablero className="grid gap-4 md:grid-cols-[260px_minmax(0,1fr)]">
        <div className="flex flex-col gap-1.5">
          {esSeg ? (
            <>
              {segs.map((x, i) => (
                <div key={x.id} className="flex items-center gap-1">
                  <div className="min-w-0 flex-1">
                    <PasoDelGestor
                      n={String(i + 1)}
                      titulo={`Seguimiento ${i + 1}`}
                      detalle={`a los ${minutosLegiblesDelTablero(x.minutos)} · ${x.variantes.length} versión(es)`}
                      elegido={elegida.seg === i}
                      onElegir={() => setElegida({ seg: i, ver: 0 })}
                    />
                  </div>
                  <button
                    type="button"
                    title="Quitar este seguimiento"
                    className="rounded px-1.5 py-1 text-sm text-red-600 hover:bg-red-50"
                    onClick={() => {
                      if (!window.confirm(`¿Quitar el seguimiento ${i + 1}?`)) return;
                      ponerSegs(vivo.current.segs.filter((_, k) => k !== i));
                      setElegida({ seg: 0, ver: 0 });
                    }}
                  >
                    🗑
                  </button>
                </div>
              ))}
              <button
                type="button"
                className="mt-1 rounded-lg border border-dashed border-borde bg-tarjeta px-2 py-2 text-left text-xs font-semibold text-tinta hover:bg-relleno"
                onClick={() => {
                  const ultimo = vivo.current.segs[vivo.current.segs.length - 1]?.minutos ?? 0;
                  const nuevos = [...vivo.current.segs, { id: nuevoId("s"), minutos: ultimo ? ultimo + 120 : 180, variantes: [{ id: nuevoId("v"), peso: 1, steps: [] }] }];
                  ponerSegs(nuevos);
                  setElegida({ seg: nuevos.length - 1, ver: 0 });
                }}
              >
                + Agregar seguimiento
              </button>
              <p className="mt-1 text-[11px] text-tinta-suave">🗑 lo quita de esta caja. Salen en el orden de sus tiempos.</p>
            </>
          ) : (
            <>
              {versiones.map((v, j) => (
                <PasoDelGestor
                  key={v.id}
                  n={letra(j)}
                  titulo={`Versión ${letra(j)}`}
                  detalle={`${porcentaje(v)}% · ${((v.steps ?? []) as EditorStep[]).length} burbuja(s)${conAnuncio(v) ? " · 📣 con anuncio" : ""}`}
                  elegido={elegida.ver === j}
                  onElegir={() => setElegida({ seg: 0, ver: j })}
                  apagado={(v.peso ?? 1) === 0}
                />
              ))}
            </>
          )}
        </div>
        <div className="flex min-w-0 flex-col gap-3">
          {esSeg && s && (
            <>
              <div className="flex flex-wrap items-center gap-2 text-xs text-tinta">
                <h4 className="text-sm font-bold">
                  {elegida.seg + 1}. Seguimiento {elegida.seg + 1}
                </h4>
                {elegida.seg === 0 ? (
                  <>
                    · sale a los
                    <CampoDeTiempoDelTablero valor={s.minutos} onCambio={(m) => ponerSeg({ minutos: m ?? 60 })} />
                    del último mensaje del cliente (si escribe, vuelve a contar)
                    {s.minutos >= 24 * 60 - 7 && <span className="font-semibold text-rose-600">⚠ Pasa las 24 h: por WhatsApp no llegaría.</span>}
                  </>
                ) : (
                  // DEL 2 EN ADELANTE, A TUS HORARIOS FIJOS (25/10/2026, punto 4). Los minutos valen solo en el
                  // simulador, para poder probarlo sin esperar a la franja.
                  <>
                    · sale en tu <strong>horario fijo</strong> (Menús → Ajustes) · en el simulador, a los
                    <CampoDeTiempoDelTablero valor={s.minutos} onCambio={(m) => ponerSeg({ minutos: m ?? 60 })} />
                  </>
                )}
              </div>
              <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-tinta">
                <label className="flex items-center gap-1">
                  <input type="checkbox" checked={s.activa_oferta === true} onChange={(e) => ponerSeg({ activa_oferta: e.target.checked || undefined })} />
                  Activa el precio de oferta
                </label>
                <label className="flex items-center gap-1" title="Sale aunque caiga en las horas de silencio de Ajustes">
                  <input type="checkbox" checked={s.ignora_silencio === true} onChange={(e) => ponerSeg({ ignora_silencio: e.target.checked || undefined })} />
                  Ignora las horas de silencio
                </label>
                <label className="flex items-center gap-1" title="No se aplaza a la mañana aunque el cliente llegue tarde (Ajustes → lead tardío)">
                  <input type="checkbox" checked={s.ignora_tardio === true} onChange={(e) => ponerSeg({ ignora_tardio: e.target.checked || undefined })} />
                  Ignora el aplazamiento del lead tardío
                </label>
              </div>
            </>
          )}
          {lista.length > 1 && (
            <PestanasDelGestor
              opciones={lista.map((v, j) => ({ id: v.id, texto: `Versión ${letra(j)} · ${porcentaje(v)}%${conAnuncio(v) ? " · 📣" : ""}`, apagada: (v.peso ?? 1) === 0 }))}
              valor={version?.id ?? ""}
              onCambiar={(id) => setElegida({ ...elegida, ver: Math.max(0, lista.findIndex((v) => v.id === id)) })}
            />
          )}
          {version && (
            <div className="flex flex-wrap items-center gap-2 text-xs text-tinta">
              <button
                type="button"
                onClick={() => cambiarVersion({ peso: (version.peso ?? 1) === 0 ? 1 : 0 })}
                className={`rounded px-1.5 py-0.5 text-[11px] font-bold text-white ${(version.peso ?? 1) === 0 ? "bg-slate-400" : "bg-emerald-600"}`}
                title={(version.peso ?? 1) === 0 ? "Apagada: el bot no la manda. Clic para encenderla." : "Encendida. Clic para apagarla."}
              >
                {(version.peso ?? 1) === 0 ? "APAGADA" : "ENCENDIDA"}
              </button>
              {lista.length > 1 && (
                <label className="flex items-center gap-1">
                  Peso
                  <input
                    type="number"
                    min={0}
                    value={version.peso ?? 1}
                    onChange={(e) => cambiarVersion({ peso: Math.max(0, Math.floor(Number(e.target.value) || 0)) })}
                    className="w-14 rounded border border-borde bg-tarjeta px-1 py-0.5"
                  />
                </label>
              )}
              <button
                type="button"
                className="rounded border border-borde px-2 py-0.5 text-[11px] font-semibold hover:bg-relleno"
                title="Una copia de esta versión, aquí mismo"
                onClick={() => {
                  const copia = { ...JSON.parse(JSON.stringify(version)), id: nuevoId("v") } as Version;
                  const actual = esSeg ? vivo.current.segs[elegida.seg]?.variantes ?? [] : vivo.current.versiones;
                  ponerLista([...actual, copia]);
                  setElegida({ ...elegida, ver: actual.length });
                }}
              >
                ⧉ Duplicar versión
              </button>
              {lista.length > 1 && (
                <button
                  type="button"
                  className="rounded border border-red-200 px-2 py-0.5 text-[11px] font-semibold text-red-700 hover:bg-red-50"
                  onClick={() => {
                    const actual = esSeg ? vivo.current.segs[elegida.seg]?.variantes ?? [] : vivo.current.versiones;
                    ponerLista(actual.filter((_, j) => j !== elegida.ver));
                    setElegida({ ...elegida, ver: 0 });
                  }}
                >
                  🗑 Quitar versión
                </button>
              )}
            </div>
          )}
          {esSeg && ofertaDesde !== null && (
            <div className="rounded-md border border-emerald-300 bg-emerald-50 px-2 py-1 text-[11px] font-semibold text-emerald-900">
              💲 La vista previa enseña el PRECIO DE OFERTA: lo activa el seguimiento {ofertaDesde + 1}, y desde ahí el bot cobra ese.
            </div>
          )}
          {version ? (
            <ProductosDeLaFichaContext.Provider value={productosDeEsteSeguimiento}>
            <VentanaDelCajon
              key={`${elegida.seg}|${version.id}|${ofertaDesde ?? "-"}`}
              incrustado
              titulo={esSeg ? `Seguimiento ${elegida.seg + 1} · Versión ${letra(elegida.ver)}` : `Intro de order bump · Versión ${letra(elegida.ver)}`}
              steps={(version.steps ?? []) as EditorStep[]}
              idPrefix={`tablero_${ficha.id.replace(/[^a-z0-9]/gi, "_")}_${version.id.replace(/[^a-z0-9]/gi, "_")}`}
              cfgVista={cfgVista}
              pais={pais}
              anuncios={{
                claves: version.anuncios ?? [],
                dirigir: version.dirigir !== false,
                registro: cfgVista.ad_registry ?? [],
                alCambiarRegistro: onRegistroDeAnuncios,
              }}
              onGuardar={(steps, _nombre, anunciosNuevos) =>
                cambiarVersion({
                  steps,
                  ...(anunciosNuevos ? { anuncios: anunciosNuevos.claves, dirigir: anunciosNuevos.dirigir === false ? false : undefined } : {}),
                })
              }
              onCerrar={onCerrar}
            />
            </ProductosDeLaFichaContext.Provider>
          ) : (
            <div className="p-8 text-sm text-tinta-suave">{esSeg ? "Agrega un seguimiento a la izquierda." : "Esta ficha no tiene versiones."}</div>
          )}
          <button
            type="button"
            className="self-start rounded-md border border-dashed border-borde px-2.5 py-1 text-xs font-semibold text-tinta hover:bg-relleno"
            onClick={() => {
              const actual = esSeg ? vivo.current.segs[elegida.seg]?.variantes ?? [] : vivo.current.versiones;
              if (esSeg && !vivo.current.segs[elegida.seg]) return;
              ponerLista([...actual, { id: nuevoId("v"), peso: 1, steps: [] }]);
              setElegida({ ...elegida, ver: actual.length });
            }}
          >
            + Otra versión {esSeg ? "de este seguimiento" : ""}
          </button>
        </div>
      </div>
    </VentanaFlotante>
  );
}

/**
 * EL REGALO, EDITABLE DESDE EL TABLERO (24/10/2026): antes su ficha mandaba «a la pestaña Regalo».
 * Es el MISMO regalo de la tienda que edita la pizarra (`piezaEditable` «regalo» / «regalo-pedido» y
 * `conRegaloDeLaTienda`): si la tienda aún no tiene el suyo se ve el de todas, y al guardar pasa a ser
 * suyo; las demás tiendas no cambian.
 */
/**
 * «¿QUÉ REGALO?» (25/10/2026): el selector de arriba del gestor del regalo. Elige uno de los
 * regalos guardados (o el general), guarda el de ahora como uno nuevo, y renombra el elegido. Dice
 * qué tiendas lo usan: cambiarlo aquí lo cambia en todas ellas.
 */
function SelectorDeRegalo({ cfg, tiendaId, aplicar }: { cfg: FullConfig; tiendaId: string; aplicar: (c: FullConfig) => void }) {
  const tienda = (cfg.tiendas ?? []).find((t) => t.id === tiendaId);
  const lista = cfg.regalos_guardados ?? [];
  const elegido = tienda?.regalo_origen && lista.some((r) => r.id === tienda.regalo_origen) ? tienda.regalo_origen : "";
  const propio = !elegido && Object.keys(tienda?.regalo ?? {}).length > 0;
  const usan = elegido ? (cfg.tiendas ?? []).filter((t) => t.regalo_origen === elegido) : [];
  return (
    <div data-selector-de-regalo className="mb-3 flex flex-wrap items-center gap-2 rounded-lg border border-pink-200 bg-pink-50 px-3 py-2 text-xs text-tinta">
      <span className="font-bold text-pink-900">🎁 ¿Qué regalo?</span>
      <select
        value={elegido || (propio ? "__propio" : "")}
        onChange={(e) => {
          const v = e.target.value;
          if (v === "__propio") return;
          if (propio && !window.confirm("Esta tienda tiene un regalo propio sin guardar en la lista. Si eliges otro, se reemplaza. ¿Seguir?")) return;
          aplicar(conRegaloElegido(cfg, tiendaId, v));
        }}
        className="rounded-md border border-borde bg-tarjeta px-2 py-1 text-xs font-semibold"
      >
        <option value="">🌐 El regalo general del bot</option>
        {propio && <option value="__propio">✏️ Propio de esta tienda (sin guardar en la lista)</option>}
        {lista.map((r) => (
          <option key={r.id} value={r.id}>
            🎁 {r.nombre?.trim() || "Regalo sin nombre"}
          </option>
        ))}
      </select>
      <button
        type="button"
        onClick={() => {
          const nombre = window.prompt("Nombre para guardar este regalo en la lista", `Regalo de ${tienda?.nombre?.trim() || "la tienda"}`);
          if (nombre === null) return;
          aplicar(conRegaloGuardadoDeLaTienda(cfg, tiendaId, nombre));
        }}
        className="rounded-md border border-borde bg-tarjeta px-2 py-1 font-semibold hover:bg-relleno"
        title="Guarda el regalo que ves ahora como uno nuevo de la lista, para usarlo en otras tiendas"
      >
        💾 Guardar como regalo nuevo
      </button>
      {elegido && (
        <button
          type="button"
          onClick={() => {
            const r = lista.find((x) => x.id === elegido)!;
            const nombre = window.prompt("Nuevo nombre del regalo", r.nombre ?? "");
            if (nombre === null || !nombre.trim()) return;
            aplicar(conRegaloGuardado(cfg, { ...r, nombre: nombre.trim() }));
          }}
          className="rounded-md border border-borde bg-tarjeta px-2 py-1 font-semibold hover:bg-relleno"
        >
          ✏️ Renombrar
        </button>
      )}
      <span className="text-[11px] text-tinta-suave">
        {elegido
          ? `Lo usan: ${usan.map((t) => t.nombre?.trim() || t.id).join(", ")}. Lo que cambies aquí cambia en todas ellas.`
          : propio
            ? "Lo que cambies aquí es solo de esta tienda."
            : "Usa el general. Al cambiar algo aquí, esta tienda pasa a tener el suyo propio."}
      </span>
    </div>
  );
}

function GestorDelRegaloDelTablero({
  cfg,
  tiendaId,
  pais,
  aplicar,
  onCerrar,
}: {
  cfg: FullConfig;
  tiendaId: string;
  pais: string;
  aplicar: (c: FullConfig) => void;
  onCerrar: () => void;
}) {
  const vivo = useRef(cfg);
  vivo.current = cfg;
  const [paso, setPaso] = useState<"regalo" | "regalo-pedido" | "premio" | "no">("regalo");
  const tienda = (cfg.tiendas ?? []).find((t) => t.id === tiendaId);
  const suyo = tienda?.regalo ?? {};
  const pasos = [
    ["regalo", "Ofrecimiento del regalo", "La pregunta: «¿deseas recibir un regalito?»"],
    ["regalo-pedido", "Enlace para comentar", "Lo que recibe al aceptar: dónde comentar"],
    ["premio", "El premio", "Lo que recibe cuando ya comentó"],
    ["no", "Si dice que no", "La respuesta cuando no lo quiere"],
  ] as const;
  const cfgVista = configComoLaVeLaTienda(cfg, tienda, "lineal");
  return (
    <VentanaFlotante
      titulo={`🎁 Regalo de ${tienda?.nombre?.trim() || "esta tienda"}`}
      detalle={
        Object.keys(suyo).length > 0
          ? "Es el regalo propio de esta tienda. Las demás tiendas no cambian."
          : "Esta tienda usa el regalo de todas. Al guardar un cambio aquí, pasa a tener el suyo; las demás no cambian."
      }
      onCerrar={onCerrar}
      ancho={ANCHO_DEL_GESTOR}
    >
      <SelectorDeRegalo cfg={cfg} tiendaId={tiendaId} aplicar={aplicar} />
      {/* EL TIEMPO DEL REGALO, AQUÍ MISMO (26/10/2026): el mismo dato del menú ajustes («Espera del correo /
          regalo»), en minutos. Uno solo para todo el bot. */}
      <label className="mb-3 flex flex-wrap items-center gap-2 text-sm font-semibold text-tinta">
        ⏳ Se ofrece tras
        <input
          key={cfg.globals?.awaiting_email_timeout_seconds ?? 0}
          type="number"
          min={0}
          step={0.5}
          defaultValue={Math.round(((cfg.globals?.awaiting_email_timeout_seconds ?? 0) / 60) * 10) / 10}
          onBlur={(e) => {
            const seg = Math.max(0, Math.round((Number(e.target.value) || 0) * 60));
            const c = vivo.current;
            if (seg !== (c.globals?.awaiting_email_timeout_seconds ?? 0)) aplicar({ ...c, globals: { ...c.globals, awaiting_email_timeout_seconds: seg } });
          }}
          className="w-16 rounded border border-borde bg-tarjeta px-1 py-0.5 text-sm font-normal"
        />
        min de silencio
        <span className="w-full text-xs font-normal text-tinta-suave">
          Contado desde el último mensaje del cliente. Vale para todo el bot (todas las tiendas y países), y también es la espera de «⏳ Si no paga» y
          «⏳ Si no responde» cuando van al Regalo sin minutos propios.
        </span>
      </label>
      <div data-ventana-del-tablero className="grid gap-4 md:grid-cols-[260px_minmax(0,1fr)]">
        <div className="flex flex-col gap-1.5">
          {pasos.map(([id, titulo, detalle], i) => (
            <PasoDelGestor key={id} n={String(i + 1)} titulo={titulo} detalle={detalle} elegido={paso === id} onElegir={() => setPaso(id)} />
          ))}
          <p className="mt-1 text-[11px] text-tinta-suave">El enlace según el anuncio del cliente ({"{{ENLACE_ANUNCIO}}"}) sale del registro de anuncios, como siempre.</p>
        </div>
        <div className="min-w-0">
          {(paso === "regalo" || paso === "regalo-pedido") &&
            (() => {
              const pieza = piezaEditable(cfg, "whatsapp", paso, tiendaId);
              if (!pieza) return <p className="text-sm text-tinta-suave">Este paso todavía no tiene burbujas en el regalo de siempre (menú ajustes → Regalo).</p>;
              return (
                <VentanaDelCajon
                  key={paso}
                  incrustado
                  titulo={pieza.titulo}
                  steps={pieza.steps}
                  idPrefix={`tablero_regalo_${paso.replace(/[^a-z]/g, "_")}`}
                  cfgVista={cfgVista}
                  pais={pais}
                  onGuardar={(steps) => {
                    const p = piezaEditable(vivo.current, "whatsapp", paso, tiendaId);
                    if (p) aplicar(p.conPasos(steps));
                  }}
                  onCerrar={onCerrar}
                />
              );
            })()}
          {(paso === "premio" || paso === "no") && (
            <VentanaDeTexto
              key={paso}
              incrustado
              titulo={paso === "premio" ? "🎁 El premio (lo que recibe al comentar)" : "Si dice que no"}
              valor={(paso === "premio" ? suyo.reward_message ?? cfg.gift?.reward_message : suyo.decline_message ?? cfg.gift?.decline_message) ?? ""}
              cfgVista={cfgVista}
              onGuardar={(texto) =>
                aplicar(conRegaloDeLaTienda(vivo.current, tiendaId, paso === "premio" ? { reward_message: texto } : { decline_message: texto }))
              }
              onCerrar={onCerrar}
            />
          )}
        </div>
      </div>
    </VentanaFlotante>
  );
}

/**
 * LOS DATOS DE PAGO DESDE EL TABLERO (24/10/2026). El cobro con «Preguntar el método» manda, al
 * elegir un método, SUS respuestas de ese país (`pasosDelMetodo` en tablero/pago.ts): la capa de la
 * modalidad activa, o la base del país. Aquí se leen y se escriben en ese MISMO sitio, como lo hace
 * el editor principal (`selectedCountryProfile` / `setCountryProfile`); la lista de métodos es la del
 * país (sus botones), más lo escrito de un método que ya no está, para poder vaciarlo.
 */
function DatosDePagoDelTablero({
  cfg,
  pais,
  onConfigChange,
  onSnapshot,
}: {
  cfg: FullConfig;
  pais: CountryCode;
  onConfigChange: (c: FullConfig) => void;
  onSnapshot: () => void;
}) {
  const [parte, setParte] = useState<"respuestas" | "comodines">("respuestas");
  const mode = activeModality(cfg);
  const perfil = mergeCountryPaymentProfileForEditor(
    pais,
    cfg,
    cfg.modality_payment_profiles?.[mode]?.[pais] ?? cfg.payment_profiles_by_country?.[pais]
  );
  const escritas = perfil.payment_responses ?? {};
  const metodos: Array<[string, string, EditorStep[]]> = [
    ...(perfil.payment_buttons ?? []).map((b, i): [string, string, EditorStep[]] => {
      const m = b.method || `metodo_${i + 1}`;
      return [m, b.label || m, escritas[m] ?? []];
    }),
  ];
  for (const [m, pasos] of Object.entries(escritas)) {
    if (!metodos.some(([x]) => x === m) && (pasos ?? []).length > 0) metodos.push([m, m, pasos ?? []]);
  }
  const [elegido, setElegido] = useState(0);
  const actual = metodos[Math.min(elegido, metodos.length - 1)];
  const ponerPasos = (metodo: string, pasos: EditorStep[]) =>
    onConfigChange({
      ...cfg,
      country_sales_enabled: { ...(cfg.country_sales_enabled ?? {}), [pais]: perfil.enabled !== false },
      modality_payment_profiles: {
        ...cfg.modality_payment_profiles,
        [mode]: {
          ...cfg.modality_payment_profiles?.[mode],
          [pais]: { ...perfil, payment_responses: { ...escritas, [metodo]: pasos } },
        },
      },
    });
  return (
    <div className="space-y-3">
      <PestanasDelGestor
        opciones={[
          { id: "respuestas" as const, texto: "Al elegir cada método" },
          { id: "comodines" as const, texto: "Comodines {{METODO_DE_PAGO}}" },
        ]}
        valor={parte}
        onCambiar={setParte}
      />
      {parte === "comodines" && (
        <CountryPaymentProfilesEditor cfg={cfg} selectedCountry={pais} onChange={onConfigChange} onSnapshot={onSnapshot} onEdit={() => onSnapshot()} soloDatosDePago />
      )}
      {parte === "respuestas" && (
        <div className="grid gap-4 md:grid-cols-[220px_minmax(0,1fr)]">
          <div className="flex flex-col gap-1.5">
            {metodos.length === 0 && (
              <p className="text-xs text-tinta-suave">Este país no tiene métodos todavía (menú ajustes → Precios y pagos → Métodos de pago).</p>
            )}
            {metodos.map(([m, etiqueta, pasos], i) => (
              <PasoDelGestor
                key={m}
                n={String(i + 1)}
                titulo={etiqueta}
                detalle={pasos.length ? `${pasos.length} burbuja(s)` : "sin escribir: no manda nada"}
                elegido={actual?.[0] === m}
                onElegir={() => setElegido(i)}
              />
            ))}
            <p className="mt-1 text-[11px] text-tinta-suave">
              Es lo que el cobro manda cuando el cliente elige ese método. {"{{PRODUCTO}}"} es el producto de ese cobro, y el precio
              es el de lo que eligió (el de la vista previa es de ejemplo).
            </p>
          </div>
          {actual && (
            <div className="min-w-0">
              <StepEditorPreviewPair
                key={`${pais}_${actual[0]}`}
                steps={actual[2]}
                onChange={(pasos) => ponerPasos(actual[0], pasos)}
                onSnapshot={onSnapshot}
                onEdit={() => onSnapshot()}
                idPrefix={`tablero_pm_${pais}_${actual[0]}`}
                priceSoles={perfil.course_price_soles || 0}
                previewContext={previewContextFromConfig(cfg, pais)}
                className="lg:grid-cols-1 xl:grid-cols-[minmax(0,1fr)_minmax(220px,300px)]"
              />
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function minutosLegiblesDelTablero(m: number): string {
  if (m % 1440 === 0) return `${m / 1440} día${m === 1440 ? "" : "s"}`;
  if (m % 60 === 0) return `${m / 60} h`;
  return `${m} min`;
}

/** Un tiempo en minutos, escrito en minutos, horas o días. */
function CampoDeTiempoDelTablero({ valor, onCambio }: { valor: number | undefined; onCambio: (m: number | undefined) => void }) {
  const unidadInicial = !valor ? 60 : valor % 1440 === 0 ? 1440 : valor % 60 === 0 ? 60 : 1;
  const [unidad, setUnidad] = useState(unidadInicial);
  const cantidad = valor ? valor / unidad : "";
  return (
    <span className="inline-flex items-center gap-1">
      <input
        type="number"
        min={0}
        value={cantidad}
        onChange={(e) => {
          const n = Number(e.target.value);
          onCambio(Number.isFinite(n) && n > 0 ? Math.round(n * unidad) : undefined);
        }}
        className="w-16 rounded-md border border-borde bg-relleno px-2 py-1 text-sm"
      />
      <select
        value={unidad}
        onChange={(e) => {
          const u = Number(e.target.value);
          setUnidad(u);
          if (valor) onCambio(Math.round((valor / unidad) * u));
        }}
        className="rounded-md border border-borde bg-relleno px-1 py-1 text-sm"
      >
        <option value={1}>minutos</option>
        <option value={60}>horas</option>
        <option value={1440}>días</option>
      </select>
    </span>
  );
}

function ListaDeEleccion({
  todos,
  elegidos,
  onCambio,
}: {
  todos: Array<{ id: string; nombre: string }>;
  elegidos: string[];
  onCambio: (ids: string[]) => void;
}) {
  return (
    <div className="flex flex-wrap gap-1">
      {todos.map((x) => {
        const puesto = elegidos.includes(x.id);
        return (
          <button
            key={x.id}
            type="button"
            onClick={() => onCambio(puesto ? elegidos.filter((y) => y !== x.id) : [...elegidos, x.id])}
            className={`rounded-md border px-2 py-0.5 text-xs ${puesto ? "border-emerald-500 bg-emerald-50 font-bold" : "border-borde"}`}
          >
            {x.nombre}
          </button>
        );
      })}
    </div>
  );
}

function AjustesDeLaFicha({
  ficha,
  productos,
  entregasPorProducto = [],
  anuncios,
  workflows,
  paises,
  paisInicial,
  onAbrirBurbujas,
  onGuardar,
  onCerrar,
  onAbrirPagos,
}: {
  /** Abre «Datos de pago por país» en ese país (los textos que el cobro manda por método). */
  onAbrirPagos?: (pais: string) => void;
  ficha: FichaEnElEditor;
  productos: Array<{ id: string; nombre: string }>;
  /** Para la ficha Entregar: las entregas de cada producto, los de esta tienda primero (`propio`). */
  entregasPorProducto?: Array<{ id: string; nombre: string; propio: boolean; opciones: Array<{ clave: string; nombre: string }> }>;
  anuncios: Array<{ id: string; nombre: string }>;
  workflows: Array<{ id: string; nombre: string }>;
  paises: string[];
  paisInicial: string;
  onAbrirBurbujas: () => void;
  onGuardar: (cambio: Partial<FichaEnElEditor>) => void;
  onCerrar: () => void;
}) {
  const [b, setB] = useState<FichaEnElEditor>(ficha);
  // EL BUSCADOR DE «LO QUE SE ENTREGA» (27/10/2026): con muchos productos, la lista era eterna.
  const [buscarEntrega, setBuscarEntrega] = useState("");
  const [pais, setPais] = useState(paisInicial);
  const a = ASPECTO[ficha.tipo];
  const cobro = b.cobro ?? { modo: "abierto" as const };
  const tramos = cobro.tramos_por_pais?.[pais] ?? [];
  const ponCobro = (c: typeof cobro) => setB({ ...b, cobro: c });
  const ponTramos = (lista: typeof tramos) => ponCobro({ ...cobro, tramos_por_pais: { ...(cobro.tramos_por_pais ?? {}), [pais]: lista } });
  const etiqueta = "block text-xs font-semibold text-tinta";
  const ayuda = "mt-0.5 block text-[11px] font-normal text-tinta-suave";
  useEffect(() => {
    const alPulsar = (e: KeyboardEvent) => e.key === "Escape" && onCerrar();
    window.addEventListener("keydown", alPulsar);
    return () => window.removeEventListener("keydown", alPulsar);
  }, [onCerrar]);
  const selector = (valor: string | undefined, onCambio: (v: string | undefined) => void, lista: Array<{ id: string; nombre: string }>, vacio: string) => (
    <select value={valor ?? ""} onChange={(e) => onCambio(e.target.value || undefined)} className="mt-1 w-full rounded-md border border-borde bg-relleno px-2 py-1 text-sm font-normal">
      <option value="">{vacio}</option>
      {lista.map((p) => (
        <option key={p.id} value={p.id}>
          {p.nombre}
        </option>
      ))}
    </select>
  );
  return (
    <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/30 p-4" data-ventana-del-tablero onClick={onCerrar}>
      <div className="prolijo max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-2xl border border-borde bg-tarjeta p-5 text-tinta shadow-2xl" onClick={(e) => e.stopPropagation()}>
        <p className="text-sm font-black">
          {a.icono} {a.nombre}
        </p>
        <div className="mt-3 space-y-4">
          {ficha.tipo !== "inicio" && (
            <label className={etiqueta}>
              Nombre de la ficha
              <input value={b.titulo ?? ""} onChange={(e) => setB({ ...b, titulo: e.target.value })} placeholder={a.nombre} className="mt-1 w-full rounded-md border border-borde bg-relleno px-2 py-1 text-sm font-normal" />
            </label>
          )}
          {ficha.tipo === "inicio" && (
            <>
              <label className={etiqueta}>
                País de este Inicio
                <select value={b.pais ?? ""} onChange={(e) => setB({ ...b, pais: e.target.value || undefined })} className="mt-1 w-full rounded-md border border-borde bg-relleno px-2 py-1 text-sm font-normal">
                  <option value="">🌍 Otros países (los que no tienen su Inicio)</option>
                  {paises.map((p) => (
                    <option key={p} value={p}>
                      {p}
                    </option>
                  ))}
                </select>
                <span className={ayuda}>Por aquí entran los clientes NUEVOS de ese país. Tira un cable desde su punto naranja a la primera ficha.</span>
              </label>
            </>
          )}
          {(ficha.tipo === "mensaje" || ficha.tipo === "cobro" || ficha.tipo === "seguimientos" || ficha.tipo === "intro_ob" || ficha.tipo === "correo") && (
            <button type="button" onClick={onAbrirBurbujas} className="rounded-md border border-borde bg-relleno px-3 py-1.5 text-xs font-semibold hover:bg-tarjeta">
              ✏️ {ficha.tipo === "seguimientos" ? "Abrir sus seguimientos" : ficha.tipo === "intro_ob" ? "Abrir sus versiones" : "Escribir sus burbujas"}
            </button>
          )}
          {/* QUÉ PRODUCTO PRESENTA (23/10/2026): la IA solo habla de lo que ya se le presentó. */}
          {(ficha.tipo === "mensaje" || ficha.tipo === "intro_ob" || ficha.tipo === "seguimientos") && (
            <div className={etiqueta}>
              Presenta estos productos
              <span className="mt-1 block">
                <ListaDeEleccion todos={productos} elegidos={b.presenta ?? []} onCambio={(ids) => setB({ ...b, presenta: ids })} />
              </span>
              <span className={ayuda}>
                Desde que sale esta ficha, la IA conoce su contenido y su precio (de su ficha en Productos) y puede contestar «qué contiene» o «cuánto
                cuesta». Un producto que todavía no se presentó no existe para la IA: así el oculto sigue oculto hasta su intro.
              </span>
            </div>
          )}
          {/* «⏳ ESPERA ANTES DE SALIR» (25/10/2026, punto 9): el upsell no sale en el mismo segundo de la
              entrega. Vive aquí dentro; la tarjeta no muestra nada. */}
          {ficha.tipo === "mensaje" && (
            <div className={etiqueta}>
              ⏳ Espera antes de salir <span className="ml-2"><CampoDeTiempoDelTablero valor={b.espera_min} onCambio={(m) => setB({ ...b, espera_min: m })} /></span>
              <span className={ayuda}>
                Para el upsell después de la entrega: espera estos minutos antes de mandar sus burbujas. Si el cliente escribe mientras tanto, vuelve a
                contar. Vacío = sale enseguida.
              </span>
            </div>
          )}
          {(ficha.tipo === "mensaje" || ficha.tipo === "intro_ob" || ficha.tipo === "correo") && (
            <div className={etiqueta}>
              ⏰ Si no responde en <span className="ml-2"><CampoDeTiempoDelTablero valor={b.sin_respuesta_min} onCambio={(m) => setB({ ...b, sin_respuesta_min: m })} /></span>
              <span className={ayuda}>
                {ficha.tipo === "correo"
                  ? "Aparece la salida «No dio su correo», contada desde su último mensaje. Vacío = sin esa salida."
                  : "Con botones o cuadritos, la salida «⏳ Si no responde» siempre se ve. Aquí pones cuánto espera, contado desde su último mensaje; vacío = el silencio del regalo de tus Ajustes. Si tiene «⏳ Seguimientos» conectados, mandan ellos y esta salida no se usa (por eso no se ve)."}
              </span>
            </div>
          )}
          {ficha.tipo === "correo" && (
            <div className="space-y-2">
              <label className={etiqueta}>
                Asunto del correo
                <input
                  value={b.correo_asunto ?? ""}
                  onChange={(e) => setB({ ...b, correo_asunto: e.target.value })}
                  placeholder="Vacío = el nombre de lo que compró"
                  className="mt-1 w-full rounded-md border border-borde bg-relleno px-2 py-1 text-sm font-normal"
                />
              </label>
              <label className={etiqueta}>
                Texto del correo
                <textarea
                  value={b.correo_texto ?? ""}
                  onChange={(e) => setB({ ...b, correo_texto: e.target.value })}
                  rows={6}
                  className="mt-1 w-full rounded-md border border-borde bg-relleno px-2 py-1 text-sm font-normal"
                />
                <span className={ayuda}>
                  <strong>{"{{ENLACES}}"}</strong> = solo los enlaces de lo que compró, con el nombre de cada producto.{" "}
                  <strong>{"{{MATERIAL}}"}</strong> = el texto completo de su entrega, con sus enlaces. Sus burbujas piden el correo; cuando lo escribe, se
                  envía desde tu Gmail y sigue por «Correo enviado».
                </span>
              </label>
            </div>
          )}
          {ficha.tipo === "entregar" &&
            (() => {
              // LAS ENTREGAS DE LA FICHA (25/10/2026): una o varias, en orden, de uno o varios productos.
              // Se guarda la lista y, para lo de antes, el producto de la primera.
              const lista = b.entregas?.length ? b.entregas : b.producto_id ? [b.producto_id] : [""];
              // EL TÍTULO DICE LO QUE SE ENTREGA (29/10/2026, él: «el nombre de la ficha puede cambiarse pero no
              // garantiza qué producto se entrega»). Si la ficha se llama como la nombró el sistema («Entregar»,
              // «Entrega · <producto>»), al cambiar el producto se renombra sola: «Entrega · <el nuevo>». Un
              // nombre propio suyo no se toca.
              const productoDe = (clave?: string) => entregasPorProducto.find((g) => g.id === (clave ?? "").split("#")[0])?.nombre;
              const nombresDelSistema = new Set(["", "entregar", "entrega", ...entregasPorProducto.map((g) => `entrega · ${g.nombre}`.toLowerCase())]);
              const poner = (nueva: string[]) => {
                const limpias = nueva.filter(Boolean);
                const nuevo = productoDe(limpias[0]);
                const tituloAhora = (b.titulo ?? "").trim();
                const renombrar = nuevo && nombresDelSistema.has(tituloAhora.toLowerCase());
                setB({
                  ...b,
                  entregas: limpias.length ? nueva : undefined,
                  producto_id: limpias[0]?.split("#")[0] || undefined,
                  ...(renombrar ? { titulo: `Entrega · ${nuevo}` } : {}),
                });
              };
              const sinTildes = (s: string) => s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
              const q = sinTildes(buscarEntrega.trim());
              // Lo ya elegido siempre se ve (si no, el selector quedaría en blanco al buscar).
              const filtrar = (g: (typeof entregasPorProducto)[number]) => ({
                ...g,
                opciones: g.opciones.filter((o) => !q || lista.includes(o.clave) || sinTildes(`${g.nombre} ${o.nombre}`).includes(q)),
              });
              const propios = entregasPorProducto.filter((g) => g.propio).map(filtrar).filter((g) => g.opciones.length);
              const otros = entregasPorProducto.filter((g) => !g.propio).map(filtrar).filter((g) => g.opciones.length);
              return (
                <div className={etiqueta}>
                  Lo que se entrega
                  <span className={ayuda}>
                    Elige qué entrega de qué producto. Arriba, los productos de esta tienda; abajo, los demás. Las entregas extra (muestras, niveles…)
                    se escriben en la ficha del producto, en «📦 Entregas extra».
                  </span>
                  <input
                    id="buscar-entrega"
                    value={buscarEntrega}
                    onChange={(e) => setBuscarEntrega(e.target.value)}
                    placeholder="Buscar producto…"
                    className="mt-1 w-full rounded-md border border-borde bg-relleno px-2 py-1 text-sm font-normal"
                  />
                  <div className="mt-1 space-y-1">
                    {lista.map((clave, i) => (
                      <div key={i} className="flex items-center gap-1">
                        <select
                          value={clave}
                          onChange={(e) => poner(lista.map((x, j) => (j === i ? e.target.value : x)))}
                          className="w-full rounded-md border border-borde bg-relleno px-2 py-1 text-sm font-normal"
                        >
                          <option value="">(elige una entrega)</option>
                          {propios.map((g) => (
                            <optgroup key={g.id} label={`── ${g.nombre} ──`}>
                              {g.opciones.map((o) => (
                                <option key={o.clave} value={o.clave}>
                                  {/* El producto delante, también con el selector cerrado (29/10/2026). */}
                                  {`${g.nombre} · ${o.nombre}`}
                                </option>
                              ))}
                            </optgroup>
                          ))}
                          {otros.map((g) => (
                            <optgroup key={g.id} label={`Otros productos · ${g.nombre}`}>
                              {g.opciones.map((o) => (
                                <option key={o.clave} value={o.clave}>
                                  {`${g.nombre} · ${o.nombre}`}
                                </option>
                              ))}
                            </optgroup>
                          ))}
                        </select>
                        {lista.length > 1 && (
                          <button
                            type="button"
                            title="Quitar esta entrega"
                            onClick={() => poner(lista.filter((_, j) => j !== i))}
                            className="rounded px-1.5 text-sm text-tinta-suave hover:bg-red-100 hover:text-red-700"
                          >
                            ✕
                          </button>
                        )}
                      </div>
                    ))}
                  </div>
                  {lista.some(Boolean) && (
                    <button type="button" onClick={() => poner([...lista, ""])} className="mt-1 text-xs font-semibold text-sky-700 hover:underline">
                      + Agregar otra entrega
                    </button>
                  )}
                  <span className={ayuda}>Salen en este orden. Si dice «compra aprobada», no sirve para algo gratis: para eso usa una entrega extra.</span>
                </div>
              );
            })()}
          {/* «📧 OFRECER TAMBIÉN POR CORREO» (24/10/2026): sin borrador de correo; van los enlaces de su entrega. */}
          {ficha.tipo === "entregar" && (
            <div className="space-y-2">
              <label className="flex items-start gap-2 text-xs font-semibold">
                <input type="checkbox" checked={b.por_correo === true} onChange={(e) => setB({ ...b, por_correo: e.target.checked || undefined })} className="mt-0.5" />
                <span>
                  📧 Ofrecer también por correo
                  <span className={ayuda}>
                    Después de entregar pregunta con dos botones. Si elige correo, le pide su dirección (si ya la dio antes, se lo manda ahí) y le llegan los
                    enlaces de lo que compró, desde tu Gmail. No hay borrador que llenar. Apagado: no lo ofrece, pero si el cliente lo pide de palabra, se le
                    manda igual.
                  </span>
                </span>
              </label>
              {b.por_correo && (
                <div className="grid gap-2 rounded-md border border-borde bg-relleno p-2 text-[11px]">
                  <label>
                    La pregunta
                    <input value={b.correo_pregunta ?? ""} onChange={(e) => setB({ ...b, correo_pregunta: e.target.value })} placeholder="¿Te lo envío también a tu correo? 📧" className="mt-0.5 w-full rounded border border-borde bg-tarjeta px-2 py-1 text-xs" />
                  </label>
                  <div className="grid grid-cols-2 gap-2">
                    <label>
                      Botón sí
                      <input value={b.correo_si ?? ""} maxLength={20} onChange={(e) => setB({ ...b, correo_si: e.target.value })} placeholder="📧 Sí, por correo" className="mt-0.5 w-full rounded border border-borde bg-tarjeta px-2 py-1 text-xs" />
                    </label>
                    <label>
                      Botón no
                      <input value={b.correo_no ?? ""} maxLength={20} onChange={(e) => setB({ ...b, correo_no: e.target.value })} placeholder="Solo WhatsApp" className="mt-0.5 w-full rounded border border-borde bg-tarjeta px-2 py-1 text-xs" />
                    </label>
                  </div>
                  <label>
                    Cuando pide su dirección
                    <input value={b.correo_pide ?? ""} onChange={(e) => setB({ ...b, correo_pide: e.target.value })} placeholder="¡Claro! ¿A qué correo te lo envío? ✍️" className="mt-0.5 w-full rounded border border-borde bg-tarjeta px-2 py-1 text-xs" />
                  </label>
                  <span className="text-tinta-suave">Vacíos = los de fábrica (los que ves en gris).</span>
                </div>
              )}
            </div>
          )}
          {/* EL CEREBRO DE ESTA ETAPA (24/10/2026): opcional. */}
          {ficha.tipo !== "inicio" && ficha.tipo !== "condicion" && ficha.tipo !== "reparto" && ficha.tipo !== "esperar" && ficha.tipo !== "workflow" && (
            <label className={etiqueta}>
              🧠 Instrucciones para la IA aquí (opcional)
              <textarea
                value={b.instrucciones ?? ""}
                onChange={(e) => setB({ ...b, instrucciones: e.target.value || undefined })}
                rows={3}
                placeholder="Vacío = usa el cerebro general. Ej.: «Si duda, recuérdale que la entrega es inmediata.»"
                className="mt-1 w-full rounded-md border border-borde bg-relleno px-2 py-1 text-sm font-normal"
              />
              <span className={ayuda}>Solo vale mientras el cliente está en esta ficha, sumado al cerebro general. Una a tres líneas bastan.</span>
            </label>
          )}
          {ficha.tipo === "esperar" && (
            <div className={etiqueta}>
              Esperar <span className="ml-2"><CampoDeTiempoDelTablero valor={b.minutos} onCambio={(m) => setB({ ...b, minutos: m })} /></span>
              <span className={ayuda}>Y sigue por su cable. Respeta las horas de silencio. Si mientras tanto paga un cobro abierto, el pago manda.</span>
            </div>
          )}
          {ficha.tipo === "workflow" && (
            <label className={etiqueta}>
              Workflow al que lleva
              {selector(b.workflow_id, (v) => setB({ ...b, workflow_id: v }), workflows, workflows.length ? "(elige un workflow)" : "(no hay workflows: créalos en Mis tiendas)")}
              <span className={ayuda}>El cliente sigue en ese workflow desde su ▶ Inicio.</span>
            </label>
          )}
          {ficha.tipo === "reparto" && (
            <div className="space-y-2">
              <span className={etiqueta}>Rutas y su peso</span>
              {(b.reparto ?? []).map((o, i) => (
                <div key={o.id} className="flex items-center gap-2 text-xs">
                  <input
                    value={o.nombre ?? ""}
                    placeholder={`Ruta ${i + 1}`}
                    onChange={(e) => setB({ ...b, reparto: (b.reparto ?? []).map((x) => (x.id === o.id ? { ...x, nombre: e.target.value } : x)) })}
                    className="flex-1 rounded-md border border-borde bg-relleno px-2 py-1"
                  />
                  ⚖
                  <input
                    type="number"
                    min={0}
                    value={o.peso}
                    onChange={(e) => setB({ ...b, reparto: (b.reparto ?? []).map((x) => (x.id === o.id ? { ...x, peso: Math.max(0, Number(e.target.value) || 0) } : x)) })}
                    className="w-16 rounded-md border border-borde bg-relleno px-2 py-1"
                  />
                  <button type="button" className="text-rose-600" onClick={() => setB({ ...b, reparto: (b.reparto ?? []).filter((x) => x.id !== o.id) })}>
                    ✕
                  </button>
                </div>
              ))}
              <button
                type="button"
                onClick={() => setB({ ...b, reparto: [...(b.reparto ?? []), { id: `r${Date.now().toString(36)}`, peso: 1 }] })}
                className="rounded-md border border-borde bg-relleno px-2 py-1 text-xs font-semibold"
              >
                + Ruta
              </button>
              <span className={ayuda}>Cada cliente sale por una ruta al azar, según su peso. Sirve para probar dos intros o dos ofertas.</span>
            </div>
          )}
          {ficha.tipo === "condicion" && (
            <div className="space-y-2">
              <label className={etiqueta}>
                Pregunta
                <select
                  value={b.condicion?.tipo ?? "compro"}
                  onChange={(e) => setB({ ...b, condicion: { tipo: e.target.value as "compro" | "pais" | "anuncio" } })}
                  className="mt-1 w-full rounded-md border border-borde bg-relleno px-2 py-1 text-sm font-normal"
                >
                  <option value="compro">¿Ya compró un producto?</option>
                  <option value="pais">¿Es de estos países?</option>
                  <option value="anuncio">¿Vino de un anuncio?</option>
                </select>
              </label>
              {(b.condicion?.tipo ?? "compro") === "compro" && selector(b.condicion?.producto_id, (v) => setB({ ...b, condicion: { tipo: "compro", producto_id: v } }), productos, "(elige un producto)")}
              {b.condicion?.tipo === "pais" && (
                <ListaDeEleccion todos={paises.map((p) => ({ id: p, nombre: p }))} elegidos={b.condicion?.paises ?? []} onCambio={(ids) => setB({ ...b, condicion: { tipo: "pais", paises: ids } })} />
              )}
              {b.condicion?.tipo === "anuncio" && (
                <>
                  <ListaDeEleccion todos={anuncios} elegidos={b.condicion?.anuncios ?? []} onCambio={(ids) => setB({ ...b, condicion: { tipo: "anuncio", anuncios: ids } })} />
                  <span className={ayuda}>Sin elegir ninguno: cualquier anuncio. Los anuncios son los de tu registro (menú ajustes).</span>
                </>
              )}
              <span className={ayuda}>Salen dos cables: «Sí» y «No».</span>
            </div>
          )}
          {ficha.tipo === "cobro" && (
            <div className="space-y-3">
              <div className="flex gap-2 text-xs">
                {(["abierto", "producto"] as const).map((m) => (
                  <button key={m} type="button" onClick={() => ponCobro({ ...cobro, modo: m })} className={`rounded-md border px-3 py-1 font-semibold ${cobro.modo === m ? "border-amber-500 bg-amber-50" : "border-borde"}`}>
                    {m === "abierto" ? "Pago abierto (contribución)" : "Precio de un producto"}
                  </button>
                ))}
              </div>
              {cobro.modo === "producto" ? (
                <>
                  <label className={etiqueta}>
                    Producto que se cobra
                    {selector(cobro.producto_id, (v) => ponCobro({ ...cobro, producto_id: v }), productos, "(elige un producto)")}
                  </label>
                  <div className={etiqueta}>
                    También acepta
                    <span className="mt-1 block">
                      <ListaDeEleccion todos={productos.filter((p) => p.id !== cobro.producto_id)} elegidos={cobro.acepta ?? []} onCambio={(ids) => ponCobro({ ...cobro, acepta: ids })} />
                    </span>
                    <span className={ayuda}>
                      Como en la venta de siempre: si paga el precio de uno más caro de estos, se le entrega ese; si paga el de uno más barato, se le pregunta si fue un error o si lo prefiere. Cada uno sale por su cable.
                    </span>
                  </div>
                  <label className={etiqueta}>
                    Qué precio
                    <select value={cobro.precio ?? "etapa"} onChange={(e) => ponCobro({ ...cobro, precio: e.target.value as "normal" | "oferta" | "etapa" })} className="mt-1 w-full rounded-md border border-borde bg-relleno px-2 py-1 text-sm font-normal">
                      <option value="etapa">Según la etapa (el de oferta si ya salió un seguimiento que lo activa)</option>
                      <option value="normal">Siempre el normal</option>
                      <option value="oferta">Siempre el de oferta</option>
                    </select>
                    <span className={ayuda}>El precio de cada país. Se congela al abrir el cobro: si lo cambias después, a este cliente se le cobra lo que se le dijo.</span>
                  </label>
                  <label className="flex items-start gap-2 text-xs font-semibold">
                    <input type="checkbox" checked={cobro.metodos === true} onChange={(e) => ponCobro({ ...cobro, metodos: e.target.checked || undefined })} className="mt-0.5" />
                    <span>
                      💳 Preguntar el método y mandar sus datos solo
                      <span className={ayuda}>
                        Como la venta de siempre. Tus burbujas de aquí preguntan el método (y, si usas botones de métodos, salen los botones). Si ya lo eligió antes,
                        no se le pregunta: le llegan los datos de ese método. Los datos son los tuyos de «Métodos de pago» de su país, con el precio de lo que
                        eligió. Si dice otro método o «mejor el otro», le llegan los nuevos.
                      </span>
                    </span>
                  </label>
                  {cobro.metodos && (
                    <label className="ml-6 flex items-start gap-2 text-xs font-semibold">
                      <input type="checkbox" checked={cobro.sin_preguntar === true} onChange={(e) => ponCobro({ ...cobro, sin_preguntar: e.target.checked || undefined })} className="mt-0.5" />
                      <span>
                        🤫 No volver a preguntar el método al llegar
                        <span className={ayuda}>
                          Para cuando el mensaje de antes YA preguntó «¿con qué método pagas?». El cobro se abre en silencio: cuando el cliente dice el método
                          (o manda el comprobante), sigue igual que siempre. Así no le llega la misma pregunta dos veces.
                        </span>
                      </span>
                    </label>
                  )}
                  {onAbrirPagos && (
                    <button
                      type="button"
                      onClick={() => onAbrirPagos(pais)}
                      className="rounded-md border border-borde bg-relleno px-3 py-1.5 text-xs font-semibold hover:bg-tarjeta"
                    >
                      💳 Ver y editar los datos de pago de {banderaDe(pais)} {pais}
                    </button>
                  )}
                  <label className="flex items-start gap-2 text-xs font-semibold">
                    <input type="checkbox" checked={cobro.diferencia === true} onChange={(e) => ponCobro({ ...cobro, diferencia: e.target.checked || undefined })} className="mt-0.5" />
                    <span>
                      ⬆️ Upgrade: si ya compró uno más barato de esta lista, cobra solo la diferencia
                      <span className={ayuda}>
                        Por ejemplo, compró el básico y ahora quiere el full: se le cobra el full menos lo que ya pagó. Lo que ya tiene no se le vuelve a cobrar.
                      </span>
                    </span>
                  </label>
                </>
              ) : (
                <div className="space-y-2">
                  <label className="flex items-center gap-2 text-xs font-semibold">
                    País
                    <select value={pais} onChange={(e) => setPais(e.target.value)} className="rounded-md border border-borde bg-relleno px-1 py-0.5 text-xs">
                      {paises.map((p) => (
                        <option key={p} value={p}>
                          {p}
                        </option>
                      ))}
                    </select>
                    <span className="font-normal text-tinta-suave">cada país con sus montos y su moneda</span>
                  </label>
                  <label className="flex items-center gap-2 text-xs font-semibold">
                    Mínimo
                    <input
                      type="number"
                      min={0}
                      value={cobro.minimo_por_pais?.[pais] ?? ""}
                      onChange={(e) => {
                        const n = Number(e.target.value);
                        const resto = { ...(cobro.minimo_por_pais ?? {}) };
                        if (e.target.value === "" || !Number.isFinite(n)) delete resto[pais];
                        else resto[pais] = n;
                        ponCobro({ ...cobro, minimo_por_pais: resto });
                      }}
                      className="w-24 rounded-md border border-borde bg-relleno px-2 py-1 text-sm font-normal"
                    />
                    <span className="font-normal text-tinta-suave">por debajo → «Menos del mínimo»</span>
                  </label>
                  <div className="text-xs font-semibold">Tramos ({pais})</div>
                  {tramos.map((t, i) => (
                    <div key={t.id} className="flex items-center gap-2 text-xs">
                      <span className="w-14 font-semibold">Tramo {i + 1}</span>
                      desde
                      <input type="number" min={0} value={t.desde} onChange={(e) => ponTramos(tramos.map((x) => (x.id === t.id ? { ...x, desde: Number(e.target.value) || 0 } : x)))} className="w-20 rounded-md border border-borde bg-relleno px-2 py-1" />
                      hasta
                      <input
                        type="number"
                        min={0}
                        value={t.hasta ?? ""}
                        placeholder="sin tope"
                        onChange={(e) => ponTramos(tramos.map((x) => (x.id === t.id ? { ...x, hasta: e.target.value === "" ? undefined : Number(e.target.value) } : x)))}
                        className="w-20 rounded-md border border-borde bg-relleno px-2 py-1"
                      />
                      <button type="button" onClick={() => ponTramos(tramos.filter((x) => x.id !== t.id))} className="text-rose-600">
                        ✕
                      </button>
                    </div>
                  ))}
                  <button
                    type="button"
                    onClick={() => {
                      const n = tramos.length + 1;
                      const ultimo = tramos[tramos.length - 1];
                      ponTramos([...tramos, { id: `t${n}`, desde: ultimo ? (ultimo.hasta ?? ultimo.desde) + 1 : 0 }]);
                    }}
                    className="rounded-md border border-borde bg-relleno px-2 py-1 text-xs font-semibold"
                  >
                    + Agregar tramo
                  </button>
                  <span className={ayuda}>El tramo 1 de cada país sale por el mismo puntito «Tramo 1», cada uno con sus montos. Si paga en partes, se suman.</span>
                </div>
              )}
              {cobro.modo === "producto" && (
                <label className={etiqueta}>
                  Precio especial ({pais}) para el downsell
                  <input
                    type="number"
                    min={0}
                    value={cobro.precio_por_pais?.[pais] ?? ""}
                    placeholder="el de su ficha"
                    onChange={(e) => {
                      const n = Number(e.target.value);
                      const resto = { ...(cobro.precio_por_pais ?? {}) };
                      if (e.target.value === "" || !Number.isFinite(n) || n <= 0) delete resto[pais];
                      else resto[pais] = n;
                      ponCobro({ ...cobro, precio_por_pais: Object.keys(resto).length ? resto : undefined });
                    }}
                    className="ml-2 w-24 rounded-md border border-borde bg-relleno px-2 py-1 text-sm font-normal"
                  />
                  <span className={ayuda}>
                    Vacío = el precio de su ficha de producto. Pon un precio aquí para cobrar el mismo producto más barato (el downsell, si dijo que no
                    al upsell). Cada país con el suyo.
                  </span>
                </label>
              )}
              <span className={ayuda}>
                «⏳ Si no paga»: hacia tus Seguimientos, salen a sus tiempos; hacia otra ficha (el Regalo), tras el silencio del regalo. El cobro sigue
                abierto: si paga cuando sea, su monto lo lleva a su ruta.
              </span>
              <span className={ayuda}>Se revisa como en la venta de siempre: comprobante repetido, fecha (si el país la exige) y, en Yape/Plin, que esté a nombre de quien cobra.</span>
            </div>
          )}
          {ficha.tipo === "regalo" && (
            <div className="space-y-2">
              <button type="button" onClick={onAbrirBurbujas} className="rounded-md border border-borde bg-relleno px-3 py-1.5 text-xs font-semibold hover:bg-tarjeta">
                🎁 Editar el regalo de esta tienda
              </button>
              <p className="text-xs text-tinta-suave">
                Su pregunta, el enlace para comentar, el premio y la respuesta si dice que no. Es el regalo de esta tienda (el mismo que ves en la pizarra). Su salida «Al terminar el regalo» deja seguir la ruta después.
              </p>
            </div>
          )}
          {ficha.tipo === "humano" && <p className="text-xs text-tinta-suave">El bot deja de contestar a este cliente y te llega un aviso.</p>}
        </div>
        <div className="mt-5 flex justify-end gap-2">
          <button type="button" onClick={onCerrar} className="rounded-md border border-borde px-3 py-1.5 text-xs font-semibold">
            Cancelar
          </button>
          <button type="button" onClick={() => onGuardar(b)} className="rounded-md bg-emerald-600 px-3 py-1.5 text-xs font-bold text-white hover:bg-emerald-700">
            Listo
          </button>
        </div>
      </div>
    </div>
  );
}

function MisTiendas({
  cfg,
  onAbrir,
  onTablero,
  onWorkflow,
  onCambiar,
  onConfigChange,
  onSnapshot,
}: {
  cfg: FullConfig;
  onAbrir: (tiendaId: string) => void;
  /** Abre el tablero de la tienda (22/10/2026). */
  onTablero?: (tiendaId: string) => void;
  /** Abre un workflow en el tablero (23/10/2026). */
  onWorkflow?: (workflowId: string) => void;
  /** Un cambio de un solo paso (con su Ctrl+Z). */
  onCambiar: (c: FullConfig) => void;
  /** Un cambio sin paso propio: lo que se teclea en «Cambiar sus datos». */
  onConfigChange: (c: FullConfig) => void;
  onSnapshot: () => void;
}) {
  const tiendas = (cfg.tiendas ?? []).filter((t) => String(t?.id ?? "").trim());
  const almacen = cfg.biblioteca_de_productos ?? [];
  const [menuDe, setMenuDe] = useState<string | null>(null);
  const [datosDe, setDatosDe] = useState<string | null>(null);
  const [buscar, setBuscar] = useState("");
  // EL ESTADO REAL DE CADA NÚMERO (22/10/2026): «🟢 Activa» salía aunque su número estuviera pausado
  // o ni siquiera conectado aquí, y entonces nadie contestaba. Solo lee la base, nada de Meta.
  // null = todavía no se sabe (o falló): se muestra como siempre, sin inventar un estado.
  const [numeros, setNumeros] = useState<Array<{ id: string; telefono: string; pausado: boolean }> | null>(null);
  const leerNumeros = useCallback(() => {
    fetch("/api/negocio", { cache: "no-store" })
      .then((r) => (r.ok ? r.json() : null))
      .then((d: { lista?: Array<{ id: string; telefono: string; pausado: boolean }> } | null) => {
        if (Array.isArray(d?.lista)) setNumeros(d.lista);
      })
      .catch(() => undefined);
  }, []);
  useEffect(() => leerNumeros(), [leerNumeros]);
  const numeroDe = (t: TiendaEditor) => {
    const id = String(t.numero ?? "").trim();
    return id && numeros ? numeros.find((n) => n.id === id) ?? null : null;
  };
  /** Pausa o reanuda un número al instante (lo mismo que el botón de Meta Connect). */
  const pausar = async (id: string, pausado: boolean) => {
    try {
      const r = await fetch("/api/meta/connect/whatsapp/pausar", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ phoneNumberId: id, pausado }),
      });
      if (!r.ok) window.alert("No se pudo cambiar el número. Hazlo en Meta Connect → 6. Cuentas de WhatsApp.");
    } catch {
      window.alert("No se pudo cambiar el número. Hazlo en Meta Connect → 6. Cuentas de WhatsApp.");
    }
    leerNumeros();
  };
  useEffect(() => {
    if (!menuDe) return;
    const cerrar = (e: Event) => {
      if (e instanceof KeyboardEvent && e.key !== "Escape") return;
      if (e instanceof PointerEvent && (e.target as HTMLElement | null)?.closest?.("[data-menu-tienda]")) return;
      setMenuDe(null);
    };
    window.addEventListener("keydown", cerrar);
    window.addEventListener("pointerdown", cerrar);
    return () => {
      window.removeEventListener("keydown", cerrar);
      window.removeEventListener("pointerdown", cerrar);
    };
  }, [menuDe]);
  const SEMI: Record<string, string> = { "": "COMOHOY", dos_juntas: "COMO DOU", segunda_oculta: "COMO OB" };
  const productosDe = (t: TiendaEditor) =>
    [...new Set(Object.values(t.alineacion ?? {}).filter(Boolean))]
      .map((id) => almacen.find((p) => p?.id === id)?.name?.trim())
      .filter(Boolean)
      .join(" · ");
  const crear = () => {
    const id = `tienda_${Date.now().toString(36)}`;
    // La misma tienda vacía que crea «+ Agregar tienda» en menú ajustes → Tiendas.
    onCambiar({ ...cfg, tiendas: [...(cfg.tiendas ?? []), { id, nombre: "", numero: "", semimodalidad: "" }] });
    setDatosDe(id);
  };
  const visibles = tiendas.filter((t) => {
    const q = buscar.trim().toLowerCase();
    return !q || `${t.nombre ?? ""} ${productosDe(t)} ${t.numero ?? ""}`.toLowerCase().includes(q);
  });
  const enDatos = tiendas.find((t) => t.id === datosDe);
  return (
    // `prolijo`: la letra de Sendy, y su oscuro con la pizarra en 🌙 (globals.css).
    <div className="prolijo min-h-0 flex-1 overflow-y-auto bg-fondo p-6">
      <div className="mx-auto max-w-5xl">
        <div className="mb-4 flex flex-wrap items-center gap-3">
          <div>
            <h2 className="text-lg font-bold text-tinta">🏪 Mis tiendas</h2>
            <p className="text-xs text-tinta-suave">
              {tiendas.length} tienda(s). Doble clic en una para abrir su pizarra.
            </p>
          </div>
          <span className="ml-auto" />
          <input
            type="search"
            value={buscar}
            onChange={(e) => setBuscar(e.target.value)}
            placeholder="🔍 Buscar"
            className="w-48 rounded-md border border-borde bg-tarjeta px-2 py-1.5 text-xs text-tinta"
          />
          <button
            type="button"
            onClick={crear}
            className="rounded-md bg-emerald-600 px-3 py-1.5 text-xs font-bold text-white hover:bg-emerald-700"
          >
            + Crear tienda
          </button>
        </div>
        {tiendas.length === 0 && (
          <div className="rounded-xl border border-dashed border-borde bg-tarjeta p-8 text-center text-sm text-tinta-suave">
            Todavía no tienes tiendas. Pulsa «+ Crear tienda».
          </div>
        )}
        <div className="space-y-2">
          {visibles.map((t, i) => {
            const apagada = t.enabled === false;
            const sinNumero = !String(t.numero ?? "").trim();
            const cobrador = (cfg.cobradores ?? []).find((c) => c.id === t.cobrador);
            const frases = (t.frases_de_entrada ?? []).filter((f) => f.trim());
            // SIN PALABRA, LA SEGUNDA DE UN NÚMERO NO RECIBE A NADIE (22/10/2026). Si comparte número
            // con una tienda encendida que está ANTES en la lista y ninguna de las dos tiene palabra
            // activadora, el bot manda todos los clientes a esa otra (la misma regla que
            // `tiendaDelNumero`). Solo se avisa; nada se bloquea.
            const suNumero = String(t.numero ?? "").trim();
            const yo = tiendas.findIndex((x) => x.id === t.id);
            const leGana =
              !apagada && suNumero && frasesDeEntrada(t).length === 0
                ? tiendas
                    .slice(0, yo)
                    .find(
                      (x) =>
                        x.enabled !== false &&
                        String(x.numero ?? "").trim() === suNumero &&
                        frasesDeEntrada(x).length === 0
                    ) ?? null
                : null;
            return (
              <div
                key={t.id}
                onDoubleClick={() => onAbrir(t.id)}
                className={`relative flex cursor-pointer flex-wrap items-center gap-3 rounded-xl border border-borde bg-tarjeta px-4 py-3 shadow-sm hover:border-acento ${apagada ? "opacity-60" : ""}`}
                title="Doble clic para abrir su pizarra"
              >
                <div className="min-w-0 flex-1">
                  <div className="truncate text-sm font-bold text-tinta">🏪 {t.nombre?.trim() || `Tienda ${i + 1}`}</div>
                  <div className="truncate text-[11px] text-tinta-suave">
                    {productosDe(t) || "Sin productos"} · {SEMI[t.semimodalidad ?? ""] ?? "COMOHOY"}
                    {cobrador ? ` · cobra ${cobrador.nombre?.trim() || "su cobrador"}` : ""}
                    {frases.length > 0 ? ` · 🔑 ${frases.join(", ")}` : ""}
                  </div>
                  {leGana && (
                    <div className="mt-1 text-[11px] font-semibold text-red-700">
                      ⚠ Comparte número con «{leGana.nombre?.trim() || "otra tienda"}» y ninguna tiene palabra
                      activadora: todos sus clientes van a «{leGana.nombre?.trim() || "esa tienda"}». Ponle una
                      palabra a una de las dos (⋯ Más opciones → 🔑 Palabra activadora).
                    </div>
                  )}
                </div>
                {/* El teléfono, no el código interno de Meta (si este proyecto lo conoce). */}
                <span className="text-[11px] text-tinta-suave" title={sinNumero ? undefined : `ID en Meta: ${t.numero}`}>
                  📱 {sinNumero ? "sin número" : numeroDe(t)?.telefono ?? t.numero}
                </span>
                {(() => {
                  // EL ESTADO DE VERDAD: apagada, sin número, su número pausado, su número no
                  // conectado aquí, o activa. Mientras no se sabe del número, como siempre.
                  const n = numeroDe(t);
                  const noConectado = !apagada && !sinNumero && numeros !== null && !n;
                  const pausadoSuNumero = !apagada && !!n?.pausado;
                  const [clase, texto, ayuda] = apagada
                    ? ["bg-slate-200 text-slate-700", "⏸ Apagada", "No atiende. Su número contesta con tu contenido general (u otra tienda del mismo número), salvo que lo pauses."]
                    : sinNumero
                      ? ["bg-amber-100 text-amber-800", "Preparada", "Sin número todavía: nadie la elige por WhatsApp."]
                      : pausadoSuNumero
                        ? ["bg-amber-100 text-amber-800", "⏸ Su número está pausado", "Nadie le contesta. Reanúdalo en Meta Connect → 6. Cuentas de WhatsApp, o con «▶ Reanudar su número» en Más opciones."]
                        : noConectado
                          ? ["bg-red-100 text-red-800", "⚠ Su número no está conectado aquí", "Este proyecto no tiene ese número: sus clientes no llegan aquí. Conéctalo en Meta Connect."]
                          : ["bg-emerald-100 text-emerald-800", "🟢 Activa", "Atiende por su número."];
                  return (
                    <span className={`rounded-full px-2 py-0.5 text-[11px] font-semibold ${clase}`} title={ayuda}>
                      {texto}
                    </span>
                  );
                })()}
                <button
                  type="button"
                  onClick={() => onAbrir(t.id)}
                  className="rounded-md border border-borde bg-relleno px-3 py-1 text-xs font-semibold text-tinta hover:bg-tarjeta"
                >
                  ◈ Abrir pizarra
                </button>
                {onTablero &&
                  (() => {
                    // Encendido en algún canal: se dice en cuáles.
                    const enCanales = Object.entries(cfg.tableros?.[t.id] ?? {})
                      .filter(([, tb]) => tb?.encendido)
                      .map(([c]) => (c === "whatsapp" ? "🟢" : c === "messenger" ? "🔵" : "🟣"));
                    return (
                      <button
                        type="button"
                        onClick={() => onTablero(t.id)}
                        title={
                          enCanales.length
                            ? "Encendido en esos canales: sus clientes nuevos van por el tablero"
                            : "La ruta que tú armas con fichas y cables, y que el bot sigue"
                        }
                        className={`rounded-md border px-3 py-1 text-xs font-semibold hover:bg-tarjeta ${
                          enCanales.length ? "border-emerald-400 bg-emerald-50 text-emerald-800" : "border-borde bg-relleno text-tinta"
                        }`}
                      >
                        🧩 Tablero{enCanales.length ? ` ${enCanales.join("")}` : ""}
                      </button>
                    );
                  })()}
                <div className="relative" data-menu-tienda>
                  <button
                    type="button"
                    onClick={() => setMenuDe((m) => (m === t.id ? null : t.id))}
                    className="rounded-md border border-borde bg-relleno px-3 py-1 text-xs font-semibold text-tinta hover:bg-tarjeta"
                  >
                    ⋯ Más opciones
                  </button>
                  {menuDe === t.id && (
                    <div className="absolute right-0 top-8 z-30 w-60 overflow-hidden rounded-xl border border-borde bg-tarjeta py-1 text-sm text-tinta shadow-2xl">
                      <button
                        type="button"
                        onClick={() => {
                          setMenuDe(null);
                          setDatosDe(t.id);
                        }}
                        className="block w-full px-3 py-1.5 text-left hover:bg-relleno"
                      >
                        ✏️ Cambiar sus datos
                        <span className="block text-[10px] text-tinta-suave">Nombre, número, productos, cobrador, frases</span>
                      </button>
                      {/* ACCESO DIRECTO A LA PALABRA ACTIVADORA (22/10/2026). Abre la misma ventana de
                          datos y lleva el cursor a su casilla (`frases_de_entrada`): no es otro sitio. */}
                      <button
                        type="button"
                        onClick={() => {
                          setMenuDe(null);
                          setDatosDe(t.id);
                          const irALaCasilla = (intento: number) => {
                            const casilla = document.getElementById(`tienda_${t.id}_frases`) as HTMLInputElement | null;
                            if (casilla) {
                              casilla.scrollIntoView({ block: "center" });
                              casilla.focus();
                            } else if (intento < 20) {
                              window.setTimeout(() => irALaCasilla(intento + 1), 100);
                            }
                          };
                          irALaCasilla(0);
                        }}
                        className="block w-full px-3 py-1.5 text-left hover:bg-relleno"
                      >
                        🔑 Palabra activadora
                        <span className="block text-[10px] text-tinta-suave">
                          {frases.length > 0 ? `Hoy: ${frases.join(", ")}` : "Opcional: para varias tiendas en un número"}
                        </span>
                      </button>
                      <button
                        type="button"
                        onClick={() => {
                          setMenuDe(null);
                          const r = duplicarTienda(cfg, t.id);
                          if (r) onCambiar(r.cfg);
                        }}
                        className="block w-full px-3 py-1.5 text-left hover:bg-relleno"
                      >
                        ⧉ Duplicar
                        <span className="block text-[10px] text-tinta-suave">Una copia completa, sin número</span>
                      </button>
                      <button
                        type="button"
                        onClick={() => {
                          setMenuDe(null);
                          onCambiar({
                            ...cfg,
                            tiendas: (cfg.tiendas ?? []).map((x) => (x.id === t.id ? { ...x, enabled: apagada } : x)),
                          });
                          // APAGAR NO CALLABA EL NÚMERO (22/10/2026): decía «deja de atender» y su
                          // número seguía contestando con el contenido general. Ahora se le pregunta.
                          // Solo si ninguna otra tienda encendida usa ese número: si la hay, la atiende ella.
                          const n = numeroDe(t);
                          if (!n) return;
                          const otraLoUsa = (cfg.tiendas ?? []).some(
                            (x) => x.id !== t.id && x.enabled !== false && String(x.numero ?? "").trim() === n.id
                          );
                          if (otraLoUsa) return;
                          if (!apagada && !n.pausado) {
                            if (
                              window.confirm(
                                `¿Pausar también su número ${n.telefono}?\n\n` +
                                  `• Aceptar: nadie le contesta a ese número (ni los seguimientos pendientes).\n` +
                                  `• Cancelar: sus clientes pasan a tu contenido general.\n\n` +
                                  `La tienda se apaga al GUARDAR; el número se pausa YA.`
                              )
                            )
                              void pausar(n.id, true);
                          } else if (apagada && n.pausado) {
                            if (
                              window.confirm(
                                `¿Reanudar también su número ${n.telefono}?\n\nEstá pausado: sin reanudarlo, la tienda encendida no le contesta a nadie.\n\nLa tienda se enciende al GUARDAR; el número se reanuda YA.`
                              )
                            )
                              void pausar(n.id, false);
                          }
                        }}
                        className="block w-full px-3 py-1.5 text-left hover:bg-relleno"
                      >
                        {apagada ? "▶ Encender" : "⏸ Apagar"}
                        <span className="block text-[10px] text-tinta-suave">
                          {apagada
                            ? "Vuelve a atender en su número"
                            : "Deja de vender lo suyo. Te pregunta si pausar su número"}
                        </span>
                      </button>
                      {(() => {
                        // Reanudar o pausar su número desde aquí, sin ir a Meta Connect.
                        const n = numeroDe(t);
                        if (!n) return null;
                        return (
                          <button
                            type="button"
                            onClick={() => {
                              setMenuDe(null);
                              void pausar(n.id, !n.pausado);
                            }}
                            className="block w-full px-3 py-1.5 text-left hover:bg-relleno"
                          >
                            {n.pausado ? "▶ Reanudar su número" : "⏸ Pausar su número"}
                            <span className="block text-[10px] text-tinta-suave">
                              {n.pausado ? `${n.telefono} vuelve a contestar. Al instante` : `Nadie le contesta a ${n.telefono}. Al instante`}
                            </span>
                          </button>
                        );
                      })()}
                      <div className="my-1 border-t border-borde" />
                      <button
                        type="button"
                        onClick={() => {
                          setMenuDe(null);
                          if (
                            !window.confirm(
                              `¿Eliminar la tienda «${t.nombre?.trim() || `Tienda ${i + 1}`}»? Sus sub pestañas no se borran. Ctrl+Z la devuelve mientras no guardes.`
                            )
                          )
                            return;
                          onCambiar({ ...cfg, tiendas: (cfg.tiendas ?? []).filter((x) => x.id !== t.id) });
                        }}
                        className="block w-full px-3 py-1.5 text-left text-red-700 hover:bg-red-50"
                      >
                        🗑 Eliminar
                      </button>
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
        {/* MIS WORKFLOWS (23/10/2026): tuberías completas sin tienda. Arrancan cuando un botón o un
            cuadrito con «▶ Activar workflow», o una ficha «Ir a un workflow», las activa. */}
        {onWorkflow && (
          <div className="mt-8">
            <div className="mb-3 flex flex-wrap items-center gap-3">
              <div>
                <h2 className="text-lg font-bold text-tinta">▶▶ Mis workflows</h2>
                <p className="text-xs text-tinta-suave">
                  Tuberías completas que no son de ninguna tienda. Arrancan cuando un botón o cuadrito con «▶ Activar workflow» (o una ficha «Ir a un workflow») las activa.
                </p>
              </div>
              <span className="ml-auto" />
              <button
                type="button"
                onClick={() => {
                  const nombre = window.prompt("Nombre del workflow", "Nuevo workflow");
                  if (nombre === null) return;
                  const id = `wf_${Date.now().toString(36)}`;
                  onCambiar({
                    ...cfg,
                    workflows: {
                      ...(cfg.workflows ?? {}),
                      [id]: { encendido: true, nombre: nombre.trim().slice(0, 80) || "Nuevo workflow", fichas: [{ id: "inicio", tipo: "inicio", x: 0, y: 160 }], cables: [] },
                    },
                  });
                  onWorkflow(id);
                }}
                className="rounded-md bg-indigo-600 px-3 py-1.5 text-xs font-bold text-white hover:bg-indigo-700"
              >
                + Crear workflow
              </button>
            </div>
            {Object.keys(cfg.workflows ?? {}).length === 0 && (
              <div className="rounded-xl border border-dashed border-borde bg-tarjeta p-6 text-center text-sm text-tinta-suave">
                Todavía no tienes workflows.
              </div>
            )}
            <div className="space-y-2">
              {Object.entries(cfg.workflows ?? {}).map(([id, w]) => (
                <div
                  key={id}
                  onDoubleClick={() => onWorkflow(id)}
                  className="flex flex-wrap items-center gap-3 rounded-xl border border-borde bg-tarjeta px-4 py-3 shadow-sm"
                >
                  <span className="text-sm font-bold text-tinta">▶▶ {w.nombre?.trim() || "Workflow sin nombre"}</span>
                  <span className="text-[11px] text-tinta-suave">{w.fichas.filter((f) => f.tipo !== "inicio").length} ficha(s)</span>
                  <span className="ml-auto" />
                  <button type="button" onClick={() => onWorkflow(id)} className="rounded-md border border-borde bg-relleno px-3 py-1 text-xs font-semibold text-tinta hover:bg-tarjeta">
                    🧩 Abrir
                  </button>
                  <button
                    type="button"
                    onClick={() => {
                      const copia = JSON.parse(JSON.stringify(w)) as TableroEnElEditor;
                      onCambiar({ ...cfg, workflows: { ...(cfg.workflows ?? {}), [`wf_${Date.now().toString(36)}`]: { ...copia, nombre: `${w.nombre ?? "Workflow"} (copia)` } } });
                    }}
                    className="rounded-md border border-borde bg-relleno px-3 py-1 text-xs font-semibold text-tinta hover:bg-tarjeta"
                  >
                    ⧉ Duplicar
                  </button>
                  <button
                    type="button"
                    onClick={() => {
                      if (!window.confirm(`¿Eliminar el workflow «${w.nombre ?? id}»? Los botones que lo activan dejarán de hacer algo.`)) return;
                      const resto = { ...(cfg.workflows ?? {}) };
                      delete resto[id];
                      onCambiar({ ...cfg, workflows: resto });
                    }}
                    className="rounded-md border border-red-200 bg-tarjeta px-2 py-1 text-xs text-red-700"
                  >
                    🗑
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
      {/* CAMBIAR SUS DATOS: la MISMA ficha de menú ajustes → Tiendas, ya abierta en ésta. */}
      {enDatos && (
        <VentanaDeDatosDeTienda
          cfg={cfg}
          tienda={enDatos}
          onConfigChange={onConfigChange}
          onSnapshot={onSnapshot}
          onCerrar={() => setDatosDe(null)}
        />
      )}
    </div>
  );
}

function VentanaDeDatosDeTienda({
  cfg,
  tienda,
  onConfigChange,
  onSnapshot,
  onCerrar,
  alEditarProductos,
}: {
  cfg: FullConfig;
  tienda: TiendaEditor;
  onConfigChange: (c: FullConfig) => void;
  onSnapshot: () => void;
  onCerrar: () => void;
  /** «📦 Editar productos y precios», desde la pizarra (19/10/2026). */
  alEditarProductos?: () => void;
}) {
  /** La lista entera con ésta cambiada: lo de fuera de esta tienda no se toca. */
  const conEsta = (siguientes: TiendaEditor[]) =>
    (cfg.tiendas ?? []).flatMap((t) => (t.id === tienda.id ? siguientes : [t]));
  // SOLO SU VENTANA, sin otra alrededor: la de la casa ya trae su Cerrar, su Escape y su clic
  // fuera. La fila de la lista queda escondida (la ventana es `fixed`, así que se ve igual).
  return (
    <div className="h-0 overflow-hidden">
      <TiendasDelProyecto
        cfg={cfg}
        tiendas={[tienda]}
        abiertaAlInicio={tienda.id}
        alCerrarLaVentana={onCerrar}
        onTiendas={(siguientes) => onConfigChange({ ...cfg, tiendas: conEsta(siguientes) })}
        onSnapshot={onSnapshot}
        onReenganche={(siguientes) =>
          onConfigChange({ ...cfg, tiendas: conEsta(siguientes), globals: { ...cfg.globals, modo_reenganche: true } })
        }
        palette={cfg.ad_color_palette ?? []}
        onPalette={(ad_color_palette) => onConfigChange({ ...cfg, ad_color_palette })}
        alEditarProductos={alEditarProductos}
      />
    </div>
  );
}

/**
 * UN TEXTO SOLO, EN SU VENTANA (17/10/2026): «la pestaña de entrega de regalo no abre, ni la de
 * despedida». Esos dos se guardan como UN texto (`reward_message`, `decline_message`), no como
 * burbujas, así que no se abren en el editor de burbujas —ahí se podría poner una imagen que el
 * bot no mandaría—: se escriben aquí, con su vista previa.
 */
/** La vista previa con los productos de la ficha del tablero, si los hay. */
function conProductosDeLaFicha(ctx: PreviewContext, productos: ProductosDeLaFicha | null): PreviewContext {
  return productos?.productos.length ? { ...ctx, productosDeLaFicha: productos } : ctx;
}

/**
 * LOS PRODUCTOS QUE EL BOT USARÁ EN LOS COMODINES DE ESTA FICHA, con el precio del país visto: los del
 * cobro (el que cobra y los que acepta) o los que la ficha presenta. Mismo orden que el motor.
 */
/**
 * EL PAÍS DE SU MANTA: si la ficha solo está en la ruta de un Inicio con país, es de ahí (una ficha de
 * Ecuador se ve en dólares sin tocar «Montos de»). Si está en varias, o en ninguna, «Montos de».
 */
function paisDeSuManta(tablero: TableroEnElEditor, f: FichaEnElEditor, paisVisto: string): string {
  const paises = new Set<string>();
  for (const inicio of tablero.fichas.filter((x) => x.tipo === "inicio")) {
    const vistos = new Set([inicio.id]);
    const cola = [inicio.id];
    while (cola.length) {
      const id = cola.shift()!;
      for (const c of tablero.cables) if (c.de === id && !vistos.has(c.a)) (vistos.add(c.a), cola.push(c.a));
    }
    if (vistos.has(f.id)) paises.add(inicio.pais ?? "");
  }
  const [unico] = [...paises];
  return paises.size === 1 && unico ? unico : paisVisto;
}

function productosParaElVisor(
  cfg: FullConfig,
  f: FichaEnElEditor | undefined,
  paisVisto: string,
  tablero?: TableroEnElEditor
): ProductosDeLaFicha | null {
  if (!f) return null;
  const pais = tablero ? paisDeSuManta(tablero, f, paisVisto) : paisVisto;
  const ids = f.tipo === "cobro" ? [f.cobro?.producto_id, ...(f.cobro?.acepta ?? [])] : (f.presenta ?? []);
  // EL PRECIO QUE COBRARÁ EL BOT (25/10/2026): «¿en los visores se pueden ver los precios ya rebajados
  // según la etapa?». Un cobro «Siempre el de oferta» enseña el de oferta; los demás, el normal (y el
  // gestor de seguimientos lo cambia al de oferta desde el que lo activa, ver `GestorDeVersiones`).
  const deOferta = f.tipo === "cobro" && f.cobro?.precio === "oferta";
  const productos: ProductoConPrecio[] = [];
  for (const id of new Set(ids.filter((x): x is string => !!x))) {
    const p = (cfg.biblioteca_de_productos ?? []).find((x) => x.id === id);
    if (!p?.name) continue;
    const suyo = p.precios_por_pais?.[pais as CountryCode] as { price_soles?: number; market_price?: number; discount_price_soles?: number } | undefined;
    const normal = suyo?.price_soles ?? p.price_soles;
    const rebajado = suyo?.discount_price_soles ?? (p as { discount_price_soles?: number }).discount_price_soles;
    const oferta = typeof rebajado === "number" && rebajado > 0 ? rebajado : null;
    const precio = deOferta && oferta !== null ? oferta : normal;
    const antes = suyo?.market_price ?? (p as { market_price?: number }).market_price;
    productos.push({
      id,
      name: p.name,
      precio: typeof precio === "number" && precio > 0 ? precio : null,
      antes: typeof antes === "number" && antes > 0 ? antes : null,
      oferta,
    });
  }
  return productos.length ? { productos, pais } : null;
}

function VentanaDeTexto({
  titulo,
  valor,
  cfgVista,
  onGuardar,
  onCerrar,
  incrustado,
}: {
  titulo: string;
  valor: string;
  cfgVista: FullConfig;
  onGuardar: (texto: string) => void;
  onCerrar: () => void;
  /** Dentro de un gestor (19/10/2026): se aplica al irse, como `VentanaDelCajon`. */
  incrustado?: boolean;
}) {
  const productosFicha = useContext(ProductosDeLaFichaContext);
  const [texto, setTexto] = useState(valor);
  useEffect(() => {
    if (incrustado) return;
    const alPulsar = (e: KeyboardEvent) => {
      if (e.key === "Escape") onCerrar();
    };
    window.addEventListener("keydown", alPulsar);
    return () => window.removeEventListener("keydown", alPulsar);
  }, [onCerrar, incrustado]);
  const original = useRef(valor);
  const alIrse = useRef<() => void>(() => {});
  alIrse.current = () => {
    if (texto === original.current) return;
    onGuardar(texto);
    original.current = texto;
  };
  useEffect(() => {
    if (!incrustado) return;
    return () => alIrse.current();
  }, [incrustado]);
  if (incrustado) {
    return (
      <div className="flex flex-col gap-3">
        <div className="flex flex-wrap items-center gap-2">
          <h4 className="text-sm font-bold text-tinta">{titulo}</h4>
          {texto !== original.current && (
            <>
              <span className="text-[11px] font-semibold text-amber-700">● Cambios sin aplicar</span>
              <button type="button" onClick={() => setTexto(original.current)} className="rounded border border-borde px-2.5 py-1 text-xs font-semibold text-tinta-suave hover:bg-relleno">
                Descartar
              </button>
            </>
          )}
        </div>
        <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_minmax(260px,340px)]">
          <textarea
            value={texto}
            onChange={(e) => setTexto(e.target.value)}
            rows={10}
            className="w-full rounded-md border border-borde bg-tarjeta p-2 text-sm text-tinta focus:border-emerald-500 focus:outline-none"
          />
          <div>
            <p className="mb-1 text-[11px] font-medium text-tinta-suave">Así le llega al cliente</p>
            <ChatPreview
              steps={[textStep(texto)]}
              priceSoles={previewFullPriceFromConfig(cfgVista)}
              comboPrice={previewComboPriceFromConfig(cfgVista)}
              basicoPrice={previewBasicoPriceFromConfig(cfgVista)}
              previewContext={conProductosDeLaFicha(previewContextFromConfig(cfgVista), productosFicha)}
              highlightPlaceholders
            />
          </div>
        </div>
      </div>
    );
  }
  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-black/40 p-4" onClick={onCerrar}>
      <div className="my-8 w-full max-w-4xl rounded-lg border border-neutral-300 bg-tarjeta shadow-xl" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between gap-3 border-b border-neutral-200 px-4 py-3">
          <div>
            <h3 className="text-sm font-bold text-neutral-900">{titulo}</h3>
            <p className="text-xs text-neutral-500">Un solo mensaje de texto. Escape o Cancelar = descartar.</p>
          </div>
          <div className="flex items-center gap-2">
            <button type="button" onClick={onCerrar} className="rounded border border-neutral-300 px-3 py-1.5 text-xs font-semibold text-neutral-600 hover:bg-neutral-50">
              Cancelar
            </button>
            <button type="button" onClick={() => onGuardar(texto)} className="rounded bg-emerald-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-emerald-700">
              Listo
            </button>
          </div>
        </div>
        <div className="grid gap-4 p-4 lg:grid-cols-[minmax(0,1fr)_minmax(260px,340px)]">
          <textarea
            value={texto}
            onChange={(e) => setTexto(e.target.value)}
            rows={10}
            className="w-full rounded-md border border-neutral-300 p-2 text-sm text-neutral-900 focus:border-emerald-500 focus:outline-none"
          />
          <div>
            <p className="mb-1 text-[11px] font-medium text-neutral-500">Así le llega al cliente</p>
            <ChatPreview
              steps={[textStep(texto)]}
              priceSoles={previewFullPriceFromConfig(cfgVista)}
              comboPrice={previewComboPriceFromConfig(cfgVista)}
              basicoPrice={previewBasicoPriceFromConfig(cfgVista)}
              previewContext={conProductosDeLaFicha(previewContextFromConfig(cfgVista), productosFicha)}
              highlightPlaceholders
            />
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * QUIÉN COBRA DE VERDAD EN ESE PAÍS (17/10/2026): «que en esa ventanita flotante diga quién va a
 * cobrar». Es la misma cuenta que el bot le manda al cliente (`elCobroDelPais` en config.ts),
 * leída igual: la del cobrador de la tienda en ese país; si no tiene, la del país. Solo enseña.
 */
function QuienCobraEnElPais({ cfg, tienda, pais }: { cfg: FullConfig; tienda: TiendaEditor; pais: string }) {
  const { nombre, titular, cuenta, porMetodo, cobrador, deQuien } = quienCobraEn(cfg, tienda, pais);
  return (
    <div className="rounded-lg border-2 border-emerald-300 bg-emerald-50 p-3 text-sm text-neutral-900">
      <div className="font-bold">
        {banderaDe(pais)} En {pais} cobra: {nombre || "(sin nombre)"}
      </div>
      <div className="mt-1 grid gap-0.5 text-xs">
        <div>
          Titular que valida el comprobante: <b>{titular || "—"}</b>
        </div>
        {porMetodo.length > 0 ? (
          porMetodo.map((x) => (
            <div key={x.metodo}>
              {x.metodo}: <b>{x.cuenta || "—"}</b>
            </div>
          ))
        ) : (
          <div>
            Cuenta: <b>{cuenta || "—"}</b>
          </div>
        )}
        <div className="text-neutral-600">
          {deQuien
            ? `Son los datos de ${deQuien} para ${pais}.`
            : cobrador
              ? `${cobrador.nombre?.trim() || "El cobrador de la tienda"} no tiene cuenta en ${banderaDe(pais)} ${pais}: cobra la cuenta del país.`
              : `Esta tienda no tiene cobrador: cobra la cuenta del país.`}
        </div>
      </div>
    </div>
  );
}

/** Quién cobra en ese país, leído como el bot (`elCobroDelPais`). Lo usan la ventana y la tarjeta. */
function quienCobraEn(cfg: FullConfig, tienda: Pick<TiendaEditor, "cobrador"> | null | undefined, pais: string) {
  const limpio = (v: unknown) => String(v ?? "").trim();
  const k = pais as CountryCode;
  const perfil = cfg.modality_payment_profiles?.[activeModality(cfg)]?.[k] ?? cfg.payment_profiles_by_country?.[k];
  const idDelCobrador = limpio(tienda?.cobrador);
  const cobrador = idDelCobrador ? (cfg.cobradores ?? []).find((c) => limpio(c.id) === idDelCobrador) : undefined;
  const suyo = cobrador?.por_pais?.[k] as
    | { titular?: string; nombre_completo?: string; numero_de_cuenta?: string; cuentas_por_metodo?: Record<string, string>; metodos_apagados?: string[] }
    | undefined;
  const delPais = perfil as
    | { nombre_completo?: string; numero_de_cuenta?: string; cuentas_por_metodo?: Record<string, string>; payment_validation?: { yape_recipient_name_starts_with?: string } }
    | undefined;
  const titularSuyo = limpio(suyo?.titular);
  const titular =
    titularSuyo ||
    limpio(delPais?.payment_validation?.yape_recipient_name_starts_with) ||
    limpio((cfg as { payment_validation?: { yape_recipient_name_starts_with?: string } }).payment_validation?.yape_recipient_name_starts_with);
  const nombre = titularSuyo
    ? limpio(suyo?.nombre_completo) || titularSuyo
    : limpio(suyo?.nombre_completo) || limpio(delPais?.nombre_completo) || titular;
  const cuenta = limpio(suyo?.numero_de_cuenta) || limpio(delPais?.numero_de_cuenta);
  const apagados = new Set((suyo?.metodos_apagados ?? []).map((m) => limpio(m).toLowerCase()));
  const porMetodo = Object.entries({ ...(delPais?.cuentas_por_metodo ?? {}), ...(suyo?.cuentas_por_metodo ?? {}) })
    .filter(([m, v]) => limpio(v) && !apagados.has(limpio(m).toLowerCase()))
    .map(([m, v]) => {
      const deEl = limpio(suyo?.cuentas_por_metodo?.[m]);
      return { metodo: m, cuenta: deEl || limpio(suyo?.numero_de_cuenta) || limpio(v) };
    });
  const deQuien = cobrador && suyo ? cobrador.nombre?.trim() || "su cobrador" : null;
  return { nombre, titular, cuenta, porMetodo, cobrador, deQuien };
}

function VentanaDelCobro({
  cfg,
  tienda,
  pais,
  onCobrador,
  onCobradores,
  onSnapshot,
  onCerrar,
  incrustado,
}: {
  cfg: FullConfig;
  tienda: TiendaEditor;
  /** El país del camino desde el que se abrió: arriba, quién cobra ahí. */
  pais?: string;
  onCobrador: (id: string) => void;
  onCobradores: (siguientes: CobradorEditor[]) => void;
  onSnapshot: () => void;
  onCerrar: () => void;
  /** Dentro de un gestor (19/10/2026): sin ventana encima. Lo de aquí se aplica al momento. */
  incrustado?: boolean;
}) {
  useEffect(() => {
    if (incrustado) return;
    const alPulsar = (e: KeyboardEvent) => {
      if (e.key === "Escape") onCerrar();
    };
    window.addEventListener("keydown", alPulsar);
    return () => window.removeEventListener("keydown", alPulsar);
  }, [onCerrar, incrustado]);
  const cobradores = cfg.cobradores ?? [];
  const cuerpo = (
    <div className="space-y-4">
      {pais && <QuienCobraEnElPais cfg={cfg} tienda={tienda} pais={pais} />}
      <label className="block text-xs font-semibold text-tinta">
        Quién cobra en esta tienda
        <select
          value={tienda.cobrador ?? ""}
          onChange={(e) => onCobrador(e.target.value)}
          className="mt-1 block w-full max-w-sm rounded-md border border-borde bg-tarjeta px-2 py-1.5 text-sm"
        >
          <option value="">Nadie: las cuentas de cada país</option>
          {cobradores.map((c, j) => (
            <option key={c.id} value={c.id}>
              {c.nombre?.trim() || `Usuario ${j + 1}`}
            </option>
          ))}
        </select>
      </label>
      <CobradoresDelProyecto cfg={cfg} cobradores={cobradores} tiendas={cfg.tiendas ?? []} onCobradores={onCobradores} onSnapshot={onSnapshot} />
    </div>
  );
  if (incrustado) return cuerpo;
  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-black/40 p-4" onClick={onCerrar}>
      <div className="my-8 w-full max-w-4xl rounded-lg border border-neutral-300 bg-tarjeta shadow-xl" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between gap-3 border-b border-neutral-200 px-4 py-3">
          <div>
            <h3 className="text-sm font-bold text-neutral-900">💳 El cobro de {tienda.nombre?.trim() || "esta tienda"}</h3>
            <p className="text-xs text-neutral-500">El precio sale de la ficha del producto, por país. Aquí, a qué cuentas paga.</p>
          </div>
          <button type="button" onClick={onCerrar} className="rounded bg-emerald-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-emerald-700">
            Listo
          </button>
        </div>
        <div className="space-y-4 p-4">
          {pais && <QuienCobraEnElPais cfg={cfg} tienda={tienda} pais={pais} />}
          <label className="block text-xs font-semibold text-neutral-700">
            Quién cobra en esta tienda
            <select
              value={tienda.cobrador ?? ""}
              onChange={(e) => onCobrador(e.target.value)}
              className="mt-1 block w-full max-w-sm rounded-md border border-neutral-300 bg-tarjeta px-2 py-1.5 text-sm"
            >
              <option value="">Nadie: las cuentas de cada país</option>
              {cobradores.map((c, j) => (
                <option key={c.id} value={c.id}>
                  {c.nombre?.trim() || `Usuario ${j + 1}`}
                </option>
              ))}
            </select>
          </label>
          <CobradoresDelProyecto
            cfg={cfg}
            cobradores={cobradores}
            tiendas={cfg.tiendas ?? []}
            onCobradores={onCobradores}
            onSnapshot={onSnapshot}
          />
        </div>
      </div>
    </div>
  );
}

/**
 * EL CAJÓN ENTERO EN UNA VENTANA (16/10/2026): «al dar doble clic sobre su franja de arriba se
 * abra todo el cajón… no quiero que se abra solo una burbuja sino todo, como cuando yo abro un
 * pop up de intro completa, seguimiento completo». Es el mismo editor de burbujas de siempre
 * (`StepList`), con sus botones y cuadritos, sobre un BORRADOR: «Listo» lo aplica, Escape lo
 * descarta. Las apagadas SÍ salen aquí: es donde se encienden.
 */
function VentanaDelCajon({
  titulo,
  nombre,
  steps,
  idPrefix,
  cfgVista,
  burbuja,
  pais,
  seguimiento,
  anuncios,
  onGuardar,
  onCerrar,
  incrustado,
}: {
  /** DENTRO DE UN GESTOR (19/10/2026), como Sendy: sin ventana encima. Lo editado se aplica solo
   *  al cambiar de paso o cerrar el gestor; «Descartar» lo deja como estaba. */
  incrustado?: boolean;
  /** SUS ANUNCIOS, ARRIBA, COMO EN CANALES (17/10/2026): «mejor las etiquetas del ad que queden
   *  de manera interna en la ficha… igualito con su on off». Solo en intros y seguimientos, que
   *  son las que el bot dirige por anuncio. Se guardan con «Listo», con lo demás. */
  anuncios?: {
    claves: string[];
    dirigir: boolean;
    registro: AdRegistryEntry[];
    alCambiarRegistro: (r: AdRegistryEntry[]) => void;
    /** Los que ya usa la tienda: sus campañas, primero en la lista. */
    deLaTienda?: string[];
  };
  titulo: string;
  /** Si es una ficha de seguimiento, cuál (0 = el 1): la vista previa usa el precio de su etapa. */
  seguimiento?: number;
  /** El país del camino desde el que se abrió: la vista previa enseña sus precios. */
  pais?: string;
  /** Su nombre, si se puede cambiar desde aquí. Sin él, la cabecera es solo el título. */
  nombre?: string;
  steps: EditorStep[];
  idPrefix: string;
  /** La configuración como la ve la tienda: precios y comodines del visor. */
  cfgVista: FullConfig;
  /** La burbuja que se quiere ver al abrir (la del botón o cuadrito que se tocó). */
  burbuja?: number;
  onGuardar: (steps: EditorStep[], nombre?: string, anuncios?: { claves: string[]; dirigir: boolean }) => void;
  onCerrar: () => void;
}) {
  const productosFicha = useContext(ProductosDeLaFichaContext);
  const [borrador, setBorradorDirecto] = useState<EditorStep[]>(steps);
  /**
   * CTRL+Z DENTRO DE LA VENTANA (19/10/2026): «acabo de mover una burbuja manualmente en el visor,
   * pero al darle Cmd o Ctrl+Z no la regresa a su lugar». Lo de esta ventana es un borrador: el
   * Ctrl+Z del editor no lo veía (y deshacía algo de la pizarra, debajo). Ahora tiene el suyo.
   */
  const historial = useRef<{ atras: EditorStep[][]; adelante: EditorStep[][] }>({ atras: [], adelante: [] });
  const incrustadoVivo = useRef(incrustado);
  incrustadoVivo.current = incrustado;
  const borradorVivo = useRef(borrador);
  borradorVivo.current = borrador;
  const setBorrador = (siguiente: EditorStep[]) => {
    historial.current.atras = [...historial.current.atras.slice(-60), borradorVivo.current];
    historial.current.adelante = [];
    setBorradorDirecto(siguiente);
  };
  useEffect(() => {
    const alTeclear = (e: KeyboardEvent) => {
      if (!(e.ctrlKey || e.metaKey)) return;
      const tecla = e.key.toLowerCase();
      const rehacer = (tecla === "z" && e.shiftKey) || tecla === "y";
      if (tecla !== "z" && tecla !== "y") return;
      // En un campo de texto, el deshacer del propio campo (letras).
      const el = document.activeElement as HTMLElement | null;
      if (el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA" || el.isContentEditable)) return;
      const h = historial.current;
      // DENTRO DE UN GESTOR, SIN NADA PROPIO QUE DESHACER, el Ctrl+Z es de la pizarra (19/10/2026:
      // «creo un seguimiento y al presionar Ctrl+Z no desaparece»). En la ventana suelta se queda
      // aquí siempre, como antes: debajo está la pizarra y no debe deshacerse a ciegas.
      if (incrustadoVivo.current && (rehacer ? h.adelante.length === 0 : h.atras.length === 0)) return;
      e.preventDefault();
      e.stopImmediatePropagation();
      if (rehacer) {
        const siguiente = h.adelante.pop();
        if (!siguiente) return;
        h.atras.push(borradorVivo.current);
        setBorradorDirecto(siguiente);
      } else {
        const anterior = h.atras.pop();
        if (!anterior) return;
        h.adelante.push(borradorVivo.current);
        setBorradorDirecto(anterior);
      }
    };
    // En captura: antes que el Ctrl+Z del editor, que deshacía la pizarra de debajo.
    window.addEventListener("keydown", alTeclear, true);
    return () => window.removeEventListener("keydown", alTeclear, true);
  }, []);
  const [nuevoNombre, setNuevoNombre] = useState(nombre ?? "");
  const [susAnuncios, setSusAnuncios] = useState(anuncios ? { claves: anuncios.claves, dirigir: anuncios.dirigir } : null);
  useEffect(() => {
    if (incrustado) return;
    const alPulsar = (evento: KeyboardEvent) => {
      if (evento.key !== "Escape") return;
      evento.preventDefault();
      onCerrar();
    };
    window.addEventListener("keydown", alPulsar);
    return () => window.removeEventListener("keydown", alPulsar);
  }, [onCerrar, incrustado]);
  // INCRUSTADO: lo editado se aplica al irse (cambiar de paso o cerrar el gestor), salvo que lo
  // haya descartado. Con refs, para aplicar lo último y no lo del primer dibujo.
  const original = useRef({ steps, nombre: nombre ?? "", anuncios: anuncios ? { claves: anuncios.claves, dirigir: anuncios.dirigir } : null });
  const cambiado =
    borrador !== original.current.steps ||
    (nombre !== undefined && nuevoNombre.trim() !== original.current.nombre) ||
    JSON.stringify(susAnuncios) !== JSON.stringify(original.current.anuncios);
  const alIrse = useRef<() => void>(() => {});
  const [, setAplicado] = useState(0);
  alIrse.current = () => {
    if (!cambiado) return;
    onGuardar(
      borrador,
      nombre !== undefined && nuevoNombre.trim() !== nombre ? nuevoNombre.trim() : undefined,
      susAnuncios ?? undefined
    );
    // Lo aplicado pasa a ser el punto de partida: no se vuelve a aplicar al irse.
    original.current = { steps: borrador, nombre: nuevoNombre.trim(), anuncios: susAnuncios };
    setAplicado((n) => n + 1);
  };
  useEffect(() => {
    if (!incrustado) return;
    return () => alIrse.current();
  }, [incrustado]);
  // INCRUSTADO Y SIN CAMBIOS SUYOS, SIGUE A LO DE AFUERA: un Ctrl+Z de la pizarra o un cambio
  // hecho en otro sitio se ve aquí al momento (si no, enseñaría lo viejo y al irse lo reescribiría).
  // Por CONTENIDO, no por referencia: la lista puede llegar nueva en cada dibujo.
  const firmaDeAfuera = incrustado ? JSON.stringify(steps) : "";
  useEffect(() => {
    if (!incrustado || borradorVivo.current !== original.current.steps) return;
    if (JSON.stringify(original.current.steps) === firmaDeAfuera) return;
    original.current = { ...original.current, steps };
    historial.current = { atras: [], adelante: [] };
    setBorradorDirecto(steps);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [firmaDeAfuera]);
  // LA BURBUJA DEL BOTÓN O CUADRITO QUE SE TOCÓ, a la vista y marcada un momento.
  useEffect(() => {
    if (burbuja == null) return;
    const t = window.setTimeout(() => {
      const el = document.getElementById(`editor-step-${idPrefix}-${burbuja}`);
      if (!el) return;
      el.scrollIntoView({ behavior: "smooth", block: "center" });
      el.classList.add("ring-4", "ring-amber-400");
      window.setTimeout(() => el.classList.remove("ring-4", "ring-amber-400"), 2200);
    }, 250);
    return () => window.clearTimeout(t);
  }, [burbuja, idPrefix]);
  const descartar = () => {
    historial.current = { atras: [], adelante: [] };
    setBorradorDirecto(original.current.steps);
    setNuevoNombre(original.current.nombre);
    setSusAnuncios(original.current.anuncios);
  };
  if (incrustado) {
    return (
      <div className="flex min-w-0 flex-col gap-3">
        <div className="flex flex-wrap items-center gap-2">
          {nombre !== undefined ? (
            <input
              value={nuevoNombre}
              onChange={(e) => setNuevoNombre(e.target.value.slice(0, 120))}
              placeholder="Nombre de la sub pestaña"
              title="Nombre de la sub pestaña: el bot no lo lee, es para ti"
              className="min-w-0 max-w-md flex-1 rounded border border-borde bg-tarjeta px-2 py-1 text-sm font-bold text-tinta focus:border-emerald-500 focus:outline-none"
            />
          ) : (
            <h4 className="text-sm font-bold text-tinta">{titulo}</h4>
          )}
          {cambiado ? (
            <>
              <span className="text-[11px] font-semibold text-amber-700" title="Se aplica al elegir otro paso o al cerrar">● Cambios sin aplicar</span>
              <button type="button" onClick={() => alIrse.current()} className="rounded bg-emerald-600 px-2.5 py-1 text-xs font-semibold text-white hover:bg-emerald-700">
                Aplicar
              </button>
              <button type="button" onClick={descartar} className="rounded border border-borde px-2.5 py-1 text-xs font-semibold text-tinta-suave hover:bg-relleno">
                Descartar
              </button>
            </>
          ) : (
            <span className="text-[11px] text-tinta-suave">Toca una burbuja de la vista previa y te lleva a su editor.</span>
          )}
        </div>
        {anuncios && susAnuncios && (
          <AdTagPicker
            registry={anuncios.registro}
            selectedKeys={susAnuncios.claves}
            onChange={(claves) => setSusAnuncios({ ...susAnuncios, claves })}
            onRegistryChange={anuncios.alCambiarRegistro}
            routingEnabled={susAnuncios.dirigir}
            onRoutingEnabledChange={(dirigir) => setSusAnuncios({ ...susAnuncios, dirigir })}
            deLaTienda={anuncios.deLaTienda}
          />
        )}
        <StepEditorPreviewPair
          steps={borrador}
          onChange={setBorrador}
          onSnapshot={() => {}}
          onEdit={() => {}}
          idPrefix={idPrefix}
          priceSoles={previewFullPriceFromConfig(cfgVista)}
          comboPrice={previewComboPriceFromConfig(cfgVista)}
          basicoPrice={previewBasicoPriceFromConfig(cfgVista)}
          {...(seguimiento !== undefined
            ? {
                stagePriceSoles: previewFullPriceForFollowup(cfgVista, seguimiento),
                stageComboPrice: previewOrderBumpPriceForFollowup(cfgVista, "combo", seguimiento),
                stageBasicoPrice: previewOrderBumpPriceForFollowup(cfgVista, "basico", seguimiento),
              }
            : {})}
          previewContext={conProductosDeLaFicha(previewContextFromConfig(cfgVista), productosFicha)}
          sinExpandir
        />
      </div>
    );
  }
  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-black/40 p-4">
      {/* `prolijo`: la letra y el aire de Sendy, y su oscuro con la pizarra en 🌙 (globals.css). */}
      <div className="prolijo my-8 w-full max-w-6xl rounded-xl border border-neutral-300 bg-tarjeta shadow-xl" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between gap-3 border-b border-neutral-200 px-4 py-3">
          <div className="min-w-0 flex-1">
            {nombre !== undefined ? (
              // EL NOMBRE SE CAMBIA AQUÍ MISMO (16/10/2026): «mejor cambiarla directamente ahí».
              <input
                value={nuevoNombre}
                onChange={(e) => setNuevoNombre(e.target.value.slice(0, 120))}
                placeholder="Nombre de la sub pestaña"
                title="Nombre de la sub pestaña: el bot no lo lee, es para ti"
                className="w-full max-w-md rounded border border-neutral-300 px-2 py-1 text-sm font-bold text-neutral-900 focus:border-emerald-500 focus:outline-none"
              />
            ) : (
              <h3 className="text-sm font-bold text-neutral-900">{titulo}</h3>
            )}
            <p className="mt-0.5 text-xs text-neutral-500">
              Todas sus burbujas. Toca una burbuja de la vista previa y te lleva a su editor.
              {pais ? ` Vista previa con los precios de ${banderaDe(pais)} ${COUNTRY_OPTIONS.find((o) => o.code === pais)?.label ?? pais}.` : ""}
            </p>
          </div>
          <div className="flex items-center gap-2">
            <span className="hidden text-[11px] text-neutral-500 sm:inline">Escape o Cancelar = descartar</span>
            <button type="button" onClick={onCerrar} className="rounded border border-neutral-300 px-3 py-1.5 text-xs font-semibold text-neutral-600 hover:bg-neutral-50">
              Cancelar
            </button>
            <button
              type="button"
              onClick={() =>
                onGuardar(
                  borrador,
                  nombre !== undefined && nuevoNombre.trim() !== nombre ? nuevoNombre.trim() : undefined,
                  susAnuncios ?? undefined
                )
              }
              className="rounded bg-emerald-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-emerald-700"
            >
              Listo
            </button>
          </div>
        </div>
        {/* EL MISMO EDITOR CON VISOR QUE EN LOS MENÚS (16/10/2026): «en las otras yo puedo
            seleccionar una burbuja y me lleva a su cajón editor, y viceversa, duplicar burbujas,
            previsualizar los comodines y spintax… faltan funciones». */}
        <div className="max-h-[78vh] overflow-y-auto p-4">
          {anuncios && susAnuncios && (
            <div className="mb-4">
              <AdTagPicker
                registry={anuncios.registro}
                selectedKeys={susAnuncios.claves}
                onChange={(claves) => setSusAnuncios({ ...susAnuncios, claves })}
                onRegistryChange={anuncios.alCambiarRegistro}
                routingEnabled={susAnuncios.dirigir}
                onRoutingEnabledChange={(dirigir) => setSusAnuncios({ ...susAnuncios, dirigir })}
                deLaTienda={anuncios.deLaTienda}
              />
            </div>
          )}
          <StepEditorPreviewPair
            steps={borrador}
            onChange={setBorrador}
            onSnapshot={() => {}}
            onEdit={() => {}}
            idPrefix={idPrefix}
            priceSoles={previewFullPriceFromConfig(cfgVista)}
            comboPrice={previewComboPriceFromConfig(cfgVista)}
            basicoPrice={previewBasicoPriceFromConfig(cfgVista)}
            // EL PRECIO CON DESCUENTO DE SU SEGUIMIENTO (17/10/2026): «el descuento se activa en el
            // seguimiento 2… sigo viendo el precio de 10 soles, su descuento es 8». El bot ya lo
            // cobraba; la vista previa de la pizarra no sabía en qué seguimiento estaba. Es lo
            // mismo que hacen los menús (`previewStagePrices`), con los productos de la tienda.
            {...(seguimiento !== undefined
              ? {
                  stagePriceSoles: previewFullPriceForFollowup(cfgVista, seguimiento),
                  stageComboPrice: previewOrderBumpPriceForFollowup(cfgVista, "combo", seguimiento),
                  stageBasicoPrice: previewOrderBumpPriceForFollowup(cfgVista, "basico", seguimiento),
                }
              : {})}
            previewContext={conProductosDeLaFicha(previewContextFromConfig(cfgVista), productosFicha)}
            sinExpandir
          />
        </div>
      </div>
    </div>
  );
}


/**
 * LA CONFIGURACIÓN COMO LA VE UNA TIENDA — solo para la vista previa del pop up.
 *
 * Es lo mismo que hace `configDeLaColumna` dentro de «Ver recorrido»: el selector pasa a ser
 * el de la tienda y la alineación la suya. Se escribe aparte en vez de sacar aquélla para no
 * mover el recorrido, que funciona; si una cambia, cambiar la otra. NO SE GUARDA NUNCA.
 */
function configComoLaVeLaTienda(
  cfg: FullConfig,
  tienda: TiendaEditor | undefined,
  semi: string
): FullConfig {
  const mode = activeModality(cfg);
  const suya = Object.entries(tienda?.alineacion ?? {}).filter(([, v]) => v);
  return {
    ...cfg,
    globals: {
      ...cfg.globals,
      segunda_opcion_prestada: semi as "" | "dos_juntas" | "segunda_oculta",
    },
    ...(suya.length > 0
      ? {
          alineacion_por_modalidad: {
            ...cfg.alineacion_por_modalidad,
            [mode]: {
              ...(cfg.alineacion_por_modalidad?.[mode] ?? {}),
              ...Object.fromEntries(suya),
            } as AlineacionEditor,
          },
        }
      : {}),
  };
}

/**
 * DE UNA FICHA DE LA PIZARRA A SUS BURBUJAS DE VERDAD, Y DE VUELTA.
 *
 * Cada ficha sabe de dónde salió por su id —«intro:2», «ob:0», «seg:1:base», «seg:1:3»— y aquí
 * se busca en el MISMO sitio del que la sacó `modeloDePizarra`. `conPasos` devuelve la
 * configuración con esas burbujas cambiadas y nada más: el resto de la ficha (nombre,
 * banderas, tiendas, peso) no se toca.
 *
 * EL ÍNDICE ES EL REAL. Las fichas se numeran sobre la lista entera, antes de ocultar las
 * apagadas, así que guardar por ese número escribe en la que se editó. Es el fallo que el
 * visor de recorrido pagó el 21/09/2026: se guardaba en la variante de al lado.
 */
/** EL REGALO DE UNA TIENDA, con estos campos cambiados (17/10/2026). Ver `TiendaEditor.regalo`. */
function conRegaloDeLaTienda(
  cfg: FullConfig,
  tiendaId: string,
  cambio: NonNullable<TiendaEditor["regalo"]>
): FullConfig {
  // Si su regalo salió de uno GUARDADO, el cambio va a ese guardado y a todas las tiendas que lo usan
  // («los regalos guardados en un solo sitio»): editarlo en una tienda lo cambia en todas.
  const origen = (cfg.tiendas ?? []).find((t) => t.id === tiendaId)?.regalo_origen;
  const guardado = origen ? (cfg.regalos_guardados ?? []).find((r) => r.id === origen) : undefined;
  if (guardado) return conRegaloGuardado(cfg, { ...guardado, ...cambio });
  return {
    ...cfg,
    tiendas: (cfg.tiendas ?? []).map((t) => (t.id === tiendaId ? { ...t, regalo: { ...(t.regalo ?? {}), ...cambio } } : t)),
  };
}

/** Las cuatro piezas de un regalo (sin su id ni su nombre), tal cual las lee el bot en una tienda. */
function piezasDelRegalo(r: RegaloGuardado): NonNullable<TiendaEditor["regalo"]> {
  return {
    ...(r.consent_sequence ? { consent_sequence: r.consent_sequence } : {}),
    ...(r.ask_sequence ? { ask_sequence: r.ask_sequence } : {}),
    ...(r.reward_message !== undefined ? { reward_message: r.reward_message } : {}),
    ...(r.decline_message !== undefined ? { decline_message: r.decline_message } : {}),
  };
}

/** UN REGALO GUARDADO, cambiado: en la lista y en cada tienda que lo usa (la copia que lee el bot). */
function conRegaloGuardado(cfg: FullConfig, r: RegaloGuardado): FullConfig {
  const lista = cfg.regalos_guardados ?? [];
  return {
    ...cfg,
    regalos_guardados: lista.some((x) => x.id === r.id) ? lista.map((x) => (x.id === r.id ? r : x)) : [...lista, r],
    tiendas: (cfg.tiendas ?? []).map((t) => (t.regalo_origen === r.id ? { ...t, regalo: piezasDelRegalo(r) } : t)),
  };
}

/**
 * «¿QUÉ REGALO?» DE UNA TIENDA (25/10/2026). `id` vacío = el regalo general del bot (la tienda deja
 * de tener el suyo). Si no, el guardado con ese id: sus piezas se copian en la tienda.
 */
function conRegaloElegido(cfg: FullConfig, tiendaId: string, id: string): FullConfig {
  const r = (cfg.regalos_guardados ?? []).find((x) => x.id === id);
  return {
    ...cfg,
    tiendas: (cfg.tiendas ?? []).map((t) => {
      if (t.id !== tiendaId) return t;
      const { regalo: _r, regalo_origen: _o, ...resto } = t;
      void _r;
      void _o;
      return r ? { ...resto, regalo: piezasDelRegalo(r), regalo_origen: r.id } : resto;
    }),
  };
}

/** Guarda el regalo que tiene ahora la tienda como uno nuevo de la lista, y la tienda pasa a usarlo. */
function conRegaloGuardadoDeLaTienda(cfg: FullConfig, tiendaId: string, nombre: string): FullConfig {
  const t = (cfg.tiendas ?? []).find((x) => x.id === tiendaId);
  const g = cfg.gift;
  // Lo que se ve en la tienda: lo suyo, y lo que no tenga, del general.
  const r: RegaloGuardado = {
    id: `regalo_${Date.now().toString(36)}`,
    nombre: nombre.trim() || "Regalo",
    consent_sequence: (t?.regalo?.consent_sequence?.length ? t.regalo.consent_sequence : g?.consent_sequence) as EditorStep[] | undefined,
    ask_sequence: (t?.regalo?.ask_sequence?.length ? t.regalo.ask_sequence : g?.ask_sequence) as EditorStep[] | undefined,
    reward_message: t?.regalo?.reward_message?.trim() ? t.regalo.reward_message : g?.reward_message,
    decline_message: t?.regalo?.decline_message?.trim() ? t.regalo.decline_message : g?.decline_message,
  };
  const conLista = { ...cfg, regalos_guardados: [...(cfg.regalos_guardados ?? []), JSON.parse(JSON.stringify(r)) as RegaloGuardado] };
  return conRegaloElegido(conLista, tiendaId, r.id);
}

function piezaEditable(
  cfg: FullConfig,
  canal: ChannelKey,
  piezaId: string,
  /** La tienda de la pizarra: el regalo que se edita es el SUYO. Sin ella, el general. */
  tiendaId?: string
): { titulo: string; steps: EditorStep[]; conPasos: (steps: EditorStep[]) => FullConfig } | null {
  const mode = activeModality(cfg);
  const contenido = channelContentForMode(cfg, canal, mode);
  const conContenido = (nuevo: ChannelContentEditor): FullConfig => ({
    ...cfg,
    channels: {
      ...cfg.channels,
      [canal]: {
        ...(cfg.channels?.[canal] ?? {}),
        modality_templates: {
          ...(cfg.channels?.[canal]?.modality_templates ?? {}),
          [mode]: nuevo,
        },
      },
    },
  });
  const [tipo, a, b] = piezaId.split(":");
  const i = Number(a);
  // EL UPSELL SE EDITA COMO CUALQUIER FICHA CON ETIQUETAS: por `ubicarPieza`.
  if (tipo === "up") {
    const u = ubicarPieza(cfg, canal, piezaId);
    if (!u) return null;
    return {
      titulo: u.obj.name || `Upsell ${i + 1}`,
      steps: u.obj.steps ?? [],
      conPasos: (steps) => u.poner({ ...u.obj, steps }),
    };
  }
  // LA ENTREGA VIVE EN LA FICHA DEL PRODUCTO, en el almacén. Se cambia ahí y le llega a todas
  // las tiendas que juegan ese producto: es como siempre ha funcionado el almacén.
  if (tipo === "entrega") {
    const idDelProducto = piezaId.slice("entrega:".length);
    const almacen = cfg.biblioteca_de_productos ?? [];
    const p = almacen.find((x) => x?.id === idDelProducto);
    if (!p) return null;
    return {
      titulo: `Entrega · ${p.name?.trim() || "Producto"}`,
      steps: (p.delivery ?? []) as EditorStep[],
      conPasos: (steps) => ({
        ...cfg,
        biblioteca_de_productos: almacen.map((x) =>
          x?.id === idDelProducto ? { ...x, delivery: steps } : x
        ) as typeof almacen,
      }),
    };
  }
  // LO QUE RECIBE AL ACEPTAR EL REGALO: el enlace para comentar, en `ask_sequence`. Solo si ya
  // tiene burbujas: sin ellas el bot manda el audio y el texto viejos, y escribir aquí la
  // primera burbuja cambiaría eso sin que él lo pidiera.
  // EL REGALO DE LA TIENDA (17/10/2026): desde la pizarra de una tienda se lee y se escribe el
  // SUYO. Si todavía no tiene, se ve el de todas, y al guardar pasa a ser suyo; las demás
  // tiendas no cambian. Sin tienda, el general, como siempre.
  const suTienda = tiendaId ? (cfg.tiendas ?? []).find((t) => t.id === tiendaId) : undefined;
  // LA PRESENTACIÓN DE UN UPSELL EN FILA (19/10/2026): «cuando agrego uno nuevo no me deja
  // editarlo al darle doble clic». Vive en la ficha del producto (`presentacion_upsell`): sus
  // cajones de intro, o la lista suelta de respaldo si no tiene cajones. Se edita el primero.
  if (tipo === "presentacion") {
    const idDelProducto = piezaId.slice("presentacion:".length);
    const almacen = cfg.biblioteca_de_productos ?? [];
    const prod = almacen.find((x) => x?.id === idDelProducto);
    if (!prod) return null;
    const pres = prod.presentacion_upsell ?? {};
    const conPres = (nueva: PresentacionUpsellEditor): FullConfig => ({
      ...cfg,
      biblioteca_de_productos: almacen.map((x) => (x?.id === idDelProducto ? { ...x, presentacion_upsell: nueva } : x)),
    });
    const grupos = pres.intro_groups ?? [];
    if (grupos.length > 0) {
      return {
        titulo: `${prod.name?.trim() || "Upsell"} · presentación como upsell`,
        steps: grupos[0].steps ?? [],
        conPasos: (steps) => conPres({ ...pres, intro_groups: grupos.map((g, j) => (j === 0 ? { ...g, steps } : g)) }),
      };
    }
    return {
      titulo: `${prod.name?.trim() || "Upsell"} · presentación como upsell`,
      steps: pres.intro ?? [],
      conPasos: (steps) => conPres({ ...pres, intro: steps }),
    };
  }
  if (tipo === "regalo-pedido") {
    const suyo = suTienda?.regalo?.ask_sequence ?? [];
    if (!cfg.gift || (suyo.length === 0 && (cfg.gift.ask_sequence ?? []).length === 0)) return null;
    return {
      titulo: suTienda ? `Enlace para comentar · ${suyo.length > 0 ? "de esta tienda" : "el de todas (al guardar, esta tienda tendrá el suyo)"}` : "Enlace para comentar",
      steps: suyo.length > 0 ? suyo : cfg.gift.ask_sequence,
      conPasos: (steps) =>
        suTienda ? conRegaloDeLaTienda(cfg, suTienda.id, { ask_sequence: steps }) : { ...cfg, gift: { ...cfg.gift!, ask_sequence: steps } },
    };
  }
  // EL REGALO ES UNO SOLO POR TIENDA: su ofrecimiento son las burbujas de `consent_sequence`.
  if (tipo === "regalo") {
    if (!cfg.gift) return null;
    const suyo = suTienda?.regalo?.consent_sequence ?? [];
    return {
      titulo: suTienda ? `Ofrecimiento de regalo · ${suyo.length > 0 ? "de esta tienda" : "el de todas (al guardar, esta tienda tendrá el suyo)"}` : "Ofrecimiento de regalo",
      steps: suyo.length > 0 ? suyo : cfg.gift.consent_sequence ?? [],
      conPasos: (steps) =>
        suTienda ? conRegaloDeLaTienda(cfg, suTienda.id, { consent_sequence: steps }) : { ...cfg, gift: { ...cfg.gift, consent_sequence: steps } },
    };
  }
  if (tipo === "intro") {
    const g = contenido.intro_groups[i];
    if (!g) return null;
    return {
      titulo: g.name || `Intro ${i + 1}`,
      steps: g.steps ?? [],
      conPasos: (steps) =>
        conContenido({
          ...contenido,
          intro_groups: contenido.intro_groups.map((x, j) => (j === i ? { ...x, steps } : x)),
        }),
    };
  }
  if (tipo === "ob") {
    // Del MISMO sitio del que la leyó `modeloDePizarra`: los del canal si tiene, si no los de
    // la modalidad.
    const delCanal = contenido.order_bump_intro_groups ?? [];
    if (delCanal.length > 0) {
      const g = delCanal[i];
      if (!g) return null;
      return {
        titulo: g.name || `Intro de order bump ${i + 1}`,
        steps: g.steps ?? [],
        conPasos: (steps) =>
          conContenido({
            ...contenido,
            order_bump_intro_groups: delCanal.map((x, j) => (j === i ? { ...x, steps } : x)),
          }),
      };
    }
    const deLaModalidad = cfg.order_bump?.intro_groups ?? [];
    const g = deLaModalidad[i];
    if (!g) return null;
    return {
      titulo: g.name || `Intro de order bump ${i + 1}`,
      steps: g.steps ?? [],
      conPasos: (steps) => ({
        ...cfg,
        order_bump: {
          ...cfg.order_bump,
          intro_groups: deLaModalidad.map((x, j) => (j === i ? { ...x, steps } : x)),
        },
      }),
    };
  }
  if (tipo === "seg") {
    const f = contenido.followups[i];
    if (!f) return null;
    const conSeguimiento = (nuevo: EditorFollowup) =>
      conContenido({
        ...contenido,
        followups: contenido.followups.map((x, j) => (j === i ? nuevo : x)),
      });
    if (b === "base") {
      return {
        titulo: `${f.name || `Seguimiento ${i + 1}`} · mensajes principales`,
        steps: f.steps ?? [],
        conPasos: (steps) => conSeguimiento({ ...f, steps }),
      };
    }
    const vi = Number(b);
    const v = (f.variants ?? [])[vi];
    if (!v) return null;
    return {
      titulo: v.name || `${f.name || `Seguimiento ${i + 1}`} · variante ${vi + 2}`,
      steps: v.steps ?? [],
      conPasos: (steps) =>
        conSeguimiento({
          ...f,
          variants: (f.variants ?? []).map((x, j) => (j === vi ? { ...x, steps } : x)),
        }),
    };
  }
  return null;
}

/**
 * ════════════════════════════════════════════════════════════════════════════
 * PIZARRA, PARTE 3 — CONECTAR, DESCONECTAR, APAGAR, DUPLICAR Y AGREGAR.
 * ════════════════════════════════════════════════════════════════════════════
 *
 * Lo pidió el dueño el 16/10/2026: «al yo quitar una conexión equivaldría a quitar la bandera
 * o la tienda», «debo poder duplicar esas ventanas flotantes y dejarlas sin conexión», y el
 * botón «+» de Sendy con intro, seguimientos e intro de order bump.
 *
 * TODO ESTO SOLO MUEVE ETIQUETAS QUE ÉL YA MUEVE A MANO en los menús —encendido, banderas,
 * tiendas— y lo hace en el MISMO borrador: se ve el aviso «sin guardar» y se sube con Ctrl+S.
 * El bot no sabe de dónde vino el cambio.
 *
 * LAS TRES REGLAS QUE NO SE SALTAN, porque cada una evita un fallo de venta:
 *
 *   1. LO NUEVO VA AL FINAL DE SU LISTA. El motor recuerda POR NÚMERO qué intro y qué variante
 *      de seguimiento le tocó a cada cliente (`intro_variant_sent`, `variant_index`). Insertar
 *      en medio correría los números, y a quien está a medias le saldría otra pieza.
 *   2. LO QUE NACE O SE QUEDA SIN BANDERA, NACE O QUEDA APAGADO. Una pieza encendida sin
 *      bandera, en un canal donde nadie lleva banderas, juega para TODOS. «Suelta» tiene que
 *      significar que no sale.
 *   3. LOS «MENSAJES PRINCIPALES» NO SE CONECTAN NI SE DESCONECTAN. Sus etiquetas son las del
 *      seguimiento entero, y sus variantes las heredan: tocarlas cambiaría piezas que él no
 *      tocó. Su texto sí se edita.
 */
type PiezaUbicada = {
  /** La ficha tal cual está en la configuración. */
  obj: {
    name?: string;
    enabled?: boolean;
    paises?: string[];
    tiendas?: string[];
    semimodalidad?: string;
    steps?: EditorStep[];
    pais_routing_enabled?: boolean;
    paisRoutingEnabled?: boolean;
    /** Su camino (18/10/2026). Ver `etiqueta-de-camino.ts`. */
    camino?: string;
    tambien_en_caminos?: string[];
  };
  /** La configuración con esta ficha cambiada por otra. */
  poner: (nuevo: PiezaUbicada["obj"]) => FullConfig;
  /** La configuración con una ficha MÁS al final de la misma lista. */
  agregarAlFinal: (nuevo: PiezaUbicada["obj"]) => FullConfig;
  /** Los cajones de intro del canal guardan el «dirigir por país» en camello. */
  camello: boolean;
  /** «Mensajes principales»: sus etiquetas son las del seguimiento entero. */
  esBase: boolean;
};

function ubicarPieza(cfg: FullConfig, canal: ChannelKey, piezaId: string): PiezaUbicada | null {
  const mode = activeModality(cfg);
  const contenido = channelContentForMode(cfg, canal, mode);
  const conContenido = (nuevo: ChannelContentEditor): FullConfig => ({
    ...cfg,
    channels: {
      ...cfg.channels,
      [canal]: {
        ...(cfg.channels?.[canal] ?? {}),
        modality_templates: { ...(cfg.channels?.[canal]?.modality_templates ?? {}), [mode]: nuevo },
      },
    },
  });
  const [tipo, a, b] = piezaId.split(":");
  const i = Number(a);
  if (tipo === "intro") {
    const lista = contenido.intro_groups;
    if (!lista[i]) return null;
    const con = (l: ChannelIntroGroupEditor[]) => conContenido({ ...contenido, intro_groups: l });
    return {
      obj: lista[i],
      poner: (n) => con(lista.map((x, j) => (j === i ? ({ ...x, ...n } as ChannelIntroGroupEditor) : x))),
      agregarAlFinal: (n) => con([...lista, { name: "", steps: [], ...n } as ChannelIntroGroupEditor]),
      camello: true,
      esBase: false,
    };
  }
  if (tipo === "ob") {
    const delCanal = contenido.order_bump_intro_groups ?? [];
    if (delCanal.length > 0) {
      if (!delCanal[i]) return null;
      const con = (l: GrupoDeIntroEditor[]) => conContenido({ ...contenido, order_bump_intro_groups: l });
      return {
        obj: delCanal[i],
        poner: (n) => con(delCanal.map((x, j) => (j === i ? { ...x, ...n } : x))),
        agregarAlFinal: (n) => con([...delCanal, { ...n }]),
        camello: false,
        esBase: false,
      };
    }
    const deLaModalidad = cfg.order_bump?.intro_groups ?? [];
    if (!deLaModalidad[i]) return null;
    const con = (l: GrupoDeIntroEditor[]): FullConfig => ({
      ...cfg,
      order_bump: { ...cfg.order_bump, intro_groups: l },
    });
    return {
      obj: deLaModalidad[i],
      poner: (n) => con(deLaModalidad.map((x, j) => (j === i ? { ...x, ...n } : x))),
      agregarAlFinal: (n) => con([...deLaModalidad, { ...n }]),
      camello: false,
      esBase: false,
    };
  }
  if (tipo === "up") {
    // Del MISMO sitio del que lo lee el motor: los del canal si tiene, si no los de la modalidad.
    const delCanal = contenido.upsell_intro_groups ?? [];
    if (delCanal.length > 0) {
      if (!delCanal[i]) return null;
      const con = (l: GrupoDeIntroEditor[]) => conContenido({ ...contenido, upsell_intro_groups: l });
      return {
        obj: delCanal[i],
        poner: (n) => con(delCanal.map((x, j) => (j === i ? { ...x, ...n } : x))),
        agregarAlFinal: (n) => con([...delCanal, { ...n }]),
        camello: false,
        esBase: false,
      };
    }
    const deLaModalidad = cfg.upsell?.intro_groups ?? [];
    if (!deLaModalidad[i] || !cfg.upsell) return null;
    const con = (l: GrupoDeIntroEditor[]): FullConfig => ({
      ...cfg,
      upsell: { ...cfg.upsell, intro_groups: l },
    });
    return {
      obj: deLaModalidad[i],
      poner: (n) => con(deLaModalidad.map((x, j) => (j === i ? { ...x, ...n } : x))),
      agregarAlFinal: (n) => con([...deLaModalidad, { ...n }]),
      camello: false,
      esBase: false,
    };
  }
  if (tipo === "seg") {
    const f = contenido.followups[i];
    if (!f) return null;
    const conSeguimiento = (nuevo: EditorFollowup) =>
      conContenido({ ...contenido, followups: contenido.followups.map((x, j) => (j === i ? nuevo : x)) });
    if (b === "base") {
      return {
        obj: f,
        poner: (n) => conSeguimiento({ ...f, ...n } as EditorFollowup),
        agregarAlFinal: (n) =>
          conSeguimiento({ ...f, variants: [...(f.variants ?? []), { steps: [], ...n } as EditorFollowupVariant] }),
        camello: false,
        esBase: true,
      };
    }
    const vi = Number(b);
    const variantes = f.variants ?? [];
    if (!variantes[vi]) return null;
    return {
      obj: variantes[vi],
      poner: (n) =>
        conSeguimiento({
          ...f,
          variants: variantes.map((x, j) => (j === vi ? ({ ...x, ...n } as EditorFollowupVariant) : x)),
        }),
      agregarAlFinal: (n) =>
        conSeguimiento({ ...f, variants: [...variantes, { steps: [], ...n } as EditorFollowupVariant] }),
      camello: false,
      esBase: false,
    };
  }
  return null;
}

/**
 * CADA TIENDA CON LO SUYO (17/10/2026).
 *
 * Él: «cuando yo creo una sub pestaña la conecto y me dice "no tiene tienda"… es ridículo,
 * ¿cómo no va a tener tienda si estoy en la tienda de GRAFISMO?», y «se supone que este método
 * es el futuro, no puede quedar así». Sus sub pestañas eran 🌐 —de todas las tiendas— y la
 * tienda EXCLUYE en el motor: si una encendida nombra a la tienda, las 🌐 de esa columna dejan de
 * salir en ella. Por eso una nueva marcada «de GRAFISMO» dejó sin intro a Perú y Ecuador.
 *
 * La salida, sin tocar el motor: las sub pestañas que JUEGAN en esta tienda y son compartidas se
 * COPIAN como propias de ella, AL FINAL de su lista (el bot recuerda por número), idénticas. Las
 * originales siguen igual para las otras tiendas; si una nombraba a varias, deja de nombrar a
 * ésta. Para el cliente de esta tienda no cambia nada: recibe lo mismo, ahora desde la copia.
 *
 * Devuelve qué id pasó a cuál, para que la pizarra lleve consigo su sitio y sus cables.
 */
function idAlFinalDeSuLista(c: FullConfig, canal: ChannelKey, piezaId: string): string {
  const [tipo, a] = piezaId.split(":");
  const contenido = channelContentForMode(c, canal, activeModality(c));
  if (tipo === "intro") return `intro:${contenido.intro_groups.length}`;
  if (tipo === "ob")
    return `ob:${((contenido.order_bump_intro_groups ?? []).length > 0 ? contenido.order_bump_intro_groups ?? [] : c.order_bump?.intro_groups ?? []).length}`;
  if (tipo === "up")
    return `up:${((contenido.upsell_intro_groups ?? []).length > 0 ? contenido.upsell_intro_groups ?? [] : c.upsell?.intro_groups ?? []).length}`;
  return `seg:${a}:${(contenido.followups[Number(a)]?.variants ?? []).length}`;
}

/** Una copia IDÉNTICA de la sub pestaña, AL FINAL de su lista, solo de esta tienda. */
function copiaPropiaDeLaTienda(
  c: FullConfig,
  canal: ChannelKey,
  piezaId: string,
  tiendaId: string
): { cfg: FullConfig; id: string } | null {
  const [tipo, a] = piezaId.split(":");
  const u = ubicarPieza(c, canal, piezaId);
  if (!u) return null;
  const mode = activeModality(c);
  const id = idAlFinalDeSuLista(c, canal, piezaId);
  // LOS «MENSAJES PRINCIPALES» se copian como una variante más de su seguimiento.
  const obj: PiezaUbicada["obj"] = u.esBase
    ? (() => {
        const f = u.obj as EditorFollowup;
        const v: EditorFollowupVariant = {
          name: `${f.name || "Seguimiento"} · principales`,
          steps: JSON.parse(JSON.stringify(f.steps ?? [])),
          enabled: f.steps_enabled !== false,
          ...(f.ad_keys ? { ad_keys: [...f.ad_keys] } : {}),
          ...(f.ad_routing_enabled !== undefined ? { ad_routing_enabled: f.ad_routing_enabled } : {}),
          paises: [...(f.paises ?? [])],
          ...(f.pais_routing_enabled !== undefined ? { pais_routing_enabled: f.pais_routing_enabled } : {}),
          semimodalidad: f.semimodalidad,
        };
        return v as PiezaUbicada["obj"];
      })()
    : (JSON.parse(JSON.stringify(u.obj)) as PiezaUbicada["obj"]);
  // Una variante sin banderas ni semimodalidad propias HEREDABA las de su seguimiento: la copia
  // las lleva escritas, para recibir exactamente lo mismo.
  if (tipo === "seg" && !u.esBase) {
    const f = channelContentForMode(c, canal, mode).followups[Number(a)];
    if (f) {
      if ((obj.paises ?? []).length === 0 && obj.pais_routing_enabled !== false && (f.paises ?? []).length > 0) {
        obj.paises = [...(f.paises ?? [])];
        obj.pais_routing_enabled = true;
      }
      if (!(obj.semimodalidad ?? "").trim() && f.semimodalidad) obj.semimodalidad = f.semimodalidad;
    }
  }
  return { cfg: u.agregarAlFinal({ ...conBotonesNuevos(obj), tiendas: [tiendaId] }), id };
}

/**
 * LAS QUE SALEN HOY EN LAS OTRAS TIENDAS (en este canal), con las mismas reglas del bot.
 * Sirve para no tocarles nada a ellas.
 */
function usadasEnOtrasTiendas(c: FullConfig, canal: ChannelKey, tiendaId: string): Set<string> {
  const ts = (c.tiendas ?? []).filter((t) => String(t?.id ?? "").trim());
  const usadas = new Set<string>();
  for (const t of ts) {
    if (t.id === tiendaId) continue;
    for (const p of modeloDePizarra(c, canal, t.id, t.semimodalidad ?? "", ts, []).piezas) if (p.estado === "juega") usadas.add(p.id);
  }
  return usadas;
}

/**
 * LA ORIGINAL DEJA DE SALIR EN ESTA TIENDA, SIN CAMBIARLE NADA A LAS DEMÁS (17/10/2026).
 *
 *  · Si nombraba tiendas (o las heredaba): deja de nombrar a ésta. Las demás, igual.
 *  · Si era 🌐 y NINGUNA otra tienda la usa: se APAGA. Nadie la usaba fuera de aquí, y aquí ya
 *    está su copia; si siguiera encendida, el día que esta tienda se quedara sin la suya en esa
 *    columna (al eliminarla) el bot volvería a mandarle ésta y la pizarra la «resucitaba».
 *  · Si era 🌐 y OTRA tienda la usa: se queda tal cual. Marcarla con el nombre de las demás NO
 *    vale —probado al escribir esto—: una tienda que pasa a tener una nombrada deja fuera a sus
 *    otras 🌐 de esa columna, que es justo el fallo de hoy, al revés.
 */
function sinEstaTienda(
  c: FullConfig,
  canal: ChannelKey,
  piezaId: string,
  tiendaId: string,
  usadasFuera: Set<string>
): FullConfig {
  const [tipo, a] = piezaId.split(":");
  const u = ubicarPieza(c, canal, piezaId);
  if (!u) return c;
  const propias = u.obj.tiendas ?? [];
  const heredadas =
    tipo === "seg" && !u.esBase && propias.length === 0
      ? channelContentForMode(c, canal, activeModality(c)).followups[Number(a)]?.tiendas ?? []
      : propias;
  if (heredadas.length === 0) {
    if (usadasFuera.has(piezaId)) return c;
    // Los «mensajes principales» se apagan con su interruptor propio, no el del seguimiento.
    if (u.esBase) return u.poner({ ...u.obj, steps_enabled: false } as PiezaUbicada["obj"]);
    return u.poner({ ...u.obj, enabled: false });
  }
  return heredadas.includes(tiendaId) ? u.poner({ ...u.obj, tiendas: heredadas.filter((x) => x !== tiendaId) }) : c;
}

/**
 * UNA PIZARRA POR SEMIMODALIDAD (18/10/2026): «cada ficha debe vivir en su semimodalidad… si
 * cambio de semimodalidad debo modificar lo que sea sin que afecte a la otra». La clave lleva la
 * forma de vender: «tienda|canal|lineal», «…|dou», «…|ob».
 */
function claveDeLaVista(tiendaId: string, canal: string, semi: string): string {
  return `${tiendaId}|${canal}|${laSemimodalidadDeLaTienda({ semimodalidad: semi })}`;
}

/** La pizarra de esa semimodalidad; si todavía no tiene, la que había antes (una para todas). */
function vistaDeLaPizarra(cfg: FullConfig, tiendaId: string, canal: string, semi: string): DisposicionDePizarra | undefined {
  const vistas = cfg.pizarra?.vistas ?? {};
  return vistas[claveDeLaVista(tiendaId, canal, semi)] ?? vistas[`${tiendaId}|${canal}`];
}

/**
 * CADA SEMIMODALIDAD CON LO SUYO (18/10/2026). Igual que entre tiendas (`hacerPropiaLaTienda`):
 * las fichas SIN etiqueta de semimodalidad que juegan en ésta reciben una copia propia, con su
 * etiqueta, al final de su lista; la original sigue igual para las otras semimodalidades.
 *
 * SE COPIAN TODAS LAS QUE JUEGAN A LA VEZ, y no es un detalle: el bot filtra por semimodalidad
 * la estación ENTERA de la tienda (todos los países) —`porSemimodalidad`: si hay alguna con la
 * etiqueta, juegan SOLO ésas—. Copiar solo la intro de Perú dejaría sin intro a Ecuador y
 * Argentina en esta semimodalidad. Como en una estación juegan o todas etiquetadas o todas sin
 * etiqueta, copiar todas las sin etiqueta que juegan deja la estación con lo mismo de antes.
 *
 * El cliente recibe lo mismo (copias idénticas) y los números de las que ya estaban no cambian
 * (las copias van al final): un seguimiento ya agendado sale igual.
 */
function hacerPropiaLaSemi(
  cfg: FullConfig,
  canal: ChannelKey,
  tiendaId: string,
  semi: string,
  tiendas: TiendaEditor[],
  paisesExtra: string[]
): { cfg: FullConfig; mapa: Map<string, string> } {
  const mapa = new Map<string, string>();
  if (!tiendaId) return { cfg, mapa };
  const etiqueta = laSemimodalidadDeLaTienda({ semimodalidad: semi });
  const m = modeloDePizarra(cfg, canal, tiendaId, semi, tiendas, paisesExtra);
  const sinEtiqueta = m.piezas.filter((p) => p.estado === "juega" && !p.semimodalidad);
  let c = cfg;
  for (const p of sinEtiqueta) {
    const r = copiaPropiaDeLaTienda(c, canal, p.id, tiendaId);
    if (!r) continue;
    const u = ubicarPieza(r.cfg, canal, r.id);
    if (!u) continue;
    c = u.poner({ ...u.obj, semimodalidad: etiqueta });
    mapa.set(p.id, r.id);
  }
  return { cfg: c, mapa };
}

function hacerPropiaLaTienda(
  cfg: FullConfig,
  canal: ChannelKey,
  tiendaId: string,
  semi: string,
  tiendas: TiendaEditor[],
  paisesExtra: string[]
): { cfg: FullConfig; mapa: Map<string, string> } {
  const mapa = new Map<string, string>();
  if (!tiendaId) return { cfg, mapa };
  const m = modeloDePizarra(cfg, canal, tiendaId, semi, tiendas, paisesExtra);
  const compartidas = m.piezas.filter((p) => p.estado === "juega" && (p.todasLasTiendas || p.otrasTiendas.length > 0));
  let c = cfg;
  const usadasFuera = usadasEnOtrasTiendas(cfg, canal, tiendaId);
  for (const p of compartidas) {
    const r = copiaPropiaDeLaTienda(c, canal, p.id, tiendaId);
    if (!r) continue;
    c = sinEstaTienda(r.cfg, canal, p.id, tiendaId, usadasFuera);
    mapa.set(p.id, r.id);
  }
  return { cfg: c, mapa };
}

/**
 * DUPLICAR UNA TIENDA, «una copia completa» como en Sendy (16/10/2026).
 *
 * La copia nace SIN NÚMERO y SIN PÁGINA —un número no puede atender dos tiendas por igual: él
 * le pone el suyo— y con todo lo demás: productos, semimodalidad, cobrador, frases. Sus sub
 * pestañas PROPIAS (las que nombran a la original) se copian también, AL FINAL de cada lista
 * —el bot recuerda por número qué intro le tocó a cada cliente: insertar en medio lo
 * cambiaría—, y quedan solo de la copia. Las «🌐 todas las tiendas» ya le valen sin copiarlas.
 * Los «mensajes principales» de un seguimiento no se copian: son del seguimiento entero.
 */
function duplicarTienda(cfg: FullConfig, tiendaId: string): { cfg: FullConfig; id: string } | null {
  const original = (cfg.tiendas ?? []).find((t) => t.id === tiendaId);
  if (!original) return null;
  const id = `tienda_${Date.now().toString(36)}`;
  const copia: TiendaEditor = {
    ...JSON.parse(JSON.stringify(original)),
    id,
    nombre: `${original.nombre?.trim() || "Tienda"} (copia)`,
    numero: "",
    pagina: "",
  };
  let c: FullConfig = { ...cfg, tiendas: [...(cfg.tiendas ?? []), copia] };
  // SU TABLERO TAMBIÉN (23/10/2026), en todos sus canales. Nace apagado: la copia no tiene número
  // todavía, y encenderlo es decisión suya.
  const suTablero = cfg.tableros?.[tiendaId];
  if (suTablero) {
    const copiaDelTablero = JSON.parse(JSON.stringify(suTablero)) as NonNullable<FullConfig["tableros"]>[string];
    for (const k of Object.keys(copiaDelTablero) as Array<keyof typeof copiaDelTablero>) {
      const tb = copiaDelTablero[k];
      if (tb) tb.encendido = false;
    }
    c = { ...c, tableros: { ...(c.tableros ?? {}), [id]: copiaDelTablero } };
  }
  const mode = activeModality(cfg);
  const yaCopiadas = new Set<string>();
  for (const canal of ["whatsapp", "messenger", "instagram"] as ChannelKey[]) {
    if (cfg.channels?.[canal]?.use_content !== true) continue;
    const contenido = channelContentForMode(cfg, canal, mode);
    const suya = (x: { tiendas?: string[] }) => (x.tiendas ?? []).includes(tiendaId);
    const ids: string[] = [];
    contenido.intro_groups.forEach((g, i) => suya(g) && ids.push(`intro:${i}`));
    // La oferta y el upsell pueden ser de la MODALIDAD (compartidos entre canales): una vez.
    const obDelCanal = (contenido.order_bump_intro_groups ?? []).length > 0;
    if (obDelCanal || !yaCopiadas.has("ob")) {
      (obDelCanal ? contenido.order_bump_intro_groups ?? [] : cfg.order_bump?.intro_groups ?? []).forEach(
        (g, i) => suya(g) && ids.push(`ob:${i}`)
      );
      if (!obDelCanal) yaCopiadas.add("ob");
    }
    const upDelCanal = (contenido.upsell_intro_groups ?? []).length > 0;
    if (upDelCanal || !yaCopiadas.has("up")) {
      (upDelCanal ? contenido.upsell_intro_groups ?? [] : cfg.upsell?.intro_groups ?? []).forEach(
        (g, i) => suya(g) && ids.push(`up:${i}`)
      );
      if (!upDelCanal) yaCopiadas.add("up");
    }
    contenido.followups.forEach((f, fi) => (f.variants ?? []).forEach((v, vi) => suya(v) && ids.push(`seg:${fi}:${vi}`)));
    // Al final de cada lista: los índices recogidos arriba siguen señalando a las originales.
    for (const piezaId of ids) {
      const u = ubicarPieza(c, canal, piezaId);
      if (!u) continue;
      c = u.agregarAlFinal({ ...JSON.parse(JSON.stringify(u.obj)), tiendas: [id] });
    }
  }
  // Sus cajas y dónde dejó cada cosa en la pizarra, para que la copia se vea igual.
  const vistas = cfg.pizarra?.vistas ?? {};
  const deLaOriginal = Object.entries(vistas).filter(([k]) => k.startsWith(`${tiendaId}|`));
  if (deLaOriginal.length > 0) {
    c = {
      ...c,
      pizarra: {
        vistas: {
          ...vistas,
          ...Object.fromEntries(
            deLaOriginal.map(([k, v]) => [`${id}|${k.slice(tiendaId.length + 1)}`, { posiciones: {}, cajas: v.cajas }])
          ),
        },
      },
    };
  }
  return { cfg: c, id };
}

/**
 * EXPORTAR UNA TIENDA EN UN JSON (19/10/2026): «necesito poder exportar e importar jsons, las
 * tiendas». Lleva la tienda, los productos que juega (con su contenido, entregas y precios), su
 * fila de upsells, sus sub pestañas PROPIAS (las que la nombran; las «🌐 todas las tiendas» son
 * del bot entero y no viajan) y su pizarra. Se lee con `importarTienda`.
 */
const FORMATO_DE_TIENDA = "tienda-del-bot";
function exportarTienda(cfg: FullConfig, tiendaId: string): Record<string, unknown> | null {
  const tienda = (cfg.tiendas ?? []).find((t) => t.id === tiendaId);
  if (!tienda) return null;
  const mode = activeModality(cfg);
  const fichas: Array<{ canal: ChannelKey; piezaId: string; obj: unknown }> = [];
  for (const canal of ["whatsapp", "messenger", "instagram"] as ChannelKey[]) {
    if (cfg.channels?.[canal]?.use_content !== true) continue;
    const contenido = channelContentForMode(cfg, canal, mode);
    const suya = (x: { tiendas?: string[] }) => (x.tiendas ?? []).includes(tiendaId);
    const ids: string[] = [];
    contenido.intro_groups.forEach((g, i) => suya(g) && ids.push(`intro:${i}`));
    const obs = (contenido.order_bump_intro_groups ?? []).length > 0 ? contenido.order_bump_intro_groups ?? [] : cfg.order_bump?.intro_groups ?? [];
    obs.forEach((g, i) => suya(g) && ids.push(`ob:${i}`));
    const ups = (contenido.upsell_intro_groups ?? []).length > 0 ? contenido.upsell_intro_groups ?? [] : cfg.upsell?.intro_groups ?? [];
    ups.forEach((g, i) => suya(g) && ids.push(`up:${i}`));
    contenido.followups.forEach((f, fi) => (f.variants ?? []).forEach((v, vi) => suya(v) && ids.push(`seg:${fi}:${vi}`)));
    for (const piezaId of ids) {
      const u = ubicarPieza(cfg, canal, piezaId);
      if (u) fichas.push({ canal, piezaId, obj: JSON.parse(JSON.stringify(u.obj)) });
    }
  }
  const fila = (cfg.filas_de_upsell ?? []).find((f) => (f.tiendas ?? []).includes(tiendaId));
  // SU TABLERO TAMBIÉN (25/10/2026), con los productos que nombran sus fichas (cobros, entregas,
  // lo que presenta cada mensaje): sin ellos, la tienda importada cobraría productos que no existen.
  const suTablero = cfg.tableros?.[tiendaId];
  const todosLosIds = new Set((cfg.biblioteca_de_productos ?? []).map((p) => p?.id).filter(Boolean));
  const delTablero: string[] = [];
  const recorrer = (v: unknown) => {
    if (typeof v === "string") {
      if (todosLosIds.has(v)) delTablero.push(v);
    } else if (Array.isArray(v)) v.forEach(recorrer);
    else if (v && typeof v === "object") Object.values(v).forEach(recorrer);
  };
  recorrer(suTablero);
  const idsDeProductos = new Set<string>([
    ...Object.values(tienda.alineacion ?? {}).filter(Boolean),
    ...(tienda.upsell_apagado ? [tienda.upsell_apagado] : []),
    ...(fila?.puestos ?? []).map((p) => p.producto_id).filter(Boolean),
    ...delTablero,
  ]);
  const productos = (cfg.biblioteca_de_productos ?? []).filter((p) => p?.id && idsDeProductos.has(p.id));
  const vistas = Object.fromEntries(
    Object.entries(cfg.pizarra?.vistas ?? {})
      .filter(([k]) => k.startsWith(`${tiendaId}|`))
      .map(([k, v]) => [k.slice(tiendaId.length + 1), v])
  );
  return {
    formato: FORMATO_DE_TIENDA,
    version: 1,
    exportada: new Date().toISOString(),
    modalidad: mode,
    tienda: JSON.parse(JSON.stringify(tienda)),
    productos: JSON.parse(JSON.stringify(productos)),
    ...(fila ? { filaDeUpsell: JSON.parse(JSON.stringify(fila)) } : {}),
    fichas,
    vistas: JSON.parse(JSON.stringify(vistas)),
    // La espera antes del upsell 1 (los de la fila llevan la suya en `filaDeUpsell`).
    ...(typeof cfg.upsell?.retraso_minutos === "number" ? { retrasoDelUpsell: cfg.upsell.retraso_minutos } : {}),
    // El silencio antes del regalo: el tablero lo usa para «el upsell sin respuesta → regalo».
    ...(typeof cfg.globals?.awaiting_email_timeout_seconds === "number" ? { silencioDelRegalo: cfg.globals.awaiting_email_timeout_seconds } : {}),
    // Los minutos de cada seguimiento: con ellos el tablero arma sus tiempos iguales.
    tiemposDeSeguimiento: Object.fromEntries(
      channelContentForMode(cfg, "whatsapp", mode).followups.flatMap((f, i) =>
        typeof f.delay_minutes_from_first_message === "number" ? [[String(i), f.delay_minutes_from_first_message]] : []
      )
    ),
    ...(suTablero ? { tablero: JSON.parse(JSON.stringify(suTablero)) } : {}),
  };
}

/**
 * IMPORTAR UNA TIENDA de un JSON de `exportarTienda`. Entra como una tienda NUEVA —nunca pisa
 * una que ya exista—, SIN NÚMERO y SIN PÁGINA (como al duplicar: él le pone los suyos). Sus sub
 * pestañas van AL FINAL de cada lista (el bot recuerda por número qué intro le tocó a cada
 * cliente), los productos que no estén se agregan (los que ya estén, con el mismo id, no se
 * tocan) y su pizarra vuelve con las posiciones de sus fichas.
 */
function importarTienda(cfg: FullConfig, datos: unknown): { cfg: FullConfig; id: string; avisos: string[] } | { error: string } {
  const d = datos as {
    formato?: string;
    tienda?: TiendaEditor;
    productos?: ProductoEditor[];
    filaDeUpsell?: FilaDeUpsellEditor;
    fichas?: Array<{ canal: ChannelKey; piezaId: string; obj: Record<string, unknown> }>;
    vistas?: Record<string, DisposicionDePizarra>;
    tablero?: NonNullable<FullConfig["tableros"]>[string];
  } | null;
  if (!d || d.formato !== FORMATO_DE_TIENDA || !d.tienda) return { error: "Este archivo no es una tienda exportada desde aquí." };
  const id = `tienda_${Date.now().toString(36)}`;
  const avisos: string[] = [];
  let c: FullConfig = {
    ...cfg,
    tiendas: [
      ...(cfg.tiendas ?? []),
      { ...d.tienda, id, nombre: `${d.tienda.nombre?.trim() || "Tienda"} (importada)`, numero: "", pagina: "" },
    ],
  };
  // Los productos que faltan.
  const yaEstan = new Set((c.biblioteca_de_productos ?? []).map((p) => p?.id));
  const nuevos = (d.productos ?? []).filter((p) => p?.id && !yaEstan.has(p.id));
  if (nuevos.length > 0) c = { ...c, biblioteca_de_productos: [...(c.biblioteca_de_productos ?? []), ...nuevos] };
  // Su fila de upsells.
  if (d.filaDeUpsell) {
    c = {
      ...c,
      filas_de_upsell: [...(c.filas_de_upsell ?? []), { ...d.filaDeUpsell, id: `fila_${Date.now().toString(36)}`, tiendas: [id] }],
    };
  }
  // Sus sub pestañas, al final de cada lista, y cómo se renombra cada una.
  const mapa = new Map<string, string>();
  const mode = activeModality(c);
  for (const f of d.fichas ?? []) {
    const [tipo, a] = f.piezaId.split(":");
    const contenido = channelContentForMode(c, f.canal, mode);
    const largo =
      tipo === "intro"
        ? contenido.intro_groups.length
        : tipo === "ob"
          ? ((contenido.order_bump_intro_groups ?? []).length > 0 ? contenido.order_bump_intro_groups ?? [] : c.order_bump?.intro_groups ?? []).length
          : tipo === "up"
            ? ((contenido.upsell_intro_groups ?? []).length > 0 ? contenido.upsell_intro_groups ?? [] : c.upsell?.intro_groups ?? []).length
            : tipo === "seg"
              ? contenido.followups[Number(a)]?.variants?.length ?? -1
              : -1;
    if (largo <= 0) {
      avisos.push(`No se pudo traer «${String(f.obj?.name ?? f.piezaId)}»: en este bot no hay dónde ponerla.`);
      continue;
    }
    const u = ubicarPieza(c, f.canal, tipo === "seg" ? `seg:${a}:0` : `${tipo}:0`);
    if (!u) {
      avisos.push(`No se pudo traer «${String(f.obj?.name ?? f.piezaId)}».`);
      continue;
    }
    c = u.agregarAlFinal({ ...(f.obj as PiezaUbicada["obj"]), tiendas: [id] });
    mapa.set(f.piezaId, tipo === "seg" ? `seg:${a}:${largo}` : `${tipo}:${largo}`);
  }
  // Su pizarra, con los ids nuevos de sus fichas.
  const viejos = [...mapa.keys()].sort((x, y) => y.length - x.length);
  const renombrar = (texto: string) =>
    viejos.length === 0
      ? texto
      : texto.replace(
          new RegExp(`(^|[:|"])(${viejos.map((v) => v.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|")})(?=$|[:|"])`, "g"),
          (_m, antes: string, viejo: string) => `${antes}${mapa.get(viejo) ?? viejo}`
        );
  const vistas = Object.fromEntries(
    Object.entries(d.vistas ?? {}).map(([sufijo, v]) => [`${id}|${sufijo}`, JSON.parse(renombrar(JSON.stringify(v)))])
  );
  if (Object.keys(vistas).length > 0) c = { ...c, pizarra: { vistas: { ...(c.pizarra?.vistas ?? {}), ...vistas } } };
  // Su tablero, apagado como al duplicar: la tienda nueva no tiene número todavía.
  if (d.tablero && typeof d.tablero === "object") {
    const copia = JSON.parse(JSON.stringify(d.tablero)) as NonNullable<FullConfig["tableros"]>[string];
    for (const k of Object.keys(copia) as Array<keyof typeof copia>) {
      const tb = copia[k];
      if (tb) tb.encendido = false;
    }
    c = { ...c, tableros: { ...(c.tableros ?? {}), [id]: copia } };
  }
  return { cfg: c, id, avisos };
}

/**
 * LAS FICHAS DE UN ARCHIVO, PARA EL TABLERO (25/10/2026). Si el archivo trae su tablero de este
 * canal, ése; si es una tienda que se trabajó en la pizarra (sin tablero), se arma desde su pizarra
 * con `tableroDesdeLaPizarra`. Los productos que el archivo trae y aquí faltan se agregan (los que
 * ya están no se tocan), para que sus cobros y entregas tengan qué cobrar y qué entregar.
 */
function fichasDeUnArchivo(
  cfg: FullConfig,
  datos: unknown,
  canal: ChannelKey
): { cfg: FullConfig; tablero: TableroEnElEditor; avisos: string[] } | { error: string } {
  const d = datos as (TiendaExportada & { formato?: string; productos?: ProductoEditor[]; tablero?: NonNullable<FullConfig["tableros"]>[string] }) | null;
  if (!d || d.formato !== FORMATO_DE_TIENDA) return { error: "Este archivo no es una tienda exportada desde la pizarra o el tablero." };
  const yaEstan = new Set((cfg.biblioteca_de_productos ?? []).map((p) => p?.id));
  const nuevos = (d.productos ?? []).filter((p) => p?.id && !yaEstan.has(p.id));
  const c: FullConfig = nuevos.length > 0 ? { ...cfg, biblioteca_de_productos: [...(cfg.biblioteca_de_productos ?? []), ...nuevos] } : cfg;
  const avisos = nuevos.length > 0 ? [`Se agregaron ${nuevos.length} producto(s) que no estaban.`] : [];
  const suyo = d.tablero?.[canal as "whatsapp" | "messenger" | "instagram"];
  if (suyo && (suyo.fichas ?? []).length > 0) return { cfg: c, tablero: JSON.parse(JSON.stringify(suyo)) as TableroEnElEditor, avisos };
  const existen = new Set((c.biblioteca_de_productos ?? []).map((p) => p?.id).filter(Boolean) as string[]);
  const pago = (channelContentForMode(c, canal, activeModality(c)).payment ?? []) as unknown[];
  const nombres = Object.fromEntries((c.biblioteca_de_productos ?? []).filter((p) => p?.id).map((p) => [p.id, p.name ?? ""]));
  const r = tableroDesdeLaPizarra(d, canal, existen, pago, nombres);
  if (r.tablero.fichas.length === 0) return { error: r.avisos.join(" ") || "El archivo no trae nada que armar en este canal." };
  return { cfg: c, tablero: r.tablero as unknown as TableroEnElEditor, avisos: ["Armado desde su pizarra.", ...avisos, ...r.avisos] };
}

/** El «dirigir por país» encendido, en el nombre de campo que use esa lista. */
function conDirigirPorPais(u: PiezaUbicada): PiezaUbicada["obj"] {
  return u.camello ? { paisRoutingEnabled: true } : { pais_routing_enabled: true };
}

/**
 * SU NOMBRE, si se puede cambiar desde la pizarra (16/10/2026: «no hay manera de renombrar esa
 * pestaña… mejor cambiarla directamente ahí»). Los «mensajes principales» de un seguimiento
 * llevan el nombre del seguimiento entero, así que esos no: undefined.
 */
function nombreDePieza(cfg: FullConfig, canal: ChannelKey, piezaId: string): string | undefined {
  const u = ubicarPieza(cfg, canal, piezaId);
  return u && !u.esBase ? u.obj.name ?? "" : undefined;
}

function renombrarPieza(cfg: FullConfig, canal: ChannelKey, piezaId: string, nombre: string): FullConfig {
  const u = ubicarPieza(cfg, canal, piezaId);
  return u && !u.esBase ? u.poner({ ...u.obj, name: nombre }) : cfg;
}

/**
 * CONECTAR UNA FICHA AL CAMINO DE UN PAÍS = ponerle su bandera, la tienda, y encenderla.
 *
 * La tienda solo se añade si la ficha ya nombra tiendas: una ficha «🌐 todas las tiendas» ya
 * vale para ésta, y ponerle una tienda la QUITARÍA de las demás.
 */
function conectarPieza(
  cfg: FullConfig,
  canal: ChannelKey,
  piezaId: string,
  pais: string,
  tiendaId: string
): { cfg: FullConfig } | { error: string } {
  const u = ubicarPieza(cfg, canal, piezaId);
  if (!u) return { error: "No encontré esa ficha." };
  if (u.esBase) return { error: "Los «mensajes principales» se conectan en su sección de siempre." };
  if (!pais) return { error: "«Otros países» no se puede elegir con una bandera: conéctala a un país." };
  const paises = [...new Set([...(u.obj.paises ?? []), pais])];
  const tiendas = u.obj.tiendas ?? [];
  const conTienda = tiendas.length > 0 && tiendaId && !tiendas.includes(tiendaId) ? [...tiendas, tiendaId] : tiendas;
  return {
    cfg: u.poner({ ...u.obj, ...conDirigirPorPais(u), paises, tiendas: conTienda, enabled: true }),
  };
}

/**
 * ¿LA FICHA ES DE UN SEGUIMIENTO APAGADO ENTERO? Entonces conectarla no basta: no saldría
 * nunca. Encenderlo es de todo el canal, así que la pantalla lo pregunta antes. Las otras
 * tiendas no lo reciben si no tienen fichas propias en él: la tienda EXCLUYE.
 */
function seguimientoApagadoDe(cfg: FullConfig, canal: ChannelKey, piezaId: string): number | null {
  const [tipo, a] = piezaId.split(":");
  if (tipo !== "seg") return null;
  const f = channelContentForMode(cfg, canal, activeModality(cfg)).followups[Number(a)];
  return f && f.enabled === false ? Number(a) : null;
}

function encenderSeguimiento(cfg: FullConfig, canal: ChannelKey, indice: number): FullConfig {
  const mode = activeModality(cfg);
  const contenido = channelContentForMode(cfg, canal, mode);
  return {
    ...cfg,
    channels: {
      ...cfg.channels,
      [canal]: {
        ...(cfg.channels?.[canal] ?? {}),
        modality_templates: {
          ...(cfg.channels?.[canal]?.modality_templates ?? {}),
          [mode]: {
            ...contenido,
            followups: contenido.followups.map((x, j) => (j === indice ? { ...x, enabled: true } : x)),
          },
        },
      },
    },
  };
}

/** DESCONECTAR = quitarle esa bandera. Si se queda sin ninguna, se APAGA (regla 2). */
function desconectarPieza(
  cfg: FullConfig,
  canal: ChannelKey,
  piezaId: string,
  pais: string
): { cfg: FullConfig } | { error: string } {
  const u = ubicarPieza(cfg, canal, piezaId);
  if (!u) return { error: "No encontré esa ficha." };
  if (u.esBase) return { error: "Los «mensajes principales» se desconectan en su sección de siempre." };
  if (!pais) return { error: "En «Otros países» no hay bandera que quitar." };
  const paises = (u.obj.paises ?? []).filter((p) => p !== pais);
  return { cfg: u.poner({ ...u.obj, paises, ...(paises.length === 0 ? { enabled: false } : {}) }) };
}

function alternarPieza(cfg: FullConfig, canal: ChannelKey, piezaId: string): FullConfig | null {
  const u = ubicarPieza(cfg, canal, piezaId);
  if (!u) return null;
  return u.poner({ ...u.obj, enabled: u.obj.enabled === false });
}

/**
 * ELIMINAR UNA SUB PESTAÑA (17/10/2026): «necesito también poder eliminar las sub pestañas».
 *
 * Se quita de SU lista, del mismo sitio del que la lee el bot (ver `ubicarPieza`). Las de
 * detrás corren un puesto, igual que con «Quitar» en los menús. Los «mensajes principales» no:
 * son del seguimiento entero.
 */
function eliminarPieza(cfg: FullConfig, canal: ChannelKey, piezaId: string): { cfg: FullConfig } | { error: string } {
  const u = ubicarPieza(cfg, canal, piezaId);
  if (!u) return { error: "No encontré esa sub pestaña." };
  if (u.esBase) return { error: "Los «mensajes principales» se quitan en su sección de siempre." };
  const mode = activeModality(cfg);
  const contenido = channelContentForMode(cfg, canal, mode);
  const conContenido = (nuevo: ChannelContentEditor): FullConfig => ({
    ...cfg,
    channels: {
      ...cfg.channels,
      [canal]: {
        ...(cfg.channels?.[canal] ?? {}),
        modality_templates: { ...(cfg.channels?.[canal]?.modality_templates ?? {}), [mode]: nuevo },
      },
    },
  });
  const [tipo, a, b] = piezaId.split(":");
  const i = Number(a);
  const sin = <T,>(l: T[] | undefined, k: number) => (l ?? []).filter((_, j) => j !== k);
  if (tipo === "intro") return { cfg: conContenido({ ...contenido, intro_groups: sin(contenido.intro_groups, i) }) };
  if (tipo === "ob") {
    if ((contenido.order_bump_intro_groups ?? []).length > 0)
      return { cfg: conContenido({ ...contenido, order_bump_intro_groups: sin(contenido.order_bump_intro_groups, i) }) };
    return { cfg: { ...cfg, order_bump: { ...cfg.order_bump, intro_groups: sin(cfg.order_bump?.intro_groups, i) } } };
  }
  if (tipo === "up") {
    if ((contenido.upsell_intro_groups ?? []).length > 0)
      return { cfg: conContenido({ ...contenido, upsell_intro_groups: sin(contenido.upsell_intro_groups, i) }) };
    if (!cfg.upsell) return { error: "No encontré esa sub pestaña." };
    return { cfg: { ...cfg, upsell: { ...cfg.upsell, intro_groups: sin(cfg.upsell.intro_groups, i) } } };
  }
  if (tipo === "seg") {
    const vi = Number(b);
    return {
      cfg: conContenido({
        ...contenido,
        followups: contenido.followups.map((f, j) => (j === i ? { ...f, variants: sin(f.variants, vi) } : f)),
      }),
    };
  }
  return { error: "Esa no se puede eliminar desde aquí." };
}

/** DUPLICAR = una copia AL FINAL, apagada y sin banderas: nace suelta (reglas 1 y 2). */
/**
 * UNA COPIA LLEVA BOTONES CON SU PROPIO CÓDIGO (17/10/2026).
 *
 * El bot busca el botón pulsado por su código en todo el contenido y se queda con el PRIMERO
 * (`findBubbleButton`). Con el código copiado tal cual, el «Sí» de la copia de Argentina y el del
 * original de Perú eran el mismo para el bot: si él le cambiaba el texto a uno, el cliente podía
 * recibir el del otro. Ya pasó con los seguimientos el 27/09 (ver `elBotonDeSuSeguimiento`).
 * Solo cambia el código interno: la etiqueta, la acción y sus burbujas quedan idénticas.
 */
/**
 * UNA BURBUJA QUE ENTRA EN UNA LISTA, SIN BOTONES REPETIDOS (18/10/2026, el botón del DNI). Si
 * alguno de sus códigos ya está en esa lista (duplicar, o copiar y pegar en la misma ficha), la
 * copia recibe códigos nuevos: con dos iguales el bot ejecutaba el de la primera burbuja, aunque
 * estuviera apagada. Si no está (cortar y pegar = MOVER), conserva los suyos: un cliente que ya
 * la recibió sigue pudiendo tocarlos. Siempre devuelve una copia honda; el original no cambia.
 */
function sinBotonesRepetidos(paso: EditorStep, lista: EditorStep[]): EditorStep {
  const copia = JSON.parse(JSON.stringify(paso)) as EditorStep;
  const codigos = (v: unknown, a: Set<string>): Set<string> => {
    if (!v || typeof v !== "object") return a;
    if (Array.isArray(v)) {
      v.forEach((x) => codigos(x, a));
      return a;
    }
    const r = v as Record<string, unknown>;
    if (Array.isArray(r.buttons)) for (const b of r.buttons) if (typeof (b as { id?: unknown })?.id === "string") a.add((b as { id: string }).id);
    Object.values(r).forEach((x) => codigos(x, a));
    return a;
  };
  const yaEstan = codigos(lista, new Set());
  const repite = [...codigos(copia, new Set())].some((id) => yaEstan.has(id));
  return repite ? conBotonesNuevos(copia) : copia;
}

function conBotonesNuevos<T>(obj: T): T {
  const sufijo = Date.now().toString(36);
  let n = 0;
  const recorrer = (v: unknown): void => {
    if (!v || typeof v !== "object") return;
    if (Array.isArray(v)) {
      v.forEach(recorrer);
      return;
    }
    const r = v as Record<string, unknown>;
    if (Array.isArray(r.buttons)) {
      for (const b of r.buttons) {
        if (b && typeof b === "object" && typeof (b as { id?: unknown }).id === "string") {
          (b as { id: string }).id = `${(b as { id: string }).id.replace(/~c[0-9a-z]+$/, "")}~c${sufijo}${(n++).toString(36)}`;
        }
      }
    }
    Object.values(r).forEach(recorrer);
  };
  recorrer(obj);
  return obj;
}

function duplicarPieza(
  cfg: FullConfig,
  canal: ChannelKey,
  piezaId: string,
  /** LA COPIA, PARA LA FORMA DE VENDER QUE SE ESTÁ VIENDO (18/10/2026). Si la original es de
   *  otra semimodalidad, la copia lleva ésta: si no, la pizarra decía «duplícala y conecta la
   *  copia» y la copia tampoco se dejaba conectar (o, conectada, el bot no la mandaba). La
   *  original no se toca. */
  paraLaSemi?: string
): FullConfig | null {
  const u = ubicarPieza(cfg, canal, piezaId);
  if (!u || u.esBase) return null;
  const copia = conBotonesNuevos(JSON.parse(JSON.stringify(u.obj)) as PiezaUbicada["obj"]);
  // LA COPIA DE UN UPSELL ES OTRA VERSIÓN DEL MISMO (19/10/2026): «me dijiste que si copiaba el
  // upsell 1 se convertiría en un nuevo upsell diferente, eso no pasa». No pasa: ofrece el MISMO
  // producto, y al conectarla se sortea con la original. Su nombre lo dice. Un upsell con otro
  // producto se agrega con «+ Agregar upsell».
  const base = (u.obj.name || "Upsell").replace(/ · versión \d+$/, "");
  // La siguiente a la más alta que ya exista (hay varias con el mismo nombre, de otras tiendas
  // y semimodalidades: contarlas daba «versión 8»).
  const mayor = piezaId.startsWith("up:")
    ? Math.max(
        1,
        ...(channelContentForMode(cfg, canal, activeModality(cfg)).upsell_intro_groups ?? []).map((g) => {
          const m = (g?.name ?? "").match(/ · versión (\d+)$/);
          return m && (g?.name ?? "").startsWith(base) ? Number(m[1]) : 1;
        })
      )
    : 1;
  const nombre = piezaId.startsWith("up:")
    ? `${base} · versión ${mayor + 1}`
    : `${u.obj.name || "Ficha"} (copia)`;
  return u.agregarAlFinal({
    ...copia,
    name: nombre,
    enabled: false,
    paises: [],
    ...(paraLaSemi ? { semimodalidad: paraLaSemi } : {}),
    // SIN CAMINO (18/10/2026): duplicar es para abrir otro; lo recibe al conectarla.
    camino: undefined,
    tambien_en_caminos: undefined,
  });
}

/**
 * EL BOTÓN «+»: una ficha nueva, AL FINAL de su lista, APAGADA y sin banderas. Nombra a esta
 * tienda solo si su columna ya lo hace (ver `tiendasPara`). Nace suelta y él la conecta.
 */
type LoQueSeAgrega =
  | { tipo: "intro" }
  | { tipo: "ob" }
  | { tipo: "upsell" }
  | { tipo: "seguimiento"; indice: number }
  | { tipo: "seguimiento-nuevo" };

function agregarPieza(
  cfg: FullConfig,
  canal: ChannelKey,
  que: LoQueSeAgrega,
  tiendaId: string
): FullConfig | null {
  const mode = activeModality(cfg);
  const contenido = channelContentForMode(cfg, canal, mode);
  /**
   * ¿LA NUEVA NOMBRA A ESTA TIENDA? SOLO SI SU COLUMNA YA LO HACE (17/10/2026).
   *
   * Antes nacía siempre «solo de esta tienda», y eso rompió su GRAFISMO: la tienda EXCLUYE
   * —si una intro encendida la nombra, las 🌐 dejan de salir en ella—, así que conectar una
   * intro nueva a Argentina sacó de golpe las de Perú y Ecuador, que eran 🌐. Él: «no puede ser
   * que yo desconecte algo y se vaya a la mierda el workflow». Ahora la nueva imita a su
   * columna: si allí ya hay encendidas que nombran esta tienda, la nombra; si no, nace 🌐.
   */
  const tiendasPara = (lista: Array<{ enabled?: boolean; tiendas?: string[] }> | undefined): string[] =>
    tiendaId && (lista ?? []).some((x) => x?.enabled !== false && (x?.tiendas ?? []).includes(tiendaId))
      ? [tiendaId]
      : [];
  const conContenido = (nuevo: ChannelContentEditor): FullConfig => ({
    ...cfg,
    channels: {
      ...cfg.channels,
      [canal]: {
        ...(cfg.channels?.[canal] ?? {}),
        modality_templates: { ...(cfg.channels?.[canal]?.modality_templates ?? {}), [mode]: nuevo },
      },
    },
  });
  if (que.tipo === "intro") {
    return conContenido({
      ...contenido,
      intro_groups: [
        ...contenido.intro_groups,
        { name: "Intro nueva", steps: [emptyStep()], enabled: false, weight: 1, paises: [], tiendas: tiendasPara(contenido.intro_groups) },
      ],
    });
  }
  if (que.tipo === "ob") {
    const lista = (contenido.order_bump_intro_groups ?? []).length > 0 ? contenido.order_bump_intro_groups : cfg.order_bump?.intro_groups;
    const nueva: GrupoDeIntroEditor = { name: "Intro de order bump nueva", steps: [emptyStep()], enabled: false, weight: 1, paises: [], tiendas: tiendasPara(lista) };
    if ((contenido.order_bump_intro_groups ?? []).length > 0 || cfg.channels?.[canal]?.use_content === true) {
      return conContenido({
        ...contenido,
        order_bump_intro_groups: [...(contenido.order_bump_intro_groups ?? []), nueva],
      });
    }
    return { ...cfg, order_bump: { ...cfg.order_bump, intro_groups: [...(cfg.order_bump?.intro_groups ?? []), nueva] } };
  }
  if (que.tipo === "upsell") {
    const lista = (contenido.upsell_intro_groups ?? []).length > 0 ? contenido.upsell_intro_groups : cfg.upsell?.intro_groups;
    const nueva: GrupoDeIntroEditor = { name: "Upsell nuevo", steps: [emptyStep()], enabled: false, weight: 1, paises: [], tiendas: tiendasPara(lista) };
    // Al MISMO sitio del que lee el motor: si el canal ya tiene los suyos, ahí.
    if ((contenido.upsell_intro_groups ?? []).length > 0) {
      return conContenido({ ...contenido, upsell_intro_groups: [...(contenido.upsell_intro_groups ?? []), nueva] });
    }
    if (!cfg.upsell) return null;
    return { ...cfg, upsell: { ...cfg.upsell, intro_groups: [...(cfg.upsell.intro_groups ?? []), nueva] } };
  }
  if (que.tipo === "seguimiento") {
    const f = contenido.followups[que.indice];
    if (!f) return null;
    // Las variantes sin tienda heredan la del seguimiento entero: se mira con esa herencia.
    const variantes = (f.variants ?? []).map((v) => ({ ...v, tiendas: (v.tiendas ?? []).length > 0 ? v.tiendas : f.tiendas }));
    const nueva: EditorFollowupVariant = { name: `${f.name || `Seguimiento ${que.indice + 1}`} nuevo`, steps: [emptyStep()], enabled: false, paises: [], tiendas: tiendasPara(variantes) };
    return conContenido({
      ...contenido,
      followups: contenido.followups.map((x, j) => (j === que.indice ? { ...x, variants: [...(x.variants ?? []), nueva] } : x)),
    });
  }
  // UN SEGUIMIENTO NUEVO ENTERO, al final. Nace APAGADO entero: un turno nuevo es de todo el
  // canal, y no debe agendarse para nadie hasta que él lo conecte y lo encienda a sabiendas.
  const ultimo = contenido.followups[contenido.followups.length - 1];
  const n = contenido.followups.length + 1;
  return conContenido({
    ...contenido,
    followups: [
      ...contenido.followups,
      {
        name: `seguimiento_${n}`,
        delay_minutes_from_first_message: (ultimo?.delay_minutes_from_first_message ?? 0) + 60,
        enabled: false,
        steps: [],
        // Un seguimiento nuevo entero no tiene columna que imitar: nace 🌐, como los demás.
        variants: [{ name: `Seguimiento ${n}`, steps: [emptyStep()], enabled: false, paises: [], tiendas: [] }],
      },
    ],
  });
}

/** Las burbujas de una ficha, resumidas para leerlas en la pizarra. TODAS, también las
 *  apagadas y las vacías: el número de cada una es el que abre el pop up. */
function burbujasParaLaPizarra(steps: EditorStep[]): ResumenDeBurbuja[] {
  // SOLO LAS ENCENDIDAS (16/10/2026): «los off que no los muestre como tachado, que no
  // aparezcan». Se editan desde el cajón entero, que sí las enseña.
  return (steps ?? []).filter((s) => s.enabled !== false).map((s) => {
    const tipo: ResumenDeBurbuja["tipo"] =
      s.type === "text"
        ? "texto"
        : s.type === "image"
          ? "imagen"
          : s.type === "video"
            ? "video"
            : s.type === "audio"
              ? "audio"
              : "documento";
    const primero = (s.texts ?? []).find((t) => t.trim()) ?? "";
    const linea = primero.split("\n").map((l) => l.trim()).find(Boolean) ?? "";
    return {
      tipo,
      texto: linea.slice(0, 90),
      espera: Math.max(0, Number(s.delay_after_sec) || 0),
    };
  });
}

/**
 * LAS RAMAS DE UNA FICHA: sus botones y sus cuadritos de decisión, de las burbujas encendidas.
 *
 * El id lleva el número REAL de la burbuja —en la lista entera, no en la de encendidas—, para
 * que al cambiarla se escriba en la que es.
 */
function ramasParaLaPizarra(steps: EditorStep[]): RamaDePieza[] {
  return (steps ?? []).flatMap((s, i) =>
    s.enabled === false
      ? []
      : [
          ...(s.buttons ?? []).map((b) => ({
            id: `${i}:boton:${b.id}`,
            etiqueta: b.label,
            tipo: "boton" as const,
            accion: b.action === "send_steps" ? "" : b.action,
            mensajes: (b.steps ?? []).length,
          })),
          ...(s.decisions ?? [])
            .filter((d) => d.enabled !== false)
            .map((d) => ({
              id: `${i}:cuadrito:${d.id}`,
              etiqueta: d.title?.trim() || (d.keywords ?? []).slice(0, 3).join(", "),
              tipo: "cuadrito" as const,
              accion: d.action ?? "",
              mensajes: (d.steps ?? []).length,
              // Sin palabras clave el bot no lo activa nunca (`cuadritoDeLaIntroQueSeñala`).
              sinPalabras: !(d.keywords ?? []).some((k) => (k ?? "").trim()),
            })),
        ]
  );
}

/** «burbuja:tipo:id» → sus partes. El id del botón puede llevar «:», así que va el resto. */
function partesDeLaRama(ramaId: string): { burbuja: number; tipo: string; id: string } {
  const [b, tipo, ...resto] = ramaId.split(":");
  return { burbuja: Number(b), tipo, id: resto.join(":") };
}

/**
 * CAMBIAR A DÓNDE LLEVA UN BOTÓN O UN CUADRITO, desde la pizarra.
 *
 * Son las MISMAS acciones que se eligen en los menús; aquí solo cambia cómo se elige.
 *
 * UN BOTÓN HACE UNA SOLA COSA: o manda su mensaje, o hace una acción. La ruta de guardado solo
 * conserva las burbujas de un botón si su acción es «mensaje», así que pasarlo a otra cosa le
 * borraría el mensaje al guardar — se PREGUNTA antes. Un cuadrito puede tener las dos: primero
 * sus burbujas, después la acción.
 */
function cambiarDestinoDeRama(
  cfg: FullConfig,
  canal: ChannelKey,
  piezaId: string,
  ramaId: string,
  destino: DestinoDeRama,
  /** La tienda de la pizarra: en el regalo, cambia el SUYO. */
  tiendaId?: string,
  /** La pizarra ya avisó del cambio (20/10/2026): no se pregunta dos veces. */
  yaPreguntado = false
): { cfg: FullConfig } | { error: string } {
  const pieza = piezaEditable(cfg, canal, piezaId, tiendaId);
  if (!pieza) return { error: "No encontré esa ficha." };
  const { burbuja, tipo, id } = partesDeLaRama(ramaId);
  const paso = pieza.steps[burbuja];
  if (!paso) return { error: "No encontré esa burbuja." };
  let nuevoPaso: EditorStep = paso;
  if (tipo === "boton") {
    const boton = (paso.buttons ?? []).find((b) => b.id === id);
    if (!boton) return { error: "No encontré ese botón." };
    const accion: BubbleButtonAction = destino === "mensaje" ? "send_steps" : destino;
    if (
      !yaPreguntado &&
      boton.action === "send_steps" &&
      accion !== "send_steps" &&
      (boton.steps ?? []).length > 0 &&
      !window.confirm(
        `El botón «${boton.label}» manda un mensaje de ${(boton.steps ?? []).length} burbuja(s). Un botón hace una sola cosa: si lo llevas a otro destino, ese mensaje se borra al guardar. ¿Sigo?`
      )
    ) {
      return { error: "" };
    }
    nuevoPaso = {
      ...paso,
      buttons: (paso.buttons ?? []).map((b) => (b.id === id ? { ...b, action: accion } : b)),
    };
  } else {
    const cuadrito = (paso.decisions ?? []).find((d) => d.id === id);
    if (!cuadrito) return { error: "No encontré ese cuadrito." };
    // En el upsell el «no» escrito ya lo decide el bot; con la acción además se rechazaría dos veces.
    if (destino === "decline_upsell") return { error: "«Rechaza el UPSELL» es solo para botones." };
    nuevoPaso = {
      ...paso,
      decisions: (paso.decisions ?? []).map((d) =>
        d.id === id ? { ...d, action: destino === "mensaje" ? undefined : destino } : d
      ),
    };
  }
  return { cfg: pieza.conPasos(pieza.steps.map((s, i) => (i === burbuja ? nuevoPaso : s))) };
}

/** EL MENSAJE DE UNA RAMA, para escribirlo en su ventana. */
function ramaEditable(
  cfg: FullConfig,
  canal: ChannelKey,
  piezaId: string,
  ramaId: string,
  tiendaId?: string
): { etiqueta: string; steps: EditorStep[]; conPasos: (steps: EditorStep[]) => FullConfig } | null {
  const pieza = piezaEditable(cfg, canal, piezaId, tiendaId);
  if (!pieza) return null;
  const { burbuja, tipo, id } = partesDeLaRama(ramaId);
  const paso = pieza.steps[burbuja];
  if (!paso) return null;
  const conEsteMensaje = (steps: EditorStep[]): EditorStep =>
    tipo === "boton"
      ? { ...paso, buttons: (paso.buttons ?? []).map((b) => (b.id === id ? { ...b, action: "send_steps", steps } : b)) }
      : { ...paso, decisions: (paso.decisions ?? []).map((d) => (d.id === id ? { ...d, steps } : d)) };
  const actual =
    tipo === "boton"
      ? (paso.buttons ?? []).find((b) => b.id === id)
      : (paso.decisions ?? []).find((d) => d.id === id);
  if (!actual) return null;
  return {
    etiqueta:
      tipo === "boton"
        ? (actual as EditorBubbleButton).label
        : (actual as EditorBubbleDecision).title || "Cuadrito",
    steps: actual.steps ?? [],
    conPasos: (steps) => pieza.conPasos(pieza.steps.map((s, i) => (i === burbuja ? conEsteMensaje(steps) : s))),
  };
}

/**
 * DE SUS CAJONES AL MODELO DE LA PIZARRA.
 *
 * Lee el contenido del CANAL, que es de donde lee el bot cuando el canal usa lo suyo
 * (`use_content`). Las etiquetas se pasan tal cual a `loQueSaleEnLaEstacion`.
 *
 * LOS SEGUIMIENTOS HEREDAN COMO EN EL MOTOR (`chooseFollowupVariant`): el cajón manda, y si
 * no trae la suya vale la del seguimiento entero — bandera, semimodalidad y tiendas. Y los
 * «mensajes principales» cuentan como un cajón más mientras estén encendidos.
 */
function modeloDePizarra(
  cfg: FullConfig,
  canal: ChannelKey,
  tiendaId: string,
  semi: string,
  tiendas: TiendaEditor[],
  /** Países añadidos con «+ País», aunque todavía no tengan ninguna ficha. */
  paisesExtra: string[] = []
): ModeloDePizarra {
  const contenido = channelContentForMode(cfg, canal, activeModality(cfg));
  const nombreDeTienda = (id: string) =>
    tiendas.find((t) => t.id === id)?.nombre?.trim() || id;
  type Cruda = PiezaConEtiquetas & {
    id: string;
    tipo: TipoDePieza;
    titulo: string;
    steps: EditorStep[];
    anuncios: number;
    /** Su peso en el sorteo (17/10/2026). */
    peso?: number;
    /** Los anuncios puestos (claves), si el bot dirige esta ficha por anuncio. */
    adKeys?: string[];
    /** Su camino (18/10/2026). Vacío = el principal. Ver `etiqueta-de-camino.ts`. */
    camino?: string;
    /** Todos sus caminos (el suyo y los «también»). */
    caminos?: string[];
  };
  const conContenido = (p: Cruda) => compactSteps(p.steps ?? []).length > 0;

  // ── LAS PIEZAS, POR ESTACIÓN ────────────────────────────────────────────
  const intros: Cruda[] = contenido.intro_groups.map((g, i) => ({
    id: `intro:${i}`,
    tipo: "intro",
    titulo: g.name,
    steps: g.steps ?? [],
    enabled: g.enabled,
    paises: g.paises,
    // El editor lo escribe en camello aquí; la regla lo lee como el YAML.
    pais_routing_enabled: g.paisRoutingEnabled,
    semimodalidad: g.semimodalidad,
    tiendas: g.tiendas,
    anuncios: g.adRoutingEnabled === false ? 0 : (g.adKeys ?? []).length,
    peso: g.weight,
    adKeys: g.adRoutingEnabled === false ? [] : g.adKeys ?? [],
    camino: caminoDe(g),
    caminos: caminosDe(g),
  }));
  const deLaOferta = (
    (contenido.order_bump_intro_groups ?? []).length > 0
      ? contenido.order_bump_intro_groups ?? []
      : cfg.order_bump?.intro_groups ?? []
  ).map<Cruda>((g, i) => ({
    id: `ob:${i}`,
    tipo: "ob",
    titulo: g.name ?? `Intro de order bump ${i + 1}`,
    steps: g.steps ?? [],
    enabled: g.enabled,
    paises: g.paises,
    pais_routing_enabled: g.pais_routing_enabled,
    semimodalidad: g.semimodalidad,
    tiendas: g.tiendas,
    anuncios: 0,
    peso: g.weight,
    camino: caminoDe(g),
    caminos: caminosDe(g),
  }));
  const seguimientos = contenido.followups.map((f, fi) => {
    const baseBanderas = banderasDePieza(f);
    const piezas: Cruda[] = [];
    if (f.steps_enabled !== false && compactSteps(f.steps ?? []).length > 0) {
      piezas.push({
        id: `seg:${fi}:base`,
        tipo: "seguimiento",
        titulo: `${f.name || `Seguimiento ${fi + 1}`} · mensajes principales`,
        steps: f.steps,
        enabled: true,
        paises: baseBanderas,
        semimodalidad: f.semimodalidad,
        tiendas: f.tiendas,
        anuncios: f.ad_routing_enabled === false ? 0 : (f.ad_keys ?? []).length,
        peso: f.steps_weight,
        adKeys: f.ad_routing_enabled === false ? [] : f.ad_keys ?? [],
      });
    }
    (f.variants ?? []).forEach((v, vi) => {
      const propias = banderasDePieza(v);
      piezas.push({
        id: `seg:${fi}:${vi}`,
        tipo: "seguimiento",
        titulo: v.name || `${f.name || `Seguimiento ${fi + 1}`} · variante ${vi + 2}`,
        steps: v.steps ?? [],
        enabled: v.enabled,
        // LA HERENCIA DEL MOTOR, letra por letra: la del cajón, o si apagó su dirigir ninguna,
        // o la del seguimiento.
        paises:
          propias.length > 0 ? propias : v.pais_routing_enabled === false ? [] : baseBanderas,
        semimodalidad: (v.semimodalidad ?? "").trim() ? v.semimodalidad : f.semimodalidad,
        tiendas: (v.tiendas ?? []).length > 0 ? v.tiendas : f.tiendas,
        anuncios: v.ad_routing_enabled === false ? 0 : (v.ad_keys ?? []).length,
        peso: v.weight,
        adKeys: v.ad_routing_enabled === false ? [] : v.ad_keys ?? [],
        camino: caminoDe(v),
        caminos: caminosDe(v),
      });
    });
    return { f, fi, piezas };
  });

  // EL UPSELL, del MISMO sitio del que lo lee el motor (config.ts, al aplicar el canal): los
  // cajones del canal si tiene, si no los de la modalidad. Tiene banderas como la oferta, así
  // que va por carril; y lo sortea la MISMA función que la oferta (`sorteaCajonDeIntro`), que
  // es la que compara la prueba de la pizarra contra el motor.
  const delUpsell = (
    (contenido.upsell_intro_groups ?? []).length > 0
      ? contenido.upsell_intro_groups ?? []
      : cfg.upsell?.intro_groups ?? []
  ).map<Cruda>((g, i) => ({
    id: `up:${i}`,
    tipo: "upsell",
    titulo: g.name ?? `Upsell ${i + 1}`,
    steps: g.steps ?? [],
    enabled: g.enabled,
    paises: g.paises,
    pais_routing_enabled: g.pais_routing_enabled,
    semimodalidad: g.semimodalidad,
    tiendas: g.tiendas,
    anuncios: 0,
    peso: g.weight,
  }));
  const todas: Cruda[] = [
    ...intros,
    ...deLaOferta,
    ...seguimientos.flatMap((s) => s.piezas),
    ...delUpsell,
  ];
  // LOS QUE ÉL QUITÓ DE ESTA PIZARRA (19/10/2026) no se dibujan aquí, aunque otra tienda u otra
  // semimodalidad del canal los use. Volver a agregarlo con «+ País» lo devuelve.
  const quitados = new Set(vistaDeLaPizarra(cfg, tiendaId, canal, semi)?.quitados ?? []);
  const paises = [...new Set([...paisesConBandera(todas), ...paisesExtra])].filter((p) => !quitados.has(p));

  // ── CADA PIEZA, CON SU ESTADO EN ESTA TIENDA ────────────────────────────
  const enJuegoTotal = new Set<string>();
  /** Las piezas de un seguimiento apagado ENTERO: se ven apagadas aunque las suyas no lo estén. */
  const deUnApagadoEntero = new Set<string>();
  const estacion = (
    id: string,
    tipo: TipoDePieza,
    titulo: string,
    piezas: Cruda[],
    extra: Partial<EstacionDePizarra> = {},
    apagadaEntera = false
  ): EstacionDePizarra => {
    const conAlgo = piezas.filter(conContenido);
    if (apagadaEntera) piezas.forEach((p) => deUnApagadoEntero.add(p.id));
    const r = loQueSaleEnLaEstacion(
      apagadaEntera ? [] : conAlgo,
      tiendaId || null,
      semi,
      paises,
      // El interruptor de Ajustes, leído como lo lee el motor: ausente = encendido.
      cfg.globals?.respaldo_entre_paises !== false,
      cfg.globals?.respaldo_entre_tiendas !== false
    );
    r.enJuego.forEach((p) => enJuegoTotal.add(p.id));
    // LAS APAGADAS, EN SU PAÍS (20/10/2026): «las fichas apagadas deberían mostrar su cable y
    // conexiones». Las de esta tienda y esta semimodalidad que nombran el país y no salen (apagadas,
    // vacías o de un seguimiento apagado entero). Solo para dibujar: no cuentan en nada más.
    // SOLO LAS QUE SALDRÍAN SI ESTUVIERAN ENCENDIDAS (20/10/2026): se pregunta a la MISMA regla del
    // bot con todas encendidas. Así no se cuela una de otra tienda, «de todas las tiendas» o sin
    // semimodalidad que aquí no saldría nunca (salió así una vez y parecía conectada).
    const enJuegoAqui = new Set(r.enJuego.map((p) => p.id));
    const saldrian = new Set(
      loQueSaleEnLaEstacion(
        piezas.map((p) => ({ ...p, enabled: true })),
        tiendaId || null,
        semi,
        paises,
        cfg.globals?.respaldo_entre_paises !== false,
        cfg.globals?.respaldo_entre_tiendas !== false
      ).enJuego.map((p) => p.id)
    );
    // SOLO LAS QUE ÉL APAGÓ DESDE LA PIZARRA (20/10/2026): «¿yo te pedí que agregues algo a la
    // pizarra? o te dije que lo que ya estaba ahí, al desconectarse o conectarse, se quede». Dibujar
    // TODAS las apagadas con bandera puso en Perú fichas viejas apagadas con cables que él no hizo:
    // parecían conectadas solas. Ahora solo se queda en su sitio la que él apaga aquí.
    const quedanAqui = new Set(vistaDeLaPizarra(cfg, tiendaId, canal, semi)?.quedanApagadas ?? []);
    // Y LAS QUE ÉL DESCONECTÓ DE ESTE PAÍS (el plano, 20/10/2026): salieron del país en el bot, pero
    // se siguen dibujando en su sitio, desconectadas, con sus cables.
    const desconectadasAqui = new Set(
      (vistaDeLaPizarra(cfg, tiendaId, canal, semi)?.cortesDeRuta ?? [])
        .map(leerCorte)
        .filter((x): x is CorteDeRuta => !!x && x.quitado)
        .map((x) => `${x.pais}|${x.hacia}`)
    );
    const apagadasDe = (pais: string, enLaFila: string[]) => [
      ...piezas.filter((p) => desconectadasAqui.has(`${pais}|${p.id}`) && !enLaFila.includes(p.id)).map((p) => p.id),
      ...apagadasDeVerdad(pais).filter((id) => !enLaFila.includes(id) && !desconectadasAqui.has(`${pais}|${id}`)),
    ];
    const apagadasDeVerdad = (pais: string) =>
      piezas
        .filter(
          (p) =>
            quedanAqui.has(p.id) &&
            !enJuegoAqui.has(p.id) &&
            saldrian.has(p.id) &&
            !p.id.endsWith(":base") &&
            (p.enabled === false || !conContenido(p) || apagadaEntera) &&
            (p.paises ?? []).includes(pais)
        )
        .map((p) => p.id);
    const filas = [
      ...r.porPais.map((f) => ({
        clave: f.pais,
        etiqueta: `Si país = ${banderaTexto(f.pais)}`,
        estado: f.estado,
        piezas: f.piezas.map((p) => p.id),
        apagadas: apagadasDe(f.pais, f.piezas.map((p) => p.id)),
      })),
      {
        clave: "",
        etiqueta: paises.length > 0 ? "Ninguna de las condiciones" : "Todos los países",
        estado: r.ninguna.estado,
        piezas: r.ninguna.piezas.map((p) => p.id),
      },
    ];
    return { id, tipo, titulo, filas, piezas: piezas.map((p) => p.id), ...extra };
  };
  const estaciones: EstacionDePizarra[] = [
    estacion("intro", "intro", "Intro", intros, {
      cuando: "Al primer mensaje",
      siQuedaVacia: "Si no queda ninguna, sale la intro de siempre de la modalidad.",
    }),
  ];
  // EL ORDEN ES EL DEL CAMINO, de izquierda a derecha: intro, los seguimientos mientras no
  // compra, y la intro de order bump cuando elige método. Lo pidió así el 16/10/2026: «que
  // vaya hacia la derecha tipo Sendy… justo como armaste tu mapa».
  for (const { f, fi, piezas } of seguimientos) {
    estaciones.push(
      estacion(
        `seg:${fi}`,
        "seguimiento",
        f.name || `Seguimiento ${fi + 1}`,
        piezas,
        {
          cuando:
            f.enabled === false
              ? "Apagado entero: no se agenda"
              : `⏱ ${formatearMinutos(f.delay_minutes_from_first_message)} desde el 1.er mensaje`,
          siQuedaVacia: "Si no queda ninguno, este seguimiento no se envía.",
        },
        f.enabled === false
      )
    );
  }
  if (semi === "segunda_oculta") {
    estaciones.push(
      estacion("ob", "ob", "Intro de order bump", deLaOferta, {
        cuando: "Al elegir método o querer pagar",
        siQuedaVacia: "Si no queda ninguna, sale la intro de order bump de siempre.",
      })
    );
  }
  // EL UPSELL VA DESPUÉS: se ofrece tras entregar lo que compró. Solo se dibuja si la etapa
  // está encendida o ya tiene cajones; apagada no sale nunca, y se dice en su cabecera.
  const upsellEncendido = cfg.upsell?.enabled === true;
  if (upsellEncendido || delUpsell.length > 0) {
    estaciones.push(
      estacion(
        "upsell",
        "upsell",
        "Upsell",
        delUpsell,
        {
          cuando: upsellEncendido ? "Después de entregar" : "Etapa upsell APAGADA: no se ofrece",
          siQuedaVacia: "Si no queda ninguno, sale la intro del upsell de siempre.",
        },
        !upsellEncendido
      )
    );
  }

  // ── LAS PIEZAS PARA DIBUJAR ─────────────────────────────────────────────
  const piezas: PiezaDePizarra[] = todas.map((p) => {
    const suyas = (p.tiendas ?? []).filter(Boolean);
    const apagada =
      p.enabled === false || !conContenido(p) || deUnApagadoEntero.has(p.id);
    const juega = enJuegoTotal.has(p.id);
    const deOtra = suyas.length > 0 && !suyas.includes(tiendaId);
    const suSemi = semimodalidadDe({ semimodalidad: p.semimodalidad });
    return {
      id: p.id,
      tipo: p.tipo,
      titulo: p.titulo,
      // DE OTRA FORMA DE VENDER (18/10/2026): «regresé de COMOHOY a COMO OB y veo cuadros que se
      // han filtrado». La pizarra no la dibuja suelta en esta vista; en la suya sigue igual.
      deOtraSemi: !!suSemi && suSemi !== laSemimodalidadDeLaTienda({ semimodalidad: semi }),
      estado: apagada ? "apagada" : juega ? "juega" : "fuera",
      motivo: apagada
        ? !conContenido(p)
          ? "Sin burbujas con contenido"
          : deUnApagadoEntero.has(p.id)
            ? p.tipo === "upsell"
              ? "La etapa upsell está apagada"
              : "Su seguimiento está apagado entero"
            : "Apagada"
        : juega
          ? undefined
          : deOtra
            ? `Es de ${suyas.map(nombreDeTienda).join(", ")}`
            : (p.semimodalidad ?? "").trim()
              ? "No es de la semimodalidad de esta tienda"
              : "Esta tienda tiene piezas propias: la general no juega",
      paises: banderasDePieza(p),
      todasLasTiendas: suyas.length === 0,
      otrasTiendas: suyas.filter((t) => t !== tiendaId).map(nombreDeTienda),
      semimodalidad: (p.semimodalidad ?? "").trim() || undefined,
      // SU CAMINO (18/10/2026): la pizarra une cada ficha con las de su camino.
      camino: p.camino || undefined,
      caminos: p.caminos && !(p.caminos.length === 1 && p.caminos[0] === "") ? p.caminos : undefined,
      burbujas: compactSteps(p.steps ?? []).length,
      resumen: burbujasParaLaPizarra(p.steps ?? []),
      ramas: ramasParaLaPizarra(p.steps ?? []),
      editable: true,
      anuncios: p.anuncios,
      peso: typeof p.peso === "number" && p.peso >= 1 ? Math.floor(p.peso) : 1,
      // Los nombres, del Gestor de Ads. Una clave que ya no está se enseña tal cual: no se esconde.
      anunciosNombres: (p.adKeys ?? []).map(
        (k) => (cfg.ad_registry ?? []).find((a) => a.key === k)?.name?.trim() || k
      ),
      admiteAnuncios: p.tipo === "intro" || p.tipo === "seguimiento",
    };
  });

  // ── LA POSTVENTA: la entrega de cada producto que juega esta tienda, y el regalo ──
  //
  // Los productos son los de los puestos que entregan —el único, el básico y el full— de SU
  // tienda, o los de la modalidad si la tienda no dice. Es lo mismo que enseña «Ver
  // recorrido» en su columna de entregas, sin repetidos.
  const suTienda = tiendas.find((t) => t.id === tiendaId);
  // COMO EL BOT, NO MEZCLADO (17/10/2026): `laAlineacionQueJuega` usa la de la tienda si tiene
  // alguna, y si no la general — nunca las dos juntas. Mezclada, a GRAFISMO (sin upsell en su
  // tienda) se le dibujaba el upsell general, y el bot no se lo ofrecía.
  const deLaTienda = Object.fromEntries(Object.entries(suTienda?.alineacion ?? {}).filter(([, v]) => v));
  const alineados = (
    Object.keys(deLaTienda).length > 0 ? deLaTienda : cfg.alineacion_por_modalidad?.[activeModality(cfg)] ?? {}
  ) as Record<string, string | undefined>;
  const puestos = semi ? ["basico", "full"] : ["unico"];
  const almacen = cfg.biblioteca_de_productos ?? [];
  // Con SU PUESTO: con dos productos, cada uno tiene su pago y su entrega, y la elección de la
  // intro de order bump lleva a uno o al otro (17/10/2026).
  const vistos = new Set<string>();
  const entregas = puestos.flatMap((puesto) => {
    const id = alineados[puesto];
    const p = id && !vistos.has(id) ? almacen.find((x) => x?.id === id) : undefined;
    if (!p) return [];
    vistos.add(p.id);
    return [
      {
        id: `entrega:${p.id}`,
        puesto: puesto as "unico" | "basico" | "full",
        nombre: p.name?.trim() || "Producto",
        resumen: burbujasParaLaPizarra((p.delivery ?? []) as EditorStep[]),
      },
    ];
  });
  // LA ENTREGA DEL CANAL PISA LA DE TODAS LAS FICHAS si está encendida y tiene algo que mandar
  // (config.ts, `applyChannelContent`: va DESPUÉS del reparto por etiquetas). Con varias
  // tiendas eso es entregarles a todas lo mismo, así que se avisa en la pizarra.
  const centralDelCanal = (contenido.delivery_groups ?? []).find((g) => g.key === "central");
  const entregaDelCanal =
    !!centralDelCanal && centralDelCanal.enabled !== false && compactSteps(centralDelCanal.steps ?? []).length > 0;
  // EL PAGO: el PRECIO sale de la ficha del producto, por el país del cliente; las CUENTAS, del
  // cobrador de la tienda —sus cuentas por país— o, sin cobrador, de las de cada país.
  // (16/10/2026: el texto decía «Precios y pagos» para el precio, y eso no es así.)
  const cobrador = (cfg.cobradores ?? []).find((c) => c.id === suTienda?.cobrador);
  // QUIÉN COBRA EN CADA PAÍS (17/10/2026): «sigo viendo a Carlos Quimí en los 3 países». La
  // tarjeta decía el cobrador de la tienda en todos; el bot cobra con la cuenta de ese país.
  const pagoPorPais = Object.fromEntries(
    paises.map((p) => [p, `Precio: el de la ficha, por su país. Cobra: ${quienCobraEn(cfg, suTienda, p).nombre || "(sin cuenta en este país)"}.`])
  );
  const pago = cobrador
    ? `Precio: el de la ficha, por su país. Cuentas: las de ${cobrador.nombre?.trim() || "su cobrador"} para su país.`
    : "Precio: el de la ficha, por su país. Cuentas: las de su país (esta tienda no tiene cobrador).";

  // EL UPSELL: su producto y su entrega salen de la ficha que juega de upsell en esta tienda;
  // sus botones Sí / No son del canal, o de la etapa si el canal no dice.
  const idDelUpsell = alineados["upsell"];
  const productoUpsell = idDelUpsell ? almacen.find((p) => p?.id === idDelUpsell) : undefined;
  const conBotones = contenido.upsell_use_buttons ?? cfg.upsell?.use_buttons === true;
  const upsell = productoUpsell
    ? {
        entregaId: `entrega:${productoUpsell.id}`,
        nombre: productoUpsell.name?.trim() || "Producto upsell",
        entrega: burbujasParaLaPizarra((productoUpsell.delivery ?? []) as EditorStep[]),
        si: conBotones ? contenido.upsell_boton_si?.trim() || cfg.upsell?.boton_si?.trim() || "Sí" : "Dice que sí",
        no: conBotones ? contenido.upsell_boton_no?.trim() || cfg.upsell?.boton_no?.trim() || "No" : "Dice que no",
      }
    : undefined;
  // LOS UPSELLS EN FILA de esta tienda (o la fila general), detrás del upsell 1.
  const filas = (cfg.filas_de_upsell ?? []).filter((f) => f.enabled !== false);
  const suFila = filas.find((f) => (f.tiendas ?? []).includes(tiendaId)) ?? filas.find((f) => (f.tiendas ?? []).length === 0);
  // TAMBIÉN LOS APAGADOS (17/10/2026): ahora se manejan desde la pizarra, y uno apagado se tiene
  // que poder volver a encender. Se dibujan tenues y el camino no pasa por ellos, como el bot.
  const enFila = (suFila?.puestos ?? []).flatMap((p, puesto) => {
    const prod = almacen.find((x) => x?.id === p.producto_id);
    if (!prod) return [];
    const falta = loQueLeFaltaEnLaFila(cfg, prod);
    return [
      {
        // Su lugar REAL en la fila guardada: los mandos escriben ahí, aunque falte algún producto.
        puesto,
        entregaId: `entrega:${prod.id}`,
        productoId: prod.id,
        nombre: prod.name?.trim() || "Producto",
        minutos: p.minutos,
        encendido: p.enabled !== false,
        entrega: burbujasParaLaPizarra((prod.delivery ?? []) as EditorStep[]),
        // Lo mismo que avisa el menú Upsell: sin esto, el bot lo salta.
        aviso: falta.sinPresentacion
          ? "⚠ Sin presentación como upsell: el bot lo salta."
          : falta.sinEntrega
            ? "⚠ Sin entrega: el bot lo salta."
            : falta.paisesSinPrecio.length > 0
              ? `⚠ Sin precio en ${falta.paisesSinPrecio.join(", ")}: ahí lo salta.`
              : undefined,
      },
    ];
  });
  // Los que se pueden agregar detrás: cualquier producto que no sea ya el upsell 1 ni esté en la fila.
  const enLaFila = new Set(enFila.map((f) => f.productoId));
  const paraLaFila = almacen
    .filter((p) => p?.id && p.id !== idDelUpsell && !enLaFila.has(p.id))
    .map((p) => ({ id: p.id, nombre: p.name?.trim() || "Producto" }));
  const g = cfg.gift;
  // EL REGALO DE ESTA TIENDA, campo a campo encima del general (17/10/2026), como lo lee el bot
  // (`conElRegaloDeLaTienda`).
  const rgT = suTienda?.regalo;
  const consentimiento = (rgT?.consent_sequence ?? []).length > 0 ? rgT!.consent_sequence! : g?.consent_sequence ?? [];
  const pedidoSuyo = (rgT?.ask_sequence ?? []).length > 0 ? rgT!.ask_sequence! : g?.ask_sequence ?? [];
  return {
    estaciones,
    piezas,
    postventa: {
      entregas,
      regalo: {
        encendido: g?.has === true,
        deEstaTienda: !!rgT && Object.keys(rgT).length > 0,
        resumen: burbujasParaLaPizarra(consentimiento),
        // Sus botones y cuadritos, para dibujarlos con su cable (17/10/2026).
        ramas: ramasParaLaPizarra(consentimiento),
        acepta: g?.consent_buttons_enabled ? g.consent_yes_label?.trim() || "Acepta" : "Acepta",
        noQuiere: g?.consent_buttons_enabled ? g.consent_no_label?.trim() || "No quiere" : "No quiere",
        pedido:
          pedidoSuyo.length > 0
            ? burbujasParaLaPizarra(pedidoSuyo)
            : g?.ask_text?.trim()
              ? [{ tipo: "texto" as const, texto: g.ask_text.trim(), espera: 0 }]
              : [],
        pedidoEditable: pedidoSuyo.length > 0,
        premio: (rgT?.reward_message?.trim() || g?.reward_message?.trim()) ?? "",
        despedida: (rgT?.decline_message?.trim() || g?.decline_message?.trim()) ?? "",
      },
      entregaDelCanal,
      pago,
      pagoPorPais,
      upsell: upsell ? { ...upsell, nativos: conBotones } : undefined,
      // EL UPSELL 1 APAGADO, con su producto guardado (19/10/2026). Ver `alternarUpsell1`.
      upsellApagado: (() => {
        if (upsell) return undefined;
        const guardado = almacen.find((p) => p?.id === suTienda?.upsell_apagado);
        return guardado ? { nombre: guardado.name?.trim() || "Producto upsell" } : undefined;
      })(),
      enFila,
      paraLaFila,
      productosParaElUpsell: almacen
        .filter((p) => p?.id && !Object.values(alineados).includes(p.id))
        .map((p) => ({ id: p.id, nombre: p.name?.trim() || "Producto" })),
      regaloConBotones: g?.consent_buttons_enabled === true,
    },
  };
}

/**
 * LA FILA DE UPSELLS DE ESTA TIENDA, CAMBIADA (17/10/2026).
 *
 * La misma que enseña la pizarra y la que el bot le aplica (`filaDeLaConversacion`): la suya si
 * tiene, si no la general. Si es la GENERAL, no se toca: se le hace a esta tienda una copia
 * propia con lo mismo (puestos y downsell) y se cambia ésa. Así las otras tiendas siguen
 * exactamente igual — «cada pizarra es de su tienda». Si no hay ninguna, se crea la suya.
 */
function conLaFilaDeLaTienda(
  c: FullConfig,
  tiendaId: string,
  cambiar: (puestos: NonNullable<FilaDeUpsellEditor["puestos"]>) => NonNullable<FilaDeUpsellEditor["puestos"]>
): FullConfig {
  const filas = [...(c.filas_de_upsell ?? [])];
  const encendidas = filas.filter((f) => f.enabled !== false);
  let i = tiendaId ? filas.indexOf(encendidas.find((f) => (f.tiendas ?? []).includes(tiendaId)) as FilaDeUpsellEditor) : -1;
  if (i < 0) {
    const general = encendidas.find((f) => (f.tiendas ?? []).length === 0);
    filas.push({
      id: `fila-${Date.now().toString(36)}`,
      enabled: true,
      tiendas: tiendaId ? [tiendaId] : [],
      puestos: general ? JSON.parse(JSON.stringify(general.puestos ?? [])) : [],
      ...(general?.downsell ? { downsell: JSON.parse(JSON.stringify(general.downsell)) } : {}),
    });
    i = filas.length - 1;
  }
  filas[i] = { ...filas[i], puestos: cambiar([...(filas[i].puestos ?? [])]) };
  return { ...c, filas_de_upsell: filas };
}

/**
 * LOS MINUTOS DE UN SEGUIMIENTO, cambiados desde su tarjeta de la pizarra (17/10/2026). Es el
 * mismo campo que «🕒 Delay (min)» de Canales: `delay_minutes_from_first_message` del seguimiento
 * entero, en el contenido del canal. Se escribe igual que `piezaEditable`.
 */
function conMinutosDelSeguimiento(cfg: FullConfig, canal: ChannelKey, fi: number, minutos: number): FullConfig {
  const mode = activeModality(cfg);
  const contenido = channelContentForMode(cfg, canal, mode);
  if (!contenido.followups[fi]) return cfg;
  return {
    ...cfg,
    channels: {
      ...cfg.channels,
      [canal]: {
        ...(cfg.channels?.[canal] ?? {}),
        modality_templates: {
          ...(cfg.channels?.[canal]?.modality_templates ?? {}),
          [mode]: {
            ...contenido,
            followups: contenido.followups.map((f, i) =>
              i === fi ? { ...f, delay_minutes_from_first_message: minutos } : f
            ),
          },
        },
      },
    },
  };
}

function banderaTexto(codigo: string): string {
  const opcion = COUNTRY_OPTIONS.find((o) => o.code === codigo);
  return opcion ? opcion.label : codigo;
}

function formatearMinutos(min: number | undefined): string {
  const m = Math.max(0, Math.round(Number(min) || 0));
  if (m < 60) return `${m} min`;
  if (m < 60 * 24) return `${+(m / 60).toFixed(1)} h`;
  return `${+(m / 60 / 24).toFixed(1)} d`;
}

function JourneyStepEditorModal({
  title,
  steps,
  stepIndex,
  previewContext,
  priceSoles,
  comboPrice,
  basicoPrice,
  previewPriceOverride,
  previewComboPriceOverride,
  previewBasicoPriceOverride,
  onChange,
  onClose,
}: {
  title: string;
  steps: EditorStep[];
  stepIndex: number;
  previewContext: PreviewContext;
  priceSoles?: number;
  comboPrice?: number;
  basicoPrice?: number;
  previewPriceOverride?: number;
  previewComboPriceOverride?: number;
  previewBasicoPriceOverride?: number;
  onChange: (steps: EditorStep[]) => void;
  onClose: () => void;
}) {
  // SE EDITA UN BORRADOR, no la burbuja de verdad.
  //
  // Antes cada tecla escribía directamente en la configuración, así que salir
  // con Escape o haciendo clic fuera dejaba el cambio hecho igual que el botón
  // "Listo". Los tres botones hacían lo mismo y no había forma de arrepentirse.
  //
  // Ahora se trabaja sobre una copia: "Listo" la aplica, y salir por cualquier
  // otro lado la descarta. La vista previa de al lado lee el borrador, así que
  // se sigue viendo lo que se escribe mientras se escribe.
  const [borrador, setBorrador] = useState<EditorStep[]>(steps);
  // EL MEZCLADOR DEL CAJÓN, QUE AQUÍ NO HACÍA NADA.
  //
  // El botón «∞» del cajón pide otra combinación del spintax. En la lista se lo
  // dice al visor; aquí se le pasaba una función vacía, así que se podía pulsar
  // las veces que fuera y el texto de al lado no se movía. No daba ningún
  // error: simplemente no pasaba nada.
  //
  // El visor de esta ventana enseña UNA burbuja, así que su tirada va siempre
  // en el sitio 0.
  const [tirada, setTirada] = useState(0);
  // Al cambiar de burbuja se empieza de nuevo desde lo guardado.
  useEffect(() => {
    setBorrador(steps);
    setTirada(0);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stepIndex]);

  const aplicarYCerrar = () => {
    onChange(borrador);
    onClose();
  };

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      // Escape DESCARTA: no se llama a onChange.
      onClose();
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [onClose]);
  const step = borrador[stepIndex];
  if (!step) return null;
  const update = (patch: Partial<EditorStep>) => {
    setBorrador((previo) =>
      previo.map((item, index) =>
        index === stepIndex ? { ...item, ...patch } : item
      )
    );
  };
  return (
    <div
      className="fixed inset-0 z-[60] flex items-center justify-center bg-black/55 p-3"
      role="dialog"
      aria-modal="true"
      aria-label="Editar burbuja"
      onMouseDown={(event) => {
        if (!EL_CLIC_FUERA_CIERRA_LA_VENTANA) return;
        if (event.target === event.currentTarget) onClose();
      }}
    >
      {/* MÁS ANCHA, PERO EL WHATSAPP NO SE ESTIRA.
          La ventana pasa a ocupar casi toda la pantalla porque ahora lleva el
          cajón entero. La columna de la derecha se queda en 420 px: el visor es
          un teléfono, y un teléfono ancho enseña unos renglones que al cliente
          no le van a llegar así. Lo que crece es el sitio donde se escribe. */}
      <div className="flex max-h-[92vh] w-full max-w-[1050px] flex-col overflow-hidden rounded-lg bg-tarjeta shadow-2xl">
        <div className="flex items-center justify-between gap-3 border-b border-neutral-200 px-4 py-3">
          <div><h3 className="text-sm font-bold text-neutral-900">Editar esta burbuja</h3><p className="text-xs text-neutral-500">{title}</p></div>
          <div className="flex items-center gap-2">
            <span className="hidden text-[11px] text-neutral-500 sm:inline">
              Escape o Cancelar = descartar
            </span>
            <button type="button" onClick={onClose} className="rounded border border-neutral-300 px-3 py-1.5 text-xs font-semibold text-neutral-600 hover:bg-neutral-50">Cancelar</button>
            <button type="button" onClick={aplicarYCerrar} className="rounded bg-emerald-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-emerald-700">Guardar</button>
          </div>
        </div>
        {/* CADA COLUMNA CON SU PROPIO DESPLAZAMIENTO.
            Antes se desplazaba la ventana ENTERA: para llegar al final del
            editor había que arrastrar también el visor, y el visor se iba de la
            pantalla justo cuando hacía falta mirarlo.
            Ahora la izquierda tiene su barra y el visor se queda quieto. */}
        <div className="grid min-h-0 flex-1 gap-4 p-4 lg:grid-cols-[minmax(0,1fr)_minmax(260px,340px)]">
          <div className="min-h-0 overflow-y-auto pr-2">
            {/* EL MISMO CAJÓN QUE EN LA LISTA, NO UNA COPIA.
                Aquí había un editor hecho a mano con cuatro campos: tipo,
                enlace, variantes y encendido. El cajón de la lista tiene además
                el retardo, los botones, los cuadritos de decisión con su plazo y
                la pregunta del nombre. Quien abría la ventana para editar «todo»
                editaba menos que sin abrirla.
                El DndContext es solo la cáscara que el cajón necesita para sus
                asas de arrastrar; aquí no hay nada que reordenar.
                Lleva `id` FIJO a propósito: sin él se genera uno nuevo y el
                cajón de dentro se vuelve a montar, y al montarse otra vez los
                campos numéricos pierden lo que se estaba tecleando. */}
            <DndContext id="ventana-de-la-burbuja">
              <StepCard
                key="ventana-de-la-burbuja"
                draggableId={`ventana-burbuja-${stepIndex}`}
                droppableId={`ventana-burbuja-drop-${stepIndex}`}
                index={stepIndex}
                total={borrador.length}
                step={step}
                isDragging={false}
                isDragTarget={false}
                isActive={false}
                onUpdate={update}
                onMove={() => {}}
                onActivate={() => {}}
                onDuplicate={() => {}}
                onRemove={() => {}}
                onVaryPreview={() => setTirada((n) => n + 1)}
                /**
                 * ESCRIBIR EN UNA BURBUJA QUE NO TIENE NINGÚN TEXTO.
                 *
                 * LO QUE CONTÓ EL DUEÑO — 21 de septiembre de 2026:
                 *
                 *   «Yo duplico una burbuja que contiene solo una imagen, a la
                 *    copia le doy click derecho, editar burbuja, se abre el pop
                 *    up y NO PUEDO EDITAR EL TEXTO.»
                 *
                 * QUÉ PASABA. Una burbuja de imagen sin pie llega con la lista
                 * de textos VACÍA. Aquí se recorría esa lista con `.map` para
                 * cambiar el de la posición que se estaba tecleando — y recorrer
                 * una lista vacía devuelve otra lista vacía. Cada tecla escribía
                 * `[]`, así que lo escrito no entraba nunca y la casilla volvía
                 * a salir en blanco.
                 *
                 * No daba ningún error: simplemente no pasaba nada.
                 *
                 * ESTA MISMA FUNCIÓN YA ESTABA RESUELTA EN LA LISTA
                 * (`updateText` de `StepList`), con este mismo guardia y por
                 * este mismo motivo — su comentario lo dice: «una burbuja podía
                 * quedarse con la lista de textos vacía... al teclear hay que
                 * crear el hueco en vez de recorrer una lista que no tiene
                 * nada». La ventana era una segunda copia a la que nunca le
                 * llegó el arreglo. Por eso desde la lista se podía escribir y
                 * desde la ventana no.
                 *
                 * Medido antes de tocar, con las dos funciones sacadas del
                 * archivo y ejecutadas: con la lista vacía, la de la lista
                 * devolvía ["lo escrito"] y la de la ventana devolvía [].
                 */
                onUpdateText={(ti, value) =>
                  update({
                    texts: step.texts.length
                      ? step.texts.map((item, index) =>
                          index === ti ? value : item
                        )
                      : [value],
                  })
                }
                onAddText={() => update({ texts: [...step.texts, ""] })}
                onDuplicateText={(ti) =>
                  update({
                    texts: [
                      ...step.texts.slice(0, ti + 1),
                      step.texts[ti] ?? "",
                      ...step.texts.slice(ti + 1),
                    ],
                  })
                }
                onRemoveText={(ti) =>
                  update({ texts: step.texts.filter((_, index) => index !== ti) })
                }
                onSnapshot={() => {}}
                onEdit={() => {}}
                allowButtons
                enVentana
              />
            </DndContext>
          </div>
          {/* EL VISOR, DEL MISMO ANCHO QUE EN EL RESTO DEL EDITOR.
              Aquí su columna era más ancha que en Seguimientos, así que el
              mismo teléfono se veía de dos tamaños según se editara dentro o
              fuera de la ventana. Es un teléfono: mide lo que mide en todas
              partes. */}
          <div className="min-h-0 overflow-y-auto lg:border-l lg:border-neutral-200 lg:pl-4">
            <ChatPreview steps={[step]} previewRolls={{ 0: tirada }} priceSoles={priceSoles} comboPrice={comboPrice} basicoPrice={basicoPrice} previewPriceOverride={previewPriceOverride} previewComboPriceOverride={previewComboPriceOverride} previewBasicoPriceOverride={previewBasicoPriceOverride} previewContext={previewContext} highlightPlaceholders />
          </div>
        </div>
      </div>
    </div>
  );
}

function JourneyPreviewSection({ title, children }: { title: string; children: ReactNode }) {
  return (
    <section>
      <h3 className="mb-2 text-sm font-bold text-neutral-800">{title}</h3>
      <div className="space-y-4">{children}</div>
    </section>
  );
}

function JourneyPreviewBlock({
  title,
  detail,
  steps,
  priceSoles,
  comboPrice,
  basicoPrice,
  previewPriceOverride,
  previewComboPriceOverride,
  previewBasicoPriceOverride,
  previewContext,
  channelLabel,
  onEdit,
  onStepsChange,
  onSnapshot,
}: {
  title: string;
  detail: string;
  steps: EditorStep[];
  priceSoles?: number;
  comboPrice?: number;
  basicoPrice?: number;
  previewPriceOverride?: number;
  previewComboPriceOverride?: number;
  previewBasicoPriceOverride?: number;
  previewContext: PreviewContext;
  channelLabel: string;
  onEdit: (stepIndex: number) => void;
  /** Solo existe cuando la etapa corresponde a una secuencia real del editor. */
  onStepsChange?: (steps: EditorStep[]) => void;
  onSnapshot?: () => void;
}) {
  const [collapsed, setCollapsed] = useState(false);
  // La selección de burbuja es ÚNICA en todo el editor. Esto era un useState
  // local, y como la sección Canales pinta cinco de estos bloques, cada uno se
  // quedaba con su propia burbuja marcada: al elegir en el segundo, el primero
  // seguía resaltado y parecían dos seleccionadas a la vez. Con el hook
  // compartido cada bloque tiene su dueño y marcar aquí apaga la de allá.
  const { activeStepIndex, setActiveStepIndex } = useSeleccionDeBurbuja();
  const duplicateStep = (index: number, source?: EditorStep) => {
    const step = source ?? steps[index];
    if (!step || !onStepsChange) return;
    onSnapshot?.();
    const next = [...steps];
    // LA COPIA CONSERVA EL ESTADO DEL ORIGINAL.
    //
    // Antes nacía siempre APAGADA, «para que no se envíe por accidente». Pero
    // la vista previa solo muestra las encendidas, así que la copia caía en un
    // sitio que no se ve: duplicabas y no pasaba nada. Y pegar, igual.
    //
    // Duplicar no es un accidente: es un clic derecho y una opción elegida. Si
    // el original iba encendido, la copia también — que es lo que uno espera al
    // duplicar cualquier cosa.
    // Y SIN BOTONES REPETIDOS EN LA FICHA (18/10/2026, el del DNI): ver `sinBotonesRepetidos`.
    next.splice(index + 1, 0, sinBotonesRepetidos(step, steps));
    onStepsChange(next);
    setActiveStepIndex(index + 1);
  };
  const toggleStep = (index: number) => {
    if (!steps[index] || !onStepsChange) return;
    onSnapshot?.();
    onStepsChange(steps.map((step, currentIndex) => currentIndex === index ? { ...step, enabled: step.enabled === false } : step));
  };
  const removeStep = (index: number, opciones?: { sinPreguntar?: boolean }) => {
    if (!steps[index] || !onStepsChange) return;
    if (
      !opciones?.sinPreguntar &&
      !window.confirm("¿Eliminar esta burbuja y su cajón? Puedes deshacerlo.")
    )
      return;
    onSnapshot?.();
    onStepsChange(steps.filter((_, currentIndex) => currentIndex !== index));
    setActiveStepIndex(null);
  };
  const moveStep = (from: number, target: number, placement: "before" | "after") => {
    if (from === target || !onStepsChange) return;
    const next = [...steps];
    const [moved] = next.splice(from, 1);
    let destination = target + (placement === "after" ? 1 : 0);
    if (from < destination) destination -= 1;
    next.splice(destination, 0, moved);
    onSnapshot?.();
    onStepsChange(next);
    setActiveStepIndex(destination);
  };
  return (
    <div className="rounded-lg border border-neutral-300 bg-tarjeta p-3 shadow-sm">
      <div className="mb-2 flex flex-wrap items-center justify-between gap-2">
        <div>
          <h4 className="text-sm font-semibold text-neutral-900">{title}</h4>
          <p className="text-[11px] text-neutral-500">{detail}</p>
        </div>
        <button
          type="button"
          onClick={() => setCollapsed((current) => !current)}
          title={collapsed ? "Expandir etapa" : "Contraer etapa"}
          aria-label={collapsed ? "Expandir etapa" : "Contraer etapa"}
          className="flex h-8 w-8 items-center justify-center rounded border border-neutral-300 bg-tarjeta text-lg text-neutral-700 hover:bg-neutral-50"
        >
          {collapsed ? "▸" : "▾"}
        </button>
      </div>
      {!collapsed && (
        <ChatPreview
          steps={steps}
          priceSoles={priceSoles}
          comboPrice={comboPrice}
          basicoPrice={basicoPrice}
          previewPriceOverride={previewPriceOverride}
          previewComboPriceOverride={previewComboPriceOverride}
          previewBasicoPriceOverride={previewBasicoPriceOverride}
          previewContext={previewContext}
          highlightPlaceholders
          channelLabel={channelLabel}
          perBubbleVary
          // La ventana de recorrido ya tiene su selector móvil/normal/ancho a
          // la vista: aquí manda ese botón, no el tope.
          sinTopeDeAncho
          activeStepIndex={activeStepIndex}
          onSelectStep={onStepsChange ? setActiveStepIndex : undefined}
          onEditStep={(index) => {
            if (onStepsChange) onSnapshot?.();
            onEdit(index);
          }}
          onDuplicateStep={onStepsChange ? duplicateStep : undefined}
          onToggleStep={onStepsChange ? toggleStep : undefined}
          onRemoveStep={onStepsChange ? removeStep : undefined}
          onPasteStep={onStepsChange ? (index, step) => duplicateStep(index, step) : undefined}
          onMoveStep={onStepsChange ? moveStep : undefined}
        />
      )}
    </div>
  );
}

function StepEditorPreviewPair({
  steps,
  previewSteps,
  onChange,
  onSnapshot,
  onEdit,
  idPrefix,
  priceSoles,
  comboPrice,
  basicoPrice,
  stagePriceSoles,
  stageComboPrice,
  stageBasicoPrice,
  previewContext,
  className,
  sinExpandir,
}: {
  steps: EditorStep[];
  /** Permite que el visor resuelva comodines contextuales sin alterar el editor. */
  previewSteps?: EditorStep[];
  onChange: (steps: EditorStep[]) => void;
  onSnapshot: () => void;
  onEdit: (key: string) => void;
  idPrefix: string;
  priceSoles?: number;
  comboPrice?: number;
  basicoPrice?: number;
  /** Precio mostrado por la etapa actual, sin tocar el precio real. */
  stagePriceSoles?: number;
  stageComboPrice?: number;
  stageBasicoPrice?: number;
  previewContext?: PreviewContext;
  className?: string;
  /** Dentro de la ventana a pantalla completa: sin él, se ofrecería abrir otra
   *  igual desde dentro de la que ya está abierta. */
  sinExpandir?: boolean;
}) {
  // La selección es única en todo el editor: al marcar una burbuja aquí, la
  // que estuviera marcada en otra sección se apaga sola.
  const { activeStepIndex, setActiveStepIndex } = useSeleccionDeBurbuja();
  const [aPantallaCompleta, setAPantallaCompleta] = useState(false);
  const [comodinCopiado, setComodinCopiado] = useState<string | null>(null);
  const comodinesDisponibles = useContext(PlaceholderOptionsContext);
  const [editingStepIndex, setEditingStepIndex] = useState<number | null>(null);
  const [useScrollContainer, setUseScrollContainer] = useState(false);
  const [previewRolls, setPreviewRolls] = useState<Record<number, number>>({});
  const varyPreviewStep = (index: number) => {
    setActiveStepIndex(index);
    setPreviewRolls((current) => ({
      ...current,
      [index]: (current[index] ?? 0) + 1,
    }));
  };
  const duplicatePreviewStep = (index: number, source?: EditorStep) => {
    const step = source ?? steps[index];
    if (!step) return;
    onSnapshot();
    // Igual que arriba: la copia conserva el estado del original. Naciendo
    // apagada caía donde la vista previa no la enseña, y duplicar o pegar
    // parecía no hacer nada.
    // Sin botones repetidos en la ficha (18/10/2026): ver `sinBotonesRepetidos`.
    const copy = sinBotonesRepetidos(step, steps);
    const next = [...steps];
    next.splice(index + 1, 0, copy);
    onChange(next);
    setActiveStepIndex(index + 1);
  };
  const togglePreviewStep = (index: number) => {
    const step = steps[index];
    if (!step) return;
    onSnapshot();
    onChange(steps.map((item, itemIndex) => itemIndex === index ? { ...item, enabled: item.enabled === false } : item));
  };
  const removePreviewStep = (
    index: number,
    opciones?: { sinPreguntar?: boolean }
  ) => {
    if (!steps[index]) return;
    if (
      !opciones?.sinPreguntar &&
      !window.confirm("¿Eliminar esta burbuja y su cajón? Puedes deshacerlo.")
    )
      return;
    onSnapshot();
    onChange(steps.filter((_, itemIndex) => itemIndex !== index));
    setActiveStepIndex(null);
  };
  const movePreviewStep = (from: number, target: number, placement: "before" | "after") => {
    if (from === target) return;
    const next = [...steps];
    const [moved] = next.splice(from, 1);
    let destination = target + (placement === "after" ? 1 : 0);
    if (from < destination) destination -= 1;
    next.splice(destination, 0, moved);
    onSnapshot();
    onChange(next);
    setActiveStepIndex(destination);
  };
  return (
    <>
    {/* A PANTALLA COMPLETA, SIN MOVER NADA DE SITIO.
        El cajón se edita igual que siempre, incrustado en la página. Este botón
        abre EL MISMO editor en una ventana con la pantalla entera para él, que
        es lo único que le faltaba: aquí compite por el ancho con todo lo demás
        y por eso se ve apretado.
        Es reversible por construcción: si no se pulsa, no cambia nada. */}
    {!sinExpandir && (
      <button
        type="button"
        onClick={() => setAPantallaCompleta(true)}
        title="Abrir este cajón con la pantalla entera"
        className="mb-2 self-start rounded-full border border-neutral-300 bg-tarjeta px-3 py-1.5 text-xs font-semibold text-neutral-600 hover:border-emerald-400 hover:text-emerald-700"
      >
        ⛶ Pantalla completa
      </button>
    )}
    {aPantallaCompleta && (
      <div
        className="fixed inset-0 z-[70] overflow-y-auto bg-black/50 p-4"
        onClick={
          EL_CLIC_FUERA_CIERRA_LA_VENTANA
            ? () => setAPantallaCompleta(false)
            : undefined
        }
        role="dialog"
        aria-modal="true"
        aria-label="Editar este cajón a pantalla completa"
      >
        {/* 825 px, UN 45% MENOS QUE LOS 1500 DE ANTES.
            A ese ancho el editor y el visor no llegaban a llenarlo: quedaba una
            franja en blanco a la derecha del teléfono, y el texto de la
            izquierda se estiraba en renglones larguísimos. El visor es un
            teléfono y no crece; lo único que hacía la ventana ancha era separar
            las dos columnas.
            Y las esquinas menos redondas, para que se parezca a las demás
            ventanas de la casa y no a una tarjeta. */}
        <div
          className="mx-auto w-full max-w-[825px] rounded-lg border border-neutral-200 bg-tarjeta shadow-2xl"
          onClick={(evento) => evento.stopPropagation()}
        >
          <div className="flex flex-wrap items-center justify-between gap-3 rounded-t-lg border-b border-neutral-200 bg-neutral-50/80 px-5 py-3">
            <h3 className="text-[15px] font-bold text-neutral-900">
              Editar este cajón
            </h3>
            <div className="flex items-center gap-2">
              <span className="hidden text-[11px] text-neutral-500 sm:inline">
                Se guarda solo · Escape = cerrar
              </span>
              <button
                type="button"
                onClick={() => setAPantallaCompleta(false)}
                className="rounded-full bg-emerald-600 px-5 py-2 text-xs font-bold text-white shadow-sm hover:bg-emerald-700"
              >
                Listo
              </button>
            </div>
          </div>
          {/* LOS COMODINES, A UN CLIC.
              Se copian al portapapeles en vez de insertarse: la burbuja que se
              está escribiendo puede ser cualquiera de la lista, y adivinar cuál
              sería meter texto donde no toca. */}
          <div className="flex flex-wrap items-center gap-1.5 border-b border-neutral-200 px-5 py-3">
            <span className="mr-1 text-[11px] font-bold uppercase tracking-wide text-neutral-500">
              Comodines
            </span>
            {comodinesDisponibles.slice(0, 18).map((opcion) => (
              <button
                key={opcion.token}
                type="button"
                title={`${opcion.label} — clic para copiarlo`}
                onClick={() => {
                  void navigator.clipboard?.writeText(opcion.token);
                  setComodinCopiado(opcion.token);
                  window.setTimeout(() => setComodinCopiado(null), 1500);
                }}
                className={`rounded-full border px-2.5 py-1 font-mono text-[10px] transition-colors ${
                  comodinCopiado === opcion.token
                    ? "border-emerald-400 bg-emerald-50 text-emerald-700"
                    : "border-neutral-300 bg-tarjeta text-neutral-600 hover:border-emerald-400 hover:text-emerald-700"
                }`}
              >
                {comodinCopiado === opcion.token ? "✓ copiado" : opcion.token}
              </button>
            ))}
          </div>
          <div className="px-5 py-4">
            <StepEditorPreviewPair
              steps={steps}
              previewSteps={previewSteps}
              onChange={onChange}
              onSnapshot={onSnapshot}
              onEdit={onEdit}
              idPrefix={`${idPrefix}_full`}
              priceSoles={priceSoles}
              comboPrice={comboPrice}
              basicoPrice={basicoPrice}
              stagePriceSoles={stagePriceSoles}
              stageComboPrice={stageComboPrice}
              stageBasicoPrice={stageBasicoPrice}
              previewContext={previewContext}
              sinExpandir
            />
          </div>
        </div>
      </div>
    )}
    {/* UNA LÍNEA SEPARA LAS DOS COLUMNAS, Y NADA MÁS.
        Aquí se probó a dar a cada columna su propia barra de desplazamiento, y
        se salió mal: el tope de altura iba en la rejilla, y en una rejilla la
        fila se estira a lo que mide su contenido. El tope recortaba la CAJA sin
        encoger la fila, así que las columnas seguían midiendo lo suyo, ninguna
        sacaba barra, y el visor se pintaba por encima de las pestañas de abajo.
        No se vuelve a intentar sin poner el tope en cada columna.
        El visor se queda a la vista con `sticky`, como siempre. Y quien quiera
        encerrar el visor en una caja con barra propia ya tiene la casilla
        «Activar contenedor de edición», que para eso está. */}
    {/* DOS COLUMNAS, SALVO QUE QUIEN LLAMA PIDA OTRA COSA.
        Dentro de una ventana no caben dos columnas iguales, así que las
        llamadas de ahí piden su propio reparto: una sola columna, y el visor
        estrecho al lado solo en pantallas muy anchas.
        Eso ya se pedía, y a medias no funcionaba: las dos reparticiones se
        escribían juntas en la misma clase, y cuál manda no lo decide el orden
        en que se escriben sino el del CSS generado — donde `lg:grid-cols-2` va
        después y ganaba siempre. La de la ventana solo se notaba a partir de
        `xl`. Ahora, si quien llama trae su propio reparto, el de la casa no se
        escribe: no hay dos, hay uno. */}
    <div
      className={`grid gap-4 ${
        /grid-cols/.test(className ?? "") ? "" : "lg:grid-cols-2"
      } ${className ?? ""}`}
    >
      <StepList
        steps={steps}
        onChange={onChange}
        onSnapshot={onSnapshot}
        onEdit={onEdit}
        idPrefix={idPrefix}
        activeStepIndex={activeStepIndex}
        onActiveStepIndexChange={setActiveStepIndex}
        onVaryPreviewStep={varyPreviewStep}
      />
      <div className="lg:sticky lg:top-4 lg:self-start lg:border-l lg:border-neutral-200 lg:pl-4">
        <label className="mb-2 flex cursor-pointer items-center gap-2 text-xs text-neutral-600">
          <input
            type="checkbox"
            checked={useScrollContainer}
            onChange={(e) => setUseScrollContainer(e.target.checked)}
            className="h-4 w-4 accent-emerald-600"
          />
          Activar contenedor de edición
        </label>
        <ChatPreview
          steps={previewSteps ?? steps}
          priceSoles={priceSoles}
          comboPrice={comboPrice}
          basicoPrice={basicoPrice}
          previewPriceOverride={stagePriceSoles}
          previewComboPriceOverride={stageComboPrice}
          previewBasicoPriceOverride={stageBasicoPrice}
          previewContext={previewContext}
          activeStepIndex={activeStepIndex}
          previewRolls={previewRolls}
          useScrollContainer={useScrollContainer}
          onSelectStep={setActiveStepIndex}
          onVaryAll={() => setPreviewRolls({})}
          onEditStep={(index) => {
            onSnapshot();
            setEditingStepIndex(index);
          }}
          onDuplicateStep={duplicatePreviewStep}
          onToggleStep={togglePreviewStep}
          onRemoveStep={removePreviewStep}
          onPasteStep={(index, step) => duplicatePreviewStep(index, step)}
          onMoveStep={movePreviewStep}
        />
      </div>
      {editingStepIndex !== null && (
        <JourneyStepEditorModal
          title="Vista previa"
          steps={steps}
          stepIndex={editingStepIndex}
          priceSoles={priceSoles}
          comboPrice={comboPrice}
          basicoPrice={basicoPrice}
          previewPriceOverride={stagePriceSoles}
          previewComboPriceOverride={stageComboPrice}
          previewBasicoPriceOverride={stageBasicoPrice}
          previewContext={previewContext ?? {}}
          onChange={onChange}
          onClose={() => setEditingStepIndex(null)}
        />
      )}
    </div>
    </>
  );
}

function EditorEmojiInput({
  value,
  onChange,
  placeholder,
  className,
  onContextMenu,
}: {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  className: string;
  onContextMenu?: (event: React.MouseEvent<HTMLInputElement>) => void;
}) {
  const inputRef = useRef<HTMLInputElement | null>(null);

  function insertAtCursor(text: string) {
    const input = inputRef.current;
    if (!input) {
      onChange(value + text);
      return;
    }
    const start = input.selectionStart ?? value.length;
    const end = input.selectionEnd ?? value.length;
    const next = value.slice(0, start) + text + value.slice(end);
    onChange(next);
    requestAnimationFrame(() => {
      input.focus({ preventScroll: true });
      const position = start + text.length;
      input.setSelectionRange(position, position);
    });
  }

  return (
    <div className="mt-2 block w-full min-w-0">
      <TextVariantToolbar onEmoji={insertAtCursor} />
      <input
        ref={inputRef}
        type="text"
        value={value}
        onChange={(event) => onChange(event.target.value)}
        onContextMenu={onContextMenu}
        placeholder={placeholder}
        className={className}
      />
    </div>
  );
}

function EditorEmojiTextarea({
  value,
  onChange,
  sideActions,
  rows,
  placeholder,
  className,
  onFocus,
  onBlur,
  onContextMenu,
}: {
  value: string;
  onChange: (value: string) => void;
  sideActions?: ReactNode;
  rows: number;
  placeholder?: string;
  className: string;
  onFocus?: () => void;
  onBlur?: () => void;
  onContextMenu?: (event: React.MouseEvent<HTMLTextAreaElement>) => void;
}) {
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);
  const highlightRef = useRef<HTMLDivElement | null>(null);
  const placeholderOptions = useContext(PlaceholderOptionsContext);
  const [placeholderQuery, setPlaceholderQuery] = useState<string | null>(null);
  const hasPlaceholders = /\{\{\s*[A-Za-z0-9_]+\s*\}\}/.test(value);
  // UN NÚMERO DE CUENTA ESCRITO A MANO (23/10/2026): si cambias la cuenta o el usuario que cobra,
  // aquí no cambia. Se avisa y, si la cuenta tiene comodín, se cambia con un clic.
  const numerosGuardados = useContext(NumerosGuardadosContext);
  const aMano = useMemo(() => numerosGuardadosEn(value, numerosGuardados), [value, numerosGuardados]);

  function getPlaceholderMatch(text: string, cursor: number) {
    const before = text.slice(0, cursor);
    return before.match(/\{\{\s*([A-Za-z0-9_]*)$/);
  }

  const filteredPlaceholders =
    placeholderQuery === null
      ? []
      : placeholderOptions
          .filter((option) =>
            option.token
              .replace(/[{}]/g, "")
              .toLowerCase()
              .includes(placeholderQuery.toLowerCase())
          )
          .slice(0, 8);

  function insertAtCursor(text: string) {
    const ta = textareaRef.current;
    if (!ta) {
      onChange(value + text);
      return;
    }
    const start = ta.selectionStart ?? value.length;
    const end = ta.selectionEnd ?? value.length;
    const previousScrollTop = ta.scrollTop;
    const previousScrollLeft = ta.scrollLeft;
    const previousWindowScrollX = window.scrollX;
    const previousWindowScrollY = window.scrollY;
    const next = value.slice(0, start) + text + value.slice(end);
    onChange(next);
    requestAnimationFrame(() => {
      ta.focus({ preventScroll: true });
      const pos = start + text.length;
      ta.setSelectionRange(pos, pos);
      ta.scrollTop = previousScrollTop;
      ta.scrollLeft = previousScrollLeft;
      window.scrollTo(previousWindowScrollX, previousWindowScrollY);
    });
  }

  function insertPlaceholder(token: string) {
    const ta = textareaRef.current;
    const cursor = ta?.selectionStart ?? value.length;
    const match = getPlaceholderMatch(value, cursor);
    const start = match ? cursor - match[0].length : cursor;
    const next = value.slice(0, start) + token + value.slice(cursor);
    onChange(next);
    setPlaceholderQuery(null);
    requestAnimationFrame(() => {
      ta?.focus();
      const pos = start + token.length;
      ta?.setSelectionRange(pos, pos);
    });
  }

  return (
    <div className="block w-full min-w-0">
      <TextVariantToolbar onEmoji={insertAtCursor}>
        {sideActions}
      </TextVariantToolbar>
      <div className="relative block w-full min-w-0">
        <textarea
          ref={textareaRef}
          value={value}
          onChange={(e) => {
            const next = e.target.value;
            onChange(next);
            const match = getPlaceholderMatch(next, e.target.selectionStart ?? next.length);
            setPlaceholderQuery(match ? match[1] ?? "" : null);
          }}
          onKeyDown={(e) => {
            if (e.key === "Escape") setPlaceholderQuery(null);
            if (false && e.key === "Enter" && filteredPlaceholders.length > 0) {
              e.preventDefault();
              insertPlaceholder(filteredPlaceholders[0].token);
            }
          }}
          onClick={(e) => {
            const ta = e.currentTarget;
            const match = getPlaceholderMatch(value, ta.selectionStart ?? value.length);
            setPlaceholderQuery(match ? match[1] ?? "" : null);
          }}
          onContextMenu={onContextMenu}
          onFocus={onFocus}
          onBlur={() => {
            onBlur?.();
            window.setTimeout(() => setPlaceholderQuery(null), 120);
          }}
          rows={rows}
          placeholder={placeholder}
          className={`relative block w-full max-w-none min-w-0 ${className}`}
        />
        {/* AQUÍ HABÍA UNA COPIA DEL TEXTO, CON LOS COMODINES RESALTADOS.

            Salía debajo de CADA cuadro que tuviera un comodín, así que el
            mismo texto aparecía dos veces seguidas y cada burbuja ocupaba el
            doble de alto. En una intro de catorce burbujas, eso es media
            pantalla de texto repetido.

            Servía para ver qué comodines llevaba el texto. Eso hoy se ve mejor
            en dos sitios: el desplegable que sale al escribir {{ —que además
            los inserta— y el botón "Comodines" de arriba, que lista todos los
            que existen. Repetirlo aquí ya no aporta nada. */}
        {aMano.length > 0 && (
          <div className="mt-1 space-y-1">
            {aMano.map((x) => (
              <p
                key={x.escrito}
                className="flex flex-wrap items-center gap-1.5 rounded border border-amber-300 bg-amber-50 px-2 py-1 text-[11px] leading-snug text-amber-900"
              >
                <span>
                  ⚠ <strong>{x.escrito}</strong> está escrito a mano: si cambias tu cuenta o el usuario que cobra, aquí no cambia.
                </span>
                {x.comodin ? (
                  <button
                    type="button"
                    onClick={() => onChange(value.split(x.escrito).join(x.comodin!))}
                    className="rounded border border-amber-400 bg-tarjeta px-1.5 py-0.5 font-mono text-[10px] font-semibold text-amber-900 hover:bg-amber-100"
                  >
                    Cambiar por {x.comodin}
                  </button>
                ) : (
                  <span>Es la cuenta de un usuario: usa su comodín.</span>
                )}
              </p>
            ))}
          </div>
        )}
        {/* Aquí había un SEGUNDO desplegable de comodines.

            Hacía lo mismo que el que sigue al cursor, pero clavado arriba a
            la izquierda del campo. Al escribir {{ se abrían LOS DOS, y el de
            posición fija tapaba al otro: quedaban dos listas iguales
            superpuestas y no se podía leer ninguna.

            Se quita este y queda el que sigue a la palabra que se escribe,
            que es donde uno está mirando. El otro vive fuera de este campo
            (GlobalPlaceholderAutocomplete) y funciona en TODOS los cuadros de
            texto del editor, así que no se pierde nada. */}
      </div>
    </div>
  );
}

function HighlightedPlaceholders({ text }: { text: string }) {
  const nodes: ReactNode[] = [];
  const re = /(\{\{\s*[A-Za-z0-9_]+\s*\}\})/g;
  let last = 0;
  let match: RegExpExecArray | null;
  let key = 0;
  while ((match = re.exec(text)) !== null) {
    if (match.index > last) nodes.push(text.slice(last, match.index));
    nodes.push(
      <span
        key={key++}
        className="rounded bg-sky-100 px-0.5 font-mono font-semibold text-sky-700 ring-1 ring-sky-200"
      >
        {match[0]}
      </span>
    );
    last = match.index + match[0].length;
  }
  if (last < text.length) nodes.push(text.slice(last));
  return <>{nodes.length ? nodes : text}</>;
}

function StepList({
  steps,
  onChange,
  onSnapshot,
  onEdit,
  idPrefix,
  activeStepIndex,
  onActiveStepIndexChange,
  onVaryPreviewStep,
  allowButtons = true,
  sinAgregar = false,
}: {
  steps: EditorStep[];
  onChange: (steps: EditorStep[]) => void;
  onSnapshot: () => void;
  onEdit: (key: string) => void;
  idPrefix: string;
  activeStepIndex?: number | null;
  onActiveStepIndexChange?: (index: number | null) => void;
  onVaryPreviewStep?: (index: number) => void;
  allowButtons?: boolean;
  /** ESTE CAJÓN SOLO PUEDE TENER UNA BURBUJA.
   *
   *  Lo usa la galería de muestras: ahí una muestra ES una burbuja —un archivo
   *  con su pie— y no hay dónde meter una segunda. El botón de agregar seguía
   *  saliendo porque este editor es el mismo de todas partes, y lo que hacía
   *  era crear OTRA MUESTRA vacía: sin tema, invisible en «Info de contenido» y
   *  sin que el bot la mande nunca. Un botón que promete una cosa y hace otra. */
  sinAgregar?: boolean;
}) {
  useEffect(() => {
    if (activeStepIndex == null) return;
    const frame = window.requestAnimationFrame(() => {
      document
        .getElementById(`editor-step-${idPrefix}-${activeStepIndex}`)
        ?.scrollIntoView({ behavior: "smooth", block: "nearest" });
    });
    return () => window.cancelAnimationFrame(frame);
  }, [activeStepIndex, idPrefix, steps.length]);

  const update = (i: number, patch: Partial<EditorStep>) => {
    onEdit(`${idPrefix}:${i}:meta`);
    onChange(steps.map((s, idx) => (idx === i ? { ...s, ...patch } : s)));
  };
  const [dragIndex, setDragIndex] = useState<number | null>(null);
  const draggableId = (index: number) => `${idPrefix}::step-drag::${index}`;
  const droppableId = (index: number) => `${idPrefix}::step-drop::${index}`;
  const move = (i: number, dir: -1 | 1) => {
    const j = i + dir;
    if (j < 0 || j >= steps.length) return;
    onSnapshot();
    const copy = [...steps];
    [copy[i], copy[j]] = [copy[j], copy[i]];
    onChange(copy);
  };
  const reorder = (from: number, to: number) => {
    if (from === to || from < 0 || to < 0 || from >= steps.length || to >= steps.length)
      return;
    onSnapshot();
    const copy = [...steps];
    const [moved] = copy.splice(from, 1);
    copy.splice(to, 0, moved);
    onChange(copy);
  };
  const dropAt = (to: number) => {
    if (dragIndex === null) return;
    reorder(dragIndex, to);
    setDragIndex(null);
  };
  const onDragStartDnd = (event: DragStartEvent) => {
    const from = Number(event.active.data.current?.index);
    if (Number.isFinite(from)) setDragIndex(from);
  };
  const onDragEndDnd = (event: DragEndEvent) => {
    const from = Number(event.active.data.current?.index);
    const to = Number(event.over?.data.current?.index);
    if (Number.isFinite(from) && Number.isFinite(to)) {
      reorder(from, to);
      onActiveStepIndexChange?.(to);
    }
    setDragIndex(null);
  };
  const dropAtFromEvent = (e: React.DragEvent<HTMLElement>, to: number) => {
    e.preventDefault();
    dropAt(to);
  };
  const duplicateStep = (i: number) => {
    onSnapshot();
    const copy = [...steps];
    const step = copy[i];
    // Sin botones repetidos en la ficha (18/10/2026): ver `sinBotonesRepetidos`.
    copy.splice(i + 1, 0, sinBotonesRepetidos(step, steps));
    onChange(copy);
  };
  const removeStep = (i: number) => {
    if (!confirm("¿Quitar este paso? Puedes deshacerlo con ↶ Deshacer.")) return;
    onSnapshot();
    onChange(steps.filter((_, idx) => idx !== i));
  };
  const addStep = () => {
    onSnapshot();
    onChange([...steps, emptyStep()]);
  };
  // ESCRIBIR EN UNA BURBUJA SIN CAMPOS TIENE QUE CREAR EL PRIMERO.
  //
  // Una burbuja podía quedarse con la lista de textos VACÍA, y entonces no se
  // dibujaba ninguna casilla: se entraba al cajón y no había dónde escribir.
  // Ahora siempre se enseña una, así que al teclear en ella hay que crear el
  // hueco en vez de recorrer una lista que no tiene nada.
  const updateText = (i: number, ti: number, v: string) => {
    onEdit(`${idPrefix}:${i}:t${ti}`);
    onChange(
      steps.map((s, idx) =>
        idx === i
          ? {
              ...s,
              texts: s.texts.length
                ? s.texts.map((t, k) => (k === ti ? v : t))
                : [v],
            }
          : s
      )
    );
  };
  const addText = (i: number) => {
    onSnapshot();
    onChange(
      steps.map((s, idx) => (idx === i ? { ...s, texts: [...s.texts, ""] } : s))
    );
  };
  const duplicateText = (i: number, ti: number) => {
    onSnapshot();
    onChange(
      steps.map((s, idx) => {
        if (idx !== i) return s;
        const texts = [...s.texts];
        texts.splice(ti + 1, 0, s.texts[ti] ?? "");
        return { ...s, texts };
      })
    );
  };
  const removeText = (i: number, ti: number) => {
    if (!confirm("¿Quitar esta variante? Puedes deshacerlo con ↶ Deshacer.")) return;
    onSnapshot();
    onChange(
      steps.map((s, idx) =>
        idx === i ? { ...s, texts: s.texts.filter((_, k) => k !== ti) } : s
      )
    );
  };
  const draggingStep = dragIndex === null ? null : steps[dragIndex] ?? null;
  // Las burbujas apagadas se pliegan detrás de una barra propia de ESTE cajón.
  // Con diez apagadas por medio no se veía lo que sí corre. Al abrirlas salen
  // EN SU SITIO, no amontonadas al final: en una secuencia el orden significa
  // algo, y moverlas de sitio para mirarlas mentiría sobre dónde volverían.
  const [mostrarApagadas, setMostrarApagadas] = useState(false);
  const apagadas = steps.filter((step) => step.enabled === false).length;

  return (
    <DndContext onDragStart={onDragStartDnd} onDragEnd={onDragEndDnd}>
    {/* En columna para poder colocar la barra de apagadas ENCIMA de lo que
        esconde: el navegador respeta el orden que se le pide abajo. */}
    <div className="flex flex-col space-y-4">
      {steps.map((step, i) =>
        step.enabled === false && !mostrarApagadas ? null : (
        <div
          id={`editor-step-${idPrefix}-${i}`}
          key={i}
          // Las apagadas se van al final, debajo de su barra.
          className={`scroll-mt-4 space-y-2 ${step.enabled === false ? "order-2" : ""}`}
        >
          {false && dragIndex !== null && dragIndex !== i && (
            <button
              type="button"
              onDragOver={(e) => e.preventDefault()}
              onDrop={(e) => {
                dropAtFromEvent(e, i);
              }}
              onClick={() => dropAt(i)}
              className="w-full rounded-md border-2 border-dashed border-sky-300 bg-sky-50 py-1 text-xs font-semibold text-sky-700"
            >
              Soltar aquí
            </button>
          )}
          <StepCard
            draggableId={draggableId(i)}
            droppableId={droppableId(i)}
            index={i}
            total={steps.length}
            step={step}
            isDragging={dragIndex === i}
            isDragTarget={dragIndex !== null && dragIndex !== i}
            isActive={activeStepIndex === i}
            onUpdate={(patch) => update(i, patch)}
            onMove={(dir) => move(i, dir)}
            onActivate={() => onActiveStepIndexChange?.(i)}
            onDuplicate={() => duplicateStep(i)}
            onRemove={() => removeStep(i)}
            onVaryPreview={() => onVaryPreviewStep?.(i)}
            onUpdateText={(ti, v) => updateText(i, ti, v)}
            onAddText={() => addText(i)}
            onDuplicateText={(ti) => duplicateText(i, ti)}
            onRemoveText={(ti) => removeText(i, ti)}
            onSnapshot={onSnapshot}
            onEdit={onEdit}
            allowButtons={allowButtons}
          />
        </div>
        )
      )}
      {apagadas > 0 && (
        <button
          type="button"
          onClick={() => setMostrarApagadas((v) => !v)}
          title="Las burbujas apagadas no se envían. Aquí se guardan para no llenar la pantalla."
          className="order-1 flex w-full items-center gap-2 rounded-lg border border-neutral-300 bg-neutral-100 px-4 py-2.5 text-left text-sm font-semibold text-neutral-600 hover:bg-neutral-200"
        >
          <span className="text-neutral-400">{mostrarApagadas ? "▼" : "▶"}</span>
          Burbujas inactivas ({apagadas})
          <span className="ml-auto text-xs font-normal text-neutral-500">
            {mostrarApagadas ? "ocultar" : "ver"}
          </span>
        </button>
      )}
      {false && dragIndex !== null && dragIndex !== steps.length - 1 && (
        <button
          type="button"
          onDragOver={(e) => e.preventDefault()}
          onDrop={(e) => {
            dropAtFromEvent(e, steps.length - 1);
          }}
          onClick={() => dropAt(steps.length - 1)}
          className="w-full rounded-md border-2 border-dashed border-sky-300 bg-sky-50 py-1 text-xs font-semibold text-sky-700"
        >
          Soltar al final
        </button>
      )}
      {!sinAgregar && (
        <button
          type="button"
          onClick={addStep}
          className="order-3 w-full rounded-md border-2 border-dashed border-neutral-300 py-2 text-sm text-neutral-500 hover:border-emerald-400 hover:text-emerald-600"
        >
          ➕ Agregar paso
        </button>
      )}
    </div>
    <DragOverlay dropAnimation={null}>
      {draggingStep ? (
        <StepDragPreview index={dragIndex ?? 0} step={draggingStep} />
      ) : null}
    </DragOverlay>
    </DndContext>
  );
}

function StepDropTarget({
  id,
  index,
  onClick,
  label = "Soltar aquÃ­",
}: {
  id: string;
  index: number;
  onClick: () => void;
  label?: string;
}) {
  const { setNodeRef, isOver } = useDroppable({
    id,
    data: { index },
  });
  return (
    <button
      ref={setNodeRef}
      type="button"
      onClick={onClick}
      className={`w-full rounded-md border-2 border-dashed py-1 text-xs font-semibold ${
        isOver
          ? "border-sky-500 bg-sky-100 text-sky-800"
          : "border-sky-300 bg-sky-50 text-sky-700"
      }`}
    >
      {label}
    </button>
  );
}

function StepDragPreview({
  index,
  step,
}: {
  index: number;
  step: EditorStep;
}) {
  const firstText = step.texts.find((t) => t.trim().length > 0) ?? "";
  const preview = firstText.replace(/\s+/g, " ").trim();
  return (
    <div className="w-[min(720px,calc(100vw-3rem))] rounded-lg border-2 border-black bg-white/95 p-3 shadow-2xl">
      <div className="mb-2 flex items-center gap-2">
        <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-carbon-suave text-xs font-medium text-white">
          {index + 1}
        </span>
        <span className="rounded border border-sky-300 bg-tarjeta px-2 py-1 text-xs font-bold text-sky-700">
          Mover
        </span>
        <span className="text-xs font-semibold text-neutral-600">
          {TYPE_LABEL[step.type]}
        </span>
      </div>
      <p className="line-clamp-3 text-sm text-neutral-700">
        {preview || "(sin texto)"}
      </p>
    </div>
  );
}

/** Una línea que dice si el botón ya tiene contenido, sin abrirlo. */
function resumenDeBurbujas(steps: EditorStep[]): string {
  const activos = steps.filter((paso) => paso.enabled !== false);
  if (activos.length === 0) return "Todavía sin contenido.";
  const primero = (activos[0].texts ?? []).find((t) => t.trim())?.trim() ?? "";
  const cuantas =
    activos.length === 1 ? "1 burbuja" : `${activos.length} burbujas`;
  if (!primero) return `${cuantas}.`;
  const corto = primero.length > 60 ? `${primero.slice(0, 60)}…` : primero;
  return `${cuantas}: «${corto}»`;
}

/**
 * La ventana donde se escribe lo que manda un botón.
 *
 * Se edita un BORRADOR: "Listo" lo guarda, Escape y el clic fuera lo descartan.
 * Es la misma regla que el resto de las ventanas del editor, y existe porque
 * escribir directo hacía que salir de cualquier forma dejara el cambio hecho —
 * no había manera de arrepentirse.
 */
function BubbleButtonStepsModal({
  titulo,
  steps,
  onGuardar,
  onCerrar,
  onSnapshot,
  onEdit,
  idPrefix,
}: {
  titulo: string;
  steps: EditorStep[];
  onGuardar: (steps: EditorStep[]) => void;
  onCerrar: () => void;
  onSnapshot: () => void;
  onEdit: (key: string) => void;
  idPrefix: string;
}) {
  const [borrador, setBorrador] = useState<EditorStep[]>(steps);
  useEffect(() => {
    const alPulsar = (evento: KeyboardEvent) => {
      if (evento.key !== "Escape") return;
      evento.preventDefault();
      onCerrar();
    };
    window.addEventListener("keydown", alPulsar);
    return () => window.removeEventListener("keydown", alPulsar);
  }, [onCerrar]);
  return (
    <div
      className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-black/40 p-4"
      onClick={EL_CLIC_FUERA_CIERRA_LA_VENTANA ? onCerrar : undefined}
    >
      <div
        className="my-8 w-full max-w-4xl rounded-lg border border-neutral-300 bg-tarjeta shadow-xl"
        onClick={(evento) => evento.stopPropagation()}
      >
        <div className="flex items-center justify-between gap-3 border-b border-neutral-200 px-4 py-3">
          <div>
            <h3 className="text-sm font-bold text-neutral-900">
              Lo que se envía al tocar «{titulo}»
            </h3>
            <p className="text-xs text-neutral-500">
              Texto, imágenes, videos o muestras. Después de esto, la
              conversación sigue por su camino normal.
            </p>
          </div>
          <div className="flex items-center gap-2">
            <span className="hidden text-[11px] text-neutral-500 sm:inline">
              Escape o Cancelar = descartar
            </span>
            <button
              type="button"
              onClick={onCerrar}
              className="rounded border border-neutral-300 px-3 py-1.5 text-xs font-semibold text-neutral-600 hover:bg-neutral-50"
            >
              Cancelar
            </button>
            <button
              type="button"
              onClick={() => onGuardar(borrador)}
              className="rounded bg-emerald-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-emerald-700"
            >
              Listo
            </button>
          </div>
        </div>
        {/* Editor a la izquierda, visor de WhatsApp a la derecha — el mismo
            reparto que el resto de las burbujas. Sin el visor había que
            imaginarse cómo iba a llegar, que es justo lo que el editor está
            para evitar. */}
        <div className="grid max-h-[70vh] gap-4 overflow-y-auto p-4 lg:grid-cols-[minmax(0,1fr)_minmax(260px,340px)]">
          <div className="min-w-0">
            <StepList
              steps={borrador}
              onChange={setBorrador}
              onSnapshot={onSnapshot}
              onEdit={onEdit}
              idPrefix={idPrefix}
              allowButtons={false}
            />
          </div>
          <div className="lg:sticky lg:top-0 lg:self-start">
            <p className="mb-1 text-[11px] font-medium text-neutral-500">
              Así le llega al cliente
            </p>
            {/* Los precios y los nombres los hereda del contexto del editor,
                igual que los demás visores: sin eso, aquí se verían los
                comodines en crudo y no lo que va a recibir de verdad. */}
            <ChatPreview steps={borrador} />
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * LOS CUADRITOS DE DECISIÓN.
 *
 * Cada uno es una respuesta posible a la pregunta de su burbuja. El cliente NO
 * los ve: recibe la pregunta como texto y contesta escribiendo. El bot compara
 * lo que escribió con las palabras clave de cada cuadrito.
 *
 * Por eso van en fila y no hay tope de tres —ese límite es de los botones de
 * WhatsApp, y esto no son botones—. Y por eso el contenido se edita en una
 * ventana: en fila caben muchos, y desplegado cada uno el panel sería
 * inmanejable.
 */
/**
 * EL MENÚ LATERAL DE LA INTERFAZ NUEVA.
 *
 * Solo la cáscara: los lugares a la izquierda y, dentro del lugar abierto, sus
 * pestañas. El contenido de cada pestaña es EXACTAMENTE el de siempre — esto no
 * toca ni un campo, solo cambia por dónde se llega.
 */
/**
 * UNA FICHA DE LA BARRA IZQUIERDA.
 *
 * Sirve para los sitios del editor y para los enlaces de fuera —conversaciones,
 * Meta Connect, modo prueba—, que antes eran tres bloques escritos a mano casi
 * iguales pero no del todo: uno azul, otro gris, y cada uno con su propio borde.
 * Escrita una vez, no pueden separarse.
 */
function FichaDeLugar({
  href,
  onAbrir,
  activo = false,
  titulo,
  icono,
  nombre,
  tono,
}: {
  href?: string;
  onAbrir?: () => void;
  activo?: boolean;
  titulo: string;
  icono: string;
  nombre: string;
  tono: TonoDelTema;
}) {
  // EN CLARO, LO ACTIVO SE TIÑE; EN OSCURO, SE RELLENA.
  //
  // Un bloque de violeta saturado sobre blanco da un salto de contraste que
  // tira del ojo: en una barra de diecisiete fichas, la marcada grita y las
  // demás desaparecen. Sobre fondo oscuro pasa lo contrario, el bloque se apoya
  // en la oscuridad y se lee tranquilo.
  //
  // Así que el color es el mismo y lo que cambia es CUÁNTO se rellena: tinte
  // suave con letra de color en claro, bloque en oscuro.
  const clase = `flex w-[96px] flex-col items-center gap-1.5 rounded-2xl border px-2 py-3 text-center text-[11px] font-bold leading-tight transition-all ${
    activo
      ? "border-acento/40 bg-acento-suave text-acento oscuro:border-transparent oscuro:bg-acento oscuro:text-white"
      : "border-borde bg-tarjeta text-tinta-suave hover:bg-relleno"
  }`;
  const dentro = (
    <>
      {/* El cuadrado de color es la guía: se busca con el ojo antes de leer el
          nombre. En la ficha activa se apaga a blanco translúcido, porque ahí
          el color ya lo lleva la ficha entera. */}
      <span
        aria-hidden
        className={`flex h-9 w-9 items-center justify-center rounded-xl text-lg ${
          activo
            ? "bg-acento/15 oscuro:bg-white/20"
            : TONOS_DEL_TEMA[tono].ficha
        }`}
      >
        {icono}
      </span>
      {nombre}
    </>
  );
  if (href) {
    return (
      <Link href={href} title={titulo} className={clase}>
        {dentro}
      </Link>
    );
  }
  return (
    <button type="button" onClick={onAbrir} title={titulo} className={clase}>
      {dentro}
    </button>
  );
}

function MenuLateral({
  tab,
  onTab,
  tabsVisibles,
  etiquetaDeTab,
  vistaClasica,
  basesVisibles,
  onAlternarBases,
  sinBotonDeBases = false,
}: {
  /** Modo esencial: el botón de las bases no se dibuja. */
  sinBotonDeBases?: boolean;
  tab: Tab;
  onTab: (t: Tab) => void;
  /** Las pestañas que corresponden ahora (modalidad activa, bases ocultas…). */
  tabsVisibles: Set<Tab>;
  etiquetaDeTab: (t: Tab) => string;
  vistaClasica: () => void;
  /** «Chat» y «Mostrar bases», los dos que van delante en el menú de arriba. */
  basesVisibles: boolean;
  onAlternarBases: () => void;
}) {
  const suyas = ORDEN_DE_TABS.filter((t) => tabsVisibles.has(t));
  return (
    <>
      {/* LA BARRA LLEVA LAS MISMAS PESTAÑAS QUE EL MENÚ DE ARRIBA.
          Llevaba otra cosa: cinco grupos —«El recorrido», «Lo que vendes»…—
          inventados solo para ella, con su propio orden y con «Usuario» fuera de
          todos, o sea inalcanzable. Dos menús para lo mismo, distintos, y
          ninguno era el bueno.
          Ahora las dos vistas leen `ORDEN_DE_TABS`. Lo que no está en el menú de
          arriba no está aquí.
          Va FIJA: en una intro de catorce burbujas, un menú que se pierde arriba
          no sirve de nada. Y con su propio desplazamiento, porque diecisiete
          fichas no caben en una pantalla corta. */}
      <aside className="fixed inset-y-0 left-0 z-30 w-[116px] overflow-y-auto overscroll-contain border-r border-borde bg-tarjeta py-3 pb-6">
        <div className="flex flex-col items-center gap-2.5">
          {/* Los dos primeros del menú de arriba, en el mismo orden. */}
          <FichaDeLugar
            href="/"
            titulo="Ver las conversaciones"
            icono="💬"
            nombre="Chat"
            tono="cielo"
          />
          {!sinBotonDeBases && (
          <FichaDeLugar
            onAbrir={onAlternarBases}
            activo={basesVisibles}
            titulo="Mostrar u ocultar las pestañas base. No modifica su contenido ni el funcionamiento del bot."
            icono="🧱"
            nombre={basesVisibles ? "Ocultar bases" : "Mostrar bases"}
            tono="pizarra"
          />
          )}
          {suyas.map((t) => (
            <FichaDeLugar
              key={t}
              activo={tab === t}
              onAbrir={() => onTab(t)}
              titulo={etiquetaDeTab(t)}
              icono={ICONO_DE_TAB[t]}
              nombre={etiquetaDeTab(t)}
              tono="violeta"
            />
          ))}
          {/* La salida se queda aquí además de arriba: con «Pantalla completa»
              puesta, la cabecera se esconde entera y esta sería la única. */}
          <button
            type="button"
            onClick={vistaClasica}
            title="Volver a las pestañas de siempre. No cambia ningún dato."
            className="mt-2 w-[96px] rounded-xl border border-borde px-2 py-2 text-[11px] font-semibold text-tinta-suave transition-colors hover:bg-relleno"
          >
            ← Vista clásica
          </button>
        </div>
      </aside>
      {/* Sin margen propio: el hueco de la barra ya lo hace el relleno de la
          página, y sumarlo aquí lo empujaría dos veces. */}
      {/* AQUÍ IBA LA CABECERA, Y SE MUDÓ DENTRO DEL PANEL.
          Iba en una banda blanca por ENCIMA del panel gris, o sea fuera de la
          sección que titula. Canales, que sí la tenía dentro, se veía mejor por
          eso: el título y lo que titula están en la misma caja.
          Ahora se dibuja arriba del todo dentro del panel y vale para las
          quince, también en la vista clásica, que no tenía ninguna. Ver
          `CABECERA_DE_TAB`. */}
    </>
  );
}

/**
 * EL PLAZO DE LA BURBUJA, EN MINUTOS.
 *
 * Se teclea en crudo y solo se interpreta AL SALIR del campo.
 *
 * Interpretándolo en cada tecla, el campo se peleaba con la mano: «0» —el
 * primer carácter de «0.5» y de «05»— no es un plazo válido, así que se
 * devolvía vacío y la tecla se perdía. El punto decimal, igual. No daba error:
 * simplemente no se podía escribir.
 *
 * Vacío sigue significando «el plazo de siempre», que son 3 minutos.
 */
function PlazoEnMinutos({
  valor,
  onValor,
}: {
  valor?: number;
  onValor: (minutos: number | undefined) => void;
}) {
  const [escrito, setEscrito] = useState(valor === undefined ? "" : String(valor));
  const escribiendo = useRef(false);
  useEffect(() => {
    if (!escribiendo.current) {
      setEscrito(valor === undefined ? "" : String(valor));
    }
  }, [valor]);
  const interpretar = () => {
    escribiendo.current = false;
    const limpio = escrito.trim().replace(",", ".");
    const n = Number(limpio);
    const bueno = limpio !== "" && Number.isFinite(n) && n > 0 ? n : undefined;
    setEscrito(bueno === undefined ? "" : String(bueno));
    if (bueno !== valor) onValor(bueno);
  };
  return (
    <input
      type="text"
      inputMode="decimal"
      value={escrito}
      onFocus={() => {
        escribiendo.current = true;
      }}
      onChange={(e) => setEscrito(e.target.value)}
      onBlur={interpretar}
      onKeyDown={(e) => {
        if (e.key === "Enter") e.currentTarget.blur();
      }}
      placeholder="3"
      className="w-20 rounded-md border border-amber-300 bg-tarjeta px-2 py-1 text-sm font-semibold normal-case tracking-normal text-neutral-900"
    />
  );
}

function BubbleDecisionsEditor({
  decisions,
  onChange,
  espera,
  onEspera,
  pideNombre,
  onPideNombre,
  onSnapshot,
  onEdit,
  idPrefix,
}: {
  decisions: EditorBubbleDecision[];
  onChange: (decisions: EditorBubbleDecision[]) => void;
  /** Minutos que espera ESTA burbuja. `undefined` = el plazo de siempre. */
  espera?: number;
  onEspera: (minutos: number | undefined) => void;
  /** true = lo que conteste aquí se guarda como su nombre. */
  pideNombre: boolean;
  onPideNombre: (pide: boolean) => void;
  onSnapshot: () => void;
  onEdit: (key: string) => void;
  idPrefix: string;
}) {
  const [abierta, setAbierta] = useState<number | null>(null);
  const [menu, setMenu] = useState<{ index: number; x: number; y: number } | null>(
    null
  );
  const update = (index: number, patch: Partial<EditorBubbleDecision>) => {
    onEdit(`${idPrefix}:${index}`);
    onChange(
      decisions.map((d, i) => (i === index ? { ...d, ...patch } : d))
    );
  };
  const laAbierta = abierta !== null ? decisions[abierta] : undefined;
  return (
    <div className="mt-4 border-t border-emerald-200 pt-3">
      {laAbierta && abierta !== null && (
        <BubbleDecisionModal
          decision={laAbierta}
          onGuardar={(cambios) => {
            onSnapshot();
            update(abierta, cambios);
            setAbierta(null);
          }}
          onCerrar={() => setAbierta(null)}
          onSnapshot={onSnapshot}
          onEdit={onEdit}
          idPrefix={`${idPrefix}:${laAbierta.id}`}
        />
      )}
      {menu && (
        <>
          <div
            className="fixed inset-0 z-40"
            onClick={() => setMenu(null)}
            onContextMenu={(e) => {
              e.preventDefault();
              setMenu(null);
            }}
          />
          <div
            className="fixed z-50 rounded-md border border-neutral-300 bg-tarjeta py-1 shadow-lg"
            style={{ left: menu.x, top: menu.y }}
          >
            <button
              type="button"
              onClick={() => {
                onSnapshot();
                update(menu.index, {
                  enabled: decisions[menu.index]?.enabled === false,
                });
                setMenu(null);
              }}
              className="block w-full whitespace-nowrap px-4 py-1.5 text-left text-sm text-neutral-700 hover:bg-neutral-100"
            >
              {decisions[menu.index]?.enabled === false
                ? "🟢 Encender esta decisión"
                : "⚪ Apagar esta decisión"}
            </button>
            <button
              type="button"
              onClick={() => {
                // CON CONFIRMACIÓN. Antes borraba al primer clic: un clic
                // derecho mal apuntado se llevaba el cuadrito con todo su
                // contenido, y lo que se pierde ahí es texto escrito a mano.
                const cual =
                  decisions[menu.index]?.title?.trim() || "esta decisión";
                if (
                  !confirm(
                    `¿Borrar «${cual}» y todo lo que escribiste dentro? Puedes deshacerlo con ↶ Deshacer.`
                  )
                ) {
                  setMenu(null);
                  return;
                }
                onSnapshot();
                onChange(decisions.filter((_, i) => i !== menu.index));
                setMenu(null);
              }}
              className="block w-full whitespace-nowrap px-4 py-1.5 text-left text-sm text-red-700 hover:bg-red-50"
            >
              🗑️ Borrar esta decisión
            </button>
          </div>
        </>
      )}
      <div className="mb-2 flex items-center justify-between gap-2">
        <div>
          <p className="text-sm font-semibold text-emerald-950">Decisiones</p>
          <p className="text-[11px] text-emerald-800">
            Respuestas posibles a la pregunta de esta burbuja. El cliente
            contesta escribiendo; tú defines qué palabras activan cada una.
          </p>
        </div>
        <div className="flex shrink-0 items-center gap-2">
          {/* APAGAR TODAS es una ACCIÓN sobre los cuadritos, no un interruptor
              guardado. Un dato aparte que dijera "decisiones encendidas" podría
              contradecir a la lista —encendido sin cuadritos, apagado con
              cuadritos— y habría dos verdades para lo mismo. Así el estado se
              lee de los propios cuadritos y no puede mentir. */}
          {decisions.length > 0 && (
            <button
              type="button"
              onClick={() => {
                onSnapshot();
                const apagar = decisions.some((d) => d.enabled !== false);
                onChange(decisions.map((d) => ({ ...d, enabled: !apagar })));
              }}
              title="Apagar o encender todas de golpe, para probar sin borrar nada"
              className="rounded border border-neutral-300 bg-tarjeta px-2 py-1 text-xs font-semibold text-neutral-600 hover:bg-neutral-50"
            >
              {decisions.some((d) => d.enabled !== false)
                ? "Apagar todas"
                : "Encender todas"}
            </button>
          )}
          <button
            type="button"
            onClick={() => {
              onSnapshot();
              const id =
                typeof crypto?.randomUUID === "function"
                  ? crypto.randomUUID()
                  : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
              onChange([
                ...decisions,
                { id, title: "", keywords: [], steps: [], color: "gris" },
              ]);
            }}
            className="rounded border border-emerald-300 bg-emerald-50 px-2 py-1 text-xs font-semibold text-emerald-800 hover:bg-emerald-100"
          >
            + Agregar decisiones
          </button>
        </div>
      </div>
      {decisions.length === 0 ? (
        <p className="text-xs text-neutral-500">
          Sin decisiones, esta burbuja funciona como siempre.
        </p>
      ) : (
        <div className="flex flex-wrap gap-2">
          {decisions.map((decision, index) => (
            <button
              key={decision.id}
              type="button"
              onClick={() => setAbierta(index)}
              onContextMenu={(evento) => {
                evento.preventDefault();
                setMenu({ index, x: evento.clientX, y: evento.clientY });
              }}
              title="Clic para editar · clic derecho para apagar o borrar"
              className={`min-w-[92px] rounded-md border px-4 py-2 text-sm font-bold uppercase tracking-wide shadow-sm ${
                decision.enabled === false
                  ? "border-neutral-300 bg-neutral-200 text-neutral-500 line-through"
                  : CLASE_DE_COLOR(decision.color)
              }`}
            >
              {decision.title?.trim() || "sin título"}
              {/* La cadenita dice de un vistazo cuáles están linkeados, sin
                  abrir uno por uno. */}
              {decision.action && <span className="ml-1 opacity-80">🔗</span>}
            </button>
          ))}
        </div>
      )}
      {decisions.length > 0 && (
        <div className="mt-2 space-y-1 text-[11px]">
          <p className="text-neutral-500">
            Clic para llenar · clic derecho para apagar o borrar.
          </p>
          {/* El estado se LEE de los cuadritos, no de un interruptor: así lo
              que dice aquí no puede contradecir lo que se ve arriba. */}
          {decisions.every((d) => d.enabled === false) ? (
            <p className="rounded border border-neutral-300 bg-neutral-100 px-2 py-1 text-neutral-700">
              <strong>Todas apagadas:</strong> esta burbuja no espera respuesta.
              Se comporta como cualquier otra y la intro sigue de corrido.
            </p>
          ) : decisions.some(
              (d) =>
                d.enabled !== false &&
                (d.keywords ?? []).filter((k) => k.trim()).length === 0
            ) ? (
            <p className="text-neutral-500">
              Tienes un cuadrito sin palabras: ese atiende cualquier otra
              respuesta.
            </p>
          ) : (
            <p className="text-neutral-500">
              Si ninguna coincide con lo que escriba el cliente, la conversación
              sigue su camino normal. Un cuadrito sin palabras atiende todo lo
              demás.
            </p>
          )}
        </div>
      )}
      {/* ESTA BURBUJA PREGUNTA EL NOMBRE.
          Era lo ÚNICO que el saludo sabía hacer y una burbuja no. No lleva
          cuadritos a propósito: un nombre es texto libre y no hay palabra clave
          que lo reconozca, así que esto detiene la intro por su cuenta. */}
      <label className="mt-3 flex cursor-pointer items-start gap-2 rounded-lg border border-sky-200 bg-sky-50 px-3 py-2">
        <input
          type="checkbox"
          checked={pideNombre}
          onChange={(e) => {
            onSnapshot();
            onPideNombre(e.target.checked);
          }}
          className="mt-0.5 h-4 w-4 accent-sky-700"
        />
        <span className="text-[11px] leading-4 text-sky-950">
          <strong>Aquí le pregunto su nombre.</strong> Lo que conteste se guarda
          como su nombre y se usa en el CRM, en los avisos de pago y en el
          nombre que se manda a Meta. La burbuja espera la respuesta, sin
          necesidad de cuadritos.
        </span>
      </label>
      {/* EL PLAZO DE ESTA BURBUJA.
          Solo sale si la burbuja de verdad espera algo: un cuadrito ENCENDIDO o
          la pregunta del nombre. Sin eso no hay pausa que medir, y una casilla
          de tiempo ahí sería un número que no hace nada. */}
      {(pideNombre || decisions.some((d) => d.enabled !== false)) && (
        <div className="mt-3 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2">
          <label className="flex flex-wrap items-center gap-2 text-[11px] font-bold uppercase tracking-wide text-amber-950">
            <span aria-hidden>🕐</span>
            Cuánto espera esta burbuja
            {/* SE ESCRIBE EN CRUDO Y SE INTERPRETA AL SALIR.
                Aquí el valor se interpretaba en CADA tecla y se devolvía al
                campo: escribir «0» —el primer carácter de «0.5», o de «05»— daba
                un número no válido, el campo se vaciaba solo y la tecla se
                perdía. Lo mismo con el punto decimal.
                Ahora se guarda lo tecleado tal cual mientras se escribe, y solo
                al salir del campo se convierte en número. Es el mismo criterio
                que el resto de las casillas numéricas del editor. */}
            <PlazoEnMinutos
              valor={espera}
              onValor={(minutos) => {
                onSnapshot();
                onEspera(minutos);
              }}
            />
            <span className="font-normal normal-case tracking-normal text-amber-900">
              minutos
            </span>
          </label>
          <p className="mt-1 text-[11px] leading-4 text-amber-900">
            Pasado ese tiempo sin respuesta, salen las burbujas siguientes. La
            oferta no se cierra: si contesta después, se le atiende igual.{" "}
            <strong>Vacío = 3 minutos</strong>, que es lo que hacían todas hasta
            ahora.
          </p>
        </div>
      )}
    </div>
  );
}

/** La ventana donde se llena una decisión: título, palabras y burbujas. */
function BubbleDecisionModal({
  decision,
  onGuardar,
  onCerrar,
  onSnapshot,
  onEdit,
  idPrefix,
}: {
  decision: EditorBubbleDecision;
  onGuardar: (cambios: Partial<EditorBubbleDecision>) => void;
  onCerrar: () => void;
  onSnapshot: () => void;
  onEdit: (key: string) => void;
  idPrefix: string;
}) {
  // Borrador: "Listo" guarda, Escape y el clic fuera descartan. Igual que el
  // resto de las ventanas del editor.
  const [titulo, setTitulo] = useState(decision.title ?? "");
  const [palabras, setPalabras] = useState((decision.keywords ?? []).join(", "));
  const [palabrasAbiertas, setPalabrasAbiertas] = useState(false);
  const [color, setColor] = useState(decision.color ?? "gris");
  const [pasos, setPasos] = useState<EditorStep[]>(decision.steps ?? []);
  const enElTablero = useContext(EnElTableroContext);
  // El menú guarda la FAMILIA ("choose_product"); cuál de los tres productos
  // es va en su propio selector. Al abrir se hace el camino de vuelta: un
  // cuadrito guardado como choose_combo se enseña como "Elegir producto" + FULL.
  const [link, setLink] = useState<string>(
    esElegirProducto(decision.action) ? "choose_product" : (decision.action ?? "")
  );
  const [producto, setProducto] = useState<DecisionAction>(
    esElegirProducto(decision.action)
      ? (decision.action as DecisionAction)
      : "choose_basico"
  );
  const [metodo, setMetodo] = useState(decision.payment_method ?? "");
  const metodosDisponibles = useContext(PaymentMethodsContext);
  const [workflowElegido, setWorkflowElegido] = useState(decision.workflow_id ?? "");
  const workflowsDisponibles = useContext(WorkflowsContext);
  useEffect(() => {
    const alPulsar = (evento: KeyboardEvent) => {
      if (evento.key !== "Escape") return;
      evento.preventDefault();
      // Con la ventana de palabras abierta, Escape cierra ESA. Cerrando las dos
      // se perdería todo lo escrito en la decisión por querer salir del campo.
      if (palabrasAbiertas) {
        setPalabrasAbiertas(false);
        return;
      }
      onCerrar();
    };
    window.addEventListener("keydown", alPulsar);
    return () => window.removeEventListener("keydown", alPulsar);
  }, [onCerrar, palabrasAbiertas]);
  const guardar = () =>
    onGuardar({
      title: titulo.trim(),
      color,
      // Se limpian al guardar, no al escribir: si no, la coma recién tecleada
      // desaparecería y no se podría escribir la siguiente palabra.
      // Coma O salto de línea: en la ventana grande se escriben una por
      // renglón, y ahí la coma sobra.
      keywords: palabras
        .split(/[,\n\r]+/)
        .map((p) => p.trim())
        .filter(Boolean),
      steps: pasos,
      action:
        link === "choose_product"
          ? producto
          : ((link || undefined) as DecisionAction | undefined),
      payment_method:
        link === "send_payment_method" ? metodo.trim() : undefined,
      workflow_id: link === "start_workflow" ? workflowElegido.trim() : undefined,
    });
  return (
    <div
      className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-black/40 p-4"
      onClick={() => {
        // TOCAR EL CAMPO DE PALABRAS CERRABA LA DECISIÓN ENTERA.
        //
        // El campo vive dentro del cuadro blanco, que frena los clics; la
        // ventana grande de palabras es HERMANA de ese cuadro y cuelga de este
        // fondo. Al tocar el campo, el dedo se levanta cuando la ventana YA se
        // abrió encima — se aprieta en un sitio y se suelta en otro, así que el
        // navegador dispara el clic en el ancestro común de ambos: este fondo.
        // Y este fondo descarta. De ahí que se abriera medio segundo y se
        // cerrara sola, como si hubieran dado a Cancelar. Tocar el título nunca
        // falló porque el título sí está dentro del cuadro blanco.
        //
        // Con la ventana de palabras abierta, este fondo no cierra nada: ella
        // tapa la pantalla entera y tiene su propio cierre.
        if (palabrasAbiertas) return;
        onCerrar();
      }}
    >
      {/* Las palabras, en grande. Va por encima de esta ventana (z-60) y come
          los clics para que cerrar aquí no cierre también la de atrás. */}
      {palabrasAbiertas && (
        <div
          className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4"
          onClick={(evento) => {
            evento.stopPropagation();
            setPalabrasAbiertas(false);
          }}
        >
          <div
            className="w-full max-w-2xl rounded-lg border border-neutral-300 bg-tarjeta shadow-xl"
            onClick={(evento) => evento.stopPropagation()}
          >
            <div className="flex items-center justify-between border-b border-neutral-200 px-4 py-3">
              <h4 className="text-sm font-bold text-neutral-900">
                Palabras que activan «{titulo.trim() || "esta respuesta"}»
              </h4>
              <button
                type="button"
                onClick={() => setPalabrasAbiertas(false)}
                className="rounded bg-emerald-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-emerald-700"
              >
                Listo
              </button>
            </div>
            <div className="p-4">
              <textarea
                autoFocus
                rows={10}
                value={palabras}
                onChange={(e) => setPalabras(e.target.value)}
                placeholder={"si, si tengo, claro, un poco, algo\n\nPuedes escribirlas separadas por comas o una por renglón."}
                className="w-full resize-y rounded border border-neutral-300 px-3 py-2 text-sm leading-6"
              />
              <p className="mt-2 text-[11px] text-neutral-600">
                Separa con <strong>comas</strong> o con un{" "}
                <strong>salto de línea</strong>: las dos valen. Se comparan sin
                tildes ni mayúsculas y por palabras completas.
              </p>
            </div>
          </div>
        </div>
      )}
      <div
        className="my-8 w-full max-w-5xl rounded-lg border border-neutral-300 bg-tarjeta shadow-xl"
        onClick={(evento) => evento.stopPropagation()}
      >
        <div className="flex flex-wrap items-center justify-between gap-3 border-b border-neutral-200 px-4 py-3">
          <div className="flex items-center gap-3">
            <h3 className="text-sm font-bold text-neutral-900">
              Editar esta decisión
            </h3>
            <span
              className={`rounded px-3 py-1 text-xs font-bold uppercase ${CLASE_DE_COLOR(color)}`}
            >
              {titulo.trim() || "sin título"}
            </span>
          </div>
          <div className="flex items-center gap-2">
            <span className="hidden text-[11px] text-neutral-500 sm:inline">
              Escape o Cancelar = descartar
            </span>
            <button
              type="button"
              onClick={onCerrar}
              className="rounded border border-neutral-300 px-3 py-1.5 text-xs font-semibold text-neutral-600 hover:bg-neutral-50"
            >
              Cancelar
            </button>
            <button
              type="button"
              onClick={guardar}
              className="rounded bg-emerald-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-emerald-700"
            >
              Listo
            </button>
          </div>
        </div>

        <div className="grid gap-3 border-b border-neutral-200 px-4 py-3 md:grid-cols-[200px_minmax(0,1fr)_auto]">
          <label className="block text-xs font-medium text-neutral-700">
            Título del cuadrito
            <input
              value={titulo}
              onChange={(e) => setTitulo(e.target.value)}
              placeholder="Ej: SI"
              className="mt-1 w-full rounded border border-neutral-300 px-2 py-1.5 text-sm"
            />
            <span className="mt-1 block text-[11px] text-neutral-500">
              Solo para que sepas cuál es cuál.
            </span>
          </label>
          <label className="block text-xs font-medium text-neutral-700">
            Palabras que activan esta respuesta (separadas por comas)
            {/* AL HACER CLIC SE ABRE EN GRANDE.
                En una sola línea hay que ir empujando el texto hacia la derecha
                para leer lo que está tapado. Un campo alto aquí deformaría el
                cajón, así que el campo se queda como está y la ventana se abre
                encima, con los renglones que hagan falta. */}
            <input
              value={palabras}
              readOnly
              onFocus={() => setPalabrasAbiertas(true)}
              onClick={() => setPalabrasAbiertas(true)}
              title="Clic para escribirlas en grande"
              placeholder="si, si tengo, claro, un poco, algo"
              className="mt-1 w-full cursor-pointer rounded border border-neutral-300 px-2 py-1.5 text-sm hover:border-emerald-400 hover:bg-emerald-50/40"
            />
            <span className="mt-1 block text-[11px] text-neutral-500">
              Clic para escribirlas en grande.{" "}
            </span>
            <span className="mt-1 block text-[11px] text-neutral-500">
              Se comparan sin tildes ni mayúsculas y por palabras completas. Si
              dos cuadritos comparten una, gana el que esté antes en la fila.
            </span>
            {/* Dejarlo vacío ES la forma de pedir el comodín. Sin este aviso
                parecería un cuadrito a medio llenar. */}
            {palabras.trim() === "" && (
              <span className="mt-1 block rounded border border-amber-200 bg-amber-50 px-2 py-1 text-[11px] text-amber-900">
                Sin palabras, este cuadrito es el de{" "}
                <strong>cualquier otra respuesta</strong>: salta cuando ninguno
                de los demás acertó. Déjalo al final de la fila.
              </span>
            )}
          </label>
          <div className="text-xs font-medium text-neutral-700">
            Color
            <div className="mt-1 flex gap-1">
              {COLORES_DE_DECISION.map((c) => (
                <button
                  key={c.valor}
                  type="button"
                  onClick={() => setColor(c.valor)}
                  title={c.valor}
                  className={`h-7 w-7 rounded border-2 ${c.clase} ${color === c.valor ? "ring-2 ring-neutral-900 ring-offset-1" : ""}`}
                />
              ))}
            </div>
          </div>
        </div>

        {/* EL LINK DEL CUADRITO.
            Un comodín dentro del texto pega un dato; esto, además, DEJA ALGO
            ANOTADO. Poner {{PRECIO_BASE}} en el cuadrito del básico enseña el
            precio correcto, pero el bot sigue sin saber qué eligió el cliente —
            y de ese apunte dependen el precio contra el que se valida el
            comprobante y el producto que se entrega. */}
        {enElTablero ? (
          <p className="border-b border-neutral-200 bg-sky-50/50 px-4 py-3 text-xs text-neutral-700">
            🧩 En el tablero, este cuadrito manda sus burbujas y luego lleva a donde conectes{" "}
            <strong>su cable</strong> (su puntito en la ficha).
          </p>
        ) : (
        <div className="grid gap-3 border-b border-neutral-200 bg-sky-50/50 px-4 py-3 md:grid-cols-2">
          <label className="block text-xs font-medium text-neutral-700">
            🔗 Linkear con (opcional)
            <select
              value={link}
              onChange={(e) => setLink(e.target.value)}
              className="mt-1 block w-full rounded border border-neutral-300 bg-tarjeta px-2 py-1.5 text-sm"
            >
              <option value="">— Nada, solo manda sus burbujas —</option>
              {LINKS_DE_DECISION.map((l) => (
                <option key={l.valor} value={l.valor}>
                  {l.texto}
                </option>
              ))}
            </select>
            <span className="mt-1 block text-[11px] text-neutral-600">
              Se ejecuta <strong>después</strong> de tus burbujas. Para elegir
              producto usa esto y no un comodín: además de mandar sus datos,
              deja anotado qué compró.
            </span>
          </label>
          {link === "choose_product" && (
            <label className="block text-xs font-medium text-neutral-700">
              ¿Qué producto elige?
              <select
                value={producto}
                onChange={(e) => setProducto(e.target.value as DecisionAction)}
                className="mt-1 block w-full rounded border border-neutral-300 bg-tarjeta px-2 py-1.5 text-sm"
              >
                {PRODUCTOS_DE_DECISION.map((p) => (
                  <option key={p.valor} value={p.valor}>
                    {p.texto}
                  </option>
                ))}
              </select>
              <span className="mt-1 block text-[11px] text-neutral-600">
                Manda los datos de pago de ese producto —con su precio y el país
                del cliente— y deja anotado que eligió ese.
              </span>
              {/* Aviso honesto: el segundo producto no existe en todas las
                  modalidades, y ahí el cuadrito no haría nada. Mejor decirlo
                  aquí que descubrirlo con un cliente esperando. */}
              {producto === "choose_upsell" && (
                <span className="mt-1 block rounded border border-amber-200 bg-amber-50 px-2 py-1 text-[11px] text-amber-900">
                  El segundo producto solo existe en las modalidades{" "}
                  <strong>Upsell</strong> y{" "}
                  <strong>Doble Oferta + Upsell</strong>, y necesita nombre,
                  precio y entrega. En las demás, este cuadrito manda sus
                  burbujas y nada más.
                </span>
              )}
            </label>
          )}
          {link === "send_payment_method" && (
            <label className="block text-xs font-medium text-neutral-700">
              ¿Qué método manda?
              <select
                value={metodo}
                onChange={(e) => setMetodo(e.target.value)}
                className="mt-1 block w-full rounded border border-neutral-300 bg-tarjeta px-2 py-1.5 text-sm"
              >
                <option value="">— Elige uno —</option>
                {metodosDisponibles.map((m) => (
                  <option key={m.method} value={m.method}>
                    {m.label}
                  </option>
                ))}
              </select>
              <span className="mt-1 block text-[11px] text-neutral-600">
                Sus datos salen de Precios y pagos, los del país de cada
                cliente. No se escriben aquí.
              </span>
              {!metodo.trim() && (
                <span className="mt-1 block text-[11px] text-amber-700">
                  Sin método elegido, este link no manda nada.
                </span>
              )}
            </label>
          )}
          {link === "start_workflow" && (
            <label className="block text-xs font-medium text-neutral-700">
              ¿Qué workflow arranca?
              <select
                value={workflowElegido}
                onChange={(e) => setWorkflowElegido(e.target.value)}
                className="mt-1 block w-full rounded border border-neutral-300 bg-tarjeta px-2 py-1.5 text-sm"
              >
                <option value="">— Elige uno —</option>
                {workflowsDisponibles.map((w) => (
                  <option key={w.id} value={w.id}>
                    {w.nombre}
                  </option>
                ))}
              </select>
              <span className="mt-1 block text-[11px] text-neutral-600">
                Tras sus burbujas, el cliente deja la venta automática y sigue ese workflow desde su ▶ Inicio.
              </span>
            </label>
          )}
        </div>
        )}

        {/* Editor a la izquierda, visor de WhatsApp a la derecha — el mismo
            reparto que el resto de las burbujas del editor. */}
        <div className="grid max-h-[60vh] gap-4 overflow-y-auto p-4 lg:grid-cols-[minmax(0,1fr)_minmax(260px,340px)]">
          <div className="min-w-0">
            <StepList
              steps={pasos}
              onChange={setPasos}
              onSnapshot={onSnapshot}
              onEdit={onEdit}
              idPrefix={idPrefix}
              allowButtons={false}
            />
          </div>
          <div className="lg:sticky lg:top-0 lg:self-start">
            <p className="mb-1 text-[11px] font-medium text-neutral-500">
              Así le llega al cliente
            </p>
            <ChatPreview steps={pasos} />
          </div>
        </div>
      </div>
    </div>
  );
}

function BubbleButtonsEditor({
  buttons,
  onChange,
  onSnapshot,
  onEdit,
  idPrefix,
}: {
  buttons: EditorBubbleButton[];
  onChange: (buttons: EditorBubbleButton[]) => void;
  onSnapshot: () => void;
  onEdit: (key: string) => void;
  idPrefix: string;
}) {
  const update = (index: number, patch: Partial<EditorBubbleButton>) => {
    onEdit(`${idPrefix}:${index}`);
    onChange(buttons.map((button, i) => i === index ? { ...button, ...patch } : button));
  };
  const metodosDePagoDisponibles = useContext(PaymentMethodsContext);
  const enElTablero = useContext(EnElTableroContext);
  const workflowsDisponibles = useContext(WorkflowsContext);
  // Qué botón tiene la ventana abierta. null = ninguna.
  const [botonAbierto, setBotonAbierto] = useState<number | null>(null);
  const abierto = botonAbierto !== null ? buttons[botonAbierto] : undefined;
  return (
    <div className="mt-4 border-t border-violet-200 pt-3">
      {abierto && botonAbierto !== null && (
        <BubbleButtonStepsModal
          titulo={abierto.label.trim() || "este botón"}
          steps={abierto.steps ?? []}
          onGuardar={(steps) => {
            onSnapshot();
            update(botonAbierto, { steps });
            setBotonAbierto(null);
          }}
          onCerrar={() => setBotonAbierto(null)}
          onSnapshot={onSnapshot}
          onEdit={onEdit}
          idPrefix={`${idPrefix}:${abierto.id}:reply`}
        />
      )}
      <div className="mb-2 flex items-center justify-between gap-2">
        <div>
          <p className="text-sm font-semibold text-violet-950">Botones debajo de esta burbuja</p>
          <p className="text-[11px] text-violet-800">Máximo 3. Cada botón ejecuta solo la acción que elijas.</p>
        </div>
        <button type="button" disabled={buttons.length >= 3} onClick={() => {
          onSnapshot();
          const id = typeof crypto?.randomUUID === "function" ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
          onChange([...buttons, { id, label: "", action: "send_steps", steps: [] }]);
        }} className="rounded border border-violet-300 bg-violet-50 px-2 py-1 text-xs font-semibold text-violet-800 disabled:opacity-40">+ Agregar botón</button>
      </div>
      <div className="space-y-3">
        {buttons.map((button, index) => (
          <div key={button.id} className="rounded-md border border-violet-200 bg-violet-50/50 p-3">
            {/* EL NOMBRE DEL BOTÓN, EN SU PROPIA LÍNEA.
                Los tres campos iban en una sola fila —nombre, acción, papelera—
                y la acción se lleva 220 px fijos. Este editor no vive a lo
                ancho de la página: vive dentro de la columna de la izquierda,
                que es la mitad de una mitad. Ahí al nombre le quedaban unos
                100 px y al escribir una letra ni se veía.
                Ahora el nombre ocupa el ancho entero de su cajón y la acción va
                debajo, que además es el orden en que se llenan. */}
            <label className="block text-xs font-medium text-violet-950">
              Texto del botón (lo que ve el cliente)
              <input value={button.label} onChange={(e) => update(index, { label: e.target.value })} maxLength={20} placeholder="Ej: Quiero pagar" className="mt-1 block w-full min-w-0 rounded border border-neutral-300 bg-tarjeta px-2 py-1.5 text-sm" />
            </label>
            <div className="mt-2 grid gap-2 grid-cols-[minmax(0,1fr)_auto]">
              {/* LAS BURBUJAS SE CONSERVAN AL CAMBIAR DE ACCIÓN. Antes solo se
                  preparaban para «Enviar burbujas»; ahora cualquier acción puede
                  llevar su texto delante, así que lo escrito no se pierde por
                  cambiar el selector. */}
              {enElTablero ? (
                <p className="self-center text-xs text-violet-800">
                  🧩 En el tablero, este botón lleva a donde conectes <strong>su cable</strong> (su puntito en la ficha).
                </p>
              ) : (
              <select value={button.action} onChange={(e) => update(index, { action: e.target.value as BubbleButtonAction, steps: button.steps ?? [] })} className="min-w-0 rounded border border-neutral-300 bg-tarjeta px-2 py-1.5 text-sm">
                <option value="send_steps">Enviar burbujas / muestras</option>
                <option value="send_payment_method">Mandar los datos de un método de pago</option>
                <option value="show_payment">Mostrar métodos de pago</option>
                <option value="choose_combo">Elegir Combo</option>
                <option value="choose_basico">Elegir Básico</option>
                {/* LAS QUE FALTABAN, Y EL MOTOR YA SABÍA HACER.
                    `ejecutarAccion` es la misma función para botones y
                    cuadritos, y tiene su `case` para todas desde siempre. El
                    cuadrito las ofrecía y el botón no: era una lista corta, no
                    una limitación. */}
                <option value="choose_upsell">Elegir UPSELL (el segundo producto)</option>
                {/* EL «NO» DEL UPSELL (17/10/2026), igual que el botón nativo: cierra la oferta y
                    sigue con el regalo. Solo en botones: en los cuadritos del upsell el «no» ya lo
                    decide el detector de siempre, y con la acción además se rechazaría dos veces. */}
                <option value="decline_upsell">Rechazar UPSELL (sigue con el regalo)</option>
                <option value="show_order_bump">Abrir la oferta de 2 opciones</option>
                <option value="accept_gift">Regalo: aceptarlo</option>
                <option value="decline_gift">Regalo: rechazarlo</option>
                <option value="claim_gift">Regalo: entregarlo</option>
                <option value="human">Pasar a humano</option>
                <option value="start_workflow">▶ Activar un workflow</option>
              </select>
              )}
              <button type="button" onClick={() => { if (confirm("¿Quitar este botón?")) { onSnapshot(); onChange(buttons.filter((_, i) => i !== index)); } }} className="rounded border border-red-200 bg-tarjeta px-2 py-1 text-xs text-red-700">🗑️</button>
            </div>
            {!enElTablero && button.action === "start_workflow" && (
              // ▶ ACTIVAR UN WORKFLOW (23/10/2026): el cliente sale de la venta de siempre y entra
              // a ese workflow del tablero, desde su Inicio. Lo que estaba programado se cancela.
              <div className="mt-3 rounded border border-violet-100 bg-tarjeta p-2">
                <label className="block text-xs font-medium text-neutral-700">
                  ¿Qué workflow arranca?
                  <select
                    value={button.workflow_id ?? ""}
                    onChange={(e) => update(index, { workflow_id: e.target.value })}
                    className="mt-1 block w-full rounded border border-neutral-300 bg-tarjeta px-2 py-1.5 text-sm"
                  >
                    <option value="">— Elige uno —</option>
                    {workflowsDisponibles.map((w) => (
                      <option key={w.id} value={w.id}>
                        {w.nombre}
                      </option>
                    ))}
                  </select>
                </label>
                <p className="mt-1 text-xs text-neutral-600">
                  El cliente deja la venta automática y sigue ese workflow desde su ▶ Inicio. Los workflows se crean en Pizarra → Mis tiendas → Mis workflows.
                </p>
                {!button.workflow_id?.trim() && <p className="mt-1 text-xs text-amber-700">Sin workflow elegido, este botón no hace nada.</p>}
              </div>
            )}
            {!enElTablero && button.action === "send_payment_method" && (
              // SE ELIGE EL MÉTODO, NO SE COPIA SU TEXTO.
              //
              // Los datos de cada método viven en Precios y pagos, por país.
              // Aquí se guarda solo cuál mandar. Copiarlos sería tener el
              // número de cuenta en dos sitios: el día que cambie, uno de los
              // dos se queda viejo y el cliente paga a la cuenta que no era.
              <div className="mt-3 rounded border border-violet-100 bg-tarjeta p-2">
                <label className="block text-xs font-medium text-neutral-700">
                  ¿Qué método manda este botón?
                  <select
                    value={button.payment_method ?? ""}
                    onChange={(e) =>
                      update(index, { payment_method: e.target.value })
                    }
                    className="mt-1 block w-full rounded border border-neutral-300 bg-tarjeta px-2 py-1.5 text-sm"
                  >
                    <option value="">— Elige uno —</option>
                    {metodosDePagoDisponibles.map((metodo) => (
                      <option key={metodo.method} value={metodo.method}>
                        {metodo.label}
                      </option>
                    ))}
                  </select>
                </label>
                <p className="mt-1 text-xs text-neutral-600">
                  Los datos salen de <strong>Precios y pagos</strong>, los del
                  país de cada cliente. No se escriben aquí: así el número de
                  cuenta vive en un solo sitio.
                </p>
                {!button.payment_method?.trim() && (
                  <p className="mt-1 text-xs text-amber-700">
                    Sin método elegido, este botón no manda nada.
                  </p>
                )}
              </div>
            )}
            {!enElTablero && button.action !== "human" && button.action !== "start_workflow" && (
              // EL CONTENIDO DEL BOTÓN SE EDITA EN UNA VENTANA APARTE.
              //
              // Estaba abierto aquí dentro, y con dos o tres botones el panel
              // crecía tanto que la burbuja original quedaba fuera de la
              // pantalla: se editaba la respuesta sin ver a qué respondía.
              //
              // Aquí queda solo el resumen —cuántas burbujas y cómo empieza la
              // primera— que es lo que hace falta para saber que está lleno sin
              // tener que leerlo entero.
              //
              // ANTES SOLO SALÍA CON «Enviar burbujas», Y ESO OBLIGABA A ELEGIR.
              //
              // El dueño puso un botón «Quiero el descuento» con su texto propio
              // y el producto no se elegía; al cambiarlo a «Elegir Combo» sí se
              // elegía, pero su texto desaparecía. Una cosa o la otra.
              //
              // El cuadrito nunca tuvo ese problema: manda sus burbujas y DESPUÉS
              // ejecuta la acción. El botón podía hacer lo mismo — llama a la
              // misma función— solo que no se le daba dónde escribirlo.
              <div className="mt-3 flex flex-wrap items-center gap-2 rounded border border-violet-100 bg-tarjeta px-2 py-2">
                <button
                  type="button"
                  onClick={() => setBotonAbierto(index)}
                  className="rounded border border-violet-300 bg-violet-50 px-3 py-1.5 text-xs font-semibold text-violet-800 hover:bg-violet-100"
                >
                  ✏️ Editar lo que se envía
                </button>
                <span className="text-xs text-neutral-600">
                  {resumenDeBurbujas(button.steps ?? [])}
                </span>
                {button.action !== "send_steps" && (
                  <span className="basis-full text-[11px] leading-snug text-neutral-500">
                    Sale <strong>antes</strong> de ejecutar la acción. Déjalo vacío
                    y se ejecuta la acción a secas, como hasta ahora.
                  </span>
                )}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

function StepCard({
  draggableId,
  droppableId,
  index,
  total,
  step,
  isDragging,
  isDragTarget,
  isActive,
  onUpdate,
  onMove,
  onActivate,
  onDuplicate,
  onRemove,
  onVaryPreview,
  onUpdateText,
  onAddText,
  onDuplicateText,
  onRemoveText,
  onSnapshot,
  onEdit,
  allowButtons,
  enVentana = false,
}: {
  draggableId: string;
  droppableId: string;
  index: number;
  total: number;
  step: EditorStep;
  isDragging: boolean;
  isDragTarget: boolean;
  isActive: boolean;
  onUpdate: (patch: Partial<EditorStep>) => void;
  onMove: (dir: -1 | 1) => void;
  onActivate: () => void;
  onDuplicate: () => void;
  onRemove: () => void;
  onVaryPreview: () => void;
  onUpdateText: (ti: number, value: string) => void;
  onAddText: () => void;
  onDuplicateText: (ti: number) => void;
  onRemoveText: (ti: number) => void;
  onSnapshot: () => void;
  onEdit: (key: string) => void;
  allowButtons: boolean;
  /**
   * DENTRO DE LA VENTANA DE «EDITAR ESTA BURBUJA».
   *
   * Es el MISMO cajón, no una copia: la ventana tenía su propio editor a mano,
   * con cuatro campos, y el cajón tiene todo lo demás —el retardo, los botones,
   * los cuadritos, su plazo, la pregunta del nombre—. Dos editores para lo
   * mismo y uno siempre por detrás del otro.
   *
   * Ahí dentro cambian dos cosas, y solo dos. Sale desplegado, porque para eso
   * se abrió. Y se quitan mover, subir, bajar, duplicar y borrar: son de la
   * LISTA, no de la burbuja, y en la ventana no hay lista. Esos siguen donde
   * estaban, en el clic derecho.
   */
  enVentana?: boolean;
}) {
  const isMedia = step.type !== "text";
  // EL DESPLEGABLE DE LA BURBUJA SE RECUERDA. ANTES NO.
  //
  // ESTE ERA EL «CAJÓN 8 QUE SEGUÍA ABIERTO».
  //
  // Este abrir y cerrar no es el de los cajones grandes: es propio de la
  // burbuja y vivía SOLO en memoria. Al cambiar de pestaña la lista se
  // desmonta, y al volver se calculaba de nuevo con la misma regla de siempre:
  // «arranca cerrada si tiene texto».
  //
  // Así que una burbuja SIN texto —una imagen, un audio, una recién creada—
  // arrancaba abierta SIEMPRE. Se cerraba, se iba uno a otra pestaña, y al
  // volver estaba abierta otra vez. No es que no recordara lo que hiciste: es
  // que no lo guardaba en ninguna parte.
  //
  // Se guarda con la misma llave que usan los cajones, y por el mismo sitio, y
  // el arranque de siempre queda solo como respaldo para la primera vez.
  const llaveDelDesplegable = `wf:collapsible:burbuja:${draggableId}`;
  const [collapsed, setCollapsed] = useState(
    () => !enVentana && step.texts.some((t) => t.trim().length > 0)
  );
  useEffect(() => {
    if (enVentana) return;
    try {
      const guardado = localStorage.getItem(llaveDelDesplegable);
      if (guardado !== null) setCollapsed(guardado === "1");
    } catch {}
  }, [llaveDelDesplegable, enVentana]);
  const alternarDesplegable = () =>
    setCollapsed((c) => {
      const siguiente = !c;
      try {
        localStorage.setItem(llaveDelDesplegable, siguiente ? "1" : "0");
      } catch {}
      return siguiente;
    });
  const previewText = (() => {
    const first = step.texts.find((t) => t.trim().length > 0) ?? "";
    const oneLine = first.replace(/\s+/g, " ").trim();
    if (oneLine) return oneLine.length > 70 ? oneLine.slice(0, 70) + "…" : oneLine;
    if (isMedia) return step.drive_url ? "(media sin texto)" : "(vacío)";
    return "(sin texto)";
  })();
  const {
    attributes,
    listeners,
    setNodeRef: setDragHandleRef,
  } = useDraggable({
    id: draggableId,
    data: { index },
  });
  const { setNodeRef: setDropRef, isOver } = useDroppable({
    id: droppableId,
    data: { index },
  });
  return (
    <div
      ref={setDropRef}
      onClick={onActivate}
      className={`rounded-lg p-3 transition ${
        isDragging
          ? "border-2 border-black bg-transparent shadow-none opacity-70"
          : "bg-neutral-100 shadow"
      } ${
        step.enabled === false && !isDragging ? "opacity-60" : ""
      } ${
        // UNA SOLA LÍNEA, Y DEL MISMO GROSOR QUE LA NORMAL.
        //
        // Aquí había un borde de 2 px MÁS un aro de 2 px separado: dos líneas
        // de verdad, no una que se veía doble. En un Mac se funden en una y en
        // un PC se ven las dos, así que la misma burbuja se veía distinta según
        // la pantalla.
        //
        // Ahora solo cambia el COLOR del borde que ya tenía. Al no cambiar de
        // grosor tampoco da el saltito de un píxel al seleccionarla.
        // EL GROSOR SOLO CRECE EN LA SELECCIONADA. La línea gruesa es la marca
        // de «estoy aquí»: si la llevan todas, deja de marcar nada.
        isActive && !isDragging
          ? "border-2 border-emerald-600 bg-emerald-50 shadow-md"
          : isDragging
            ? ""
            : "border border-neutral-400"
      } ${
        isOver && !isDragging
          ? "border-sky-500 bg-neutral-300 brightness-90 ring-2 ring-sky-400"
          : ""
      }`}
    >
      <div>
      <div className="mb-3 flex flex-wrap items-start justify-between gap-2">
        <div className="flex min-w-0 flex-wrap items-center gap-2">
          <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-carbon-suave text-xs font-medium text-white">
            {index + 1}
          </span>
          {!enVentana && (
            <>
              <button
                type="button"
                ref={setDragHandleRef}
                onClick={(e) => e.stopPropagation()}
                {...listeners}
                {...attributes}
                title="Arrastrar para reordenar"
                className="shrink-0 cursor-grab rounded border border-sky-300 bg-tarjeta px-2 py-1 text-xs font-bold text-sky-700 active:cursor-grabbing"
              >
                ⋮⋮ Mover
              </button>
              <button
                type="button"
                onClick={() => onMove(-1)}
                disabled={index === 0}
                title="Subir esta burbuja"
                className="rounded border border-sky-200 bg-sky-50 px-2 py-1 text-xs font-bold text-sky-700 hover:bg-sky-100 disabled:opacity-30"
              >
                ↑ Subir
              </button>
              <button
                type="button"
                onClick={() => onMove(1)}
                disabled={index === total - 1}
                title="Bajar esta burbuja"
                className="rounded border border-sky-200 bg-sky-50 px-2 py-1 text-xs font-bold text-sky-700 hover:bg-sky-100 disabled:opacity-30"
              >
                ↓ Bajar
              </button>
            </>
          )}
          <select
            value={step.type}
            onChange={(e) => onUpdate({ type: e.target.value as StepType })}
            className="min-w-0 max-w-full rounded-md border border-neutral-300 bg-tarjeta px-2 py-1 text-xs text-neutral-800"
          >
            <option value="text">{TYPE_LABEL.text}</option>
            <option value="image">{TYPE_LABEL.image}</option>
            <option value="audio">{TYPE_LABEL.audio}</option>
            <option value="video">{TYPE_LABEL.video}</option>
            <option value="document">{TYPE_LABEL.document}</option>
          </select>
        </div>
        <div className="flex max-w-full flex-wrap items-center justify-end gap-1">
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              onVaryPreview();
            }}
            title="Variar vista previa de esta burbuja"
            aria-label="Variar vista previa de esta burbuja"
            className="flex h-7 w-7 shrink-0 items-center justify-center rounded border border-neutral-300 bg-tarjeta text-base font-semibold leading-none text-neutral-600 hover:bg-neutral-50"
          >
            ∞
          </button>
          <button
            type="button"
            onClick={() => onUpdate({ enabled: step.enabled === false })}
            title={
              step.enabled === false
                ? "Apagada: el bot NO la envía"
                : "Encendida: el bot la envía"
            }
            className={`rounded border px-2 py-1 text-xs font-semibold ${
              step.enabled === false
                ? "border-neutral-300 bg-neutral-100 text-neutral-400"
                : "border-emerald-300 bg-emerald-50 text-emerald-700"
            }`}
          >
            {step.enabled === false ? "OFF" : "ON"}
          </button>
          {!enVentana && (
            <>
              {/* separador: aísla el trash para evitar borrados accidentales */}
              <button
                type="button"
                onClick={onDuplicate}
                title="Duplicar paso"
                className="rounded border border-neutral-300 px-2 py-1 text-xs text-neutral-600 hover:bg-neutral-50"
              >
                ⧉
              </button>
              <span className="mx-1 h-6 w-px bg-neutral-300" aria-hidden="true" />
              <button
                type="button"
                onClick={onRemove}
                title="Eliminar paso"
                className="rounded border border-red-200 px-2 py-1 text-xs text-red-600 hover:bg-red-50"
              >
                🗑️
              </button>
              {/* separador antes del triángulo (extremo derecho) */}
              <span className="mx-1 h-6 w-px bg-neutral-300" aria-hidden="true" />
              <button
                type="button"
                onClick={alternarDesplegable}
                title={collapsed ? "Desplegar" : "Ocultar"}
                className="flex h-9 w-9 items-center justify-center rounded-md border border-neutral-300 bg-tarjeta text-2xl leading-none text-neutral-700 hover:bg-neutral-200"
              >
                {collapsed ? "◂" : "▾"}
              </button>
            </>
          )}
        </div>
      </div>

      {collapsed && (
        <p
          onClick={alternarDesplegable}
          className="cursor-pointer truncate text-xs text-neutral-500"
          title="Desplegar"
        >
          {previewText}
        </p>
      )}

      {!collapsed && (
        <>
          {isMedia && (
        <div className="mb-3">
          <div className="mb-1 flex items-center gap-2">
            <label className="text-sm font-semibold text-neutral-700">
              Enlace de Google Drive (
              {step.type === "image"
                ? "imagen"
                : step.type === "audio"
                  ? "audio"
                  : step.type === "video"
                    ? "video"
                    : "PDF"})
            </label>
            <BotonDeRefrescoDeMedia url={step.drive_url} />
          </div>
          <input
            type="text"
            value={step.drive_url}
            onChange={(e) => onUpdate({ drive_url: e.target.value })}
            placeholder="https://drive.google.com/file/d/.../view?usp=sharing"
            className="w-full rounded-md border border-neutral-300 bg-tarjeta px-3 py-2 text-xs text-neutral-800"
          />
        </div>
      )}

      {/* EL RÓTULO DECÍA «— VARIANTES» Y «EL BOT ELIGE UNA AL AZAR».
          Las dos frases hablaban de las cajas de variantes, que ya no existen.
          Un rótulo que nombra algo que no está es peor que no tener rótulo:
          manda a buscar una lista que no aparece por ninguna parte.
          En su sitio, lo que SÍ varía hoy: el spintax dentro del texto. */}
      <div className="mb-2 flex items-center justify-between gap-3">
        <span className="text-sm font-semibold text-neutral-700">
          {isMedia ? "Texto al pie (caption)" : "Texto"}
        </span>
        <span className="text-[11px] text-neutral-400">
          {"¿Varias formas de decirlo? {Hola|Buenas}"}
        </span>
      </div>

      {/* UN SOLO CAMPO, Y SIEMPRE A LA VISTA.
          ANTES PODÍA NO HABER NINGUNO. Si la lista de textos estaba vacía no se
          dibujaba ninguna casilla: se entraba al cajón y solo había un enlace
          «+ agregar variante». Quien no lo pulsara creía que la burbuja no se
          podía escribir.
          Y SE VAN LAS VARIANTES. Existían para que el bot eligiera una al azar
          entre varias; eso lo hace mejor el spintax dentro del propio texto
          —{"{Hola|Buenas}"}— sin partir el mensaje en cajas. De las que ya
          estén escritas se conserva LA PRIMERA; el resto desaparece al guardar.
          Es lo que el operador pidió, y queda dicho aquí para que nadie lo
          descubra echando de menos un texto. */}
      <div className="space-y-2">
        <div className="block w-full min-w-0">
          <EditorEmojiTextarea
            value={step.texts[0] ?? ""}
            onChange={(next) => onUpdateText(0, next)}
            rows={4}
            placeholder="Escribe el mensaje tal como llegará por WhatsApp…"
            className="texto-de-burbuja w-full rounded-md border border-neutral-300 bg-tarjeta px-3 py-2 text-sm text-neutral-800"
          />
        </div>
      </div>

      <div className="mt-3 flex items-center gap-2 border-t border-neutral-100 pt-3">
        <label className="text-xs text-neutral-500">
          Espera después de este paso:
        </label>
        <DraftNumberInput
          min={0}
          value={step.delay_after_sec}
          onValueChange={(delay_after_sec) =>
            onUpdate({ delay_after_sec })
          }
          className="w-20 rounded-md border border-neutral-300 bg-tarjeta px-2 py-1 text-xs text-neutral-800"
        />
        <span className="text-xs text-neutral-500">segundos</span>
      </div>
      {allowButtons && (
        <BubbleButtonsEditor
          buttons={step.buttons ?? []}
          onChange={(buttons) => onUpdate({ buttons })}
          onSnapshot={onSnapshot}
          onEdit={onEdit}
          idPrefix={`${draggableId}:buttons`}
        />
      )}
      {allowButtons && (
        <BubbleDecisionsEditor
          decisions={step.decisions ?? []}
          onChange={(decisions) => onUpdate({ decisions })}
          espera={step.espera_eleccion_minutos}
          onEspera={(espera_eleccion_minutos) =>
            onUpdate({ espera_eleccion_minutos })
          }
          pideNombre={step.capturar_nombre === true}
          onPideNombre={(capturar_nombre) => onUpdate({ capturar_nombre })}
          onSnapshot={onSnapshot}
          onEdit={onEdit}
          idPrefix={`${draggableId}:decisiones`}
        />
      )}
        </>
      )}
      </div>
    </div>
  );
}

