function compactSteps(steps: EditorStep[]): EditorStep[] {
  return steps.filter(
    (step) =>
      step.enabled !== false &&
      (step.drive_url.trim() || step.texts.some((text) => text.trim()))
  );
}

function activeIntroGroups(cfg: FullConfig): Array<{ label: string; steps: EditorStep[] }> {
  const mode = activeModality(cfg);
  const tpl = cfg.modality_templates?.[mode] ?? {};
  // AQUÍ IBA DELANTE UNA BURBUJA DE «Saludo inicial», Y SE VA.
  //
  // Esta lista alimenta el visor del recorrido y el clonado a canales. Mientras
  // el motor mandaba ese texto por delante, tenía que salir aquí. Ya no lo
  // manda: el cliente escribe y el bot contesta con la intro, entera. Dejarla
  // haría que el recorrido enseñara un mensaje que nadie recibe.
  const groups: Array<{ label: string; steps: EditorStep[] }> = [
    { label: tpl.intro_names?.[0] || "Intro 1", steps: tpl.intro_sequence ?? [] },
    { label: tpl.intro_names?.[1] || "Intro 2", steps: tpl.intro_sequence_2 ?? [] },
    { label: tpl.intro_names?.[2] || "Intro 3", steps: tpl.intro_sequence_3 ?? [] },
    ...((tpl.intro_extra_sequences ?? []).map((steps, index) => ({
      label: tpl.intro_names?.[index + 3] || `Intro ${index + 4}`,
      steps,
    }))),
  ];
  return groups
    .map((group) => ({ ...group, steps: compactSteps(group.steps) }))
    .filter((group) => group.steps.length > 0);
}

function followupTimeLabel(minutes: number): string {
  if (!Number.isFinite(minutes) || minutes <= 0) return "sin espera";
  if (minutes < 60) return `${minutes} min`;
  const hours = minutes / 60;
  if (Number.isInteger(hours) && hours < 24) return `${hours} h`;
  const days = hours / 24;
  if (Number.isInteger(days)) return `${days} dias`;
  return `${Math.round(hours * 10) / 10} h`;
}

function cloneJson<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T;
}

function cloneFollowupsForChannel(followups: EditorFollowup[]): EditorFollowup[] {
  return followups.map((followup) => ({
    ...cloneJson(followup),
    steps: cloneJson(followup.steps ?? []),
    variants: (followup.variants ?? []).map((variant) => ({
      ...cloneJson(variant),
      steps: cloneJson(variant.steps ?? []),
    })),
  }));
}

function channelDeliveryGroupsFromBase(
  cfg: FullConfig,
  mode: Modo
): ChannelDeliveryGroupEditor[] {
  const tpl = cfg.modality_templates?.[mode] ?? {};
  const centralDelivery = tpl.payment_approved ?? cfg.payment_approved ?? [];
  /**
   * LA ENTREGA DEL SEGUNDO PRODUCTO, EN LA MODALIDAD QUE SEA.
   *
   * Este grupo solo se ofrecía en las dos modalidades que podían tener etapa
   * Upsell. Ahora la puede tener cualquiera, y sin esta caja el canal se
   * quedaría a medias: el bot ofrecería el segundo producto y lo cobraría, pero
   * al entregarlo no tendría qué mandar por ese canal.
   *
   * Se añade solo cuando esa modalidad TIENE etapa escrita: una caja de entrega
   * para un producto que no existe es una caja que confunde.
   */
  const grupoDelUpsell = (): ChannelDeliveryGroupEditor[] => {
    const etapa = tpl.upsell;
    if (!(etapa?.name ?? "").trim()) return [];
    return [
      {
        key: "upsell",
        name: "UPSELL",
        enabled: true,
        steps: cloneJson(etapa?.delivery ?? []),
      },
    ];
  };
  if (mode === "order_bump") {
    const source = tpl.order_bump ?? cfg.order_bump;
    return [
      {
        key: "order_bump_basico",
        name: `Order Bump - Basico: ${source.basico.name || "Basico"}`,
        enabled: true,
        steps: cloneJson(source.basico.delivery ?? []),
      },
      {
        key: "order_bump_combo",
        name: `Order Bump - Combo: ${source.combo.name || "Combo"}`,
        enabled: true,
        steps: cloneJson(source.combo.delivery ?? []),
      },
      ...grupoDelUpsell(),
    ];
  }
  if (mode === "doble_oferta_dos") {
    const source = tpl.doble_oferta_dos ?? cfg.doble_oferta_dos;
    return [
      {
        key: "doble_oferta_dos_basico",
        name: `Doble Oferta 2 - Producto 2 / Basico: ${source.basico.name || "Producto 2"}`,
        enabled: true,
        steps: cloneJson(source.basico.delivery ?? []),
      },
      {
        key: "doble_oferta_dos_combo",
        name: `Doble Oferta 2 - Producto 1 / Combo: ${source.combo.name || "Producto 1"}`,
        enabled: true,
        steps: cloneJson(source.combo.delivery ?? []),
      },
      ...grupoDelUpsell(),
    ];
  }
  if (mode === "bioferta") {
    const source = tpl.bioferta ?? cfg.bioferta;
    return [
      {
        key: "bioferta_product_a",
        name: `Doble Oferta - Producto 1: ${source.product_a.name || "Producto 1"}`,
        enabled: true,
        steps: cloneJson(centralDelivery),
      },
      {
        key: "bioferta_product_b",
        name: `Doble Oferta - Producto 2: ${source.product_b.name || "Producto 2"}`,
        enabled: true,
        steps: cloneJson(source.product_b.delivery ?? []),
      },
      {
        key: "bioferta_pack",
        name: `Doble Oferta - Pack: ${source.pack.name || "Pack"}`,
        enabled: true,
        steps: cloneJson(source.pack.delivery ?? []),
      },
      ...grupoDelUpsell(),
    ];
  }
  if (mode === "doble_oferta_upsell") {
    // TRES productos, TRES entregas, cada una con su enlace.
    //
    // Antes esta modalidad caía en el caso de abajo y mostraba UNA sola caja
    // llamada "Entrega pago aprobado". Con tres enlaces distintos que meter,
    // eso era una invitación a equivocarse: no había forma de saber cuál iba
    // dónde, y el error solo se ve cuando una clienta recibe el producto que
    // no compró.
    //
    // EL TÍTULO ES FIJO. UNA PALABRA, SIEMPRE LA MISMA.
    //
    // Antes el título llevaba pegado el nombre del producto y encima venía de
    // un comodín cruzado: el cajón del BÁSICO se leía con el nombre del FULL
    // FULL". Quien llena estas cajas se guía por el título, así que llenó el
    // básico con el enlace del full — y el bot entregó exactamente lo que
    // estaba escrito ahí. El error no estaba en el motor: estaba en el rótulo.
    //
    // Ahora el título es una palabra que no depende de nada. El nombre del
    // producto va DENTRO de la caja, como comprobación, no como rótulo.
    const source = tpl.doble_oferta_dos ?? cfg.doble_oferta_dos;
    return [
      {
        key: "doble_oferta_dos_basico",
        name: "BÁSICO",
        enabled: true,
        steps: cloneJson(source.basico.delivery ?? []),
      },
      {
        key: "doble_oferta_dos_combo",
        name: "FULL",
        enabled: true,
        steps: cloneJson(source.combo.delivery ?? []),
      },
      // Su etapa sale ahora de SU capa, como la de las demás. Se leía de
      // `cfg.upsell` cuando la sección era una sola y se repartía a mano.
      ...grupoDelUpsell(),
    ];
  }
  // LINEAL, UPSELL Y CUALQUIER OTRA: la entrega central, y la del segundo
  // producto si esa modalidad tiene etapa escrita.
  //
  // La modalidad Upsell tenía su propia rama solo por eso. Ahora que la etapa es
  // de cada modalidad, la rama sobra: hace exactamente lo mismo que este final.
  return [
    {
      key: "central",
      name: "Entrega pago aprobado",
      enabled: true,
      steps: cloneJson(centralDelivery),
    },
    ...grupoDelUpsell(),
  ];
}

function buildChannelContentFromBase(
  cfg: FullConfig,
  channel: ChannelKey
): ChannelContentEditor {
  const mode = activeModality(cfg);
  const tpl = cfg.modality_templates?.[mode] ?? {};
  const sourceFollowups = tpl.followups ?? cfg.followups ?? [];
  const sourcePaymentApproved = tpl.payment_approved ?? cfg.payment_approved ?? [];
  const postSaleValues = extractPostSaleValues(cfg.prompt_sections.postventa ?? "");
  const postSale = adaptPostSaleForChannel(postSaleValues, channel);
  const introGroups = activeIntroGroupsForEditor(cfg).map((group) => ({
    name: group.label,
    enabled: group.enabled,
    weight: group.weight,
    adName: group.adName,
    adId: group.adId,
    skipAskName: group.skipAskName === true,
    steps: cloneJson(group.steps),
  }));
  return {
    intro_groups: introGroups,
    followups: cloneFollowupsForChannel(sourceFollowups),
    payment: compactSteps([
      {
        type: "text",
        drive_url: "",
        texts: [cfg.payment_text || cfg.payment_buttons_prompt || ""],
        delay_after_sec: 0,
      },
      ...(cfg.direct_payment_enabled ? cfg.direct_payment_steps ?? [] : []),
    ]),
    delivery: cloneJson(sourcePaymentApproved),
    delivery_groups: channelDeliveryGroupsFromBase(cfg, mode),
    post_sale: postSale,
  };
}

function activeIntroGroupsForEditor(
  cfg: FullConfig
): Array<{
  label: string;
  steps: EditorStep[];
  enabled: boolean;
  weight: number;
  adName: string;
  adId: string;
  skipAskName: boolean;
}> {
  const mode = activeModality(cfg);
  const tpl = cfg.modality_templates?.[mode] ?? {};
  // AQUÍ IBA DELANTE UN CAJÓN DE «Saludo inicial», Y SE VA.
  //
  // Esto es lo que se copia al clonar la Base hacia un canal. Mientras iba
  // delante, el canal nacía con un primer cajón que el motor trataba distinto:
  // se quedaba con su primera burbuja y descartaba el resto. Ahora el canal
  // nace con sus intros y nada más, y todas se mandan enteras.
  return [
    {
      label: tpl.intro_names?.[0] || "Intro 1",
      enabled: (tpl.intro_enabled?.[0] ?? false) === true,
      weight:
        typeof tpl.intro_weights?.[0] === "number" && tpl.intro_weights[0] > 0
          ? tpl.intro_weights[0]
          : 1,
      steps: tpl.intro_sequence ?? [],
      adName: tpl.intro_ad_names?.[0] ?? "",
      adId: tpl.intro_ad_ids?.[0] ?? "",
      skipAskName: tpl.intro_skip_ask_name?.[0] === true,
    },
    {
      label: tpl.intro_names?.[1] || "Intro 2",
      enabled: (tpl.intro_enabled?.[1] ?? false) === true,
      weight:
        typeof tpl.intro_weights?.[1] === "number" && tpl.intro_weights[1] > 0
          ? tpl.intro_weights[1]
          : 1,
      steps: tpl.intro_sequence_2 ?? [],
      adName: tpl.intro_ad_names?.[1] ?? "",
      adId: tpl.intro_ad_ids?.[1] ?? "",
      skipAskName: tpl.intro_skip_ask_name?.[1] === true,
    },
    {
      label: tpl.intro_names?.[2] || "Intro 3",
      enabled: (tpl.intro_enabled?.[2] ?? false) === true,
      weight:
        typeof tpl.intro_weights?.[2] === "number" && tpl.intro_weights[2] > 0
          ? tpl.intro_weights[2]
          : 1,
      steps: tpl.intro_sequence_3 ?? [],
      adName: tpl.intro_ad_names?.[2] ?? "",
      adId: tpl.intro_ad_ids?.[2] ?? "",
      skipAskName: tpl.intro_skip_ask_name?.[2] === true,
    },
    ...((tpl.intro_extra_sequences ?? []).map((steps, index) => ({
      label: tpl.intro_names?.[index + 3] || `Intro ${index + 4}`,
      enabled: (tpl.intro_enabled?.[index + 3] ?? false) === true,
      weight:
        typeof tpl.intro_weights?.[index + 3] === "number" &&
        tpl.intro_weights[index + 3] > 0
          ? tpl.intro_weights[index + 3]
          : 1,
      steps,
      adName: tpl.intro_ad_names?.[index + 3] ?? "",
      adId: tpl.intro_ad_ids?.[index + 3] ?? "",
      skipAskName: tpl.intro_skip_ask_name?.[index + 3] === true,
    }))),
  ].filter((group) => group.steps.length > 0);
}

function emptyChannelContent(): ChannelContentEditor {
  return {
    // Un canal nuevo nace con UNA intro, no con un saludo. No hay ningún cajón
    // que el motor trate distinto: todos se mandan enteros.
    intro_groups: [
      {
        name: "Intro 1",
        enabled: true,
        weight: 1,
        adName: "",
        adId: "",
        steps: [emptyStep()],
      },
    ],
    followups: [],
    payment: [emptyStep()],
    delivery: [emptyStep()],
    delivery_groups: [
      {
        key: "central",
        name: "Entrega pago aprobado",
        enabled: true,
        steps: [emptyStep()],
      },
    ],
    // La oferta y el upsell nacen VACÍOS a propósito: vacío significa «manda lo
    // de la modalidad», que es lo que hace hoy cualquier canal. Un canal nuevo
    // no puede empezar diciendo algo distinto sin que nadie lo haya escrito.
    order_bump_intro_groups: [],
    upsell_intro_groups: [],
    // Y la elección con botones, igual: en blanco manda la modalidad. Los
    // interruptores ni se nombran — ausente es «no opino».
    order_bump_choice_prompt: "",
    upsell_pregunta_steps: [],
    upsell_boton_si: "",
    upsell_boton_no: "",
    upsell_respuesta_rechazo: "",
    post_sale: {
      whatsappPreference: "",
      deliveryUsage: "",
      lifetimeAccess: "",
      farewells: "",
    },
  };
}

function savingsStarterRules(modality: Modo): SalesbotRuleEditor[] {
  const rule = (
    id: string,
    name: string,
    priority: number,
    keywords: string[],
    action: SalesbotRuleAction,
    response = "",
    states: string[] = ["intro_done"]
  ): SalesbotRuleEditor => ({
    ...emptySalesbotRule(),
    id,
    name,
    priority,
    keywords,
    action,
    response,
    states,
  });

  // Solo incluye respuestas que no requieren inventar contenido del producto.
  // Las dudas sobre beneficios, diferencias o recomendaciones siguen en IA.
  if (modality === "lineal") {
    return [
      rule(
        "ahorro_lineal_precio",
        "Respuesta rápida: precio",
        10,
        ["precio", "cuanto cuesta", "cuanto vale", "valor", "cuanto es"],
        "send_text",
        "Claro 😊 El valor actual de *{{PRODUCTO}}* es *{{PRECIO_COMPLETO}}*.\n\n¿Deseas que te indique los métodos de pago?"
      ),
      rule(
        "ahorro_lineal_metodos_pago",
        "Acción rápida: métodos de pago",
        20,
        ["metodos de pago", "formas de pago", "como pago", "como puedo pagar", "opciones de pago"],
        "send_payment_menu"
      ),
      rule(
        "ahorro_lineal_saludo",
        "Respuesta rápida: saludo",
        90,
        ["hola", "buenas", "buenos dias", "buenas tardes", "buenas noches"],
        "send_text",
        "¡Hola! 😊 ¿Qué te gustaría saber sobre *{{PRODUCTO}}*?"
      ),
      // ── MIENTRAS PAGA ──────────────────────────────────────────────────────
      //
      // Todas las reglas de arriba son de `intro_done`: valen ANTES de que el
      // cliente tenga la cuenta. En cuanto la tiene, la conversación pasa a
      // `payment_done` y no quedaba ni una — así que la etapa donde más escribe
      // la gente, y donde más se repiten las mismas cuatro preguntas, se iba
      // entera al modelo.
      //
      // Ninguna nombra un producto ni un método: todo sale de los comodines y
      // de la configuración del país. Es una plantilla.
      rule(
        "ahorro_lineal_pago_datos",
        "Acción rápida: reenviar los datos de pago",
        20,
        [
          "cual es la cuenta",
          "a que numero",
          "a que cuenta",
          "no veo los datos",
          "perdi los datos",
          "mandame los datos",
          "manda los datos",
          "repite los datos",
          "los datos otra vez",
          "donde pago",
        ],
        // El motor reenvía los del método que YA eligió, con su frase y sin
        // volver a presentar la venta. Nunca los escribe el modelo.
        "resend_payment",
        "",
        ["payment_done"]
      ),
      rule(
        "ahorro_lineal_pago_monto",
        "Respuesta rápida: cuánto tengo que pagar",
        30,
        [
          "cuanto era",
          "cuanto tengo que pagar",
          "cuanto le pongo",
          "cuanto deposito",
          "cual es el monto",
          "cuanto es el monto",
          "monto exacto",
        ],
        "send_text",
        "El monto es *{{PRECIO_COMPLETO}}* 😊",
        ["payment_done"]
      ),
      // LA PREGUNTA QUE SE HACE EN TODAS LAS VENTAS: «¿a qué hora me llega?».
      rule(
        "ahorro_lineal_pago_entrega",
        "Respuesta rápida: cuándo lo recibo",
        40,
        [
          "a que hora me llega",
          "a que hora me entregan",
          "a que hora me manda",
          "cuando me llega",
          "cuando lo recibo",
          "cuanto demora",
          "cuanto tarda",
          "en cuanto tiempo me llega",
        ],
        "send_text",
        "En cuanto me envíes la foto de tu comprobante 🤳 lo reviso y te llega tu acceso *al instante* 😊",
        ["payment_done"]
      ),
      // DICE QUE PAGÓ, PERO SIN FOTO. Con foto no llega hasta aquí: el motor la
      // manda derecha al lector antes que a ninguna regla.
      rule(
        "ahorro_lineal_pago_avisa",
        "Respuesta rápida: dice que ya pagó (sin foto)",
        50,
        [
          "ya pague",
          "ya hice el pago",
          "ya realice el pago",
          "ya te pase el pago",
          "ya deposite",
          "ya transferi",
          "acabo de pagar",
        ],
        "send_text",
        "¡Genial! 🙌 Envíame la *foto de tu comprobante* 🤳 y te doy tu acceso enseguida 😊",
        ["payment_done"]
      ),
    ];
  }

  if (modality === "order_bump") {
    return [
      rule(
        "ahorro_order_bump_saludo",
        "Respuesta rápida: saludo",
        90,
        ["hola", "buenas", "buenos dias", "buenas tardes", "buenas noches"],
        "send_text",
        "¡Hola! 😊 ¿Deseas conocer las opciones disponibles o tienes una duda puntual?"
      ),
      rule(
        "ahorro_order_bump_agradecimiento",
        "Respuesta rápida: agradecimiento",
        95,
        ["gracias", "muchas gracias", "gracias por la informacion"],
        "send_text",
        "Con gusto 😊 ¿Hay alguna duda puntual que quieras resolver antes de elegir?"
      ),
    ];
  }

  return [
    rule(
      `ahorro_${modality}_saludo`,
      "Respuesta rápida: saludo",
      90,
      ["hola", "buenas", "buenos dias", "buenas tardes", "buenas noches"],
      "send_text",
      "¡Hola! 😊 ¿Qué información te gustaría conocer?"
    ),
  ];
}

function normalizeChannelContent(
  content: ChannelContentEditor | undefined
): ChannelContentEditor {
  const base = content ?? emptyChannelContent();
  const groups = base.intro_groups?.length ? base.intro_groups : emptyChannelContent().intro_groups;
  const normalizedGroups = groups.map((group) => {
    // AQUÍ SE RENOMBRABAN SOLOS CUATRO NOMBRES, Y SE RETIRA ENTERO.
    //
    // La regla decía: si el nombre está VACÍO, o es exactamente «Intro», o
    // «Saludo inicial», o «Intro Messenger/Instagram», ponle «Intro» y su
    // posición. Se hizo para borrar el rastro de un mensaje suelto que ya no
    // existe, pero no corría UNA vez para migrar: corre en cada pintada.
    //
    // Resultado: esos cuatro nombres quedaron prohibidos para siempre, y sobre
    // todo el vacío. Borrabas el título entero y reaparecía «Intro 3» solo.
    // Borrabas hasta dejar «Intro» y también. Era imposible quitarle el nombre a
    // un cajón, y no había nada en pantalla que lo explicara.
    //
    // Ahora un cajón sin nombre se queda sin nombre, y lo dice en rojo en su
    // barra: «Ponle un título al cajón». Ver `tituloDeRelleno`.
    return {
      ...group,
      enabled: group.enabled ?? true,
      weight:
        typeof group.weight === "number" && group.weight > 0 ? group.weight : 1,
      adName: group.adName ?? "",
      adId: group.adId ?? "",
      skipAskName: group.skipAskName === true,
      steps: (group.steps?.length ? group.steps : [emptyStep()]).map((step) => ({
        ...step,
        delay_after_sec:
          typeof step.delay_after_sec === "number" ? step.delay_after_sec : 6,
      })),
    };
  });

  return {
    ...base,
    intro_groups: normalizedGroups,
    followups: base.followups ?? [],
    payment: base.payment?.length ? base.payment : [emptyStep()],
    delivery: base.delivery?.length ? base.delivery : [emptyStep()],
    delivery_groups: base.delivery_groups?.length
      ? base.delivery_groups
      : emptyChannelContent().delivery_groups,
    post_sale:
      base.post_sale ??
      emptyChannelContent().post_sale,
  };
}

function channelContentForMode(
  cfg: FullConfig,
  channel: ChannelKey,
  mode: Modo
): ChannelContentEditor {
  return normalizeChannelContent(cfg.channels?.[channel]?.modality_templates?.[mode]);
}

function hasChannelContent(content: ChannelContentEditor): boolean {
  const hasSteps = (steps: EditorStep[] | undefined) =>
    (steps ?? []).some(
      (step) =>
        step.drive_url.trim() ||
        step.texts.some((text) => text.trim().length > 0)
    );
  return (
    content.intro_groups.some((group) => hasSteps(group.steps)) ||
    content.followups.some(
      (followup) =>
        hasSteps(followup.steps) ||
        (followup.variants ?? []).some((variant) => hasSteps(variant.steps))
    ) ||
    // El pago NO cuenta: el motor nunca lo lee, así que un canal que solo
    // tenga eso escrito no tiene contenido — diría que sí y al clonar pediría
    // confirmación para reemplazar algo que no se envía nunca.
    hasSteps(content.delivery) ||
    (content.delivery_groups ?? []).some((group) => hasSteps(group.steps)) ||
    Object.values(content.post_sale ?? {}).some(
      (value) => typeof value === "string" && value.trim().length > 0
    )
  );
}

/**
 * LAS PIEZAS DEL TEMA.
 *
 * Se prueban EN CANALES y en ningún sitio más. Esa pestaña es la única cuyas
 * piezas son suyas —sus barras son botones propios, no el cajón compartido de
 * la casa—, así que se puede cambiar entera sin que se mueva una sola pantalla
 * de las demás. Si el estilo gusta, el resto es usar estas.
 *
 * DE DÓNDE SALE. Esquinas generosas, tarjeta que flota sobre un suelo más
 * apagado, un cuadrado de color con un icono al lado de cada título, y arriba
 * un rótulo pequeño en mayúsculas que dice de qué es la pantalla.
 *
 * SIRVEN PARA LOS DOS TEMAS. Los colores de fondo, borde y tinta salen de
 * `globals.css` con nombres de función —`bg-tarjeta`, `text-tinta-suave`—, así
 * que estas piezas no saben si están en claro o en oscuro y no hay que
 * escribirlas dos veces.
 *
 * LOS COLORES DE MARCA SÍ SON FIJOS. El verde de WhatsApp es verde en los dos
 * temas: son señales, no decoración, y cambiarlos rompería el reconocimiento.
 *
 * SE CONSTRUYE UNA VEZ. Copiar estos aspectos a mano en cada sitio es lo que
 * hace que a los dos meses cada pantalla se parezca un poco menos a la de al
 * lado, y nadie sepa cuál es la buena.
 */
const TONOS_DEL_TEMA = {
  // EL VERDE DE WHATSAPP, UN PUNTO MÁS CLARO.
  //
  // Iba en el verde fuerte, que sobre el panel gris se leía apagado: el
  // cuadrado pesaba más que el nombre que tiene al lado. Este es el mismo
  // verde, más vivo, y las letras blancas de dentro siguen leyéndose.
  esmeralda: { ficha: "bg-emerald-400 text-white", rotulo: "text-emerald-600", anillo: "ring-emerald-400" },
  cielo: { ficha: "bg-sky-500 text-white", rotulo: "text-sky-600", anillo: "ring-sky-400" },
  fucsia: {
    ficha: "bg-gradient-to-br from-fuchsia-500 via-rose-500 to-amber-400 text-white",
    rotulo: "text-fuchsia-600",
    anillo: "ring-fuchsia-400",
  },
  pizarra: { ficha: "bg-slate-700 text-white", rotulo: "text-tinta-suave", anillo: "ring-slate-400" },
  // EN CLARO SE TIÑE; EN OSCURO SE RELLENA. Es la misma regla de la ficha
  // activa del menú lateral, y por la misma razón.
  //
  // LO QUE PASABA. El cuadrado iba relleno de violeta en los dos temas, y
  // dentro lleva un EMOJI. Un emoji no obedece a `text-white`: es un dibujo a
  // todo color, y los hay oscuros. Emoji oscuro sobre bloque oscuro es un
  // cuadrado morado con una mancha dentro — no se distingue de qué es.
  //
  // Sobre fondo oscuro el bloque no molesta: se apoya en la oscuridad y el
  // emoji se lee. Así que solo cambia el tema claro, donde ahora el color va
  // en el tinte y en el perfil, y el emoji queda sobre casi blanco.
  violeta: {
    ficha:
      "bg-acento-suave text-acento ring-1 ring-inset ring-acento/25 oscuro:bg-acento oscuro:text-white oscuro:ring-0",
    rotulo: "text-acento",
    anillo: "ring-acento",
  },
} as const;
type TonoDelTema = keyof typeof TONOS_DEL_TEMA;

/**
 * LOS COLORES DE LAS FILAS.
 *
 * CADA FILA EL SUYO, NO TODAS EL DE LA PESTAÑA. Con un solo color por pestaña,
 * ocho filas seguidas salían idénticas y el cuadrado dejaba de servir para
 * distinguirlas: había que leer los ocho títulos para encontrar uno. Con un
 * color por fila, el sitio al que se vuelve se reconoce de lejos.
 *
 * Y SIEMPRE EL MISMO. El color sale del nombre de la fila, así que es el mismo
 * hoy y mañana: se aprende dónde está cada cosa por el color. Si fuera al azar
 * o por posición, movería un cajón y todo cambiaría de sitio en la cabeza.
 *
 * NO SON LOS DE `TONOS_DEL_TEMA`. Aquéllos son colores con SIGNIFICADO —el
 * verde de WhatsApp, el fucsia de Instagram— y no se pueden repartir a voleo.
 * Éstos son solo para distinguir, y por eso van en su propia lista.
 *
 * TINTE MEDIO, NO BLOQUE SATURADO. Dentro va un emoji, que es un dibujo a todo
 * color y no obedece a «letra blanca»: los hay oscuros, y sobre un bloque
 * saturado se convierten en una mancha. A este tono se leen todos.
 */
const TONOS_DE_FILA = [
  "bg-emerald-200 text-emerald-900",
  "bg-amber-200 text-amber-900",
  "bg-sky-200 text-sky-900",
  "bg-rose-200 text-rose-900",
  "bg-violet-200 text-violet-900",
  "bg-lime-200 text-lime-900",
  "bg-orange-200 text-orange-900",
  "bg-cyan-200 text-cyan-900",
  "bg-fuchsia-200 text-fuchsia-900",
  "bg-yellow-200 text-yellow-900",
] as const;

/**
 * LOS QUE NO SE DEJAN AL AZAR.
 *
 * El reparto automático sirve para las decenas de cajones que no significan
 * nada en particular. Pero hay nombres que SÍ tienen un color esperado, y ahí
 * el azar acierta o no:
 *
 *   el producto básico es celeste, el full verde, el del upsell melón.
 *
 * Se escriben aquí, y desde aquí mandan en TODAS las pestañas donde aparezca
 * ese nombre. Un color escrito a mano en cada sitio es exactamente cómo se
 * llega a que el mismo producto salga verde en una pantalla y rosa en otra.
 *
 * SE COMPARA POR EL PRINCIPIO del nombre limpio, porque algunos cajones llevan
 * pegado detrás el nombre del producto que se esté vendiendo. «PRODUCTO BÁSICO»
 * con su cola tiene que dar el mismo celeste que «PRODUCTO BÁSICO» a secas.
 */
const COLOR_POR_NOMBRE: [string, string][] = [
  ["PRODUCTO BASICO", "bg-sky-200 text-sky-900"],
  ["OPCION 2 BASICO", "bg-sky-200 text-sky-900"],
  ["PRODUCTO FULL", "bg-emerald-200 text-emerald-900"],
  ["OPCION 1 COMBO", "bg-emerald-200 text-emerald-900"],
  ["PRODUCTO UPSELL", "bg-amber-200 text-amber-900"],
  ["UPSELL VENDER UN SEGUNDO PRODUCTO", "bg-amber-200 text-amber-900"],
  // El melón que pediste para la bolsa de dinero de Precios y pagos.
  ["PAIS MONEDA Y METODOS POR PAIS", "bg-amber-200 text-amber-900"],
  ["MENSAJES DE REGALO", "bg-violet-200 text-violet-900"],
  ["EMAIL POSTVENTA", "bg-cyan-200 text-cyan-900"],
  ["ENTREGA POSTVENTA WHATSAPP CORREO", "bg-cyan-200 text-cyan-900"],
  // ENTREGA. El reparto automático le había dado el mismo ámbar a dos filas de
  // la misma pantalla. Aquí las entregas de producto siguen la regla de arriba
  // —el full verde, el básico celeste— y las demás se separan a mano.
  ["ENTREGA PRODUCTO 1", "bg-emerald-200 text-emerald-900"],
  ["ENTREGA PRODUCTO 2", "bg-sky-200 text-sky-900"],
  ["ENTREGA PAGO APROBADO", "bg-lime-200 text-lime-900"],
  ["ENCUESTA A CLIENTE", "bg-rose-200 text-rose-900"],
  ["MENSAJE POSTVENTA", "bg-violet-200 text-violet-900"],
  // PRECIOS Y PAGOS. Igual: el ámbar de la bolsa de dinero y el naranja de
  // Venezuela eran casi el mismo color uno encima del otro.
  ["ATENCION A CONSULTAS DE VENEZUELA", "bg-sky-200 text-sky-900"],
  ["TEXTO ANTE DESCONFIANZA", "bg-rose-200 text-rose-900"],
  ["CUANDO TE VUELVE A PEDIR LOS DATOS DE PAGO", "bg-violet-200 text-violet-900"],
  // CONTENIDO. «FULL (opción conjunta)» es el mismo producto full de siempre,
  // así que el mismo verde.
  ["FULL", "bg-emerald-200 text-emerald-900"],
  ["INFO DE CONTENIDO", "bg-orange-200 text-orange-900"],
  ["CIERRE DESPUES DE LAS MUESTRAS", "bg-rose-200 text-rose-900"],
];

/**
 * EL MISMO NOMBRE, EL MISMO COLOR, ESTÉ DONDE ESTÉ.
 *
 * «PRODUCTO FULL» sale en Contenido, en Las 2 opciones, en Order Bump y en
 * Entrega. Es el mismo producto en las cuatro, así que tiene que ser el mismo
 * color en las cuatro: si en una es verde y en otra rosa, el color deja de
 * decir «esto es lo mismo» y pasa a estorbar.
 *
 * Por eso el color sale del NOMBRE QUE SE LEE, no de la llave interna —que es
 * distinta en cada pestaña— ni de la posición.
 *
 * SE LIMPIA ANTES DE MIRARLO, porque el mismo producto no está escrito igual en
 * todas partes: «PRODUCTO FULL» en una y «PRODUCTO FULL (el de mayor precio)»
 * en otra. Se quita lo que va entre paréntesis, los acentos, las mayúsculas y
 * los espacios de sobra, y las dos acaban siendo lo mismo.
 */
function nombreParaElColor(titulo: string): string {
  return titulo
    .replace(EMOJI_AL_PRINCIPIO, "")
    .replace(/\([^)]*\)/g, "")
    .normalize("NFD")
    .replace(/\p{Diacritic}/gu, "")
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, " ")
    .trim();
}

/**
 * El color de una fila a partir de su nombre limpio.
 *
 * Es una suma de letras, no un sorteo: dos filas distintas pueden coincidir en
 * color y no pasa nada —el color agrupa por parecido, no identifica—, pero
 * ninguna cambia de color sola.
 */
function tonoDeFila(titulo: string): string {
  const clave = nombreParaElColor(titulo);
  // Los escritos a mano mandan. Ver `COLOR_POR_NOMBRE`.
  for (const [nombre, color] of COLOR_POR_NOMBRE) {
    if (clave.startsWith(nombre)) return color;
  }
  let suma = 0;
  for (let i = 0; i < clave.length; i += 1) {
    suma = (suma * 31 + clave.charCodeAt(i)) >>> 0;
  }
  return TONOS_DE_FILA[suma % TONOS_DE_FILA.length];
}

/* EL BOTÓN DE CLARO / OSCURO SE MUDÓ.
 *
 * Vive en `src/components/InterruptorDeTema.tsx` y se importa arriba. Estaba
 * escrito aquí dentro, y por eso el tema solo se podía cambiar desde el editor:
 * el chat y el tablero se quedaban con lo último elegido en otra pantalla. Es
 * el mismo botón y la misma llave de guardado, solo que ahora lo pueden usar
 * las demás pantallas. */

/** Un texto archivado del contenido de un cajón. Ver `SelectorDeVersiones`. */
type VersionDeIntro = {
  id: string;
  name?: string;
  lugar?: "order_bump" | "upsell";
  /**
   * LA QUE MANDABA. Ya no se marca ninguna: al cargar, la que estuviera activa
   * baja al cajón 1 y se desmarca — ver la migración en la carga. El campo se
   * queda en el tipo porque `aplicarVersionActiva` (config.ts) lo sigue
   * respetando: así, entre que él abre el editor y guarda, el bot no cambia de
   * texto. Cuando guarde, no habrá ninguna activa y mandarán los cajones.
   */
  activa?: boolean;
  steps?: EditorStep[];
};

/**
 * EL SELECTOR DE VERSIONES DE UN CAJÓN.
 *
 * QUÉ RESUELVE, Y ES MÁS GORDO DE LO QUE PARECE. El cajón de la intro de la
 * oferta y el del upsell NO GUARDAN: se escribe, se pulsa Guardar, y al volver
 * está el texto anterior. Se comprobó contra el archivo real — el texto nuevo no
 * aparecía en ninguna parte. Duplicar tampoco funcionaba, por lo mismo.
 *
 * LA LIBRETA SÍ GUARDA, porque vive en la raíz del archivo y usa el mismo camino
 * que la biblioteca de productos. Así que se le da la vuelta al problema: la
 * versión elegida ES la que manda, y el cajón pasa a ser su reflejo.
 *
 * CON UNA VERSIÓN ELEGIDA, LO QUE ESCRIBES VA A ELLA. No hay copia que confirmar
 * ni momento en que se pueda perder: escribes y ya está guardado en la libreta,
 * que es lo que sobrevive. Y el motor la recibe por una capa — ver
 * `aplicarVersionActiva` en config.ts—, así que sigue leyendo lo mismo que antes.
 *
 * SIN NINGUNA ELEGIDA TODO SIGUE COMO SIEMPRE, con el fallo incluido. Por eso se
 * avisa en la barra: es la situación en la que lo escrito puede perderse.
 *
 * SOLO GUARDA LAS BURBUJAS. La elección con botones que se ve debajo es UNA para
 * toda la sección: si entrara en la versión, cambiar de versión te cambiaría la
 * pregunta sin avisar.
 *
 * Y LA LIBRETA TAMPOCO LLEGA AL ARCHIVO SOLA: hace falta el botón Guardar de
 * arriba, igual que todo lo demás. Nada se publica sin que el operador lo diga.
 */
function SelectorDeVersiones({
  lugar,
  steps,
  onCargarComoCajon,
  biblioteca,
  onBiblioteca,
  snapshot,
  editSnapshot,
}: {
  lugar: "order_bump" | "upsell";
  /** Lo que hay en el primer cajón, que es lo que se archiva al guardar. */
  steps: EditorStep[];
  /** Trae un texto guardado como un cajón MÁS, sin tocar los que ya hay. */
  onCargarComoCajon: (version: VersionDeIntro) => void;
  biblioteca: VersionDeIntro[];
  onBiblioteca: (siguiente: VersionDeIntro[]) => void;
  snapshot: () => void;
  editSnapshot: (clave: string) => void;
}) {
  const mias = biblioteca.filter((v) => (v.lugar ?? "order_bump") === lugar);
  const [elegida, setElegida] = useState<string>("");
  const suya = mias.find((v) => v.id === elegida);

  const guardarNueva = (): void => {
    const nombre = prompt(
      "¿Con qué nombre archivas lo que hay escrito en el primer cajón?"
    )?.trim();
    if (!nombre) return;
    snapshot();
    editSnapshot(`versiones_${lugar}:nueva`);
    const id = `intro_${Date.now().toString(36)}`;
    // NACE GUARDADA Y NADA MÁS. Antes nacía «activa» y pasaba a mandar sobre el
    // cajón; eso era el rodeo de cuando el cajón no guardaba. Hoy el cajón
    // guarda, así que archivar tiene que ser inofensivo.
    onBiblioteca([
      ...biblioteca,
      { id, name: nombre, lugar, steps: cloneJson(steps) },
    ]);
    setElegida(id);
  };

  return (
    <div className="mb-3 flex flex-wrap items-center gap-2 rounded-lg border border-borde bg-relleno px-3 py-2">
      <span className="text-xs font-bold text-tinta-suave">Archivador</span>
      <select
        value={elegida}
        onChange={(e) => {
          const destino = e.target.value;
          if (destino === "__nueva__") {
            guardarNueva();
            return;
          }
          setElegida(destino);
        }}
        className="min-w-52 rounded-md border border-borde bg-tarjeta px-2 py-1 text-sm text-tinta"
      >
        <option value="">— elige un texto guardado —</option>
        {mias.map((v) => (
          <option key={v.id} value={v.id}>
            {v.name || "Sin nombre"}
          </option>
        ))}
        <option value="__nueva__">＋ Guardar el cajón 1 aquí</option>
      </select>
      {suya && (
        <>
          {/* CARGAR TRAE UN CAJÓN MÁS; NO PISA NINGUNO.
              Antes «cargar» significaba activar, y la versión activa mandaba
              sobre todos los cajones — por eso desaparecían Duplicar, Peso y
              Quitar. Ahora entra como un cajón nuevo y apagado, y a partir de
              ahí es un cajón como cualquier otro: lo enciendes, le pones peso y
              lo duplicas. Nada de lo que ya tenías se toca. */}
          <button
            type="button"
            onClick={() => {
              snapshot();
              editSnapshot(`versiones_${lugar}:cargar`);
              onCargarComoCajon(suya);
            }}
            className="rounded border border-acento bg-tarjeta px-2 py-1 text-xs font-bold text-acento hover:bg-acento-suave"
          >
            ↓ Cargar como cajón
          </button>
          <button
            type="button"
            onClick={() => {
              const nombre = prompt(
                "Nuevo nombre para este texto guardado:",
                suya.name ?? ""
              )?.trim();
              if (!nombre) return;
              snapshot();
              editSnapshot(`versiones_${lugar}:renombrar`);
              onBiblioteca(
                biblioteca.map((v) =>
                  v.id === suya.id ? { ...v, name: nombre } : v
                )
              );
            }}
            className="rounded border border-borde bg-tarjeta px-2 py-1 text-xs font-semibold text-tinta-suave hover:bg-relleno"
          >
            Renombrar
          </button>
          <button
            type="button"
            onClick={() => {
              if (
                !confirm(
                  `¿Borrar «${suya.name || "sin nombre"}» del archivador? Se pierden sus burbujas y no hay vuelta.`
                )
              ) {
                return;
              }
              snapshot();
              editSnapshot(`versiones_${lugar}:borrar`);
              onBiblioteca(biblioteca.filter((v) => v.id !== suya.id));
              setElegida("");
            }}
            className="rounded border border-red-200 bg-tarjeta px-2 py-1 text-xs font-semibold text-red-700 hover:bg-red-50"
          >
            Borrar
          </button>
        </>
      )}
      <span className="text-[11px] text-tinta-suave">
        Solo guarda y recupera textos. Lo que se envía son los cajones de abajo.
      </span>
    </div>
  );
}

/** El cuadrado de color con el icono dentro. */
/**
 * LA LISTA DE CAJONES DE UNA INTRO.
 *
 * QUÉ RESUELVE. La intro de la oferta y la del upsell eran UNA secuencia: para
 * probar otra versión había que borrar la que había, y la anterior se perdía.
 * Las intros de la modalidad son cajones desde hace tiempo —con nombre,
 * interruptor y peso— y esto es lo mismo para las otras dos.
 *
 * EL PESO ES UN REPARTO, no una prioridad: con dos encendidos a 1 y 3, de cada
 * cuatro clientes uno ve el primero y tres el segundo. El dado lo tira el motor
 * por conversación — ver `sorteaCajonDeIntro`.
 *
 * CON UNO SOLO ENCENDIDO EL BOT HACE LO DE SIEMPRE, y sin ninguno se usa la
 * secuencia vieja. Ésa es la garantía de que esto no cambia ninguna venta por el
 * hecho de existir.
 */
function CajonesDeIntro({
  grupos: gruposDelCajon,
  onGrupos: onGruposDelCajon,
  icono,
  queEs,
  respaldo,
  snapshot,
  editSnapshot,
  claveDeEdicion,
  idPrefix,
  priceSoles,
  comboPrice,
  basicoPrice,
  previewContext,
  lugar,
  biblioteca,
  onBiblioteca,
  pie,
}: {
  grupos: GrupoDeIntroEditor[];
  onGrupos: (siguientes: GrupoDeIntroEditor[]) => void;
  icono: string;
  /** Para los textos: «la oferta», «el upsell». */
  queEs: string;
  /** La secuencia de antes de los cajones. Se ofrece traerla al primero para no
   *  obligar a reescribirla, y hasta entonces es la que envía el bot. */
  respaldo: EditorStep[];
  snapshot: () => void;
  editSnapshot: (clave: string) => void;
  claveDeEdicion: string;
  idPrefix: string;
  priceSoles?: number;
  comboPrice?: number;
  basicoPrice?: number;
  previewContext: PreviewContext;
  /** De cuál de las dos es esta lista, para la libreta de versiones. Sin él no
   *  se ofrece guardar: la libreta separa las de la oferta de las del upsell. */
  lugar?: "order_bump" | "upsell";
  biblioteca?: VersionDeIntro[];
  onBiblioteca?: (siguiente: VersionDeIntro[]) => void;
  /**
   * LO QUE VA AL FINAL DE LA VENTANA DE CADA CAJÓN.
   *
   * Es la elección con botones. Va DENTRO y no debajo de la lista porque es lo
   * que remata esas burbujas: escribiéndola fuera, al abrir el cajón se perdía de
   * vista justo la frase que acompaña a lo que estás escribiendo.
   *
   * Es UNA para toda la sección, no una por cajón. Con varios cajones se ve
   * repetida y editarla en uno la cambia en todos — es la misma, no una copia.
   */
  pie?: ReactNode;
}) {
  // EL CAJÓN MANDA SIEMPRE, COMO EN INTRO Y EN SEGUIMIENTOS.
  //
  // ANTES: con una versión de la libreta elegida, el cajón se sustituía por ella
  // —una sola, sin peso— y Peso, Duplicar y Quitar desaparecían. Y era lo
  // correcto MIENTRAS el cajón no sobrevivía al guardado: la libreta solo sabe
  // guardar UNA versión, así que una copia se habría perdido en silencio.
  //
  // Arreglada esa causa —ver el sembrado de `intro_groups` al cargar—, la
  // sustitución sobra y es justo lo que impedía duplicar. El dueño lo pidió así:
  // «que sea idéntico en comportamiento al de la sección intro / seguimiento
  // para yo elegir cuál se manda».
  //
  // La libreta se queda como ARCHIVADOR: guardar un texto y volver a cargarlo
  // cuando haga falta. Ya no manda sobre nada — cargar una versión trae un cajón
  // más, y a partir de ahí es un cajón como cualquier otro.
  const grupos = gruposDelCajon;
  const onGrupos = onGruposDelCajon;
  const parchar = (i: number, parche: Partial<GrupoDeIntroEditor>) =>
    onGrupos(grupos.map((g, j) => (j === i ? { ...g, ...parche } : g)));
  /**
   * DUPLICAR UN CAJÓN, DESDE DONDE SE PULSE.
   *
   * Estaba escrito dentro del botón de ABAJO, el que solo se ve con el cajón
   * abierto. El dueño lo pidió también en la fila cerrada el 30/09/2026: «para
   * duplicarlo como está hoy tengo que entrar dentro de la pestaña; mejor que lo
   * tenga en la fachada como sus demás botones».
   *
   * Se saca aquí para que los DOS botones ejecuten LO MISMO. Escribirlo dos
   * veces es como se acaba teniendo dos duplicados que se portan distinto.
   */
  const duplicarCajon = (i: number) => {
    // El nombre PRIMERO, y la copia se abre al aceptar. Ver `nombreParaLaCopia`.
    const nombre = nombreParaLaCopia(grupos[i]?.name);
    if (nombre === null) return;
    snapshot();
    abrirCajonDuplicado(`${idPrefix}_cajon`, i + 1, grupos.length);
    onGrupos([
      ...grupos.slice(0, i + 1),
      {
        ...cloneJson(grupos[i]),
        name: nombre,
        // La copia nace apagada: se duplica para cambiarle algo, y encendida
        // entraría al reparto antes de estar lista.
        enabled: false,
      },
      ...grupos.slice(i + 1),
    ]);
  };
  /**
   * COPIAR Y PEGAR UN CAJÓN ENTERO, CON EL CLIC DERECHO.
   *
   * Lo pidió el 10/10/2026 para los upsells: copiar el cajón de intro de un producto y
   * pegarlo en otro, «y que al pegar dé la opción de renombrar», como al duplicar. Así que
   * pegar hace LO MISMO que `duplicarCajon`: pide el nombre primero y la copia nace apagada
   * —se pega para cambiarle algo, y encendida entraría al reparto antes de estar lista—.
   *
   * Solo en las intros del upsell (las de la ficha y las de Upsell/Canales), que comparten
   * forma. La oferta de dos opciones no lo ofrece: pegar ahí una intro de upsell mezclaría
   * dos cosas distintas.
   */
  const portapapeles = useContext(PortapapelesDeCajonesDeIntro);
  const conPortapapeles = portapapeles && lugar !== "order_bump" ? portapapeles : null;
  const pegarCajon = (i: number, donde: "encima" | "debajo") => {
    const copiado = conPortapapeles?.copiado;
    if (!copiado) return;
    const nombre = nombreParaLaCopia(copiado.nombre);
    if (nombre === null) return;
    snapshot();
    const destino = donde === "encima" ? i : i + 1;
    abrirCajonDuplicado(`${idPrefix}_cajon`, destino, grupos.length);
    onGrupos([
      ...grupos.slice(0, destino),
      { ...cloneJson(copiado.grupo), name: nombre, enabled: false },
      ...grupos.slice(destino),
    ]);
  };
  const encendidos = grupos.filter((g) => g.enabled !== false).length;
  return (
    <div className="space-y-2">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <p className="text-xs text-tinta-suave">
          {grupos.length === 0 ? (
            <>
              Todavía no hay cajones. El bot manda la versión de siempre, la que
              ya tienes escrita. Crea uno para poder tener varias y repartirlas.
            </>
          ) : encendidos === 0 ? (
            <>
              Ningún cajón encendido: el bot manda la versión de siempre.
            </>
          ) : encendidos === 1 ? (
            <>Uno encendido: ése sale siempre, igual que antes.</>
          ) : (
            <>
              {encendidos} encendidos: cada cliente ve uno, repartidos por peso.
            </>
          )}
        </p>
        <button
          type="button"
          onClick={() => {
            snapshot();
            onGrupos([
              ...grupos,
              {
                name: "",
                enabled: grupos.length === 0,
                weight: 1,
                // El primero nace con lo que ya estaba escrito: así se pasa a
                // cajones sin reescribir nada y sin que el bot cambie de texto.
                steps: grupos.length === 0 && respaldo.length > 0
                  ? cloneJson(respaldo)
                  : [emptyStep()],
              },
            ]);
          }}
          className="rounded-full border border-acento bg-tarjeta px-4 py-1.5 text-xs font-bold text-acento transition-colors hover:bg-acento-suave"
        >
          + Agregar cajón
        </button>
      </div>
      {grupos.map((grupo, i) => (
        <Collapsible
          key={`${idPrefix}-cajon-${i}`}
          icono={icono}
          // EL APAGADO SE VE APAGADO, COMO EN INTRO.
          //
          // Llevaba solo `inactivo`, y eso no basta: la lista de la intro
          // además le antepone «OFF - » al título y le pinta la barra en gris.
          // El dueño lo vio el 15 de septiembre de 2026 — apagó un cajón y
          // siguió igual de verde que el encendido, así que no había forma de
          // saber cuál estaba mandando sin abrirlos.
          // LA BANDERA YA NO VA PEGADA AL NOMBRE.
          //
          // LO PIDIÓ EL DUEÑO el 02/10/2026: ahora la elige en una pastilla propia, a la
          // izquierda de la de semimodalidad, «y con esto la bandera ya no saldría al
          // lado izquierdo del nombre». Tenerla en los dos sitios la repetía y partía el
          // título en dos líneas — se ve en su propia captura.
          title={`${grupo.enabled === false ? "OFF - " : ""}${
            grupo.name || "Ponle un título al cajón"
          }`}
          tituloDeRelleno={!grupo.name?.trim()}
          titleKey={`${idPrefix}_cajon_${i}`}
          inactivo={grupo.enabled === false}
          onCopiarCajon={
            conPortapapeles
              ? () =>
                  conPortapapeles.copiar({
                    nombre: grupo.name?.trim() || `Cajón ${i + 1}`,
                    grupo: cloneJson(grupo),
                  })
              : undefined
          }
          onPegarCajonEncima={
            conPortapapeles?.copiado ? () => pegarCajon(i, "encima") : undefined
          }
          onPegarCajonDebajo={
            conPortapapeles?.copiado ? () => pegarCajon(i, "debajo") : undefined
          }
          etiquetaCajonCopiado={
            conPortapapeles?.copiado ? `«${conPortapapeles.copiado.nombre}»` : undefined
          }
          // Y LA FACHADA EN ROJO SI LE FALTA LA BANDERA. Ver `leFaltaLaBandera`.
          titleClassName={bordeSinBandera(
            leFaltaLaBandera({
              paises: grupo.paises,
              routingEnabled: grupo.pais_routing_enabled,
              apagada: grupo.enabled === false,
            }),
            grupo.enabled === false
              ? "border-neutral-500 bg-neutral-300 text-neutral-900"
              : undefined
          )}
          bodyClassName={
            grupo.enabled === false ? "bg-neutral-300" : undefined
          }
          enVentana
          onDragOver={(e) => {
            e.preventDefault();
          }}
          onDrop={(e) => {
            e.preventDefault();
            const crudo = e.dataTransfer.getData("text/plain");
            const [clase, deDonde, indice] = crudo.split(":");
            if (clase !== "cajon" || deDonde !== idPrefix) return;
            const desde = Number(indice);
            if (!Number.isFinite(desde) || desde === i) return;
            snapshot();
            keepMovedCollapsibleOpen(`${idPrefix}_cajon`, desde, i, grupos.length);
            onGrupos(moveItem(grupos, desde, i));
          }}
          headerActions={
            <>
              {/* LA BANDERA, A LA IZQUIERDA DE LA SEMIMODALIDAD.
                  LO PIDIÓ EL DUEÑO el 02/10/2026, con ese orden exacto: «al lado de
                  lineal a su izquierda esté el selector de banderas». Y con el nombre
                  solo al desplegar, «para evitar agrandar el espacio». */}
              <PastillaDePais
                seleccionados={grupo.paises ?? []}
                onCambiar={(siguientes) => {
                  editSnapshot(`${claveDeEdicion}${i}:paises`);
                  parchar(i, { paises: siguientes });
                }}
              />
              <AvisoSinBandera
                visible={leFaltaLaBandera({
                  paises: grupo.paises,
                  routingEnabled: grupo.pais_routing_enabled,
                  apagada: grupo.enabled === false,
                })}
              />
              {/* LA ETIQUETA VA DELANTE DEL PUNTO, como en su boceto: primero se
                  lee para QUÉ forma de vender es, y luego si está encendida. */}
              <PastillaDeSemimodalidad
                valor={grupo.semimodalidad}
                onCambiar={(siguiente) => {
                  editSnapshot(`${claveDeEdicion}${i}:semimodalidad`);
                  parchar(i, { semimodalidad: siguiente });
                }}
              />
              <PastillaDeTiendas
                valor={grupo.tiendas}
                onCambiar={(siguiente) => {
                  editSnapshot(`${claveDeEdicion}${i}:tiendas`);
                  parchar(i, { tiendas: siguiente });
                }}
              />
              <CirculoDeEncendido
                encendido={grupo.enabled !== false}
                queEs={`este cajón de ${queEs}`}
                onCambiar={() => {
                  editSnapshot(`${claveDeEdicion}${i}:enabled`);
                  parchar(i, { enabled: grupo.enabled === false });
                }}
              />
              {/* SUBIR, BAJAR, MOVER Y LA PAPELERA, COMO EN INTRO.
                  El dueño los pidió el 15 de septiembre de 2026 para probar la
                  experiencia unos días antes de decidir si unifica las dos
                  pantallas o se queda con ésta. Son los MISMOS botones y los
                  mismos textos que los de la lista de la intro — si algún día se
                  unifican, no habrá que reaprender nada.
                  La papelera va la última y sin palabra: lo que borra no se pone
                  al lado de lo que se pulsa a menudo. */}
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  if (i === 0) return;
                  snapshot();
                  keepMovedCollapsibleOpen(`${idPrefix}_cajon`, i, i - 1, grupos.length);
                  onGrupos(moveItem(grupos, i, i - 1));
                }}
                disabled={i === 0}
                title="Subir este cajón"
                aria-label="Subir este cajón"
                className="rounded border border-sky-200 bg-sky-50 px-2 py-1 text-xs font-bold text-sky-700 hover:bg-sky-100 disabled:opacity-30"
              >
                ↑
              </button>
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  if (i === grupos.length - 1) return;
                  snapshot();
                  keepMovedCollapsibleOpen(`${idPrefix}_cajon`, i, i + 1, grupos.length);
                  onGrupos(moveItem(grupos, i, i + 1));
                }}
                disabled={i === grupos.length - 1}
                title="Bajar este cajón"
                aria-label="Bajar este cajón"
                className="rounded border border-sky-200 bg-sky-50 px-2 py-1 text-xs font-bold text-sky-700 hover:bg-sky-100 disabled:opacity-30"
              >
                ↓
              </button>
              <button
                type="button"
                draggable
                onClick={(e) => e.stopPropagation()}
                onDragStart={(e) => {
                  e.stopPropagation();
                  e.dataTransfer.effectAllowed = "move";
                  e.dataTransfer.setData("text/plain", `cajon:${idPrefix}:${i}`);
                }}
                title="Arrastrar para moverlo de sitio"
                aria-label="Arrastrar para moverlo de sitio"
                className="cursor-grab rounded border border-sky-300 bg-tarjeta px-2 py-1 text-xs font-bold text-sky-700 active:cursor-grabbing"
              >
                ⋮⋮
              </button>
              {/* DUPLICAR, EN LA FILA CERRADA. Es el MISMO `duplicarCajon` que el
                  botón de dentro: dos sitios para pulsarlo, una sola acción. */}
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  duplicarCajon(i);
                }}
                title="Duplicar este cajón"
                aria-label="Duplicar este cajón"
                className="rounded border border-sky-200 bg-sky-50 px-2 py-1 text-xs font-bold text-sky-700 hover:bg-sky-100"
              >
                ⧉
              </button>
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  if (
                    !confirm(
                      `¿Quitar «${grupo.name?.trim() || "este cajón"}»? Se pierden sus burbujas.`
                    )
                  ) {
                    return;
                  }
                  snapshot();
                  onGrupos(grupos.filter((_, j) => j !== i));
                }}
                title="Quitar este cajón"
                aria-label="Quitar este cajón"
                className="rounded border border-red-200 bg-tarjeta px-2 py-1 text-xs text-red-600 hover:bg-red-50"
              >
                🗑️
              </button>
            </>
          }
        >
          {lugar && biblioteca && onBiblioteca && (
            <SelectorDeVersiones
              lugar={lugar}
              steps={grupo.steps ?? []}
              onCargarComoCajon={(version) =>
                onGrupos([
                  ...grupos,
                  {
                    name: version.name ?? "",
                    // Apagado, como la copia de «Duplicar»: se trae para mirarlo
                    // o retocarlo, y encendido entraría al reparto sin avisar.
                    enabled: false,
                    weight: 1,
                    steps: cloneJson(version.steps ?? [emptyStep()]),
                  },
                ])
              }
              biblioteca={biblioteca}
              onBiblioteca={onBiblioteca}
              snapshot={snapshot}
              editSnapshot={editSnapshot}
            />
          )}
          <div className="mb-3 flex flex-wrap items-center gap-2">
            <input
              value={grupo.name ?? ""}
              onChange={(e) => {
                editSnapshot(`${claveDeEdicion}${i}:name`);
                parchar(i, { name: e.target.value });
              }}
              placeholder="Nombre del cajón"
              className="min-w-48 rounded-md border border-borde bg-tarjeta px-2 py-1 text-sm"
            />
            {/* EL PESO, DUPLICAR Y QUITAR SON DEL REPARTO ENTRE CAJONES, y aquí
                estaban escondidos mientras hubiera una versión de la libreta
                elegida. Esa era LA razón de que en Upsell no se pudiera
                duplicar. Ya no se esconden: el cajón manda siempre y la libreta
                es un archivador. */}
            <label className="flex items-center gap-2 rounded-md border border-borde bg-tarjeta px-2 py-1 text-xs text-tinta-suave">
              <span className="font-medium">Peso</span>
              <DraftNumberInput
                min={1}
                value={grupo.weight ?? 1}
                onValueChange={(v) => {
                  editSnapshot(`${claveDeEdicion}${i}:weight`);
                  parchar(i, { weight: Math.max(1, Math.floor(v || 1)) });
                }}
                className="w-16 rounded border border-borde px-2 py-1 text-right text-xs font-semibold"
              />
            </label>
            <button
              type="button"
              onClick={() => duplicarCajon(i)}
              className="rounded border border-borde bg-tarjeta px-2 py-1 text-xs text-tinta-suave hover:bg-relleno"
            >
              ⧉ Duplicar
            </button>
            {/* EL «QUITAR» SE FUE A LA CABECERA, COMO PAPELERA, igual que en la
                lista de la intro. Tenerlo aquí dentro obligaba a abrir el cajón
                para borrarlo y dejaba dos sitios distintos para lo mismo. */}
          </div>
          {/* LA BANDERA TAMBIÉN AQUÍ. Lo vio el dueño en su prueba del 24/09:
              «no le has puesto en la intro del OB; cuando yo cambio a COMO ob,
              aquí también debería haber ese selector». Y tenía razón: estos
              cajones son los de la intro de la oferta y los del upsell, que el
              motor ya sabe dirigir por país — faltaba dónde ponerle la bandera.
              Aquí no hay caja de anuncios, así que país ocupa la fila entera. */}
          <FilaDeEtiquetas>
            <BanderaTagPicker
              seleccionados={grupo.paises ?? []}
              routingEnabled={grupo.pais_routing_enabled}
              onRoutingEnabledChange={(pais_routing_enabled) => {
                editSnapshot(`${claveDeEdicion}${i}:pais_routing`);
                parchar(i, { pais_routing_enabled });
              }}
              onChange={(paises) => {
                editSnapshot(`${claveDeEdicion}${i}:paises`);
                parchar(i, { paises });
              }}
            />
          </FilaDeEtiquetas>
          <StepEditorPreviewPair
            steps={grupo.steps ?? []}
            onChange={(steps) => {
              editSnapshot(`${claveDeEdicion}${i}:steps`);
              parchar(i, { steps });
            }}
            onSnapshot={snapshot}
            onEdit={editSnapshot}
            idPrefix={`${idPrefix}_${i}`}
            priceSoles={priceSoles}
            comboPrice={comboPrice}
            basicoPrice={basicoPrice}
            previewContext={previewContext}
          />
          {pie}
        </Collapsible>
      ))}
    </div>
  );
}

function FichaDeIcono({
  tono,
  clase,
  tamano = "md",
  children,
}: {
  tono: TonoDelTema;
  /** El color a pelo, cuando no sale de la lista de tonos con significado.
   *  Lo usan las filas, que llevan uno por fila. Ver `TONOS_DE_FILA`. */
  clase?: string;
  /** `lg` es el de las filas y las cabeceras: es la guía de color que se busca
   *  con el ojo antes de leer nada. */
  tamano?: "md" | "lg";
  children: ReactNode;
}) {
  // UN DIBUJO DE VARIOS EMOJIS NO CABE AL MISMO TAMAÑO QUE UNO.
  //
  // «Las 2 opciones» lleva dos libros y un más, tres dibujos dentro del mismo
  // cuadrado. Al tamaño de un emoji suelto se salen por los lados. Se mide en
  // PUNTOS DE CÓDIGO, no en letras: un emoji ocupa dos o más posiciones y
  // contando letras cualquiera daría «largo».
  const cuantosDibujos =
    typeof children === "string" ? [...children].length : 1;
  const apretado = cuantosDibujos > 2;
  return (
    <span
      aria-hidden
      className={`flex shrink-0 items-center justify-center rounded-2xl font-black shadow-sm ${
        tamano === "lg"
          ? apretado
            ? "h-12 w-12 text-[11px] leading-none"
            : "h-12 w-12 text-xl"
          : apretado
            ? "h-9 w-9 text-[8px] leading-none"
            : "h-9 w-9 text-sm"
      } ${clase ?? TONOS_DEL_TEMA[tono].ficha}`}
    >
      {children}
    </span>
  );
}

/** El rótulo pequeño, el título grande y la frase de debajo. */
function CabeceraDeSeccion({
  rotulo,
  titulo,
  subtitulo,
  tono = "violeta",
  icono,
  acciones,
}: {
  rotulo: string;
  titulo: string;
  subtitulo?: string;
  tono?: TonoDelTema;
  icono?: ReactNode;
  acciones?: ReactNode;
}) {
  return (
    <div className="flex flex-wrap items-start justify-between gap-4">
      <div className="flex min-w-0 items-center gap-3">
        {icono && (
          <FichaDeIcono tono={tono} tamano="lg">
            {icono}
          </FichaDeIcono>
        )}
        <div className="min-w-0">
          <p
            className={`text-[11px] font-extrabold uppercase tracking-[0.16em] ${TONOS_DEL_TEMA[tono].rotulo}`}
          >
            {rotulo}
          </p>
          {/* EL TÍTULO, CON LA LETRA DE TITULAR Y APRETADO.
              Con la letra del sistema en negrita salía ancho y blando, y un
              título que no pesa no ordena la pantalla. */}
          <h2 className="font-titulo text-[28px] font-extrabold leading-tight tracking-tight text-tinta">
            {titulo}
          </h2>
          {subtitulo && (
            <p className="mt-0.5 max-w-3xl text-sm text-tinta-suave">
              {subtitulo}
            </p>
          )}
        </div>
      </div>
      {acciones && (
        <div className="flex flex-wrap items-center gap-2">{acciones}</div>
      )}
    </div>
  );
}

/** La tarjeta de esquinas generosas que flota sobre el suelo. */
function TarjetaSuave({
  className,
  children,
}: {
  className?: string;
  children: ReactNode;
}) {
  return (
    <div
      className={`rounded-2xl border border-borde bg-tarjeta p-5 shadow-sm ${
        className ?? ""
      }`}
    >
      {children}
    </div>
  );
}

/**
 * UNA FILA: CUADRADO DE COLOR, NOMBRE, FRASE Y CHAPA.
 *
 * Es la forma de la referencia, y es la que tienen que tener las barras que
 * abren una ventana. El cuadrado de color va primero y grande a propósito: es
 * la guía que el ojo busca antes de leer nada, así que dos filas distintas se
 * distinguen sin leerlas.
 */
function FilaDeSeccion({
  tono,
  icono,
  titulo,
  detalle,
  chapa = "Abrir",
  activo,
  onCambiarActivo,
  onAbrir,
}: {
  tono: TonoDelTema;
  icono: ReactNode;
  titulo: string;
  detalle: string;
  chapa?: string;
  /** El punto verde con la palabra «Activo». Solo lo llevan las filas de algo
   *  que se puede apagar: la oferta y el upsell. */
  activo?: boolean;
  /** Y lo enciende. Va por el MISMO camino que el interruptor de su pestaña, no
   *  por uno paralelo: dos formas de encender lo mismo acaban haciendo cosas
   *  distintas y no habría manera de saber cuál mandó. */
  onCambiarActivo?: (encendido: boolean) => void;
  onAbrir: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onAbrir}
      className="group flex w-full items-center gap-4 rounded-2xl border border-borde bg-tarjeta px-5 py-4 text-left shadow-sm transition-all hover:-translate-y-0.5 hover:shadow-md"
    >
      <FichaDeIcono tono={tono} tamano="lg">
        {icono}
      </FichaDeIcono>
      <span className="min-w-0 flex-1">
        <span className="font-titulo block text-base font-extrabold tracking-tight text-tinta">
          {titulo}
        </span>
        <span className="mt-0.5 block text-xs leading-snug text-tinta-suave">
          {detalle}
        </span>
      </span>
      {activo !== undefined && (
        // EL PUNTO VA DENTRO DE LA FILA, QUE ES UN BOTÓN.
        //
        // Un botón dentro de otro no vale en HTML, así que esto es un span que
        // atiende el clic y CORTA la propagación: encender no puede abrir
        // también la ventana. Por eso lleva su papel y su tecla.
        <span
          role="button"
          tabIndex={0}
          aria-pressed={activo}
          title={
            activo
              ? "Activo. Toca para apagarlo. Es el mismo interruptor de su pestaña"
              : "Apagado. Toca para encenderlo. Es el mismo interruptor de su pestaña"
          }
          onClick={(evento) => {
            evento.stopPropagation();
            onCambiarActivo?.(!activo);
          }}
          onKeyDown={(evento) => {
            if (evento.key !== "Enter" && evento.key !== " ") return;
            evento.preventDefault();
            evento.stopPropagation();
            onCambiarActivo?.(!activo);
          }}
          className="flex shrink-0 items-center gap-2 rounded-full px-2 py-1 hover:bg-relleno"
        >
          <span
            aria-hidden
            className={`h-3.5 w-3.5 rounded-full border ${
              activo
                ? "border-emerald-600 bg-emerald-400"
                : "border-neutral-500 bg-neutral-400"
            }`}
          />
          <span
            className={`text-xs font-bold ${
              activo ? "text-emerald-600" : "text-tinta-suave"
            }`}
          >
            {activo ? "Activo" : "Apagado"}
          </span>
        </span>
      )}
      <span className="shrink-0 rounded-full bg-relleno px-4 py-1.5 text-xs font-bold text-tinta-suave transition-colors group-hover:bg-acento-suave group-hover:text-acento oscuro:group-hover:bg-acento oscuro:group-hover:text-white">
        {chapa}
      </span>
    </button>
  );
}

function ChannelBadge({ channel }: { channel: ChannelKey }) {
  const meta = CHANNEL_PROTOTYPE_META[channel];
  const size =
    channel === "messenger" || channel === "instagram"
      ? "h-10 w-10 text-[12px]"
      : "h-9 w-9 text-[11px]";
  return (
    <span
      className={`flex ${size} shrink-0 items-center justify-center rounded-full font-black shadow-sm ${meta.badgeClass}`}
      title={meta.name}
    >
      {meta.short}
    </span>
  );
}

/**
 * Respuesta automática a los comentarios de Facebook. Nace apagada: mientras
 * el interruptor esté en off el motor ni siquiera mira esta configuración.
 *
 * Sigue el mismo patrón visual que las demás secciones del canal: etiquetas
 * `block`, `EditorEmojiTextarea` para los textos y el cajón de burbujas real
 * (StepList + ChatPreview) para lo que se le envía al cliente.
 */
function CommentAutomationCard({
  cfg,
  setCfg,
  onEdit,
  onSnapshot,
  price,
  comboPrice,
  basicoPrice,
  previewContext,
}: {
  cfg: FullConfig;
  setCfg: (next: FullConfig) => void;
  onEdit: (key: string) => void;
  onSnapshot: () => void;
  price?: number;
  comboPrice?: number;
  basicoPrice?: number;
  previewContext?: PreviewContext;
}) {
  const ca = cfg.comment_automation ?? {};
  const update = (patch: Partial<NonNullable<FullConfig["comment_automation"]>>) => {
    onEdit("comment_automation");
    setCfg({ ...cfg, comment_automation: { ...ca, ...patch } });
  };

  // La espera se guarda en segundos; en pantalla se reparte en minutos y
  // segundos. Si viniera del formato antiguo en horas, se convierte al vuelo.
  const esperaSegundos =
    typeof ca.delay_no_match_seconds === "number"
      ? ca.delay_no_match_seconds
      : Math.round((ca.delay_no_match_hours ?? 24) * 3600);
  const esperaHoras = Math.floor(esperaSegundos / 3600);
  const esperaMin = Math.floor((esperaSegundos % 3600) / 60);
  const esperaSeg = esperaSegundos % 60;
  const fijarEspera = (horas: number, min: number, seg: number) =>
    update({
      delay_no_match_seconds: Math.max(
        0,
        Math.round(horas) * 3600 + Math.round(min) * 60 + Math.round(seg)
      ),
    });

  const pasos: EditorStep[] =
    ca.message_steps && ca.message_steps.length > 0
      ? ca.message_steps
      : [
          {
            type: "text" as const,
            drive_url: "",
            texts: [ca.message ?? ""],
            delay_after_sec: 0,
          },
        ];

  return (
    <div className="space-y-4">
      <p className="text-xs text-neutral-500">
        Cuando alguien comenta en una publicación de la página, el bot le
        escribe por privado. Ese privado abre el chat de Messenger y desde ahí
        la conversación sigue el flujo normal del bot.
      </p>

      <label className="flex items-center gap-3">
        <input
          type="checkbox"
          checked={ca.enabled === true}
          onChange={(e) => update({ enabled: e.target.checked })}
          className="h-5 w-5"
        />
        <span className="text-sm font-medium text-neutral-900">
          Responder a los comentarios de esta página
        </span>
      </label>

      {/* Apagada, la sección se atenúa y no se puede tocar, como el resto del
          editor. Se deja a la vista para saber qué hay configurado. */}
      <div
        className={
          ca.enabled === true
            ? "space-y-4 border-t border-neutral-200 pt-4"
            : "pointer-events-none space-y-4 border-t border-neutral-200 pt-4 opacity-40 grayscale"
        }
        aria-disabled={ca.enabled !== true}
      >
          <label className="flex flex-wrap items-center gap-3">
            <input
              type="checkbox"
              checked={ca.accept_any === true}
              onChange={(e) => update({ accept_any: e.target.checked })}
              className="h-5 w-5"
            />
            <span className="text-sm font-medium text-neutral-900">
              Responder a cualquier comentario
            </span>
          </label>
          <p className="-mt-2 text-xs text-neutral-500">
            Encendido, no se miran las palabras clave: contesta a todo el mundo.
            Usa el tope por persona de abajo o parecerá spam.
          </p>

          <label className={ca.accept_any === true ? "block opacity-40" : "block"}>
            <span className="mb-1 block text-xs font-medium text-neutral-700">
              Validación
            </span>
            <p className="mb-1 text-xs text-neutral-500">
              Palabras que disparan la respuesta al momento, separadas por coma.
              Puedes repartirlas en varios renglones. También admite una
              expresión regular.
            </p>
            <EditorEmojiTextarea
              rows={4}
              value={ca.keywords ?? ""}
              onChange={(value) => update({ keywords: value })}
              className="w-full rounded border border-neutral-300 px-3 py-2 text-sm"
            />
          </label>

          <div>
            <span className="mb-1 block text-xs font-medium text-neutral-700">
              Mensaje privado
            </span>
            <p className="mb-2 text-xs text-neutral-500">
              Se envía <strong>solo la primera burbuja de texto</strong>: Meta no
              permite más de un privado por comentario.
            </p>
            {/* El mismo componente que usan Intro, Pago y Entregas: cajon de
                burbujas a la izquierda y previsualizacion de WhatsApp a la
                derecha, con los comodines resueltos. */}
            <StepEditorPreviewPair
              steps={pasos}
              onChange={(message_steps) => update({ message_steps })}
              onSnapshot={onSnapshot}
              onEdit={onEdit}
              idPrefix="comment_automation"
              priceSoles={price}
              comboPrice={comboPrice}
              basicoPrice={basicoPrice}
              previewContext={previewContext}
            />
          </div>

          <div>
            <span className="mb-1 block text-xs font-medium text-neutral-700">
              Si NO coincide
            </span>
            <p className="mb-2 text-xs text-neutral-500">
              No se envía nada de inmediato. Esta es la espera antes de
              escribirle. En 0 no se le escribe nunca.
            </p>
            <div className="flex flex-wrap items-end gap-2">
              <label className="block">
                <span className="mb-1 block text-xs font-medium text-neutral-700">
                  Horas
                </span>
                <input
                  type="number"
                  min="0"
                  step="1"
                  value={esperaHoras}
                  onChange={(e) =>
                    fijarEspera(Number(e.target.value), esperaMin, esperaSeg)
                  }
                  className="w-24 rounded border border-neutral-300 px-3 py-2 text-sm"
                />
              </label>
              <label className="block">
                <span className="mb-1 block text-xs font-medium text-neutral-700">
                  Minutos
                </span>
                <input
                  type="number"
                  min="0"
                  max="59"
                  step="1"
                  value={esperaMin}
                  onChange={(e) =>
                    fijarEspera(esperaHoras, Number(e.target.value), esperaSeg)
                  }
                  className="w-24 rounded border border-neutral-300 px-3 py-2 text-sm"
                />
              </label>
              <label className="block">
                <span className="mb-1 block text-xs font-medium text-neutral-700">
                  Segundos
                </span>
                <input
                  type="number"
                  min="0"
                  max="59"
                  step="1"
                  value={esperaSeg}
                  onChange={(e) =>
                    fijarEspera(esperaHoras, esperaMin, Number(e.target.value))
                  }
                  className="w-24 rounded border border-neutral-300 px-3 py-2 text-sm"
                />
              </label>
              <span className="pb-3 text-xs text-neutral-500">
                {esperaSegundos === 0
                  ? "en 0 no se le escribe nunca"
                  : `total: ${esperaSegundos.toLocaleString("es-PE")} segundos`}
              </span>
            </div>
          </div>

          <label className="flex flex-wrap items-center gap-3">
            <input
              type="checkbox"
              checked={ca.repeat_enabled === true}
              onChange={(e) => update({ repeat_enabled: e.target.checked })}
              className="h-5 w-5"
            />
            <span className="text-sm font-medium text-neutral-900">
              Enviar solo si comenta
            </span>
            <input
              type="number"
              min="1"
              step="1"
              disabled={ca.repeat_enabled !== true}
              value={ca.repeat_count ?? 2}
              onChange={(e) => update({ repeat_count: Number(e.target.value) })}
              className="w-20 rounded border border-neutral-300 px-3 py-2 text-sm disabled:opacity-40"
            />
            <span className="text-sm font-medium text-neutral-900">
              veces sin coincidir
            </span>
          </label>
          <p className="-mt-2 text-xs text-neutral-500">
            Con esto encendido, quien comenta una sola vez sin coincidir no
            recibe nada; si insiste, se le escribe al cumplirse la espera.
            Comentar dos veces ya es señal de interés.
          </p>

          <label className="flex flex-wrap items-center gap-3">
            <input
              type="checkbox"
              checked={ca.to_human_enabled === true}
              onChange={(e) => update({ to_human_enabled: e.target.checked })}
              className="h-5 w-5"
            />
            <span className="text-sm font-medium text-neutral-900">
              Pasar a humano si no responde en
            </span>
            <input
              type="number"
              min="0"
              step="1"
              disabled={ca.to_human_enabled !== true}
              value={ca.to_human_hours ?? 24}
              onChange={(e) => update({ to_human_hours: Number(e.target.value) })}
              className="w-20 rounded border border-neutral-300 px-3 py-2 text-sm disabled:opacity-40"
            />
            <span className="text-sm font-medium text-neutral-900">horas</span>
          </label>
          <p className="-mt-2 text-xs text-neutral-500">
            Apagado, el bot no hace nada al vencer el plazo. Ojo: si la persona
            nunca contestó, Messenger no crea el chat, así que no hay
            conversación que pasar a humano — solo queda anotado.
          </p>

          <label className="flex flex-wrap items-center gap-3">
            <span className="text-sm font-medium text-neutral-900">
              No volver a escribir a la misma persona en
            </span>
            <input
              type="number"
              min="0"
              step="1"
              value={ca.one_per_person_hours ?? 0}
              onChange={(e) =>
                update({ one_per_person_hours: Number(e.target.value) })
              }
              className="w-20 rounded border border-neutral-300 px-3 py-2 text-sm"
            />
            <span className="text-sm font-medium text-neutral-900">horas</span>
          </label>
          <p className="-mt-2 text-xs text-neutral-500">
            Sin esto se envía un privado por comentario: quien comenta cinco
            veces recibe cinco mensajes. En 0 no hay tope.
          </p>

          <label className="flex flex-wrap items-center gap-3">
            <input
              type="checkbox"
              checked={ca.skip_after_ignored_enabled === true}
              onChange={(e) =>
                update({ skip_after_ignored_enabled: e.target.checked })
              }
              className="h-5 w-5"
            />
            <span className="text-sm font-medium text-neutral-900">
              No insistir a quien ya ignoró
            </span>
            <input
              type="number"
              min="1"
              step="1"
              disabled={ca.skip_after_ignored_enabled !== true}
              value={ca.skip_after_ignored ?? 1}
              onChange={(e) =>
                update({ skip_after_ignored: Number(e.target.value) })
              }
              className="w-20 rounded border border-neutral-300 px-3 py-2 text-sm disabled:opacity-40"
            />
            <span className="text-sm font-medium text-neutral-900">
              privado(s)
            </span>
          </label>
          <p className="-mt-2 text-xs text-neutral-500">
            Meta no avisa si alguien borra el chat, pero el silencio vale igual:
            si no contestó, no se le vuelve a escribir aunque comente otra vez.
          </p>

          <p className="text-xs text-neutral-500">
            Meta solo permite UNA respuesta privada por comentario y dentro de
            los 7 días. El bot nunca insiste sobre el mismo comentario.
          </p>
      </div>
    </div>
  );
}

function ChannelsPrototypeTab({
  cfg,
  setCfg,
  canalAbierto,
  onAbrirCanal,
  onSnapshot,
  onEdit,
  onModalidadOrderBump,
}: {
  cfg: FullConfig;
  setCfg: (cfg: FullConfig) => void;
  /** Enciende o apaga la MODALIDAD Order Bump. Llega de fuera porque cambiar de
   *  modalidad guarda y recarga, y eso vive en la página, no aquí. Es el mismo
   *  camino que el selector de arriba: dos caminos para lo mismo acaban
   *  discrepando. */
  onModalidadOrderBump: (encendida: boolean) => void;
  /**
   * UN CANAL A LA VEZ.
   *
   * Estaban los cuatro pintados uno debajo de otro, y las tarjetas de arriba
   * solo desplazaban la pantalla. Cada canal trae su intro, sus seguimientos,
   * su entrega y sus anuncios, así que la página eran cuatro editores completos
   * encadenados: para llegar a TikTok había que pasar por delante de todo lo
   * demás, y era fácil escribir en el canal de al lado sin darse cuenta.
   *
   * VIVE FUERA DE ESTA PESTAÑA A PROPÓSITO. El visor del recorrido salta al
   * editor de un canal concreto, y si el estado viviera aquí dentro el salto
   * aterrizaría en una ficha que no está dibujada.
   */
  canalAbierto: ChannelKey;
  onAbrirCanal: (canal: ChannelKey) => void;
  onSnapshot: () => void;
  onEdit: (key: string) => void;
}) {
  const setCanalAbierto = onAbrirCanal;
  const introGroups = activeIntroGroups(cfg);
  const mode = activeModality(cfg);
  const enabledFollowups = cfg.followups.filter((followup) => followup.enabled !== false);
  const deliveryPreviewSteps = compactSteps([
    ...(cfg.payment_approved ?? []),
    ...(cfg.customer_survey_enabled && cfg.customer_survey_message
      ? [
          {
            type: "text" as const,
            drive_url: "",
            texts: [cfg.customer_survey_message],
            delay_after_sec: 0,
          },
        ]
      : []),
  ]);
  // LA ETAPA UPSELL, DESDE LA FILA DEL CANAL.
  //
  // No cambia de modalidad: enciende o apaga la SEGUNDA VENTA de la que está
  // vendiendo. Es exactamente lo que hace el botón de la pestaña Upsell —el
  // mismo campo y el mismo apunte para deshacer—, solo que alcanzable desde
  // aquí.
  const alternarEtapaUpsell = (encendida: boolean) => {
    onEdit("upsell_enabled");
    setCfg({
      ...cfg,
      upsell: { ...(cfg.upsell ?? {}), enabled: encendida },
    } as FullConfig);
  };
  const setChannelEnabled = (
    channel: Exclude<ChannelKey, "whatsapp">,
    enabled: boolean
  ) => {
    onEdit(`channel_${channel}_enabled`);
    setCfg({
      ...cfg,
      channels: {
        ...(cfg.channels ?? {}),
        [channel]: {
          ...(cfg.channels?.[channel] ?? {}),
          enabled,
        },
      },
    });
  };
  const setChannelUseContent = (channel: ChannelKey, enabled: boolean) => {
    onEdit(`channel_${channel}_use_content`);
    setCfg({
      ...cfg,
      channels: {
        ...(cfg.channels ?? {}),
        [channel]: {
          ...(cfg.channels?.[channel] ?? {}),
          enabled: channel === "whatsapp" ? true : cfg.channels?.[channel]?.enabled === true,
          use_content: enabled,
        },
      },
    });
  };
  const setChannelContent = (
    channel: ChannelKey,
    content: ChannelContentEditor
  ) => {
    const normalizedContent = normalizeChannelContent(content);
    setCfg({
      ...cfg,
      channels: {
        ...(cfg.channels ?? {}),
        [channel]: {
          ...(cfg.channels?.[channel] ?? {}),
          // Editar o clonar contenido propio implica que debe usarse en runtime.
          // El usuario aun puede apagarlo explicitamente para volver a la Base.
          use_content: true,
          modality_templates: {
            ...(cfg.channels?.[channel]?.modality_templates ?? {}),
            [mode]: normalizedContent,
          },
        },
      },
    });
  };
  const cloneChannelFromBase = (channel: ChannelKey) => {
    const current = channelContentForMode(cfg, channel, mode);
    if (
      hasChannelContent(current) &&
      !confirm(
        "Al clonar desde Base reemplazaras todo lo que esta escrito en este canal y modalidad. ¿Continuar?"
      )
    ) {
      return;
    }
    onSnapshot();
    setChannelContent(channel, buildChannelContentFromBase(cfg, channel));
  };
  const cloneChannelFromChannel = (
    target: ChannelKey,
    sourceChannel: ChannelKey
  ) => {
    const source = channelContentForMode(cfg, sourceChannel, mode);
    const sourceName = CHANNEL_PROTOTYPE_META[sourceChannel].name;
    const targetName = CHANNEL_PROTOTYPE_META[target].name;
    if (!hasChannelContent(source)) {
      alert(
        `${sourceName} no tiene contenido propio en esta modalidad. Primero prepara ${sourceName} o usa Clonar desde Base.`
      );
      return;
    }
    const current = channelContentForMode(cfg, target, mode);
    if (
      hasChannelContent(current) &&
      !confirm(
        `Al clonar desde ${sourceName} reemplazaras todo lo que esta escrito en ${targetName} para esta modalidad. ¿Continuar?`
      )
    ) {
      return;
    }
    onSnapshot();
    setChannelContent(target, cloneJson(source));
  };

  // Clona SOLO una sección (saludo/intro, seguimientos, pago, etc.) desde el
  // canal actual a otro, preservando el resto del canal destino.
  const cloneChannelSection = (
    source: ChannelKey,
    target: ChannelKey,
    section: keyof ChannelContentEditor
  ) => {
    if (source === target) return;
    const sourceContent = channelContentForMode(cfg, source, mode);
    const sourceName = CHANNEL_PROTOTYPE_META[source].name;
    const targetName = CHANNEL_PROTOTYPE_META[target].name;
    const sectionLabel =
      CLONE_SECTIONS.find((s) => s.key === section)?.label ?? section;
    if (
      !confirm(
        `Se copiará SOLO "${sectionLabel}" desde ${sourceName} a ${targetName}, sin borrar el resto de ${targetName}. ¿Continuar?`
      )
    ) {
      return;
    }
    const targetContent = channelContentForMode(cfg, target, mode);
    onSnapshot();
    setChannelContent(target, {
      ...targetContent,
      [section]: cloneJson(sourceContent[section]),
    });
  };

  // Agrega cajones completos al canal destino. No reemplaza el contenido que ya
  // existe alli, para poder actualizar solo una parte de una secuencia probada.
  const copySelectedChannelBlocks = (
    source: ChannelKey,
    target: ChannelKey,
    block: SelectableChannelBlock,
    indexes: number[]
  ) => {
    if (source === target) return;
    const sourceContent = channelContentForMode(cfg, source, mode);
    const sourceItems = (sourceContent[block] ?? []) as Array<
      { enabled?: boolean; name?: string; steps?: EditorStep[] } | EditorStep
    >;
    const selectedItems = Array.from(new Set(indexes))
      .sort((a, b) => a - b)
      .map((index) => sourceItems[index])
      .filter(Boolean);
    if (selectedItems.length === 0) return;

    const sourceName = CHANNEL_PROTOTYPE_META[source].name;
    const targetName = CHANNEL_PROTOTYPE_META[target].name;
    const blockLabel =
      block === "intro_groups"
        ? "cajones de intro"
        : block === "followups"
          ? "seguimientos"
          : block === "payment"
            ? "burbujas de pago"
            : "cajones de entrega";
    if (
      !confirm(
        `Se agregaran ${selectedItems.length} ${blockLabel} desde ${sourceName} a ${targetName}. No se borrara el contenido actual de ${targetName}. ¿Continuar?`
      )
    ) {
      return;
    }

    const targetContent = channelContentForMode(cfg, target, mode);
    const targetItems = (targetContent[block] ?? []) as Array<{
      enabled?: boolean;
      name?: string;
      steps?: EditorStep[];
    }>;
    const usedNames = new Set(
      targetItems.map((item) => (item.name ?? "").trim().toLocaleLowerCase())
    );
    const copiedItems = selectedItems.map((item) => {
      const copy = cloneJson(item) as {
        enabled?: boolean;
        name?: string;
        steps?: EditorStep[];
      };
      // Toda copia llega apagada. Asi nunca duplica un envio hasta que el
      // usuario la revise y la ponga ON en el canal destino.
      copy.enabled = false;
      if (Array.isArray(copy.steps)) {
        copy.steps = copy.steps.map((step: EditorStep) => ({ ...step, enabled: false }));
      }
      const baseName = copy.name?.trim() || (block === "intro_groups" ? "Intro" : "Seguimiento");
      let nextName = baseName;
      let suffix = 2;
      while (usedNames.has(nextName.toLocaleLowerCase())) {
        nextName = `${baseName} copia${suffix === 2 ? "" : ` ${suffix}`}`;
        suffix += 1;
      }
      usedNames.add(nextName.toLocaleLowerCase());
      return copy.name !== undefined ? { ...copy, name: nextName } : copy;
    });

    onSnapshot();
    setChannelContent(target, {
      ...targetContent,
      [block]: [...targetItems, ...copiedItems],
    });
  };

  return (
    // EN COLUMNA, PARA PODER MANDAR EL PAÍS AL FINAL.
    //
    // El bloque del país está escrito ENTRE Facebook e Instagram, porque
    // gobierna a los dos. Con Facebook abierto quedaba debajo de sus barras, y
    // con Instagram abierto quedaba encima: la misma sección salía en un sitio
    // distinto según el canal, y parecía otra cosa.
    //
    // Se ordena aquí y no moviendo el bloque: moverlo obligaría a duplicarlo o
    // a partir la sección en dos, y es un solo ajuste que gobierna a ambos.
    // AQUÍ HABÍA UN SUELO PROPIO, Y SE QUITA.
    //
    // Se puso cuando el aspecto se probaba SOLO en esta pestaña y la página
    // seguía siendo blanca: hacía falta un gris debajo para que las tarjetas
    // blancas se despegaran de algo.
    //
    // Ya no: el panel gris lo pone la página para las quince. Dejarlo aquí
    // añadía un tercer gris —el oscuro del suelo— entre el panel claro y las
    // tarjetas, y esa franja oscura rodeando las tarjetas no la pintaba nadie a
    // propósito. La zona que rodea las tarjetas es el panel, y punto.
    <section className="flex flex-col gap-5">
      {/* AQUÍ HABÍA UNA SEGUNDA CABECERA, IGUAL QUE LA DE ARRIBA.
          Esta fue la primera, de cuando el aspecto se probaba solo en Canales.
          Ahora la pinta la página para las quince, con el mismo rótulo y la
          misma frase —están en `CABECERA_DE_TAB`—, así que dejarla aquí era
          decir «Canales» dos veces seguidas. */}
      <TarjetaSuave className="!p-4">
        <p className="text-sm text-tinta-suave">
          La Base sigue siendo la fuente importable. Aqui puedes preparar textos
          rapidos por canal; por ahora WhatsApp en esta seccion es una capa segura
          de edicion y no reemplaza el motor real.
        </p>
      </TarjetaSuave>

      <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
        {CHANNEL_KEYS.map((channel) => (
          <ChannelSummaryCard
            key={channel}
            channel={channel}
            abierto={canalAbierto === channel}
            onAbrir={() => setCanalAbierto(channel)}
          />
        ))}
      </div>

      {canalAbierto === "whatsapp" && (
      <ChannelWorkspace
        channel="whatsapp"
        anchorId="canal-whatsapp"
        mode={mode}
        onCfgChange={setCfg}
        content={channelContentForMode(cfg, "whatsapp", mode)}
        onContentChange={(content) => setChannelContent("whatsapp", content)}
        onCloneFromBase={() => cloneChannelFromBase("whatsapp")}
        onCloneSectionTo={(section, target) => cloneChannelSection("whatsapp", target, section)}
        onCopySelectedBlocks={(block, indexes, target) => copySelectedChannelBlocks("whatsapp", target, block, indexes)}
        cfg={cfg}
        onRegistryChange={(ad_registry) => { onEdit("ad_registry"); setCfg({ ...cfg, ad_registry }); }}
        enabled
        runtimeEnabled={cfg.channels?.whatsapp?.use_content === true}
        onToggleRuntimeEnabled={(enabled) => setChannelUseContent("whatsapp", enabled)}
        onSnapshot={onSnapshot}
        onEdit={onEdit}
        onModalidadOrderBump={onModalidadOrderBump}
        onEtapaUpsell={alternarEtapaUpsell}
      />
      )}
      {canalAbierto === "messenger" && (
      <ChannelWorkspace
        channel="messenger"
        anchorId="canal-messenger"
        mode={mode}
        onCfgChange={setCfg}
        content={channelContentForMode(cfg, "messenger", mode)}
        onContentChange={(content) => setChannelContent("messenger", content)}
        onCloneFromBase={() => cloneChannelFromBase("messenger")}
        onCloneSectionTo={(section, target) => cloneChannelSection("messenger", target, section)}
        onCopySelectedBlocks={(block, indexes, target) => copySelectedChannelBlocks("messenger", target, block, indexes)}
        cloneSources={["whatsapp", "instagram"]}
        onCloneFromChannel={(source) => cloneChannelFromChannel("messenger", source)}
        cfg={cfg}
        onRegistryChange={(ad_registry) => { onEdit("ad_registry"); setCfg({ ...cfg, ad_registry }); }}
        enabled={cfg.channels?.messenger?.enabled === true}
        onToggleEnabled={(enabled) => setChannelEnabled("messenger", enabled)}
        runtimeEnabled={cfg.channels?.messenger?.use_content === true}
        onToggleRuntimeEnabled={(enabled) => setChannelUseContent("messenger", enabled)}
        onSnapshot={onSnapshot}
        onEdit={onEdit}
        onModalidadOrderBump={onModalidadOrderBump}
        onEtapaUpsell={alternarEtapaUpsell}
      />
      )}
      {/* EL PAÍS DE MESSENGER E INSTAGRAM: SALE CON LOS DOS.
          Es una sola configuración que gobierna a ambos, así que se muestra en
          cualquiera de los dos y en ninguno más. Estaba suelta entre las dos
          fichas, y ahí no se sabía a cuál pertenecía. */}
      {(canalAbierto === "messenger" || canalAbierto === "instagram") && (
      // `order-last` lo manda al final pase lo que pase: debajo de las barras
      // del canal abierto, sea Facebook o sea Instagram.
      //
      // Y CON EL COLOR DEL CANAL QUE SE ESTÁ VIENDO. Salía siempre azul, y
      // debajo de las barras de Instagram, que son magenta, parecía un trozo de
      // Facebook colado ahí. Es la misma configuración; solo se viste del canal
      // delante del que aparece.
      <section className="order-last overflow-hidden rounded-2xl border border-borde bg-tarjeta shadow-sm">
        {/* La cinta lleva el color del canal delante del que aparece. Es una
            sola configuración que gobierna a los dos, y antes salía siempre
            azul: debajo de las barras de Instagram parecía un trozo de Facebook
            colado ahí. */}
        <div
          className={`h-1.5 w-full ${
            TONOS_DEL_TEMA[canalAbierto === "instagram" ? "fucsia" : "cielo"].ficha
          }`}
        />
        <div className="p-5">
        <div className="flex flex-wrap items-start justify-between gap-4">
          <div className="flex min-w-0 items-center gap-3">
            <FichaDeIcono
              tono={canalAbierto === "instagram" ? "fucsia" : "cielo"}
              tamano="lg"
            >
              🌎
            </FichaDeIcono>
            <div className="min-w-0">
              <h3 className="font-titulo text-xl font-extrabold tracking-tight text-tinta">
                País antes de vender
              </h3>
              <p className="mt-0.5 max-w-2xl text-xs leading-snug text-tinta-suave">
                Messenger e Instagram no informan la lada. El bot preguntará el
                país una vez y guardará la respuesta para precios, métodos,
                comprobante y seguimientos. Esta configuración aplica a ambos
                canales.
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={() => {
              onEdit("messenger_country_prompt");
              setCfg({ ...cfg, messenger_country_prompt: { ...cfg.messenger_country_prompt, enabled: !(cfg.messenger_country_prompt?.enabled === true), message: cfg.messenger_country_prompt?.message ?? "" } });
            }}
            className={`shrink-0 rounded-full px-4 py-2 text-xs font-bold shadow-sm transition-colors ${cfg.messenger_country_prompt?.enabled === true ? "bg-emerald-600 text-white hover:bg-emerald-700" : "border border-borde bg-tarjeta text-tinta-suave hover:bg-relleno"}`}
          >
            {cfg.messenger_country_prompt?.enabled === true ? "Activado" : "Apagado"}
          </button>
        </div>
        <div className="mt-4 grid gap-3 md:grid-cols-2">
          <label className="block text-xs font-semibold text-sky-950">Pregunta inicial editable — admite spintax {"{Hola|Buenas}"}<textarea value={cfg.messenger_country_prompt?.message ?? ""} onChange={(event) => { onEdit("messenger_country_prompt"); setCfg({ ...cfg, messenger_country_prompt: { ...cfg.messenger_country_prompt, enabled: cfg.messenger_country_prompt?.enabled === true, message: event.target.value } }); }} rows={2} placeholder="{Hola|Buenas}, ¿de qué país nos visitas?" className="mt-1 w-full resize-y rounded-md border border-sky-200 bg-tarjeta px-3 py-2 text-sm text-neutral-900" /></label>
          <SpintaxPreviewBubble variants={[cfg.messenger_country_prompt?.message ?? ""]} />
        </div>
        <div className="mt-4 rounded-md border border-sky-200 bg-tarjeta p-3">
          <label className="flex items-center justify-between gap-3 text-xs font-semibold text-sky-950">
            <span>Recordatorio único si no responde el país</span>
            <input
              type="checkbox"
              checked={cfg.messenger_country_prompt?.reminder_enabled === true}
              onChange={(event) => {
                onEdit("messenger_country_prompt");
                setCfg({
                  ...cfg,
                  messenger_country_prompt: {
                    ...cfg.messenger_country_prompt,
                    enabled: cfg.messenger_country_prompt?.enabled === true,
                    message: cfg.messenger_country_prompt?.message ?? "",
                    reminder_enabled: event.target.checked,
                  },
                });
              }}
              className="h-4 w-4"
            />
          </label>
          {cfg.messenger_country_prompt?.reminder_enabled === true && (
            <div className="mt-3 grid gap-3 md:grid-cols-[150px_minmax(0,1fr)_minmax(0,1fr)]">
              <label className="text-xs font-semibold text-sky-950">
                Esperar minutos
                <input
                  type="number"
                  min={1}
                  value={cfg.messenger_country_prompt?.reminder_delay_minutes ?? 5}
                  onChange={(event) => {
                    const value = Number(event.target.value);
                    onEdit("messenger_country_prompt");
                    setCfg({
                      ...cfg,
                      messenger_country_prompt: {
                        ...cfg.messenger_country_prompt,
                        enabled: cfg.messenger_country_prompt?.enabled === true,
                        message: cfg.messenger_country_prompt?.message ?? "",
                        reminder_delay_minutes:
                          Number.isFinite(value) && value >= 1 ? Math.round(value) : 1,
                      },
                    });
                  }}
                  className="mt-1 w-full rounded-md border border-sky-200 px-3 py-2 text-sm text-neutral-900"
                />
              </label>
              <label className="text-xs font-semibold text-sky-950">
                Texto del recordatorio
                <textarea
                  rows={2}
                  value={cfg.messenger_country_prompt?.reminder_message ?? ""}
                  onChange={(event) => {
                    onEdit("messenger_country_prompt");
                    setCfg({
                      ...cfg,
                      messenger_country_prompt: {
                        ...cfg.messenger_country_prompt,
                        enabled: cfg.messenger_country_prompt?.enabled === true,
                        message: cfg.messenger_country_prompt?.message ?? "",
                        reminder_message: event.target.value,
                      },
                    });
                  }}
                  className="mt-1 w-full resize-y rounded-md border border-sky-200 px-3 py-2 text-sm text-neutral-900"
                />
              </label>
              <SpintaxPreviewBubble variants={[cfg.messenger_country_prompt?.reminder_message ?? ""]} />
            </div>
          )}
          <p className="mt-2 text-xs text-sky-800">Si no responde, se envía una sola vez y no inicia la venta ni los seguimientos.</p>
        </div>
        <p className="mt-2 text-xs text-sky-800">Reconoce respuestas con errores comunes: “Peruu”, “Pru”, “Ecudor”, etc.</p>
        <label className="mt-4 block text-xs font-semibold text-sky-950">Si el cliente escribe sin decir su país, responder con:
          <select value={cfg.messenger_country_prompt?.reask_mode ?? "spintax"} onChange={(event) => { onEdit("messenger_country_prompt"); setCfg({ ...cfg, messenger_country_prompt: { ...cfg.messenger_country_prompt, enabled: cfg.messenger_country_prompt?.enabled === true, message: cfg.messenger_country_prompt?.message ?? "", reask_mode: event.target.value as "spintax" | "microcall" | "llm" } }); }} className="mt-1 w-full rounded-md border border-sky-200 bg-tarjeta px-3 py-2 text-sm text-neutral-900">
            <option value="spintax">Spintax — frases variadas fijas (gratis)</option>
            <option value="microcall">Micro-llamada — IA breve y barata</option>
            <option value="llm">LLM completo — IA con más contexto</option>
          </select>
        </label>
        {(cfg.messenger_country_prompt?.reask_mode ?? "spintax") === "spintax" ? (
          <div className="mt-3 grid gap-3 md:grid-cols-2">
            <label className="block text-xs font-semibold text-sky-950">Frases (una por línea) — el bot elige una al azar<textarea value={(cfg.messenger_country_prompt?.reask_variants ?? []).join("\n")} onChange={(event) => { onEdit("messenger_country_prompt"); setCfg({ ...cfg, messenger_country_prompt: { ...cfg.messenger_country_prompt, enabled: cfg.messenger_country_prompt?.enabled === true, message: cfg.messenger_country_prompt?.message ?? "", reask_variants: event.target.value.split("\n") } }); }} rows={8} className="mt-1 w-full resize-y rounded-md border border-sky-200 bg-tarjeta px-3 py-2 text-sm text-neutral-900" /></label>
            <SpintaxPreviewBubble variants={cfg.messenger_country_prompt?.reask_variants ?? []} />
          </div>
        ) : (
          <label className="mt-3 block text-xs font-semibold text-sky-950">Instrucción para la IA (tu estilo, editable)<textarea value={cfg.messenger_country_prompt?.reask_instruction ?? ""} onChange={(event) => { onEdit("messenger_country_prompt"); setCfg({ ...cfg, messenger_country_prompt: { ...cfg.messenger_country_prompt, enabled: cfg.messenger_country_prompt?.enabled === true, message: cfg.messenger_country_prompt?.message ?? "", reask_instruction: event.target.value } }); }} rows={4} className="mt-1 w-full resize-y rounded-md border border-sky-200 bg-tarjeta px-3 py-2 text-sm text-neutral-900" /></label>
        )}
        <p className="mt-2 text-xs text-tinta-suave">La IA nunca da precio ni métodos hasta que el cliente diga su país. Todos estos textos son editables.</p>
        </div>
      </section>
      )}
      {canalAbierto === "instagram" && (
      <ChannelWorkspace
        channel="instagram"
        anchorId="canal-instagram"
        mode={mode}
        onCfgChange={setCfg}
        content={channelContentForMode(cfg, "instagram", mode)}
        onContentChange={(content) => setChannelContent("instagram", content)}
        onCloneFromBase={() => cloneChannelFromBase("instagram")}
        onCloneSectionTo={(section, target) => cloneChannelSection("instagram", target, section)}
        onCopySelectedBlocks={(block, indexes, target) => copySelectedChannelBlocks("instagram", target, block, indexes)}
        cloneSources={["whatsapp", "messenger"]}
        onCloneFromChannel={(source) => cloneChannelFromChannel("instagram", source)}
        cfg={cfg}
        onRegistryChange={(ad_registry) => { onEdit("ad_registry"); setCfg({ ...cfg, ad_registry }); }}
        enabled={cfg.channels?.instagram?.enabled === true}
        onToggleEnabled={(enabled) => setChannelEnabled("instagram", enabled)}
        runtimeEnabled={cfg.channels?.instagram?.use_content === true}
        onToggleRuntimeEnabled={(enabled) => setChannelUseContent("instagram", enabled)}
        onSnapshot={onSnapshot}
        onEdit={onEdit}
        onModalidadOrderBump={onModalidadOrderBump}
        onEtapaUpsell={alternarEtapaUpsell}
      />
      )}
      {canalAbierto === "tiktok" && (
      <ChannelWorkspace
        channel="tiktok"
        anchorId="canal-tiktok"
        mode={mode}
        onCfgChange={setCfg}
        content={channelContentForMode(cfg, "tiktok", mode)}
        onContentChange={(content) => setChannelContent("tiktok", content)}
        onCloneFromBase={() => cloneChannelFromBase("tiktok")}
        onCloneSectionTo={(section, target) => cloneChannelSection("tiktok", target, section)}
        onCopySelectedBlocks={(block, indexes, target) => copySelectedChannelBlocks("tiktok", target, block, indexes)}
        cloneSources={["whatsapp", "messenger", "instagram"]}
        onCloneFromChannel={(source) => cloneChannelFromChannel("tiktok", source)}
        cfg={cfg}
        onRegistryChange={(ad_registry) => { onEdit("ad_registry"); setCfg({ ...cfg, ad_registry }); }}
        enabled={cfg.channels?.tiktok?.enabled === true}
        onToggleEnabled={(enabled) => setChannelEnabled("tiktok", enabled)}
        runtimeEnabled={cfg.channels?.tiktok?.use_content === true}
        onToggleRuntimeEnabled={(enabled) => setChannelUseContent("tiktok", enabled)}
        disabled
        onSnapshot={onSnapshot}
        onEdit={onEdit}
        onModalidadOrderBump={onModalidadOrderBump}
        onEtapaUpsell={alternarEtapaUpsell}
      />
      )}
    </section>
  );
}

/**
 * LA TARJETA DE UN CANAL: AHORA ELIGE, NO DESPLAZA.
 *
 * Antes solo hacía scroll hasta su ficha, porque las cuatro estaban pintadas a
 * la vez. Ahora abre la suya y esconde las demás, así que la tarjeta tiene que
 * decir cuál está abierta: sin eso, tocar una y ver cambiar la pantalla entera
 * deja la duda de en cuál se está escribiendo.
 */
function ChannelSummaryCard({
  channel,
  abierto,
  onAbrir,
}: {
  channel: ChannelKey;
  abierto: boolean;
  onAbrir: () => void;
}) {
  const meta = CHANNEL_PROTOTYPE_META[channel];
  const tono = TONOS_DEL_TEMA[meta.tono];
  // EL QUE NO ESTÁ ABIERTO NO SE APAGA, SE QUEDA EN REPOSO.
  //
  // Antes los otros tres iban al 60% de opacidad: el nombre y la frase de abajo
  // se volvían ilegibles justo cuando hacen falta, que es para decidir a cuál
  // ir. El abierto se marca poniéndolo en pie —anillo de su color y una sombra
  // más alta—, no hundiendo a los demás.
  return (
    <button
      type="button"
      onClick={onAbrir}
      aria-pressed={abierto}
      className={`w-full cursor-pointer rounded-2xl border bg-tarjeta p-4 text-left transition-all hover:-translate-y-0.5 hover:shadow-md ${
        abierto
          ? `border-transparent shadow-md ring-2 ${tono.anillo}`
          : "border-borde shadow-sm"
      }`}
    >
      <div className="flex items-start gap-3">
        <FichaDeIcono tono={meta.tono} tamano="lg">
          {meta.short}
        </FichaDeIcono>
        <div className="min-w-0">
          <div className="font-titulo truncate text-base font-extrabold tracking-tight text-tinta">
            {meta.name}
          </div>
          <div className={`text-xs font-semibold ${tono.rotulo}`}>
            {meta.status}
          </div>
          <div className="mt-1.5 text-[11px] leading-snug text-tinta-suave">
            {meta.setupHint}
          </div>
        </div>
      </div>
    </button>
  );
}

function ChannelWorkspace({
  channel,
  mode,
  introGroups,
  followups,
  deliveryPreviewSteps,
  content,
  onContentChange,
  onCloneFromBase,
  cloneSources = [],
  onCloneFromChannel,
  onCloneSectionTo,
  onCopySelectedBlocks,
  cfg,
  onCfgChange,
  onRegistryChange,
  connected = false,
  enabled = false,
  runtimeEnabled = false,
  onToggleEnabled,
  onToggleRuntimeEnabled,
  disabled = false,
  onSnapshot,
  onEdit,
  anchorId,
  onModalidadOrderBump,
  onEtapaUpsell,
}: {
  channel: ChannelKey;
  mode: Modo;
  introGroups?: Array<{ label: string; steps: EditorStep[] }>;
  followups?: EditorFollowup[];
  deliveryPreviewSteps?: EditorStep[];
  content?: ChannelContentEditor;
  onContentChange?: (content: ChannelContentEditor) => void;
  onCloneFromBase?: () => void;
  cloneSources?: ChannelKey[];
  onCloneFromChannel?: (source: ChannelKey) => void;
  onCloneSectionTo?: (section: keyof ChannelContentEditor, target: ChannelKey) => void;
  onCopySelectedBlocks?: (
    block: SelectableChannelBlock,
    indexes: number[],
    target: ChannelKey
  ) => void;
  cfg: FullConfig;
  /** Para ajustes que no son contenido del canal (p. ej. comentarios). */
  onCfgChange?: (next: FullConfig) => void;
  /** Enciende o apaga la MODALIDAD Order Bump desde la fila de este canal.
   *  Es el mismo camino que el interruptor de su pestaña, no uno paralelo: dos
   *  formas de encender lo mismo acaban haciendo cosas distintas. */
  onModalidadOrderBump?: (encendida: boolean) => void;
  /** Enciende o apaga la ETAPA upsell de la modalidad que vende. No cambia de
   *  modalidad: solo quita o pone la segunda venta. */
  onEtapaUpsell?: (encendida: boolean) => void;
  onRegistryChange: (entries: AdRegistryEntry[]) => void;
  connected?: boolean;
  enabled?: boolean;
  runtimeEnabled?: boolean;
  onToggleEnabled?: (enabled: boolean) => void;
  onToggleRuntimeEnabled?: (enabled: boolean) => void;
  disabled?: boolean;
  onSnapshot: () => void;
  onEdit: (key: string) => void;
  anchorId?: string;
}) {
  const meta = CHANNEL_PROTOTYPE_META[channel];
  // QUÉ SECCIÓN DEL CANAL ESTÁ ABIERTA. Una a la vez, en su ventana.
  const [seccionAbierta, setSeccionAbierta] = useState<
    | null
    | "intro"
    | "seguimientos"
    | "orderbump"
    | "upsell"
    | "entregas"
    | "postventa"
    | "comentarios"
  >(null);
  const otherChannels = CHANNEL_KEYS.filter((c) => c !== channel);
  const [cloneSection, setCloneSection] = useState<keyof ChannelContentEditor>("intro_groups");
  const [cloneTarget, setCloneTarget] = useState<ChannelKey>(otherChannels[0] ?? "messenger");
  // EL PRECIO DE ESTAS VISTAS SE PREGUNTA, NO SE COGE A PELO.
  //
  // Decía `cfg.globals.course_price_soles`: el número guardado en la raíz del
  // archivo, que el motor reemplaza al arrancar. Aquí, además, se cogía SIN
  // mirar el país ni la ficha, así que estas vistas enseñaban ese número viejo
  // pasara lo que pasara — mientras las otras dos líneas de aquí abajo sí
  // preguntaban. Tres vistas pegadas, dos diciendo la verdad y una no.
  //
  // Ahora usa el mismo resolvedor que el resto, que ya mira la capa del país y
  // la ficha por país antes de caer a ese número.
  const price = previewFullPriceFromConfig(cfg);
  const comboPreviewPrice = previewComboPriceFromConfig(cfg);
  const basicoPreviewPrice = previewBasicoPriceFromConfig(cfg);
  const previewStagePrices = (followupIndex: number) => ({
    price: previewFullPriceForFollowup(cfg, followupIndex),
    combo: previewOrderBumpPriceForFollowup(cfg, "combo", followupIndex),
    basico: previewOrderBumpPriceForFollowup(cfg, "basico", followupIndex),
  });
  const editableContent = content ?? emptyChannelContent();
  const updateContent = (patch: Partial<ChannelContentEditor>) => {
    onContentChange?.({ ...editableContent, ...patch });
  };
  const previewContext = previewContextFromConfig(cfg);
  // LA PREGUNTA DEL FINAL DEL UPSELL, SEMBRADA COMO LOS CAJONES.
  //
  // Sin nada escrito en este canal se enseña la de la modalidad —que es la que
  // sale hoy—, y en cuanto se toca una burbuja pasa a ser de este canal. Así no
  // se abre una pantalla en blanco que parece que la pregunta se perdió.
  const preguntaDelUpsell =
    (editableContent.upsell_pregunta_steps ?? []).length > 0
      ? editableContent.upsell_pregunta_steps ?? []
      : cloneJson(cfg.upsell?.pregunta_steps ?? []);
  const collapseChannel = () => {
    window.dispatchEvent(
      new CustomEvent("wf:collapse-all", { detail: { prefix: `channel_${channel}_` } })
    );
  };

  return (
    // EL CANAL ABIERTO, EN BLANCO Y CON SU COLOR EN UNA CINTA.
    //
    // El panel iba entero del color del canal, así que el verde de WhatsApp
    // teñía el fondo de todo lo que hubiera dentro: barras, campos y visores. A
    // media pantalla de color, el color deja de señalar nada.
    //
    // Ahora la tarjeta es blanca y el canal se reconoce por la cinta de arriba y
    // por su cuadradito. `panelClass` no se toca: lo usan otras pantallas.
    <div
      id={anchorId}
      className="scroll-mt-4 overflow-hidden rounded-2xl border border-borde bg-tarjeta shadow-sm"
    >
      <div className={`h-1.5 w-full ${TONOS_DEL_TEMA[meta.tono].ficha}`} />
      <div className="p-5">
      <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <FichaDeIcono tono={meta.tono} tamano="lg">
            {meta.short}
          </FichaDeIcono>
          <div>
            <h3 className="font-titulo text-2xl font-extrabold tracking-tight text-tinta">
              {meta.name}
            </h3>
            <p className={`text-xs font-semibold ${TONOS_DEL_TEMA[meta.tono].rotulo}`}>
              {meta.status} · Modalidad: {MODALIDAD_LABEL[mode]}
            </p>
            <p className="mt-1 max-w-xl text-[11px] leading-snug text-tinta-suave">
              {meta.setupHint}
            </p>
          </div>
        </div>
        <button
          type="button"
          onClick={collapseChannel}
          className="rounded-full border border-borde bg-tarjeta px-3.5 py-2 text-xs font-bold text-tinta-suave shadow-sm transition-colors hover:bg-relleno"
        >
          Cerrar todos los cajones
        </button>
        {/* LOS MANDOS DE LA CABECERA, EN COLORES DEL TEMA.
            Iban en ámbar claro, blanco y azul claro puestos a mano, así que en
            oscuro se quedaban clarísimos sobre fondo oscuro: manchas brillantes
            flotando, y el texto oscuro encima casi ilegible.
            Ahora usan relleno, borde y tinta del tema. El AVISO sigue estando,
            pero lo da el estado marcado —relleno de acento cuando está
            encendido—, no un color pegado de fábrica. */}
        {(channel === "whatsapp" || onToggleRuntimeEnabled) && (
          <label
            className={`flex cursor-pointer items-center gap-2 rounded-full border px-4 py-2 text-xs font-bold transition-colors ${
              runtimeEnabled
                ? "border-acento/40 bg-acento-suave text-acento oscuro:border-transparent oscuro:bg-acento oscuro:text-white"
                : "border-borde bg-tarjeta text-tinta-suave hover:bg-relleno"
            }`}
          >
            <input
              type="checkbox"
              checked={runtimeEnabled}
              onChange={(e) => onToggleRuntimeEnabled?.(e.target.checked)}
              disabled={disabled || (channel !== "whatsapp" && !enabled)}
              className="h-4 w-4 accent-acento"
            />
            Textos propios del canal
          </label>
        )}
        {channel !== "whatsapp" && (
          <label
            className={`flex cursor-pointer items-center gap-2 rounded-full border px-4 py-2 text-xs font-bold transition-colors ${
              enabled
                ? "border-transparent bg-emerald-600 text-white"
                : "border-borde bg-tarjeta text-tinta-suave hover:bg-relleno"
            }`}
          >
            <input
              type="checkbox"
              checked={enabled}
              onChange={(e) => onToggleEnabled?.(e.target.checked)}
              disabled={disabled}
              className="h-4 w-4 accent-emerald-600"
            />
            {enabled ? "ON" : "OFF"}
          </label>
        )}
        {!connected && !disabled && (
          <div className="flex flex-wrap items-center gap-2">
            <button
              type="button"
              onClick={onCloneFromBase}
              title="Copia una vez el contenido base de la modalidad activa para este canal"
              className="rounded-full border border-borde bg-tarjeta px-4 py-2 text-xs font-bold text-tinta-suave transition-colors hover:bg-relleno"
            >
              Clonar desde Base
            </button>
            {cloneSources.map((source) => (
              <button
                key={source}
                type="button"
                onClick={() => onCloneFromChannel?.(source)}
                title={`Copia una vez el contenido preparado en ${CHANNEL_PROTOTYPE_META[source].name} para esta modalidad`}
                className="rounded-full border border-borde bg-tarjeta px-4 py-2 text-xs font-bold text-tinta-suave transition-colors hover:bg-relleno"
              >
                Clonar desde {CHANNEL_PROTOTYPE_META[source].name}
              </button>
            ))}
          </div>
        )}
        {!connected && !disabled && onCloneSectionTo && otherChannels.length > 0 && (
          <div className="mt-2 flex flex-wrap items-center gap-2 rounded-xl border border-borde bg-relleno px-3 py-2">
            <span className="text-xs font-bold text-tinta-suave">Clonar solo:</span>
            <select
              value={cloneSection}
              onChange={(e) => setCloneSection(e.target.value as keyof ChannelContentEditor)}
              className="rounded-lg border border-borde bg-tarjeta px-2 py-1 text-xs text-tinta"
            >
              {CLONE_SECTIONS.map((s) => (
                <option key={s.key} value={s.key}>{s.label}</option>
              ))}
            </select>
            <span className="text-xs text-tinta-suave">→</span>
            <select
              value={cloneTarget}
              onChange={(e) => setCloneTarget(e.target.value as ChannelKey)}
              className="rounded-lg border border-borde bg-tarjeta px-2 py-1 text-xs text-tinta"
            >
              {otherChannels.map((c) => (
                <option key={c} value={c}>{CHANNEL_PROTOTYPE_META[c].name}</option>
              ))}
            </select>
            {/* PERFILADO, NO RELLENO. El relleno sólido se reserva para lo que
                está ENCENDIDO. Un botón de acción con el mismo bloque de color
                compite con él y llena la pantalla de manchas fuertes. */}
            <button
              type="button"
              onClick={() => onCloneSectionTo(cloneSection, cloneTarget)}
              className="rounded-full border border-acento bg-tarjeta px-4 py-1.5 text-xs font-bold text-acento transition-colors hover:bg-acento-suave"
            >
              Clonar sección
            </button>
          </div>
        )}
      </div>

      {/* LAS SECCIONES DEL CANAL, EN VENTANA.
          Eran cajones desplegables uno debajo de otro. Cada uno trae dentro un
          editor entero —la intro con sus cajones, los seguimientos con sus
          variantes, las entregas por modalidad—, así que abrir dos dejaba la
          página kilométrica y perdías de vista en cuál estabas escribiendo.
          Ahora se abre una a la vez, en su ventana, y el resto no estorba. */}
      {/* BARRAS, COMO LOS DESPLEGABLES DE ANTES.
          Mismo aspecto: una barra por sección, apiladas, con su flecha a la
          izquierda y su chapa a la derecha. Lo único que cambia es lo que hace
          al tocarla — abre su ventana en vez de crecer hacia abajo. Se conserva
          la forma porque ya se reconoce de un vistazo: cambiar el aspecto Y el
          comportamiento a la vez obliga a reaprender el sitio entero. */}
      {/* LA MISMA BARRA, CON LA ROPA DEL TEMA CLARO.
          Hace exactamente lo de antes: abre su ventana. Lo que cambia es que
          se apoya en blanco con esquina generosa, lleva el cuadradito de color
          de su asunto, y al pasar por encima se levanta un pelo en vez de
          oscurecerse. La chapa de «Abrir» se rellena al apuntarla, así que el
          sitio donde hay que hacer clic es el sitio que responde. */}
      <div className="space-y-3">
        {SECCIONES_DEL_CANAL.filter(({ clave }) => {
          if (clave === "comentarios") {
            return channel === "messenger" && Boolean(onCfgChange);
          }
          // LA OFERTA SOLO DONDE HAY DOS OPCIONES QUE OFRECER. Escribir esos
          // cajones en una modalidad que vende una sola es escribir algo que
          // nunca sale.
          //
          // SE PREGUNTA POR EL DATO, NO POR EL NOMBRE — 22 de septiembre de
          // 2026. Preguntaba `activeModality(cfg) === "order_bump"`, y con la
          // presentación prestada lineal SIGUE llamándose lineal aunque esté
          // vendiendo dos opciones: la fila no aparecía y no había dónde
          // escribir la intro de la oferta de ese canal. Con sus palabras: «al
          // cambiar de PRESENTA no aparece en el menú de canales sus
          // respectivos intros como aparecen al cambiar de modalidad».
          //
          // Es el mismo fallo que ya costó tres veces en este proyecto —la caja
          // que una modalidad llena y otra no abre— y la regla escrita es
          // exactamente ésta: preguntar por el dato.
          //
          // Y SOLO EN LA FORMA QUE TIENE SEGUNDA INTRO. «Como -DOU-» presenta
          // las dos opciones en la intro principal —la fila «Intro» de arriba—,
          // así que ahí no falta nada. La que revela la segunda al ir a pagar
          // es «como -OB-», y ésa sí necesita su propio cajón. Es la misma
          // diferencia que entre las modalidades de verdad.
          if (clave === "orderbump") {
            return (
              activeModality(cfg) === "order_bump" ||
              segundaOpcionPrestada(cfg) === "segunda_oculta"
            );
          }
          return true;
        }).map(({ clave, icono, titulo, detalle }) => (
          <FilaDeSeccion
            key={clave}
            tono={meta.tono}
            icono={icono}
            titulo={titulo}
            detalle={detalle}
            // SOLO ESTAS DOS LLEVAN EL PUNTO, porque son las únicas de la lista
            // que se pueden apagar. Y AQUÍ SE APAGAN: el punto es el
            // interruptor, no un cartel.
            //
            // No es un interruptor paralelo: cada uno llama al MISMO sitio que
            // su pestaña —Order Bump pasa por el cambio de modalidad, con su
            // guardado y su recarga; Upsell escribe el mismo campo de la etapa—.
            // Dos caminos distintos para una decisión acaban discrepando.
            //
            // Y cuidado con Order Bump: apagarlo devuelve el bot a Lineal, así
            // que la fila desaparece de la lista en cuanto se apaga. Es lo
            // correcto —en Lineal no hay dos opciones que ofrecer— pero conviene
            // saberlo antes de buscarla.
            activo={
              clave === "orderbump"
                ? cfg.order_bump.enabled === true
                : clave === "upsell"
                  ? cfg.upsell?.enabled === true
                  : undefined
            }
            onCambiarActivo={
              clave === "orderbump"
                ? onModalidadOrderBump
                : clave === "upsell"
                  ? onEtapaUpsell
                  : undefined
            }
            onAbrir={() => setSeccionAbierta(clave)}
          />
        ))}
      </div>

      {/* AQUÍ HABÍA UN AVISO sobre dónde se editan los datos de pago. Se retira
          a petición del operador: con las secciones en ventana, el aviso
          quedaba suelto en medio de la pantalla sin nada a lo que referirse. */}

      {seccionAbierta === "intro" && (
        <VentanaDeProducto
          titulo={`Intro · ${meta.name}`}
          colorPorDefecto="blanco"
          onCerrar={() => setSeccionAbierta(null)}
        >
          {/* EL SALUDO INICIAL YA NO VA APARTE.
              Era el primer cajón de esta misma intro, dibujado en su propia
              sección. Dos sitios para una sola lista: había que acordarse de
              que el primero vivía en otro sitio, y al mover cajones el reparto
              dejaba de tener sentido. Ahora la intro se ve entera, desde el
              primer cajón. */}
          {connected ? (
            <div className="space-y-3">
              {(introGroups ?? []).map((group, index) => (
                <Collapsible
                  key={group.label}
                  title={group.label}
                  titleKey={`channel_${channel}_intro_${index}`}
                >
                  <ChatPreview
                    steps={group.steps}
                    priceSoles={price}
                    comboPrice={comboPreviewPrice}
                    basicoPrice={basicoPreviewPrice}
                    previewContext={previewContext}
                  />
                </Collapsible>
              ))}
            </div>
          ) : (
            <ChannelIntroEditor
              channel={channel}
              content={editableContent}
              onChange={updateContent}
              price={price}
              comboPrice={comboPreviewPrice}
              basicoPrice={basicoPreviewPrice}
              previewContext={previewContext}
              onSnapshot={onSnapshot}
              onEdit={onEdit}
              registry={cfg.ad_registry ?? []}
              onRegistryChange={onRegistryChange}
              copyTargets={otherChannels}
              onCopySelected={(indexes, target) =>
                onCopySelectedBlocks?.("intro_groups", indexes, target)
              }
              copyDisabled={disabled}
            />
          )}
        </VentanaDeProducto>
      )}

      {seccionAbierta === "seguimientos" && (
        <VentanaDeProducto
          titulo={`Seguimientos · ${meta.name}`}
          colorPorDefecto="blanco"
          onCerrar={() => setSeccionAbierta(null)}
        >
          {connected ? (
            <div className="space-y-3">
              {(followups ?? []).length === 0 && (
                <p className="text-sm text-neutral-500">
                  No hay seguimientos activos para mostrar.
                </p>
              )}
              {(followups ?? []).map((followup, index) => (
                <Collapsible
                  // LA LLAVE NO LLEVA EL NOMBRE. Ver el porqué en el otro cajón
                  // de seguimientos de este mismo archivo: con el nombre dentro,
                  // escribir una letra tira el panel entero y el cursor se pierde.
                  key={`channel-${channel}-followup-${index}`}
                  title={followup.name || "Ponle un título al cajón"}
                  tituloDeRelleno={!followup.name?.trim()}
                  titleKey={`channel_${channel}_followup_${index}`}
                >
                  <div className="mb-2 flex flex-wrap items-center justify-between gap-2">
                    <span className="rounded-md border border-neutral-200 bg-neutral-50 px-2 py-1 text-[11px] font-semibold text-neutral-600">
                      {followupTimeLabel(followup.delay_minutes_from_first_message)}
                    </span>
                  </div>
                  <ChatPreview
                    steps={compactSteps(followup.steps)}
                    priceSoles={price}
                    comboPrice={comboPreviewPrice}
                    basicoPrice={basicoPreviewPrice}
                    previewPriceOverride={previewStagePrices(index).price}
                    previewComboPriceOverride={previewStagePrices(index).combo}
                    previewBasicoPriceOverride={previewStagePrices(index).basico}
                    previewContext={previewContext}
                  />
                  {(followup.variants ?? []).length > 0 && (
                    <div className="mt-2 text-[11px] font-semibold text-sky-700">
                      Variantes: {(followup.variants ?? []).length}
                    </div>
                  )}
                </Collapsible>
              ))}
            </div>
          ) : (
            <ChannelFollowupsEditor
              channel={channel}
              content={editableContent}
              onChange={updateContent}
              price={price}
              comboPrice={comboPreviewPrice}
              basicoPrice={basicoPreviewPrice}
              previewStagePrices={previewStagePrices}
              previewContext={previewContext}
              onSnapshot={onSnapshot}
              onEdit={onEdit}
              registry={cfg.ad_registry ?? []}
              onRegistryChange={onRegistryChange}
              copyTargets={otherChannels}
              onCopySelected={(indexes, target) =>
                onCopySelectedBlocks?.("followups", indexes, target)
              }
              copyDisabled={disabled}
            />
          )}
        </VentanaDeProducto>
      )}

      {/* AQUÍ HABÍA UN CAJÓN «PAGO», Y NO SERVÍA PARA NADA.
          Se leía del archivo, se veía aquí y se guardaba de vuelta — pero el
          motor NUNCA lo leyó, desde el primer commit. Los datos de pago salen
          de Precios y pagos → país, que es lo que permite que cada cliente
          reciba los suyos.

          Lo escrito en el YAML NO se borra: el guardado lo sigue leyendo y
          escribiendo tal cual. Solo deja de estar a la vista. */}

      {/* LA OFERTA Y EL UPSELL, CON SUS CAJONES PROPIOS DE ESTE CANAL.
          Mismo trato que la intro y los seguimientos: lo que se escriba aquí
          manda sobre lo de la modalidad PARA ESTE CANAL, y vacío deja mandar a
          la modalidad. Lo que NO entra aquí son las reglas —el interruptor, los
          minutos, cuándo se dispara—: eso no es por canal, y con dos sitios no
          habría forma de saber cuál manda. */}
      {seccionAbierta === "orderbump" && (
        <VentanaDeProducto
          titulo={`Order Bump · ${meta.name}`}
          colorPorDefecto="blanco"
          onCerrar={() => setSeccionAbierta(null)}
        >
          <p className="mb-3 rounded-md border border-borde bg-relleno px-3 py-2 text-xs text-tinta-suave">
            La intro de la oferta <strong>de este canal</strong>. Con cajones
            encendidos aquí, mandan éstos; vacío, manda la de la pestaña Order
            Bump. El interruptor de la oferta y las reglas de cuándo se ofrece
            viven ahí, no aquí.
          </p>
          <CajonesDeIntro
            grupos={cajonesSembrados(
              editableContent.order_bump_intro_groups,
              cfg.order_bump.intro_groups,
              cfg.order_bump.intro
            )}
            onGrupos={(order_bump_intro_groups) =>
              updateContent({ order_bump_intro_groups })
            }
            icono={ICONO_DE_CAJON.orderBump}
            queEs="la oferta de este canal"
            respaldo={[]}
            snapshot={onSnapshot}
            editSnapshot={(clave) => onEdit(`channel_${channel}_${clave}`)}
            claveDeEdicion="ob_intro_canal"
            idPrefix={`channel_${channel}_ob_intro`}
            comboPrice={comboPreviewPrice}
            basicoPrice={basicoPreviewPrice}
            previewContext={previewContextFromConfig(cfg)}
            lugar="order_bump"
            biblioteca={cfg.biblioteca_de_intros ?? []}
            onBiblioteca={
              onCfgChange
                ? (biblioteca_de_intros) =>
                    onCfgChange({ ...cfg, biblioteca_de_intros })
                : undefined
            }
            pie={
              <>
          {/* Y AL FINAL, LA BURBUJA QUE PIDE ELEGIR.
              Es lo último que lee el cliente antes de decidir, así que se
              escribe donde se acaba de escribir la oferta. Las etiquetas de los
              dos botones NO están aquí: las pone el nombre del producto que
              esté sentado en cada puesto, y escribirlas a mano dejaría una
              pantalla diciendo un nombre y el bot mandando otro. */}
          <div className="mt-6 rounded-lg border border-borde bg-relleno p-4">
            <h3 className="mb-1 text-sm font-black uppercase tracking-tight text-tinta">
              Elección con botones
            </h3>
            <p className="mb-3 text-xs text-tinta-suave">
              El texto que pide elegir, <strong>de este canal</strong>. En
              blanco manda el de la pestaña Order Bump.
            </p>
            <div className="grid gap-4 lg:grid-cols-2">
              <div>
                <label className="mb-3 flex cursor-pointer items-center gap-2 text-sm font-medium text-tinta">
                  <input
                    type="checkbox"
                    checked={
                      editableContent.order_bump_use_buttons ??
                      cfg.order_bump.use_buttons === true
                    }
                    onChange={(e) => {
                      onSnapshot();
                      onEdit(`channel_${channel}_ob_use_buttons`);
                      updateContent({
                        order_bump_use_buttons: e.target.checked,
                      });
                    }}
                    className="h-5 w-5"
                  />
                  Mostrar la elección con botones
                </label>
                <label className="block text-sm font-medium text-tinta">
                  Texto que pide elegir
                </label>
                <textarea
                  rows={3}
                  value={
                    editableContent.order_bump_choice_prompt ??
                    ""
                  }
                  onChange={(e) => {
                    onEdit(`channel_${channel}_ob_choice_prompt`);
                    updateContent({
                      order_bump_choice_prompt: e.target.value,
                    });
                  }}
                  className="mt-1 w-full rounded border border-borde bg-tarjeta px-3 py-2 text-sm text-tinta"
                  placeholder={
                    cfg.order_bump.choice_prompt?.trim() ||
                    "Ej: 👇 Elige tu opción para pasarte los datos de pago"
                  }
                />
                <p className="mt-1 text-[11px] text-tinta-suave">
                  Vacío = sale el de la modalidad.
                </p>
              </div>
              <div className="lg:sticky lg:top-4 lg:self-start">
                <p className="mb-1 text-[11px] font-medium text-tinta-suave">
                  Vista previa (así le llegan los 2 botones al cliente)
                </p>
                {(editableContent.order_bump_use_buttons ??
                cfg.order_bump.use_buttons === true) ? (
                  <ButtonsPreview
                    prompt={
                      editableContent.order_bump_choice_prompt?.trim() ||
                      cfg.order_bump.choice_prompt ||
                      ""
                    }
                    buttons={[
                      {
                        label: previewContext.option1Name || "Opción 1",
                        method: "ob_combo",
                      },
                      {
                        label: previewContext.option2Name || "Opción 2",
                        method: "ob_basico",
                      },
                    ]}
                  />
                ) : (
                  <p className="rounded-md border border-borde bg-tarjeta px-3 py-4 text-center text-xs text-tinta-suave">
                    Botones apagados
                  </p>
                )}
              </div>
            </div>
          </div>
              </>
            }
          />
        </VentanaDeProducto>
      )}

      {seccionAbierta === "upsell" && (
        <VentanaDeProducto
          titulo={`Upsell · ${meta.name}`}
          colorPorDefecto="blanco"
          onCerrar={() => setSeccionAbierta(null)}
        >
          <p className="mb-3 rounded-md border border-borde bg-relleno px-3 py-2 text-xs text-tinta-suave">
            La intro del upsell <strong>de este canal</strong>. Con cajones
            encendidos aquí, mandan éstos; vacío, manda la de la pestaña Upsell.
            Los minutos y el interruptor de la etapa viven ahí.
          </p>
          <CajonesDeIntro
            grupos={cajonesSembrados(
              editableContent.upsell_intro_groups,
              cfg.upsell?.intro_groups,
              cfg.upsell?.intro
            )}
            onGrupos={(upsell_intro_groups) =>
              updateContent({ upsell_intro_groups })
            }
            icono={ICONO_DE_CAJON.upsell}
            queEs="el upsell de este canal"
            respaldo={[]}
            snapshot={onSnapshot}
            editSnapshot={(clave) => onEdit(`channel_${channel}_${clave}`)}
            claveDeEdicion="upsell_intro_canal"
            idPrefix={`channel_${channel}_upsell_intro`}
            priceSoles={precioDelUpsellEnElVisor(cfg)}
            comboPrice={comboPreviewPrice}
            basicoPrice={basicoPreviewPrice}
            previewContext={previewContextFromConfig(cfg)}
            lugar="upsell"
            biblioteca={cfg.biblioteca_de_intros ?? []}
            onBiblioteca={
              onCfgChange
                ? (biblioteca_de_intros) =>
                    onCfgChange({ ...cfg, biblioteca_de_intros })
                : undefined
            }
            pie={
              <>
          {/* Y AL FINAL, LA PREGUNTA QUE REMATA.
              La ÚLTIMA burbuja encendida es la que lleva los botones; las de
              antes salen tal cual, en orden. Es la misma regla del motor, no
              una del editor: si la última no es texto, no hay dónde colgarlos. */}
          <div className="mt-6 rounded-lg border border-borde bg-relleno p-4">
            <h3 className="mb-1 text-sm font-black uppercase tracking-tight text-tinta">
              Elección con botones
            </h3>
            <p className="mb-3 text-xs text-tinta-suave">
              La pregunta del final, <strong>de este canal</strong>: «¿deseas
              llevarlo?». En blanco manda la de la pestaña Upsell.
            </p>
            <StepEditorPreviewPair
              steps={preguntaDelUpsell}
              onChange={(upsell_pregunta_steps) =>
                updateContent({ upsell_pregunta_steps })
              }
              onSnapshot={onSnapshot}
              onEdit={(clave) => onEdit(`channel_${channel}_${clave}`)}
              idPrefix={`channel_${channel}_upsell_pregunta`}
              priceSoles={precioDelUpsellEnElVisor(cfg)}
              comboPrice={comboPreviewPrice}
              basicoPrice={basicoPreviewPrice}
              previewContext={previewContext}
              sinExpandir
            />

            <div className="mt-4 grid gap-4 lg:grid-cols-2">
              <div className="space-y-3">
                <label className="flex cursor-pointer items-center gap-3">
                  <input
                    type="checkbox"
                    checked={
                      editableContent.upsell_use_buttons ??
                      cfg.upsell?.use_buttons === true
                    }
                    onChange={(e) => {
                      onSnapshot();
                      onEdit(`channel_${channel}_upsell_use_buttons`);
                      updateContent({ upsell_use_buttons: e.target.checked });
                    }}
                    className="h-5 w-5"
                  />
                  <span className="text-sm text-tinta">
                    Preguntar con botones
                  </span>
                </label>
                <label className="block text-xs font-medium text-tinta-suave">
                  Botón «sí»
                  <input
                    value={editableContent.upsell_boton_si ?? ""}
                    onChange={(e) => {
                      onEdit(`channel_${channel}_upsell_boton_si`);
                      updateContent({ upsell_boton_si: e.target.value });
                    }}
                    className="mt-1 block w-full rounded border border-borde bg-tarjeta px-3 py-2 text-sm text-tinta"
                    placeholder={cfg.upsell?.boton_si?.trim() || "Sí, lo quiero"}
                  />
                </label>
                <label className="block text-xs font-medium text-tinta-suave">
                  Botón «no»
                  <input
                    value={editableContent.upsell_boton_no ?? ""}
                    onChange={(e) => {
                      onEdit(`channel_${channel}_upsell_boton_no`);
                      updateContent({ upsell_boton_no: e.target.value });
                    }}
                    className="mt-1 block w-full rounded border border-borde bg-tarjeta px-3 py-2 text-sm text-tinta"
                    placeholder={cfg.upsell?.boton_no?.trim() || "No, gracias"}
                  />
                </label>
                <label className="block text-xs font-medium text-tinta-suave">
                  Lo que se le dice si dice que NO (antes del regalo)
                  <textarea
                    rows={2}
                    value={editableContent.upsell_respuesta_rechazo ?? ""}
                    onChange={(e) => {
                      onEdit(`channel_${channel}_upsell_respuesta_rechazo`);
                      updateContent({
                        upsell_respuesta_rechazo: e.target.value,
                      });
                    }}
                    className="mt-1 w-full rounded border border-borde bg-tarjeta px-3 py-2 text-sm text-tinta"
                    placeholder={
                      cfg.upsell?.respuesta_rechazo?.trim() ||
                      "¡Perfecto! Que lo disfrutes muchísimo 🎉"
                    }
                  />
                </label>
                <p className="text-[11px] text-tinta-suave">
                  Cada campo en blanco deja mandar al de la modalidad.
                </p>
              </div>
              <div className="lg:sticky lg:top-4 lg:self-start">
                <p className="mb-1 text-[11px] font-medium text-tinta-suave">
                  Vista previa
                </p>
                {(editableContent.upsell_use_buttons ??
                cfg.upsell?.use_buttons === true) ? (
                  (() => {
                    // EL MISMO TEXTO QUE VA A LLEVAR EL BOTÓN, NO OTRO. Se mira
                    // lo mismo que mira el motor y en el mismo orden: la última
                    // burbuja encendida si es de texto, y si no, el respaldo.
                    const todas = preguntaDelUpsell;
                    const encendidas = todas.filter(
                      (paso) => paso.enabled !== false
                    );
                    const apagadaAProposito =
                      todas.length > 0 && encendidas.length === 0;
                    const ultima = encendidas[encendidas.length - 1];
                    const deLaUltima =
                      ultima && (ultima.type ?? "text") === "text"
                        ? (ultima.texts ?? []).find((t) => t.trim()) ?? ""
                        : "";
                    const crudo = apagadaAProposito
                      ? ""
                      : deLaUltima.trim() || (cfg.upsell?.pregunta ?? "");
                    const texto = resolvePreviewSpintax(
                      applyPreviewPrices(
                        crudo,
                        precioDelUpsellEnElVisor(cfg),
                        comboPreviewPrice,
                        basicoPreviewPrice,
                        previewContext
                      ),
                      0,
                      0
                    );
                    return (
                      <ButtonsPreview
                        prompt={texto}
                        buttons={[
                          {
                            label:
                              editableContent.upsell_boton_si?.trim() ||
                              cfg.upsell?.boton_si ||
                              "",
                            method: "upsell_si",
                          },
                          {
                            label:
                              editableContent.upsell_boton_no?.trim() ||
                              cfg.upsell?.boton_no ||
                              "",
                            method: "upsell_no",
                          },
                        ]}
                        ejemplo={[
                          { label: "Sí, lo quiero", method: "upsell_si" },
                          { label: "No, gracias", method: "upsell_no" },
                        ]}
                      />
                    );
                  })()
                ) : (
                  <p className="rounded-md border border-borde bg-tarjeta px-3 py-4 text-center text-xs text-tinta-suave">
                    Botones apagados
                  </p>
                )}
              </div>
            </div>
          </div>
              </>
            }
          />
        </VentanaDeProducto>
      )}

      {seccionAbierta === "entregas" && (
        <VentanaDeProducto
          titulo={`Entregas por modalidad · ${meta.name}`}
          colorPorDefecto="blanco"
          onCerrar={() => setSeccionAbierta(null)}
        >
          {connected ? (
            <ChatPreview
              steps={deliveryPreviewSteps ?? []}
              priceSoles={price}
              comboPrice={comboPreviewPrice}
              basicoPrice={basicoPreviewPrice}
              previewContext={previewContext}
            />
          ) : (
            <ChannelDeliveryEditor
              channel={channel}
              mode={mode}
              content={editableContent}
              onChange={updateContent}
              price={price}
              comboPrice={comboPreviewPrice}
              basicoPrice={basicoPreviewPrice}
              previewContext={previewContext}
              onSnapshot={onSnapshot}
              onEdit={onEdit}
              copyTargets={otherChannels}
              onCopySelected={(indexes, target) =>
                onCopySelectedBlocks?.("delivery_groups", indexes, target)
              }
              copyDisabled={disabled}
              cfg={cfg}
            />
          )}
        </VentanaDeProducto>
      )}

      {seccionAbierta === "postventa" && (
        <VentanaDeProducto
          titulo={`Postventa extra · ${meta.name}`}
          colorPorDefecto="blanco"
          onCerrar={() => setSeccionAbierta(null)}
        >
          {connected ? (
            <p className="text-sm text-neutral-500">
              WhatsApp usa la postventa central actual del bot.
            </p>
          ) : (
            <ChannelPostSaleEditorPanel
              channel={channel}
              value={editableContent.post_sale}
              onChange={(postSale) => updateContent({ post_sale: postSale })}
              onEdit={onEdit}
            />
          )}
        </VentanaDeProducto>
      )}

      {/* Solo en Facebook: los comentarios son de la página, no de WhatsApp
          ni de Instagram. */}
      {seccionAbierta === "comentarios" && channel === "messenger" && onCfgChange && (
        <VentanaDeProducto
          titulo={`Comentarios de Facebook · ${meta.name}`}
          colorPorDefecto="blanco"
          onCerrar={() => setSeccionAbierta(null)}
        >
          <CommentAutomationCard
            cfg={cfg}
            setCfg={onCfgChange}
            onEdit={onEdit}
            price={price}
            comboPrice={comboPreviewPrice}
            basicoPrice={basicoPreviewPrice}
            previewContext={previewContext}
            onSnapshot={onSnapshot}
          />
        </VentanaDeProducto>
      )}
      </div>
    </div>
  );
}

/** Las secciones de un canal, en el orden en que se trabajan. */
const SECCIONES_DEL_CANAL = [
  {
    clave: "intro" as const,
    icono: "📱",
    titulo: "Intro",
    detalle: "El saludo y la presentación, cajón por cajón",
  },
  {
    clave: "seguimientos" as const,
    icono: "📲",
    titulo: "Seguimientos",
    detalle: "Lo que se manda si no contesta, con sus variantes",
  },
  {
    clave: "orderbump" as const,
    icono: ICONO_DE_CAJON.orderBump,
    titulo: "Order Bump",
    detalle: "La oferta de dos opciones, antes de pagar",
  },
  {
    clave: "upsell" as const,
    icono: ICONO_DE_CAJON.upsell,
    titulo: "Upsell",
    detalle: "La segunda venta, después de entregar",
  },
  {
    clave: "entregas" as const,
    // LA MOTO, Y NO LA BOLSA. La bolsa pasó a ser el dibujo de la oferta de dos
    // opciones, y dos filas de la misma lista con el mismo dibujo es justo lo
    // que hace dudar de en cuál estás. Entregar es llevar algo a alguien.
    icono: "🛵",
    titulo: "Entregas por modalidad",
    detalle: "Lo que recibe al pagar, según lo que compró",
  },
  {
    clave: "postventa" as const,
    icono: "💬",
    titulo: "Postventa extra",
    detalle: "Lo que sigue después de entregar",
  },
  {
    clave: "comentarios" as const,
    icono: "📣",
    titulo: "Comentarios de Facebook",
    detalle: "Responder a quien comenta en la página",
  },
];

function ChannelCopySelector({
  label,
  items,
  targets,
  onCopy,
  onDelete,
  disabled = false,
}: {
  label: string;
  items: Array<{ enabled?: boolean }>;
  targets: ChannelKey[];
  onCopy: (indexes: number[], target: ChannelKey) => void;
  onDelete?: (indexes: number[]) => void;
  disabled?: boolean;
}) {
  const [selectedIndexes, setSelectedIndexes] = useState<number[]>([]);
  const [target, setTarget] = useState<ChannelKey>(targets[0] ?? "messenger");
  if (items.length === 0 || targets.length === 0 || disabled) return null;
  const allSelected = selectedIndexes.length === items.length;
  return (
    <div className="mt-3 flex flex-wrap items-center gap-2 rounded-md border border-sky-200 bg-sky-50 px-3 py-2">
      <span className="text-xs font-semibold text-sky-950">Copiar {label}:</span>
      {items.map((item, index) => (
        <label key={index} className="flex cursor-pointer items-center gap-1 text-xs text-sky-900">
          <input
            type="checkbox"
            checked={selectedIndexes.includes(index)}
            onChange={() =>
              setSelectedIndexes((current) =>
                current.includes(index)
                  ? current.filter((value) => value !== index)
                  : [...current, index]
              )
            }
            className="h-3.5 w-3.5 accent-sky-600"
          />
          {item.enabled === false ? `OFF ${index + 1}` : `#${index + 1}`}
        </label>
      ))}
      <button
        type="button"
        onClick={() => setSelectedIndexes(allSelected ? [] : items.map((_, index) => index))}
        className="rounded border border-sky-300 bg-tarjeta px-2 py-1 text-xs font-semibold text-sky-800 hover:bg-sky-100"
      >
        {allSelected ? "Quitar seleccion" : "Todos"}
      </button>
      <select
        value={target}
        onChange={(event) => setTarget(event.target.value as ChannelKey)}
        className="rounded border border-sky-300 bg-tarjeta px-2 py-1 text-xs"
      >
        {targets.map((channel) => (
          <option key={channel} value={channel}>{CHANNEL_PROTOTYPE_META[channel].name}</option>
        ))}
      </select>
      <button
        type="button"
        disabled={selectedIndexes.length === 0}
        onClick={() => {
          onCopy(selectedIndexes, target);
          setSelectedIndexes([]);
        }}
        className="rounded border border-sky-400 bg-sky-100 px-3 py-1 text-xs font-bold text-sky-900 hover:bg-sky-200 disabled:cursor-not-allowed disabled:opacity-40"
      >
        Copiar seleccionadas
      </button>
      {onDelete && <button
        type="button"
        disabled={selectedIndexes.length === 0}
        onClick={() => {
          if (!confirm(`Eliminar ${selectedIndexes.length} elemento(s) seleccionado(s)?`)) return;
          onDelete(selectedIndexes);
          setSelectedIndexes([]);
        }}
        className="rounded border border-red-300 bg-tarjeta px-3 py-1 text-xs font-bold text-red-700 hover:bg-red-50 disabled:cursor-not-allowed disabled:opacity-40"
      >
        Eliminar seleccionadas
      </button>}
      <span className="text-[11px] text-sky-800">Llegan OFF al destino.</span>
    </div>
  );
}

/**
 * EL AVISO DE QUE NO HAY NADA QUE ENVIAR.
 *
 * POR QUÉ HACE FALTA.
 *
 * Con todos los cajones apagados, el motor no manda nada. Eso es lo correcto
 * —callar es mejor que hablar del producto equivocado—, pero desde la pantalla
 * no se distingue de tenerlo bien: se ven los cajones ahí, con su contenido
 * escrito, y nada dice que ninguno va a salir.
 *
 * Antes esto ni se notaba, porque el motor se iba a buscar el contenido a la
 * modalidad y salía ALGO. Ese «algo» era la intro de otro producto. Ahora que
 * no presta nada de nadie, el silencio hay que avisarlo.
 *
 * Son dos avisos distintos a propósito: no tener ninguno y tenerlos todos
 * apagados se arreglan de formas distintas, y decir «agrega» a quien ya tiene
 * cinco escritos lo manda a crear un sexto en vez de encender uno.
 */
function AvisoDeNadaQueEnviar({
  cuantos,
  encendidos,
  queEs,
}: {
  cuantos: number;
  encendidos: number;
  /** «una intro» / «un seguimiento». Va dentro de la frase. */
  queEs: string;
}) {
  if (encendidos > 0) return null;
  return (
    <div className="rounded-xl border-2 border-red-300 bg-red-50 px-4 py-3 text-sm font-semibold text-red-900">
      {cuantos === 0 ? (
        <>⛔ No hay ninguno. Agrega {queEs}.</>
      ) : (
        <>⛔ Están todos apagados. Activa al menos {queEs}.</>
      )}
      <span className="mt-1 block text-xs font-normal">
        Así el bot no envía nada aquí. No toma el contenido de otro sitio: se
        queda callado.
      </span>
    </div>
  );
}

function ChannelIntroEditor({
  channel,
  content,
  onChange,
  price,
  comboPrice,
  basicoPrice,
  previewContext,
  onSnapshot,
  onEdit,
  registry,
  onRegistryChange,
  copyTargets,
  onCopySelected,
  copyDisabled = false,
}: {
  /* AQUÍ HABÍA DOS MANDOS PARA PARTIR LA LISTA, Y SE VAN.
   *
   * Uno dibujaba SOLO un cajón y el otro se saltaba los primeros. Existían para
   * sacar el primer cajón a su propia sección, la del mensaje suelto que iba por
   * delante de la intro. Ese mensaje ya no existe.
   *
   * Se quitan y no se dejan «por si acaso»: mientras estén, alguien puede volver
   * a esconder el primer cajón sin darse cuenta de que el motor lo trataba
   * distinto, que es exactamente lo que pasó. */
  channel: ChannelKey;
  content: ChannelContentEditor;
  onChange: (patch: Partial<ChannelContentEditor>) => void;
  price: number;
  comboPrice: number;
  basicoPrice: number;
  previewContext: PreviewContext;
  onSnapshot: () => void;
  onEdit: (key: string) => void;
  registry: AdRegistryEntry[];
  onRegistryChange: (entries: AdRegistryEntry[]) => void;
  copyTargets: ChannelKey[];
  onCopySelected: (indexes: number[], target: ChannelKey) => void;
  copyDisabled?: boolean;
}) {
  const groups = content.intro_groups ?? [];
  const [selectedIndexes, setSelectedIndexes] = useState<number[]>([]);
  const [copyTarget, setCopyTarget] = useState<ChannelKey>(copyTargets[0] ?? "messenger");
  const toggleSelected = (index: number) => {
    setSelectedIndexes((current) =>
      current.includes(index)
        ? current.filter((item) => item !== index)
        : [...current, index]
    );
  };
  const selectAll = () => {
    setSelectedIndexes(
      selectedIndexes.length === groups.length ? [] : groups.map((_, index) => index)
    );
  };
  const updateGroup = (index: number, patch: Partial<ChannelIntroGroupEditor>) => {
    onChange({
      intro_groups: groups.map((group, i) =>
        i === index ? { ...group, ...patch } : group
      ),
    });
  };
  const duplicateGroup = (index: number) => {
    // El nombre PRIMERO: si cancela, no se duplica ni se toca el historial.
    const nombre = nombreParaLaCopia(groups[index]?.name);
    if (nombre === null) return;
    onSnapshot();
    const copy = cloneJson(groups[index]);
    // Abre la copia (queda en index + 1) para caer dentro de ella.
    abrirCajonDuplicado(
      `channel_${channel}_own_intro`,
      index + 1,
      groups.length
    );
    onChange({
      intro_groups: [
        ...groups.slice(0, index + 1),
        { ...copy, name: nombre },
        ...groups.slice(index + 1),
      ],
    });
  };
  const moveGroup = (index: number, dir: -1 | 1) => {
    const target = index + dir;
    if (target < 0 || target >= groups.length) return;
    onSnapshot();
    keepMovedCollapsibleOpen(`channel_${channel}_own_intro`, index, target, groups.length);
    onChange({ intro_groups: moveItem(groups, index, target) });
  };
  const removeGroup = (index: number) => {
    if (!confirm("Quitar este cajon de intro?")) return;
    onSnapshot();
    onChange({ intro_groups: groups.filter((_, i) => i !== index) });
  };
  const addGroup = () => {
    onSnapshot();
    onChange({
      intro_groups: [
        ...groups,
        {
          name: `Intro ${groups.length + 1}`,
          enabled: true,
          weight: 1,
          adName: "",
          adId: "",
          adKeys: [],
          skipAskName: false,
          steps: [emptyStep()],
        },
      ],
    });
  };
  // Cajones que se dibujan aqui. Los indices siguen siendo los reales, asi
  // que mover, duplicar y borrar siguen apuntando al cajon correcto.
  const visibles = conSuIndice(groups);
  const soloUno = false;
  return (
    // AQUÍ ESTUVO LA MANO QUE SALUDA, Y FUE MALA IDEA.
    //
    // Se puso porque esto es la intro, y el saludo es lo primero que se manda.
    // Pero el dibujo de un cajón no está para ilustrar lo que dice dentro: está
    // para decir DÓNDE ESTÁS. Y esta lista se edita dentro de un canal, así que
    // lo que orienta es el canal, no el contenido.
    //
    // El celular es el mismo de la fila «Intro» de Canales, de donde se entra.
    <TonoDeLaSeccion.Provider value={{ tono: "cielo", icono: "📱" }}>
    <div className="space-y-3">
      {/* Solo en la lista entera. Dibujando un cajón suelto, el aviso hablaría
          de algo que no se está viendo. */}
      {!soloUno && (
        <AvisoDeNadaQueEnviar
          cuantos={groups.length}
          encendidos={groups.filter((g) => g.enabled !== false).length}
          queEs="una intro"
        />
      )}
      {!soloUno && !copyDisabled && copyTargets.length > 0 && groups.length > 0 && (
        <div className="flex flex-wrap items-center gap-2 rounded-md border border-sky-200 bg-sky-50 px-3 py-2">
          <span className="text-xs font-semibold text-sky-950">
            Selecciona cajones de intro para copiar:
          </span>
          <button
            type="button"
            onClick={selectAll}
            className="rounded border border-sky-300 bg-tarjeta px-2 py-1 text-xs font-semibold text-sky-800 hover:bg-sky-100"
          >
            {selectedIndexes.length === groups.length ? "Quitar seleccion" : "Seleccionar todos"}
          </button>
          <select
            value={copyTarget}
            onChange={(event) => setCopyTarget(event.target.value as ChannelKey)}
            className="rounded border border-sky-300 bg-tarjeta px-2 py-1 text-xs"
          >
            {copyTargets.map((target) => (
              <option key={target} value={target}>
                {CHANNEL_PROTOTYPE_META[target].name}
              </option>
            ))}
          </select>
          <button
            type="button"
            disabled={selectedIndexes.length === 0}
            onClick={() => {
              onCopySelected(selectedIndexes, copyTarget);
              setSelectedIndexes([]);
            }}
            className="rounded border border-sky-400 bg-sky-100 px-3 py-1 text-xs font-bold text-sky-900 hover:bg-sky-200 disabled:cursor-not-allowed disabled:opacity-40"
          >
            Copiar seleccionadas
          </button>
          <button
            type="button"
            disabled={selectedIndexes.length === 0}
            onClick={() => {
              if (!confirm(`Eliminar ${selectedIndexes.length} intro(s) seleccionada(s)?`)) return;
              onSnapshot();
              onChange({ intro_groups: groups.filter((_, index) => !selectedIndexes.includes(index)) });
              setSelectedIndexes([]);
            }}
            className="rounded border border-red-300 bg-tarjeta px-3 py-1 text-xs font-bold text-red-700 hover:bg-red-50 disabled:cursor-not-allowed disabled:opacity-40"
          >
            Eliminar seleccionadas
          </button>
        </div>
      )}
      {visibles.map(({ item: group, index }) => (
        <Collapsible
          key={`channel-${channel}-intro-${index}`}
          // LA BANDERA SE VE EN LA FILA, SIN ABRIR EL CAJÓN.
          //
          // Lo pidió el dueño el 24/09/2026 con una captura y una flecha roja
          // señalando esta fila. Y hacía falta: lo estaba resolviendo a mano,
          // escribiendo el emoji DENTRO del nombre —«🇵🇪 QUIMICA EN ACCION -
          // PERU»—. Ahora el nombre vuelve a ser solo el nombre.
          //
          // VA DELANTE DEL NOMBRE porque es lo que se busca al recorrer la lista
          // con la vista: primero de quién es, después cómo se llama.
          // LA BANDERA YA NO VA PEGADA AL NOMBRE: la elige y la enseña su pastilla, aquí
          // al lado. Lo pidió el dueño el 02/10/2026 —«así el logo de la bandera no queda
          // al inicio del nombre»— y en su captura se ve por qué: «PRUEBA LINEAL PERU»
          // caía en dos líneas.
          title={`${group.enabled === false ? "OFF - " : ""}${
            group.name || "Ponle un título al cajón"
          }`}
          tituloDeRelleno={!group.name?.trim()}
          titleKey={`channel_${channel}_own_intro_${index}`}
          headerActions={
            <>
              {/* LA BANDERA, A LA IZQUIERDA DE LA SEMIMODALIDAD.
                  AQUÍ ES DONDE ÉL LAS MIRA, y costó tres intentos encontrarlo. Su camino,
                  dictado el 02/10/2026: «Menú canales, pop up master INTRO… al abrirse el
                  pop up INTRO · WHATSAPP, ahí dentro están las sub pestañas… ahí dice por
                  título 🇵🇪 PRUEBA LINEAL PERU». El «cajón master» que él dijo NO tocar es
                  la baldosa de fuera; la bandera va en los cajones de DENTRO. */}
              <PastillaDePais
                seleccionados={group.paises ?? []}
                onCambiar={(paises) => {
                  onEdit(`channel_${channel}_intro_${index}_paises`);
                  updateGroup(index, { paises });
                }}
              />
              <AvisoSinBandera
                visible={leFaltaLaBandera({
                  paises: group.paises,
                  routingEnabled: group.paisRoutingEnabled,
                  apagada: group.enabled === false,
                })}
              />
              {/* LA ETIQUETA, EN LA FACHADA. Ver `PastillaDeSemimodalidad`. */}
              <PastillaDeSemimodalidad
                valor={group.semimodalidad}
                onCambiar={(siguiente) => {
                  onEdit(`channel_${channel}_intro_${index}_semimodalidad`);
                  updateGroup(index, { semimodalidad: siguiente });
                }}
              />
              <PastillaDeTiendas
                valor={group.tiendas}
                onCambiar={(siguiente) => {
                  onEdit(`channel_${channel}_intro_${index}_tiendas`);
                  updateGroup(index, { tiendas: siguiente });
                }}
              />
              <CirculoDeEncendido
                encendido={group.enabled !== false}
                queEs={`la Intro ${index + 1} de este canal`}
                onCambiar={() => {
                  onEdit(`channel_${channel}_intro_${index}_enabled`);
                  updateGroup(index, { enabled: group.enabled === false });
                }}
              />
              {/* SOLO EL CHECK, Y VERDE AL MARCARLO.
                  Llevaba la palabra «Copiar» al lado, y en una fila con otros
                  cuatro controles esa palabra no decía nada que la casilla no
                  dijera ya. El verde es lo que hace falta: hay que ver de un
                  vistazo cuáles están marcados antes de copiar. */}
              <label
                title="Seleccionar este cajón para copiarlo a otro canal"
                className="flex cursor-pointer items-center rounded p-1 hover:bg-black/5"
                onClick={(event) => event.stopPropagation()}
              >
                <input
                  type="checkbox"
                  checked={selectedIndexes.includes(index)}
                  onChange={() => toggleSelected(index)}
                  disabled={copyDisabled}
                  className="h-4 w-4 accent-emerald-600"
                />
                <span className="sr-only">Seleccionar para copiar</span>
              </label>
              {/* SUBIR, BAJAR Y MOVER SE QUEDAN SIN PALABRA — y esto DESHACE una
                  decisión anterior, así que queda contado por qué.
                  ANTES: se habían probado con el símbolo solo y no salió bien.
                  Pero el motivo era el DIBUJO, no la palabra: se usaban «⌃» y
                  «⌄», que parecen pareja y no lo son —ningún tipo de letra los
                  dibuja igual, el de bajar salía más fino y más corto—.
                  AHORA se usan «↑» y «↓», que sí son pareja de verdad y se
                  dibujan iguales en cualquier tipo de letra. El problema de
                  entonces no puede volver.
                  Y LO PIDIÓ EL DUEÑO el 30/09/2026, con un motivo de espacio:
                  la etiqueta de semimodalidad entra en esta misma fila, «hay que
                  minimizar espacio... quitar el texto y que solo queden las
                  flechas». El nombre de cada botón sigue saliendo al pasar el
                  ratón, y va en `aria-label` para quien no ve la pantalla.
                  La papelera se queda en símbolo, como siempre: es universal y
                  conviene que NO lleve palabra, porque se pulsa por error menos
                  si no se lee «Quitar» de pasada. */}
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  moveGroup(index, -1);
                }}
                disabled={index === 0}
                title="Subir este cajón"
                aria-label="Subir este cajón"
                className="rounded border border-sky-200 bg-sky-50 px-2 py-1 text-xs font-bold text-sky-700 hover:bg-sky-100 disabled:opacity-30"
              >
                ↑
              </button>
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  moveGroup(index, 1);
                }}
                disabled={index === groups.length - 1}
                title="Bajar este cajón"
                aria-label="Bajar este cajón"
                className="rounded border border-sky-200 bg-sky-50 px-2 py-1 text-xs font-bold text-sky-700 hover:bg-sky-100 disabled:opacity-30"
              >
                ↓
              </button>
              <button
                type="button"
                draggable
                onClick={(e) => e.stopPropagation()}
                onDragStart={(e) => {
                  e.stopPropagation();
                  e.dataTransfer.effectAllowed = "move";
                  e.dataTransfer.setData(
                    "text/plain",
                    `channel-intro:${channel}:${index}`
                  );
                }}
                title="Arrastrar para moverlo de sitio"
                aria-label="Arrastrar para moverlo de sitio"
                className="cursor-grab rounded border border-sky-300 bg-tarjeta px-2 py-1 text-xs font-bold text-sky-700 active:cursor-grabbing"
              >
                ⋮⋮
              </button>
              {/* DUPLICAR, EN LA FILA CERRADA. Lo pidió el dueño el 30/09/2026:
                  «para duplicarlo como está hoy tengo que entrar dentro de la
                  pestaña; mejor que lo tenga en la fachada como sus demás
                  botones».
                  Llama al MISMO `duplicateGroup` que el botón de dentro, así que
                  hace exactamente lo mismo: copia el cajón entero —burbujas,
                  bandera, anuncios y etiqueta— y pregunta el nombre antes. */}
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  duplicateGroup(index);
                }}
                title="Duplicar este cajón"
                aria-label="Duplicar este cajón"
                className="rounded border border-sky-200 bg-sky-50 px-2 py-1 text-xs font-bold text-sky-700 hover:bg-sky-100"
              >
                ⧉
              </button>
              {/* LA PAPELERA, A LA DERECHA Y LA ÚLTIMA.
                  Estaba dentro del cajón, escrita como «Quitar», y había que
                  abrirlo para llegar a ella. Aquí va donde se espera, y al
                  final: lo que borra nunca se pone al lado de lo que se pulsa
                  a menudo. */}
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  removeGroup(index);
                }}
                title="Quitar este cajón"
                aria-label="Quitar este cajón"
                className="rounded border border-red-200 bg-tarjeta px-2 py-1 text-xs text-red-600 hover:bg-red-50"
              >
                🗑️
              </button>
            </>
          }
          onDragOver={(e) => {
            e.preventDefault();
          }}
          onDrop={(e) => {
            e.preventDefault();
            const raw = e.dataTransfer.getData("text/plain");
            const [kind, dragChannel, rawIndex] = raw.split(":");
            if (kind !== "channel-intro" || dragChannel !== channel) return;
            const from = Number(rawIndex);
            if (!Number.isFinite(from)) return;
            if (from === index) return;
            onSnapshot();
            keepMovedCollapsibleOpen(`channel_${channel}_own_intro`, from, index, groups.length);
            onChange({ intro_groups: moveItem(groups, from, index) });
          }}
          // Y LA FACHADA EN ROJO SI LE FALTA LA BANDERA. En el canal el interruptor se
          // llama `paisRoutingEnabled` —el resto del proyecto lo escribe con guiones
          // bajos— así que se lee de su nombre, no del de al lado.
          titleClassName={bordeSinBandera(
            leFaltaLaBandera({
              paises: group.paises,
              routingEnabled: group.paisRoutingEnabled,
              apagada: group.enabled === false,
            }),
            group.enabled === false
              ? "border-neutral-500 bg-neutral-300 text-neutral-900"
              : undefined
          )}
          inactivo={group.enabled === false}
          bodyClassName={group.enabled === false ? "bg-neutral-300" : undefined}
          defaultOpen={index === 0}
        >
          <div className="mb-3 flex flex-wrap items-center gap-2">
            <input
              value={group.name}
              onChange={(e) => {
                onEdit(`channel_${channel}_intro_${index}_name`);
                updateGroup(index, { name: e.target.value });
              }}
              className="min-w-48 rounded-md border border-neutral-300 bg-tarjeta px-2 py-1 text-sm"
            />
            <button
              type="button"
              onClick={() => {
                onEdit(`channel_${channel}_intro_${index}_enabled`);
                updateGroup(index, { enabled: group.enabled === false });
              }}
              className={`rounded border px-2 py-1 text-xs font-semibold ${
                group.enabled === false
                  ? "border-neutral-300 bg-neutral-100 text-neutral-400"
                  : "border-emerald-300 bg-emerald-50 text-emerald-700"
              }`}
            >
              {group.enabled === false ? "OFF" : "ON"}
            </button>
            <label className="flex items-center gap-2 rounded-md border border-neutral-300 bg-tarjeta px-2 py-1 text-xs text-neutral-700">
              <span className="font-medium">Peso</span>
              <input
                type="text"
                inputMode="numeric"
                pattern="[0-9]*"
                value={group.weight ?? 1}
                onChange={(e) => {
                  onEdit(`channel_${channel}_intro_${index}_weight`);
                  const digits = e.target.value.replace(/\D/g, "");
                  updateGroup(index, {
                    weight: Math.max(1, Math.floor(Number(digits) || 1)),
                  });
                }}
                className="w-14 rounded border border-neutral-300 px-2 py-1 text-right text-xs font-semibold text-neutral-900 focus:border-emerald-500 focus:outline-none focus:ring-1 focus:ring-emerald-500"
                title="Peso de prioridad para elegir esta intro"
              />
              <span className="font-semibold text-neutral-500">%</span>
            </label>
            {/* AQUÍ HABÍA UN «INICIO INMEDIATO: ON/OFF», Y SE RETIRA.
                Servía para saltarse la burbuja del saludo inicial y lanzar esta
                intro de una. Esa burbuja ya no existe en el canal, así que el
                interruptor decidía sobre algo que no está: encendido y apagado
                hacían lo mismo.
                Lo que SÍ sigue esperando es la burbuja con cuadritos de
                decisión, que es donde hay una pregunta de verdad. */}
            {/* AQUÍ HABÍA UN «↑ Subir cajón» Y UN «↓ Bajar cajón», Y SE RETIRAN.
                Hacían exactamente lo mismo que las flechas de la cabecera, dos
                filas más arriba. Dos botones para lo mismo, separados, y el de
                abajo colgando solo en su renglón. */}
            <button
              type="button"
              onClick={() => duplicateGroup(index)}
              className="rounded border border-neutral-300 bg-tarjeta px-2 py-1 text-xs text-neutral-600"
            >
              Duplicar cajón
            </button>
            {/* EL «QUITAR» SE FUE A LA CABECERA, COMO PAPELERA. Tenerlo aquí
                dentro obligaba a abrir el cajón para borrarlo, y dejaba dos
                sitios distintos para lo mismo. */}
          </div>
          {/* Los campos sueltos de "Nombre del AD" e "ID del AD" se quitaron:
              los anuncios se asocian con etiquetas, que es lo de abajo. Pero el
              ID guardado SIGUE contando para la atribucion (se junta con los de
              las etiquetas al guardar), asi que si un cajon todavia lo tiene
              escrito se muestra aqui para poder limpiarlo — nunca oculto y
              activo a la vez. */}
          {(group.adName?.trim() || group.adId?.trim()) && (
            <div className="mb-3 flex flex-wrap items-center gap-2 rounded-md border border-amber-300 bg-amber-50 px-3 py-2">
              <span className="text-xs text-amber-900">
                Este cajón conserva un anuncio escrito a mano:
                {group.adName?.trim() ? ` ${group.adName.trim()}` : ""}
                {group.adId?.trim() ? ` (ID ${group.adId.trim()})` : ""}. Sigue
                contando para la atribución.
              </span>
              <button
                type="button"
                onClick={() => {
                  onEdit(`channel_${channel}_intro_${index}_ad_legacy`);
                  updateGroup(index, { adName: "", adId: "" });
                }}
                className="rounded border border-amber-400 bg-tarjeta px-2 py-1 text-xs font-semibold text-amber-800 hover:bg-amber-100"
              >
                Quitarlo
              </button>
            </div>
          )}
          <FilaDeEtiquetas>
            {/* LA BANDERA VA EN TODAS, TAMBIÉN EN LA PRIMERA.
                La de anuncios se salta la primera porque es la intro por
                defecto. Con la bandera no hace falta esa excepción: si marcas
                todas y a un cliente no le toca ninguna, el sorteo sigue como si
                no hubiera banderas. Nadie se queda sin intro.
                Por eso aquí la fila puede quedarse con una sola caja: en la
                primera intro, país ocupa el ancho entero. */}
            <BanderaTagPicker
              seleccionados={group.paises ?? []}
              routingEnabled={group.paisRoutingEnabled}
              onRoutingEnabledChange={(paisRoutingEnabled) => {
                onEdit(`channel_${channel}_intro_${index}_pais_routing`);
                updateGroup(index, { paisRoutingEnabled });
              }}
              onChange={(paises) => {
                onEdit(`channel_${channel}_intro_${index}_paises`);
                updateGroup(index, { paises });
              }}
            />
            {index > 0 && (
              <AdTagPicker
                registry={registry}
                selectedKeys={group.adKeys ?? []}
                routingEnabled={group.adRoutingEnabled}
                onRoutingEnabledChange={(adRoutingEnabled) => {
                  onEdit(`channel_${channel}_intro_${index}_routing`);
                  updateGroup(index, { adRoutingEnabled });
                }}
                onChange={(adKeys) => {
                  onEdit(`channel_${channel}_intro_${index}_ads`);
                  updateGroup(index, { adKeys });
                }}
                onRegistryChange={onRegistryChange}
              />
            )}
          </FilaDeEtiquetas>
          <StepEditorPreviewPair
            steps={group.steps}
            onChange={(steps) => updateGroup(index, { steps })}
            onSnapshot={onSnapshot}
            onEdit={onEdit}
            idPrefix={`channel_${channel}_intro_${index}`}
            priceSoles={price}
            comboPrice={comboPrice}
            basicoPrice={basicoPrice}
            previewContext={previewContext}
            className="lg:grid-cols-1 xl:grid-cols-[minmax(0,1fr)_minmax(220px,280px)]"
          />
        </Collapsible>
      ))}
      {!soloUno && (
        <button
          type="button"
          onClick={addGroup}
          className="w-full rounded-md border-2 border-dashed border-neutral-300 py-2 text-sm text-neutral-500 hover:border-emerald-400 hover:text-emerald-600"
        >
          Agregar cajon de intro
        </button>
      )}
    </div>
    </TonoDeLaSeccion.Provider>
  );
}

function ChannelFollowupsEditor({
  channel,
  content,
  onChange,
  price,
  comboPrice,
  basicoPrice,
  previewStagePrices,
  previewContext,
  onSnapshot,
  onEdit,
  registry,
  onRegistryChange,
  copyTargets,
  onCopySelected,
  copyDisabled = false,
}: {
  channel: ChannelKey;
  content: ChannelContentEditor;
  onChange: (patch: Partial<ChannelContentEditor>) => void;
  price: number;
  comboPrice: number;
  basicoPrice: number;
  previewStagePrices: (followupIndex: number) => { price: number; combo: number; basico: number };
  previewContext: PreviewContext;
  onSnapshot: () => void;
  onEdit: (key: string) => void;
  registry: AdRegistryEntry[];
  onRegistryChange: (entries: AdRegistryEntry[]) => void;
  copyTargets: ChannelKey[];
  onCopySelected: (indexes: number[], target: ChannelKey) => void;
  copyDisabled?: boolean;
}) {
  const followups = content.followups ?? [];
  const [selectedIndexes, setSelectedIndexes] = useState<number[]>([]);
  const [copyTarget, setCopyTarget] = useState<ChannelKey>(copyTargets[0] ?? "messenger");
  const toggleSelected = (index: number) => {
    setSelectedIndexes((current) =>
      current.includes(index)
        ? current.filter((item) => item !== index)
        : [...current, index]
    );
  };
  const selectAll = () => {
    setSelectedIndexes(
      selectedIndexes.length === followups.length
        ? []
        : followups.map((_, index) => index)
    );
  };
  const updateFollowup = (index: number, patch: Partial<EditorFollowup>) => {
    onChange({
      followups: followups.map((followup, i) =>
        i === index ? { ...followup, ...patch } : followup
      ),
    });
  };
  const duplicateFollowup = (index: number) => {
    // El nombre PRIMERO, y la copia se abre al aceptar. Ver `nombreParaLaCopia`.
    const nombre = nombreParaLaCopia(followups[index]?.name);
    if (nombre === null) return;
    onSnapshot();
    const copy = cloneJson(followups[index]);
    abrirCajonDuplicado(
      `channel_${channel}_own_followup`,
      index + 1,
      followups.length
    );
    onChange({
      followups: [
        ...followups.slice(0, index + 1),
        { ...copy, name: nombre },
        ...followups.slice(index + 1),
      ],
    });
  };
  const moveFollowup = (index: number, dir: -1 | 1) => {
    const target = index + dir;
    if (target < 0 || target >= followups.length) return;
    onSnapshot();
    keepMovedCollapsibleOpen(`channel_${channel}_own_followup`, index, target, followups.length);
    onChange({ followups: moveItem(followups, index, target) });
  };
  const removeFollowup = (index: number) => {
    if (!confirm("Quitar este seguimiento?")) return;
    onSnapshot();
    onChange({ followups: followups.filter((_, i) => i !== index) });
  };
  const addFollowup = () => {
    onSnapshot();
    onChange({
      followups: [
        ...followups,
        {
          name: `Seguimiento ${followups.length + 1}`,
          delay_minutes_from_first_message: 0,
          enabled: true,
          steps: [emptyStep()],
          variants: [],
        },
      ],
    });
  };
  const updateVariant = (
    followupIndex: number,
    variantIndex: number,
    patch: Partial<EditorFollowupVariant>
  ) => {
    const followup = followups[followupIndex];
    const variants = followup.variants ?? [];
    updateFollowup(followupIndex, {
      variants: variants.map((variant, i) =>
        i === variantIndex ? { ...variant, ...patch } : variant
      ),
    });
  };
  const addVariant = (followupIndex: number) => {
    onSnapshot();
    const followup = followups[followupIndex];
    const variants = followup.variants ?? [];
    updateFollowup(followupIndex, {
      variants: [
        ...variants,
        {
          // Ya no se llama «Variante»: aquí todos son cajones hermanos y ese
          // nombre venía de cuando había un original del que variar.
          name: `Cajón ${variants.length + 1}`,
          enabled: true,
          // Y nace en blanco. Antes copiaba el texto del principal, que era
          // el punto de partida natural cuando existía; hoy el principal es el
          // primer cajón de esta misma lista y copiarlo es duplicarlo.
          steps: [emptyStep()],
        },
      ],
    });
  };
  const duplicateVariant = (followupIndex: number, variantIndex: number) => {
    const variantes = followups[followupIndex]?.variants ?? [];
    // El nombre PRIMERO, y la copia se abre al aceptar. Ver `nombreParaLaCopia`.
    const nombre = nombreParaLaCopia(variantes[variantIndex]?.name);
    if (nombre === null) return;
    onSnapshot();
    const copy = cloneJson(variantes[variantIndex]);
    abrirCajonDuplicado(
      `channel_${channel}_followup_${followupIndex}_variant`,
      variantIndex + 1,
      variantes.length
    );
    updateFollowup(followupIndex, {
      variants: [
        ...variantes.slice(0, variantIndex + 1),
        { ...copy, name: nombre },
        ...variantes.slice(variantIndex + 1),
      ],
    });
  };
  const removeVariant = (followupIndex: number, variantIndex: number) => {
    if (!confirm("Quitar esta variante de seguimiento?")) return;
    onSnapshot();
    const variants = followups[followupIndex]?.variants ?? [];
    updateFollowup(followupIndex, {
      variants: variants.filter((_, i) => i !== variantIndex),
    });
  };
  // AQUÍ VIVÍA `cloneMainIntoVariant`, Y SE VA CON EL PRINCIPAL.
  //
  // Servía para traer a una variante el texto de «Mensajes principales», que era
  // una pestaña aparte. Desde el 15 de septiembre de 2026 el principal es el
  // PRIMER CAJÓN de la misma lista, así que copiarlo es duplicarlo o usar el
  // «Traer texto de…» de al lado, que ya sirve para cualquiera de los hermanos.
  const cloneVariantIntoVariant = (
    followupIndex: number,
    sourceVariantIndex: number,
    targetVariantIndex: number
  ) => {
    const variants = followups[followupIndex]?.variants ?? [];
    const source = variants[sourceVariantIndex];
    const target = variants[targetVariantIndex];
    const hasText = (target?.steps ?? []).some(
      (step) =>
        step.drive_url.trim() ||
        step.texts.some((text) => text.trim().length > 0)
    );
    if (
      hasText &&
      !confirm(
        `Al clonar desde variante ${sourceVariantIndex + 1} reemplazaras el texto de esta variante. ¿Continuar?`
      )
    ) {
      return;
    }
    onSnapshot();
    updateVariant(followupIndex, targetVariantIndex, {
      steps: cloneJson(source?.steps ?? [emptyStep()]),
    });
  };

  return (
    // EL DIBUJO DE LOS CAJONES DE AQUÍ ES EL DE SEGUIMIENTOS, NO EL DEL CANAL.
    //
    // Un cajón sin emoji en el título hereda el de la pestaña, y esta lista se
    // dibuja DENTRO de Canales: todos los seguimientos salían con el celular de
    // Canales, igual que las intros y que las entregas. Tres listas distintas
    // con el mismo dibujo.
    //
    // Se cambia solo para lo de dentro, que es lo que hace el contexto.
    <TonoDeLaSeccion.Provider value={{ tono: "cielo", icono: "📲" }}>
    <div className="space-y-3">
      <AvisoDeNadaQueEnviar
        cuantos={followups.length}
        encendidos={followups.filter((f) => f.enabled !== false).length}
        queEs="un seguimiento"
      />
      {!copyDisabled && copyTargets.length > 0 && followups.length > 0 && (
        <div className="flex flex-wrap items-center gap-2 rounded-md border border-sky-200 bg-sky-50 px-3 py-2">
          <span className="text-xs font-semibold text-sky-950">
            Selecciona seguimientos para copiar:
          </span>
          <button
            type="button"
            onClick={selectAll}
            className="rounded border border-sky-300 bg-tarjeta px-2 py-1 text-xs font-semibold text-sky-800 hover:bg-sky-100"
          >
            {selectedIndexes.length === followups.length ? "Quitar seleccion" : "Seleccionar todos"}
          </button>
          <select
            value={copyTarget}
            onChange={(event) => setCopyTarget(event.target.value as ChannelKey)}
            className="rounded border border-sky-300 bg-tarjeta px-2 py-1 text-xs"
          >
            {copyTargets.map((target) => (
              <option key={target} value={target}>
                {CHANNEL_PROTOTYPE_META[target].name}
              </option>
            ))}
          </select>
          <button
            type="button"
            disabled={selectedIndexes.length === 0}
            onClick={() => {
              onCopySelected(selectedIndexes, copyTarget);
              setSelectedIndexes([]);
            }}
            className="rounded border border-sky-400 bg-sky-100 px-3 py-1 text-xs font-bold text-sky-900 hover:bg-sky-200 disabled:cursor-not-allowed disabled:opacity-40"
          >
            Copiar seleccionadas
          </button>
          <button
            type="button"
            disabled={selectedIndexes.length === 0}
            onClick={() => {
              if (!confirm(`Eliminar ${selectedIndexes.length} seguimiento(s) seleccionado(s)?`)) return;
              onSnapshot();
              onChange({ followups: followups.filter((_, index) => !selectedIndexes.includes(index)) });
              setSelectedIndexes([]);
            }}
            className="rounded border border-red-300 bg-tarjeta px-3 py-1 text-xs font-bold text-red-700 hover:bg-red-50 disabled:cursor-not-allowed disabled:opacity-40"
          >
            Eliminar seleccionadas
          </button>
        </div>
      )}
      {conSuIndice(followups).map(({ item: followup, index }) => (
        <Collapsible
          // LA LLAVE NO PUEDE LLEVAR EL NOMBRE, Y AQUÍ ESTABA EL FALLO.
          //
          // React usa la llave para saber si un panel sigue siendo el mismo.
          // Con el nombre dentro, escribir o borrar UNA letra cambiaba la llave:
          // React daba el panel por otro, tiraba el que había y construía uno
          // nuevo. El campo se quedaba sin cursor en cada tecla, así que borrar
          // un título era hacer clic, borrar una letra, volver a hacer clic.
          //
          // La posición basta para distinguirlos y no cambia al escribir.
          key={`channel-${channel}-own-followup-${index}`}
          // LA BANDERA SE VE EN LA FILA, igual que en los cajones de intro. Sus
          // banderas son las de sus variantes: el seguimiento no las lleva en el
          // canal —ahí el etiquetado vive en la variante, como el de anuncios—.
          title={`${followup.enabled === false ? "OFF - " : ""}${
            banderasDeLasVariantes(followup)
              ? `${banderasDeLasVariantes(followup)} `
              : ""
          }${followup.name || "Ponle un título al cajón"}`}
          tituloDeRelleno={!followup.name?.trim()}
          titleKey={`channel_${channel}_own_followup_${index}`}
          // CADA SEGUIMIENTO, EN SU PROPIA VENTANA.
          //
          // Abierto crecía hacia abajo y empujaba a los otros dos: se estaba
          // editando el 1 y por debajo seguían asomando el 2 y el 3, con sus
          // mensajes y sus variantes. En un cajón con dos listas dentro eso es
          // mucha pantalla y es fácil escribir en el que no era.
          //
          // El dueño lo pidió el 15 de septiembre de 2026: «si toco seguimiento
          // 1, solo veo el contenido del seguimiento 1, ya no veo el 2 ni el 3».
          //
          // No es una pantalla nueva: es el mismo interruptor que ya usan los
          // cajones de la oferta y del upsell. La barra se queda EXACTAMENTE
          // igual —mismo recuadro, mismos botones, mismo sitio— y lo único que
          // cambia es a dónde va el contenido.
          enVentana
          headerActions={
            <>
              {/* LA ETIQUETA DEL SEGUIMIENTO ENTERO. La de cada variante manda
                  sobre ésta; sin la suya, la variante hereda la de aquí — igual
                  que la bandera. Ver `semi` en `chooseFollowupVariant`. */}
              <PastillaDeSemimodalidad
                valor={followup.semimodalidad}
                onCambiar={(siguiente) => {
                  onEdit(`channel_${channel}_own_followup_${index}_semimodalidad`);
                  updateFollowup(index, { semimodalidad: siguiente });
                }}
              />
              <PastillaDeTiendas
                valor={followup.tiendas}
                onCambiar={(siguiente) => {
                  onEdit(`channel_${channel}_own_followup_${index}_tiendas`);
                  updateFollowup(index, { tiendas: siguiente });
                }}
              />
              <CirculoDeEncendido
                encendido={followup.enabled !== false}
                queEs={`el seguimiento ${index + 1} de este canal`}
                onCambiar={() => {
                  onEdit(`channel_${channel}_own_followup_${index}_enabled`);
                  updateFollowup(index, {
                    enabled: followup.enabled === false,
                  });
                }}
              />
              <label
                title="Seleccionar este seguimiento para copiarlo a otro canal"
                className="flex cursor-pointer items-center gap-1 rounded border border-sky-300 bg-tarjeta px-2 py-1 text-xs font-semibold text-sky-800"
                onClick={(event) => event.stopPropagation()}
              >
                <input
                  type="checkbox"
                  checked={selectedIndexes.includes(index)}
                  onChange={() => toggleSelected(index)}
                  disabled={copyDisabled}
                  className="h-3.5 w-3.5 accent-sky-600"
                />
                Copiar
              </label>
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  moveFollowup(index, -1);
                }}
                disabled={index === 0}
                className="rounded border border-sky-200 bg-sky-50 px-2 py-1 text-xs font-bold text-sky-700 hover:bg-sky-100 disabled:opacity-30"
              >
                ↑
              </button>
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  moveFollowup(index, 1);
                }}
                disabled={index === followups.length - 1}
                className="rounded border border-sky-200 bg-sky-50 px-2 py-1 text-xs font-bold text-sky-700 hover:bg-sky-100 disabled:opacity-30"
              >
                ↓
              </button>
              <button
                type="button"
                draggable
                onClick={(e) => e.stopPropagation()}
                onDragStart={(e) => {
                  e.stopPropagation();
                  e.dataTransfer.effectAllowed = "move";
                  e.dataTransfer.setData(
                    "text/plain",
                    `channel-followup:${channel}:${index}`
                  );
                }}
                title="Mover cajón"
                aria-label="Mover cajón"
                className="cursor-grab rounded border border-sky-300 bg-tarjeta px-2 py-1 text-xs font-bold text-sky-700 active:cursor-grabbing"
              >
                ⋮⋮
              </button>
              {/* DUPLICAR, EN LA FILA CERRADA. El MISMO `duplicateFollowup` que
                  el botón de dentro: copia el seguimiento entero con sus cajones
                  y pregunta el nombre antes. */}
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  duplicateFollowup(index);
                }}
                title="Duplicar este seguimiento"
                aria-label="Duplicar este seguimiento"
                className="rounded border border-sky-200 bg-sky-50 px-2 py-1 text-xs font-bold text-sky-700 hover:bg-sky-100"
              >
                ⧉
              </button>
            </>
          }
          onDragOver={(e) => e.preventDefault()}
          onDrop={(e) => {
            e.preventDefault();
            const raw = e.dataTransfer.getData("text/plain");
            const [kind, dragChannel, rawIndex] = raw.split(":");
            if (kind !== "channel-followup" || dragChannel !== channel) return;
            const from = Number(rawIndex);
            if (!Number.isFinite(from) || from === index) return;
            onSnapshot();
            keepMovedCollapsibleOpen(`channel_${channel}_own_followup`, from, index, followups.length);
            onChange({ followups: moveItem(followups, from, index) });
          }}
          titleClassName={
            followup.enabled === false
              ? "border-neutral-500 bg-neutral-300 text-neutral-900"
              : undefined
          }
          inactivo={followup.enabled === false}
          bodyClassName={followup.enabled === false ? "bg-neutral-300" : undefined}
        >
          <div className="mb-3 space-y-2">
            <div className="flex flex-wrap items-center gap-2">
              <input
                value={followup.name}
                onChange={(e) => {
                  onEdit(`channel_${channel}_followup_${index}_name`);
                  updateFollowup(index, { name: e.target.value });
                }}
                className="min-w-48 flex-1 rounded-md border border-neutral-300 bg-tarjeta px-2 py-1 text-sm"
              />
              <button
                type="button"
                onClick={() => {
                  onEdit(`channel_${channel}_followup_${index}_enabled`);
                  updateFollowup(index, { enabled: followup.enabled === false });
                }}
                className={`rounded border px-2 py-1 text-xs font-semibold ${
                  followup.enabled === false
                    ? "border-neutral-300 bg-neutral-100 text-neutral-400"
                    : "border-emerald-300 bg-emerald-50 text-emerald-700"
                }`}
              >
                {followup.enabled === false ? "OFF" : "ON"}
              </button>
            </div>
            <div className="flex flex-wrap items-end gap-2">
            <label className="grid gap-1">
              <span className="text-[10px] font-semibold uppercase text-neutral-500">
                🕒 Delay (min)
              </span>
              <DraftNumberInput
                value={followup.delay_minutes_from_first_message}
                onValueChange={(delay_minutes_from_first_message) => {
                  onEdit(`channel_${channel}_followup_${index}_delay`);
                  updateFollowup(index, {
                    delay_minutes_from_first_message,
                  });
                }}
                title="Delay en minutos desde el primer mensaje"
                ariaLabel="Delay en minutos"
                className="rounded-md border border-neutral-300 bg-tarjeta px-2 py-1 text-sm"
              />
            </label>
            <label
              className="flex items-center gap-1.5 pb-1 text-[11px] text-neutral-600"
              title="Este seguimiento se envía a su hora aunque caiga en horario de silencio. Solo afecta a este seguimiento."
            >
              <input
                type="checkbox"
                checked={followup.ignore_quiet_hours === true}
                onChange={(e) => {
                  onEdit(`channel_${channel}_followup_${index}_ignore_quiet`);
                  updateFollowup(index, {
                    ignore_quiet_hours: e.target.checked,
                  });
                }}
                className="h-4 w-4"
              />
              Enviar aunque sea horario de silencio
            </label>
            <label
              className="flex items-center gap-1.5 pb-1 text-[11px] text-neutral-600"
              title="Este seguimiento cuenta sus minutos desde el mensaje aunque el cliente escriba pasada la hora límite. Solo afecta a este seguimiento."
            >
              <input
                type="checkbox"
                checked={followup.ignore_late_lead_defer === true}
                onChange={(e) => {
                  onEdit(`channel_${channel}_followup_${index}_ignore_late`);
                  updateFollowup(index, {
                    ignore_late_lead_defer: e.target.checked,
                  });
                }}
                className="h-4 w-4"
              />
              Enviar aunque escriba pasada la hora límite
            </label>
            {/* Los mismos dos de siempre, retirados por lo mismo: las flechas
                ↑ ↓ de la cabecera ya hacen esto. */}
            <button
              type="button"
              onClick={() => duplicateFollowup(index)}
              className="rounded border border-neutral-300 bg-tarjeta px-2 py-1 text-xs text-neutral-600"
            >
              Duplicar
            </button>
            <button
              type="button"
              onClick={() => removeFollowup(index)}
              className="rounded border border-red-200 bg-tarjeta px-2 py-1 text-xs text-red-600"
            >
              Quitar
            </button>
            </div>
          </div>
          {/* UNA SOLA LISTA DE CAJONES, COMO EN INTRO.
              Aquí había DOS pestañas: «Mensajes principales» —sin botones, sin
              poder renombrarla, duplicarla ni moverla— y «Variantes», que era
              una caja dentro de otra caja. El dueño lo pidió el 15 de septiembre
              de 2026: que todo sea una lista de cajones hermanos.
              El contenido del principal bajó a la cabeza de la lista al cargar
              —ver `bajarPrincipalALaLista`—, así que aquí ya no hay nada
              especial que pintar: todos son cajones y el que esté encendido
              entra al sorteo. */}
          <div className="space-y-3">
              {conSuIndice(followup.variants ?? []).map(
                ({ item: variant, index: variantIndex }) => (
                <Collapsible
                  // Sin el nombre en la llave: es la casilla «SEG1» donde el
                  // cursor se perdía en cada letra. Ver el cajón de arriba.
                  key={`channel-${channel}-followup-${index}-variant-${variantIndex}`}
                  // LA BANDERA YA NO VA PEGADA AL NOMBRE: la elige y la enseña su
                  // pastilla, en esta misma barra. Lo pidió el dueño el 02/10/2026.
                  title={`${variant.enabled === false ? "OFF - " : ""}${
                    variant.name || "Ponle un título al cajón"
                  }`}
                  tituloDeRelleno={!variant.name?.trim()}
                  titleKey={`channel_${channel}_followup_${index}_variant_${variantIndex}`}
                  titleClassName={bordeSinBandera(
                    leFaltaLaBandera({
                      paises: variant.paises,
                      routingEnabled: variant.pais_routing_enabled,
                      apagada:
                        followup.enabled === false || variant.enabled === false,
                    }),
                    followup.enabled === false || variant.enabled === false
                      ? "border-neutral-500 bg-neutral-300 text-neutral-900"
                      : undefined
                  )}
                  inactivo={followup.enabled === false || variant.enabled === false}
                  bodyClassName={
                    followup.enabled === false || variant.enabled === false
                      ? "bg-neutral-300"
                      : undefined
                  }
                  onDragOver={(e) => {
                    e.preventDefault();
                  }}
                  onDrop={(e) => {
                    e.preventDefault();
                    const crudo = e.dataTransfer.getData("text/plain");
                    const [clase, deQuien, desdeCrudo] = crudo.split(":");
                    if (clase !== "cajon-seg" || deQuien !== `${channel}-${index}`)
                      return;
                    const desde = Number(desdeCrudo);
                    if (!Number.isFinite(desde) || desde === variantIndex) return;
                    onSnapshot();
                    keepMovedCollapsibleOpen(
                      `channel_${channel}_followup_${index}_variant`,
                      desde,
                      variantIndex,
                      (followup.variants ?? []).length
                    );
                    updateFollowup(index, {
                      variants: moveItem(
                        followup.variants ?? [],
                        desde,
                        variantIndex
                      ),
                    });
                  }}
                  // LA MISMA BARRA QUE LOS CAJONES DE INTRO, y por lo mismo: un
                  // cajón es un cajón se mire donde se mire. Antes estos solo
                  // tenían el ON/OFF y la papelera metidos DENTRO, así que para
                  // borrar uno o cambiarlo de sitio había que abrirlo.
                  headerActions={
                    <>
                      {/* LA BANDERA DE LA VARIANTE, A LA IZQUIERDA DE LA SEMIMODALIDAD.
                          AQUÍ ES DONDE ÉL LAS MIRA. Con sus palabras, el 02/10/2026:
                          «dentro de Canales… SEGUIMIENTOS · WHATSAPP, donde se encuentra
                          el seguimiento 1, 2 y 3, que son los cajones que contienen las
                          variables… y DENTRO DE CADA UNO DE ELLOS están los seguimientos
                          que deben tener la bandera seleccionable».
                          Y es el sitio correcto también por dentro: en el canal, el
                          seguimiento no lleva bandera —el etiquetado vive en la variante,
                          igual que el de anuncios—. */}
                      <PastillaDePais
                        seleccionados={variant.paises ?? []}
                        onCambiar={(paises) => {
                          onEdit(
                            `channel_${channel}_followup_${index}_variant_${variantIndex}_paises`
                          );
                          updateVariant(index, variantIndex, { paises });
                        }}
                      />
                      <AvisoSinBandera
                        visible={leFaltaLaBandera({
                          paises: variant.paises,
                          routingEnabled: variant.pais_routing_enabled,
                          apagada:
                            followup.enabled === false || variant.enabled === false,
                        })}
                      />
                      {/* LA ETIQUETA DEL CAJÓN, que manda sobre la del
                          seguimiento entero. Sin la suya, hereda aquélla — igual
                          que la bandera. */}
                      <PastillaDeSemimodalidad
                        valor={variant.semimodalidad}
                        onCambiar={(siguiente) => {
                          onEdit(
                            `channel_${channel}_followup_${index}_variant_${variantIndex}_semimodalidad`
                          );
                          updateVariant(index, variantIndex, {
                            semimodalidad: siguiente,
                          });
                        }}
                      />
                      <PastillaDeTiendas
                        valor={variant.tiendas}
                        onCambiar={(siguiente) => {
                          onEdit(
                            `channel_${channel}_followup_${index}_variant_${variantIndex}_tiendas`
                          );
                          updateVariant(index, variantIndex, {
                            tiendas: siguiente,
                          });
                        }}
                      />
                      <CirculoDeEncendido
                        encendido={variant.enabled !== false}
                        queEs={`este cajón del ${followup.name || "seguimiento"}`}
                        onCambiar={() => {
                          onEdit(
                            `channel_${channel}_followup_${index}_variant_${variantIndex}_enabled`
                          );
                          updateVariant(index, variantIndex, {
                            enabled: variant.enabled === false,
                          });
                        }}
                      />
                      <button
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          if (variantIndex === 0) return;
                          onSnapshot();
                          keepMovedCollapsibleOpen(
                            `channel_${channel}_followup_${index}_variant`,
                            variantIndex,
                            variantIndex - 1,
                            (followup.variants ?? []).length
                          );
                          updateFollowup(index, {
                            variants: moveItem(
                              followup.variants ?? [],
                              variantIndex,
                              variantIndex - 1
                            ),
                          });
                        }}
                        disabled={variantIndex === 0}
                        title="Subir este cajón"
                        aria-label="Subir este cajón"
                        className="rounded border border-sky-200 bg-sky-50 px-2 py-1 text-xs font-bold text-sky-700 hover:bg-sky-100 disabled:opacity-30"
                      >
                        ↑
                      </button>
                      <button
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          const ultimas = (followup.variants ?? []).length - 1;
                          if (variantIndex >= ultimas) return;
                          onSnapshot();
                          keepMovedCollapsibleOpen(
                            `channel_${channel}_followup_${index}_variant`,
                            variantIndex,
                            variantIndex + 1,
                            (followup.variants ?? []).length
                          );
                          updateFollowup(index, {
                            variants: moveItem(
                              followup.variants ?? [],
                              variantIndex,
                              variantIndex + 1
                            ),
                          });
                        }}
                        disabled={
                          variantIndex === (followup.variants ?? []).length - 1
                        }
                        title="Bajar este cajón"
                        aria-label="Bajar este cajón"
                        className="rounded border border-sky-200 bg-sky-50 px-2 py-1 text-xs font-bold text-sky-700 hover:bg-sky-100 disabled:opacity-30"
                      >
                        ↓
                      </button>
                      <button
                        type="button"
                        draggable
                        onClick={(e) => e.stopPropagation()}
                        onDragStart={(e) => {
                          e.stopPropagation();
                          e.dataTransfer.effectAllowed = "move";
                          e.dataTransfer.setData(
                            "text/plain",
                            `cajon-seg:${channel}-${index}:${variantIndex}`
                          );
                        }}
                        title="Arrastrar para moverlo de sitio"
                        aria-label="Arrastrar para moverlo de sitio"
                        className="cursor-grab rounded border border-sky-300 bg-tarjeta px-2 py-1 text-xs font-bold text-sky-700 active:cursor-grabbing"
                      >
                        ⋮⋮
                      </button>
                      {/* DUPLICAR, EN LA FILA CERRADA. El MISMO
                          `duplicateVariant` que el botón de dentro. */}
                      <button
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          duplicateVariant(index, variantIndex);
                        }}
                        title="Duplicar este cajón"
                        aria-label="Duplicar este cajón"
                        className="rounded border border-sky-200 bg-sky-50 px-2 py-1 text-xs font-bold text-sky-700 hover:bg-sky-100"
                      >
                        ⧉
                      </button>
                      <button
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          removeVariant(index, variantIndex);
                        }}
                        title="Quitar este cajón"
                        aria-label="Quitar este cajón"
                        className="rounded border border-red-200 bg-tarjeta px-2 py-1 text-xs text-red-600 hover:bg-red-50"
                      >
                        🗑️
                      </button>
                    </>
                  }
                >
                  <div className="mb-3 flex flex-wrap items-center gap-2">
                    <input
                      value={variant.name ?? ""}
                      onChange={(e) => {
                        onEdit(
                          `channel_${channel}_followup_${index}_variant_${variantIndex}_name`
                        );
                        updateVariant(index, variantIndex, {
                          name: e.target.value,
                        });
                      }}
                      className="min-w-48 rounded-md border border-neutral-300 bg-tarjeta px-2 py-1 text-sm"
                    />
                    {/* EL ON/OFF Y LA PAPELERA SE FUERON A LA CABECERA, como en
                        los cajones de Intro: para apagar o borrar uno ya no hay
                        que abrirlo. Aquí se queda lo que solo tiene sentido con
                        el cajón abierto. */}
                    <button
                      type="button"
                      onClick={() => duplicateVariant(index, variantIndex)}
                      className="rounded border border-neutral-300 bg-tarjeta px-2 py-1 text-xs text-neutral-600"
                    >
                      ⧉ Duplicar cajón
                    </button>
                    {/* «CLONAR PRINCIPAL» SE VA CON EL PRINCIPAL.
                        Servía para copiar aquí el texto de aquella pestaña
                        especial. Ya no existe: el principal es el primer cajón
                        de esta misma lista, así que copiarlo es duplicarlo. */}
                    {(followup.variants ?? []).map((sourceVariant, sourceIndex) =>
                      sourceIndex === variantIndex ? null : (
                        <button
                          key={`clonar-variante-${sourceIndex}`}
                          type="button"
                          onClick={() =>
                            cloneVariantIntoVariant(index, sourceIndex, variantIndex)
                          }
                          className="rounded border border-neutral-300 bg-tarjeta px-2 py-1 text-xs text-neutral-600"
                          title={`Traer aquí el texto de «${sourceVariant.name || `cajón ${sourceIndex + 1}`}»`}
                        >
                          Traer texto de {sourceVariant.name || `cajón ${sourceIndex + 1}`}
                        </button>
                      )
                    )}
                  </div>
                  <FilaDeEtiquetas>
                  <BanderaTagPicker
                    seleccionados={variant.paises ?? []}
                    routingEnabled={variant.pais_routing_enabled}
                    onRoutingEnabledChange={(pais_routing_enabled) => {
                      onEdit(`channel_${channel}_followup_${index}_variant_${variantIndex}_pais_routing`);
                      updateVariant(index, variantIndex, { pais_routing_enabled });
                    }}
                    onChange={(paises) => {
                      onEdit(`channel_${channel}_followup_${index}_variant_${variantIndex}_paises`);
                      updateVariant(index, variantIndex, { paises });
                    }}
                  />
                  <AdTagPicker
                    registry={registry}
                    selectedKeys={variant.ad_keys ?? []}
                    routingEnabled={variant.ad_routing_enabled}
                    onRoutingEnabledChange={(ad_routing_enabled) => {
                      onEdit(`channel_${channel}_followup_${index}_variant_${variantIndex}_routing`);
                      updateVariant(index, variantIndex, { ad_routing_enabled });
                    }}
                    onChange={(ad_keys) => {
                      onEdit(`channel_${channel}_followup_${index}_variant_${variantIndex}_ads`);
                      updateVariant(index, variantIndex, { ad_keys });
                    }}
                    onRegistryChange={onRegistryChange}
                  />
                  </FilaDeEtiquetas>
                  <StepEditorPreviewPair
                    steps={variant.steps}
                    onChange={(steps) =>
                      updateVariant(index, variantIndex, { steps })
                    }
                    onSnapshot={onSnapshot}
                    onEdit={onEdit}
                    idPrefix={`channel_${channel}_followup_${index}_variant_${variantIndex}`}
                    priceSoles={price}
                    comboPrice={comboPrice}
                    basicoPrice={basicoPrice}
                    stagePriceSoles={previewStagePrices(index).price}
                    stageComboPrice={previewStagePrices(index).combo}
                    stageBasicoPrice={previewStagePrices(index).basico}
                    previewContext={previewContext}
                    className="lg:grid-cols-1 xl:grid-cols-[minmax(0,1fr)_minmax(220px,280px)]"
                  />
                </Collapsible>
              ))}
              <button
                type="button"
                onClick={() => addVariant(index)}
                className="w-full rounded-md border-2 border-dashed border-neutral-300 py-2 text-sm text-neutral-500 hover:border-sky-400 hover:text-sky-600"
              >
                Agregar cajón
              </button>
          </div>
        </Collapsible>
      ))}
      <button
        type="button"
        onClick={addFollowup}
        className="w-full rounded-md border-2 border-dashed border-neutral-300 py-2 text-sm text-neutral-500 hover:border-emerald-400 hover:text-emerald-600"
      >
        Agregar seguimiento
      </button>
    </div>
    </TonoDeLaSeccion.Provider>
  );
}

/** ¿Este paso tiene algo escrito, o es una caja vacía? */
function pasoTieneAlgo(paso: EditorStep): boolean {
  const textos = [
    ...(paso.texts ?? []),
    (paso as { caption?: string }).caption ?? "",
    (paso as { drive_url?: string }).drive_url ?? "",
  ];
  return textos.some((texto) => (texto ?? "").trim().length > 0);
}

function deliveryGroupsForChannelContent(
  content: ChannelContentEditor,
  // Con qué entregas DEBERÍA contar esta modalidad. Se pasa solo desde la
  // pantalla de Canales, que es la única que las muestra para llenarlas.
  esperadas?: ChannelDeliveryGroupEditor[]
): ChannelDeliveryGroupEditor[] {
  let groups = content.delivery_groups ?? [];

  // COMPLETAR LAS QUE FALTEN.
  //
  // Los grupos se crean una sola vez, al estrenar el canal. Una modalidad que
  // nace después —o que pasa a tener más productos— se queda con los grupos
  // viejos para siempre: por eso "Doble Oferta + Upsell" mostraba UNA entrega
  // teniendo tres productos, y no había forma de que aparecieran las otras dos.
  //
  // Se añaden vacías, nunca se pisa lo que ya estaba escrito. Si el canal ya
  // tenía su entrega, sigue igual; solo aparecen al lado las que faltaban.
  if (esperadas?.length) {
    const faltan = esperadas.filter(
      (esperada) => !groups.some((g) => g.key === esperada.key)
    );
    if (faltan.length) groups = [...groups, ...faltan];

    // EL TÍTULO LO MANDA LA MODALIDAD, NO LO QUE QUEDÓ GUARDADO.
    //
    // El nombre se guardaba junto con la entrega, así que un título viejo se
    // quedaba para siempre — incluso uno equivocado. Pasó: los cajones decían
    // "1 · BASE: {{PRODUCTO}}" y "2 · FULL: {{PRODUCTO2}}" con los comodines
    // cruzados, y quien llena estas cajas se guía por el título. Se llenó el
    // básico con el enlace del full, y el bot entregó lo que estaba escrito.
    //
    // El título describe QUÉ RANURA es, no es un texto del operador: por eso
    // se reescribe siempre desde la modalidad. Los pasos no se tocan.
    const nombreEsperado = new Map(esperadas.map((e) => [e.key, e.name]));
    groups = groups.map((g) => {
      const nombre = nombreEsperado.get(g.key);
      return nombre && nombre !== g.name ? { ...g, name: nombre } : g;
    });

    // Y QUITAR LA GENÉRICA QUE SOBRA.
    //
    // Todo canal nace con una entrega llamada "Entrega pago aprobado" (clave
    // "central"), que es la única que necesita la modalidad Lineal. En una
    // modalidad con entregas propias esa caja se sumaba a las suyas y salían
    // CUATRO para tres productos.
    //
    // Si tenía texto NO se tira: se MUEVE a la primera entrega de la modalidad
    // cuando esa está vacía. Así lo que se escribió sigue ahí, en la caja que
    // le corresponde, en vez de quedar en una que ya no significa nada.
    const esperada = new Set(esperadas.map((e) => e.key));
    const sobra = groups.find(
      (g) => !esperada.has(g.key) && (g.steps ?? []).some(pasoTieneAlgo)
    );
    if (sobra) {
      const primera = groups.find((g) => g.key === esperadas[0].key);
      if (primera && !(primera.steps ?? []).some(pasoTieneAlgo)) {
        groups = groups.map((g) =>
          g.key === primera.key ? { ...g, steps: sobra.steps } : g
        );
      }
    }
    groups = groups.filter((g) => esperada.has(g.key));
  }

  if (groups.length > 0) {
    // Básico es la entrega base y debe quedar primero en todos los canales.
    // Las claves que usa el motor para elegir la entrega correcta no cambian.
    const rank = (group: ChannelDeliveryGroupEditor) =>
      group.key.endsWith("_basico") ? 0 : group.key.endsWith("_combo") ? 1 : 2;
    return [...groups].sort((left, right) => rank(left) - rank(right));
  }
  return [
    {
      key: "central",
      name: "Entrega pago aprobado",
      enabled: true,
      steps: content.delivery?.length ? content.delivery : [emptyStep()],
    },
  ];
}

function whatsappDeliveryGroupsForMode(
  cfg: FullConfig,
  mode: Modo
): ChannelDeliveryGroupEditor[] {
  return deliveryGroupsForChannelContent(
    channelContentForMode(cfg, "whatsapp", mode)
  );
}

function preferredEmailDeliveryGroupKey(
  mode: Modo,
  target: EmailTarget
): string {
  // El correo del segundo producto se extrae de SU entrega, la misma que el bot
  // manda por WhatsApp. Cayendo a "central" traía la del primero: el enlace que
  // el cliente ya tiene.
  if (target === "upsell") return "upsell";
  if (mode === "order_bump") {
    return target === "vip" ? "order_bump_combo" : "order_bump_basico";
  }
  if (mode === "doble_oferta_dos") {
    return target === "vip"
      ? "doble_oferta_dos_combo"
      : "doble_oferta_dos_basico";
  }
  if (mode === "bioferta") {
    return target === "vip" ? "bioferta_pack" : "bioferta_product_a";
  }
  return "central";
}

function firstDeliveryBubbleText(
  group: ChannelDeliveryGroupEditor | undefined
): string {
  return allDeliveryBubbleTexts(group)[0] ?? "";
}

function allDeliveryBubbleTexts(
  group: ChannelDeliveryGroupEditor | undefined
): string[] {
  return (group?.steps ?? [])
    .filter((step) => step.enabled !== false)
    .map((step) => step.texts.find((text) => text.trim().length > 0) ?? "")
    .filter((text) => text.trim().length > 0);
}

function WhatsAppDeliveryExtractControl({
  groups,
  selectedKey,
  onSelectedKeyChange,
  onExtractFirst,
  onExtractAll,
}: {
  groups: ChannelDeliveryGroupEditor[];
  selectedKey: string;
  onSelectedKeyChange: (key: string) => void;
  onExtractFirst: () => void;
  onExtractAll: () => void;
}) {
  const selectedGroup = groups.find((group) => group.key === selectedKey);
  const hasText = !!firstDeliveryBubbleText(selectedGroup).trim();
  return (
    <div className="mb-2 rounded-md border border-sky-200 bg-sky-50 px-3 py-2">
      <p className="text-xs font-medium text-sky-950">
        Copiar desde la entrega de WhatsApp
      </p>
      <p className="mt-1 text-[11px] leading-snug text-sky-800">
        Copia solo desde la entrega seleccionada. Puedes traer la primera burbuja
        o todas sus burbujas activas, y deshacerlo antes de guardar.
      </p>
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <select
          value={selectedKey}
          onChange={(event) => onSelectedKeyChange(event.target.value)}
          disabled={groups.length === 0}
          className="min-w-0 flex-1 rounded border border-sky-300 bg-tarjeta px-2 py-1.5 text-xs text-neutral-800 disabled:opacity-50"
        >
          {groups.length === 0 ? (
            <option value="">No hay entregas de WhatsApp configuradas</option>
          ) : (
            groups.map((group) => (
              <option key={group.key} value={group.key}>
                {group.name || "Entrega sin nombre"}
              </option>
            ))
          )}
        </select>
        <button
          type="button"
          onClick={onExtractFirst}
          disabled={!hasText}
          title={
            hasText
              ? "Reemplazar el cuerpo con la primera burbuja de esta entrega"
              : "La primera burbuja de esta entrega no tiene texto"
          }
          className="rounded border border-sky-400 bg-tarjeta px-3 py-1.5 text-xs font-semibold text-sky-800 hover:bg-sky-100 disabled:cursor-not-allowed disabled:opacity-50"
        >
          Extraer primera burbuja
        </button>
        <button
          type="button"
          onClick={onExtractAll}
          disabled={!hasText}
          title={
            hasText
              ? "Reemplazar el cuerpo con todas las burbujas activas de esta entrega"
              : "Esta entrega no tiene texto para copiar"
          }
          className="rounded border border-sky-400 bg-sky-700 px-3 py-1.5 text-xs font-semibold text-white hover:bg-sky-800 disabled:cursor-not-allowed disabled:opacity-50"
        >
          Extraer todas las burbujas
        </button>
      </div>
      {!hasText && groups.length > 0 && (
        <p className="mt-1 text-[11px] text-amber-800">
          La primera burbuja de esta entrega no contiene texto para copiar.
        </p>
      )}
    </div>
  );
}

/**
 * El nombre del producto que le toca a una ranura de entrega.
 *
 * La clave interna es la que manda de verdad —el motor entrega por clave, no
 * por título— así que se traduce desde ella y no desde lo que diga el rótulo.
 * Devuelve "" cuando la ranura no corresponde a un producto concreto.
 */
function productoDeLaEntrega(key: string, cfg: FullConfig): string {
  const dosNiveles =
    activeModality(cfg) === "order_bump" ? cfg.order_bump : cfg.doble_oferta_dos;
  if (key === "doble_oferta_dos_basico" || key === "order_bump_basico") {
    return dosNiveles.basico?.name?.trim() || "";
  }
  if (key === "doble_oferta_dos_combo" || key === "order_bump_combo") {
    return dosNiveles.combo?.name?.trim() || "";
  }
  if (key === "upsell") return cfg.upsell?.name?.trim() || "";
  return "";
}

function ChannelDeliveryEditor({
  channel,
  mode,
  content,
  onChange,
  price,
  comboPrice,
  basicoPrice,
  previewContext,
  onSnapshot,
  onEdit,
  copyTargets,
  onCopySelected,
  copyDisabled = false,
  // Hace falta para saber qué entregas DEBERÍA tener esta modalidad, y así
  // completar las que falten cuando el canal se creó con menos productos.
  cfg,
}: {
  channel: ChannelKey;
  mode: Modo;
  content: ChannelContentEditor;
  onChange: (patch: Partial<ChannelContentEditor>) => void;
  price: number;
  comboPrice: number;
  basicoPrice: number;
  previewContext: PreviewContext;
  onSnapshot: () => void;
  onEdit: (key: string) => void;
  copyTargets: ChannelKey[];
  onCopySelected: (indexes: number[], target: ChannelKey) => void;
  copyDisabled?: boolean;
  cfg: FullConfig;
}) {
  // Se le pasan las entregas que la modalidad DEBERÍA tener, para que aparezcan
  // aunque este canal se haya creado cuando la modalidad tenía menos productos.
  const groups = deliveryGroupsForChannelContent(
    content,
    channelDeliveryGroupsFromBase(cfg, mode).map((grupo) => ({
      ...grupo,
      steps: [],
    }))
  );
  const hasFixedDeliveries = mode !== "lineal";
  // LA DEL UPSELL ES FIJA TAMBIÉN EN LINEAL.
  //
  // «Fija» quiere decir que no se puede borrar ni mover: son las entregas que
  // el motor busca POR SU CLAVE. Lineal quedaba fuera porque solo tenía la
  // central, y ahora también tiene la del segundo producto. Sin esto se podía
  // borrar — y la caja volvía sola VACÍA en el siguiente pintado, porque se
  // repone de la modalidad. Se perdía lo escrito sin que nada avisara.
  const isFixedDeliveryGroup = (key: string) =>
    key === "upsell" ||
    (hasFixedDeliveries &&
      (key.startsWith("order_bump_") ||
        key.startsWith("doble_oferta_dos_") ||
        key.startsWith("bioferta_")));
  const updateGroup = (
    index: number,
    patch: Partial<ChannelDeliveryGroupEditor>
  ) => {
    const nextGroups = groups.map((group, i) =>
      i === index ? { ...group, ...patch } : group
    );
    onChange({
      delivery_groups: nextGroups,
      delivery: nextGroups[0]?.steps ?? content.delivery,
    });
  };
  const addGroup = () => {
    onSnapshot();
    onChange({
      delivery_groups: [
        ...groups,
        {
          key: `extra_${groups.length + 1}`,
          name: `Entrega extra ${groups.length + 1}`,
          enabled: true,
          steps: [emptyStep()],
        },
      ],
    });
  };
  const duplicateGroup = (index: number) => {
    onSnapshot();
    const copy = cloneJson(groups[index]);
    // La copia estrena clave propia, asi que su cajon se puede abrir de forma
    // exacta: se deja abierto para caer dentro de el al duplicar.
    const claveNueva = `${copy.key}_copy_${Date.now()}`;
    try {
      localStorage.setItem(
        `wf:collapsible:channel_${channel}_${mode}_delivery_${claveNueva}_${index + 1}`,
        "1"
      );
    } catch {}
    onChange({
      delivery_groups: [
        ...groups.slice(0, index + 1),
        {
          ...copy,
          key: claveNueva,
          name: `${copy.name} copia`,
        },
        ...groups.slice(index + 1),
      ],
    });
  };
  const moveGroup = (index: number, dir: -1 | 1) => {
    const target = index + dir;
    if (target < 0 || target >= groups.length) return;
    if (
      isFixedDeliveryGroup(groups[index]?.key ?? "") ||
      isFixedDeliveryGroup(groups[target]?.key ?? "")
    ) {
      return;
    }
    onSnapshot();
    keepMovedCollapsibleOpenExact(
      `channel_${channel}_${mode}_delivery_${groups[index]?.key}_${index}`,
      `channel_${channel}_${mode}_delivery_${groups[index]?.key}_${target}`
    );
    const nextGroups = moveItem(groups, index, target);
    onChange({
      delivery_groups: nextGroups,
      delivery: nextGroups[0]?.steps ?? content.delivery,
    });
  };
  const removeGroup = (index: number) => {
    if (!confirm("Quitar este cajon de entrega?")) return;
    onSnapshot();
    const nextGroups = groups.filter((_, i) => i !== index);
    onChange({
      delivery_groups: nextGroups,
      delivery: nextGroups[0]?.steps ?? [emptyStep()],
    });
  };
  // CADA ENTREGA CON EL DIBUJO DE LO QUE ENTREGA.
  //
  // Los cajones de aquí heredaban el dibujo de la sección, así que la entrega
  // del básico, la del full y la del upsell salían las tres con la bolsa: tres
  // filas idénticas en la misma ventana, y hay que leerlas para saber cuál es
  // cuál. Son las tres cosas que se venden, y ya tienen su dibujo en el resto
  // del editor: el paquete, los libros y el carrito.
  //
  // Sale de la CLAVE del cajón, no de su nombre: el nombre lo escribe el
  // operador y puede llamarse como quiera. La clave es la que lee el motor.
  // Solo los tres que se pidieron. Las demás entregas —la central de Lineal,
  // las de la Doble Oferta, el pack— se quedan con la bolsa de la sección: no
  // son ni básico ni full ni upsell, y darles un dibujo prestado diría algo que
  // no es.
  const dibujoDeLaEntrega = (key: string) => {
    if (key === "upsell") return "🛒";
    if (key.endsWith("_combo")) return "📦";
    if (key.endsWith("_basico")) return "📚";
    return "🛍️";
  };
  // El nombre del cajón es solo una etiqueta del editor: resolver aquí los
  // comodines no altera lo guardado ni la entrega que recibe el cliente.
  const displayGroupName = (group: ChannelDeliveryGroupEditor, index: number) => {
    const rawName = group.name || `Entrega ${index + 1}`;
    return applyPreviewPrices(
      rawName,
      price,
      comboPrice,
      basicoPrice,
      previewContext
    );
  };

  return (
    <div className="space-y-3">
      <p className="text-xs text-neutral-500">
        Estos cajones separan la entrega segun la modalidad activa:{" "}
        {MODALIDAD_LABEL[mode]}. Sirven para no mezclar enlaces o materiales de
        productos distintos.
      </p>
      {hasFixedDeliveries && (
        <p className="rounded-md border border-amber-200 bg-amber-50 px-3 py-2 text-xs font-medium text-amber-800">
          En esta modalidad las entregas son fijas y se crean al usar Clonar desde
          Base. No necesitas agregarlas manualmente.
        </p>
      )}
      <ChannelCopySelector
        label="cajones de entrega"
        items={groups}
        targets={copyTargets}
        onCopy={onCopySelected}
        onDelete={(indexes) => {
          const removable = indexes.filter((index) => !isFixedDeliveryGroup(groups[index]?.key ?? ""));
          if (removable.length === 0) {
            alert("Las entregas fijas de esta modalidad no se pueden eliminar.");
            return;
          }
          const nextGroups = groups.filter((_, index) => !removable.includes(index));
          onSnapshot();
          onChange({ delivery_groups: nextGroups, delivery: nextGroups[0]?.steps ?? [emptyStep()] });
        }}
        disabled={copyDisabled}
      />
      {conSuIndice(groups).map(({ item: group, index }) => (
        <Collapsible
          key={`${group.key}_${index}`}
          title={`${dibujoDeLaEntrega(group.key)} ${
            group.enabled === false ? "OFF - " : ""
          }${displayGroupName(group, index)}`}
          titleKey={`channel_${channel}_${mode}_delivery_${group.key}_${index}`}
          headerActions={
            !isFixedDeliveryGroup(group.key) ? (
              <>
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    moveGroup(index, -1);
                  }}
                  disabled={
                    index === 0 ||
                    isFixedDeliveryGroup(groups[index - 1]?.key ?? "")
                  }
                  className="rounded border border-sky-200 bg-sky-50 px-2 py-1 text-xs font-bold text-sky-700 hover:bg-sky-100 disabled:opacity-30"
                >
                  ↑
                </button>
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    moveGroup(index, 1);
                  }}
                  disabled={
                    index === groups.length - 1 ||
                    isFixedDeliveryGroup(groups[index + 1]?.key ?? "")
                  }
                  className="rounded border border-sky-200 bg-sky-50 px-2 py-1 text-xs font-bold text-sky-700 hover:bg-sky-100 disabled:opacity-30"
                >
                  ↓
                </button>
                <button
                  type="button"
                  draggable
                  onClick={(e) => e.stopPropagation()}
                  onDragStart={(e) => {
                    e.stopPropagation();
                    e.dataTransfer.effectAllowed = "move";
                    e.dataTransfer.setData(
                      "text/plain",
                      `channel-delivery:${channel}:${mode}:${index}`
                    );
                  }}
                  title="Mover cajón"
                  className="cursor-grab rounded border border-sky-300 bg-tarjeta px-2 py-1 text-xs font-bold text-sky-700 active:cursor-grabbing"
                >
                  ⋮⋮ Mover
                </button>
              </>
            ) : undefined
          }
          onDragOver={(e) => {
            if (!isFixedDeliveryGroup(group.key)) e.preventDefault();
          }}
          onDrop={(e) => {
            if (isFixedDeliveryGroup(group.key)) return;
            e.preventDefault();
            const raw = e.dataTransfer.getData("text/plain");
            const [kind, dragChannel, dragMode, rawIndex] = raw.split(":");
            if (
              kind !== "channel-delivery" ||
              dragChannel !== channel ||
              dragMode !== mode
            ) {
              return;
            }
            const from = Number(rawIndex);
            if (
              !Number.isFinite(from) ||
              from === index ||
              isFixedDeliveryGroup(groups[from]?.key ?? "")
            ) {
              return;
            }
            onSnapshot();
            keepMovedCollapsibleOpenExact(
              `channel_${channel}_${mode}_delivery_${groups[from]?.key}_${from}`,
              `channel_${channel}_${mode}_delivery_${groups[from]?.key}_${index}`
            );
            const nextGroups = moveItem(groups, from, index);
            onChange({
              delivery_groups: nextGroups,
              delivery: nextGroups[0]?.steps ?? content.delivery,
            });
          }}
          titleClassName={
            group.enabled === false
              ? "border-neutral-500 bg-neutral-300 text-neutral-900"
              : undefined
          }
          inactivo={group.enabled === false}
          bodyClassName={group.enabled === false ? "bg-neutral-300" : undefined}
          defaultOpen={index === 0}
        >
          <div className="mb-3 flex flex-wrap items-center gap-2">
            <input
              value={group.name}
              onChange={(e) => {
                onEdit(`channel_${channel}_${mode}_delivery_${index}_name`);
                updateGroup(index, { name: e.target.value });
              }}
              className="min-w-48 rounded-md border border-neutral-300 bg-tarjeta px-2 py-1 text-sm"
            />
            <button
              type="button"
              onClick={() => {
                onEdit(`channel_${channel}_${mode}_delivery_${index}_enabled`);
                updateGroup(index, { enabled: group.enabled === false });
              }}
              className={`rounded border px-2 py-1 text-xs font-semibold ${
                group.enabled === false
                  ? "border-neutral-300 bg-neutral-100 text-neutral-400"
                  : "border-emerald-300 bg-emerald-50 text-emerald-700"
              }`}
            >
              {group.enabled === false ? "OFF" : "ON"}
            </button>
            {!isFixedDeliveryGroup(group.key) && (
              <>
                {/* Y los mismos dos, retirados igual: duplicaban las flechas
                    ↑ ↓ de la cabecera. */}
                <button
                  type="button"
                  onClick={() => duplicateGroup(index)}
                  className="rounded border border-neutral-300 bg-tarjeta px-2 py-1 text-xs text-neutral-600"
                >
                  Duplicar cajon
                </button>
                <button
                  type="button"
                  onClick={() => removeGroup(index)}
                  className="rounded border border-red-200 bg-tarjeta px-2 py-1 text-xs text-red-600"
                >
                  Quitar
                </button>
              </>
            )}
          </div>
          {/* QUÉ PRODUCTO ES ESTA RANURA, con el nombre que tiene puesto.
              El título es fijo a propósito; el nombre va aquí dentro, como
              comprobación antes de pegar un enlace. Es la vuelta al error de
              llenar el básico con el material del full. */}
          {productoDeLaEntrega(group.key, cfg) && (
            <p className="mb-2 rounded-md border border-sky-200 bg-sky-50 px-3 py-2 text-xs text-sky-900">
              Aquí va lo que recibe quien compra{" "}
              <strong>{productoDeLaEntrega(group.key, cfg)}</strong>.
            </p>
          )}
          <StepEditorPreviewPair
            steps={group.steps}
            onChange={(steps) => updateGroup(index, { steps })}
            onSnapshot={onSnapshot}
            onEdit={onEdit}
            idPrefix={`channel_${channel}_${mode}_delivery_${index}`}
            priceSoles={price}
            comboPrice={comboPrice}
            basicoPrice={basicoPrice}
            previewContext={previewContext}
            className="lg:grid-cols-1 xl:grid-cols-[minmax(0,1fr)_minmax(220px,280px)]"
          />
        </Collapsible>
      ))}
      {!hasFixedDeliveries && (
        <button
          type="button"
          onClick={addGroup}
          className="w-full rounded-md border-2 border-dashed border-neutral-300 py-2 text-sm text-neutral-500 hover:border-emerald-400 hover:text-emerald-600"
        >
          Agregar cajon de entrega
        </button>
      )}
    </div>
  );
}

function ChannelPostSaleEditorPanel({
  channel,
  value,
  onChange,
  onEdit,
}: {
  channel: ChannelKey;
  value?: ChannelPostSaleEditor;
  onChange: (value: ChannelPostSaleEditor) => void;
  onEdit: (key: string) => void;
}) {
  const postSale: ChannelPostSaleEditor = value ?? {
    whatsappPreference: "",
    deliveryUsage: "",
    lifetimeAccess: "",
    farewells: "",
  };
  const update = (key: keyof ChannelPostSaleEditor, nextValue: string) => {
    onEdit(`channel_${channel}_post_sale_${key}`);
    onChange({ ...postSale, [key]: nextValue });
  };
  return (
    <div className="space-y-4">
      <p className="text-xs text-neutral-500">
        Respuestas postventa propias de este canal. No reemplazan las entregas
        de producto; sirven para dudas despues de la compra.
      </p>
      <label className="block">
        <span className="mb-1 block text-xs font-medium text-neutral-700">
          Si no quiere dar correo
        </span>
        <EditorEmojiTextarea
          rows={3}
          value={postSale.whatsappPreference}
          onChange={(value) => update("whatsappPreference", value)}
          className="w-full rounded border border-neutral-300 px-3 py-2 text-sm"
        />
      </label>
      <label className="block">
        <span className="mb-1 block text-xs font-medium text-neutral-700">
          Si pregunta como descargar o usar el material
        </span>
        <EditorEmojiTextarea
          rows={3}
          value={postSale.deliveryUsage}
          onChange={(value) => update("deliveryUsage", value)}
          className="w-full rounded border border-neutral-300 px-3 py-2 text-sm"
        />
      </label>
      <label className="block">
        <span className="mb-1 block text-xs font-medium text-neutral-700">
          Si pregunta si el acceso es de por vida
        </span>
        <EditorEmojiTextarea
          rows={2}
          value={postSale.lifetimeAccess}
          onChange={(value) => update("lifetimeAccess", value)}
          className="w-full rounded border border-neutral-300 px-3 py-2 text-sm"
        />
      </label>
      <label className="block">
        <span className="mb-1 block text-xs font-medium text-neutral-700">
          Despedidas postventa
        </span>
        <EditorEmojiTextarea
          rows={3}
          value={postSale.farewells}
          onChange={(value) => update("farewells", value)}
          className="w-full rounded border border-neutral-300 px-3 py-2 text-sm"
        />
      </label>
    </div>
  );
}

